# ==============================================================================
# Project Earth LAN - All in One Manager, Downloader & Game Finder
# Features: Admin-Elevated | Full White Text / Dark GUI | Progress Bar Dialogs
# ==============================================================================

# 0. OPTIONS-PARAMETER (getrennte Fenster): -Option <Nummer> startet nur diese Option
$Option = ''
for ($ai = 0; $ai -lt ($args.Count - 1); $ai++) {
    if ([string]$args[$ai] -eq '-Option') { $Option = [string]$args[$ai + 1] }
}
# -Autostart: vom Windows-Autostart (geplante Aufgabe, Autostart-Button) gestartet -> Control
# Center minimiert öffnen.
$script:PelAutostartMode = $false
foreach ($a0 in $args) { if ([string]$a0 -eq '-Autostart') { $script:PelAutostartMode = $true } }
$script:IsCompiledExe = -not ($PSCommandPath -and $PSCommandPath -like '*.ps1')
if ($script:IsCompiledExe) {
    # Mit PS2EXE (oder aehnlichem) zu einer .exe kompiliert: $PSCommandPath ist dann leer
    # bzw. zeigt nicht mehr auf eine .ps1-Datei. Fuer alle Stellen, die sich selbst neu
    # starten (Admin-Erhoehung, einzelne Options-Fenster, Autostart), muss dann die
    # eigene .exe direkt erneut gestartet werden statt "powershell.exe -File ...".
    try { $script:SelfPath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { $script:SelfPath = $null }
} else {
    $script:SelfPath = $PSCommandPath
}

# Versionsnummer dieses Builds. Format: YYYY.MM.DD, damit ein einfacher Textvergleich
# auch die zeitliche Reihenfolge richtig erkennt. Es gibt KEIN automatisches Update mehr:
# der Manager prueft beim Start nur (lesend) auf GitHub, ob dort eine neuere Version
# veroeffentlicht wurde, und zeigt dann im Live-Status einen Button, der die GitHub-Seite
# im Browser oeffnet - heruntergeladen und ersetzt wird ausschliesslich von Hand.
$script:PelVersion = "2026.10.01"
$script:PelGitHubUrl = "https://github.com/Firehawk215/Project-Earth-Lan"
$script:PelGitHubApiLatest = "https://api.github.com/repos/Firehawk215/Project-Earth-Lan/releases/latest"
$script:PelGitHubApiTags = "https://api.github.com/repos/Firehawk215/Project-Earth-Lan/tags"
$script:PelGitHubApiContents = "https://api.github.com/repos/Firehawk215/Project-Earth-Lan/contents/"
$script:PelGitHubRawVersion = "https://raw.githubusercontent.com/Firehawk215/Project-Earth-Lan/main/version.txt"

# ------------------------------------------------------------------------------
# SICHERHEIT: NETZWERK-SECRET (symmetrisch)
# ------------------------------------------------------------------------------
# $script:PelNetworkSecret: gemeinsames Secret (siehe network_code_tool.ps1), dient als
# HMAC-Schluessel, um Status-/Planer-/Postfach-Broadcasts als "echter" Project Earth LAN
# Manager zu kennzeichnen - Pakete ohne passende Signatur werden von allen Nodes ignoriert
# (Schutz vor Spoofing/Fremd-Software auf demselben Netz). Weil der Wert fest im Code
# steht, hat ihn automatisch jeder, der die offizielle .exe startet - ganz ohne manuelle
# Eingabe. Aendern: neuen Code mit network_code_tool.ps1 erzeugen, hier eintragen, neu
# kompilieren und die neue .exe ueber GitHub veroeffentlichen.
$script:PelNetworkSecret = "nPKRhk8X2AUkfTN8"

# HMAC-SHA256 ueber Text mit $script:PelNetworkSecret als Schluessel - fuer die Signatur
# von Beacon-/Status-Broadcasts (siehe oben, Punkt 2). Gibt Base64 zurueck.
function Get-PelHmacBase64 {
    param([string]$Text)
    try {
        $keyBytes = [System.Text.Encoding]::UTF8.GetBytes($script:PelNetworkSecret)
        $hmac = New-Object System.Security.Cryptography.HMACSHA256(,$keyBytes)
        try {
            $hash = $hmac.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Text))
            return [Convert]::ToBase64String($hash)
        } finally { $hmac.Dispose() }
    } catch { return '' }
}

# Prueft eine per Get-PelHmacBase64 erzeugte Signatur.
function Test-PelHmac {
    param([string]$Text, [string]$Signature)
    if ([string]::IsNullOrEmpty($Signature)) { return $false }
    $expected = Get-PelHmacBase64 -Text $Text
    if ([string]::IsNullOrEmpty($expected)) { return $false }
    return ($expected -eq $Signature)
}

# Live-Status-Verbund (Control Center <-> Control Center, Port 9928): jeder offene
# Manager meldet seinen eigenen Live-Status (Name, IP, P2P-Status, Freunde online,
# Version) per UDP-Broadcast und hört gleichzeitig auf die Meldungen aller anderen -
# so kennt jeder Manager im Netzwerk automatisch den Status aller anderen, ohne dass
# jemand aktiv nachfragen muss.
$script:PelStatusPort = 9928

# 1. ADMIN-RECHTE & KONSOLE EINRICHTEN
$Host.UI.RawUI.ForegroundColor = "White"
Clear-Host

$currentPrincipal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $currentPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    $optArg = ""
    if ($Option) { $optArg = " -Option $Option" }
    if ($script:PelAutostartMode) { $optArg += " -Autostart" }
    if (-not $script:IsCompiledExe -and $PSCommandPath) {
        Start-Process powershell.exe "-NoProfile -ExecutionPolicy Bypass -STA -WindowStyle Hidden -File `"$PSCommandPath`"$optArg" -Verb RunAs
        exit
    } elseif ($script:IsCompiledExe -and $script:SelfPath) {
        # Als kompilierte .exe gestartet: die eigene .exe direkt mit erhoehten Rechten
        # neu starten (kein "powershell.exe -File" noetig, sie enthaelt das Skript bereits).
        try {
            Start-Process -FilePath $script:SelfPath -ArgumentList $optArg.Trim() -Verb RunAs
            exit
        } catch {
            Write-Warning "[DEBUG ERROR] Bitte starte den Project Earth LAN Manager als Administrator."
            return
        }
    } else {
        Write-Warning "[DEBUG ERROR] Bitte starte deine PowerShell-Konsole als Administrator."
        return
    }
}

# WinForms & System-Baugruppen laden
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Web

# ------------------------------------------------------------------------------
# SPRACHE / LANGUAGE: Deutsch oder Englisch (Button oben links im Control Center)
# ------------------------------------------------------------------------------
# Der Quelltext bleibt deutsch. Bei "en" übersetzt PelI18n alles beim Anzeigen:
# Fenster (New-PelForm), Menüs (New-PelContextMenu), Meldungen ([PelI18n]::Show),
# Tooltips ([PelI18n]::Tip), Protokollfenster ([PelI18n]::Append) und Listen-
# zellen ([PelI18n]::AddSub). Neue Texte: unten in $script:PelI18nDictEn eintragen
# ("deutscher Text<TAB>English text", Platzhalter {0}, {1} ... für variable Teile).
$script:PelLangFile = 'C:\Project-Earth-Lan\language.txt'
$script:PelLang = 'de'
$script:PelRestartRequested = $false

$script:PelI18nCode = @'
using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows.Forms;

// ============================================================================
// PelI18n - Sprachumschaltung Deutsch/Englisch fuer den ganzen Manager.
// Der Quelltext bleibt deutsch; uebersetzt wird beim ANZEIGEN:
//   - Attach(): Fenster, Beschriftungen, Buttons, Gruppen, Spaltenkoepfe und
//     Menues werden beim Erzeugen und bei jeder spaeteren Textaenderung uebersetzt
//   - Show()/Tip()/Append()/AddSub(): Meldungsfenster, Tooltips, Protokoll-
//     fenster und Listenzellen
// Woerterbuch: exakte Texte + Muster mit Platzhaltern ({0}, {1}, ...), deren
// Inhalte rekursiv mituebersetzt werden. Unbekannte Texte bleiben unveraendert.
// ============================================================================
public static class PelI18n
{
    public static bool Enabled = false;
    public static string Lang = "de";

    private static readonly Dictionary<string, string> exact = new Dictionary<string, string>(StringComparer.Ordinal);
    private sealed class Pat { public Regex Rx; public string Prefix; public string En; public int Weight; }
    private static readonly List<Pat> pats = new List<Pat>();
    private static readonly ConditionalWeakTable<object, object> done = new ConditionalWeakTable<object, object>();
    private static readonly object Marker = new object();
    private static readonly Regex phRx = new Regex(@"\{(\d+)(?::[^}]*)?\}", RegexOptions.CultureInvariant);
    private static readonly Regex stampRx = new Regex(@"^(\[\d{1,2}:\d{2}(?::\d{2})?\]\s+|\d{1,2}:\d{2}(?::\d{2})?\s+)", RegexOptions.CultureInvariant);
    [ThreadStatic] private static bool busy;

    public static int Count { get { return exact.Count + pats.Count; } }

    // ---- Woerterbuch laden ("deutsch<TAB>englisch" pro Zeile, \n \t \\ maskiert) ----
    public static void Load(string text)
    {
        if (string.IsNullOrEmpty(text)) return;
        foreach (string raw in text.Split('\n'))
        {
            string line = raw.TrimEnd('\r');
            int tab = line.IndexOf('\t');
            if (tab <= 0) continue;
            string de = Unesc(line.Substring(0, tab));
            string en = Unesc(line.Substring(tab + 1));
            Add(de, en);
            string[] dl = de.Split('\n');
            string[] el = en.Split('\n');
            if (dl.Length > 1 && dl.Length == el.Length)
            {
                for (int i = 0; i < dl.Length; i++)
                {
                    string a = dl[i].Trim(), b = el[i].Trim();
                    if (a.Length > 0 && b.Length > 0 && a != b) Add(a, b);
                }
            }
        }
        pats.Sort(delegate (Pat x, Pat y) { return y.Weight.CompareTo(x.Weight); });
    }

    private static string Unesc(string s)
    {
        if (s.IndexOf('\\') < 0) return s;
        StringBuilder sb = new StringBuilder(s.Length);
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '\\' && i + 1 < s.Length)
            {
                char n = s[++i];
                if (n == 'n') sb.Append('\n');
                else if (n == 't') sb.Append('\t');
                else sb.Append(n);
            }
            else sb.Append(c);
        }
        return sb.ToString();
    }

    private static int CountLetters(string s)
    {
        int n = 0;
        foreach (char c in s) if (char.IsLetter(c)) n++;
        return n;
    }

    public static void Add(string de, string en)
    {
        if (de == null || en == null) return;
        de = de.Trim();
        if (de.Length == 0) return;
        if (!phRx.IsMatch(de))
        {
            if (!exact.ContainsKey(de)) exact[de] = en;
            return;
        }
        StringBuilder rx = new StringBuilder("^");
        int last = 0, letters = 0;
        string prefix = null;
        HashSet<string> seen = new HashSet<string>();
        foreach (Match m in phRx.Matches(de))
        {
            string lit = de.Substring(last, m.Index - last);
            if (prefix == null) prefix = lit;
            letters += CountLetters(lit);
            rx.Append(Regex.Escape(lit));
            string g = "g" + m.Groups[1].Value;
            if (seen.Contains(g)) rx.Append(@"\k<" + g + ">");
            else { rx.Append("(?<" + g + ">.*?)"); seen.Add(g); }
            last = m.Index + m.Length;
        }
        string tail = de.Substring(last);
        letters += CountLetters(tail);
        rx.Append(Regex.Escape(tail)).Append("$");
        if (letters < 3) return;                        // zu unspezifisch, z. B. "{0} ({1})"
        Pat p = new Pat();
        p.Rx = new Regex(rx.ToString(), RegexOptions.Singleline | RegexOptions.CultureInvariant);
        p.Prefix = prefix ?? "";
        p.En = en;
        p.Weight = letters;
        pats.Add(p);
    }

    // ---- Uebersetzen -------------------------------------------------------------
    public static string Tr(string s) { return Tr(s, 0); }

    private static string Tr(string s, int depth)
    {
        if (!Enabled || string.IsNullOrEmpty(s) || depth > 4) return s;
        int a = 0; while (a < s.Length && char.IsWhiteSpace(s[a])) a++;
        int b = s.Length; while (b > a && char.IsWhiteSpace(s[b - 1])) b--;
        if (a >= b) return s;
        string core = s.Substring(a, b - a);
        bool crlf = core.IndexOf('\r') >= 0;
        string norm = crlf ? core.Replace("\r\n", "\n") : core;
        string t = Core(norm, depth);
        if (t == null && norm.IndexOf('\n') >= 0)
        {
            string[] lines = norm.Split('\n');
            bool changed = false;
            for (int i = 0; i < lines.Length; i++)
            {
                string x = Tr(lines[i], depth + 1);
                if (x != lines[i]) { lines[i] = x; changed = true; }
            }
            if (changed) t = string.Join("\n", lines);
        }
        if (t == null) return s;
        if (crlf) t = t.Replace("\n", "\r\n");
        return s.Substring(0, a) + t + s.Substring(b);
    }

    private static string Core(string core, int depth)
    {
        string v;
        if (exact.TryGetValue(core, out v)) return v;
        foreach (Pat p in pats)
        {
            if (p.Prefix.Length > 0 && !core.StartsWith(p.Prefix, StringComparison.Ordinal)) continue;
            Match m = p.Rx.Match(core);
            if (!m.Success) continue;
            StringBuilder sb = new StringBuilder();
            int last = 0;
            foreach (Match ph in phRx.Matches(p.En))
            {
                sb.Append(p.En, last, ph.Index - last);
                Group g = m.Groups["g" + ph.Groups[1].Value];
                if (g.Success) sb.Append(Tr(g.Value, depth + 1));
                last = ph.Index + ph.Length;
            }
            sb.Append(p.En, last, p.En.Length - last);
            return sb.ToString();
        }
        return null;
    }

    // Protokoll-/Chatzeilen: fuehrenden Zeitstempel "[12:34] " / "12:34:56  " erhalten
    public static string TrLine(string s)
    {
        if (!Enabled || string.IsNullOrEmpty(s)) return s;
        Match m = stampRx.Match(s);
        if (m.Success) return m.Value + Tr(s.Substring(m.Length));
        return Tr(s);
    }

    // ---- Oberflaeche -----------------------------------------------------------
    public static void Attach(Control c)
    {
        if (!Enabled || c == null) return;
        object d;
        if (done.TryGetValue(c, out d)) return;
        done.Add(c, Marker);
        if (c is Label || c is ButtonBase || c is GroupBox || c is TabPage || c is Form)
        {
            Fix(c);
            c.TextChanged += OnTextChanged;
        }
        ListView lv = c as ListView;
        if (lv != null)
        {
            FixColumns(lv);
            lv.HandleCreated += delegate (object s, EventArgs e) { FixColumns((ListView)s); };
        }
        ToolStrip ts = c as ToolStrip;
        if (ts != null) AttachStrip(ts);
        if (c.ContextMenuStrip != null) AttachStrip(c.ContextMenuStrip);
        c.ContextMenuStripChanged += delegate (object s, EventArgs e)
        {
            Control cc = (Control)s;
            if (cc.ContextMenuStrip != null) AttachStrip(cc.ContextMenuStrip);
        };
        foreach (Control ch in c.Controls) Attach(ch);
        c.ControlAdded += delegate (object s, ControlEventArgs e) { Attach(e.Control); };
    }

    public static void AttachStrip(ToolStrip ts)
    {
        if (!Enabled || ts == null) return;
        object d;
        if (done.TryGetValue(ts, out d)) return;
        done.Add(ts, Marker);
        foreach (ToolStripItem it in ts.Items) AttachItem(it);
        ts.ItemAdded += delegate (object s, ToolStripItemEventArgs e) { AttachItem(e.Item); };
    }

    private static void AttachItem(ToolStripItem it)
    {
        if (it == null) return;
        object d;
        if (done.TryGetValue(it, out d)) return;
        done.Add(it, Marker);
        FixItem(it);
        it.TextChanged += delegate (object s, EventArgs e) { FixItem((ToolStripItem)s); };
        ToolStripDropDownItem dd = it as ToolStripDropDownItem;
        if (dd != null)
        {
            if (dd.HasDropDownItems) AttachStrip(dd.DropDown);
            dd.DropDownOpening += delegate (object s, EventArgs e) { AttachStrip(((ToolStripDropDownItem)s).DropDown); };
        }
    }

    private static void OnTextChanged(object s, EventArgs e) { Fix((Control)s); }

    private static void Fix(Control c)
    {
        if (busy) return;
        string cur = c.Text;
        string t = Tr(cur);
        if (t != cur)
        {
            busy = true;
            try { c.Text = t; } finally { busy = false; }
        }
    }

    private static void FixItem(ToolStripItem it)
    {
        if (busy) return;
        busy = true;
        try
        {
            string t = Tr(it.Text);
            if (t != it.Text) it.Text = t;
            if (!string.IsNullOrEmpty(it.ToolTipText))
            {
                string tt = Tr(it.ToolTipText);
                if (tt != it.ToolTipText) it.ToolTipText = tt;
            }
        }
        finally { busy = false; }
    }

    private static void FixColumns(ListView lv)
    {
        foreach (ColumnHeader h in lv.Columns)
        {
            string t = Tr(h.Text);
            if (t != h.Text) h.Text = t;
        }
    }

    // ---- Ersatz fuer direkte WinForms-Aufrufe ------------------------------------
    public static void Tip(ToolTip tip, Control c, string text) { tip.SetToolTip(c, Tr(text)); }
    public static void Append(TextBoxBase box, string text) { box.AppendText(TrLine(text)); }
    public static ListViewItem.ListViewSubItem AddSub(ListViewItem it, string text) { return it.SubItems.Add(Tr(text)); }

    public static DialogResult Show(string text) { return MessageBox.Show(Tr(text)); }
    public static DialogResult Show(string text, string caption) { return MessageBox.Show(Tr(text), Tr(caption)); }
    public static DialogResult Show(string text, string caption, MessageBoxButtons buttons) { return MessageBox.Show(Tr(text), Tr(caption), buttons); }
    public static DialogResult Show(string text, string caption, MessageBoxButtons buttons, MessageBoxIcon icon) { return MessageBox.Show(Tr(text), Tr(caption), buttons, icon); }
    public static DialogResult Show(string text, string caption, MessageBoxButtons buttons, MessageBoxIcon icon, MessageBoxDefaultButton def) { return MessageBox.Show(Tr(text), Tr(caption), buttons, icon, def); }
    public static DialogResult Show(IWin32Window owner, string text) { return MessageBox.Show(owner, Tr(text)); }
    public static DialogResult Show(IWin32Window owner, string text, string caption) { return MessageBox.Show(owner, Tr(text), Tr(caption)); }
    public static DialogResult Show(IWin32Window owner, string text, string caption, MessageBoxButtons buttons) { return MessageBox.Show(owner, Tr(text), Tr(caption), buttons); }
    public static DialogResult Show(IWin32Window owner, string text, string caption, MessageBoxButtons buttons, MessageBoxIcon icon) { return MessageBox.Show(owner, Tr(text), Tr(caption), buttons, icon); }
    public static DialogResult Show(IWin32Window owner, string text, string caption, MessageBoxButtons buttons, MessageBoxIcon icon, MessageBoxDefaultButton def) { return MessageBox.Show(owner, Tr(text), Tr(caption), buttons, icon, def); }
}
'@

