function Set-PelLanguage([string]$Lang) {
    try {
        $dir = Split-Path -Parent $script:PelLangFile
        if (-not [System.IO.Directory]::Exists($dir)) { [void][System.IO.Directory]::CreateDirectory($dir) }
        [System.IO.File]::WriteAllText($script:PelLangFile, $Lang)
    } catch { }
}

# Gespeicherte Sprache; beim allerersten Start: Windows-Sprache (Deutsch -> de, sonst en)
function Get-PelLanguage {
    try {
        if ([System.IO.File]::Exists($script:PelLangFile)) {
            $l = ([System.IO.File]::ReadAllText($script:PelLangFile)).Trim().ToLowerInvariant()
            if ($l -eq 'de' -or $l -eq 'en') { return $l }
        }
    } catch { }
    $def = 'en'
    try { if ([System.Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName -eq 'de') { $def = 'de' } } catch { }
    Set-PelLanguage $def
    return $def
}

function Initialize-PelI18n {
    $script:PelLang = Get-PelLanguage
    if (-not ('PelI18n' -as [type])) {
        Add-Type -TypeDefinition $script:PelI18nCode -ReferencedAssemblies System.Windows.Forms -Language CSharp
    }
    [PelI18n]::Lang = $script:PelLang
    if ($script:PelLang -eq 'en') {
        try { [PelI18n]::Load($script:PelI18nDictEn); [PelI18n]::Enabled = $true } catch { $script:PelLang = 'de' }
    }
}

function New-PelForm {
    $f = New-Object -TypeName System.Windows.Forms.Form
    if ([PelI18n]::Enabled) { [PelI18n]::Attach($f) }
    return $f
}

function New-PelContextMenu {
    $m = New-Object -TypeName System.Windows.Forms.ContextMenuStrip
    if ([PelI18n]::Enabled) { [PelI18n]::AttachStrip($m) }
    return $m
}

# Übersetzung für Texte außerhalb der Oberfläche (z. B. erzeugte Dateien)
function ConvertTo-PelLang([string]$Text) { return [PelI18n]::Tr($Text) }

# Neustart nach Sprachwechsel: kurz warten, bis dieses Control Center beendet ist
# (nur ein Control Center pro PC), dann neu starten.
function Start-PelDelayedRestart {
    try {
        $cmd = $null
        if ($script:IsCompiledExe -and $script:SelfPath) { $cmd = "start `"`" `"$($script:SelfPath)`"" }
        elseif ($script:SelfPath) { $cmd = "start `"`" powershell.exe -NoProfile -ExecutionPolicy Bypass -STA -WindowStyle Hidden -File `"$($script:SelfPath)`"" }
        if ($cmd) { Start-Process -FilePath 'cmd.exe' -ArgumentList "/c timeout /t 3 /nobreak >nul & $cmd" -WindowStyle Hidden }
    } catch { }
}

Initialize-PelI18n

# ------------------------------------------------------------------------------
# HELPER & PROGRESS DIALOG FUNKTIONEN
# ------------------------------------------------------------------------------

function Show-ProgressDialog {
    param (
        [string]$Title,
        [scriptblock]$TaskScript
    )

    $pForm = (New-PelForm)
    $pForm.Text = $Title
    $pForm.Size = New-Object System.Drawing.Size(500, 190)
    $pForm.StartPosition = "CenterScreen"
    $pForm.FormBorderStyle = "Sizable"
    $pForm.MaximizeBox = $true
    $pForm.MinimizeBox = $false
    $pForm.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $pForm.ForeColor = [System.Drawing.Color]::White

    $lblStatus = New-Object System.Windows.Forms.Label
    $lblStatus.Text = "Initialisiere Vorgang..."
    $lblStatus.Location = New-Object System.Drawing.Point(20, 20)
    $lblStatus.Size = New-Object System.Drawing.Size(445, 30)
    $lblStatus.ForeColor = [System.Drawing.Color]::White
    $lblStatus.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)
    $pForm.Controls.Add($lblStatus)

    $pb = New-Object System.Windows.Forms.ProgressBar
    $pb.Location = New-Object System.Drawing.Point(20, 55)
    $pb.Size = New-Object System.Drawing.Size(445, 25)
    $pb.Minimum = 0
    $pb.Maximum = 100
    $pb.Value = 0
    $pForm.Controls.Add($pb)

    $lblPercent = New-Object System.Windows.Forms.Label
    $lblPercent.Text = "0%"
    $lblPercent.Location = New-Object System.Drawing.Point(20, 90)
    $lblPercent.Size = New-Object System.Drawing.Size(445, 20)
    $lblPercent.TextAlign = "MiddleCenter"
    $lblPercent.ForeColor = [System.Drawing.Color]::LightGray
    $lblPercent.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Regular)
    $pForm.Controls.Add($lblPercent)

    $updateProgress = {
        param([string]$statusText, [int]$percentValue)
        if ($statusText) { $lblStatus.Text = $statusText }
        if ($percentValue -ge 0 -and $percentValue -le 100) {
            $pb.Value = $percentValue
            $lblPercent.Text = "$percentValue%"
        }
        [System.Windows.Forms.Application]::DoEvents()
    }

    $pForm.Add_Shown({
        try {
            &$TaskScript $updateProgress
            Start-Sleep -Milliseconds 600
        } catch {
            [PelI18n]::Show("Fehler während des Vorgangs:`n$($_.Exception.Message)", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        } finally {
            $pForm.Close()
        }
    })

    $pForm.Add_Shown({ Enable-PelResizableForm $pForm }.GetNewClosure())
    [void]$pForm.ShowDialog()
}

# ------------------------------------------------------------------------------
# FENSTER-SKALIERUNG (alle Fenster in der Groesse veraenderbar, Inhalt skaliert mit)
# ------------------------------------------------------------------------------
# Macht ein bereits fertig aufgebautes Formular (alle Controls hinzugefuegt) frei in
# Länge/Höhe/Breite veraenderbar: erfasst beim ersten Anzeigen (Add_Shown) die
# urspruengliche Groesse & Position jedes (auch verschachtelten) Steuerelements sowie
# dessen Schriftgroesse als "Blaupause" und skaliert bei jedem Resize-Ereignis Position,
# Groesse und Schriftgroesse aller Controls proportional zur neuen Fenstergroesse. Das
# funktioniert generisch fuer JEDES Formular, ohne dass jedes einzelne Steuerelement von
# Hand mit "Anchor"/"Dock" versehen werden muss. Formulare, die bereits ein eigenes,
# handgepflegtes Anchor-Layout besitzen (z. B. Server-Manager, Kommunikationszentrale,
# Kodi-Steuerung), rufen diese Funktion bewusst NICHT auf, um das native Anchor-Verhalten
# nicht doppelt zu ueberschreiben.
# ------------------------------------------------------------------------------
# Macht ein bereits fertig aufgebautes Formular (alle Controls hinzugefuegt) frei in
# Länge/Höhe/Breite veraenderbar und skaliert bei jedem Resize-Ereignis Position,
# Groesse und Schriftgroesse aller Controls proportional zur neuen Fenstergroesse.
# BUGFIX: Steuerelemente, die ERST NACH dem ersten Anzeigen dazukommen (z. B. eine
# Mitgliederliste, die sich per Knopfdruck neu aufbaut), wurden bisher nicht erfasst
# und blieben beim Skalieren auf der Stelle. Jeder Container (das Formular selbst
# und jedes verschachtelte Panel/jede GroupBox) bekommt deshalb einen "ControlAdded"-
# Beobachter: taucht dort ein neues Steuerelement auf, wird seine Basis-Position aus
# der AKTUELLEN Fenstergröße zurückgerechnet, so als wäre es von Anfang an dabei
# gewesen - und ein "ControlRemoved"-Beobachter entfernt es wieder aus der Liste,
# wenn eine Liste geleert/neu aufgebaut wird (verhindert, dass die interne Liste bei
# häufig aktualisierten Ansichten immer weiter anwächst).
# Formulare, die bereits ein eigenes, handgepflegtes Anchor-Layout besitzen (z. B.
# Server-Manager, Kommunikationszentrale, Kodi-Steuerung), rufen diese Funktion
# bewusst NICHT auf, um das native Anchor-Verhalten nicht doppelt zu ueberschreiben.
function Enable-PelResizableForm {
    param([System.Windows.Forms.Form]$Form)
    if (-not $Form -or $Form.IsDisposed) { return }
    if ($Form.FormBorderStyle -eq [System.Windows.Forms.FormBorderStyle]::FixedDialog -or
        $Form.FormBorderStyle -eq [System.Windows.Forms.FormBorderStyle]::Sizable) {
        $Form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::Sizable
    }
    $state = [pscustomobject]@{
        Baseline = [System.Collections.Generic.List[object]]::new()
        OrigW    = [double][Math]::Max(1, $Form.ClientSize.Width)
        OrigH    = [double][Math]::Max(1, $Form.ClientSize.Height)
        Busy     = $false
    }

    function Get-PelCurrentScale {
        $sx = $Form.ClientSize.Width / $state.OrigW
        $sy = $Form.ClientSize.Height / $state.OrigH
        if ($sx -le 0) { $sx = 1 }
        if ($sy -le 0) { $sy = 1 }
        return @($sx, $sy, [Math]::Min($sx, $sy))
    }

    function Add-PelBaselineEntry($Ctrl) {
        $sc = Get-PelCurrentScale
        $entry = [pscustomobject]@{
            Ctrl = $Ctrl
            X = $Ctrl.Left / $sc[0]; Y = $Ctrl.Top / $sc[1]
            W = $Ctrl.Width / $sc[0]; H = $Ctrl.Height / $sc[1]
            FontSize = $(if ($sc[2] -gt 0) { $Ctrl.Font.Size / $sc[2] } else { $Ctrl.Font.Size })
        }
        $state.Baseline.Add($entry)
    }

    function Watch-PelContainer($Parent) {
        $Parent.Add_ControlAdded({
            param($s, $e)
            if (-not $e.Control -or $e.Control.IsDisposed) { return }
            Add-PelBaselineEntry $e.Control
            Watch-PelContainer $e.Control
            if ($e.Control.Controls -and $e.Control.Controls.Count -gt 0) { Register-PelContainer $e.Control }
        }.GetNewClosure())
        $Parent.Add_ControlRemoved({
            param($s, $e)
            for ($i = $state.Baseline.Count - 1; $i -ge 0; $i--) {
                if ($state.Baseline[$i].Ctrl -eq $e.Control) { $state.Baseline.RemoveAt($i) }
            }
        }.GetNewClosure())
    }

    function Register-PelContainer($Parent) {
        foreach ($c in @($Parent.Controls)) {
            Add-PelBaselineEntry $c
            Watch-PelContainer $c
            if ($c.Controls -and $c.Controls.Count -gt 0) { Register-PelContainer $c }
        }
    }

    Register-PelContainer $Form
    Watch-PelContainer $Form

    if (-not $Form.MinimumSize -or $Form.MinimumSize.Width -eq 0) {
        try { $Form.MinimumSize = New-Object System.Drawing.Size([int]($state.OrigW * 0.4), [int]($state.OrigH * 0.4)) } catch { }
    }
    $Form.Add_Resize({
        param($s, $e)
        if ($state.Busy) { return }
        if ($s.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { return }
        if ($state.OrigW -le 0 -or $state.OrigH -le 0) { return }
        $state.Busy = $true
        try {
            $sx = $s.ClientSize.Width / $state.OrigW
            $sy = $s.ClientSize.Height / $state.OrigH
            if ($sx -le 0 -or $sy -le 0) { return }
            $sf = [Math]::Min($sx, $sy)
            foreach ($b in @($state.Baseline)) {
                if (-not $b.Ctrl -or $b.Ctrl.IsDisposed) { continue }
                $b.Ctrl.Left = [int]([Math]::Round($b.X * $sx))
                $b.Ctrl.Top = [int]([Math]::Round($b.Y * $sy))
                $b.Ctrl.Width = [Math]::Max(1, [int]([Math]::Round($b.W * $sx)))
                $b.Ctrl.Height = [Math]::Max(1, [int]([Math]::Round($b.H * $sy)))
                if ($b.FontSize -gt 0) {
                    try {
                        $newSize = [Math]::Max(6.0, [Math]::Min(28.0, [double]$b.FontSize * $sf))
                        $b.Ctrl.Font = New-Object System.Drawing.Font($b.Ctrl.Font.FontFamily, $newSize, $b.Ctrl.Font.Style)
                    } catch { }
                }
            }
        } catch {
        } finally { $state.Busy = $false }
    }.GetNewClosure())
}

# ------------------------------------------------------------------------------
# NEUE VERSION AUF GITHUB? (nur lesen - es wird NICHTS heruntergeladen oder ersetzt)
# ------------------------------------------------------------------------------
# Die fruehere automatische Update-Verteilung (zentraler Server + P2P ueber Port 9777)
# wurde komplett entfernt. Stattdessen schaut das Control Center beim Start und danach
# alle 6 Stunden auf GitHub nach, ob dort eine neuere Version liegt als dieser Build
# ($script:PelVersion). Wenn ja, erscheint im Live-Status der Button "Neue Version auf
# GitHub", der nur die GitHub-Seite im Browser oeffnet - herunterladen und ersetzen
# macht jeder selbst. Damit kann niemand ueber das Netzwerk fremden Code einschleusen.
#
# Wo gesucht wird (alles oeffentlich lesbar, keine Anmeldung, kein Token):
#   1. neuestes Release (Tag und Titel, z. B. "v2026.09.29" oder "Stand 29.09.2026")
#   2. Tags des Repositorys
#   3. Dateinamen im Hauptverzeichnis (.ps1/.exe/.zip/.7z/.rar/.msi), z. B.
#      "Project Earth Lan Manager 29.09.2026.ps1"
#   4. optional eine version.txt im Hauptverzeichnis (erste Zeile = Version)
# Erkannt werden Datumsangaben als JJJJ.MM.TT und TT.MM.JJJJ (auch mit - oder _).
# Daten, die mehr als 2 Tage in der Zukunft liegen, werden ignoriert (Tippfehler).
# Laeuft in einem eigenen Runspace, die Oberflaeche friert dabei nicht ein.
$script:PelGitHubLatest = ''
$script:PelGitHubCheckScript = {
    param([string]$ApiLatest, [string]$ApiTags, [string]$ApiContents, [string]$RawVersion)
    $state = @{ Best = ''; Src = ''; Ok = $false }
    $maxAllowed = (Get-Date).AddDays(2).ToString('yyyy.MM.dd')
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }

    function Add-PelFoundVersion([string]$Text, [string]$Source) {
        if ([string]::IsNullOrWhiteSpace($Text)) { return }
        $found = @()
        foreach ($m in [regex]::Matches($Text, '(?<!\d)(20\d\d)[._-](\d{1,2})[._-](\d{1,2})(?!\d)')) {
            $found += ,@([int]$m.Groups[1].Value, [int]$m.Groups[2].Value, [int]$m.Groups[3].Value)
        }
        foreach ($m in [regex]::Matches($Text, '(?<!\d)(\d{1,2})[._-](\d{1,2})[._-](20\d\d)(?!\d)')) {
            $found += ,@([int]$m.Groups[3].Value, [int]$m.Groups[2].Value, [int]$m.Groups[1].Value)
        }
        foreach ($f in $found) {
            if ($f[1] -lt 1 -or $f[1] -gt 12 -or $f[2] -lt 1 -or $f[2] -gt 31) { continue }
            $v = '{0:D4}.{1:D2}.{2:D2}' -f $f[0], $f[1], $f[2]
            if ($v -gt $maxAllowed) { continue }
            if ($v -gt $state.Best) { $state.Best = $v; $state.Src = $Source }
        }
    }
    function Get-PelWebText([string]$Url) {
        try {
            $r = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 12 -UserAgent 'ProjectEarthLanManager' -ErrorAction Stop
            $state.Ok = $true
            $c = $r.Content
            if ($c -is [byte[]]) { $c = [System.Text.Encoding]::UTF8.GetString($c) }
            return [string]$c
        } catch { return $null }
    }
    function Get-PelJsonNames([string]$Json, [string]$Field) {
        $names = @()
        if (-not $Json) { return $names }
        foreach ($m in [regex]::Matches($Json, '"' + $Field + '"\s*:\s*"((?:[^"\\]|\\.)*)"')) { $names += $m.Groups[1].Value }
        return $names
    }

    $rel = Get-PelWebText $ApiLatest
    foreach ($n in (Get-PelJsonNames $rel 'tag_name')) { Add-PelFoundVersion $n "Release $n" }
    foreach ($n in (Get-PelJsonNames $rel 'name')) { Add-PelFoundVersion $n "Release $n" }
    $tags = Get-PelWebText $ApiTags
    foreach ($n in (Get-PelJsonNames $tags 'name')) { Add-PelFoundVersion $n "Tag $n" }
    $files = Get-PelWebText $ApiContents
    foreach ($n in (Get-PelJsonNames $files 'name')) {
        if ($n -match '(?i)\.(ps1|exe|zip|7z|rar|msi)$') { Add-PelFoundVersion $n "Datei $n" }
    }
    $vt = Get-PelWebText $RawVersion
    if ($vt) {
        $first = @($vt -split "`r?`n" | Where-Object { $_.Trim() -ne '' } | Select-Object -First 1)
        if ($first.Count -gt 0) { Add-PelFoundVersion ([string]$first[0]) 'version.txt' }
    }
    return [pscustomobject]@{ Ok = [bool]$state.Ok; Latest = [string]$state.Best; Source = [string]$state.Src }
}

# Oeffnet die GitHub-Seite des Projekts im Standardbrowser.
function Open-PelGitHubPage {
    try { Start-Process $script:PelGitHubUrl | Out-Null } catch {
        try { Start-Process 'explorer.exe' -ArgumentList $script:PelGitHubUrl | Out-Null } catch { }
    }
}

# ------------------------------------------------------------------------------
# ZENTRALE NETZWERKADAPTER-AUSWAHL (Control Center -> Live-Status -> "Adapter wechseln")
# ------------------------------------------------------------------------------
# Statt in jedem einzelnen Options-Fenster (Kommunikationszentrale, Server-Browser, ...)
# erneut nach dem Adapter zu fragen, wird die Auswahl einmal hier getroffen und in einer
# gemeinsamen Datei gespeichert. Jedes Options-Fenster liest sie beim Start und startet
# seine Netzwerk-Dienste direkt damit, ohne den Nutzer noch einmal zu fragen.
$script:PelAdapterConfigPath = "C:\Project-Earth-Lan\selected_adapter.json"

function Get-PelAdapterList {
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($nic in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
        if ($nic.OperationalStatus -ne [System.Net.NetworkInformation.OperationalStatus]::Up) { continue }
        if ($nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Loopback) { continue }
        if ($nic.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Tunnel) { continue }
        foreach ($ua in $nic.GetIPProperties().UnicastAddresses) {
            if ($ua.Address.AddressFamily -ne [System.Net.Sockets.AddressFamily]::InterNetwork) { continue }
            $ip = $ua.Address.ToString()
            if ($ip.StartsWith('169.254.')) { continue }
            $mask = '255.255.255.0'
            if ($ua.IPv4Mask) { $mask = $ua.IPv4Mask.ToString() }
            $metric = 0
            try {
                $ifc = Get-NetIPInterface -InterfaceAlias $nic.Name -AddressFamily IPv4 -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($ifc) { $metric = [int]$ifc.InterfaceMetric }
            } catch { }
            $list.Add([pscustomobject]@{
                Name        = $nic.Name
                Description = $nic.Description
                Ip          = $ip
                Mask        = $mask
                Metric      = $metric
                IsP2P       = [bool](($nic.Name -eq $script:PelP2pAdapterName) -or ($nic.Description -match 'Project Earth P2P'))
            })
        }
    }
    return $list
}

# Automatische Adapter-Wahl beim ersten Öffnen (noch nichts zentral gewählt): es gewinnt
# der Adapter mit der niedrigsten Schnittstellenmetrik unter allen aktiven IPv4-Adaptern
# (Windows priorisiert Routen mit der niedrigsten Metrik, das ist also der Adapter, den
# Windows selbst als bevorzugte Verbindung verwendet).
function Get-PelAutoAdapter {
    $all = @(Get-PelAdapterList)
    if ($all.Count -eq 0) { return $null }
    return ($all | Sort-Object -Property Metric | Select-Object -First 1)
}

# Liest die zentral gespeicherte Adapter-Auswahl und prüft, ob sie noch existiert/aktiv
# ist (IP-Abgleich gegen die aktuell aktiven Adapter) - liefert $null, wenn noch nichts
# gewählt wurde oder der gespeicherte Adapter gerade nicht verfügbar ist.
function Get-PelSelectedAdapter {
    try {
        if (-not (Test-Path -LiteralPath $script:PelAdapterConfigPath)) { return $null }
        $saved = Get-Content -LiteralPath $script:PelAdapterConfigPath -Raw | ConvertFrom-Json
        if (-not $saved -or -not $saved.Ip) { return $null }
        $current = @(Get-PelAdapterList) | Where-Object { $_.Ip -eq $saved.Ip } | Select-Object -First 1
        return $current
    } catch {
        return $null
    }
}

function Save-PelSelectedAdapter {
    param($Adapter)
    try {
        $dir = Split-Path -Parent $script:PelAdapterConfigPath
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -Path $dir -ItemType Directory -Force | Out-Null }
        $Adapter | Select-Object Name, Description, Ip, Mask | ConvertTo-Json | Set-Content -LiteralPath $script:PelAdapterConfigPath -Encoding UTF8
    } catch { }
}

# Gemeinsamer Auswahldialog (Control Center -> "Adapter wechseln"). $ParentForm ist
# optional (für die Zentrierung über dem aufrufenden Fenster).
function Select-PelNetworkAdapter {
    param($ParentForm = $null)
    $adapters = @(Get-PelAdapterList)
    if ($adapters.Count -eq 0) {
        [PelI18n]::Show("Es wurde kein aktiver IPv4-Netzwerkadapter gefunden.", "Netzwerkadapter", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
        return $null
    }
    $current = Get-PelSelectedAdapter

    $dlg = (New-PelForm)
    $dlg.Text = "Netzwerkadapter wählen"
    $dlg.Size = New-Object System.Drawing.Size(700, 380)
    $dlg.StartPosition = "CenterParent"
    $dlg.FormBorderStyle = "Sizable"
    $dlg.MaximizeBox = $true
    $dlg.Add_Shown({ Enable-PelResizableForm $dlg }.GetNewClosure())
    $dlg.MaximizeBox = $false
    $dlg.MinimizeBox = $false
    $dlg.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $dlg.ForeColor = [System.Drawing.Color]::White

    $fontMainDlg = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
    $fontBoldDlg = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)

    $lblHint = New-Object System.Windows.Forms.Label
    $lblHint.Text = "Adapter auswählen (der P2P-Adapter PEL-P2P ist grün markiert). Gilt für alle Fenster (Chat/Voice, Server-Browser, ...)."
    $lblHint.Location = New-Object System.Drawing.Point(12, 12)
    $lblHint.Size = New-Object System.Drawing.Size(660, 22)
    $lblHint.ForeColor = [System.Drawing.Color]::White
    $lblHint.Font = $fontMainDlg
    $dlg.Controls.Add($lblHint)

    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = New-Object System.Drawing.Point(12, 40)
    $lv.Size = New-Object System.Drawing.Size(660, 240)
    $lv.View = "Details"
    $lv.FullRowSelect = $true
    $lv.HideSelection = $false
    $lv.MultiSelect = $false
    $lv.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
    $lv.ForeColor = [System.Drawing.Color]::White
    $lv.Font = $fontMainDlg
    [void]$lv.Columns.Add("Adapter", 150)
    [void]$lv.Columns.Add("Beschreibung", 260)
    [void]$lv.Columns.Add("IPv4", 120)
    [void]$lv.Columns.Add("Maske", 110)
    $dlg.Controls.Add($lv)

    $preselect = $null
    foreach ($a in $adapters) {
        $it = New-Object System.Windows.Forms.ListViewItem($a.Name)
        [void][PelI18n]::AddSub($it, $a.Description)
        [void][PelI18n]::AddSub($it, $a.Ip)
        [void][PelI18n]::AddSub($it, $a.Mask)
        $it.Tag = $a
        if ($a.IsP2P) { $it.ForeColor = [System.Drawing.Color]::LightGreen }
        [void]$lv.Items.Add($it)
        if (-not $preselect) {
            if ($current -and $current.Ip -eq $a.Ip) { $preselect = $it }
            elseif (-not $current -and $a.IsP2P) { $preselect = $it }
        }
    }
    if (-not $preselect) { $preselect = $lv.Items[0] }
    $preselect.Selected = $true

    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Text = "Übernehmen"
    $btnOk.Location = New-Object System.Drawing.Point(400, 295)
    $btnOk.Size = New-Object System.Drawing.Size(130, 34)
    $btnOk.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnOk.ForeColor = [System.Drawing.Color]::White
    $btnOk.FlatStyle = "Flat"
    $btnOk.Font = $fontBoldDlg
    $btnOk.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $dlg.Controls.Add($btnOk)

    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = "Abbrechen"
    $btnCancel.Location = New-Object System.Drawing.Point(542, 295)
    $btnCancel.Size = New-Object System.Drawing.Size(130, 34)
    $btnCancel.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
    $btnCancel.ForeColor = [System.Drawing.Color]::White
    $btnCancel.FlatStyle = "Flat"
    $btnCancel.Font = $fontBoldDlg
    $btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $dlg.Controls.Add($btnCancel)

    $lv.Add_DoubleClick({ $btnOk.PerformClick() })
    $dlg.AcceptButton = $btnOk
    $dlg.CancelButton = $btnCancel

    $result = $null
    $ownerArg = if ($ParentForm) { $ParentForm } else { $null }
    $dlgResult = if ($ownerArg) { $dlg.ShowDialog($ownerArg) } else { $dlg.ShowDialog() }
    if ($dlgResult -eq [System.Windows.Forms.DialogResult]::OK -and $lv.SelectedItems.Count -gt 0) {
        $result = $lv.SelectedItems[0].Tag
        Save-PelSelectedAdapter -Adapter $result
    }
    $dlg.Dispose()
    return $result
}

# ==============================================================================
# NATIVES P2P-NETZWERK (ersetzt ZeroTier komplett)
# ==============================================================================
# Aufbau (Details siehe P2P-Integrationsanleitung):
#   1. Signaling   : kleiner UDP-Vermittlungsserver (PEL-Rendezvous.ps1). Jeder Manager
#                    meldet sich mit LobbyId (Hash des Lobby-Namens), Zufalls-NodeId und
#                    seinen lokalen Adressen an. Der Server sieht dabei die öffentliche
#                    Adresse (NAT-Außenseite), vergibt eine feste virtuelle IP (10.77.x.y)
#                    und verteilt die Adressliste an alle Lobby-Mitglieder.
#   2. Hole Punching: beide Seiten schicken gleichzeitig authentifizierte HELLO-Pakete an
#                    alle bekannten Adressen des anderen -> beide NATs öffnen ein "Loch",
#                    das erste gültige Paket legt den direkten Weg fest. Keepalive alle 5 s.
#                    Klappt es nach 8 s nicht (beide symmetrisches NAT), läuft der Verkehr
#                    verschlüsselt über den Server (Relay) - Punching läuft im Hintergrund
#                    weiter und wechselt automatisch auf direkt, sobald es klappt.
#   3. Routing     : virtueller Adapter "PEL-P2P" (Wintun, Layer 3). Windows schickt alles
#                    für 10.77.0.0/16 (inkl. Broadcasts 255.255.255.255 / 10.77.255.255 für
#                    Server-Browser) an den Adapter, die Engine verschlüsselt es und sendet
#                    es per UDP an den passenden Peer (Unicast) bzw. an alle (Broadcast).
#   4. Sicherheit  : AES-256-CTR + HMAC-SHA256 mit einem Schlüssel aus Lobby-Passwort
#                    (PBKDF2, 100.000 Runden). Replay-Schutz, Absender-IP-Prüfung. Der
#                    Server kann nichts mitlesen und nichts einschleusen.
# Die Engine läuft komplett in eigenen .NET-Threads (kein PowerShell im Paketpfad) und
# lebt im Control Center - alle Options-Fenster nutzen den Adapter automatisch mit.
# ------------------------------------------------------------------------------
$script:PelP2pDir           = 'C:\Project-Earth-Lan\p2p'
$script:PelP2pSettingsPath  = 'C:\Project-Earth-Lan\p2p\p2p_settings.json'
$script:PelP2pAdapterName   = 'PEL-P2P'
$script:PelP2pUdpPort       = 47800
$script:PelP2pMtu           = 1380
# Standard-Vermittlungsserver (Host:Port) - hier eure Serveradresse eintragen, dann
# müssen die Spieler im Control Center nur noch Lobby-Name und Passwort eingeben.
$script:PelP2pDefaultServer = ''
# Wintun (offizieller, signierter WireGuard-TUN-Treiber). Wird beim ersten Beitritt
# einmalig geladen, per SHA-256 UND Authenticode-Signatur (WireGuard LLC) geprüft.
# Offline: wintun.dll aus dem ZIP (bin\<amd64|x86|arm64>) unverändert nach
# C:\Project-Earth-Lan\p2p\<amd64|x86|arm64>\wintun.dll kopieren.
$script:PelP2pWintunUrl     = 'https://www.wintun.net/builds/wintun-0.14.1.zip'
$script:PelP2pWintunSha256  = '07C256185D6EE3652E09FA55C0B673E2624B565E02C4B9091C79CA7D2F24EF51'
$script:PelP2pEngine        = $null
$script:PelP2pCfgJob        = $null

$script:PelP2pCode = @'
using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using Microsoft.Win32.SafeHandles;

// ============================================================================
// Project Earth LAN - natives P2P-Netzwerk (ersetzt ZeroTier)
//   PelWintun      : P/Invoke auf wintun.dll (virtueller Layer-3-Adapter / TUN)
//   PelBytes       : Big-Endian-Helfer
//   PelP2pCrypto   : AES-256-CTR + HMAC-SHA256 (Encrypt-then-MAC), 16 Byte Tag
//   PelP2pEngine   : Signaling-Client, UDP Hole Punching, Relay-Fallback,
//                    Paket-Routing TUN <-> UDP (laeuft komplett in eigenen Threads)
// Bewusst C# 5 (Windows PowerShell 5.1 / Add-Type / PS2EXE kompatibel).
// ============================================================================

public static class PelWintun
{
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode, EntryPoint = "LoadLibraryW")]
    public static extern IntPtr LoadLibrary(string path);

    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode, EntryPoint = "SetDllDirectoryW")]
    public static extern bool SetDllDirectory(string path);

    [DllImport("wintun.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    public static extern IntPtr WintunCreateAdapter(string name, string tunnelType, ref Guid requestedGuid);

    [DllImport("wintun.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    public static extern IntPtr WintunOpenAdapter(string name);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern void WintunCloseAdapter(IntPtr adapter);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern IntPtr WintunStartSession(IntPtr adapter, uint capacity);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern void WintunEndSession(IntPtr session);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern IntPtr WintunGetReadWaitEvent(IntPtr session);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern IntPtr WintunReceivePacket(IntPtr session, out uint packetSize);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern void WintunReleaseReceivePacket(IntPtr session, IntPtr packet);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern IntPtr WintunAllocateSendPacket(IntPtr session, uint packetSize);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern void WintunSendPacket(IntPtr session, IntPtr packet);

    [DllImport("wintun.dll", SetLastError = true)]
    public static extern uint WintunGetRunningDriverVersion();

    private static string loadedPath = null;

    // Laedt wintun.dll von einem festen Pfad. Danach findet jeder [DllImport("wintun.dll")]
    // automatisch das bereits geladene Modul. WICHTIG: Die Datei muss exakt "wintun.dll"
    // heissen - Windows ordnet geladene Module ueber den Dateinamen zu.
    public static void Load(string fullPath)
    {
        if (loadedPath != null) return;
        if (!string.Equals(System.IO.Path.GetFileName(fullPath), "wintun.dll", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("Die Wintun-Datei muss wintun.dll heissen: " + fullPath);
        try { SetDllDirectory(System.IO.Path.GetDirectoryName(fullPath)); } catch { }
        IntPtr h = LoadLibrary(fullPath);
        if (h == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(), "wintun.dll konnte nicht geladen werden: " + fullPath);
        loadedPath = fullPath;
    }
}

// Kapselt ein natives Event-Handle (von Wintun), damit WaitHandle.WaitAny es nutzen kann.
// ownsHandle = false: Wintun gibt das Handle selbst frei.
public sealed class PelNativeWaitHandle : WaitHandle
{
    public PelNativeWaitHandle(IntPtr handle) { SafeWaitHandle = new SafeWaitHandle(handle, false); }
}

public static class PelBytes
{
    public static uint ReadU32(byte[] b, int o) { return ((uint)b[o] << 24) | ((uint)b[o + 1] << 16) | ((uint)b[o + 2] << 8) | b[o + 3]; }
    public static void WriteU32(byte[] b, int o, uint v) { b[o] = (byte)(v >> 24); b[o + 1] = (byte)(v >> 16); b[o + 2] = (byte)(v >> 8); b[o + 3] = (byte)v; }
    public static int ReadU16(byte[] b, int o) { return (b[o] << 8) | b[o + 1]; }
    public static void WriteU16(byte[] b, int o, int v) { b[o] = (byte)(v >> 8); b[o + 1] = (byte)v; }
    public static ulong ReadU64(byte[] b, int o) { return ((ulong)ReadU32(b, o) << 32) | ReadU32(b, o + 4); }
    public static void WriteU64(byte[] b, int o, ulong v) { WriteU32(b, o, (uint)(v >> 32)); WriteU32(b, o + 4, (uint)v); }
    public static string IpToString(uint ip) { return (ip >> 24) + "." + ((ip >> 16) & 255) + "." + ((ip >> 8) & 255) + "." + (ip & 255); }
    public static uint IpToUInt(IPAddress a) { return ReadU32(a.GetAddressBytes(), 0); }
    public static IPAddress UIntToIp(uint v) { byte[] b = new byte[4]; WriteU32(b, 0, v); return new IPAddress(b); }
    public static bool IsPrivate(IPAddress a)
    {
        byte[] b = a.GetAddressBytes();
        if (b.Length != 4) return false;
        return b[0] == 10 || (b[0] == 172 && b[1] >= 16 && b[1] <= 31) || (b[0] == 192 && b[1] == 168) || (b[0] == 100 && b[1] >= 64 && b[1] <= 127);
    }
    public static byte[] Utf8Limit(string s, int maxBytes)
    {
        if (s == null) s = "";
        while (s.Length > 0 && Encoding.UTF8.GetByteCount(s) > maxBytes) s = s.Substring(0, s.Length - 1);
        return Encoding.UTF8.GetBytes(s);
    }
}

// ----------------------------------------------------------------------------
// Paketformat Peer <-> Peer (alles nach dem Header ist verschluesselt):
//   [0..1]  Magic 'P''E'   [2] Typ   [3..10] Absender-NodeId   [11..14] Seq
//   [15..]  AES-256-CTR(Nutzdaten)    [letzte 16] HMAC-SHA256(Header+Chiffrat)
// CTR-Zaehlerblock = NodeId(8) | Seq(4) | Blocknummer(4) -> nie doppelt, weil jede
// Sitzung eine neue Zufalls-NodeId bekommt und Seq pro Paket hochzaehlt.
// Eine Instanz pro Thread verwenden (HMAC/ICryptoTransform sind nicht threadsicher).
// ----------------------------------------------------------------------------
public sealed class PelP2pCrypto
{
    public const int Hdr = 15;
    public const int Tag = 16;
    private readonly ICryptoTransform ecb;
    private readonly HMACSHA256 mac;

    public PelP2pCrypto(byte[] encKey, byte[] macKey)
    {
        Aes aes = Aes.Create();
        aes.Mode = CipherMode.ECB;
        aes.Padding = PaddingMode.None;
        aes.Key = encKey;
        ecb = aes.CreateEncryptor();
        mac = new HMACSHA256(macKey);
    }

    private void Ctr(ulong node, uint seq, byte[] src, int srcOff, byte[] dst, int dstOff, int len)
    {
        if (len <= 0) return;
        int blocks = (len + 15) / 16;
        byte[] ctr = new byte[blocks * 16];
        for (int b = 0; b < blocks; b++)
        {
            int o = b * 16;
            PelBytes.WriteU64(ctr, o, node);
            PelBytes.WriteU32(ctr, o + 8, seq);
            PelBytes.WriteU32(ctr, o + 12, (uint)b);
        }
        byte[] ks = new byte[ctr.Length];
        ecb.TransformBlock(ctr, 0, ctr.Length, ks, 0);
        for (int i = 0; i < len; i++) dst[dstOff + i] = (byte)(src[srcOff + i] ^ ks[i]);
    }

    public byte[] Seal(byte type, ulong node, uint seq, byte[] body, int off, int len)
    {
        byte[] p = new byte[Hdr + len + Tag];
        p[0] = 0x50; p[1] = 0x45; p[2] = type;
        PelBytes.WriteU64(p, 3, node);
        PelBytes.WriteU32(p, 11, seq);
        Ctr(node, seq, body, off, p, Hdr, len);
        byte[] h = mac.ComputeHash(p, 0, Hdr + len);
        Buffer.BlockCopy(h, 0, p, Hdr + len, Tag);
        return p;
    }

    // Liefert die entschluesselten Nutzdaten oder null (falscher Schluessel / manipuliert).
    public byte[] Open(byte[] buf, int off, int len, out byte type, out ulong node, out uint seq)
    {
        type = 0; node = 0; seq = 0;
        if (len < Hdr + Tag || buf[off] != 0x50 || buf[off + 1] != 0x45) return null;
        int bodyLen = len - Hdr - Tag;
        byte[] h = mac.ComputeHash(buf, off, Hdr + bodyLen);
        int diff = 0;
        for (int i = 0; i < Tag; i++) diff |= h[i] ^ buf[off + Hdr + bodyLen + i];
        if (diff != 0) return null;
        type = buf[off + 2];
        node = PelBytes.ReadU64(buf, off + 3);
        seq = PelBytes.ReadU32(buf, off + 11);
        byte[] body = new byte[bodyLen];
        Ctr(node, seq, buf, off + Hdr, body, 0, bodyLen);
        return body;
    }
}

public sealed class PelP2pPeer
{
    public ulong NodeId;
    public string Name = "";
    public uint Vip;
    public IPEndPoint PublicEp;
    public List<IPEndPoint> LocalEps = new List<IPEndPoint>();
    public volatile IPEndPoint DirectEp;   // bestaetigter direkter Weg (nach Hole Punching)
    public volatile int Path;              // 0 = verbinde / punching, 1 = direkt, 2 = relay
    public long LastRxMs;
    public long LastHelloMs;
    public long LastRelayHelloMs;
    public long PunchStartMs;
    public volatile int RttMs = -1;
    public long RxBytes;
    public long TxBytes;
    public volatile int AuthFails;
    public volatile bool InServerList = true;
    public bool HasRev;          // Info kam ueber Erweiterung E2 (mit Revision)
    public uint InfoRev;         // Lobby-Revision dieser Info
    public bool Punching;        // Hole Punching hat tatsaechlich begonnen (fuer den Relay-Timer)
    // Replay-Schutz (Sliding Window, 64 Pakete)
    public bool AnySeq;
    public uint MaxSeq;
    public ulong Window;
}

public sealed class PelP2pPeerInfo
{
    public string Name;
    public string Ip;
    public string Mode;
    public string Endpoint;
    public int RttMs;
    public long RxBytes;
    public long TxBytes;
}

public sealed class PelP2pEngine
{
    // ---- Protokoll-Konstanten -------------------------------------------------
    public const byte ProtoVersion = 1;
    private const byte T_HELLO = 1, T_HELLO_ACK = 2, T_DATA = 4, T_BYE = 5;
    private const byte S_REGISTER = 0x10, S_LEAVE = 0x11, S_RELAY = 0x12;
    private const byte S_WELCOME = 0x20, S_PEER = 0x21, S_RELAYED = 0x22, S_ERROR = 0x23, S_MEMBERS = 0x24;
    private const byte S_SYNC = 0x25, S_PEER2 = 0x26, S_GONE = 0x27, EXT_V2 = 0xE2;
    private const int SIO_UDP_CONNRESET = -1744830452;
    // Hole Punching: hoechstens so viele Mitspieler je 200-ms-Takt anpingen (bei 500 Leuten in
    // einer Lobby wuerde sonst jeder neue Mitspieler seinen Upload und den Router fluten)
    public int PunchBudgetPerTick = 120;

    // ---- Einstellungen (vor Start() setzbar) ------------------------------------
    public int PreferredPort = 47800;      // fester Port = feste Firewall-Regel / optionale Portweiterleitung
    public bool AllowRelay = true;         // Fallback ueber den Vermittlungsserver bei symmetrischem NAT
    // Broadcast-Firewall: Hintergrund-"Laerm" von Windows, Linux und macOS (Namensdienste,
    // Geraetesuche, App-Suchfunktionen) wird weder gesendet noch angenommen. Laesst sich
    // zur Laufzeit per SetNoiseFilter() umstellen (GUI: "Broadcast-Firewall").
    private volatile HashSet<int> noisePorts = new HashSet<int>(new int[] { 5353, 5355, 137, 138, 1900, 3702, 67, 68, 17500, 57621, 1716, 21027, 427, 8611, 8612, 161 });
    private volatile bool noiseEnabled = true, noiseIgmp = true, noiseStrict = true;
    private readonly ConcurrentDictionary<int, long> noiseStats = new ConcurrentDictionary<int, long>();
    private long noiseBlocked;
    public long NoiseBlocked { get { return Interlocked.Read(ref noiseBlocked); } }
    public bool NoiseFilterEnabled { get { return noiseEnabled; } }

    public void SetNoiseFilter(bool enabled, int[] udpPorts, bool blockIgmp, bool strict)
    {
        HashSet<int> h = new HashSet<int>();
        if (udpPorts != null) foreach (int x in udpPorts) if (x > 0 && x < 65536) h.Add(x);
        noisePorts = h;
        noiseIgmp = blockIgmp;
        noiseStrict = strict;
        noiseEnabled = enabled;
    }

    public void ResetNoiseStats() { noiseStats.Clear(); Interlocked.Exchange(ref noiseBlocked, 0); }

    // "5353=120;137=40;-2=7" (-2 = IGMP), sortiert nach Anzahl
    public string GetNoiseStats()
    {
        List<KeyValuePair<int, long>> l = new List<KeyValuePair<int, long>>(noiseStats);
        l.Sort(delegate (KeyValuePair<int, long> a, KeyValuePair<int, long> b) { return b.Value.CompareTo(a.Value); });
        StringBuilder sb = new StringBuilder();
        foreach (KeyValuePair<int, long> kv in l) sb.Append(kv.Key).Append('=').Append(kv.Value).Append(';');
        return sb.ToString();
    }
    public int PunchTimeoutMs = 8000;      // so lange Hole Punching, bevor Relay genutzt wird
    public int PeerTimeoutMs = 20000;      // ohne Lebenszeichen -> Verbindung neu aufbauen

    // ---- Status (von PowerShell per Timer gelesen) ------------------------------
    private volatile string state = "Getrennt";
    public string State { get { return state; } }
    public volatile string LastError = "";
    public volatile string AssignedIp = "";
    public volatile int PrefixLength = 16;
    public volatile string PublicEndpoint = "";
    public volatile bool IpChanged = false;
    public volatile bool ServerReachable = false;
    public int LocalPort { get { return localPort; } }
    public bool IsRunning { get { return running; } }
    public string AdapterName { get { return adapterName; } }
    public int PeerCount { get { lock (sync) { return byNode.Count; } } }
    public readonly ConcurrentQueue<string> Log = new ConcurrentQueue<string>();

    // ---- intern -----------------------------------------------------------------
    private readonly object sync = new object();
    private readonly Dictionary<ulong, PelP2pPeer> byNode = new Dictionary<ulong, PelP2pPeer>();
    private readonly Dictionary<uint, PelP2pPeer> byVip = new Dictionary<uint, PelP2pPeer>();
    private static readonly Stopwatch clock = Stopwatch.StartNew();
    private Socket sock;
    private IntPtr adapter = IntPtr.Zero, session = IntPtr.Zero;
    private WaitHandle readEvent;
    private ManualResetEvent stopEvent;
    private Thread tunThread, udpThread, maintThread;
    private volatile bool stopping, running;
    private PelP2pCrypto cTun, cUdp, cMaint;
    private byte[] lobbyId, machineKey;
    private ulong nodeId;
    private string displayName = "", serverHost = "", adapterName = "PEL-P2P";
    private int serverPort, localPort;
    private volatile IPEndPoint serverEp;
    private long lastResolveMs = -1000000, lastRegTxMs = -1000000, lastServerRxMs = 0;
    private volatile bool gotWelcome;
    private long lastGoneCleanMs;
    private volatile uint vip, mask, bcast;
    private int seqCounter;
    private byte[] cookie = new byte[8];                 // Anti-Spoofing-Cookie vom Server
    // Erweiterung E2: Abgleich der Mitgliederliste (nur im Empfangs-Thread benutzt)
    private uint syncRev;
    private int syncTotal;
    private readonly HashSet<ulong> syncIds = new HashSet<ulong>();
    private readonly Dictionary<ulong, KeyValuePair<uint, long>> gone = new Dictionary<ulong, KeyValuePair<uint, long>>();

    private static long Now() { return clock.ElapsedMilliseconds; }

    private void AddLog(string text)
    {
        Log.Enqueue(DateTime.Now.ToString("HH:mm:ss") + "  " + text);
        string dummy;
        while (Log.Count > 400 && Log.TryDequeue(out dummy)) { }
    }

    private void SetState(string s) { if (state != s) { state = s; AddLog("Status: " + s); } }

    private uint NextSeq() { return (uint)Interlocked.Increment(ref seqCounter); }

    // Lobby-Schluessel: PBKDF2 (100.000 Runden) aus Passwort + Lobbyname.
    // Der Server sieht nur die LobbyId (Hash des Namens) - nie Passwort oder Schluessel.
    public static byte[] DeriveLobbyId(string lobbyName)
    {
        using (SHA256 sha = SHA256.Create())
        {
            byte[] h = sha.ComputeHash(Encoding.UTF8.GetBytes("PEL-LOBBY-V1|" + lobbyName.Trim().ToLowerInvariant()));
            byte[] id = new byte[16];
            Buffer.BlockCopy(h, 0, id, 0, 16);
            return id;
        }
    }

    // =========================================================================
    // START
    // =========================================================================
    public void Start(string serverHostName, int serverUdpPort, string lobbyName, string password,
                      string myName, string machineKeyHex, string wintunDllPath, string tunAdapterName)
    {
        if (running) throw new InvalidOperationException("P2P laeuft bereits.");
        if (string.IsNullOrEmpty(lobbyName) || lobbyName.Trim().Length < 3) throw new ArgumentException("Der Lobby-Name muss mindestens 3 Zeichen haben.");
        if (string.IsNullOrEmpty(password) || password.Length < 6) throw new ArgumentException("Das Lobby-Passwort muss mindestens 6 Zeichen haben.");
        if (string.IsNullOrEmpty(serverHostName)) throw new ArgumentException("Kein Vermittlungsserver eingetragen.");

        stopping = false; gotWelcome = false; ServerReachable = false; IpChanged = false;
        vip = 0; mask = 0; bcast = 0; AssignedIp = ""; PublicEndpoint = ""; LastError = "";
        lastResolveMs = -1000000; lastRegTxMs = -1000000; lastServerRxMs = 0; serverEp = null;
        cookie = new byte[8];
        lock (sync) { byNode.Clear(); byVip.Clear(); }

        serverHost = serverHostName.Trim(); serverPort = serverUdpPort;
        displayName = string.IsNullOrEmpty(myName) ? Environment.MachineName : myName;
        adapterName = string.IsNullOrEmpty(tunAdapterName) ? "PEL-P2P" : tunAdapterName;

        // Schluessel ableiten
        SetState("Schluessel werden abgeleitet ...");
        lobbyId = DeriveLobbyId(lobbyName);
        byte[] salt = Encoding.UTF8.GetBytes("PEL-P2P-V1|" + lobbyName.Trim().ToLowerInvariant());
        byte[] km;
        using (Rfc2898DeriveBytes kdf = new Rfc2898DeriveBytes(password, salt, 100000)) { km = kdf.GetBytes(64); }
        byte[] encKey = new byte[32], macKey = new byte[32];
        Buffer.BlockCopy(km, 0, encKey, 0, 32);
        Buffer.BlockCopy(km, 32, macKey, 0, 32);
        cTun = new PelP2pCrypto(encKey, macKey);
        cUdp = new PelP2pCrypto(encKey, macKey);
        cMaint = new PelP2pCrypto(encKey, macKey);

        machineKey = new byte[16];
        if (!string.IsNullOrEmpty(machineKeyHex) && machineKeyHex.Length == 32)
        {
            for (int i = 0; i < 16; i++) machineKey[i] = Convert.ToByte(machineKeyHex.Substring(i * 2, 2), 16);
        }
        byte[] rnd = new byte[8];
        using (RandomNumberGenerator rng = RandomNumberGenerator.Create())
        {
            do { rng.GetBytes(rnd); nodeId = PelBytes.ReadU64(rnd, 0); } while (nodeId == 0);
            if (string.IsNullOrEmpty(machineKeyHex)) rng.GetBytes(machineKey);
            byte[] s4 = new byte[4]; rng.GetBytes(s4); seqCounter = (int)(PelBytes.ReadU32(s4, 0) & 0x0FFFFFFF);
        }

        // Wintun-Adapter anlegen
        SetState("Virtueller Adapter wird erstellt ...");
        PelWintun.Load(wintunDllPath);
        Guid g = new Guid("5045ab12-3c4d-4e50-9a2b-50454c503250"); // fest -> Windows erkennt das Netz wieder
        adapter = PelWintun.WintunCreateAdapter(adapterName, "Project Earth P2P", ref g);
        if (adapter == IntPtr.Zero)
        {
            int e1 = Marshal.GetLastWin32Error();
            adapter = PelWintun.WintunOpenAdapter(adapterName);
            if (adapter == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(e1, "Wintun-Adapter konnte nicht erstellt werden (Admin-Rechte?)");
        }
        session = PelWintun.WintunStartSession(adapter, 0x400000);
        if (session == IntPtr.Zero)
        {
            int e2 = Marshal.GetLastWin32Error();
            PelWintun.WintunCloseAdapter(adapter); adapter = IntPtr.Zero;
            throw new System.ComponentModel.Win32Exception(e2, "Wintun-Sitzung konnte nicht gestartet werden");
        }
        readEvent = new PelNativeWaitHandle(PelWintun.WintunGetReadWaitEvent(session));
        stopEvent = new ManualResetEvent(false);

        // UDP-Socket (ein Socket fuer Server UND alle Peers -> gleiche NAT-Zuordnung)
        try
        {
            sock = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
            try { sock.IOControl(SIO_UDP_CONNRESET, new byte[] { 0, 0, 0, 0 }, null); } catch { }
            try { sock.Bind(new IPEndPoint(IPAddress.Any, PreferredPort)); }
            catch (SocketException)
            {
                AddLog("UDP-Port " + PreferredPort + " ist belegt - nutze einen zufaelligen Port.");
                sock.Bind(new IPEndPoint(IPAddress.Any, 0));
            }
            sock.ReceiveTimeout = 1000;
            sock.ReceiveBufferSize = 1 << 20;
            sock.SendBufferSize = 1 << 20;
            localPort = ((IPEndPoint)sock.LocalEndPoint).Port;
        }
        catch
        {
            CleanupNative();
            throw;
        }

        running = true;
        AddLog("Lokaler UDP-Port: " + localPort + ", Adapter: " + adapterName + ", Wintun-Treiber " + DriverVersion());
        SetState("Verbinde mit Vermittlungsserver ...");
        tunThread = new Thread(TunLoop); tunThread.IsBackground = true; tunThread.Name = "PEL-P2P-TUN"; tunThread.Start();
        udpThread = new Thread(UdpLoop); udpThread.IsBackground = true; udpThread.Name = "PEL-P2P-UDP"; udpThread.Start();
        maintThread = new Thread(MaintLoop); maintThread.IsBackground = true; maintThread.Name = "PEL-P2P-MAINT"; maintThread.Start();
    }

    private static string DriverVersion()
    {
        try { uint v = PelWintun.WintunGetRunningDriverVersion(); return (v >> 16) + "." + (v & 0xFFFF); } catch { return "?"; }
    }

    // =========================================================================
    // STOP
    // =========================================================================
    public void Stop()
    {
        if (!running) return;
        stopping = true;
        try { stopEvent.Set(); } catch { }
        if (maintThread != null) maintThread.Join(3000);
        // Abmelden: Peers und Server sofort informieren (sonst erst nach Timeout)
        try
        {
            byte[] empty = new byte[0];
            foreach (PelP2pPeer p in SnapshotPeers())
            {
                byte[] bye = cMaint.Seal(T_BYE, nodeId, NextSeq(), empty, 0, 0);
                IPEndPoint d = p.DirectEp;
                if (p.Path == 1 && d != null) SendRaw(bye, d);
                else if (p.Path == 2) SendRelay(p.NodeId, bye);
            }
            IPEndPoint se = serverEp;
            if (se != null)
            {
                byte[] lv = new byte[3 + 16 + 8];
                lv[0] = 0x50; lv[1] = 0x53; lv[2] = S_LEAVE;
                Buffer.BlockCopy(lobbyId, 0, lv, 3, 16);
                PelBytes.WriteU64(lv, 19, nodeId);
                SendRaw(lv, se);
            }
        }
        catch { }
        try { sock.Close(); } catch { }
        if (udpThread != null) udpThread.Join(3000);
        if (tunThread != null) tunThread.Join(3000);
        CleanupNative();
        running = false;
        ServerReachable = false;
        AssignedIp = "";
        lock (sync) { byNode.Clear(); byVip.Clear(); }
        SetState("Getrennt");
    }

    private void CleanupNative()
    {
        try { if (session != IntPtr.Zero) PelWintun.WintunEndSession(session); } catch { }
        session = IntPtr.Zero;
        // Adapter aus WintunCreateAdapter wird beim Schliessen automatisch wieder entfernt.
        try { if (adapter != IntPtr.Zero) PelWintun.WintunCloseAdapter(adapter); } catch { }
        adapter = IntPtr.Zero;
    }

    // =========================================================================
    // THREAD 1: virtueller Adapter -> UDP (ausgehender Spiel-Traffic)
    // =========================================================================
    private void TunLoop()
    {
        WaitHandle[] handles = new WaitHandle[] { readEvent, stopEvent };
        while (!stopping)
        {
            uint size;
            IntPtr pkt = PelWintun.WintunReceivePacket(session, out size);
            if (pkt == IntPtr.Zero)
            {
                int err = Marshal.GetLastWin32Error();
                if (err == 259) { WaitHandle.WaitAny(handles, 500); continue; }           // ERROR_NO_MORE_ITEMS
                if (err == 38) { if (!stopping) { LastError = "Virtueller Adapter wurde beendet."; SetState("Fehler: Adapter beendet"); } break; } // ERROR_HANDLE_EOF
                Thread.Sleep(20);
                continue;
            }
            byte[] data = new byte[size];
            Marshal.Copy(pkt, data, 0, (int)size);
            PelWintun.WintunReleaseReceivePacket(session, pkt);
            try { RouteOutbound(data); }
            catch (Exception ex) { AddLog("TUN-Fehler: " + ex.Message); }
        }
    }

    private void CountNoise(int key)
    {
        Interlocked.Increment(ref noiseBlocked);
        noiseStats.AddOrUpdate(key, 1, delegate (int k, long v) { return v + 1; });
    }

    // multi = Ziel ist Broadcast/Multicast. Im strengen Modus werden die Dienste auch als
    // direkte Pakete (Anfragen UND Antworten, also Quell- oder Zielport) geblockt.
    private bool IsNoise(byte[] p, bool multi)
    {
        if (!noiseEnabled) return false;
        byte proto = p[9];
        if (proto == 2) { if (noiseIgmp) { CountNoise(-2); return true; } return false; }   // IGMP
        if (proto != 17) return false;
        if (!multi && !noiseStrict) return false;
        int ihl = (p[0] & 15) * 4;
        if (p.Length < ihl + 4) return true;
        int sport = PelBytes.ReadU16(p, ihl);
        int dport = PelBytes.ReadU16(p, ihl + 2);
        HashSet<int> set = noisePorts;
        if (set.Contains(dport)) { CountNoise(dport); return true; }
        if (noiseStrict && set.Contains(sport)) { CountNoise(sport); return true; }
        return false;
    }

    private void RouteOutbound(byte[] p)
    {
        if (p.Length < 20 || (p[0] >> 4) != 4) return;                // nur IPv4
        uint my = vip;
        if (my == 0) return;
        uint dst = PelBytes.ReadU32(p, 16);
        bool multi = dst == 0xFFFFFFFF || dst == bcast || (dst >> 28) == 0xE;
        if (IsNoise(p, multi)) return;
        if (multi)
        {
            // Broadcast/Multicast (Server-Browser, LAN-Suche) an ALLE verbundenen Peers
            foreach (PelP2pPeer peer in SnapshotPeers()) if (peer.Path != 0) SendData(peer, p);
            return;
        }
        if ((dst & mask) != (my & mask)) return;
        PelP2pPeer target;
        lock (sync) { byVip.TryGetValue(dst, out target); }
        if (target == null || target.Path == 0) return;                // noch nicht verbunden -> verwerfen (Spiel wiederholt)
        SendData(target, p);
    }

    private void SendData(PelP2pPeer peer, byte[] ipPacket)
    {
        byte[] wire = cTun.Seal(T_DATA, nodeId, NextSeq(), ipPacket, 0, ipPacket.Length);
        IPEndPoint d = peer.DirectEp;
        if (peer.Path == 1 && d != null) SendRaw(wire, d);
        else if (peer.Path == 2) SendRelay(peer.NodeId, wire);
        else return;
        Interlocked.Add(ref peer.TxBytes, ipPacket.Length);
    }

    private void SendRaw(byte[] data, IPEndPoint ep)
    {
        try { sock.SendTo(data, ep); } catch (ObjectDisposedException) { } catch (SocketException) { }
    }

    private void SendRelay(ulong toNode, byte[] wire)
    {
        IPEndPoint se = serverEp;
        if (se == null || !AllowRelay) return;
        byte[] r = new byte[3 + 16 + 8 + 8 + wire.Length];
        r[0] = 0x50; r[1] = 0x53; r[2] = S_RELAY;
        Buffer.BlockCopy(lobbyId, 0, r, 3, 16);
        PelBytes.WriteU64(r, 19, nodeId);
        PelBytes.WriteU64(r, 27, toNode);
        Buffer.BlockCopy(wire, 0, r, 35, wire.Length);
        SendRaw(r, se);
    }

    // =========================================================================
    // THREAD 2: UDP -> virtueller Adapter (eingehend) + Server-Nachrichten
    // =========================================================================
    private void UdpLoop()
    {
        byte[] buf = new byte[65536];
        while (!stopping)
        {
            EndPoint from = new IPEndPoint(IPAddress.Any, 0);
            int n;
            try { n = sock.ReceiveFrom(buf, ref from); }
            catch (ObjectDisposedException) { break; }
            catch (SocketException se)
            {
                if (stopping) break;
                if (se.SocketErrorCode == SocketError.TimedOut || se.SocketErrorCode == SocketError.ConnectionReset || se.SocketErrorCode == SocketError.MessageSize) continue;
                AddLog("UDP-Fehler: " + se.SocketErrorCode);
                Thread.Sleep(50);
                continue;
            }
            if (n < 3) continue;
            IPEndPoint ep = (IPEndPoint)from;
            try
            {
                if (buf[0] == 0x50 && buf[1] == 0x53)
                {
                    IPEndPoint se2 = serverEp;
                    if (se2 != null && se2.Equals(ep)) HandleServer(buf, n, ep);
                }
                else if (buf[0] == 0x50 && buf[1] == 0x45)
                {
                    HandlePeerPacket(buf, 0, n, ep, false);
                }
            }
            catch (Exception ex) { AddLog("Paketfehler: " + ex.Message); }
        }
    }

    private bool ReplayOk(PelP2pPeer p, uint seq)
    {
        lock (p)
        {
            if (!p.AnySeq) { p.AnySeq = true; p.MaxSeq = seq; p.Window = 1UL; return true; }
            if (seq > p.MaxSeq)
            {
                uint d = seq - p.MaxSeq;
                p.Window = d >= 64 ? 1UL : ((p.Window << (int)d) | 1UL);
                p.MaxSeq = seq;
                return true;
            }
            uint back = p.MaxSeq - seq;
            if (back >= 64) return false;
            ulong bit = 1UL << (int)back;
            if ((p.Window & bit) != 0) return false;
            p.Window |= bit;
            return true;
        }
    }

    private void HandlePeerPacket(byte[] buf, int off, int len, IPEndPoint ep, bool viaRelay)
    {
        if (len < PelP2pCrypto.Hdr + PelP2pCrypto.Tag) return;
        ulong sender = PelBytes.ReadU64(buf, off + 3);
        if (sender == nodeId) return;
        PelP2pPeer p;
        lock (sync) { byNode.TryGetValue(sender, out p); }
        if (p == null) return;                                          // (noch) nicht in der Lobby-Liste
        byte type; ulong node; uint seq;
        byte[] body = cUdp.Open(buf, off, len, out type, out node, out seq);
        if (body == null)
        {
            int f = ++p.AuthFails;
            if (f == 5) AddLog("Pakete von " + p.Name + " lassen sich nicht pruefen - anderes Lobby-Passwort?");
            return;
        }
        if (!ReplayOk(p, seq)) return;
        p.AuthFails = 0;
        Interlocked.Exchange(ref p.LastRxMs, Now());

        if (!viaRelay)
        {
            IPEndPoint cur = p.DirectEp;
            if (p.Path != 1 || cur == null)
            {
                p.DirectEp = ep;
                p.Path = 1;
                AddLog("Direktverbindung (Hole Punching) mit " + p.Name + " ueber " + ep);
            }
            else if (!cur.Equals(ep) && (PelBytes.IsPrivate(ep.Address) || !PelBytes.IsPrivate(cur.Address)))
            {
                // Roaming / besserer Weg (z. B. gleiches Heimnetz statt Umweg ueber die Public-IP)
                p.DirectEp = ep;
                AddLog("Weg zu " + p.Name + " gewechselt -> " + ep);
            }
        }
        else if (p.Path == 0)
        {
            p.Path = 2;
            AddLog("Verbindung mit " + p.Name + " laeuft ueber Relay (Vermittlungsserver).");
        }

        switch (type)
        {
            case T_HELLO:
                if (body.Length >= 16 && PelBytes.ReadU64(body, 0) == nodeId)
                {
                    byte[] ack = new byte[16];
                    PelBytes.WriteU64(ack, 0, sender);
                    Buffer.BlockCopy(body, 8, ack, 8, 8);
                    byte[] w = cUdp.Seal(T_HELLO_ACK, nodeId, NextSeq(), ack, 0, 16);
                    if (viaRelay) SendRelay(sender, w); else SendRaw(w, ep);
                }
                break;
            case T_HELLO_ACK:
                if (body.Length >= 16 && PelBytes.ReadU64(body, 0) == nodeId)
                {
                    long rtt = Now() - (long)PelBytes.ReadU64(body, 8);
                    if (rtt >= 0 && rtt < 10000) p.RttMs = (int)rtt;
                }
                break;
            case T_DATA:
                DeliverInbound(p, body);
                break;
            case T_BYE:
                p.Path = 0; p.DirectEp = null; p.InServerList = false;
                AddLog(p.Name + " hat die Lobby verlassen.");
                break;
        }
    }

    private void DeliverInbound(PelP2pPeer p, byte[] ip)
    {
        if (ip.Length < 20 || (ip[0] >> 4) != 4) return;
        uint src = PelBytes.ReadU32(ip, 12);
        uint dst = PelBytes.ReadU32(ip, 16);
        if (src != p.Vip) return;                                       // Anti-Spoofing: nur die eigene virtuelle IP des Peers
        uint my = vip;
        bool multiIn = dst == 0xFFFFFFFF || dst == bcast || (dst >> 28) == 0xE;
        if (!(dst == my || multiIn)) return;
        if (IsNoise(ip, multiIn)) return;                               // auch eingehend (aeltere Manager-Versionen)
        IntPtr s = session;
        if (s == IntPtr.Zero || stopping) return;
        IntPtr buf = PelWintun.WintunAllocateSendPacket(s, (uint)ip.Length);
        if (buf == IntPtr.Zero) return;                                 // Ring voll -> verwerfen (wie echtes LAN)
        Marshal.Copy(ip, 0, buf, ip.Length);
        PelWintun.WintunSendPacket(s, buf);
        Interlocked.Add(ref p.RxBytes, ip.Length);
    }

    // =========================================================================
    // Signaling: Nachrichten vom Vermittlungsserver
    // =========================================================================
    private static IPEndPoint ReadEp(byte[] b, int o)
    {
        byte[] a = new byte[4];
        Buffer.BlockCopy(b, o, a, 0, 4);
        return new IPEndPoint(new IPAddress(a), PelBytes.ReadU16(b, o + 4));
    }

    private void HandleServer(byte[] b, int n, IPEndPoint ep)
    {
        Interlocked.Exchange(ref lastServerRxMs, Now());
        if (!ServerReachable) { ServerReachable = true; if (gotWelcome) SetState("Verbunden"); }
        byte t = b[2];
        if (t == S_WELCOME && n >= 3 + 4 + 6 + 1 + 8)
        {
            uint newVip = PelBytes.ReadU32(b, 3);
            IPEndPoint pub = ReadEp(b, 7);
            int prefix = b[13];
            byte[] ck = new byte[8];
            Buffer.BlockCopy(b, 14, ck, 0, 8);
            cookie = ck;
            if (newVip == 0)
            {
                // Erste Antwort: nur Cookie (beweist, dass wir unter dieser Adresse erreichbar
                // sind - Schutz gegen gefaelschte Absender). Sofort erneut registrieren.
                Interlocked.Exchange(ref lastRegTxMs, -1000000);
                return;
            }
            if (prefix < 8 || prefix > 30) prefix = 16;
            uint m = prefix == 0 ? 0 : 0xFFFFFFFF << (32 - prefix);
            PublicEndpoint = pub.ToString();
            if (newVip != vip || m != mask)
            {
                mask = m; bcast = (newVip & m) | ~m; vip = newVip;
                PrefixLength = prefix;
                AssignedIp = PelBytes.IpToString(newVip);
                IpChanged = true;
                AddLog("Virtuelle IP zugewiesen: " + AssignedIp + "/" + prefix + " (oeffentlich sichtbar als " + PublicEndpoint + ")");
            }
            gotWelcome = true;
            SetState("Verbunden");
        }
        else if (t == S_PEER && n >= 3 + 8 + 4 + 6 + 2)
        {
            ApplyPeer(b, n, 3, false, 0);
        }
        else if (t == S_PEER2 && n >= 8 + 8 + 4 + 6 + 2)
        {
            ApplyPeer(b, n, 8, true, PelBytes.ReadU32(b, 4));
        }
        else if (t == S_GONE && n >= 15)
        {
            uint rev = PelBytes.ReadU32(b, 3);
            ulong nid = PelBytes.ReadU64(b, 7);
            lock (sync)
            {
                gone[nid] = new KeyValuePair<uint, long>(rev, Now());
                PelP2pPeer p;
                if (byNode.TryGetValue(nid, out p) && (!p.HasRev || !Newer(p.InfoRev, rev))) p.InServerList = false;
            }
        }
        else if (t == S_SYNC && n >= 12)
        {
            uint rev = PelBytes.ReadU32(b, 3);
            int total = PelBytes.ReadU16(b, 7);
            int cnt = b[11];
            if (rev != syncRev || syncTotal != total) { syncRev = rev; syncTotal = total; syncIds.Clear(); }
            for (int i = 0; i < cnt && 12 + i * 8 + 8 <= n; i++) syncIds.Add(PelBytes.ReadU64(b, 12 + i * 8));
            if (syncIds.Count >= syncTotal)
            {
                lock (sync)
                {
                    foreach (PelP2pPeer p in byNode.Values)
                    {
                        KeyValuePair<uint, long> g;
                        bool goneLater = gone.TryGetValue(p.NodeId, out g) && Newer(g.Key, rev);
                        if (syncIds.Contains(p.NodeId)) { if (!goneLater) p.InServerList = true; }
                        else if (!p.HasRev || !Newer(p.InfoRev, rev)) p.InServerList = false;
                    }
                }
                syncIds.Clear(); syncTotal = -1;
            }
        }
        else if (t == S_MEMBERS && n >= 4)
        {
            int cnt = b[3];
            HashSet<ulong> set = new HashSet<ulong>();
            for (int i = 0; i < cnt && 4 + i * 8 + 8 <= n; i++) set.Add(PelBytes.ReadU64(b, 4 + i * 8));
            lock (sync) { foreach (PelP2pPeer p in byNode.Values) p.InServerList = set.Contains(p.NodeId); }
        }
        else if (t == S_RELAYED && n >= 3 + 8 + PelP2pCrypto.Hdr + PelP2pCrypto.Tag)
        {
            ulong from = PelBytes.ReadU64(b, 3);
            if (PelBytes.ReadU64(b, 11 + 3) != from) return;            // Absender im Paket muss zum Relay-Absender passen
            HandlePeerPacket(b, 11, n - 11, ep, true);
        }
        else if (t == S_ERROR && n >= 5)
        {
            int ml = Math.Min(b[4], n - 5);
            string msg = Encoding.UTF8.GetString(b, 5, ml);
            LastError = msg;
            SetState("Fehler: " + msg);
        }
    }

    // Mitspieler-Info aus PEER (alt) bzw. PEER2 (mit Revision) uebernehmen
    private void ApplyPeer(byte[] b, int n, int start, bool withRev, uint rev)
    {
        {
            int o = start;
            ulong nid = PelBytes.ReadU64(b, o); o += 8;
            uint pv = PelBytes.ReadU32(b, o); o += 4;
            IPEndPoint pub = ReadEp(b, o); o += 6;
            int nl = b[o++];
            if (o + nl + 1 > n) return;
            string nm = Encoding.UTF8.GetString(b, o, nl); o += nl;
            int cnt = b[o++];
            List<IPEndPoint> locals = new List<IPEndPoint>();
            for (int i = 0; i < cnt && o + 6 <= n; i++) { locals.Add(ReadEp(b, o)); o += 6; }
            if (nid == nodeId) return;
            bool isNew = false;
            lock (sync)
            {
                if (withRev)
                {
                    KeyValuePair<uint, long> g;
                    if (gone.TryGetValue(nid, out g))
                    {
                        if (!Newer(rev, g.Key)) return;             // verspaetete Info ueber jemanden, der schon weg ist
                        gone.Remove(nid);
                    }
                }
                PelP2pPeer p;
                if (byNode.TryGetValue(nid, out p) && withRev && p.HasRev && Newer(p.InfoRev, rev)) return;   // aeltere Info
                if (p == null)
                {
                    p = new PelP2pPeer();
                    p.NodeId = nid;
                    p.PunchStartMs = Now();
                    byNode[nid] = p;
                    isNew = true;
                }
                if (p.Vip != pv)
                {
                    PelP2pPeer old;
                    if (p.Vip != 0 && byVip.TryGetValue(p.Vip, out old) && old == p) byVip.Remove(p.Vip);
                    p.Vip = pv;
                    byVip[pv] = p;
                }
                p.Name = nm;
                p.PublicEp = pub;
                p.LocalEps = locals;
                p.InServerList = true;
                if (withRev) { p.HasRev = true; p.InfoRev = rev; }
            }
            if (isNew) AddLog("Mitspieler in der Lobby: " + nm + " (" + PelBytes.IpToString(pv) + ") - starte Hole Punching an " + pub);
        }
    }

    private List<IPEndPoint> GetLocalCandidates()
    {
        List<IPEndPoint> list = new List<IPEndPoint>();
        try
        {
            foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
            {
                if (ni.OperationalStatus != OperationalStatus.Up) continue;
                if (ni.NetworkInterfaceType == NetworkInterfaceType.Loopback) continue;
                if (string.Equals(ni.Name, adapterName, StringComparison.OrdinalIgnoreCase)) continue;
                foreach (UnicastIPAddressInformation ua in ni.GetIPProperties().UnicastAddresses)
                {
                    if (ua.Address.AddressFamily != AddressFamily.InterNetwork) continue;
                    byte[] a = ua.Address.GetAddressBytes();
                    if (a[0] == 169 && a[1] == 254) continue;
                    uint u = PelBytes.IpToUInt(ua.Address);
                    if (mask != 0 && (u & mask) == (vip & mask)) continue;
                    list.Add(new IPEndPoint(ua.Address, localPort));
                    if (list.Count >= 6) return list;
                }
            }
        }
        catch { }
        return list;
    }

    private void SendRegister()
    {
        IPEndPoint se = serverEp;
        if (se == null) return;
        byte[] nm = PelBytes.Utf8Limit(displayName, 32);
        List<IPEndPoint> locals = GetLocalCandidates();
        byte[] p = new byte[4 + 16 + 8 + 16 + 1 + nm.Length + 1 + locals.Count * 6 + 8 + 9];
        p[0] = 0x50; p[1] = 0x53; p[2] = S_REGISTER; p[3] = ProtoVersion;
        Buffer.BlockCopy(lobbyId, 0, p, 4, 16);
        PelBytes.WriteU64(p, 20, nodeId);
        Buffer.BlockCopy(machineKey, 0, p, 28, 16);
        int o = 44;
        p[o++] = (byte)nm.Length;
        Buffer.BlockCopy(nm, 0, p, o, nm.Length); o += nm.Length;
        p[o++] = (byte)locals.Count;
        foreach (IPEndPoint l in locals)
        {
            Buffer.BlockCopy(l.Address.GetAddressBytes(), 0, p, o, 4);
            PelBytes.WriteU16(p, o + 4, l.Port);
            o += 6;
        }
        Buffer.BlockCopy(cookie, 0, p, o, 8);
        // Erweiterung E2: eigener Stand der Mitgliederliste (alte Server ignorieren das)
        p[o + 8] = EXT_V2;
        PelBytes.WriteU64(p, o + 9, ListDigest());
        SendRaw(p, se);
    }

    private static ulong Mix(ulong nid, uint rev)
    {
        ulong z = nid ^ ((ulong)rev * 0x9E3779B97F4A7C15UL);
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        return z ^ (z >> 31);
    }

    private static bool Newer(uint a, uint b) { return (int)(a - b) > 0; }

    private ulong ListDigest()
    {
        ulong d = 0;
        lock (sync) { foreach (PelP2pPeer p in byNode.Values) if (p.HasRev && p.InServerList) d ^= Mix(p.NodeId, p.InfoRev); }
        return d;
    }

    private void SendHello(PelP2pPeer p, IPEndPoint ep, bool viaRelay)
    {
        byte[] body = new byte[16];
        PelBytes.WriteU64(body, 0, p.NodeId);
        PelBytes.WriteU64(body, 8, (ulong)Now());
        byte[] w = cMaint.Seal(T_HELLO, nodeId, NextSeq(), body, 0, 16);
        if (viaRelay) SendRelay(p.NodeId, w); else SendRaw(w, ep);
    }

    // =========================================================================
    // THREAD 3: Wartung - Registrierung, Hole Punching, Keepalive, Timeouts
    // =========================================================================
    private void MaintLoop()
    {
        while (!stopping)
        {
            try { MaintTick(); }
            catch (Exception ex) { AddLog("Wartungsfehler: " + ex.Message); }
            if (stopEvent.WaitOne(200)) break;
        }
    }

    private void MaintTick()
    {
        long now = Now();

        // DNS des Servers alle 5 Minuten neu aufloesen (DynDNS-tauglich)
        if (serverEp == null || now - lastResolveMs > 300000)
        {
            lastResolveMs = now;
            try
            {
                IPAddress ip = null;
                if (!IPAddress.TryParse(serverHost, out ip))
                {
                    foreach (IPAddress a in Dns.GetHostAddresses(serverHost))
                        if (a.AddressFamily == AddressFamily.InterNetwork) { ip = a; break; }
                }
                if (ip != null)
                {
                    IPEndPoint ne = new IPEndPoint(ip, serverPort);
                    if (serverEp == null || !serverEp.Equals(ne)) { serverEp = ne; AddLog("Vermittlungsserver: " + ne); }
                }
                else if (serverEp == null) SetState("Fehler: Server-Adresse nicht aufloesbar");
            }
            catch (Exception ex) { if (serverEp == null) SetState("Fehler: Server nicht aufloesbar (" + ex.Message + ")"); }
        }

        // Registrierung / Keepalive beim Server (anfangs schnell, dann alle 10 s)
        long sinceSrv = now - Interlocked.Read(ref lastServerRxMs);
        int regInterval = (gotWelcome && ServerReachable) ? 10000 : 2000;
        if (now - Interlocked.Read(ref lastRegTxMs) >= regInterval) { Interlocked.Exchange(ref lastRegTxMs, now); SendRegister(); }
        if (ServerReachable && sinceSrv > 35000)
        {
            ServerReachable = false;
            SetState(gotWelcome ? "Server nicht erreichbar - bestehende Direktverbindungen bleiben aktiv" : "Verbinde mit Vermittlungsserver ...");
        }

        if (!gotWelcome) return;                                        // ohne eigene IP kein Punching

        // Alte "ist weg"-Merker aufraeumen (nur gegen verspaetete Pakete noetig)
        if (gone.Count > 0 && now - lastGoneCleanMs > 30000)
        {
            lastGoneCleanMs = now;
            lock (sync)
            {
                List<ulong> old = new List<ulong>();
                foreach (KeyValuePair<ulong, KeyValuePair<uint, long>> kv in gone) if (now - kv.Value.Value > 120000) old.Add(kv.Key);
                foreach (ulong id in old) gone.Remove(id);
            }
        }

        int budget = PunchBudgetPerTick;
        foreach (PelP2pPeer p in SnapshotPeers())
        {
            long lastRx = Interlocked.Read(ref p.LastRxMs);

            if (p.Path != 0 && lastRx > 0 && now - lastRx > PeerTimeoutMs)
            {
                AddLog("Keine Antwort mehr von " + p.Name + " - baue Verbindung neu auf.");
                p.Path = 0; p.DirectEp = null; p.PunchStartMs = now; p.RttMs = -1; p.Punching = false;
            }

            if (p.Path == 1)
            {
                // Keepalive haelt das NAT-Loch offen (typische UDP-Timeouts: 30-120 s)
                IPEndPoint d = p.DirectEp;
                if (d != null && now - p.LastHelloMs >= 5000) { p.LastHelloMs = now; SendHello(p, d, false); }
            }
            else
            {
                // UDP Hole Punching: beide Seiten senden gleichzeitig an alle bekannten
                // Adressen des anderen -> beide NATs legen eine Zuordnung an, das erste
                // authentifizierte Paket bestaetigt den direkten Weg.
                if (!p.Punching)
                {
                    if (budget <= 0) continue;                          // kommt im naechsten Takt dran
                    p.Punching = true; p.PunchStartMs = now;
                }
                long since = now - p.PunchStartMs;
                int iv = since < 10000 ? 250 : 2000;
                if (now - p.LastHelloMs >= iv && budget > 0)
                {
                    budget--;
                    p.LastHelloMs = now;
                    if (p.PublicEp != null) SendHello(p, p.PublicEp, false);
                    List<IPEndPoint> locals = p.LocalEps;
                    if (locals != null) foreach (IPEndPoint l in locals) SendHello(p, l, false);
                }
                if (p.Path == 0 && since > PunchTimeoutMs && AllowRelay && ServerReachable)
                {
                    p.Path = 2;
                    AddLog("Kein direkter Weg zu " + p.Name + " (symmetrisches NAT?) - nutze Relay ueber den Vermittlungsserver.");
                }
                if (p.Path == 2 && now - p.LastRelayHelloMs >= 2000) { p.LastRelayHelloMs = now; SendHello(p, null, true); }
            }

            if (!p.InServerList && (lastRx == 0 || now - lastRx > 15000))
            {
                lock (sync)
                {
                    byNode.Remove(p.NodeId);
                    PelP2pPeer cur;
                    if (byVip.TryGetValue(p.Vip, out cur) && cur == p) byVip.Remove(p.Vip);
                }
                AddLog(p.Name + " ist nicht mehr in der Lobby.");
            }
        }
    }

    private List<PelP2pPeer> SnapshotPeers()
    {
        lock (sync) { return new List<PelP2pPeer>(byNode.Values); }
    }

    // Fuer die GUI (Timer im Control Center)
    public PelP2pPeerInfo[] GetPeers()
    {
        List<PelP2pPeerInfo> r = new List<PelP2pPeerInfo>();
        foreach (PelP2pPeer p in SnapshotPeers())
        {
            PelP2pPeerInfo i = new PelP2pPeerInfo();
            i.Name = p.Name;
            i.Ip = PelBytes.IpToString(p.Vip);
            IPEndPoint d = p.DirectEp;
            if (p.Path == 1) { i.Mode = "Direkt"; i.Endpoint = d == null ? "" : d.ToString(); }
            else if (p.Path == 2) { i.Mode = "Relay"; i.Endpoint = "ueber Server"; }
            else { i.Mode = p.AuthFails >= 5 ? "Passwort falsch?" : "Verbinde ..."; i.Endpoint = p.PublicEp == null ? "" : p.PublicEp.ToString(); }
            i.RttMs = p.Path == 0 ? -1 : p.RttMs;
            i.RxBytes = Interlocked.Read(ref p.RxBytes);
            i.TxBytes = Interlocked.Read(ref p.TxBytes);
            r.Add(i);
        }
        r.Sort(delegate (PelP2pPeerInfo a, PelP2pPeerInfo b2) { return string.Compare(a.Name, b2.Name, StringComparison.OrdinalIgnoreCase); });
        return r.ToArray();
    }
}
'@

function Initialize-PelP2pTypes {
    if (-not ('PelP2pEngine' -as [type])) { Add-Type -TypeDefinition $script:PelP2pCode -Language CSharp }
}

# Innerste Fehlermeldung (bei .NET-Methodenaufrufen steckt die echte Meldung in der
# InnerException, außen steht nur "Ausnahme beim Aufrufen von Start ...").
function Get-PelInnerMessage($ErrorRecordOrException) {
    $ex = $ErrorRecordOrException
    if ($ex -is [System.Management.Automation.ErrorRecord]) { $ex = $ex.Exception }
    while ($ex -and $ex.InnerException) { $ex = $ex.InnerException }
    if ($ex) { return $ex.Message }
    return [string]$ErrorRecordOrException
}

# ---- Einstellungen (Server, Lobby, Passwort per DPAPI, fester Maschinenschlüssel) -----
function Get-PelP2pSettings {
    $s = [ordered]@{ Server = $script:PelP2pDefaultServer; Lobby = ''; PasswordEnc = ''; AutoConnect = $false; MachineKey = ''; HostLobby = ''; HostPasswordEnc = ''; HostAddress = ''; HostAuto = $false; DynProvider = 0; DynName = ''; DynSecretEnc = ''; NoiseEnabled = $true; NoiseStrict = $true; NoiseCats = '*'; NoiseCustom = '' }
    try {
        if ([System.IO.File]::Exists($script:PelP2pSettingsPath)) {
            $j = Get-Content -LiteralPath $script:PelP2pSettingsPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($k in @($s.Keys)) {
                if ($j.PSObject.Properties[$k] -and $null -ne $j.$k) { $s[$k] = $j.$k }
            }
        }
    } catch { Write-PelLog -Level 'P2P' -Message "Einstellungen nicht lesbar: $($_.Exception.Message)" }
    if (-not $s.Server) { $s.Server = $script:PelP2pDefaultServer }
    # Maschinenschlüssel: bleibt für immer gleich -> derselbe PC bekommt in einer Lobby
    # immer dieselbe virtuelle IP (wichtig für Freundesliste, Postfach, Direkt-Verbinden).
    if (-not ([string]$s.MachineKey -match '^[0-9a-f]{32}$')) {
        $kb = New-Object byte[] 16
        $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
        try { $rng.GetBytes($kb) } finally { $rng.Dispose() }
        $s.MachineKey = (($kb | ForEach-Object { $_.ToString('x2') }) -join '')
        Save-PelP2pSettings ([pscustomobject]$s)
    }
    return [pscustomobject]$s
}

function Save-PelP2pSettings($Settings) {
    try {
        if (-not [System.IO.Directory]::Exists($script:PelP2pDir)) { [void][System.IO.Directory]::CreateDirectory($script:PelP2pDir) }
        $Settings | Select-Object Server, Lobby, PasswordEnc, AutoConnect, MachineKey, HostLobby, HostPasswordEnc, HostAddress, HostAuto, DynProvider, DynName, DynSecretEnc, NoiseEnabled, NoiseStrict, NoiseCats, NoiseCustom | ConvertTo-Json |
            Set-Content -LiteralPath $script:PelP2pSettingsPath -Encoding UTF8
    } catch { Write-PelLog -Level 'P2P' -Message "Einstellungen nicht speicherbar: $($_.Exception.Message)" }
}

# Passwort nur verschlüsselt speichern (Windows-DPAPI, lesbar nur für dieses Benutzerkonto)
function Protect-PelP2pPassword([string]$Plain) {
    if (-not $Plain) { return '' }
    try { return (ConvertTo-SecureString -String $Plain -AsPlainText -Force | ConvertFrom-SecureString) } catch { return '' }
}

function Unprotect-PelP2pPassword([string]$Encrypted) {
    if (-not $Encrypted) { return '' }
    $bstr = [IntPtr]::Zero
    try {
        $ss = ConvertTo-SecureString -String $Encrypted -ErrorAction Stop
        $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($ss)
        return [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)
    } catch { return '' }
    finally { if ($bstr -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) } }
}

# ---- Wintun bereitstellen (einmaliger Download, doppelt geprüft) ---------------------
function Test-PelWintunSignature([string]$Path) {
    try {
        $sig = Get-AuthenticodeSignature -LiteralPath $Path
        return ($sig.Status -eq 'Valid' -and [string]$sig.SignerCertificate.Subject -match 'WireGuard LLC')
    } catch { return $false }
}

function Get-PelWintunDll {
    $arch = switch ([string]$env:PROCESSOR_ARCHITECTURE) { 'ARM64' { 'arm64' } 'AMD64' { 'amd64' } default { 'x86' } }
    if (-not [System.IO.Directory]::Exists($script:PelP2pDir)) { [void][System.IO.Directory]::CreateDirectory($script:PelP2pDir) }
    # Eigener Unterordner je Architektur, Dateiname MUSS "wintun.dll" bleiben.
    $archDir = Join-Path $script:PelP2pDir $arch
    if (-not [System.IO.Directory]::Exists($archDir)) { [void][System.IO.Directory]::CreateDirectory($archDir) }
    $dll = Join-Path $archDir 'wintun.dll'
    # Ältere Versionen haben die Datei als "wintun-<arch>.dll" abgelegt - gültig? Dann übernehmen.
    $legacy = Join-Path $script:PelP2pDir "wintun-$arch.dll"
    if (-not [System.IO.File]::Exists($dll) -and [System.IO.File]::Exists($legacy) -and (Test-PelWintunSignature $legacy)) {
        try { [System.IO.File]::Copy($legacy, $dll, $true) } catch { }
    }
    if ([System.IO.File]::Exists($dll)) {
        if (Test-PelWintunSignature $dll) { return $dll }
        Write-PelLog -Level 'P2P' -Message "Vorhandene $dll hat keine gültige Signatur - wird neu geladen."
        try { [System.IO.File]::Delete($dll) } catch { throw "Die vorhandene Datei $dll ist ungültig und lässt sich nicht löschen (noch geladen? Manager neu starten)." }
    }
    $zip = Join-Path $env:TEMP ("wintun-{0}.zip" -f [guid]::NewGuid().ToString('N'))
    $oldPp = $ProgressPreference
    try {
        $ProgressPreference = 'SilentlyContinue'
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
        Invoke-WebRequest -Uri $script:PelP2pWintunUrl -OutFile $zip -UseBasicParsing -ErrorAction Stop
        $hash = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash
        if ($hash -ne $script:PelP2pWintunSha256) { throw "Prüfsumme des Wintun-Downloads stimmt nicht (erwartet $($script:PelP2pWintunSha256), erhalten $hash). Abgebrochen." }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $za = [System.IO.Compression.ZipFile]::OpenRead($zip)
        try {
            $entry = $za.Entries | Where-Object { $_.FullName -eq "wintun/bin/$arch/wintun.dll" } | Select-Object -First 1
            if (-not $entry) { throw "wintun.dll für $arch nicht im Archiv gefunden." }
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $dll, $true)
        } finally { $za.Dispose() }
    } finally {
        $ProgressPreference = $oldPp
        try { if ([System.IO.File]::Exists($zip)) { [System.IO.File]::Delete($zip) } } catch { }
    }
    if (-not (Test-PelWintunSignature $dll)) {
        try { [System.IO.File]::Delete($dll) } catch { }
        throw "wintun.dll hat keine gültige Signatur von WireGuard LLC - aus Sicherheitsgründen nicht verwendet."
    }
    Write-PelLog -Level 'P2P' -Message "Wintun bereitgestellt: $dll"
    return $dll
}

# ---- Firewall: eingehend UDP für den P2P-Port (Hole Punching, Roaming, LAN-Direktweg) --
function Enable-PelP2pFirewall {
    $name = "Project Earth LAN P2P (UDP $($script:PelP2pUdpPort))"
    try {
        if (-not (Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue)) {
            New-NetFirewallRule -DisplayName $name -Direction Inbound -Action Allow -Protocol UDP -LocalPort $script:PelP2pUdpPort -Profile Any -ErrorAction Stop | Out-Null
        }
    } catch { Write-PelLog -Level 'P2P' -Message "Firewall-Regel konnte nicht angelegt werden: $($_.Exception.Message)" }
}

# ---- Adapter-Konfiguration (läuft in eigenem Runspace, blockiert die GUI nicht) -------
$script:PelP2pAdapterConfigScript = {
    param([string]$Alias, [string]$Ip, [int]$Prefix, [int]$Mtu)
    $ErrorActionPreference = 'Stop'
    $ad = $null
    for ($i = 0; $i -lt 40 -and -not $ad; $i++) {
        $ad = Get-NetAdapter -Name $Alias -ErrorAction SilentlyContinue
        if (-not $ad) { Start-Sleep -Milliseconds 250 }
    }
    if (-not $ad) { throw "Adapter '$Alias' wurde nicht gefunden." }
    $idx = $ad.ifIndex
    # IPv6 auf dem Tunnel aus (Spiele nutzen IPv4, spart Rauschen)
    try { Disable-NetAdapterBinding -Name $Alias -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue } catch { }
    # NetBIOS über TCP/IP auf dem Tunnel aus - Windows erzeugt diesen Lärm dann gar nicht erst
    try {
        $nbKey = "HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces\Tcpip_$($ad.InterfaceGuid)"
        if (Test-Path -LiteralPath $nbKey) { Set-ItemProperty -LiteralPath $nbKey -Name NetbiosOptions -Value 2 -Type DWord -ErrorAction SilentlyContinue }
    } catch { }
    # Alte/fremde IPv4-Adressen entfernen, dann die zugewiesene setzen (nur aktiv, nicht dauerhaft)
    Get-NetIPAddress -InterfaceIndex $idx -AddressFamily IPv4 -ErrorAction SilentlyContinue |
        Where-Object { $_.IPAddress -ne $Ip } | Remove-NetIPAddress -Confirm:$false -ErrorAction SilentlyContinue
    if (-not (Get-NetIPAddress -InterfaceIndex $idx -IPAddress $Ip -ErrorAction SilentlyContinue)) {
        New-NetIPAddress -InterfaceIndex $idx -IPAddress $Ip -PrefixLength $Prefix -PolicyStore ActiveStore | Out-Null
    }
    # Metrik 1: Windows schickt Broadcasts (255.255.255.255) bevorzugt über diesen Adapter
    # -> LAN-Server-Suche der Spiele findet die Mitspieler. MTU 1380 lässt Platz für
    # Verschlüsselung + UDP-Header, damit nichts fragmentiert.
    Set-NetIPInterface -InterfaceIndex $idx -AddressFamily IPv4 -InterfaceMetric 1 -NlMtuBytes $Mtu -ErrorAction SilentlyContinue
    # Netzwerkprofil "Privat" - sonst blockt die Windows-Firewall eingehende Spiel-Verbindungen
    for ($i = 0; $i -lt 20; $i++) {
        $prof = Get-NetConnectionProfile -InterfaceIndex $idx -ErrorAction SilentlyContinue
        if ($prof) {
            if ([string]$prof.NetworkCategory -ne 'Private') { Set-NetConnectionProfile -InterfaceIndex $idx -NetworkCategory Private -ErrorAction SilentlyContinue }
            break
        }
        Start-Sleep -Milliseconds 500
    }
    'OK'
}

function Start-PelP2pAdapterConfig([string]$Ip, [int]$Prefix) {
    $ps = [System.Management.Automation.PowerShell]::Create()
    [void]$ps.AddScript($script:PelP2pAdapterConfigScript.ToString()).AddArgument($script:PelP2pAdapterName).AddArgument($Ip).AddArgument($Prefix).AddArgument($script:PelP2pMtu)
    $script:PelP2pCfgJob = [pscustomobject]@{ PS = $ps; Handle = $ps.BeginInvoke(); Ip = $Ip }
}

# $null = läuft noch / nichts zu tun, sonst Ergebnisobjekt { Ok, Ip, Message }
function Receive-PelP2pAdapterConfig {
    $job = $script:PelP2pCfgJob
    if (-not $job -or -not $job.Handle.IsCompleted) { return $null }
    $ok = $false; $msg = ''
    try {
        $out = $job.PS.EndInvoke($job.Handle)
        $ok = (@($out) -contains 'OK')
        if ($job.PS.Streams.Error.Count -gt 0) { $msg = [string]$job.PS.Streams.Error[0] }
    } catch { $msg = Get-PelInnerMessage $_ }
    finally {
        try { $job.PS.Dispose() } catch { }
        $script:PelP2pCfgJob = $null
    }
    return [pscustomobject]@{ Ok = $ok; Ip = $job.Ip; Message = $msg }
}

# ---- Broadcast-Firewall (Hintergrund-"Lärm" von Windows, Linux und macOS) ---------------
# Die Engine verwirft diese Pakete, bevor sie in den Tunnel gehen, UND beim Empfang.
# Spiele-Suchen (eigene Ports der Spiele) sind davon nicht betroffen.
$script:PelNoiseCategories = @(
    [pscustomobject]@{ Id = 'mdns';    Default = $true;  Ports = @(5353);            Name = 'mDNS / Bonjour / Avahi (macOS, Linux, Windows)' }
    [pscustomobject]@{ Id = 'llmnr';   Default = $true;  Ports = @(5355);            Name = 'LLMNR - Windows-Namensauflösung' }
    [pscustomobject]@{ Id = 'netbios'; Default = $true;  Ports = @(137, 138);        Name = 'NetBIOS - Windows-Netzwerkumgebung, Samba (Linux)' }
    [pscustomobject]@{ Id = 'ssdp';    Default = $true;  Ports = @(1900);            Name = 'SSDP / UPnP - Gerätesuche (Windows, Smart-TVs, Router)' }
    [pscustomobject]@{ Id = 'wsd';     Default = $true;  Ports = @(3702);            Name = 'WS-Discovery - Windows-/Druckersuche' }
    [pscustomobject]@{ Id = 'dhcp';    Default = $true;  Ports = @(67, 68);          Name = 'DHCP-Anfragen' }
    [pscustomobject]@{ Id = 'igmp';    Default = $true;  Ports = @();                Name = 'IGMP - Multicast-Anmeldungen aller Systeme' }
    [pscustomobject]@{ Id = 'apps';    Default = $true;  Ports = @(17500, 57621, 1716, 21027); Name = 'App-Suchen (Dropbox, Spotify, KDE Connect, Syncthing)' }
    [pscustomobject]@{ Id = 'print';   Default = $true;  Ports = @(427, 8611, 8612, 161); Name = 'Drucker-/Gerätesuche (SLP, Canon BJNP, SNMP)' }
    [pscustomobject]@{ Id = 'steam';   Default = $false; Ports = @(27036);           Name = 'Steam Remote Play / In-Home-Streaming-Suche (nützlich!)' }
)

# Aktive Konfiguration aus den Einstellungen (NoiseCats = '*' -> Standardauswahl)
function Get-PelNoiseConfig {
    param($Settings = $null)
    if (-not $Settings) { $Settings = Get-PelP2pSettings }
    $cats = @{}
    $sel = [string]$Settings.NoiseCats
    foreach ($c in $script:PelNoiseCategories) {
        $cats[$c.Id] = if ($sel -eq '*' -or -not $sel) { [bool]$c.Default } else { (@($sel -split ',') -contains $c.Id) }
    }
    $ports = New-Object System.Collections.Generic.List[int]
    foreach ($c in $script:PelNoiseCategories) { if ($cats[$c.Id]) { foreach ($pt in $c.Ports) { $ports.Add([int]$pt) } } }
    foreach ($tok in ([string]$Settings.NoiseCustom -split '[,;\s]+')) {
        $n = 0
        if ([int]::TryParse($tok, [ref]$n) -and $n -gt 0 -and $n -lt 65536) { $ports.Add($n) }
    }
    return [pscustomobject]@{
        Enabled = ($Settings.NoiseEnabled -ne $false)
        Strict  = ($Settings.NoiseStrict -ne $false)
        Igmp    = [bool]$cats['igmp']
        Cats    = $cats
        Custom  = [string]$Settings.NoiseCustom
        Ports   = [int[]]$ports.ToArray()
    }
}

function Set-PelEngineNoiseFilter($Engine) {
    if (-not $Engine) { return }
    $cfg = Get-PelNoiseConfig
    try { $Engine.SetNoiseFilter([bool]$cfg.Enabled, [int[]]$cfg.Ports, [bool]$cfg.Igmp, [bool]$cfg.Strict) } catch { }
}

# Portnummer -> lesbarer Dienstname (für die Statistik)
function Get-PelNoisePortName([int]$Port) {
    if ($Port -eq -2) { return 'IGMP' }
    foreach ($c in $script:PelNoiseCategories) {
        if ($c.Ports -contains $Port) { $short = ($c.Name -split ' - | \(')[0].Trim(); return "$short ($Port)" }
    }
    return "UDP $Port"
}

# ---- Start / Stop ---------------------------------------------------------------------
function Test-PelP2pRunning { return [bool]($script:PelP2pEngine -and $script:PelP2pEngine.IsRunning) }

function Start-PelP2p {
    param([string]$Server, [string]$Lobby, [string]$Password)
    if (Test-PelP2pRunning) { return }
    if (-not ($Server -match '^\s*([A-Za-z0-9\.\-]+)(?::(\d{1,5}))?\s*$')) { throw "Ungültige Serveradresse '$Server' (Format: host oder host:port)." }
    $srvHost = $matches[1]
    $srvPort = if ($matches[2]) { [int]$matches[2] } else { 47810 }
    if ($srvPort -lt 1 -or $srvPort -gt 65535) { throw "Ungültiger Port $srvPort." }
    Initialize-PelP2pTypes
    $dll = Get-PelWintunDll
    $set = Get-PelP2pSettings
    Enable-PelP2pFirewall
    $eng = New-Object PelP2pEngine
    $eng.PreferredPort = $script:PelP2pUdpPort
    Set-PelEngineNoiseFilter $eng
    try {
        $eng.Start($srvHost, $srvPort, $Lobby, $Password, (Get-PelDisplayName), [string]$set.MachineKey, $dll, $script:PelP2pAdapterName)
    } catch {
        throw (Get-PelInnerMessage $_)
    }
    $script:PelP2pEngine = $eng
    Write-PelLog -Level 'P2P' -Message "Lobby '$Lobby' beigetreten (Server $srvHost`:$srvPort, UDP $($eng.LocalPort))"
}

function Stop-PelP2p {
    $eng = $script:PelP2pEngine
    if (-not $eng) { return }
    try { $eng.Stop() } catch { Write-PelLog -Level 'P2P' -Message ("Fehler beim Trennen: " + (Get-PelInnerMessage $_)) }
    $line = $null
    while ($eng.Log.TryDequeue([ref]$line)) { Write-PelLog -Level 'P2P' -Message $line }
    if ($script:PelP2pCfgJob) { try { $script:PelP2pCfgJob.PS.Stop(); $script:PelP2pCfgJob.PS.Dispose() } catch { }; $script:PelP2pCfgJob = $null }
    # War der P2P-Adapter zentral gewählt, auf die normale Verbindung zurückstellen, damit
    # die Options-Fenster (Server-Browser, Kommunikationszentrale) nicht ins Leere zeigen.
    try {
        if ([System.IO.File]::Exists($script:PelAdapterConfigPath)) {
            $saved = Get-Content -LiteralPath $script:PelAdapterConfigPath -Raw | ConvertFrom-Json
            if ($saved -and [string]$saved.Name -eq $script:PelP2pAdapterName) {
                $fallback = @(Get-PelAdapterList) | Where-Object { -not $_.IsP2P } | Sort-Object -Property Metric | Select-Object -First 1
                if ($fallback) { Save-PelSelectedAdapter $fallback }
            }
        }
    } catch { }
    Write-PelLog -Level 'P2P' -Message 'P2P-Netzwerk getrennt.'
}

# ==============================================================================
# OPTION 9: EIGENE LOBBY HOSTEN (eingebauter Vermittlungsserver, "Auto-Installer")
# ==============================================================================
# Ein Klick genügt: der Manager startet den Vermittlungsserver (derselbe Code wie
# PEL-Rendezvous.ps1) im Control Center, legt die Firewall-Regeln an, gibt die Ports
# per UPnP automatisch im Router frei, ermittelt die öffentliche IP, tritt der eigenen
# Lobby bei und erzeugt einen Einladungscode. Freunde fügen nur den Code ein - fertig.
# Nichts wird installiert; der Server läuft, solange das Control Center läuft.
$script:PelHostPort  = 47810
# Option 9 (Hosten am Heimanschluss): bis 512 Spieler je Lobby. Relay-Verkehr (nur Paare, die
# kein Hole Punching schaffen) wird begrenzt, damit dein Upload für dich nutzbar bleibt:
# höchstens 10 Mbit/s insgesamt und 3 Mbit/s je Mitspieler (0 = unbegrenzt).
$script:PelHostMaxMembers = 512
$script:PelHostRelayMbitTotal = 10
$script:PelHostRelayMbitPerMember = 3
$script:PelRvServer  = $null
$script:PelHostJob   = $null
$script:PelHostState = [pscustomobject]@{
    Running = $false; Lobby = ''; Password = ''; PublicIp = ''; LanIp = ''; Address = ''
    UpnpOk = $false; UpnpPorts = @(); Warning = ''; Probing = $false; Cgnat = $false; AutoAddress = $true
}

$script:PelRvCode = @'
using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public sealed class PelRvMember
{
    public ulong NodeId;
    public string MachineKey;
    public IPEndPoint Ep;
    public uint Vip;
    public byte[] Name = new byte[0];
    public byte[] Locals = new byte[0];
    public long LastSeen;
    public double Tokens;
    public double ByteTokens;
    public long TokenTs;
    // Protokoll-Erweiterung "E2" (ab 2026.09.29): Mitgliederliste nur bei Aenderungen
    public bool V2;
    public uint Rev;          // Lobby-Revision der letzten Aenderung dieses Mitglieds
    public int Mismatch;      // wie oft in Folge der Stand des Clients nicht passte
}

public sealed class PelRvLobby
{
    public string Id;
    public Dictionary<ulong, PelRvMember> Members = new Dictionary<ulong, PelRvMember>();
    public Dictionary<string, uint> Leases = new Dictionary<string, uint>();
    public long LastActive;
    public uint Rev;          // zaehlt jede Aenderung (Beitritt, Adresswechsel, Verlassen)
    public ulong Digest;      // XOR ueber Mix(NodeId, Rev) aller Mitglieder
}

public sealed class PelRendezvousServer
{
    private const byte S_REGISTER = 0x10, S_LEAVE = 0x11, S_RELAY = 0x12;
    private const byte S_WELCOME = 0x20, S_PEER = 0x21, S_RELAYED = 0x22, S_ERROR = 0x23, S_MEMBERS = 0x24;
    // Erweiterung E2: Clients haengen an REGISTER [0xE2][Digest u64] an (alte Server ignorieren das).
    // Sie bekommen dann nur noch Aenderungen (PEER2/GONE) statt alle 10 s die komplette Liste;
    // die komplette Liste (PEER2 + SYNC) nur, wenn ihr Stand zweimal hintereinander nicht passt.
    private const byte S_SYNC = 0x25, S_PEER2 = 0x26, S_GONE = 0x27, EXT_V2 = 0xE2;
    private const int SyncChunk = 150;
    private const uint NetBase = 0x0A4D0000;   // 10.77.0.0
    private const int Prefix = 16;

    public int Port = 47810;
    public int MaxMembers = 512;
    public int MaxLobbies = 2000;
    public int RelayPps = 4000;
    // Relay-Bandbreite in Mbit/s (0 = unbegrenzt): je Mitglied und fuer alle zusammen. Schuetzt
    // den Upload des Gastgebers, wenn viele Mitspieler hinter strengem NAT/CGNAT sitzen.
    public double RelayMbitPerMember = 0;
    public double RelayMbitTotal = 0;
    private double totalTokens;
    private long totalTs;
    public long RelayDropped;
    public readonly ConcurrentQueue<string> Log = new ConcurrentQueue<string>();
    public long RelayedPackets;
    public volatile int MemberCount;
    // Nur wenn der Server beim Spieler zu Hause laeuft (Manager-Option "Lobby hosten"):
    // oeffentliche IP des Anschlusses. Mitglieder, die sich ueber Loopback/LAN anmelden
    // (der Host selbst, Gaeste im selben Heimnetz), werden dann mit dieser IP angekuendigt.
    public volatile IPAddress PublicIp;

    private readonly Dictionary<string, PelRvLobby> lobbies = new Dictionary<string, PelRvLobby>();
    private readonly Stopwatch clock = Stopwatch.StartNew();
    private readonly byte[] cookieKey = new byte[32];
    private HMACSHA256 cookieMac;
    private Socket sock;
    private Thread thread;
    private volatile bool stopping;

    private long Now() { return clock.ElapsedMilliseconds; }
    private void AddLog(string s) { Log.Enqueue(DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "  " + s); }

    private static uint ReadU32(byte[] b, int o) { return ((uint)b[o] << 24) | ((uint)b[o + 1] << 16) | ((uint)b[o + 2] << 8) | b[o + 3]; }
    private static void WriteU32(byte[] b, int o, uint v) { b[o] = (byte)(v >> 24); b[o + 1] = (byte)(v >> 16); b[o + 2] = (byte)(v >> 8); b[o + 3] = (byte)v; }
    private static ulong ReadU64(byte[] b, int o) { return ((ulong)ReadU32(b, o) << 32) | ReadU32(b, o + 4); }
    private static void WriteU64(byte[] b, int o, ulong v) { WriteU32(b, o, (uint)(v >> 32)); WriteU32(b, o + 4, (uint)v); }
    private static string Hex(byte[] b, int o, int n) { StringBuilder sb = new StringBuilder(n * 2); for (int i = 0; i < n; i++) sb.Append(b[o + i].ToString("x2")); return sb.ToString(); }
    private static string Ip(uint v) { return (v >> 24) + "." + ((v >> 16) & 255) + "." + ((v >> 8) & 255) + "." + (v & 255); }

    public void Start()
    {
        using (RandomNumberGenerator rng = RandomNumberGenerator.Create()) rng.GetBytes(cookieKey);
        cookieMac = new HMACSHA256(cookieKey);
        sock = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
        try { sock.IOControl(-1744830452, new byte[] { 0, 0, 0, 0 }, null); } catch { }   // nur Windows (SIO_UDP_CONNRESET)
        sock.Bind(new IPEndPoint(IPAddress.Any, Port));
        sock.ReceiveTimeout = 1000;
        sock.ReceiveBufferSize = 4 << 20;
        sock.SendBufferSize = 4 << 20;
        thread = new Thread(Loop);
        thread.IsBackground = true;
        thread.Start();
        AddLog("Vermittlungsserver laeuft auf UDP-Port " + Port);
    }

    public void Stop()
    {
        stopping = true;
        try { sock.Close(); } catch { }
        if (thread != null) thread.Join(3000);
    }

    // Wird nur im Server-Thread aktualisiert (kein gleichzeitiger Zugriff auf die Listen).
    private volatile string statsText = "Lobbys: 0, Mitglieder: 0";
    public string Stats() { return statsText + ", Relay-Pakete: " + Interlocked.Read(ref RelayedPackets) + ", wegen Limit verworfen: " + Interlocked.Read(ref RelayDropped); }

    private byte[] Cookie(IPEndPoint ep)
    {
        byte[] d = new byte[6];
        Buffer.BlockCopy(ep.Address.GetAddressBytes(), 0, d, 0, 4);
        d[4] = (byte)(ep.Port >> 8); d[5] = (byte)ep.Port;
        byte[] h = cookieMac.ComputeHash(d);
        byte[] c = new byte[8];
        Buffer.BlockCopy(h, 0, c, 0, 8);
        return c;
    }

    private static bool IsPrivateOrLoopback(IPAddress a)
    {
        if (IPAddress.IsLoopback(a)) return true;
        byte[] b = a.GetAddressBytes();
        if (b.Length != 4) return false;
        return b[0] == 10 || (b[0] == 172 && b[1] >= 16 && b[1] <= 31) || (b[0] == 192 && b[1] == 168) || (b[0] == 169 && b[1] == 254);
    }

    private IPEndPoint Advertised(IPEndPoint ep)
    {
        IPAddress pub = PublicIp;
        if (pub != null && IsPrivateOrLoopback(ep.Address)) return new IPEndPoint(pub, ep.Port);
        return ep;
    }

    private void Send(byte[] data, IPEndPoint ep) { try { sock.SendTo(data, ep); } catch { } }

    private void Loop()
    {
        byte[] buf = new byte[65536];
        long lastCleanup = 0;
        while (!stopping)
        {
            EndPoint from = new IPEndPoint(IPAddress.Any, 0);
            int n = 0;
            try { n = sock.ReceiveFrom(buf, ref from); }
            catch (ObjectDisposedException) { break; }
            catch (SocketException) { n = 0; }
            if (stopping) break;
            try
            {
                if (n >= 3 && buf[0] == 0x50 && buf[1] == 0x53)
                {
                    IPEndPoint ep = (IPEndPoint)from;
                    if (buf[2] == S_REGISTER) OnRegister(buf, n, ep);
                    else if (buf[2] == S_RELAY) OnRelay(buf, n, ep);
                    else if (buf[2] == S_LEAVE) OnLeave(buf, n, ep);
                }
            }
            catch (Exception ex) { AddLog("Paketfehler: " + ex.Message); }
            long now = Now();
            if (now - lastCleanup > 1000) { lastCleanup = now; Cleanup(now); }
        }
    }

    private void SendError(IPEndPoint ep, byte code, string msg)
    {
        byte[] m = Encoding.UTF8.GetBytes(msg);
        if (m.Length > 200) Array.Resize(ref m, 200);
        byte[] p = new byte[5 + m.Length];
        p[0] = 0x50; p[1] = 0x53; p[2] = S_ERROR; p[3] = code; p[4] = (byte)m.Length;
        Buffer.BlockCopy(m, 0, p, 5, m.Length);
        Send(p, ep);
    }

    private byte[] BuildPeer(PelRvMember m)
    {
        byte[] p = new byte[3 + 8 + 4 + 6 + 1 + m.Name.Length + 1 + m.Locals.Length];
        p[0] = 0x50; p[1] = 0x53; p[2] = S_PEER;
        WriteU64(p, 3, m.NodeId);
        WriteU32(p, 11, m.Vip);
        IPEndPoint adv = Advertised(m.Ep);
        Buffer.BlockCopy(adv.Address.GetAddressBytes(), 0, p, 15, 4);
        p[19] = (byte)(adv.Port >> 8); p[20] = (byte)adv.Port;
        int o = 21;
        p[o++] = (byte)m.Name.Length;
        Buffer.BlockCopy(m.Name, 0, p, o, m.Name.Length); o += m.Name.Length;
        p[o++] = (byte)(m.Locals.Length / 6);
        Buffer.BlockCopy(m.Locals, 0, p, o, m.Locals.Length);
        return p;
    }

    // Altes Format (nur fuer Manager vor 2026.09.29): hoechstens 255 Eintraege.
    private byte[] BuildMembers(PelRvLobby l)
    {
        int cnt = Math.Min(l.Members.Count, 255);
        byte[] p = new byte[4 + cnt * 8];
        p[0] = 0x50; p[1] = 0x53; p[2] = S_MEMBERS; p[3] = (byte)cnt;
        int i = 0;
        foreach (ulong id in l.Members.Keys) { if (i >= cnt) break; WriteU64(p, 4 + i * 8, id); i++; }
        return p;
    }

    private void Broadcast(PelRvLobby l, byte[] data, ulong except)
    {
        foreach (PelRvMember o in l.Members.Values) if (o.NodeId != except) Send(data, o.Ep);
    }

    // ---- Erweiterung E2 -------------------------------------------------------------------
    public static ulong Mix(ulong nid, uint rev)
    {
        ulong z = nid ^ ((ulong)rev * 0x9E3779B97F4A7C15UL);
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        return z ^ (z >> 31);
    }

    // PEER2 = [P S 0x26][Art: 0 Aenderung / 1 Abgleich][Rev u32] + Inhalt wie PEER
    private byte[] BuildPeer2(PelRvMember m, byte kind)
    {
        byte[] bp = BuildPeer(m);
        byte[] p = new byte[bp.Length + 5];
        p[0] = 0x50; p[1] = 0x53; p[2] = S_PEER2; p[3] = kind;
        WriteU32(p, 4, m.Rev);
        Buffer.BlockCopy(bp, 3, p, 8, bp.Length - 3);
        return p;
    }

    // Mitglied neu/geaendert: neue Revision, allen E2-Clients (auch ihm selbst) die Aenderung,
    // alten Clients wie bisher PEER + Mitgliederliste.
    private void NotifyChange(PelRvLobby l, PelRvMember m)
    {
        if (m.Rev != 0) l.Digest ^= Mix(m.NodeId, m.Rev);
        l.Rev++; if (l.Rev == 0) l.Rev = 1;
        m.Rev = l.Rev;
        l.Digest ^= Mix(m.NodeId, m.Rev);
        byte[] p2 = BuildPeer2(m, 0);
        byte[] pm = null, mem = null;
        foreach (PelRvMember x in l.Members.Values)
        {
            if (x.V2) Send(p2, x.Ep);
            else if (x.NodeId != m.NodeId)
            {
                if (pm == null) { pm = BuildPeer(m); mem = BuildMembers(l); }
                Send(pm, x.Ep); Send(mem, x.Ep);
            }
        }
    }

    // Mitglied ist weg (abgemeldet, Timeout, neue Sitzung desselben PCs). Vorher schon entfernt.
    private void NotifyGone(PelRvLobby l, PelRvMember m)
    {
        if (m.Rev != 0) l.Digest ^= Mix(m.NodeId, m.Rev);
        l.Rev++; if (l.Rev == 0) l.Rev = 1;
        byte[] g = new byte[15];
        g[0] = 0x50; g[1] = 0x53; g[2] = S_GONE;
        WriteU32(g, 3, l.Rev);
        WriteU64(g, 7, m.NodeId);
        byte[] mem = null;
        foreach (PelRvMember x in l.Members.Values)
        {
            if (x.V2) Send(g, x.Ep);
            else { if (mem == null) mem = BuildMembers(l); Send(mem, x.Ep); }
        }
    }

    // Kompletter Abgleich: alle anderen als PEER2 (Art 1), danach die Mitgliederliste in
    // Stuecken: SYNC = [P S 0x25][Rev u32][Gesamt u16][Start u16][Anzahl u8][NodeIds...]
    private void SendSync(PelRvLobby l, PelRvMember m)
    {
        foreach (PelRvMember x in l.Members.Values) if (x.NodeId != m.NodeId) Send(BuildPeer2(x, 1), m.Ep);
        List<ulong> ids = new List<ulong>(l.Members.Keys);
        int total = ids.Count;
        for (int st = 0; st < total; st += SyncChunk)
        {
            int cnt = Math.Min(SyncChunk, total - st);
            byte[] p = new byte[12 + cnt * 8];
            p[0] = 0x50; p[1] = 0x53; p[2] = S_SYNC;
            WriteU32(p, 3, l.Rev);
            p[7] = (byte)(total >> 8); p[8] = (byte)total;
            p[9] = (byte)(st >> 8); p[10] = (byte)st;
            p[11] = (byte)cnt;
            for (int i = 0; i < cnt; i++) WriteU64(p, 12 + i * 8, ids[st + i]);
            Send(p, m.Ep);
        }
    }

    // Feste virtuelle IP je PC (MachineKey) und Lobby: deterministisch aus dem Hash,
    // bei Kollision die naechste freie. Letztes Oktett nie .0/.255 (Spiele-Kompatibilitaet).
    private uint AllocateVip(PelRvLobby l, string mk)
    {
        HashSet<uint> used = new HashSet<uint>();
        foreach (PelRvMember o in l.Members.Values) used.Add(o.Vip);
        uint lease;
        if (l.Leases.TryGetValue(mk, out lease) && !used.Contains(lease)) return lease;
        uint idx;
        // Nur aus dem MachineKey (nicht aus der Lobby) -> derselbe PC hat in JEDER Lobby und auf
        // JEDEM Server dieselbe virtuelle IP (wichtig fuer Freundesliste, Moderatoren, Bans,
        // Kanal-Ersteller - die alle ueber die IP laufen). Nur bei einer Kollision weicht sie ab.
        using (SHA256 sha = SHA256.Create()) idx = ReadU32(sha.ComputeHash(Encoding.ASCII.GetBytes("PEL-VIP|" + mk)), 0) % 65024u;
        for (int t = 0; t < 65024; t++)
        {
            uint v = NetBase | ((idx / 254u) << 8) | (idx % 254u + 1u);
            bool leasedToOther = false;
            foreach (KeyValuePair<string, uint> kv in l.Leases) if (kv.Value == v && kv.Key != mk) { leasedToOther = true; break; }
            if (!used.Contains(v) && !leasedToOther) { l.Leases[mk] = v; return v; }
            idx = (idx + 1u) % 65024u;
        }
        return 0;
    }

    private void OnRegister(byte[] b, int n, IPEndPoint ep)
    {
        if (n < 46) return;
        if (b[3] != 1) { SendError(ep, 1, "Veraltete oder neuere Manager-Version - bitte aktualisieren."); return; }
        string lid = Hex(b, 4, 16);
        ulong nid = ReadU64(b, 20);
        string mk = Hex(b, 28, 16);
        int o = 44;
        int nl = b[o++];
        if (nl > 32 || o + nl + 1 > n) return;
        byte[] name = new byte[nl]; Buffer.BlockCopy(b, o, name, 0, nl); o += nl;
        int cnt = b[o++];
        if (cnt > 8 || o + cnt * 6 > n) return;
        byte[] locals = new byte[cnt * 6]; Buffer.BlockCopy(b, o, locals, 0, cnt * 6); o += cnt * 6;
        byte[] expect = Cookie(ep);
        bool cookieOk = o + 8 <= n;
        for (int i = 0; cookieOk && i < 8; i++) if (b[o + i] != expect[i]) cookieOk = false;
        bool v2 = cookieOk && o + 8 + 9 <= n && b[o + 8] == EXT_V2;
        ulong clientDigest = v2 ? ReadU64(b, o + 9) : 0;

        byte[] w = new byte[22];
        w[0] = 0x50; w[1] = 0x53; w[2] = S_WELCOME;
        IPEndPoint advSelf = Advertised(ep);
        Buffer.BlockCopy(advSelf.Address.GetAddressBytes(), 0, w, 7, 4);
        w[11] = (byte)(advSelf.Port >> 8); w[12] = (byte)advSelf.Port; w[13] = Prefix;
        Buffer.BlockCopy(expect, 0, w, 14, 8);
        if (!cookieOk)
        {
            // Erst Cookie ausliefern (virtuelle IP 0 = "noch nicht aufgenommen").
            // Gefaelschte Absender bekommen so nie Mitgliederlisten (kein Verstaerker).
            Send(w, ep);
            return;
        }

        long now = Now();
        PelRvLobby l;
        if (!lobbies.TryGetValue(lid, out l))
        {
            if (lobbies.Count >= MaxLobbies) { SendError(ep, 2, "Server ausgelastet (zu viele Lobbys)."); return; }
            l = new PelRvLobby(); l.Id = lid; lobbies[lid] = l;
            // Zufaelliger Startwert: nach einem Server-Neustart passt kein alter Client-Stand zufaellig
            byte[] rr = new byte[4];
            using (RandomNumberGenerator rng = RandomNumberGenerator.Create()) rng.GetBytes(rr);
            l.Rev = ReadU32(rr, 0);
        }
        l.LastActive = now;

        bool changed = false, isNew = false;
        PelRvMember m;
        if (!l.Members.TryGetValue(nid, out m))
        {
            // Gleicher PC mit neuer Sitzung (Absturz/Neustart)? Alte Sitzung sofort entfernen.
            List<PelRvMember> stale = new List<PelRvMember>();
            foreach (PelRvMember x in l.Members.Values) if (x.MachineKey == mk) stale.Add(x);
            foreach (PelRvMember s in stale) { l.Members.Remove(s.NodeId); NotifyGone(l, s); }
            if (l.Members.Count >= MaxMembers) { SendError(ep, 3, "Lobby ist voll (max. " + MaxMembers + ")."); return; }
            m = new PelRvMember();
            m.NodeId = nid; m.MachineKey = mk; m.Ep = ep;
            m.Vip = AllocateVip(l, mk);
            if (m.Vip == 0) { SendError(ep, 4, "Keine freie virtuelle IP."); return; }
            m.Tokens = RelayPps; m.ByteTokens = RelayMbitPerMember * 125000.0; m.TokenTs = now;
            l.Members[nid] = m;
            changed = true; isNew = true;
            AddLog("Lobby " + lid.Substring(0, 8) + ": + " + Encoding.UTF8.GetString(name) + " (" + Ip(m.Vip) + ") von " + ep + " [" + l.Members.Count + " online]");
        }
        if (!m.Ep.Equals(ep)) { m.Ep = ep; changed = true; }
        if (!Same(m.Name, name) || !Same(m.Locals, locals)) { m.Name = name; m.Locals = locals; changed = true; }
        m.LastSeen = now;
        m.V2 = v2;

        WriteU32(w, 3, m.Vip);
        Send(w, ep);
        if (changed) NotifyChange(l, m);
        if (m.V2)
        {
            // Stand des Clients = alle anderen Mitglieder mit ihrer Revision
            ulong expected = l.Digest ^ Mix(m.NodeId, m.Rev);
            if (clientDigest == expected) m.Mismatch = 0;
            // Erst beim zweiten Fehlstand in Folge abgleichen (ein einzelner kann nur eine gerade
            // unterwegs befindliche Aenderung sein). Nach einem Abgleich zaehlt der naechste sofort.
            else if (isNew || ++m.Mismatch >= 2) { m.Mismatch = 1; SendSync(l, m); }
        }
        else
        {
            // Alte Manager-Version: wie bisher komplette Liste bei jeder Anmeldung
            Send(BuildMembers(l), ep);
            foreach (PelRvMember x in l.Members.Values) if (x.NodeId != nid) Send(BuildPeer(x), ep);
        }
    }

    private static bool Same(byte[] a, byte[] b)
    {
        if (a.Length != b.Length) return false;
        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return false;
        return true;
    }

    private void OnLeave(byte[] b, int n, IPEndPoint ep)
    {
        if (n < 27) return;
        PelRvLobby l;
        if (!lobbies.TryGetValue(Hex(b, 3, 16), out l)) return;
        ulong nid = ReadU64(b, 19);
        PelRvMember m;
        if (!l.Members.TryGetValue(nid, out m) || !m.Ep.Equals(ep)) return;
        l.Members.Remove(nid);
        AddLog("Lobby " + l.Id.Substring(0, 8) + ": - " + Encoding.UTF8.GetString(m.Name) + " (abgemeldet) [" + l.Members.Count + " online]");
        NotifyGone(l, m);
    }

    private void OnRelay(byte[] b, int n, IPEndPoint ep)
    {
        if (n < 35 + 31) return;
        PelRvLobby l;
        if (!lobbies.TryGetValue(Hex(b, 3, 16), out l)) return;
        PelRvMember src, dst;
        if (!l.Members.TryGetValue(ReadU64(b, 19), out src) || !src.Ep.Equals(ep)) return;
        if (!l.Members.TryGetValue(ReadU64(b, 27), out dst)) return;
        long now = Now();
        long el = now - src.TokenTs;
        src.TokenTs = now;
        src.Tokens = Math.Min(RelayPps, src.Tokens + el * RelayPps / 1000.0);
        if (src.Tokens < 1) return;
        int bytes = n - 35 + 11;
        if (RelayMbitPerMember > 0)
        {
            double rate = RelayMbitPerMember * 125000.0;
            src.ByteTokens = Math.Min(rate, src.ByteTokens + el * rate / 1000.0);
            if (src.ByteTokens < bytes) { Interlocked.Increment(ref RelayDropped); return; }
        }
        if (RelayMbitTotal > 0)
        {
            double rate = RelayMbitTotal * 125000.0;
            totalTokens = Math.Min(rate, totalTokens + (now - totalTs) * rate / 1000.0);
            totalTs = now;
            if (totalTokens < bytes) { Interlocked.Increment(ref RelayDropped); return; }
            totalTokens -= bytes;
        }
        if (RelayMbitPerMember > 0) src.ByteTokens -= bytes;
        src.Tokens -= 1;
        src.LastSeen = now;
        byte[] f = new byte[3 + 8 + (n - 35)];
        f[0] = 0x50; f[1] = 0x53; f[2] = S_RELAYED;
        WriteU64(f, 3, src.NodeId);
        Buffer.BlockCopy(b, 35, f, 11, n - 35);
        Send(f, dst.Ep);
        Interlocked.Increment(ref RelayedPackets);
    }

    private void Cleanup(long now)
    {
        List<string> emptyLobbies = new List<string>();
        foreach (PelRvLobby l in lobbies.Values)
        {
            List<PelRvMember> dead = new List<PelRvMember>();
            foreach (PelRvMember m in l.Members.Values) if (now - m.LastSeen > 35000) dead.Add(m);
            foreach (PelRvMember d in dead)
            {
                AddLog("Lobby " + l.Id.Substring(0, 8) + ": - " + Encoding.UTF8.GetString(d.Name) + " (Timeout)");
                l.Members.Remove(d.NodeId);
                NotifyGone(l, d);
            }
            if (l.Members.Count == 0 && now - l.LastActive > 6L * 3600 * 1000) emptyLobbies.Add(l.Id);
        }
        foreach (string id in emptyLobbies) lobbies.Remove(id);
        int total = 0;
        foreach (PelRvLobby l in lobbies.Values) total += l.Members.Count;
        statsText = "Lobbys: " + lobbies.Count + ", Mitglieder: " + total;
        MemberCount = total;
    }
}
'@

function Initialize-PelRvTypes {
    if (-not ('PelRendezvousServer' -as [type])) { Add-Type -TypeDefinition $script:PelRvCode -Language CSharp }
}

# ---- Einladungscode: "PEL1:" + Base64url(Server | Lobby | Passwort) -------------------
function New-PelInviteCode([string]$Server, [string]$Lobby, [string]$Password) {
    $raw = [System.Text.Encoding]::UTF8.GetBytes("$Server`n$Lobby`n$Password")
    return 'PEL1:' + ([Convert]::ToBase64String($raw).TrimEnd('=').Replace('+', '-').Replace('/', '_'))
}

function ConvertFrom-PelInviteCode([string]$Text) {
    if (-not ($Text -match 'PEL1:([A-Za-z0-9_\-]+)')) { return $null }
    try {
        $b = $matches[1].Replace('-', '+').Replace('_', '/')
        while ($b.Length % 4) { $b += '=' }
        $parts = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b)) -split "`n"
        if ($parts.Count -lt 3 -or -not $parts[0] -or -not $parts[1]) { return $null }
        return [pscustomobject]@{ Server = $parts[0]; Lobby = $parts[1]; Password = ($parts[2..($parts.Count - 1)] -join "`n") }
    } catch { return $null }
}

function New-PelRandomPassword([int]$Length = 10) {
    $chars = 'abcdefghkmnpqrstuvwxyzABCDEFGHKLMNPQRSTUVWXYZ23456789'
    $bytes = New-Object byte[] $Length
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
    return -join ($bytes | ForEach-Object { $chars[$_ % $chars.Length] })
}

# LAN-IP, über die dieser PC ins Internet geht (es wird nichts gesendet, nur die Route gewählt)
function Get-PelLanIpForInternet {
    $u = $null
    try {
        $u = New-Object System.Net.Sockets.UdpClient
        $u.Connect('8.8.8.8', 53)
        return $u.Client.LocalEndPoint.Address.ToString()
    } catch { return '' } finally { if ($u) { $u.Close() } }
}

function Test-PelPublicIPv4([string]$Ip) {
    $a = $null
    if (-not [System.Net.IPAddress]::TryParse($Ip, [ref]$a)) { return $false }
    $b = $a.GetAddressBytes()
    if ($b.Length -ne 4) { return $false }
    if ($b[0] -eq 10 -or $b[0] -eq 127 -or ($b[0] -eq 172 -and $b[1] -ge 16 -and $b[1] -le 31) -or ($b[0] -eq 192 -and $b[1] -eq 168)) { return $false }
    if ($b[0] -eq 100 -and $b[1] -ge 64 -and $b[1] -le 127) { return $false }   # CGNAT
    if ($b[0] -eq 169 -and $b[1] -eq 254) { return $false }
    return $true
}

# ---- Router-Freigabe (UPnP) + öffentliche IP ermitteln - im Hintergrund-Runspace -------
$script:PelHostProbeScript = {
    param([int[]]$Ports, [string]$LanIp)
    $r = [ordered]@{ UpnpOk = $false; UpnpIp = ''; WebIp = ''; Error = '' }
    try {
        $nat = New-Object -ComObject HNetCfg.NATUPnP
        $col = $null
        for ($i = 0; $i -lt 4 -and -not $col; $i++) {
            $col = $nat.StaticPortMappingCollection
            if (-not $col) { Start-Sleep -Milliseconds 1500 }
        }
        if ($col) {
            foreach ($p in $Ports) {
                try { $col.Remove($p, 'UDP') } catch { }
                $m = $col.Add($p, 'UDP', $p, $LanIp, $true, "Project Earth LAN $p")
                if ($m -and $m.ExternalIPAddress) { $r.UpnpIp = [string]$m.ExternalIPAddress }
            }
            $r.UpnpOk = $true
        } else {
            $r.Error = 'Der Router antwortet nicht auf UPnP (in der Router-Oberfläche ausgeschaltet?).'
        }
    } catch { $r.Error = $_.Exception.Message }
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        $r.WebIp = ([string](Invoke-RestMethod -Uri 'https://api.ipify.org' -TimeoutSec 6 -UseBasicParsing)).Trim()
    } catch { }
    [pscustomobject]$r
}

function Start-PelHostProbe([string]$LanIp) {
    $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
    $rs.ApartmentState = 'STA'
    $rs.Open()
    $ps = [System.Management.Automation.PowerShell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($script:PelHostProbeScript.ToString()).AddArgument([int[]]@($script:PelHostPort, $script:PelP2pUdpPort)).AddArgument($LanIp)
    $script:PelHostJob = [pscustomobject]@{ PS = $ps; Rs = $rs; Handle = $ps.BeginInvoke() }
    $script:PelHostState.Probing = $true
}

# Wertet das Ergebnis aus, sobald es da ist; liefert $true, wenn sich etwas geändert hat.
function Receive-PelHostProbe {
    $job = $script:PelHostJob
    if (-not $job -or -not $job.Handle.IsCompleted) { return $false }
    $res = $null
    try { $res = @($job.PS.EndInvoke($job.Handle)) | Select-Object -Last 1 } catch { }
    try { $job.PS.Dispose(); $job.Rs.Close(); $job.Rs.Dispose() } catch { }
    $script:PelHostJob = $null
    $h = $script:PelHostState
    $h.Probing = $false
    if (-not $h.Running) { return $true }
    $warn = @()
    $pub = ''
    if ($res) {
        $h.UpnpOk = [bool]$res.UpnpOk
        if ($h.UpnpOk) { $h.UpnpPorts = @($script:PelHostPort, $script:PelP2pUdpPort) }
        if (Test-PelPublicIPv4 $res.WebIp) { $pub = $res.WebIp } elseif (Test-PelPublicIPv4 $res.UpnpIp) { $pub = $res.UpnpIp }
        $cgnat = [bool]($res.UpnpIp -and ((-not (Test-PelPublicIPv4 $res.UpnpIp)) -or ($res.WebIp -and $res.UpnpIp -ne $res.WebIp)))
        $h.Cgnat = $cgnat
        if ($cgnat) {
            if ($script:PelDyn.Provider -gt 0) { $warn += "DynDNS hilft hier leider nicht: der Name würde auf eine Adresse zeigen, die dein Anbieter mit anderen Kunden teilt." }
            $warn += "Dein Router hat keine eigene öffentliche IPv4-Adresse (Router meldet $($res.UpnpIp), das Internet sieht $($res.WebIp)). Das ist typisch für DS-Lite/CGNAT bei Kabel- und Glasfaser-Anschlüssen oder einen zweiten Router davor: Freunde von außen erreichen deine Lobby dann NICHT. Der Einladungscode enthält deshalb deine LAN-Adresse und funktioniert nur im selben Heimnetz (LAN-Party). Für Online-Spiele: jemand mit normalem Anschluss hostet, oder PEL-Rendezvous.ps1 läuft auf einem kleinen Server/VPS."
            $pub = ''
            if ($h.AutoAddress -and $h.LanIp) { $h.Address = "$($h.LanIp)`:$($script:PelHostPort)" }
        }
        elseif (-not $h.UpnpOk) {
            $warn += "Automatische Portfreigabe hat nicht geklappt ($($res.Error)). Bitte im Router einmalig UDP-Port $($script:PelHostPort) und $($script:PelP2pUdpPort) an $($h.LanIp) weiterleiten (Fritz!Box: Internet -> Freigaben -> Portfreigaben)."
        }
    }
    if (-not $pub -and -not $h.Address) { $warn += "Öffentliche IP konnte nicht ermittelt werden - nutze oben eine feste Adresse (DynDNS) und starte das Hosten neu." }
    if ($pub) {
        $h.PublicIp = $pub
        try { $script:PelRvServer.PublicIp = [System.Net.IPAddress]::Parse($pub) } catch { }
        if ($h.AutoAddress) { $h.Address = "$pub`:$($script:PelHostPort)" }
        $script:PelDyn.LastIp = $pub
    }
    $h.Warning = ($warn -join "`n`n")
    Write-PelLog -Level 'HOST' -Message ("Router-Check: UPnP=" + $h.UpnpOk + ", öffentliche IP=" + $pub + $(if ($h.Warning) { " | " + ($h.Warning -replace '\s+', ' ') } else { '' }))
    return $true
}

function Start-PelHostServer {
    param([string]$Lobby, [string]$Password, [int]$DynProvider = 0, [string]$DynName = '', [string]$DynSecret = '')
    if ($script:PelHostState.Running) { return }
    Initialize-PelRvTypes
    $name = "Project Earth LAN Vermittlungsserver (UDP $($script:PelHostPort))"
    try {
        if (-not (Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue)) {
            New-NetFirewallRule -DisplayName $name -Direction Inbound -Action Allow -Protocol UDP -LocalPort $script:PelHostPort -Profile Any -ErrorAction Stop | Out-Null
        }
    } catch { Write-PelLog -Level 'HOST' -Message "Firewall-Regel: $($_.Exception.Message)" }
    Enable-PelP2pFirewall
    $srv = New-Object PelRendezvousServer
    $srv.Port = $script:PelHostPort
    $srv.MaxMembers = $script:PelHostMaxMembers
    $srv.RelayMbitTotal = $script:PelHostRelayMbitTotal
    $srv.RelayMbitPerMember = $script:PelHostRelayMbitPerMember
    try { $srv.Start() } catch { throw "Der Vermittlungsserver konnte UDP-Port $($script:PelHostPort) nicht öffnen (läuft er schon woanders?): $(Get-PelInnerMessage $_)" }
    $script:PelRvServer = $srv
    $h = $script:PelHostState
    $h.Running = $true; $h.Lobby = $Lobby; $h.Password = $Password
    $dynAddr = Get-PelDynAddress $DynProvider $DynName
    $h.Address = $dynAddr; $h.AutoAddress = (-not $dynAddr); $h.Cgnat = $false
    $h.PublicIp = ''; $h.Warning = ''; $h.UpnpOk = $false; $h.UpnpPorts = @()
    $d = $script:PelDyn
    $d.Provider = $DynProvider; $d.Name = $DynName; $d.Secret = $DynSecret; $d.LastIp = ''
    $d.LastUpdate = [DateTime]::MinValue; $d.NextCheck = [DateTime]::UtcNow; $d.Ok = $true; $d.Message = ''; $d.Resolved = ''
    $d.LastCheck = [DateTime]::MinValue; $d.Manual = $false
    $h.LanIp = Get-PelLanIpForInternet
    Start-PelHostProbe -LanIp $h.LanIp
    Write-PelLog -Level 'HOST' -Message "Vermittlungsserver gestartet (UDP $($script:PelHostPort), LAN-IP $($h.LanIp), Lobby '$Lobby')"
}

function Stop-PelHostServer {
    $h = $script:PelHostState
    if (-not $h.Running) { return }
    $h.Running = $false
    if ($script:PelRvServer) {
        $line = $null
        while ($script:PelRvServer.Log.TryDequeue([ref]$line)) { Write-PelLog -Level 'HOST' -Message $line }
        try { $script:PelRvServer.Stop() } catch { }
        $script:PelRvServer = $null
    }
    if ($script:PelHostJob) { try { $script:PelHostJob.PS.Stop(); $script:PelHostJob.PS.Dispose(); $script:PelHostJob.Rs.Close() } catch { }; $script:PelHostJob = $null }
    if ($script:PelDyn.Job) { try { $script:PelDyn.Job.PS.Stop(); $script:PelDyn.Job.PS.Dispose() } catch { }; $script:PelDyn.Job = $null }
    # Router-Freigaben wieder entfernen (nur die, die wir selbst angelegt haben)
    if ($h.UpnpPorts.Count -gt 0) {
        try {
            $col = (New-Object -ComObject HNetCfg.NATUPnP).StaticPortMappingCollection
            if ($col) { foreach ($p in $h.UpnpPorts) { try { $col.Remove([int]$p, 'UDP') } catch { } } }
        } catch { }
        $h.UpnpPorts = @()
    }
    Write-PelLog -Level 'HOST' -Message 'Vermittlungsserver beendet.'
}

# ------------------------------------------------------------------------------
# DYNDNS FÜR OPTION 9 - feste Adresse trotz täglich wechselnder öffentlicher IP
# ------------------------------------------------------------------------------
# Anbieter: 0 = keiner (öffentliche IP direkt), 1 = Router aktualisiert selbst (z. B.
# MyFRITZ!), 2 = DuckDNS (kostenlos, der Manager aktualisiert), 3 = eigene Update-URL
# (No-IP, dynv6, IPv64, ... mit {IP} als Platzhalter). Solange gehostet wird, prüft
# das Control Center alle 5 Minuten die öffentliche IP (im Hintergrund-Runspace). Ändert
# sie sich, wird der DynDNS-Eintrag aktualisiert und der Vermittlungsserver kündigt den
# Gastgeber sofort unter der neuen IP an. Die Manager der Mitspieler schlagen den Namen
# alle 5 Minuten neu nach und verbinden sich danach von selbst wieder.
$script:PelDyn = [pscustomobject]@{
    Provider = 0; Name = ''; Secret = ''; LastIp = ''; LastUpdate = [DateTime]::MinValue
    NextCheck = [DateTime]::MinValue; Job = $null; Ok = $true; Message = ''; Resolved = ''
    LastCheck = [DateTime]::MinValue; Manual = $false
}

# Adresse für den Einladungscode aus Anbieter + Name ('' = öffentliche IP verwenden)
function Get-PelDynAddress([int]$Provider, [string]$Name) {
    $n = ([string]$Name).Trim()
    if ($Provider -eq 0 -or -not $n) { return '' }
    $n = $n -replace '^(?i)https?://', ''
    $n = $n.TrimEnd('/')
    if ($Provider -eq 2) { $n = ($n -replace '(?i)\.duckdns\.org(:\d+)?$', '') + '.duckdns.org' }
    if ($n -notmatch ':\d+$') { $n = "$n`:$($script:PelHostPort)" }
    return $n
}

# Arbeitet im Runspace UND direkt (Button "Jetzt testen"): öffentliche IPv4 ermitteln,
# bei Bedarf DynDNS aktualisieren, danach prüfen, wohin der Name zeigt.
$script:PelDynWorkScript = {
    param([int]$Provider, [string]$Name, [string]$Secret, [string]$LastIp, [bool]$Force, [int]$Port)
    $r = [ordered]@{ Ip = ''; Updated = $false; Ok = $true; Message = ''; Resolved = '' }
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    foreach ($u in @('https://api.ipify.org', 'https://ipv4.icanhazip.com')) {
        try {
            $t = ([string](Invoke-RestMethod -Uri $u -TimeoutSec 6 -UseBasicParsing)).Trim()
            if ($t -match '^\d{1,3}(\.\d{1,3}){3}$') { $r.Ip = $t; break }
        } catch { }
    }
    if (-not $r.Ip) { $r.Ok = $false; $r.Message = 'Öffentliche IP nicht ermittelbar (Internet weg?)'; return [pscustomobject]$r }
    $need = $Force -or ($r.Ip -ne $LastIp)
    $hostName = ''
    if ($Provider -eq 2) {
        $dom = (([string]$Name).Trim() -replace '(?i)\.duckdns\.org(:\d+)?$', '')
        $hostName = "$dom.duckdns.org"
        if (-not $dom -or -not $Secret) { $r.Ok = $false; $r.Message = 'DuckDNS: Subdomain und Token eintragen.' }
        elseif ($need) {
            $url = "https://www.duckdns.org/update?domains=$([uri]::EscapeDataString($dom))&token=$([uri]::EscapeDataString($Secret.Trim()))&ip=$($r.Ip)"
            try {
                $resp = ([string](Invoke-RestMethod -Uri $url -TimeoutSec 10 -UseBasicParsing)).Trim()
                if ($resp -eq 'OK') { $r.Updated = $true; $r.Message = "DuckDNS aktualisiert: $hostName -> $($r.Ip)" }
                else { $r.Ok = $false; $r.Message = "DuckDNS lehnt ab ('$resp') - Subdomain oder Token falsch?" }
            } catch { $r.Ok = $false; $r.Message = "DuckDNS nicht erreichbar: $($_.Exception.Message)" }
        } else { $r.Message = "DuckDNS aktuell ($hostName -> $($r.Ip))" }
    }
    elseif ($Provider -eq 3) {
        $hostName = (([string]$Name).Trim() -replace '^(?i)https?://', '' -replace ':\d+$', '')
        if (-not $Secret -or $Secret -notmatch '^(?i)https?://') { $r.Ok = $false; $r.Message = 'Update-URL fehlt (muss mit http:// oder https:// beginnen).' }
        elseif ($need) {
            $url = $Secret.Trim().Replace('{IP}', $r.Ip).Replace('{ip}', $r.Ip)
            $headers = @{}
            # Zugangsdaten in der URL (https://benutzer:passwort@host/...) als Basic-Auth senden
            if ($url -match '^(https?://)([^/@:]+):([^/@]+)@(.+)$') {
                $pair = [uri]::UnescapeDataString($matches[2]) + ':' + [uri]::UnescapeDataString($matches[3])
                $headers['Authorization'] = 'Basic ' + [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($pair))
                $url = $matches[1] + $matches[4]
            }
            try {
                $resp = [string](Invoke-WebRequest -Uri $url -Headers $headers -UserAgent 'ProjectEarthLAN-Manager/1.0' -TimeoutSec 10 -UseBasicParsing).Content
                $short = ($resp -replace '\s+', ' ').Trim()
                if ($short.Length -gt 60) { $short = $short.Substring(0, 60) + '...' }
                if ($resp -match '(?i)\b(badauth|nohost|notfqdn|abuse|badagent|911|error|fail|ko|unauthori[sz]ed)\b') { $r.Ok = $false; $r.Message = "Anbieter meldet Fehler: $short" }
                else { $r.Updated = $true; $r.Message = "DynDNS aktualisiert ($short)" }
            } catch { $r.Ok = $false; $r.Message = "Update-URL fehlgeschlagen: $($_.Exception.Message)" }
        } else { $r.Message = "DynDNS aktuell ($($r.Ip))" }
    }
    elseif ($Provider -eq 1) {
        $hostName = (([string]$Name).Trim() -replace '^(?i)https?://', '' -replace ':\d+$', '')
        $r.Message = 'Router aktualisiert den Namen selbst.'
    }
    else { $r.Message = "Öffentliche IP: $($r.Ip)" }
    if ($hostName) {
        try {
            $a = [System.Net.Dns]::GetHostAddresses($hostName) | Where-Object { $_.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetwork } | Select-Object -First 1
            if ($a) { $r.Resolved = $a.ToString() }
        } catch { }
    }
    [pscustomobject]$r
}

function Start-PelDynCheck([bool]$Force) {
    $d = $script:PelDyn
    $ps = [System.Management.Automation.PowerShell]::Create()
    [void]$ps.AddScript($script:PelDynWorkScript.ToString()).AddArgument([int]$d.Provider).AddArgument([string]$d.Name).AddArgument([string]$d.Secret).AddArgument([string]$d.LastIp).AddArgument($Force).AddArgument([int]$script:PelHostPort)
    $d.Job = [pscustomobject]@{ PS = $ps; Handle = $ps.BeginInvoke() }
}

# Wird jede Sekunde vom Control Center aufgerufen (nur aktiv, solange gehostet wird)
# Button "Öffentliche IP jetzt aktualisieren": sofort prüfen und DynDNS zwingend melden
function Invoke-PelDynRefreshNow {
    $h = $script:PelHostState
    $d = $script:PelDyn
    if (-not $h.Running) { return 'Erst "Hosten starten" - die Aktualisierung läuft nur, solange du hostest.' }
    if ($d.Job) { return 'Eine Prüfung läuft gerade schon.' }
    $d.Manual = $true
    $d.Message = 'wird aktualisiert ...'
    Start-PelDynCheck -Force $true
    return ''
}

function Invoke-PelDynTick {
    $h = $script:PelHostState
    $d = $script:PelDyn
    if ($d.Job -and $d.Job.Handle.IsCompleted) {
        $res = $null
        try { $res = @($d.Job.PS.EndInvoke($d.Job.Handle)) | Select-Object -Last 1 } catch { }
        try { $d.Job.PS.Dispose() } catch { }
        $d.Job = $null
        if ($res -and $h.Running) {
            if ($res.Ip) {
                if ($d.LastIp -and $res.Ip -ne $d.LastIp) { Write-PelLog -Level 'HOST' -Message "Öffentliche IP gewechselt: $($d.LastIp) -> $($res.Ip)" }
                $d.LastIp = $res.Ip
                if (-not $h.Cgnat -and (Test-PelPublicIPv4 $res.Ip)) {
                    if ($h.PublicIp -ne $res.Ip) {
                        $h.PublicIp = $res.Ip
                        try { $script:PelRvServer.PublicIp = [System.Net.IPAddress]::Parse($res.Ip) } catch { }
                    }
                    if ($h.AutoAddress) { $h.Address = "$($res.Ip)`:$($script:PelHostPort)" }
                }
            }
            if ($res.Updated -and $res.Ok) { $d.LastUpdate = [DateTime]::UtcNow }
            if ($res.Message -and $res.Message -ne $d.Message -and ($res.Updated -or -not $res.Ok)) { Write-PelLog -Level 'HOST' -Message "DynDNS: $($res.Message)" }
            $d.Ok = [bool]$res.Ok; $d.Message = [string]$res.Message; $d.Resolved = [string]$res.Resolved
            $d.LastCheck = [DateTime]::Now
            if ($d.Manual) { Write-PelLog -Level 'HOST' -Message "Manuelle IP-Aktualisierung: $($res.Ip) | $($res.Message)"; $d.Manual = $false }
            $d.NextCheck = if ($res.Ok) { [DateTime]::UtcNow.AddMinutes(5) } else { [DateTime]::UtcNow.AddMinutes(1) }
        }
    }
    if ($h.Running -and -not $d.Job -and -not $h.Probing -and [DateTime]::UtcNow -ge $d.NextCheck) {
        # Alle 6 Stunden auch ohne IP-Wechsel melden (manche Anbieter löschen sonst ungenutzte Namen)
        $force = ([DateTime]::UtcNow - $d.LastUpdate).TotalHours -ge 6
        Start-PelDynCheck -Force $force
    }
}

# ==============================================================================
# OPTION 10: ANLEITUNG & FAQ (Datei auf dem Desktop)
# ==============================================================================
# Erklärt alle Optionen für Einsteiger, LAN-Partys, Orgas und Online-LAN-Gaming.
# Beim Ändern von Funktionen bitte auch diesen Text anpassen. Platzhalter:
# {VERSION} und {DATUM} werden beim Erstellen ersetzt.
$script:PelHelpText = @'
==============================================================================
  PROJECT EARTH LAN MANAGER - ANLEITUNG & FAQ
  Version {VERSION}  -  erstellt am {DATUM}
==============================================================================

Diese Datei erklärt alle Funktionen des Managers - für Einsteiger, für
LAN-Partys vor Ort, für Veranstalter (Orgas) und für Online-LAN-Gaming über
das Internet. Am Ende stehen häufige Fragen (FAQ) und Lösungen für Probleme.

Tipp: Mit Strg+F kannst du in dieser Datei nach einem Stichwort suchen.


INHALT
------
  1.  Was ist der Project Earth LAN Manager?
  2.  Schnellstart in 3 Minuten
  3.  Das Control Center (Hauptfenster)
  4.  Das P2P-Netzwerk einfach erklärt
  5.  Alle Optionen im Überblick (1 bis 11)
  6.  LAN-Party vor Ort
  7.  Für Veranstalter (Orgas)
  8.  Online-LAN-Gaming über das Internet
  9.  Rechte: Owner, Moderatoren, Admins
  10. Ports und Dateien (Übersicht)
  11. FAQ - häufige Fragen
  12. Probleme lösen (Fehlerbehebung)
  13. Sicherheit & Datenschutz
  14. Hilfe holen


==============================================================================
1. WAS IST DER PROJECT EARTH LAN MANAGER?
==============================================================================

Ein Programm für Windows, das alte und neue Spiele mit LAN-Modus wieder
gemeinsam spielbar macht - im selben Raum oder über das Internet, als wärt
ihr per Kabel verbunden.

Das Wichtigste auf einen Blick:
  - Eigenes Netzwerk (P2P) eingebaut: kein ZeroTier, Hamachi oder anderes
    VPN nötig, keine Anmeldung bei fremden Diensten.
  - Findet deine LAN-Spiele und merkt sie sich in der Spielebibliothek.
  - Matchmaking: Mitspieler finden, faire Teams, Bereit-Check, Wertung.
  - Server-Browser: zeigt Spieleserver im Netz und verbindet dich mit Klick.
  - Chat, Sprachchat, Dateien senden, Postfach und Freundesliste.
  - Spieleabend-Planer mit Erinnerung.
  - Intranet für LAN-Partys: eigene Seite per Baukasten oder Vorlage -
    oder das Intranet des Veranstalters direkt im Manager.

Warum es das gibt: Das Tool will nichts ersetzen. Discord, Steam und
TeamSpeak sind gut, und wer sie mag, soll sie weiter nutzen. Es ist für
alle, die einfach mal wieder zusammen spielen wollen, ohne sich erst durch
Anmeldungen und Einstellungen zu klicken. Kein Konto, keine Werbung, keine
fremden Dienste - ein Hobbyprojekt aus Liebe zu LAN-Games.

Der Manager braucht Administratorrechte (für den virtuellen Netzwerkadapter
und die Windows-Firewall). Die Abfrage erscheint beim Start automatisch.

Sprache: Der Button "Sprache" oben links im Control Center schaltet zwischen
Deutsch und Englisch um (der Manager startet dafür einmal neu). Direkt
daneben schaltet der Button "Autostart" den Start mit Windows an und aus.


==============================================================================
2. SCHNELLSTART IN 3 MINUTEN
==============================================================================

Es gibt drei Wege. Such dir den passenden aus:

A) JEMAND HAT DIR EINEN EINLADUNGSCODE GESCHICKT (am einfachsten)
   1. Den Code komplett kopieren (er beginnt mit PEL1:).
   2. Manager starten. Im Control Center in der Box "P2P-Netzwerk (Lobby)"
      auf "Einladung einfügen" klicken.
   3. Fertig. Nach wenigen Sekunden steht dort "Verbunden" und deine
      Mitspieler erscheinen in der Liste.
   Der Manager merkt sich alles und tritt beim nächsten Start von selbst bei.

B) DU WILLST SELBST EINE LOBBY AUFMACHEN (Gastgeber)
   1. Option 9 "Eigene Lobby hosten" öffnen.
   2. Lobby-Name und Passwort sind schon ausgefüllt - einfach
      "Hosten starten" klicken.
   3. "Einladung kopieren" und den Code an deine Freunde schicken
      (Discord, WhatsApp, Mail ...).
   Wichtig: Dein Control Center muss dafür offen bleiben. Mehr dazu in
   Kapitel 8.

C) EURE GRUPPE HAT EINEN FESTEN SERVER
   1. In der P2P-Box Vermittlungsserver, Lobby-Name und Passwort eintragen
      (bekommst du vom Betreiber) und "Beitreten" klicken.
   2. Haken bei "Beim Start automatisch beitreten" setzen.

Danach: Spiel starten und im Spiel die LAN-Suche benutzen - oder Option 5
(Server-Browser) bzw. "Mitspielen" im Control Center.


==============================================================================
3. DAS CONTROL CENTER (HAUPTFENSTER)
==============================================================================

Das Control Center ist das Fenster, das beim Start erscheint. Es sollte
während des Spielens offen bleiben (minimieren ist ok) - hier laufen das
P2P-Netzwerk, das Postfach und der Live-Status. Pro PC gibt es immer nur
ein Control Center; startest du den Manager ein zweites Mal, wird das
vorhandene Fenster nach vorne geholt.

INFOBEREICH (Symbol neben der Uhr)
  Der Manager hat genau EIN Symbol im Infobereich, egal wie viele Fenster
  offen sind. Minimierst du das Control Center oder ein Options-Fenster,
  verschwindet es aus der Taskleiste und läuft dort weiter.
  Ein Klick auf das Symbol (links oder rechts) zeigt ein Menü:
   - "Control Center" (fett) holt das Hauptfenster zurück.
   - "Offene Fenster": alle offenen Optionen mit Nummer und Namen, z. B.
     "4 · Turniere & Matchmaking - im Infobereich". Klick = anzeigen.
   - "Alle Fenster anzeigen", "Option öffnen" (alle Optionen, offene mit
     Haken) und "Beenden".
   - "Beim Minimieren in den Infobereich": ausschalten, wenn minimierte
     Fenster lieber normal in der Taskleiste bleiben sollen.
  Beim Darüberfahren zeigt das Symbol, wie viele Fenster gerade versteckt
  sind. Ist das Control Center zu, bekommt ein verstecktes Options-Fenster
  ausnahmsweise ein eigenes Symbol ("PEL 4 - ..."). Tipp: Windows blendet
  neue Symbole manchmal unter dem kleinen Pfeil neben der Uhr aus - dort
  einfach auf die Taskleiste ziehen, dann ist es immer sichtbar.

Oben: die Optionen 1 bis 13 (siehe Kapitel 5). Jede Option öffnet ein eigenes
Fenster, mehrere können gleichzeitig offen sein.

Die Pfeile oben rechts scrollen das Fenster, falls es nicht auf den
Bildschirm passt (z. B. Laptop oder Steam Deck).

BOX "P2P-NETZWERK (LOBBY)"
  - Vermittlungsserver, Lobby-Name, Lobby-Passwort: die Zugangsdaten.
  - "Einladung einfügen": holt einen Einladungscode aus der Zwischenablage
    (oder fragt danach) und tritt sofort bei.
  - "Einladung erstellen": macht aus den eingetragenen Daten einen Code
    für Freunde und kopiert ihn.
  - "Beitreten" / "Trennen": Verbindung starten oder beenden.
  - "Broadcast-Firewall": blockt Hintergrund-Lärm (siehe Kapitel 4).
  - Status und Virtuelle IP: deine Adresse im P2P-Netz (10.77.x.y).
  - Mitspielerliste: Name, virtuelle IP, Verbindungsart und Ping.
      Direkt      = beste Verbindung, Daten gehen direkt zum Mitspieler
      Relay       = läuft über den Vermittlungsserver (geht immer, etwas
                    mehr Ping)
      Verbinde    = Verbindung wird gerade aufgebaut
      Passwort falsch? = der Mitspieler nutzt ein anderes Lobby-Passwort

BOX "LIVE-STATUS"
  - Verbindung, eigene IP, gewählter Netzwerkadapter.
  - Freunde online: wie viele deiner Freunde gerade erreichbar sind.
  - Andere Manager im Netz: wer außer dir den Manager offen hat.
  - Nächster Spieleabend und ungelesene Nachrichten im Postfach
    (Klick darauf öffnet das Postfach).
  - "Wer spielt gerade was": zeigt, welches Spiel die anderen spielen.
    Doppelklick oder "Mitspielen" startet dasselbe Spiel und verbindet
    dich mit dem Server.
  - "Aktionen" (oder Rechtsklick auf einen Spieler in der Liste):
    - "Nachricht senden": landet in seinem Postfach (Option 7) - kommt
      auch an, wenn er gerade offline ist.
    - "In den Chat einladen" / "In den Sprachchat einladen": er bekommt
      unten rechts ein Fenster (bleibt im Vordergrund) mit einem Knopf, der
      die Kommunikationszentrale (Option 6) direkt im richtigen Bereich
      öffnet, dazu eine Sprechblase am Symbol im Infobereich. Deine eigene
      öffnet sich gleich mit.
    - "Zum Spielen einladen": Spiel auswählen, kurze Nachricht dazu. Hostest
      du das Spiel gerade oder bist auf einem Server, kann er mit einem
      Klick auf "Beitreten" direkt zu dir.
    - Unten im Live-Status steht, ob die Einladung angekommen ist.
      Einladungen erreichen nur ein geöffnetes Control Center; Nachrichten
      über das Postfach kommen immer an. Gebannte Spieler können dich nicht
      einladen, und zu viele Einladungen in kurzer Zeit werden ignoriert.
  - "Adapter wechseln": welcher Netzwerkadapter für Chat, Server-Browser
    usw. benutzt wird. Normalerweise nicht nötig - sobald du einer Lobby
    beitrittst, wird der P2P-Adapter automatisch gewählt.
  - "Spieleabend-Planer": Termine anlegen, die automatisch an alle
    verteilt werden (siehe Kapitel 7).
  - "Fehlerlog exportieren": packt alle Protokolle in eine ZIP-Datei, die
    du bei Problemen weitergeben kannst.
  - "Neue Version auf GitHub": erscheint nur, wenn es ein Update gibt.
    Öffnet die Download-Seite - der Manager aktualisiert sich nie von selbst.


==============================================================================
4. DAS P2P-NETZWERK EINFACH ERKLÄRT
==============================================================================

LAN-Spiele erwarten, dass alle Spieler im selben Netzwerk sind. Übers
Internet ist das normalerweise nicht so. Der Manager baut deshalb ein
virtuelles Netzwerk: Jeder bekommt eine Adresse wie 10.77.12.34, und für
Windows und die Spiele sieht es aus wie ein ganz normales LAN-Kabel.

WIE FINDEN SICH DIE PCS? (Vermittlungsserver)
  Ein kleiner "Vermittlungsserver" stellt die Mitspieler einander vor:
  "Spieler A ist hier erreichbar, Spieler B dort." Danach verbinden sich die
  PCs direkt miteinander (sog. Hole Punching). Der Spiel-Verkehr läuft also
  NICHT über den Server - nur wenn eine direkte Verbindung gar nicht
  klappt, springt er als Umleitung (Relay) ein.
  Der Vermittlungsserver läuft entweder
    - bei einem Spieler (Option 9 "Eigene Lobby hosten") oder
    - dauerhaft auf einem Server (Programm PEL-Rendezvous).

WAS IST EINE LOBBY?
  Eine Lobby ist ein eigenes, abgeschlossenes Netz: Lobby-Name + Passwort.
  Nur wer beides kennt, ist drin. Auf einem Vermittlungsserver können viele
  Lobbys gleichzeitig laufen, ohne sich zu sehen.

DEINE VIRTUELLE IP
  Wird automatisch vergeben und bleibt für deinen PC gleich - in jeder
  Lobby und auch nach einem Neustart. So funktionieren Freundesliste,
  Postfach und Remotedesktop dauerhaft mit derselben Adresse.

VERSCHLÜSSELUNG
  Alles im P2P-Netz ist verschlüsselt (AES-256) und gegen Fälschung
  geschützt. Der Schlüssel entsteht aus dem Lobby-Passwort - der
  Vermittlungsserver kennt ihn nicht und kann nichts mitlesen.

BROADCAST-FIREWALL
  Windows, Linux und macOS schicken ständig Suchrufe ins Netz (Drucker,
  Smart-TVs, Namensauflösung, Apps wie Spotify oder Dropbox). Im P2P-Netz
  würden die an alle Mitspieler gehen und nur Bandbreite kosten. Die
  Broadcast-Firewall verwirft sie. Die Server-Suche der Spiele ist davon
  NICHT betroffen. Einstellbar über den Button in der P2P-Box:
  Kategorien an-/abhaken, eigene Ports ergänzen, Statistik ansehen.
  Steam Remote Play (In-Home-Streaming) ist absichtlich erlaubt.

METRIK (für Neugierige)
  Der P2P-Adapter bekommt die höchste Priorität (Metrik 1). Dadurch landen
  die Server-Suchen der Spiele (Broadcasts an 255.255.255.255) im P2P-Netz
  bei deinen Mitspielern. Dein Internet (YouTube, Downloads ...) läuft
  weiterhin ganz normal über dein WLAN/LAN.


==============================================================================
5. ALLE OPTIONEN IM ÜBERBLICK
==============================================================================

OPTION 1 - TOOLS, MODS & GAMES DOWNLOADER & DATEI-SERVER
  Ein Klick auf Option 1 zeigt zwei Einträge: den Downloader und den
  eigenen Datei-Server (Teil 2 unten).
  Lädt Dateien von einem Download-Server herunter (z. B. Patches, Mods,
  Tools für alte Spiele).
  - Kategorie wählen, "Ordner und Dateien auslesen", Dateien markieren und
    "Ausgewählte Datei(en) herunterladen".
  - "Server & Freunde": eigene Server-Adresse eintragen oder die eines
    Freundes aus der Freundesliste übernehmen. Verzeichnisse können
    automatisch vom Server gelesen werden.
  - "Einladung einfügen": Code eines Freundes (beginnt mit PELF1:) aus
    seiner Option 1 einfügen - Adresse, Passwort und Kategorien werden
    automatisch übernommen. Das Passwort merkt sich der Manager
    verschlüsselt.
  - Selbst Dateien anbieten: am einfachsten mit dem eigenen Datei-Server
    (Teil 2, ein Klick).
    Profis können weiterhin Caddy in Docker nutzen (Button "Caddy/Docker
    Anleitung").

OPTION 1 (TEIL 2) - EIGENEN DATEI-SERVER HOSTEN (Downloads für Freunde)
  Biete Tools, Mods, Patches oder Spiele-Dateien direkt von deinem PC an -
  ohne Docker, ohne Caddy, ohne Portfreigabe im Router. Deine Freunde
  laden sie in Option 1 herunter.
  So geht's:
   1. Im Control Center auf Option 1 klicken -> "Eigenen Datei-Server
      hosten" (oder im Downloader unten auf "Eigener Datei-Server").
      Der Freigabe-Ordner ist schon eingetragen
      (C:\Project-Earth-Lan\Freigabe, mit "Öffnen" im Explorer anzeigen).
   2. Dateien in die Unterordner kopieren. Jeder Unterordner ist im
      Downloader eine Kategorie (Standard: Windows Tools, Mods, Games).
      Neue Unterordner = neue Kategorien.
   3. Passwort: "Neu" -> "Passwort setzen" (empfohlen).
   4. "Freigabe starten", dann "Einladung kopieren" und den Code (beginnt
      mit PELF1:) an Freunde schicken.
   5. Freunde: Option 1 -> "Einladung einfügen" -> Kategorie wählen ->
      "Ordner und Dateien auslesen" -> herunterladen.
  Gut zu wissen:
  - Erreichbar nur aus deinem Heimnetz und dem P2P-Netz (10.77.x.y).
    Anfragen aus dem Internet werden verworfen. Für Freunde außerhalb
    deines Heimnetzes müsst ihr in derselben P2P-Lobby sein.
  - Nur lesen: Niemand kann etwas hochladen, ändern oder löschen, und
    niemand kommt aus dem Freigabe-Ordner heraus.
  - Nach 8 falschen Passwörtern wird die IP für 5 Minuten gesperrt.
  - Unten im Fenster siehst du, wer gerade was herunterlädt.
  - Die Freigabe läuft, solange das Control Center offen ist. Mit
    "Beim Start des Managers automatisch freigeben" und Autostart
    (Autostart-Button oben links) ist sie immer aktiv.
  - Standard-Port TCP 9930 (änderbar). Läuft dort schon Caddy, einen
    anderen Port wählen oder Caddy beenden.
  - Freunde können die Freigabe auch im Browser öffnen:
    http://<deine-IP>:9930 (Benutzername egal, dann das Passwort).

OPTION 2 - WINDOWS REMOTEDESKTOP
  Auf einen anderen PC zugreifen (z. B. um einem Freund zu helfen).
  - "RDP Hier Aktivieren": erlaubt Remotedesktop auf DIESEM PC (Port 9870).
  - "RDP Standard Sperren": schaltet es wieder aus.
  - "RDP Konto erstellen / Passwort ändern": eigenes Benutzerkonto für
    Fernzugriffe anlegen, damit du dein Hauptpasswort nicht weitergeben
    musst.
  - Verbinden: virtuelle P2P-IP (10.77.x.y) oder LAN-IP des Ziel-PCs
    eintragen und "Verbinden" klicken.
  Hinweis: Windows Home kann nur verbinden, aber selbst nicht per
  Remotedesktop gesteuert werden (Einschränkung von Microsoft).

OPTION 3 - SPIELEBIBLIOTHEK (Spiele finden, verwalten, starten)
  Alle Spiele dieses PCs an einer Stelle. Beim Beitreten (Server-Browser,
  Kommunikationszentrale, Control Center) sucht der Manager zuerst hier -
  so startet das richtige Spiel ohne Nachfragen.
  - "Spiele scannen": durchsucht deine Festplatten nach Spielen mit
    LAN-Multiplayer (Steam, Epic, GOG, Ubisoft, EA und Spieleordner) und
    wählt die richtige Spiel-EXE (nicht Installer, Updater oder Server).
    "Eigene Listen": Whitelist, Blacklist und EXE-Korrekturen.
  - "Manuell suchen": ein bestimmtes Spiel auf allen Laufwerken suchen
    (auch versteckte Ordner) und per "Zur Spielebibliothek hinzufügen"
    übernehmen.
  - ".exe hinzufügen": die Spiel-EXE selbst auswählen.
  - "Spiel testen" (oder Doppelklick) startet das Spiel ohne Verbindung.
  - ".exe ändern", "Umbenennen" (F2), "Ordner öffnen", "Entfernen".
    Entfernen löscht nichts auf der Festplatte; ein neuer Scan nimmt das
    Spiel nicht wieder auf.
  - Von Hand bestätigte Einträge (selbst hinzugefügt, umbenannt, EXE
    geändert, beim Beitreten ausgewählt) überschreibt ein Scan nie.
  - "Direktbeitritt: Ja" = der Manager kennt die Startparameter und
    verbindet das Spiel beim Beitreten automatisch mit dem Server.
  - Haken "Verknüpfungen auf dem Desktop anlegen": legt wie früher pro
    Spiel eine Verknüpfung im Ordner "Lan Games" an. Für den Manager
    selbst nicht nötig, deshalb standardmäßig aus.
  - Beim ersten Start übernimmt die Bibliothek automatisch deine bisherigen
    Verknüpfungen, EXE-Korrekturen und beim Beitreten gewählten EXEs.
  - "Abgleichen": gleicht die Bibliothek sofort mit allen verbundenen
    Managern ab (gleiches Netz oder gleiche P2P-Lobby, das Control Center
    muss offen sein). Das passiert auch automatisch beim Start des Control
    Centers, bei jeder Änderung und alle 2 Minuten.
    Spalte "Im Netz": wie viele andere das Spiel auch haben.
    Orange Zeilen: Spiele, die andere haben und dir fehlen.
  - Automatisch aufnehmen: startest du ein Spiel, das noch nicht in der
    Bibliothek steht (z. B. gerade heruntergeladen, ohne Installation),
    trägt das Control Center es selbst ein und meldet es sofort den
    anderen. Vom Nutzer entfernte Spiele bleiben entfernt.
  - Datenschutz: beim Abgleich werden nur Spielname, EXE-Dateiname und
    Name des Spielordners verschickt - nie ein vollständiger Pfad.

OPTION 4 - TURNIERE & MATCHMAKING
  Mitspieler für ein Spiel finden, faire Teams bilden und direkt beitreten.
  Alle, die mitmachen wollen, öffnen Option 4 (im selben Netz oder in
  derselben P2P-Lobby) - die Fenster finden sich automatisch (Port 9877).
  - Spiel (aus deiner Spielebibliothek, Option 3) und Modus wählen, dann
    "Suchen". Modi: 1 gegen 1 bis 5 gegen 5, Jeder gegen jeden (4 oder 8).
  - Sind genug Spieler in derselben Warteschlange, kommt der Bereit-Check:
    30 Sekunden zum Bestätigen. Wer ablehnt oder nicht reagiert, fliegt aus
    der Warteschlange; die anderen bleiben vorne drin.
  - Teams: möglichst ausgeglichen nach Wertung (Elo, Start 1000). Wer
    "Zufällige Teams bevorzugen" wählt, stimmt für gemischte Teams.
  - "Ich kann hosten": du eröffnest das Spiel, die anderen verbinden sich
    mit deiner Adresse über "Beitreten / Spiel starten" (startet das Spiel
    aus der Bibliothek mit den richtigen Startparametern).
  - Nach dem Spiel: "Ergebnis melden"; jemand aus dem gegnerischen Team
    klickt "Ergebnis bestätigen" (oder "ablehnen"). Erst dann zählt es.
  - Die Wertung gilt pro Spiel. Jeder Manager berechnet sie selbst aus den
    bestätigten Ergebnissen - alle sehen dieselben Zahlen.
  - Koordinator: Das Fenster mit der niedrigsten IP führt die
    Warteschlangen. Geht es zu, übernimmt automatisch das nächste.
  - Vertrauen: Im P2P-Netz ist die Absender-Adresse jeder Nachricht
    abgesichert. In einem normalen LAN setzt Matchmaking voraus, dass ihr
    euren Mitspielern vertraut - ein manipulierter Manager könnte dort
    falsche Ergebnisse melden (sie zählen aber erst nach Bestätigung durch
    den Gegner).
  TURNIERE (Reiter "Turniere")
  - "Neues Turnier": Name, Spiel, Format (K.-o. bis 64 Teilnehmer oder
    Jeder gegen jeden bis 16) und Spieler pro Team (1 bis 5). Wer anlegt,
    ist Organisator.
  - Alle mit offener Option 4 sehen das Turnier und klicken "Anmelden".
    Gäste ohne Manager trägt der Organisator mit "Namen hinzufügen" ein.
  - "Turnier starten": Der Manager setzt nach Wertung (oder zufällig),
    bildet bei Teams ausgeglichene Teams und erstellt alle Spiele. Beim
    K.-o. bekommen die Besten die Freilose.
  - Ergebnis: Ein Spieler meldet ("Sieg: ..."), die Gegenseite klickt
    "Bestätigen" - erst dann zählt es. Der Organisator kann Ergebnisse
    direkt eintragen und korrigieren, solange die nächste Runde nicht
    gespielt ist. Sieger rücken automatisch weiter.
  - Jeder gegen jeden: Sieg 3 Punkte, Unentschieden 1, Tabelle unten.
  - Der Stand kommt immer vom Manager des Organisators - sein Option-4-
    Fenster muss für Anmeldungen und Ergebnisse offen sein. Turniere
    werden in matchmaking\turniere.json gespeichert und können im
    Intranet (Option 11, Block "Turnier (live)") angezeigt werden.
  Die bisherige "Manuelle Game-Suche" findest du jetzt in Option 3 unter
  "Manuell suchen".

OPTION 5 - SERVER-MANAGER & SERVER-BROWSER
  Drei Bereiche in einem Fenster:
  - Game Server Browser: findet Spieleserver im Netz (IP-Suche, ganzes
    Subnetz oder bestimmte Ports). "Join" sucht das passende Spiel auf
    deinem PC und verbindet automatisch. "IP:Port kopieren" für manuelle
    Eingabe im Spiel. Alle offenen Manager tauschen ihre Serverlisten aus.
  - Server-Manager: Dedicated-Server (eigene Spieleserver) starten,
    überwachen, neu starten und beenden, inkl. Startparameter und
    Firewall-Freigabe per Klick.
  - Server-Baukasten: Server per Klick mit Vorlagen für F.E.A.R. /
    F.E.A.R. Combat, Unreal Tournament 2004, Counter-Strike 1.6, Source
    und 2, Call of Duty 4, Quake III, Jedi Academy (normal und mit
    ClanMod), Team Fortress 2, Left 4 Dead 2, Garry's Mod, Day of
    Defeat: Source, Half-Life 2: Deathmatch und Valheim - dazu "Eigenes
    Spiel" mit freien Parametern.
    1. Spiel wählen - "Suchen" findet die Server-EXE (Spielebibliothek,
       Steam), sonst "Durchsuchen".
    2. Name, Port, Spieler, Passwort, Modus und Karte eintragen. Die
       Vorschau zeigt die fertige Startzeile.
    3. "Als .bat speichern" oder "Speichern & starten" (legt auch die
       Firewall-Regeln für die Ports an). Gespeichert wird in
       C:\Project-Earth-Lan\server; die .bat startet auch per Doppelklick.
    Gespeicherte Server stehen links und lassen sich ändern, starten und
    löschen. Gestartet wird über den Server-Manager - mit automatischem
    Neustart bei Absturz; im Server-Browser erscheint der Server wie
    gewohnt.
    Map-Rotation ("Map-Rotation ..." neben den zusätzlichen Parametern;
    für F.E.A.R., UT2004, CoD4, Quake III, CS 1.6/Source, TF2, Garry's
    Mod, DoD:S und HL2DM): links alle gefundenen Karten mit Filter,
    markieren und "Hinzufügen" (oder Doppelklick, "Alle", eigene Karte
    eintippen). Rechts die Reihenfolge festlegen - "Nach oben/unten",
    "Als Start", "Mischen" oder Einträge mit der Maus ziehen (auch von
    links an eine bestimmte Stelle). Die erste Karte ist die Startkarte,
    ab 2 Karten wird der Reihe nach rotiert und am Ende von vorne
    begonnen. Gespeichert wird die Rotation mit dem Server:
    F.E.A.R. als Mission0, Mission1 ... in der PEL_-Options-Datei,
    UT2004 als Kartenliste des Spieltyps in der PEL_-ini, CoD4 als
    sv_mapRotation in der Startzeile, Quake III als PEL_..._rotation.cfg
    in baseq3, hlds/srcds als PEL_..._mapcycle.txt (+mapcyclefile).
    Die Original-Dateien des Spiels bleiben unverändert; "Löschen"
    entfernt auch die PEL_-Rotationsdateien. Jedi Academy hat seine
    Rotation unter "server.cfg & Maps ...". Nicht möglich bei CS2,
    Left 4 Dead 2, Valheim und "Eigenes Spiel".
    Einstellungsdateien: F.E.A.R. nutzt eine Kopie seiner Options-Datei
    (ExampleServerOptions.txt oder ServerOptions0000.txt), UT2004 eine
    Kopie von UT2004.ini, Jedi Academy eine Kopie der server.cfg (bei
    ClanMod aus dem Ordner clanmod). Die Kopien beginnen mit PEL_, das
    Original bleibt unverändert; "Löschen" entfernt sie wieder. Gibt es
    keine eigene Datei, nimmt der Baukasten eine eingebaute Vorlage
    (F.E.A.R. Combat bzw. Jedi Academy mit/ohne ClanMod).
    F.E.A.R.: Die Options-Datei liegt normalerweise unter Öffentliche
    Dokumente\Monolith Productions\FEAR\ServerOptions - der Baukasten
    findet sie selbst, sonst über "Options-Datei ..." wählen. Servername,
    Spieler und Karten stehen dort im Abschnitt des Spielmodus (z. B.
    [DeathMatch]); fehlt der Abschnitt für den gewählten Modus, legt der
    Baukasten ihn an. Karten lassen sich auswählen oder eintippen
    ("Docks" wird zu Worlds\ReleaseMultiplayer\Docks). Die gewählte
    Karte wird Startkarte, die übrigen bleiben als Rotation. Die
    Kartenliste kommt aus der Options-Datei und zusätzlich direkt aus den
    Spielarchiven (*.Arch00 neben der Server-EXE und einen Ordner höher)
    sowie aus eigenen Karten unter Worlds\...Multiplayer\*.World00p.
    Jedi Academy: "server.cfg & Maps ..." öffnet alle Einstellungen der
    server.cfg, aufgebaut wie die Datei: 1. Server-Identifikation (Name
    mit Farbcodes ^1-^7, Begrüßung, Spieler, VIP-Slots, Passwörter, RCON
    mit "Zufall"), 2. Netzwerk & Performance, 3. Spielmodus und Limits,
    4. Gameplay & Lichtschwert (Waffen/Macht sperren, Machtstufe, Saber
    Locks ...), 5. Bots, dazu weitere Zeilen (z. B. ClanMod) und rechts
    die Map-Rotation. Hinweis: In Jedi Academy ist 7 = Siege und 8 = CTF.
    - "Maps im base-Ordner suchen" liest alle Karten aus den .pk3-Dateien
      (auch eigene Karten) samt Name und Spielmodi. Markieren und "In
      Rotation einfügen", Reihenfolge mit "Nach oben/unten".
    - "Map-Datei hinzufügen" wählt eine .pk3/.bsp von irgendwo und
      kopiert sie nach Rückfrage in den base-Ordner. Mitspieler brauchen
      die Karte auch (oder "Spieler dürfen fehlende Karten laden").
    - "Vorhandene server.cfg einfügen" übernimmt Werte, weitere Zeilen und
      Rotation aus einer fertigen Datei. "Vorschau / speichern unter"
      zeigt die fertige server.cfg und speichert sie auf Wunsch.
    - "Übernehmen" trägt Name, Spieler, Modus, Passwort und Startkarte in
      den Baukasten ein; gespeichert wird alles mit dem Server.
    Schutz vor Neustart-Schleifen: Stürzt ein Server dreimal hintereinander
    innerhalb von 30 Sekunden ab, setzt der Manager den Auto-Neustart aus
    ("Startet nicht sauber"). Zwischen den Versuchen wartet er 5, 15 bzw.
    30 Sekunden. "Neu starten" schaltet ihn wieder frei. "Stoppen"
    beendet auch Server-Prozesse, die sich von ihrer .bat gelöst haben.
  - SteamCMD (Knopf oben im Server-Baukasten): offizielle Dedicated
    Server von Steam mit einem Klick laden und aktualisieren - z. B.
    CS:Source, CS 1.6, CS2, TF2, L4D2, Garry's Mod, DoD:S, HL2DM,
    Valheim, Sven Co-op, Killing Floor 2, 7 Days to Die, Rust, ARK,
    Satisfactory, Palworld.
    1. Spiel wählen, "Installieren / Aktualisieren" klicken. Beim ersten
       Mal fragt der Manager, ob er SteamCMD direkt von Valve laden darf
       (steamcdn-a.akamaihd.net, nur steamcmd.exe wird übernommen).
    2. SteamCMD lädt den Server in einem eigenen Konsolenfenster nach
       C:\Project-Earth-Lan\steamcmd\servers\<Spiel>. Angemeldet wird
       nur anonym - kein Steam-Konto, kein Passwort. Nochmal klicken
       aktualisiert den Server bzw. setzt einen abgebrochenen Download
       fort.
    3. Wenn fertig: "Im Baukasten bauen" - Vorlage und Server-EXE sind
       schon eingetragen, du musst nur noch Name, Karte, Passwort
       wählen und speichern. Spiele ohne eigene Vorlage landen bei
       "Eigenes Spiel" (Startparameter laut Server-Doku des Spiels).
    Hinweise: CS2 ist über 30 GB groß - am besten vor der LAN laden.
    CS 1.6 (HLDS) braucht manchmal 2-3 Durchläufe. Valheim verlangt ein
    Passwort mit mindestens 5 Zeichen.
  - P2P / Text Chat (Port 9872): alle Manager im Netz finden sich
    automatisch, mit einfachem Text-Chat.

OPTION 6 - KOMMUNIKATIONSZENTRALE (Chat, Dateien, Sprachchat)
  - Chat: Gruppenchat mit allen, private Nachrichten (Teilnehmer
    auswählen), eigene Kanäle - auch dauerhaft und mit Passwort.
    "Nur Freunde" zeigt nur Nachrichten deiner Freunde.
  - Dateien senden: Ziel wählen, Datei(en) oder ganze Ordner senden.
    Mehrere parallele Verbindungen, Tempo-Limit, Fortsetzen nach Abbruch,
    Anzeige von Tempo und Restzeit.
  - Voice Chat: Kanäle erstellen, privat sprechen, Gruppen-Voice,
    Passwort-Kanäle. Mikrofon/Lautsprecher wählbar, Push-to-Talk oder
    Sprachaktivierung, Lautstärke pro Teilnehmer (Rechtsklick).
  - Rechtsklick auf einen Teilnehmer: Freund hinzufügen/entfernen,
    Anstupsen, IP kopieren, Lautstärke, IP bannen.
  - Rechtsklick auf einen dauerhaften Kanal: löschen (nur Ersteller und
    berechtigte Personen, siehe Kapitel 9). Wer noch im gelöschten Kanal
    ist, landet automatisch wieder im allgemeinen Bereich; die anderen
    Manager bekommen die Löschung sofort.
  - Chat und Voice Chat haben getrennte Kanäle: ein Kanal, den du im Chat
    erstellst, erscheint nur im Chat - und umgekehrt. Kanäle aus älteren
    Versionen gelten weiter für beide.
  - "Ingame-Overlay" (oben): zeigt über dem Spiel deinen Sprachkanal
    (grün = spricht gerade) und die letzten Chatnachrichten.
    Strg+Umschalt+O = an/aus, Strg+Umschalt+Enter = Nachricht schreiben.
    Position, Deckkraft und Anzeigedauer im Menü des Buttons.
    Sichtbar im Fenstermodus und im randlosen Vollbild; im exklusiven
    Vollbild zeichnet Windows das Spiel über alles. Das Overlay ist ein
    normales Fenster und greift nicht ins Spiel ein - keine Probleme mit
    Anti-Cheat. Die Kommunikationszentrale muss dafür offen sein
    (minimiert reicht).

OPTION 7 - FREUNDESLISTE, BANNLISTE & POSTFACH
  - Postfach: Nachrichten an andere Spieler schreiben - auch wenn sie
    gerade offline sind. Die Nachricht wird automatisch zugestellt, sobald
    der Empfänger seinen Manager startet. Ordner: Eingang, Ausgang,
    Gesendet.
  - Freundesliste: Name, IP und Notiz. "Gerade im Netzwerk" zeigt andere
    laufende Manager - Doppelklick fügt sie als Freund hinzu. Die Liste
    gehört nur dir und wird nicht verteilt.
  - Bannliste: Von gebannten IPs nimmt dein Manager nichts mehr an (Chat,
    Voice, Dateien, Postfach).
  - "Moderatoren verwalten": nur sichtbar für den Owner (siehe Kapitel 9).

OPTION 8 - KODI STREAMING
  Fernbedienung für ein Kodi im Netzwerk (auch über das P2P-Netz):
  Medien durchsuchen, abspielen, Wiedergabeliste, Lautstärke,
  Tastenkürzel. Zusätzlich kann das laufende Video lokal auf diesem PC
  mitlaufen (über VLC, wird bei Bedarf automatisch installiert).
  Adresse: IP des Kodi-PCs (z. B. seine 10.77.x.y) und Port 8080; in Kodi
  muss "Fernsteuerung über HTTP erlauben" aktiv sein.
  - Bedienknöpfe unter dem Video: Titel zurück/weiter, 10 s spulen,
    Play/Pause, Stop, Leiser, Lauter, Stumm, Schleife. Sie wirken nur
    auf die Wiedergabe auf diesem PC, nicht auf den Kodi-PC.
  - Scrubbing-Leiste (unter dem Video und im Vollbild in der unteren
    Leiste): zeigt Zeit und Gesamtlänge; Klicken oder Ziehen springt an
    die Stelle.
  - Leiste über dem Video (normales Fenster und Vollbild): erscheint bei
    Mausbewegung, verschwindet nach 3 Sekunden. Suchfeld für Filme,
    Serien, Folgen, Musik und Interpreten (Doppelklick/Enter spielt ab
    bzw. öffnet die Serie), "Medien auswählen ..." und Vollbild an/aus.
    Im Vollbild kommen die Bedienknöpfe unten dazu.
  - Medien auswählen: Doppelklick öffnet Ordner bzw. spielt ab.
    Rechtsklick: Öffnen, Ganzen Ordner abspielen, Ganzen Ordner in die
    Wiedergabeliste, Ab hier der Reihe nach abspielen, Alles in dieser
    Ansicht abspielen.

OPTION 9 - EIGENE LOBBY HOSTEN
  Macht deinen PC mit einem Klick zum Vermittlungsserver für eine Lobby.
  - Lobby-Name und Passwort (zufällig erzeugt, "Neu" für ein anderes).
  - "Feste Adresse": damit der Einladungscode gültig bleibt, auch wenn
    sich deine Internet-Adresse ändert (siehe Kapitel 8):
      Keine            - Code enthält deine aktuelle Internet-IP
      Router           - z. B. MyFRITZ!-Adresse eintragen
      DuckDNS          - kostenlos, der Manager aktualisiert selbst
      Andere DynDNS    - No-IP, dynv6, IPv64 ... über eine Update-URL
    "Jetzt testen" prüft, ob der Name auf deine aktuelle IP zeigt.
  - "Beim Start des Managers automatisch hosten".
  - "Hosten starten": startet den Server, gibt die Ports im Router frei
    (UPnP), ermittelt deine öffentliche IP und tritt selbst bei.
  - "Einladung kopieren": Code für deine Freunde.
  - "Öffentliche IP jetzt aktualisieren": sofort neu prüfen und melden.
    Automatisch passiert das alle 5 Minuten.
  - Warnhinweise erscheinen unten im Fenster (z. B. DS-Lite, fehlende
    Portfreigabe).

OPTION 10 - ANLEITUNG & FAQ
  Erstellt genau diese Datei auf deinem Desktop und öffnet sie.

OPTION 11 - INTRANET FÜR LAN-PARTYS (ansehen, erstellen, einbetten)
  Eine eigene Seite für eure LAN-Party - direkt aus dem Manager, ohne
  Webserver-Software und ohne fremde Dienste. Drei Bereiche:
  INTRANET ANSEHEN
   - Beim Öffnen sucht der Manager im Heimnetz und in deiner P2P-Lobby nach
     veröffentlichten Intranets (Port 9931). Links anklicken - fertig.
   - "Adresse eingeben": ein Intranet direkt öffnen (z. B. 10.77.0.5 oder
     http://lan.local). "Im Browser öffnen" zeigt es im normalen Browser.
   - Beim Block "Spiele-Server" gibt es "Mitspielen": startet das Spiel und
     verbindet wie im Server-Browser (Adresse auch in der Zwischenablage).
  BAUKASTEN (für Veranstalter)
   1. Vorlage wählen ("Klassische LAN-Party", "Turnier-Event", "Kleine
      Freundes-LAN", "Große LAN-Party (mit Speisekarte)") und "Vorlage
      laden" - oder mit "+ Block" selbst bauen.
   2. Name, Datum, Ort, Countdown, Akzentfarbe, Logo (Größe wählbar) und
      auf Wunsch ein eigenes Kopfbild eintragen, Blöcke
      auswählen und rechts bearbeiten. Die Vorschau zeigt sofort, was die
      anderen sehen.
   3. "Veröffentlichen". Solange Option 11 offen ist, ist das Intranet
      online (minimieren ist in Ordnung).
   Blöcke: News, Zeitplan, Spiele-Server, Spieleabende (live aus dem
   Planer), Turnier und Ergebnisse (live aus Option 4), Downloads (Dateien aus dem
   Ordner intranet\downloads), Regeln, Sitzplan, Umfrage, Bestellliste
   (z. B. Pizza), Orga-Kontakt und freier Text.
   Umfrage und Bestellliste: ein Eintrag pro PC, jederzeit änderbar. Mit
   "Stimmen / Einträge leeren" setzt du sie zurück.
  SITZPLAN & CHECK-IN
   - Block "Sitzplan & Check-in": eine Zeile pro Reihe, z. B. "A | 1-12"
     oder "C | 1-6, -, 7-12" (- = Gang). "Gesperrt: A1, B5" sperrt Plätze
     (Orga, Technik), "Info: ..." ist ein Hinweis für die Gäste.
   - Gäste wählen ihren Platz im Intranet (einer pro PC, mit Name/Nick)
     und sehen ihn unter "Dein Platz". Belegte Plätze zeigen den Namen.
   - "Check-in verwalten" (Block auswählen): am Eingang Name oder Platz
     ins Suchfeld tippen, Enter = einchecken. Außerdem: Check-in
     zurücknehmen, Platz ändern, Gast ohne PC eintragen, entfernen, CSV,
     Platzwahl für Gäste schließen/öffnen.
   - Nach dem Check-in kann der Gast seinen Platz nicht mehr selbst
     ändern - das geht dann nur noch über die Orga.
  EIGENES KOPFBILD UND LOGOS
   - "Kopfbild wählen": PNG, JPG oder GIF bis 5 MB (empfohlen etwa 1600 x
     400 Pixel). Anzeige als Banner über dem Kopfbereich oder als dessen
     Hintergrund. Steht der Name schon im Bild, blendet "Titel, Datum und
     Ort ausblenden" den Text aus - der Countdown bleibt.
   - Logo-Größe: klein, mittel oder groß.
   - Block "Logos & Sponsoren": "Bilder hinzufügen" kopiert Logos in den
     Ordner intranet\logos (bis 24 Bilder, je bis 2 MB). Optional im Inhalt
     eine Zeile pro Bild: Dateiname | Name | https://... - dann steht der
     Name darunter und das Logo ist ein Link.
   - "Export .zip" nimmt Logo, Kopfbild und Logo-Ordner mit.
  PREISLISTE (eigene Preise der Orga)
   Block "Preisliste": Du bestimmst alle Preise selbst - Eintritt, Getränke,
   Snacks, Turnier-Startgeld. Im Feld "Inhalt", eine Angabe pro Zeile:
     [Getränke]                            Kategorie
     Cola (0,5 l) | 1,50 | Pfand 0,25      Artikel | Preis | Hinweis
     Turnier-Startgeld | frei              Preis darf auch Text sein
     Info: Bezahlung bar am Orga-Tisch     Hinweis für die Gäste
     Währung: CHF                          optional, Standard ist EUR
   - Eine reine Zahl (1,50) wird mit Währung und zwei Nachkommastellen
     gezeigt, jeder andere Text unverändert (z. B. "5 EUR pro Tag").
   - Bis zu 100 Einträge. Die Preisliste ist nur zum Lesen; bestellt wird
     weiter über den Block "Bestellung mit Speisekarte" (dort stehen die
     Preise ebenfalls pro Artikel).
  BESTELLUNG MIT SPEISEKARTE (für größere LAN-Partys)
   Im Feld "Inhalt" steht die Karte, eine Angabe pro Zeile:
     [Pizza]                               Kategorie
     Margherita | 7,50 | Tomate, Mozzarella  Artikel | Preis | Beschreibung
     Info: Bestellschluss 19 Uhr           Hinweis für die Gäste
     Link: Pizzeria Roma | 06184 1234 | https://...
                                           Lieferdienst oder Lokal
     Orga: 10.77.0.5, 192.168.1.20         weitere Orga-PCs (bekommen eine
                                           Meldung bei jeder Bestellung)
   - Bis zu 200 Artikel. Gäste wählen Mengen (0-10 je Artikel), tragen
     Name, Platz und Anmerkung ein und klicken "Bestellen". Eine Bestellung
     pro PC, änderbar, bis die Orga sie auf "bestellt" setzt.
   - Neue Bestellungen erscheinen beim Veranstalter unten rechts in einem
     Meldungsfenster (sammelt alle neuen Bestellungen), bei den Orga-PCs
     aus der Zeile "Orga:" ebenso (dort muss das Control Center offen sein).
   - "Bestellungen verwalten" (Block auswählen): alle Bestellungen mit
     Summe, Status setzen (bestellt, unterwegs, abholbereit, storniert),
     "Alle neuen: bestellt", "Sammelbestellung kopieren" (alle Artikel
     zusammengezählt - zum Bestellen beim Lieferdienst), "Als CSV
     speichern" und "Bestellschluss".
   - Gäste sehen ihre eigene Bestellung mit Status unter "Deine
     Bestellung"; alle anderen sehen nur, wie viel bestellt wurde - keine
     Namen.
   - Lieferdienste und Lokale stehen als Links auf der Seite. Ist beim Ort
     etwas eingetragen, gibt es zusätzlich "Restaurants in der Nähe"
     (Karte bei OpenStreetMap). Diese Links führen ins Internet und öffnen
     sich im normalen Browser; bestellt und bezahlt wird dort bzw. über
     die Orga - der Manager selbst gibt keine Bestellung an Lieferdienste
     weiter.
  EIGENE SPEISEN & GETRÄNKE (online bestellbar oder nur vor Ort)
   Block "Bestellung mit Speisekarte" auswählen und "Speisen & Getränke"
   klicken (bei der Preisliste heißt der Button "Preise bearbeiten"). In
   der Tabelle legst du eigene Speisen und Getränke an und bestimmst die
   Preise selbst. Pro Artikel:
     Herkunft:  "Eigenes Angebot" (macht/verkauft die Orga selbst) oder
                "Lieferdienst" (wird für die Gäste bestellt)
     Verkauf:   "Online bestellbar" (Gäste bestellen im Intranet) oder
                "Nur vor Ort (Theke)" (steht mit Preis auf der Seite,
                gekauft wird an Theke/Kasse - kein Bestellfeld)
     Ausverkauft: bleibt sichtbar, ist aber nicht mehr bestellbar
   - Neue Zeilen sind automatisch "Eigenes Angebot" und "Online
     bestellbar". "Nach oben/unten", "Zeile löschen", "Übernehmen".
   - "Eigene ins Sortiment" merkt sich alle eigenen Artikel mit Preis auf
     diesem PC; "Aus Sortiment einfügen" holt sie bei der nächsten
     LAN-Party wieder in die Karte.
   - "LAN ohne Internet": blendet Lieferdienst-Links und die Restaurant-
     Karte aus. Gibt es nur eigene Artikel, entfallen sie automatisch.
     Eigene Speisen und Getränke funktionieren ganz ohne Internet.
   - "Sammelbestellung kopieren" trennt "Für den Lieferdienst" und
     "Eigenes Angebot der Orga (selbst zubereiten / Theke)".
   - Im Feld "Inhalt" steht das als 4. Feld, z. B.:
       Chili con Carne | 4,50 | selbst gekocht | eigen
       Cola 0,5 l | 2,00 | | eigen, vor Ort
       Hot Dog | 2,50 | | eigen, ausverkauft
       Internet: nein
   - Gibt es schon Bestellungen, neue Artikel unten anfügen und alte auf
     "ausverkauft" setzen - Bestellungen merken sich die Position.
   "Export .zip" / "Import .zip": Seite sichern oder an andere Orgas
   weitergeben (mit Logo, Kopfbild und Logos, ohne Downloads).
  EINSTELLUNGEN
   - "Intranet des Veranstalters einbetten": Hat die LAN-Party schon ein
     eigenes Intranet, nur dessen Adresse eintragen und veröffentlichen.
     Die Manager der Gäste zeigen dann genau diese Seite an. Erlaubt sind
     nur Adressen im lokalen Netz (private IP oder Namen wie lan.local).
   - Port (Standard TCP 9931) und "automatisch veröffentlichen".
  Gut zu wissen:
  - Erreichbar nur aus Heimnetz und P2P-Netz (10.77.x.y), nie aus dem
    Internet. Gäste können nur lesen (außer Umfrage/Bestellliste).
  - Alle Texte werden als reiner Text angezeigt: kein eigenes JavaScript,
    keine Schriften oder Skripte aus dem Internet.
  - Die Anzeige im Manager nutzt das Web-Steuerelement von Windows. Die
    eigenen Seiten sind dafür gebaut; aufwendige Veranstalter-Seiten
    sehen darin evtl. nicht perfekt aus - dann "Im Browser öffnen".
  - Andere Ports als 9931 findet die automatische Suche nicht - dann
    "Adresse eingeben" mit IP:Port.


AUTOSTART (kleiner Button oben links, neben "Sprache")
  Startet den Manager automatisch mit Windows (ca. 30 Sekunden nach der
  Anmeldung, unsichtbar im Infobereich neben der Uhr, ohne UAC-Abfrage).
  Dann sind Postfach, Live-Status,
  Spieleabend-Erinnerungen und - falls eingestellt - die Lobby immer aktiv.
  Der Button zeigt "Autostart: AN" bzw. "AUS" - nochmal klicken
  schaltet es wieder aus. Verschiebst du die Programmdatei,
  hier einmal neu einrichten.

==============================================================================
6. LAN-PARTY VOR ORT
==============================================================================

Alle sitzen im selben Raum und hängen am selben Router/Switch?

VARIANTE 1 - OHNE P2P (echtes LAN)
  Ihr seid schon in einem echten Netzwerk. Manager starten und loslegen:
  Chat, Server-Browser, Dateien senden und "Mitspielen" funktionieren
  direkt über euer LAN. Unter "Adapter wechseln" den LAN-/WLAN-Adapter
  wählen, falls ein anderer eingestellt ist.

VARIANTE 2 - MIT P2P-LOBBY (empfohlen bei gemischten Gruppen)
  Sinnvoll, wenn auch Leute von zu Hause mitspielen, oder wenn das
  Party-Netz zickt (WLAN-Isolation, mehrere Netze, Gäste-WLAN).
  Einer hostet (Option 9), alle anderen fügen den Einladungscode ein.
  Im selben Raum verbinden sich die PCs automatisch über das lokale Netz
  (Ping 1-15 ms), auch wenn der Router UPnP nicht kann.

CHECKLISTE FÜR DEN ABEND
  [ ] Alle haben dieselbe Manager-Version (GitHub-Hinweis beachten).
  [ ] Der Gastgeber hat Option 9 gestartet, der Code ist verteilt.
  [ ] In der Mitspielerliste stehen alle als "Direkt" oder "Relay".
  [ ] Spiele mit Option 3 gescannt, alle stehen in der Spielebibliothek.
  [ ] Ein Test-Ping: "ping 10.77.x.y" in der Eingabeaufforderung.
  [ ] Sprachchat in Option 6 - Mikrofon vorher einstellen.


==============================================================================
7. FÜR VERANSTALTER (ORGAS)
==============================================================================

EMPFOHLENER AUFBAU
  - Intranet (Option 11): Zeitplan, Server, Regeln, Pizza-Liste und
    Ergebnisse auf einer Seite - aus einer Vorlage in wenigen Minuten.
    Habt ihr schon ein eigenes Intranet, bettet Option 11 es ein.
  - Ein fester Vermittlungsserver (PEL-Rendezvous) auf einem Server mit
    fester IP oder einem kleinen VPS. Dann muss kein Teilnehmer etwas im
    Router einstellen, und es funktioniert auch bei DS-Lite/CGNAT.
  - Eine Lobby pro Veranstaltung, mit eigenem Passwort. Einladungscode
    über "Einladung erstellen" in der P2P-Box erzeugen und verteilen.
  - Große Gruppen: eine Lobby hat bis zu 512 Plätze. Alle Teilnehmer
    sollten dafür die aktuelle Manager-Version haben - ältere Versionen
    funktionieren in derselben Lobby, erzeugen aber viel mehr Traffic
    und sehen höchstens 255 Mitspieler.

TRAFFIC BEIM GASTGEBER / SERVER
  - Direktverbindungen (der Normalfall) laufen gar nicht über den Server.
  - Vermittlung: Der Server schickt nur Änderungen (jemand kommt, geht,
    wechselt die Adresse). Im Ruhezustand braucht er selbst bei 512
    Spielern nur ca. 20 kbit/s Upload. Kommen alle 512 nacheinander
    herein, sind das insgesamt ca. 18 MB.
  - Relay (nur Paare, bei denen beide Router zu streng sind): läuft
    doppelt über den Server. Beim Hosten zu Hause (Option 9) ist das auf
    10 Mbit/s insgesamt und 3 Mbit/s je Mitspieler begrenzt, damit dein
    Internet nutzbar bleibt. Der eigenständige Server (PEL-Rendezvous)
    ist unbegrenzt, lässt sich aber mit -RelayMbitTotal und
    -RelayMbitPerMember begrenzen.
  - Für Veranstaltungen mit Hunderten Teilnehmern ist ein kleiner VPS mit
    PEL-Rendezvous besser als ein Heimanschluss.
  - Jeder Teilnehmer hält eine Verbindung zu jedem anderen. Bei sehr
    vielen Teilnehmern sendet der Live-Status deshalb seltener (bis 128
    alle 8 s, bis 256 alle 20 s, darüber alle 30 s) - im P2P-Netz genauso
    wie auf einer LAN-Party ohne Internet.

LAN-PARTY OHNE INTERNET: WIE VIELE GEHEN?
  Im Manager gibt es offline kein Spielerlimit - Chat, Server-Browser,
  Live-Status, Dateien und Option 1 laufen direkt über euer Netzwerk.
  Die Grenze setzt das Netzwerk:
  - Ein normaler Heimrouter vergibt Adressen für ca. 250 Geräte (/24).
    Für mehr ein größeres Netz einrichten (z. B. /22 = ca. 1.000
    Adressen) - das können eigene DHCP-Server oder bessere Router.
  - Gigabit-Switches verwenden. Ab einigen Hundert PCs lohnen sich
    mehrere Switches bzw. getrennte Netze (VLANs).
  - Die Broadcast-Firewall wirkt nur im P2P-Netz; im echten LAN ist das
    Grundrauschen von Windows (Druckersuche, Namensauflösung ...) höher.

SPIELEABEND-PLANER
  Control Center -> "Spieleabend-Planer": Titel, Spiel, Datum und Uhrzeit
  eintragen. Der Termin wird automatisch an alle Manager verteilt - auch an
  Leute, die den Manager erst Tage später öffnen (es muss nur irgendein
  anderer Manager online sein, der ihn kennt).
  - Wer den Manager öffnet, bekommt eine Ankündigung, wenn ein Abend in den
    nächsten 3 Tagen ansteht, und eine Erinnerung 15 Minuten vorher.
  - Absagen kann nur der Ersteller (auf dem PC, auf dem er angelegt wurde).
  - "Eigene Spiele": Liste deiner Spiele für die Auswahl im Planer.

MODERATION
  Siehe Kapitel 9 (Moderatoren, Admins, Bannliste).

DEDICATED SERVER
  Option 5 -> Server-Manager: Server starten, überwachen und per Klick in
  der Firewall freigeben. Spieler finden den Server im Server-Browser oder
  über "Wer spielt gerade was".


==============================================================================
8. ONLINE-LAN-GAMING ÜBER DAS INTERNET
==============================================================================

WER MUSS WAS IM ROUTER EINSTELLEN?
  Nur der Betreiber des Vermittlungsservers - alle anderen NICHTS.
    - Option 9 zu Hause: Der Manager versucht die Freigabe automatisch
      (UPnP). Klappt das nicht, einmalig UDP 47810 und 47800 an deinen PC
      weiterleiten.
      Fritz!Box: Internet -> Freigaben -> Gerät -> "Selbstständige
      Portfreigaben für dieses Gerät erlauben" (dann klappt UPnP), oder
      die Ports dort von Hand freigeben.
    - PEL-Rendezvous auf einem VPS: nur UDP 47810 in dessen Firewall öffnen.

DS-LITE / CGNAT (viele Kabel- und Glasfaser-Anschlüsse)
  Dein Anschluss hat keine eigene öffentliche IPv4-Adresse. Von außen kann
  dann niemand deinen Vermittlungsserver erreichen - Option 9 zeigt dazu
  einen Hinweis. Beitreten kannst du trotzdem überall. Lösungen:
    - Jemand mit normalem Anschluss hostet.
    - PEL-Rendezvous auf einem kleinen VPS (ab ca. 1-4 EUR/Monat).
    - Beim Anbieter eine öffentliche IPv4 bzw. "Dual Stack" anfragen.

WECHSELNDE IP / ZWANGSTRENNUNG
  Viele Anschlüsse bekommen regelmäßig (oft nachts) eine neue IP. Dann
  zeigt ein Einladungscode mit der alten IP ins Leere. Lösung: eine feste
  Adresse (DynDNS) in Option 9:
    - Fritz!Box: Internet -> MyFRITZ!-Konto, Adresse (xyz.myfritz.net)
      in Option 9 bei "Router" eintragen.
    - DuckDNS (kostenlos): auf duckdns.org anmelden, Subdomain anlegen,
      Subdomain + Token in Option 9 eintragen.
  Danach einmal einen neuen Code verschicken - der bleibt dann gültig.
  Nach einem IP-Wechsel verbinden sich alle innerhalb weniger Minuten von
  selbst wieder.

DIREKT ODER RELAY?
  "Direkt" ist der Normalfall. "Relay" bedeutet: Beide Router sind so
  streng, dass keine direkte Verbindung möglich ist. Es funktioniert
  trotzdem, nur mit etwas mehr Ping. Der Manager versucht im Hintergrund
  weiter, auf "Direkt" zu wechseln.


==============================================================================
9. RECHTE: OWNER, MODERATOREN, ADMINS
==============================================================================

Dauerhafte Chat- und Voice-Kanäle darf nicht jeder löschen. Berechtigt sind:

  KANAL-ERSTELLER
    Wer den Kanal angelegt hat, darf ihn löschen (Rechtsklick auf den
    Kanal in Option 6).

  OWNER (Projektbetreiber)
    Nur auf dem PC mit der Datei C:\Project-Earth-Lan\owner.key. Beim
    Löschen fragt der Manager nach dem Owner-Passwort. Owner-Befehle sind
    digital signiert und gelten bei ALLEN Managern - unabhängig von IPs.
    Nur der Owner sieht in Option 7 "Moderatoren verwalten".

  MODERATOREN
    Vom Owner ernannt (Option 7 -> Moderatoren verwalten), wirken bei allen
    Managern. Sie werden über ihre IP erkannt - im P2P-Netz also über ihre
    virtuelle 10.77er-IP.

  GLOBALE ADMINS (pro PC)
    Jeder kann in C:\Project-Earth-Lan\AllowIP.txt (eine IP pro Zeile)
    festlegen, wessen Löschungen SEIN Manager anerkennt. Das gilt nur für
    den eigenen PC - niemand kann sich selbst zum Admin bei anderen machen.

  WICHTIG NACH DEM UMSTIEG VON ZEROTIER
    Moderatoren, AllowIP.txt, Freundes- und Bannliste und Kanal-Ersteller
    arbeiten mit IP-Adressen. Die alten ZeroTier-IPs gelten im P2P-Netz
    nicht mehr. Einmal mit den neuen 10.77er-IPs neu eintragen - diese
    bleiben danach dauerhaft gleich.


==============================================================================
10. PORTS UND DATEIEN (ÜBERSICHT)
==============================================================================

PORTS (alle werden bei Bedarf automatisch in der Windows-Firewall geöffnet)
  UDP 47800        P2P-Netzwerk (Verbindung zu den Mitspielern)
  UDP 47810        Vermittlungsserver (nur beim Gastgeber / Server)
  TCP/UDP 9872     Manager-Verbund, Server-Browser, Text-Chat (Option 5)
  UDP 9873         Sprachchat
  TCP/UDP 9874     Chat (Option 6)
  TCP/UDP 9876     Dateien senden
  TCP/UDP 9776     Abgleich von Kanälen und Owner-Befehlen
  TCP/UDP 9877     Turniere & Matchmaking (Option 4)
  UDP 9928         Live-Status und Spieleabend-Planer
  TCP 9929         Postfach
  TCP 9930         Datei-Server (Option 1 / Caddy, nur wer selbst anbietet)
  TCP 9931         Intranet (Option 11, nur wer veröffentlicht)
  TCP 9870         Remotedesktop (Option 2, nur wenn aktiviert)
  Im P2P-Netz laufen alle diese Ports automatisch durch den Tunnel -
  im Router muss dafür nichts freigegeben werden.

DATEIEN (Ordner C:\Project-Earth-Lan)
  language.txt             gewählte Sprache (de / en)
  p2p\p2p_settings.json    P2P-Einstellungen (Passwörter verschlüsselt)
  p2p\amd64\wintun.dll     Treiber für den virtuellen Netzwerkadapter
  logs\                    Protokolle (für "Fehlerlog exportieren")
  Friendlist.json          Freundesliste und Kanäle
  ip_bans.json             Bannliste
  Postfach\                Nachrichten
  events.json              Spieleabende
  selected_adapter.json    gewählter Netzwerkadapter
  downloader_server.json   Einstellungen für Option 1 (Passwort verschlüsselt)
  downloader_own_password.json  Passwort deiner Freigabe (Option 1)
  fileserver.json          Einstellungen für Option 1
  Freigabe\               Standard-Ordner für Option 1
  intranet\               Option 11: intranet.json (deine Seite), mitmachen.json
                           (Umfrage/Bestellliste), logo.*, downloads\ (Dateien
                           für die Gäste), sortiment.json (deine eigenen
                           Speisen und Getränke mit Preisen)
  willkommen_gesehen.txt   merkt sich, dass das Willkommensfenster lief
  fenster.json             Einstellung "Beim Minimieren in den Infobereich"
  matchmaking\turniere.json Turniere aus Option 4
  eigene_whitelist.txt / eigene_blacklist.txt / exe_korrekturen.txt
                           eigene Listen für Option 3
  games.json               Spielebibliothek (Option 3): Spielnamen und
                           EXE-Pfade dieses PCs, wird nie verschickt
  server\                  Server-Baukasten (Option 5): gespeicherte
                           Server als .bat und .pel.json
  steamcmd\                SteamCMD (Option 5) und die damit geladenen
                           Dedicated Server (Unterordner servers\)
  overlay.json             Ingame-Overlay (Option 6): an/aus, Position,
                           Deckkraft
  games_netz.json          Abgleich (Option 3): welche Spiele die anderen
                           Manager haben (nur Namen, keine Pfade)
  lib_sync.txt             kurzlebig: "Abgleichen" aus Option 3 an das
                           Control Center
  fileserver_open.txt      kurzlebig: "Eigener Datei-Server" aus dem
                           Downloader (Option 1) an das Control Center
  matchmaking\             Option 4: bestätigte Ergebnisse (für die
                           Wertung) und deine Einstellungen
  AllowIP.txt              optionale Admin-Liste (Kapitel 9)


==============================================================================
11. FAQ - HÄUFIGE FRAGEN
==============================================================================

Brauche ich noch ZeroTier, Hamachi oder Radmin?
  Nein. Das Netzwerk ist im Manager eingebaut. Andere VPNs können parallel
  installiert bleiben, werden aber nicht mehr gebraucht.

Kostet das etwas / brauche ich ein Konto?
  Nein. Kein Konto, keine Anmeldung. Nur wer einen eigenen VPS mietet,
  zahlt dafür beim Anbieter.

Läuft das auf dem Steam Deck?
  Ja, wenn auf dem Steam Deck Windows installiert ist. Mit SteamOS (Linux)
  läuft der Manager nicht.

Läuft das auf Mac oder Linux?
  Nein, nur Windows 10 und 11.

Warum Administratorrechte?
  Für den virtuellen Netzwerkadapter und die Firewall-Regeln. Ohne diese
  Rechte kann Windows kein Netzwerk einrichten.

Bleibt mein Einladungscode gleich?
  Ja, solange Lobby-Name, Passwort und Adresse gleich bleiben. Mit einer
  festen Adresse (DynDNS) bleibt er auch nach IP-Wechseln gültig.

Was passiert, wenn der Gastgeber den Manager schließt?
  Bestehende Verbindungen zwischen den anderen laufen weiter, aber
  niemand kann neu beitreten. Startet der Gastgeber wieder, verbinden sich
  alle automatisch neu (wenn "automatisch beitreten" aktiv ist).

Kann ich in mehreren Lobbys gleichzeitig sein?
  Nein, immer in einer. "Trennen" und dann einer anderen beitreten.

Warum bekomme ich immer dieselbe virtuelle IP?
  Absichtlich: So funktionieren Freundesliste, Postfach, Moderatoren und
  Remotedesktop dauerhaft. Nur wenn zwei PCs in einer Lobby zufällig
  dieselbe Adresse bekämen, weicht einer davon ab.

Ist mein Internet jetzt langsamer?
  Nein. Nur Verkehr an 10.77.x.y läuft durch das P2P-Netz. Alles andere
  geht wie gewohnt direkt ins Internet.

Sieht der Server-Betreiber, was wir machen?
  Nein. Er sieht nur, wer in einer Lobby ist (Name, IP). Inhalte sind
  verschlüsselt, den Schlüssel kennt nur, wer das Lobby-Passwort hat.

Ein Spiel findet die anderen in der LAN-Suche nicht.
  Siehe Kapitel 12, Punkt "Spiel findet keine Server".

Windows fragt nach "Öffentliches oder privates Netzwerk"?
  Der Manager stellt das P2P-Netz automatisch auf "Privat". Falls die
  Frage trotzdem kommt: "Privat" wählen.

Wie stelle ich die Sprache um?
  Button "Sprache" oben links im Control Center. Der Manager startet einmal
  neu.

Meldet der Virenscanner die EXE?
  Das kommt bei selbst gebauten PowerShell-Programmen leider vor (Fehlalarm).
  Lade den Manager nur von der offiziellen GitHub-Seite und vergleiche die
  Prüfsumme (.sha256.txt).


==============================================================================
12. PROBLEME LÖSEN (FEHLERBEHEBUNG)
==============================================================================

"Verbinde mit Vermittlungsserver ..." bleibt stehen
  - Adresse im Feld "Vermittlungsserver" prüfen (Tippfehler, Port).
  - Läuft beim Gastgeber das Control Center mit Option 9?
  - Gastgeber: Portfreigabe prüfen (Kapitel 8), Hinweise in Option 9
    lesen (DS-Lite?).
  - Eigene Firewall/Virenschutz: der Manager braucht Internetzugriff.

Mitspieler steht auf "Passwort falsch?"
  Lobby-Name UND Passwort müssen exakt gleich sein (Groß-/Kleinschreibung
  beim Passwort beachten). Am einfachsten den Einladungscode neu einfügen.

Mitspieler bleibt auf "Verbinde ..."
  Normalerweise wechselt er nach ca. 8 Sekunden auf "Direkt" oder "Relay".
  Wenn nicht: beide "Trennen" und neu beitreten. Hilft das nicht, war der
  Vermittlungsserver kurz weg - ein paar Sekunden warten.

Spiel findet keine Server in der LAN-Suche
  - Beide in derselben Lobby und in der Liste "Direkt"/"Relay"?
  - Das Spiel muss nach dem Beitreten gestartet werden (sonst kennt es
    den neuen Adapter nicht) - Spiel neu starten.
  - Manche Spiele suchen nur im ersten Netzwerkadapter: dann per IP
    verbinden (10.77.x.y des Hosts), Option 5 "Join" oder "Mitspielen".
  - Windows-Firewall: Beim ersten Start fragt Windows, ob das Spiel ins
    Netz darf - "Private Netzwerke" erlauben.
  - Broadcast-Firewall: Falls ein Spiel ungewöhnliche Ports nutzt, testweise
    ausschalten.

Hoher Ping / Ruckeln
  - Steht der Mitspieler auf "Relay"? Dann läuft alles über den Server.
    Gastgeber: UPnP/Portfreigabe für UDP 47800 hilft oft.
  - WLAN statt Kabel? Downloads im Hintergrund?

"Das P2P-Netzwerk konnte nicht gestartet werden"
  - Manager als Administrator gestartet?
  - Die Meldung nennt den Grund. Beim ersten Start wird der Treiber
    (Wintun) geladen - dafür wird kurz Internet gebraucht.
  - Manager komplett schließen (auch aus der Taskleiste) und neu starten.

Nach dem Trennen funktionieren Chat/Server-Browser nicht mehr
  Control Center -> "Adapter wechseln" -> deinen normalen LAN-/WLAN-Adapter
  wählen. (Passiert normalerweise automatisch.)

Postfach-Nachricht kommt nicht an
  Der Empfänger muss seinen Manager einmal starten. Nachrichten bleiben
  so lange im Ausgang und werden dann automatisch zugestellt.


==============================================================================
13. SICHERHEIT & DATENSCHUTZ
==============================================================================

  - Alle Daten bleiben auf deinem PC (Ordner C:\Project-Earth-Lan).
    Freundes- und Bannliste werden nie verteilt.
  - Passwörter und Tokens werden mit Windows verschlüsselt gespeichert
    (nur für dein Windows-Benutzerkonto lesbar).
  - Der Einladungscode enthält das Lobby-Passwort: nur an Mitspieler
    schicken, nicht öffentlich posten. Ein neues Passwort macht alte
    Codes ungültig.
  - Alle in einer Lobby sind gleichberechtigt, wie in einem echten LAN.
    Gib freigegebene Ordner und Remotedesktop nur für Leute frei, denen du
    vertraust.
  - Der Manager lädt keine Updates von selbst. Neue Versionen gibt es nur
    auf GitHub.
  - Der Fehlerlog-Export enthält IP-Adressen und den Computernamen, aber
    keine Chats, Nachrichten oder Passwörter.


==============================================================================
14. HILFE HOLEN
==============================================================================

  1. Control Center -> "Fehlerlog exportieren". Die ZIP-Datei landet auf
     dem Desktop.
  2. Beschreibe kurz, was du gemacht hast und was passiert ist
     (Screenshot hilft).
  3. Projektseite und neueste Version:
     https://github.com/Firehawk215/Project-Earth-Lan

Viel Spaß beim Zocken!
'@

$script:PelHelpTextEn = @'
==============================================================================
  PROJECT EARTH LAN MANAGER - GUIDE & FAQ
  Version {VERSION}  -  created on {DATUM}
==============================================================================

This file explains all functions of the manager - for beginners, for LAN
parties on site, for organizers and for online LAN gaming over the
internet. At the end you will find frequently asked questions (FAQ) and
solutions for problems.

Tip: press Ctrl+F to search this file for a keyword.


CONTENTS
--------
  1.  What is the Project Earth LAN Manager?
  2.  Quick start in 3 minutes
  3.  The Control Center (main window)
  4.  The P2P network explained simply
  5.  All options at a glance (1 to 11)
  6.  LAN party on site
  7.  For organizers
  8.  Online LAN gaming over the internet
  9.  Permissions: owner, moderators, admins
  10. Ports and files (overview)
  11. FAQ - frequently asked questions
  12. Troubleshooting
  13. Security & privacy
  14. Getting help


==============================================================================
1. WHAT IS THE PROJECT EARTH LAN MANAGER?
==============================================================================

A Windows program that makes old and new games with a LAN mode playable
together again - in the same room or over the internet, as if you were
connected by cable.

The most important points at a glance:
  - Its own network (P2P) is built in: no ZeroTier, Hamachi or other VPN
    needed, no sign-up with third-party services.
  - Finds your LAN games and keeps them in the game library.
  - Matchmaking: find players, fair teams, ready check, ratings.
  - Server browser: shows game servers on the network and connects you
    with one click.
  - Chat, voice chat, file transfer, mailbox and friends list.
  - Game night planner with reminders.
  - Intranet for LAN parties: your own page from the builder or a
    template - or the organizer's intranet right inside the manager.

Why this exists: the tool does not want to replace anything. Discord,
Steam and TeamSpeak are good, and if you like them, keep using them. It
is for everyone who simply wants to play together again without clicking
through sign-ups and settings first. No account, no ads, no third-party
services - a hobby project for the love of LAN games.

The manager needs administrator rights (for the virtual network adapter
and the Windows firewall). The prompt appears automatically at startup.

Language: the button "Language" at the top left of the Control Center
switches between German and English (the manager restarts once). Right
next to it the button "Autostart" turns starting with Windows on and off.


==============================================================================
2. QUICK START IN 3 MINUTES
==============================================================================

There are three ways. Pick the one that fits:

A) SOMEONE SENT YOU AN INVITE CODE (easiest)
   1. Copy the whole code (it starts with PEL1:).
   2. Start the manager. In the Control Center, in the box
      "P2P network (lobby)", click "Paste invite".
   3. Done. After a few seconds it says "Connected" and your
      fellow players appear in the list.
   The manager remembers everything and rejoins automatically next time.

B) YOU WANT TO OPEN YOUR OWN LOBBY (host)
   1. Open option 9 "Host your own lobby".
   2. Lobby name and password are already filled in - just click
      "Start hosting".
   3. Click "Copy invite" and send the code to your friends
      (Discord, WhatsApp, e-mail ...).
   Important: your Control Center must stay open for this. More about
   this in chapter 8.

C) YOUR GROUP HAS A PERMANENT SERVER
   1. In the P2P box, enter relay server, lobby name and password
      (you get them from the operator) and click "Join".
   2. Tick "Join automatically at startup".

After that: start the game and use the game's LAN search - or option 5
(server browser) or "Join game" in the Control Center.


==============================================================================
3. THE CONTROL CENTER (MAIN WINDOW)
==============================================================================

The Control Center is the window that appears at startup. It should stay
open while you play (minimizing is fine) - the P2P network, the mailbox
and the live status run here. There is always only one Control Center per
PC; if you start the manager a second time, the existing window is
brought to the front.

NOTIFICATION AREA (icon next to the clock)
  The manager has exactly ONE icon in the notification area, no matter
  how many windows are open. When you minimize the Control Center or an
  option window, it leaves the taskbar and keeps running there.
  Clicking the icon (left or right) shows a menu:
   - "Control Center" (bold) brings the main window back.
   - "Open windows": all open options with number and name, e.g.
     "4 · Tournaments & matchmaking - in the notification area".
     Click = show.
   - "Show all windows", "Open option" (all options, open ones ticked)
     and "Exit".
   - "Minimize to the notification area": turn it off if minimized
     windows should stay in the taskbar as usual.
  Hovering over the icon shows how many windows are hidden. If the
  Control Center is closed, a hidden option window gets its own icon as
  an exception ("PEL 4 - ..."). Tip: Windows sometimes tucks new icons
  away under the small arrow next to the clock - drag it onto the taskbar
  so it is always visible.

At the top: options 1 to 13 (see chapter 5). Each option opens its own
window, several can be open at the same time.

The arrows at the top right scroll the window if it does not fit on the
screen (e.g. laptop or Steam Deck).

BOX "P2P NETWORK (LOBBY)"
  - Relay server, lobby name, lobby password: the access data.
  - "Paste invite": takes an invite code from the clipboard (or asks for
    it) and joins immediately.
  - "Create invite": turns the entered data into a code for friends and
    copies it.
  - "Join" / "Disconnect": start or end the connection.
  - "Broadcast firewall": blocks background noise (see chapter 4).
  - Status and virtual IP: your address in the P2P network (10.77.x.y).
  - Player list: name, virtual IP, connection type and ping.
      Direct      = best connection, data goes straight to the player
      Relay       = runs via the relay server (always works, slightly
                    higher ping)
      Connecting  = connection is being established
      Wrong password? = the player uses a different lobby password

BOX "LIVE STATUS"
  - Connection, own IP, selected network adapter.
  - Friends online: how many of your friends are reachable right now.
  - Other managers on the network: who else has the manager open.
  - Next game night and unread messages in the mailbox (click to open
    the mailbox).
  - "Who is playing what right now": shows which game the others are
    playing. Double-click or "Join game" starts the same game and
    connects you to the server.
  - "Actions" (or right-click a player in the list):
    - "Send message": ends up in their mailbox (option 7) - also arrives
      if they are offline right now.
    - "Invite to chat" / "Invite to voice chat": they get a window at the
      bottom right (stays on top) with a button that opens the
      communication center (option 6) directly in the right section, plus
      a balloon at the icon in the notification area. Yours opens as well.
    - "Invite to play": choose a game, add a short message. If you are
      hosting the game or playing on a server, they can join you with
      one click on "Join".
    - The bottom of the live status shows whether the invitation arrived.
      Invitations only reach an open Control Center; messages via the
      mailbox always arrive. Banned players cannot invite you, and too
      many invitations in a short time are ignored.
  - "Change adapter": which network adapter is used for chat, server
    browser etc. Usually not needed - as soon as you join a lobby, the
    P2P adapter is selected automatically.
  - "Game night planner": create dates that are distributed to everyone
    automatically (see chapter 7).
  - "Export error log": packs all logs into a ZIP file you can pass on
    if there are problems.
  - "New version on GitHub": only appears when there is an update. Opens
    the download page - the manager never updates itself.


==============================================================================
4. THE P2P NETWORK EXPLAINED SIMPLY
==============================================================================

LAN games expect all players to be in the same network. Over the internet
that is normally not the case. So the manager builds a virtual network:
everyone gets an address like 10.77.12.34, and to Windows and the games
it looks like a completely normal LAN cable.

HOW DO THE PCS FIND EACH OTHER? (relay server)
  A small "relay server" introduces the players to each other:
  "Player A can be reached here, player B there." After that the PCs
  connect directly to each other (so-called hole punching). The game
  traffic does NOT go through the server - only if a direct connection
  is not possible at all does it step in as a detour (relay).
  The relay server runs either
    - at one of the players (option 9 "Host your own lobby") or
    - permanently on a server (program PEL-Rendezvous).

WHAT IS A LOBBY?
  A lobby is its own closed network: lobby name + password. Only those
  who know both are in. Many lobbies can run on one relay server at the
  same time without seeing each other.

YOUR VIRTUAL IP
  Is assigned automatically and stays the same for your PC - in every
  lobby and after a restart. That way the friends list, mailbox and
  Remote Desktop keep working with the same address.

ENCRYPTION
  Everything in the P2P network is encrypted (AES-256) and protected
  against tampering. The key is derived from the lobby password - the
  relay server does not know it and cannot read anything.

BROADCAST FIREWALL
  Windows, Linux and macOS constantly send discovery calls into the
  network (printers, smart TVs, name resolution, apps like Spotify or
  Dropbox). In the P2P network they would go to all players and only
  cost bandwidth. The broadcast firewall drops them. Game server
  discovery is NOT affected. Configurable via the button in the P2P box:
  tick/untick categories, add your own ports, view statistics.
  Steam Remote Play (In-Home Streaming) is intentionally allowed.

METRIC (for the curious)
  The P2P adapter gets the highest priority (metric 1). This way the
  games' server searches (broadcasts to 255.255.255.255) end up in the
  P2P network with your fellow players. Your internet (YouTube,
  downloads ...) keeps running normally via your Wi-Fi/LAN.


==============================================================================
5. ALL OPTIONS AT A GLANCE
==============================================================================

OPTION 1 - TOOLS, MODS & GAMES DOWNLOADER & FILE SERVER
  A click on option 1 shows two entries: the downloader and your own
  file server (part 2 below).
  Downloads files from a download server (e.g. patches, mods, tools for
  old games).
  - Choose a category, "Read folders and files", select files and
    "Download selected file(s)".
  - "Server & friends": enter your own server address or take over the
    one of a friend from the friends list. Directories can be read
    automatically from the server.
  - "Paste invite": paste a friend's code (starts with PELF1:) from their
    option 1 - address, password and categories are filled in
    automatically. The manager remembers the password encrypted.
  - Offer files yourself: easiest with your own file server (part 2,
    one click). Advanced
    users can still use Caddy in Docker (button "Caddy/Docker guide").

OPTION 1 (PART 2) - HOST YOUR OWN FILE SERVER (downloads for friends)
  Offer tools, mods, patches or game files directly from your PC - no
  Docker, no Caddy, no port forwarding in the router. Your friends
  download them in option 1.
  How it works:
   1. In the Control Center click option 1 -> "Host your own file
      server" (or in the downloader at the bottom "Own file server").
      The shared folder is already filled in
      (C:\Project-Earth-Lan\Freigabe, "Open" shows it in Explorer).
   2. Copy files into the subfolders. Each subfolder is a category in the
      downloader (default: Windows Tools, Mods, Games). New subfolders =
      new categories.
   3. Password: "New" -> "Set password" (recommended).
   4. "Start sharing", then "Copy invite" and send the code (starts with
      PELF1:) to your friends.
   5. Friends: option 1 -> "Paste invite" -> choose a category ->
      "Read folders and files" -> download.
  Good to know:
  - Reachable only from your home network and the P2P network
    (10.77.x.y). Requests from the internet are dropped. Friends outside
    your home network must be in the same P2P lobby.
  - Read-only: nobody can upload, change or delete anything, and nobody
    can get out of the shared folder.
  - After 8 wrong passwords the IP is blocked for 5 minutes.
  - At the bottom of the window you can see who is downloading what.
  - Sharing runs as long as the Control Center is open. With "Share
    automatically when the manager starts" and autostart (autostart button at the top left) it
    is always active.
  - Default port TCP 9930 (can be changed). If Caddy is already running
    there, choose a different port or stop Caddy.
  - Friends can also open the share in a browser:
    http://<your-IP>:9930 (any user name, then the password).

OPTION 2 - WINDOWS REMOTE DESKTOP
  Access another PC (e.g. to help a friend).
  - "Enable RDP here": allows Remote Desktop on THIS PC (port 9870).
  - "Disable RDP (default)": turns it off again.
  - "Create RDP account / change password": create your own user account
    for remote access so you don't have to share your main password.
  - Connect: enter the virtual P2P IP (10.77.x.y) or LAN IP of the
    target PC and click "Connect".
  Note: Windows Home can only connect, but cannot be controlled via
  Remote Desktop itself (Microsoft limitation).

OPTION 3 - GAME LIBRARY (find, manage, launch games)
  All games on this PC in one place. When joining (server browser,
  communication center, Control Center) the manager looks here first -
  so the right game starts without asking.
  - "Scan games": searches your drives for games with LAN multiplayer
    (Steam, Epic, GOG, Ubisoft, EA and game folders) and picks the
    correct game EXE (not installers, updaters or servers).
    "Own lists": whitelist, blacklist and EXE corrections.
  - "Search manually": search all drives for a specific game (including
    hidden folders) and add it with "Add to game library".
  - "Add .exe": pick the game EXE yourself.
  - "Test game" (or double-click) starts the game without connecting.
  - "Change .exe", "Rename" (F2), "Open folder", "Remove".
    Remove deletes nothing on the disk; a new scan will not add the game
    again.
  - Entries you confirmed yourself (added, renamed, EXE changed, picked
    when joining) are never overwritten by a scan.
  - "Direct join: Yes" = the manager knows the start parameters and
    connects the game to the server automatically when joining.
  - Checkbox "Create shortcuts on the desktop": as before, one shortcut
    per game in the "Lan Games" folder. Not needed by the manager
    itself, so it is off by default.
  - On first start the library automatically takes over your previous
    shortcuts, EXE corrections and EXEs picked when joining.
  - "Sync": syncs the library with all connected managers right away
    (same network or same P2P lobby, the Control Center must be open).
    This also happens automatically when the Control Center starts, on
    every change and every 2 minutes.
    Column "In network": how many others have the game too.
    Orange rows: games others have and you are missing.
  - Added automatically: if you start a game that is not in the library
    yet (e.g. just downloaded, no installation), the Control Center adds
    it by itself and tells the others right away. Games you removed stay
    removed.
  - Privacy: syncing only sends the game name, the EXE file name and the
    name of the game folder - never a full path.

OPTION 4 - TOURNAMENTS & MATCHMAKING
  Find players for a game, build fair teams and join directly. Everyone
  who wants to take part opens option 4 (in the same network or the same
  P2P lobby) - the windows find each other automatically (port 9877).
  - Choose a game (from your game library, option 3) and a mode, then
    "Search". Modes: 1 vs 1 up to 5 vs 5, free for all (4 or 8).
  - When enough players are in the same queue, the ready check starts:
    30 seconds to confirm. Whoever declines or does not respond leaves the
    queue; the others stay at the front.
  - Teams: as balanced as possible by rating (Elo, start 1000). Choosing
    "Prefer random teams" is a vote for mixed teams.
  - "I can host": you open the game, the others connect to your address
    with "Join / start game" (starts the game from the library with the
    right start parameters).
  - After the game: "Report result"; someone from the opposing team clicks
    "Confirm result" (or "reject"). Only then does it count.
  - Ratings are per game. Every manager calculates them itself from the
    confirmed results - everyone sees the same numbers.
  - Coordinator: the window with the lowest IP runs the queues. If it
    closes, the next one takes over automatically.
  - Trust: in the P2P network the sender address of every message is
    secured. In a normal LAN, matchmaking assumes you trust your fellow
    players - a manipulated manager could report wrong results there (they
    only count after the opponent confirms).
  TOURNAMENTS ("Tournaments" tab)
  - "New tournament": name, game, format (knockout up to 64 participants
    or round robin up to 16) and players per team (1 to 5). Whoever
    creates it is the organizer.
  - Everyone with option 4 open sees the tournament and clicks "Sign up".
    The organizer adds guests without the manager with "Add name".
  - "Start tournament": the manager seeds by rating (or randomly), forms
    balanced teams if needed and creates all games. In knockout the best
    get the byes.
  - Result: one player reports ("Win: ..."), the other side clicks
    "Confirm" - only then it counts. The organizer can enter and correct
    results directly as long as the next round has not been played.
    Winners advance automatically.
  - Round robin: win 3 points, draw 1, table at the bottom.
  - The status always comes from the organizer's manager - their option 4
    window has to be open for sign-ups and results. Tournaments are saved
    in matchmaking\turniere.json and can be shown in the intranet
    (option 11, block "Tournament (live)").
  The former "Manual game search" is now in option 3 under "Search
  manually".

OPTION 5 - SERVER MANAGER & SERVER BROWSER
  Three areas in one window:
  - Game server browser: finds game servers on the network (IP search,
    whole subnet or specific ports). "Join" looks for the matching game
    on your PC and connects automatically. "Copy IP:port" for manual
    entry in the game. All open managers exchange their server lists.
  - Server manager: start, monitor, restart and stop dedicated servers
    (your own game servers), including start parameters and firewall
    rules with one click.
  - Server builder: servers with one click, with templates for F.E.A.R. /
    F.E.A.R. Combat, Unreal Tournament 2004, Counter-Strike 1.6, Source
    and 2, Call of Duty 4, Quake III, Jedi Academy (plain and with
    ClanMod), Team Fortress 2, Left 4 Dead 2, Garry's Mod, Day of
    Defeat: Source, Half-Life 2: Deathmatch and Valheim - plus "Own
    game" with free parameters.
    1. Pick the game - "Find" locates the server EXE (game library,
       Steam), otherwise "Browse".
    2. Enter name, port, players, password, mode and map. The preview
       shows the finished command line.
    3. "Save as .bat" or "Save & start" (also creates firewall rules for
       the ports). Saved to C:\Project-Earth-Lan\server; the .bat also
       starts by double-click.
    Saved servers are listed on the left and can be edited, started and
    deleted. Starting runs through the server manager - with automatic
    restart after a crash; the server shows up in the server browser as
    usual.
    Map rotation ("Map rotation ..." next to the additional parameters;
    for F.E.A.R., UT2004, CoD4, Quake III, CS 1.6/Source, TF2, Garry's
    Mod, DoD:S and HL2DM): all found maps on the left with a filter,
    select them and click "Add" (or double-click, "All", type a custom
    map). Set the order on the right - "Up/Down", "As start", "Shuffle"
    or drag entries with the mouse (also from the left to a specific
    position). The first map is the start map, from 2 maps on the server
    rotates in order and starts over at the end. The rotation is saved
    with the server: F.E.A.R. as Mission0, Mission1 ... in the PEL_
    options file, UT2004 as the map list of the game type in the PEL_
    ini, CoD4 as sv_mapRotation in the command line, Quake III as
    PEL_..._rotation.cfg in baseq3, hlds/srcds as PEL_..._mapcycle.txt
    (+mapcyclefile). The game's original files stay unchanged; "Delete"
    also removes the PEL_ rotation files. Jedi Academy has its rotation
    under "server.cfg & maps ...". Not available for CS2, Left 4 Dead 2,
    Valheim and "Own game".
    Settings files: F.E.A.R. uses a copy of its options file
    (ExampleServerOptions.txt or ServerOptions0000.txt), UT2004 a copy of
    UT2004.ini, Jedi Academy a copy of server.cfg (with ClanMod from the
    clanmod folder). The copies start with PEL_, the original stays
    unchanged; "Delete" removes them again. Without an own file the
    builder uses a built-in template (F.E.A.R. Combat or Jedi Academy
    with/without ClanMod).
    F.E.A.R.: the options file normally lives in Public Documents\
    Monolith Productions\FEAR\ServerOptions - the builder finds it by
    itself, otherwise pick it via "Options file ...". Server name, players
    and maps are stored in the section of the game mode (e.g.
    [DeathMatch]); if the section for the chosen mode is missing, the
    builder adds it. Maps can be picked or typed ("Docks" becomes
    Worlds\ReleaseMultiplayer\Docks). The chosen map becomes the start
    map, the others stay as rotation. The map list comes from the
    options file and also directly from the game archives (*.Arch00 next
    to the server EXE and one folder up) and from custom maps under
    Worlds\...Multiplayer\*.World00p.
    Jedi Academy: "server.cfg & maps ..." opens all settings of the
    server.cfg, laid out like the file: 1. server identification (name
    with colour codes ^1-^7, message of the day, players, VIP slots,
    passwords, RCON with "Random"), 2. network & performance, 3. game
    mode and limits, 4. gameplay & saber (disable weapons/force, force
    rank, saber locks ...), 5. bots, plus more lines (e.g. ClanMod) and
    the map rotation on the right. Note: in Jedi Academy 7 = Siege and
    8 = CTF.
    - "Search maps in base folder" reads all maps from the .pk3 files
      (custom maps too) with name and game modes. Select them and click
      "Insert into rotation", order with "Up/Down".
    - "Add map file" picks a .pk3/.bsp from anywhere and copies it into
      the base folder after asking. Other players need the map too (or
      "Players may download missing maps").
    - "Insert existing server.cfg" takes over values, more lines and the
      rotation from a finished file. "Preview / save as" shows the final
      server.cfg and saves it if you like.
    - "Apply" puts name, players, mode, password and start map into the
      builder; everything is saved with the server.
    Restart-loop protection: if a server crashes three times in a row
    within 30 seconds, the manager pauses auto-restart ("Does not start
    cleanly"). Between attempts it waits 5, 15 or 30 seconds. "Restart"
    enables it again. "Stop" also ends server processes that detached
    from their .bat.
  - SteamCMD (button at the top of the server builder): download and
    update official dedicated servers from Steam with one click - e.g.
    CS:Source, CS 1.6, CS2, TF2, L4D2, Garry's Mod, DoD:S, HL2DM,
    Valheim, Sven Co-op, Killing Floor 2, 7 Days to Die, Rust, ARK,
    Satisfactory, Palworld.
    1. Pick the game, click "Install / update". The first time the
       manager asks whether it may download SteamCMD directly from Valve
       (steamcdn-a.akamaihd.net, only steamcmd.exe is kept).
    2. SteamCMD downloads the server in its own console window to
       C:\Project-Earth-Lan\steamcmd\servers\<game>. It only logs in
       anonymously - no Steam account, no password. Clicking again
       updates the server or resumes an interrupted download.
    3. When done: "Build in builder" - template and server EXE are
       already filled in, you only pick name, map, password and save.
       Games without their own template go to "Own game" (start
       parameters per the game's server documentation).
    Notes: CS2 is over 30 GB - best downloaded before the LAN. CS 1.6
    (HLDS) sometimes needs 2-3 runs. Valheim requires a password with at
    least 5 characters.
  - P2P / text chat (port 9872): all managers on the network find each
    other automatically, with a simple text chat.

OPTION 6 - COMMUNICATION CENTER (chat, files, voice chat)
  - Chat: group chat with everyone, private messages (select a
    participant), your own channels - also permanent and with password.
    "Friends only" shows only messages from your friends.
  - Send files: choose a target, send file(s) or whole folders.
    Several parallel connections, speed limit, resume after
    interruption, display of speed and remaining time.
  - Voice chat: create channels, talk privately, group voice, password
    channels. Selectable microphone/speakers, push-to-talk or voice
    activation, volume per participant (right-click).
  - Right-click on a participant: add/remove friend, poke, copy IP,
    volume, ban IP.
  - Right-click on a permanent channel: delete (only the creator and
    authorized persons, see chapter 9). Anyone still in the deleted
    channel is moved back to the general area automatically; the other
    managers get the deletion right away.
  - Chat and voice chat have separate channels: a channel you create in
    the chat only appears in the chat - and vice versa. Channels from
    older versions still apply to both.
  - "In-game overlay" (top): shows your voice channel (green = talking
    right now) and the latest chat messages on top of the game.
    Ctrl+Shift+O = on/off, Ctrl+Shift+Enter = write a message.
    Position, opacity and display time in the button's menu.
    Visible in windowed and borderless fullscreen mode; in exclusive
    fullscreen Windows draws the game over everything. The overlay is a
    normal window and does not touch the game - no anti-cheat issues.
    The communication center must be open for it (minimized is fine).

OPTION 7 - FRIENDS LIST, BAN LIST & MAILBOX
  - Mailbox: write messages to other players - even if they are offline
    right now. The message is delivered automatically as soon as the
    recipient starts their manager. Folders: inbox, outbox, sent.
  - Friends list: name, IP and note. "Currently on the network" shows
    other running managers - double-click adds them as a friend. The
    list belongs only to you and is not shared.
  - Ban list: your manager no longer accepts anything from banned IPs
    (chat, voice, files, mailbox).
  - "Manage moderators": only visible to the owner (see chapter 9).

OPTION 8 - KODI STREAMING
  Remote control for a Kodi on the network (also via the P2P network):
  browse media, play, playlist, volume, keyboard shortcuts. In addition
  the current video can be played locally on this PC (via VLC, installed
  automatically if needed).
  Address: IP of the Kodi PC (e.g. its 10.77.x.y) and port 8080; in Kodi
  "Allow remote control via HTTP" must be enabled.
  - Control buttons below the video: previous/next track, seek 10 s,
    play/pause, stop, quieter, louder, mute, loop. They only affect
    playback on this PC, not the Kodi PC.
  - Scrubbing bar (below the video and in the bottom bar in full
    screen): shows time and total length; click or drag to jump there.
  - Bar above the video (normal window and full screen): appears when
    the mouse moves, disappears after 3 seconds. Search box for movies,
    TV shows, episodes, music and artists (double-click/Enter plays or
    opens the show), "Select media ..." and full screen on/off. In full
    screen the control buttons are added at the bottom.
  - Select media: double-click opens folders or plays. Right-click:
    Open, Play whole folder, Add whole folder to the playlist, Play in
    order from here, Play everything in this view.

OPTION 9 - HOST YOUR OWN LOBBY
  Turns your PC into the relay server for a lobby with one click.
  - Lobby name and password (generated randomly, "New" for another one).
  - "Fixed address": so that the invite code stays valid even when your
    internet address changes (see chapter 8):
      None             - code contains your current internet IP
      Router           - enter e.g. your MyFRITZ! address
      DuckDNS          - free, the manager updates it itself
      Other DynDNS     - No-IP, dynv6, IPv64 ... via an update URL
    "Test now" checks whether the name points to your current IP.
  - "Host automatically when the manager starts".
  - "Start hosting": starts the server, opens the ports in the router
    (UPnP), determines your public IP and joins itself.
  - "Copy invite": code for your friends.
  - "Update public IP now": check and report immediately. This happens
    automatically every 5 minutes.
  - Warnings appear at the bottom of the window (e.g. DS-Lite, missing
    port forwarding).

OPTION 10 - GUIDE & FAQ
  Creates exactly this file on your desktop and opens it.

OPTION 11 - INTRANET FOR LAN PARTIES (view, build, embed)
  Your own page for your LAN party - straight from the manager, without
  web server software and without third-party services. Three areas:
  VIEW INTRANET
   - When it opens, the manager searches your home network and your P2P
     lobby for published intranets (port 9931). Click one - done.
   - "Enter address": open an intranet directly (e.g. 10.77.0.5 or
     http://lan.local). "Open in browser" shows it in your normal browser.
   - The "Game servers" block has "Join": starts the game and connects
     like the server browser (address also copied to the clipboard).
  BUILDER (for organizers)
   1. Pick a template ("Classic LAN party", "Tournament event", "Small LAN
      with friends", "Big LAN party (with menu)") and click "Load
      template" - or build your own with "+ Block".
   2. Enter name, date, location, countdown, accent color, logo (size
      selectable) and optionally your own header image, select
      blocks and edit them. The preview shows right away what the others
      will see.
   3. "Publish". As long as option 11 is open, the intranet is online
      (minimizing is fine).
   Blocks: news, schedule, game servers, game nights (live from the
   planner), tournament and results (live from option 4), downloads (files from the
   folder intranet\downloads), rules, seating plan, poll, order list
   (e.g. pizza), organizer contact and free text.
   Poll and order list: one entry per PC, can be changed at any time.
   "Clear votes / entries" resets them.
  SEAT MAP & CHECK-IN
   - Block "Seat map & check-in": one line per row, e.g. "A | 1-12" or
     "C | 1-6, -, 7-12" (- = aisle). "Gesperrt: A1, B5" blocks seats
     (organizers, tech), "Info: ..." is a note for the guests.
   - Guests pick their seat in the intranet (one per PC, with name/nick)
     and see it under "Your seat". Taken seats show the name.
   - "Manage check-in" (select the block): at the entrance type a name or
     seat into the search box, Enter = check in. Also: undo check-in,
     change seat, add a guest without PC, remove, CSV, close/reopen seat
     selection for guests.
   - After check-in the guest can no longer change the seat themselves -
     only the organizers can.
  OWN HEADER IMAGE AND LOGOS
   - "Choose header image": PNG, JPG or GIF up to 5 MB (about 1600 x 400
     pixels recommended). Shown as a banner above the header or as its
     background. If the name is already in the image, "Hide title, date
     and location" hides the text - the countdown stays.
   - Logo size: small, medium or large.
   - Block "Logos & sponsors": "Add images" copies logos into the folder
     intranet\logos (up to 24 images, 2 MB each). Optionally one line per
     image in the content: file name | name | https://... - the name is
     then shown below and the logo becomes a link.
   - "Export .zip" includes logo, header image and logo folder.
  PRICE LIST (the organizers' own prices)
   Block "Price list": you set all prices yourself - entry, drinks,
   snacks, tournament fee. In the "Content" field, one detail per line:
     [Drinks]                              category
     Cola (0.5 l) | 1.50 | deposit 0.25    item | price | note
     Tournament entry | free               the price may also be text
     Info: pay cash at the organizer desk  note for the guests
     Currency: CHF                         optional, default is EUR
   - A plain number (1.50) is shown with currency and two decimals, any
     other text unchanged (e.g. "5 EUR per day").
   - Up to 100 entries. The price list is read-only; ordering still goes
     through the block "Orders with menu" (which has prices per item too).
  ORDERS WITH MENU (for bigger LAN parties)
   The "Content" field holds the menu, one detail per line:
     [Pizza]                               category
     Margherita | 7.50 | tomato, mozzarella  item | price | description
     Info: orders close at 7 pm            note for the guests
     Link: Pizzeria Roma | 06184 1234 | https://...
                                           delivery service or restaurant
     Orga: 10.77.0.5, 192.168.1.20         more organizer PCs (get a
                                           notification for every order)
   - Up to 200 items. Guests pick quantities (0-10 per item), enter name,
     seat and a note and click "Order". One order per PC, can be changed
     until the organizers set it to "ordered".
   - New orders show up at the organizer in a notification window at the
     bottom right (collects all new orders), and likewise on the
     organizer PCs from the "Orga:" line (their Control Center must be
     open).
   - "Manage orders" (select the block): all orders with totals, set
     status (ordered, on the way, ready, cancelled), "All new: ordered",
     "Copy combined order" (all items added up - for ordering at the
     delivery service), "Save as CSV" and "Close orders".
   - Guests see their own order with status under "Your order"; everyone
     else only sees how much was ordered - no names.
   - Delivery services and restaurants appear as links on the page. If a
     location is entered, there is also "Restaurants nearby" (map on
     OpenStreetMap). These links lead to the internet and open in the
     normal browser; ordering and paying happens there or via the
     organizers - the manager itself does not pass orders on to delivery
     services.
  OWN FOOD & DRINKS (order online or on site only)
   Select the block "Orders with menu" and click "Food & drinks" (for the
   price list the button is called "Edit prices"). In the table you add
   your own food and drinks and set the prices yourself. Per item:
     Source:  "Own offer" (made/sold by the organizers) or
              "Delivery service" (ordered for the guests)
     Sale:    "Order online" (guests order in the intranet) or
              "On site only (counter)" (shown with price on the page,
              bought at the counter/till - no quantity field)
     Sold out: stays visible but can no longer be ordered
   - New rows are "Own offer" and "Order online" automatically. "Move
     up/down", "Delete row", "Apply".
   - "Save own to my items" remembers all own items with price on this
     PC; "Insert from my items" puts them back on the menu at the next
     LAN party.
   - "LAN without internet": hides delivery service links and the
     restaurant map. If there are only own items, they are hidden
     automatically. Own food and drinks work entirely without internet.
   - "Copy combined order" separates "For the delivery service" and
     "Own offer of the organizers (prepare yourselves / counter)".
   - In the "Content" field this is the 4th field, e.g.:
       Chili con carne | 4.50 | home-made | own
       Cola 0.5 l | 2.00 | | own, on site
       Hot dog | 2.50 | | own, sold out
       Internet: no
   - If there are already orders, add new items at the bottom and set old
     ones to "sold out" - orders remember the position.
   "Export .zip" / "Import .zip": back up the page or pass it on to other
   organizers (with logo, header image and logos, without downloads).
  SETTINGS
   - "Embed the organizer's intranet": if the LAN party already has its
     own intranet, just enter its address and publish. The guests'
     managers then show exactly that page. Only addresses in the local
     network are allowed (private IP or names like lan.local).
   - Port (default TCP 9931) and "publish automatically".
  Good to know:
  - Reachable only from the home network and the P2P network
    (10.77.x.y), never from the internet. Guests can only read (except
    poll/order list).
  - All texts are shown as plain text: no custom JavaScript, no fonts or
    scripts from the internet.
  - The view inside the manager uses the Windows web control. The own
    pages are built for it; elaborate organizer pages may not look
    perfect in it - then use "Open in browser".
  - The automatic search does not find ports other than 9931 - use
    "Enter address" with IP:port then.


AUTOSTART (small button at the top left, next to "Language")
  Starts the manager automatically with Windows (about 30 seconds after
  sign-in, hidden in the notification area next to the clock, without a
  UAC prompt). Then the mailbox, live
  status, game night reminders and - if set up - the lobby are always
  active. The button shows "Autostart: ON" or "OFF" - click again to
  turn it off. If you move the program file, set
  it up again here.

==============================================================================
6. LAN PARTY ON SITE
==============================================================================

Everyone sits in the same room and is connected to the same
router/switch?

VARIANT 1 - WITHOUT P2P (real LAN)
  You are already in a real network. Start the manager and go: chat,
  server browser, file transfer and "Join game" work directly over your
  LAN. Under "Change adapter" select the LAN/Wi-Fi adapter if a
  different one is set.

VARIANT 2 - WITH A P2P LOBBY (recommended for mixed groups)
  Useful if people also join from home, or if the party network is
  difficult (Wi-Fi isolation, several networks, guest Wi-Fi).
  One person hosts (option 9), everyone else pastes the invite code.
  In the same room the PCs connect automatically via the local network
  (ping 1-15 ms), even if the router does not support UPnP.

CHECKLIST FOR THE EVENING
  [ ] Everyone has the same manager version (watch the GitHub notice).
  [ ] The host has started option 9, the code has been shared.
  [ ] Everyone shows up in the player list as "Direct" or "Relay".
  [ ] Games scanned with option 3, all of them are in the game library.
  [ ] A test ping: "ping 10.77.x.y" in the command prompt.
  [ ] Voice chat in option 6 - set up the microphone beforehand.


==============================================================================
7. FOR ORGANIZERS
==============================================================================

RECOMMENDED SETUP
  - Intranet (option 11): schedule, servers, rules, pizza list and
    results on one page - from a template in a few minutes. Already have
    your own intranet? Option 11 embeds it.
  - A permanent relay server (PEL-Rendezvous) on a server with a fixed
    IP or a small VPS. Then no participant has to change anything in
    their router, and it also works with DS-Lite/CGNAT.
  - One lobby per event, with its own password. Create the invite code
    with "Create invite" in the P2P box and share it.
  - Large groups: a lobby has up to 512 places. All participants should
    use the current manager version - older versions work in the same
    lobby, but cause much more traffic and see at most 255 players.

TRAFFIC AT THE HOST / SERVER
  - Direct connections (the normal case) do not go through the server
    at all.
  - Signaling: the server only sends changes (someone joins, leaves,
    changes address). When idle it needs only about 20 kbit/s upload,
    even with 512 players. If all 512 join one after another, that is
    about 18 MB in total.
  - Relay (only pairs where both routers are too strict): passes through
    the server twice. When hosting at home (option 9) it is limited to
    10 Mbit/s in total and 3 Mbit/s per player, so your internet stays
    usable. The standalone server (PEL-Rendezvous) is unlimited, but can
    be limited with -RelayMbitTotal and -RelayMbitPerMember.
  - For events with hundreds of participants a small VPS running
    PEL-Rendezvous is better than a home connection.
  - Every participant keeps a connection to every other one. With very
    many participants the live status is therefore sent less often (up
    to 128 every 8 s, up to 256 every 20 s, above that every 30 s) - in
    the P2P network as well as at a LAN party without internet.

LAN PARTY WITHOUT INTERNET: HOW MANY PLAYERS?
  Offline there is no player limit in the manager - chat, server
  browser, live status, files and option 1 run directly over your
  network. The limit is set by the network:
  - A normal home router hands out addresses for about 250 devices
    (/24). For more, set up a larger network (e.g. /22 = about 1,000
    addresses) - dedicated DHCP servers or better routers can do that.
  - Use gigabit switches. From a few hundred PCs, several switches or
    separate networks (VLANs) are worthwhile.
  - The broadcast firewall only works in the P2P network; on a real LAN
    the background noise from Windows (printer search, name resolution
    ...) is higher.

GAME NIGHT PLANNER
  Control Center -> "Game night planner": enter title, game, date and
  time. The date is distributed automatically to all managers - even to
  people who open the manager days later (any other manager that knows
  it just has to be online).
  - Whoever opens the manager gets an announcement when an evening is
    coming up in the next 3 days, and a reminder 15 minutes before.
  - Only the creator can cancel (on the PC where it was created).
  - "Own games": list of your games for selection in the planner.

MODERATION
  See chapter 9 (moderators, admins, ban list).

DEDICATED SERVERS
  Option 5 -> server manager: start servers, monitor them and open them
  in the firewall with one click. Players find the server in the server
  browser or via "Who is playing what".


==============================================================================
8. ONLINE LAN GAMING OVER THE INTERNET
==============================================================================

WHO HAS TO CHANGE WHAT IN THE ROUTER?
  Only the operator of the relay server - everyone else NOTHING.
    - Option 9 at home: the manager tries to open the ports
      automatically (UPnP). If that does not work, forward UDP 47810
      and 47800 to your PC once.
      Fritz!Box: Internet -> Permit Access -> device -> "Permit
      independent port sharing for this device" (then UPnP works), or
      open the ports manually there.
    - PEL-Rendezvous on a VPS: only open UDP 47810 in its firewall.

DS-LITE / CGNAT (many cable and fiber connections)
  Your connection does not have its own public IPv4 address. Then nobody
  from outside can reach your relay server - option 9 shows a notice
  about this. You can still join anywhere. Solutions:
    - Someone with a regular connection hosts.
    - PEL-Rendezvous on a small VPS (from about 1-4 EUR/month).
    - Ask your provider for a public IPv4 or "dual stack".

CHANGING IP / FORCED DISCONNECTION
  Many connections regularly get a new IP (often at night). Then an
  invite code with the old IP leads nowhere. Solution: a fixed address
  (dynamic DNS) in option 9:
    - Fritz!Box: Internet -> MyFRITZ! account, enter the address
      (xyz.myfritz.net) in option 9 under "Router".
    - DuckDNS (free): sign in at duckdns.org, create a subdomain, enter
      subdomain + token in option 9.
  Then send a new code once - it stays valid from then on.
  After an IP change everyone reconnects by themselves within a few
  minutes.

DIRECT OR RELAY?
  "Direct" is the normal case. "Relay" means: both routers are so strict
  that no direct connection is possible. It still works, just with a
  slightly higher ping. The manager keeps trying in the background to
  switch to "Direct".


==============================================================================
9. PERMISSIONS: OWNER, MODERATORS, ADMINS
==============================================================================

Not everyone may delete permanent chat and voice channels. Authorized are:

  CHANNEL CREATOR
    Whoever created the channel may delete it (right-click on the channel
    in option 6).

  OWNER (project operator)
    Only on the PC with the file C:\Project-Earth-Lan\owner.key. When
    deleting, the manager asks for the owner password. Owner commands are
    digitally signed and apply to ALL managers - independent of IPs. Only
    the owner sees "Manage moderators" in option 7.

  MODERATORS
    Appointed by the owner (option 7 -> Manage moderators), apply to all
    managers. They are recognized by their IP - in the P2P network by
    their virtual 10.77 IP.

  GLOBAL ADMINS (per PC)
    Everyone can specify in C:\Project-Earth-Lan\AllowIP.txt (one IP per
    line) whose deletions THEIR manager accepts. This only applies to
    your own PC - nobody can make themselves an admin for others.

  IMPORTANT AFTER SWITCHING FROM ZEROTIER
    Moderators, AllowIP.txt, friends list, ban list and channel creators
    work with IP addresses. The old ZeroTier IPs are no longer valid in
    the P2P network. Enter them once again with the new 10.77 IPs - these
    stay the same permanently afterwards.


==============================================================================
10. PORTS AND FILES (OVERVIEW)
==============================================================================

PORTS (all are opened automatically in the Windows firewall when needed)
  UDP 47800        P2P network (connection to the players)
  UDP 47810        Relay server (only at the host / server)
  TCP/UDP 9872     Manager network, server browser, text chat (option 5)
  UDP 9873         Voice chat
  TCP/UDP 9874     Chat (option 6)
  TCP/UDP 9876     File transfer
  TCP/UDP 9776     Sync of channels and owner commands
  TCP/UDP 9877     Tournaments & matchmaking (option 4)
  UDP 9928         Live status and game night planner
  TCP 9929         Mailbox
  TCP 9930         File server (option 1 / Caddy, only if you offer files)
  TCP 9931         Intranet (option 11, only if you publish)
  TCP 9870         Remote Desktop (option 2, only if enabled)
  In the P2P network all of these ports automatically run through the
  tunnel - nothing needs to be opened in the router for them.

FILES (folder C:\Project-Earth-Lan)
  language.txt             chosen language (de / en)
  p2p\p2p_settings.json    P2P settings (passwords encrypted)
  p2p\amd64\wintun.dll     driver for the virtual network adapter
  logs\                    logs (for "Export error log")
  Friendlist.json          friends list and channels
  ip_bans.json             ban list
  Postfach\                messages
  events.json              game nights
  selected_adapter.json    selected network adapter
  downloader_server.json   settings for option 1 (password encrypted)
  downloader_own_password.json  password of your share (option 1)
  fileserver.json          settings for option 1
  Freigabe\               default folder for option 1
  intranet\               option 11: intranet.json (your page), mitmachen.json
                           (poll/order list), logo.*, downloads\ (files for
                           the guests), sortiment.json (your own food and
                           drinks with prices)
  willkommen_gesehen.txt   remembers that the welcome window was shown
  fenster.json             setting "Minimize to the notification area"
  matchmaking\turniere.json tournaments from option 4
  eigene_whitelist.txt / eigene_blacklist.txt / exe_korrekturen.txt
                           own lists for option 3
  games.json               game library (option 3): game names and EXE
                           paths of this PC, never sent anywhere
  server\                  server builder (option 5): saved servers as
                           .bat and .pel.json
  steamcmd\                SteamCMD (option 5) and the dedicated servers
                           downloaded with it (subfolder servers\)
  overlay.json             in-game overlay (option 6): on/off, position,
                           opacity
  games_netz.json          sync (option 3): which games the other managers
                           have (names only, no paths)
  lib_sync.txt             short-lived: "Sync" request from option 3 to
                           the Control Center
  fileserver_open.txt      short-lived: "Own file server" request from the
                           downloader (option 1) to the Control Center
  matchmaking\             option 4: confirmed results (for the rating)
                           and your settings
  AllowIP.txt              optional admin list (chapter 9)


==============================================================================
11. FAQ - FREQUENTLY ASKED QUESTIONS
==============================================================================

Do I still need ZeroTier, Hamachi or Radmin?
  No. The network is built into the manager. Other VPNs can stay
  installed in parallel, but they are no longer needed.

Does it cost anything / do I need an account?
  No. No account, no sign-up. Only those who rent their own VPS pay the
  provider for it.

Does it run on the Steam Deck?
  Yes, if Windows is installed on the Steam Deck. The manager does not
  run on SteamOS (Linux).

Does it run on Mac or Linux?
  No, only Windows 10 and 11.

Why administrator rights?
  For the virtual network adapter and the firewall rules. Without these
  rights Windows cannot set up a network.

Does my invite code stay the same?
  Yes, as long as lobby name, password and address stay the same. With a
  fixed address (dynamic DNS) it stays valid even after IP changes.

What happens if the host closes the manager?
  Existing connections between the others keep running, but nobody can
  join anew. When the host starts again, everyone reconnects
  automatically (if "join automatically" is active).

Can I be in several lobbies at the same time?
  No, always in one. "Disconnect" and then join another one.

Why do I always get the same virtual IP?
  On purpose: this way the friends list, mailbox, moderators and Remote
  Desktop keep working. Only if two PCs in a lobby would get the same
  address by chance does one of them differ.

Is my internet slower now?
  No. Only traffic to 10.77.x.y goes through the P2P network. Everything
  else goes directly to the internet as usual.

Can the server operator see what we do?
  No. They only see who is in a lobby (name, IP). Contents are encrypted,
  only those with the lobby password know the key.

A game does not find the others in the LAN search.
  See chapter 12, item "Game does not find servers".

Windows asks "public or private network"?
  The manager sets the P2P network to "private" automatically. If the
  question still appears: choose "private".

Does the antivirus report the EXE?
  Unfortunately this happens with self-built PowerShell programs (false
  positive). Only download the manager from the official GitHub page and
  compare the checksum (.sha256.txt).

How do I switch the language?
  Button "Language" at the top left of the Control Center. The manager
  restarts once.


==============================================================================
12. TROUBLESHOOTING
==============================================================================

"Connecting to relay server ..." does not change
  - Check the address in the "Relay server" field (typo, port).
  - Is the host's Control Center running with option 9?
  - Host: check port forwarding (chapter 8), read the notices in option
    10 (DS-Lite?).
  - Own firewall/antivirus: the manager needs internet access.

Player shows "Wrong password?"
  Lobby name AND password must be exactly the same (the password is
  case-sensitive). The easiest way is to paste the invite code again.

Player stays on "Connecting ..."
  Normally it switches to "Direct" or "Relay" after about 8 seconds. If
  not: both click "Disconnect" and join again. If that does not help,
  the relay server was briefly gone - wait a few seconds.

Game does not find servers in the LAN search
  - Both in the same lobby and "Direct"/"Relay" in the list?
  - The game must be started after joining (otherwise it does not know
    the new adapter) - restart the game.
  - Some games only search on the first network adapter: then connect
    via IP (the host's 10.77.x.y), option 5 "Join" or "Join game".
  - Windows firewall: at the first start Windows asks whether the game
    may access the network - allow "Private networks".
  - Broadcast firewall: if a game uses unusual ports, turn it off for a
    test.

High ping / stuttering
  - Is the player on "Relay"? Then everything goes through the server.
    Host: UPnP/port forwarding for UDP 47800 often helps.
  - Wi-Fi instead of cable? Downloads in the background?

"The P2P network could not be started"
  - Was the manager started as administrator?
  - The message names the reason. At the first start the driver
    (Wintun) is downloaded - this briefly needs internet.
  - Close the manager completely (also from the taskbar) and restart it.

After disconnecting, chat/server browser no longer work
  Control Center -> "Change adapter" -> select your normal LAN/Wi-Fi
  adapter. (Normally this happens automatically.)

Mailbox message does not arrive
  The recipient must start their manager once. Messages stay in the
  outbox until then and are delivered automatically.


==============================================================================
13. SECURITY & PRIVACY
==============================================================================

  - All data stays on your PC (folder C:\Project-Earth-Lan). Friends and
    ban lists are never shared.
  - Passwords and tokens are stored encrypted by Windows (only readable
    for your Windows user account).
  - The invite code contains the lobby password: only send it to players,
    don't post it publicly. A new password makes old codes invalid.
  - Everyone in a lobby has equal rights, as in a real LAN. Only share
    folders and Remote Desktop with people you trust.
  - The manager does not download updates by itself. New versions are
    only available on GitHub.
  - The error log export contains IP addresses and the computer name,
    but no chats, messages or passwords.


==============================================================================
14. GETTING HELP
==============================================================================

  1. Control Center -> "Export error log". The ZIP file is saved on the
     desktop.
  2. Briefly describe what you did and what happened (a screenshot
     helps).
  3. Project page and latest version:
     https://github.com/Firehawk215/Project-Earth-Lan

Have fun gaming!
'@

$script:PelCaddyGuideEn = @'
SETTING UP YOUR OWN DOWNLOAD SERVER FOR THE TOOLS/MODS/GAMES DOWNLOADER
With Docker Desktop + Caddy on Windows 11
========================================================================

This guide belongs to the "Server & friends" button in option 1
(Tools, mods & games downloader) of the Project Earth LAN Manager.
For this button to offer your own address, you need an HTTP server
somewhere that shows your folders (Windows Tools / Mods / Games or
your own directories) as a clickable directory listing. That is
exactly what Caddy does - a lightweight web server you start with
Docker.


1. INSTALL DOCKER DESKTOP
------------------------------------------------------------------
 - Download Docker Desktop for Windows from docker.com and
   install it.
 - Start Docker Desktop once and wait until "Engine running" is
   shown at the bottom left (the WSL2 backend is set up
   automatically during installation if it is missing - a
   restart may be required).
 - Check in a PowerShell window that everything works:

       docker --version
       docker run hello-world


2. PREPARE THE FOLDER STRUCTURE
------------------------------------------------------------------
Create a folder that Caddy will share later, e.g.:

       C:\PEL-Downloads\
       |-- Windows Tools\
       |-- Mods\
       `-- Games\

The names are up to you - the downloader can detect them
automatically later (see step 6). By default the LAN Manager
expects exactly these three folders; your own names work as
well as soon as you enter them in the "Server & friends" dialog
or let the manager find them automatically.


3. WRITE THE CADDYFILE
------------------------------------------------------------------
In the same directory, create a file without extension called
"Caddyfile" with the following content:

       :9930 {
           root * /srv/downloads
           file_server browse
       }

 - ":9930" is the port the downloader uses by default.
 - "file_server browse" provides the clickable directory listing
   that the LAN game finder and the downloader read via HTTP.
 - "root * /srv/downloads" is the path INSIDE the container -
   it is mapped to your real Windows folder in the next step.


4. START CADDY WITH DOCKER
------------------------------------------------------------------
The easiest way is a "docker-compose.yml" in the same folder:

       services:
         pel-downloader:
           image: caddy:2
           container_name: pel-downloader
           restart: unless-stopped
           ports:
             - "9930:9930"
           volumes:
             - "C:/PEL-Downloads:/srv/downloads"
             - "./Caddyfile:/etc/caddy/Caddyfile"

Then run in PowerShell in the same folder:

       docker compose up -d

Alternatively without Compose, directly with "docker run":

       docker run -d --name pel-downloader ^
         -p 9930:9930 ^
         -v "C:\PEL-Downloads:/srv/downloads" ^
         -v "%cd%\Caddyfile:/etc/caddy/Caddyfile" ^
         caddy:2

Test locally in your browser: http://localhost:9930/  - you should
see your folders (Windows Tools, Mods, Games) as a clickable list.


5. OPEN THE FIREWALL & NETWORK
------------------------------------------------------------------
So that friends can access it through your P2P network as well,
Windows must allow incoming connections on port 9930:

       New-NetFirewallRule -DisplayName "Project Earth LAN Downloader" `
         -Direction Inbound -Protocol TCP -LocalPort 9930 -Action Allow

For option 1 the LAN Manager itself only opens an OUTGOING
connection - if you want to host a server yourself, you need this
additional inbound rule. Also make sure you are connected to the
desired P2P lobby (Control Center -> P2P network), so your friends
can reach you via your virtual IP (10.77.x.y).


6. ENTER THE ADDRESS IN THE LAN MANAGER
------------------------------------------------------------------
 1. Open option 1 -> "Server & friends".
 2. Enter your address at the top, e.g. http://<your-P2P-IP>:9930,
    and click "Save".
 3. Optional: click "Find directories automatically on the server"
    to take over your folder names automatically instead of typing
    them in by hand - this works because Caddy's
    "file_server browse" delivers the same kind of directory
    listing the LAN game finder already understands.
 4. "Apply & close" - the downloader window reloads with the new
    address.

The settings are then stored in
C:\Project-Earth-Lan\downloader_server.json and are kept after
restarting the manager.


7. GIVE FRIENDS ACCESS
------------------------------------------------------------------
So that players can connect with each other without typing IP and
port every time:

 1. Add each other in option 7 -> friends list with your virtual
    P2P IP (if not done yet).
 2. In the "Server & friends" dialog you can then simply choose the
    name from the friends list under "Take over from a friend",
    enter the port (default 9930) and click "Apply" - the
    downloader automatically builds http://<friend-IP>:<port> from
    it and downloads from that server instead of your own.

This way everyone in the group can either host their own server or
switch to a friend's server with one click.


8. USEFUL DOCKER COMMANDS
------------------------------------------------------------------
       docker compose logs -f        Show Caddy's live logs
       docker compose restart        Reload after changing the Caddyfile
       docker compose down           Stop the server

After every change to the Caddyfile a "docker compose restart" is
enough for the new configuration to take effect.


------------------------------------------------------------------
IN SHORT: Docker Desktop hosts a Caddy container that shares your
Windows folder on port 9930 as a browsable file list. The LAN
Manager (option 1) talks to this server via a freely configurable
address, which can be entered manually, detected automatically or
taken over directly from the friends list (option 7).
'@

function Export-PelHelpFile {
    param($Owner = $null)
    try {
        $desk = [Environment]::GetFolderPath('Desktop')
        if (-not $desk -or -not [System.IO.Directory]::Exists($desk)) { $desk = Join-Path $env:USERPROFILE 'Desktop' }
        if ($script:PelLang -eq 'en') {
            $path = Join-Path $desk 'Project Earth LAN - Guide & FAQ.txt'
            $txt = $script:PelHelpTextEn.Replace('{VERSION}', [string]$script:PelVersion).Replace('{DATUM}', (Get-Date -Format 'yyyy-MM-dd'))
        } else {
            $path = Join-Path $desk 'Project Earth LAN - Anleitung & FAQ.txt'
            $txt = $script:PelHelpText.Replace('{VERSION}', [string]$script:PelVersion).Replace('{DATUM}', (Get-Date -Format 'dd.MM.yyyy'))
        }
        $txt = ($txt -replace "`r?`n", "`r`n")
        [System.IO.File]::WriteAllText($path, $txt, (New-Object System.Text.UTF8Encoding($true)))
        Write-PelLog -Level 'INFO' -Message "Anleitung & FAQ erstellt: $path"
        try { Start-Process -FilePath 'notepad.exe' -ArgumentList "`"$path`"" } catch { }
        return $path
    } catch {
        Show-PelMsg "Die Anleitung konnte nicht erstellt werden:`n$($_.Exception.Message)" 'Anleitung & FAQ' ([System.Windows.Forms.MessageBoxIcon]::Error) $Owner
        return $null
    }
}

# ------------------------------------------------------------------------------
# SPIEL-EXE-AUSWAHL, WHITELIST & BLACKLIST (Option 3, Option 4, "Mitspielen")
# ------------------------------------------------------------------------------
# Früher wurde einfach die GRÖSSTE .exe im Spielordner genommen. Das traf oft daneben:
# .NET-Installer in _CommonRedist (80 MB), Dedicated Server (BF1942_w32ded.exe ist
# größer als BF1942.exe), Editoren (UnrealEd.exe > UT2004.exe), HLTV-Proxy (hltv.exe >
# hl.exe), Modell-Tools in bin\ (studiomdl.exe > left4dead2.exe), mitgelieferte
# ffmpeg.exe, EA-Installer (__Installer\Touchup.exe) usw. Jetzt gilt:
#   1. Ordner mit Installern, Redistributables, Anticheat, Tools, Engine-Dateien usw.
#      werden gar nicht erst durchsucht (max. 6 Ebenen tief).
#   2. EXEs mit eindeutigen Nicht-Spiel-Namen werden aussortiert (Installer, Updater,
#      Crash-Reporter, Server, Editoren, Browser-Hilfsprozesse, Laufzeitumgebungen ...).
#   3. Die übrigen werden bewertet: Name passt zum Spiel/Ordner (auch Kürzel wie UT2004,
#      BF1942, GTA5, CSGO), bekannte Spiel-EXE aus den Join-Regeln, Multiplayer-EXE
#      (iw3mp statt iw3sp), geringe Ordnertiefe, plausible Größe. Launcher zählen nur,
#      wenn sonst nichts übrig bleibt (z. B. Minecraft Launcher).
# Eigene Korrekturen: C:\Project-Earth-Lan\exe_korrekturen.txt (siehe Option 3 ->
# "Eigene Listen") hat immer Vorrang vor der automatischen Auswahl.
$script:PelExeExcludeDirs = '(?i)^(_?_?commonredist|__installer|_installer|installers?|redists?|redistributables?|_redist|directx\w*|dx9|dxsetup|vcredist\w*|vc_?redist\w*|dotnet\w*|netfx\w*|physx\w*|prerequisites?|_?prereqs?|dependencies|support|easyanticheat\w*|battleye|punkbuster|pb|monobleedingedge|mods?|tools?|sdk|editors?|docs?|documentation|manuals?|extras|soundtrack|ost|artbook|bonus|goodies|wallpapers?|screenshots|crashreports?|logs?|cache|shadercache|shader_cache|thirdparty|third_party|engine|__overlay|_overlay|launcher_data|steam_settings|uninstall\w*|setup|install)$'
$script:PelExeExcludeNames = '(?i)^(unins\d*|uninst.*|uninstall.*|.*setup.*|.*install|.*installer.*|.*update|.*updater.*|.*patch|.*patcher.*|autorun|autoplay|touchup|cleanup|repair.*|activation.*|register.*|dxwebsetup|dxsetup|vc_?redist.*|vcredist.*|dotnetfx.*|ndp\d+.*|oalinst|physx.*|directx.*|xnafx.*|.*prereq.*|.*redist.*|crash|.*crash(handler|reporter|report|sender|pad|dump|mon).*|.*errorreport.*|.*bugreport.*|report.*|feedback.*|.*support.*|sysinfo.*|dxdiag.*|.*diag|.*diagnostics?|systemcheck.*|.*benchmark.*|easyanticheat.*|eac|eac_launcher|.*_be|beservice.*|battleye.*|be_launcher|pnkbstr.*|pbsvc.*|punkbuster.*|uplay.*|upc|origin.*|eadesktop|eabackground.*|gfwl.*|securom.*|steamservice|steamerrorreporter.*|gameoverlayui.*|.*browser.*|cef.*|.*cefsharp.*|.*cefprocess.*|.*subprocess.*|.*webhelper.*|.*webengine.*|qtwebengineprocess|node|python\d*w?|java|javaw|ffmpeg|ffprobe|ffplay|7za?|7z|unzip|zip|curl|wget|lua\d*|luac\d*|perl|.*editor.*|unrealed|ued|world ?builder|.*sdk.*|hammer|hammerplusplus|studiomdl|hlmv|vbsp|vvis|vrad|vpk|shadercompile.*|captioncompiler|.*compiler.*|.*viewer.*|.*modeler.*|.*converter.*|.*config|.*configurator|.*configtool|.*settings|.*options|.*language.*|langselect.*|.*server.*|.*dedicated.*|.*_ded|.*w32ded|.*-ds|srcds.*|hlds.*|hltv|ucc|.*tool|.*tools|.*toolkit|.*helper.*|.*service|.*agent|.*monitor|.*daemon|.*uploader|.*downloader|.*unpack.*|.*extract.*|.*decompress.*|.*convert.*|.*verify.*|dosbox|scummvm|unitycrashhandler(32|64)?|.*handler)$'
$script:PelExeGoodDirs = '(?i)^(bin|bin32|bin64|binaries|win32|win64|x64|x86|system|system64|game|retail|shipping)$'
$script:PelRomanOrNumber = '^(\d+|i{1,3}|iv|v|vi{1,3}|ix|x)$'

function ConvertTo-PelCompactName([string]$s) {
    return ((([string]$s).ToLowerInvariant()) -replace "[’'`´]", '' -replace '[^a-z0-9]', '')
}

# Kürzel eines Spielnamens: "Unreal Tournament 2004" -> ut2004, "Grand Theft Auto V" ->
# gta5/gtav, "Counter-Strike Global Offensive" -> csgo, "Call of Duty 4 ..." -> cod4.
function Get-PelNameAcronyms([string]$Name) {
    $words = @((([string]$Name).ToLowerInvariant() -replace "[’'`´]", '') -split '[^a-z0-9]+' | Where-Object { $_ })
    if ($words.Count -lt 2) { return @() }
    $roman = @{ 'ii' = '2'; 'iii' = '3'; 'iv' = '4'; 'v' = '5'; 'vi' = '6'; 'vii' = '7'; 'viii' = '8'; 'ix' = '9'; 'x' = '10' }
    $a = ''; $b = ''; $c = ''; $cDone = $false
    foreach ($w in $words) {
        if ($w -match '^\d+$') {
            $a += $w; $b += $w
            if (-not $cDone) { $c += $w; $cDone = $true }
        } elseif ($roman.ContainsKey($w) -and $a.Length -gt 0) {
            $a += $roman[$w]; $b += $w
            if (-not $cDone) { $c += $roman[$w]; $cDone = $true }
        } else {
            $a += $w.Substring(0, 1); $b += $w.Substring(0, 1)
            if (-not $cDone) { $c += $w.Substring(0, 1) }
        }
    }
    return @(@($a, $b, $c) | Where-Object { $_.Length -ge 2 } | Select-Object -Unique)
}

# Alle Zahlen aus einem Spielnamen (auch römische): "Battlefield 1942" -> 1942,
# "Diablo II" -> 2.
function Get-PelNameNumbers([string]$Name) {
    $roman = @{ 'ii' = '2'; 'iii' = '3'; 'iv' = '4'; 'v' = '5'; 'vi' = '6'; 'vii' = '7'; 'viii' = '8'; 'ix' = '9'; 'x' = '10' }
    $out = @()
    $i = 0
    foreach ($w in @(([string]$Name).ToLowerInvariant() -split '[^a-z0-9]+' | Where-Object { $_ })) {
        if ($w -match '^\d+$') { $out += $w }
        elseif ($i -gt 0 -and $roman.ContainsKey($w)) { $out += $roman[$w] }
        $i++
    }
    return $out
}

# Verzeichnisse, die nie selbst ein einzelnes Spiel sind (Laufwerkswurzel, Programme-
# Ordner, Sammelordner wie "Games", "steamapps\common", "EA Games" ...). Manche Programme
# tragen so etwas als Installationsort in die Registry ein - dann würde sonst ein ganzes
# Laufwerk oder alle Spiele auf einmal durchsucht und eine beliebige EXE verknüpft.
function Test-PelUnsafeGameRoot([string]$Path) {
    if (-not $Path) { return $true }
    try { $full = [System.IO.Path]::GetFullPath($Path.Trim().TrimEnd('\', '/')) } catch { return $true }
    $root = [System.IO.Path]::GetPathRoot($full)
    if (-not $root -or ($full.TrimEnd('\', '/') -ieq $root.TrimEnd('\', '/'))) { return $true }
    if ($env:windir -and $full.StartsWith($env:windir, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    $leaf = [System.IO.Path]::GetFileName($full).ToLowerInvariant()
    $containers = @('windows', 'program files', 'program files (x86)', 'programdata', 'users', 'appdata', 'local', 'roaming', 'documents', 'desktop', 'downloads',
        'games', 'spiele', 'xboxgames', 'steam', 'steamlibrary', 'steamapps', 'common', 'epic games', 'gog games', 'gog galaxy', 'origin games', 'ea games',
        'electronic arts', 'ubisoft', 'ubisoft game launcher', 'elamigos', 'games (x86)')
    return ($containers -contains $leaf)
}

# Sammelt .exe-Dateien unterhalb eines Spielordners (höchstens 6 Ebenen, ohne Junctions,
# ohne die Ausschluss-Ordner oben). Begrenzt auf 20.000 Ordner / 4.000 EXEs.
function Get-PelExeCandidates([string]$Root, [int]$MaxDepth = 6, [switch]$NoDirExclusions) {
    $list = New-Object System.Collections.Generic.List[object]
    $stack = New-Object System.Collections.Generic.Stack[object]
    $stack.Push([pscustomobject]@{ Dir = $Root; Depth = 0 })
    $dirCount = 0
    while ($stack.Count -gt 0) {
        $it = $stack.Pop()
        $dirCount++
        if ($dirCount -gt 20000) { break }
        try {
            foreach ($f in [System.IO.Directory]::EnumerateFiles($it.Dir, '*.exe')) {
                if (-not $f.EndsWith('.exe', [System.StringComparison]::OrdinalIgnoreCase)) { continue }
                $list.Add([pscustomobject]@{ Path = $f; Depth = $it.Depth })
                if ($list.Count -ge 4000) { return $list.ToArray() }
            }
        } catch { }
        if ($it.Depth -ge $MaxDepth) { continue }
        try {
            foreach ($d in [System.IO.Directory]::EnumerateDirectories($it.Dir)) {
                $leaf = [System.IO.Path]::GetFileName($d)
                if (-not $NoDirExclusions -and $leaf -match $script:PelExeExcludeDirs) { continue }
                try { if (([System.IO.File]::GetAttributes($d) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { continue } } catch { continue }
                $stack.Push([pscustomobject]@{ Dir = $d; Depth = $it.Depth + 1 })
            }
        } catch { }
    }
    return $list.ToArray()
}

# Wählt die Spiel-EXE in einem Ordner. Rückgabe: Objekt mit Path, Score, Reason (kurze
# Begründung für das Protokoll) - oder $null, wenn keine brauchbare EXE gefunden wurde.
function Select-PelGameExe {
    param([string]$Folder, [string]$GameName = '', [string[]]$PreferredNames = @())
    if (-not $Folder -or -not [System.IO.Directory]::Exists($Folder)) { return $null }
    $rootFull = [System.IO.Path]::GetFullPath($Folder).TrimEnd('\', '/')
    $gComp = ConvertTo-PelCompactName $GameName
    $fComp = ConvertTo-PelCompactName ([System.IO.Path]::GetFileName($rootFull))
    $targets = @(@($gComp, $fComp) | Where-Object { $_ } | Select-Object -Unique)
    $acr = @(@(Get-PelNameAcronyms $GameName) + @(Get-PelNameAcronyms ([System.IO.Path]::GetFileName($rootFull))) | Select-Object -Unique)
    $nums = @(@(Get-PelNameNumbers $GameName) + @(Get-PelNameNumbers ([System.IO.Path]::GetFileName($rootFull))) | Select-Object -Unique)
    $firstLetters = @(@($gComp, $fComp) | Where-Object { $_ } | ForEach-Object { $_.Substring(0, 1) } | Select-Object -Unique)
    $pref = @($PreferredNames | Where-Object { $_ } | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $known = $script:PelKnownGameExes

    foreach ($pass in 1..2) {
        $cands = if ($pass -eq 1) { @(Get-PelExeCandidates -Root $rootFull) } else { @(Get-PelExeCandidates -Root $rootFull -NoDirExclusions) }
        $scored = New-Object System.Collections.Generic.List[object]
        foreach ($c in $cands) {
            $leaf = [System.IO.Path]::GetFileName($c.Path)
            $leafL = $leaf.ToLowerInvariant()
            $base = [System.IO.Path]::GetFileNameWithoutExtension($leaf)
            $baseL = $base.ToLowerInvariant()
            if ($baseL -match $script:PelExeExcludeNames) { continue }
            $x = ConvertTo-PelCompactName $base
            if (-not $x) { continue }
            $size = [int64]0
            try { $size = (New-Object System.IO.FileInfo($c.Path)).Length } catch { }
            $score = 0
            $why = New-Object System.Collections.Generic.List[string]

            # Name
            $ns = 0
            foreach ($t in $targets) {
                if ($x -eq $t) { $ns = [Math]::Max($ns, 60) }
                elseif ($t.Length -ge 4 -and $x.Contains($t)) { $ns = [Math]::Max($ns, 40) }
                elseif ($x.Length -ge 3 -and $t.Contains($x)) { $ns = [Math]::Max($ns, 30) }
            }
            foreach ($a in $acr) {
                if ($x -eq $a) { $ns = [Math]::Max($ns, 50) }
                elseif ($a.Length -ge 3 -and $x.Contains($a)) { $ns = [Math]::Max($ns, 35) }
                elseif ($x.Length -ge 3 -and $a.Contains($x)) { $ns = [Math]::Max($ns, 30) }
            }
            if ($ns -lt 25) {
                foreach ($n in $nums) {
                    if ($x.Contains($n) -and ($firstLetters -contains $x.Substring(0, 1))) { $ns = 25; break }
                }
            }
            if ($ns -gt 0) { $score += $ns; $why.Add('Name passt') }
            if ($pref -contains $leafL) { $score += 50; $why.Add('bekannte Spiel-EXE') }
            elseif ($known -and $known.ContainsKey($leafL)) { $score += 45; $why.Add('bekannte Spiel-EXE') }

            # Multiplayer bevorzugen (LAN!), Singleplayer-Varianten abwerten
            if ($baseL -match '(mp|multiplayer|multi|online)$|(^|[^a-z])mp([^a-z]|$)') { $score += 15; $why.Add('Multiplayer') }
            elseif ($baseL -match '(sp|singleplayer|single|campaign)$|(^|[^a-z])sp([^a-z]|$)') { $score -= 10 }

            # Ordnertiefe und typische Programmordner
            switch ([int]$c.Depth) { 0 { $score += 15 } 1 { $score += 10 } 2 { $score += 5 } }
            $parentLeaf = [System.IO.Path]::GetFileName([System.IO.Path]::GetDirectoryName($c.Path))
            if ([int]$c.Depth -gt 0 -and $parentLeaf -match $script:PelExeGoodDirs) { $score += 5 }
            if ($c.Path -match '(?i)(win64|x64|bin64|_64|64bit)' -or $baseL -match '64$') { $score += 3 }

            # Größe: winzige Stub-Dateien abwerten, echte Programme leicht bevorzugen
            if ($size -lt 64KB) { $score -= 15 }
            elseif ($size -ge 10MB) { $score += 6 }
            elseif ($size -ge 1MB) { $score += 4 }

            # Launcher nur, wenn es nichts Besseres gibt
            if ($baseL -match 'launcher') { $score -= 35; $why.Add('Launcher') }

            $scored.Add([pscustomobject]@{ Path = $c.Path; Score = $score; Size = $size; Depth = [int]$c.Depth; Reason = ($why -join ', ') })
        }
        if ($scored.Count -gt 0) {
            $best = $scored | Sort-Object @{ Expression = 'Score'; Descending = $true }, @{ Expression = 'Size'; Descending = $true }, @{ Expression = 'Depth'; Descending = $false } | Select-Object -First 1
            if (-not $best.Reason) { $best.Reason = 'beste Bewertung' }
            return $best
        }
    }
    return $null
}

# --- Whitelist/Blacklist-Abgleich --------------------------------------------------
# Namen werden vereinheitlicht (Kleinschreibung, Satzzeichen weg, "&" -> "and"), damit
# "Counter-Strike" = "Counter Strike" und "Garry's Mod" = "Garrys Mod" gilt.
function ConvertTo-PelMatchText([string]$s) {
    $t = ([string]$s).ToLowerInvariant()
    $t = $t -replace "[’'`´]", ''
    $t = $t -replace '&', ' and '
    $t = $t -replace '[^a-z0-9]+', ' '
    return $t.Trim()
}

# Whitelist: Einträge müssen als ganze Wörter vorkommen (kein "Battlefield 2" in
# "Battlefield 2142"). Kurze Einzelwörter ("Rust", "Game", "Black", "Doom") gelten nur
# exakt oder mit Versionszusatz ("Doom 3", "Diablo II") - sonst würde "Rust" auch
# "RustDesk" und "Game" jeden "... Game Launcher" aufnehmen. Umgekehrt zählt auch ein
# Ordnername, der vollständig in einem Eintrag steckt ("Raven Shield" ->
# "Tom Clancy's Rainbow Six 3: Raven Shield"), wenn er aus mind. 2 Wörtern besteht.
function Find-PelWhitelistMatch([string]$Name, [string[]]$Entries) {
    $n = ConvertTo-PelMatchText $Name
    if (-not $n) { return $null }
    $nWords = $n.Split(' ')
    foreach ($e in $Entries) {
        $ne = ConvertTo-PelMatchText $e
        if (-not $ne) { continue }
        if ($n -eq $ne) { return $e }
        $eWords = $ne.Split(' ')
        if ($eWords.Count -eq 1 -and $ne.Length -le 6) {
            if ($nWords.Count -ge 2 -and $nWords[0] -eq $ne -and $nWords[1] -match $script:PelRomanOrNumber) { return $e }
            continue
        }
        if ((" $n ").Contains(" $ne ")) { return $e }
        if ($nWords.Count -ge 2 -and $n.Length -ge 8 -and (" $ne ").Contains(" $n ")) { return $e }
    }
    return $null
}

# Blacklist: Begriffe als ganze Wörter/Wortgruppen ("tools" trifft "Authoring Tools",
# aber "mod" trifft NICHT mehr "Modern Warfare"); $ExactNames nur bei exakt gleichem Namen.
function Find-PelBlacklistMatch([string]$Name, [string[]]$Phrases, [string[]]$ExactNames = @()) {
    $n = ConvertTo-PelMatchText $Name
    if (-not $n) { return $null }
    foreach ($x in $ExactNames) { if ($n -eq (ConvertTo-PelMatchText $x)) { return $x } }
    foreach ($b in $Phrases) {
        $nb = ConvertTo-PelMatchText $b
        if ($nb -and (" $n ").Contains(" $nb ")) { return $b }
    }
    return $null
}

# Liefert die echte Spiel-EXE einer "Lan Games"-Verknüpfung. Steam-Spiele verweisen seit
# dem Umbau von Option 3 auf "steam.exe -applaunch <ID>"; die eigentliche Spiel-EXE steht
# dann in der Beschreibung ("... | exe=<Pfad>").
function Get-PelShortcutGameExe($Shortcut) {
    $d = [string]$Shortcut.Description
    if ($d -match '\|\s*exe=(.+)$') {
        $e = $matches[1].Trim()
        if ([System.IO.File]::Exists($e)) { return $e }
    }
    $t = [string]$Shortcut.TargetPath
    if ($t -and [System.IO.File]::Exists($t) -and ([System.IO.Path]::GetFileName($t) -ine 'steam.exe')) { return $t }
    return $null
}

# --- Eigene Listen (vom Nutzer pflegbar, Option 3 -> "Eigene Listen") ----------------
$script:PelUserListDir = 'C:\Project-Earth-Lan'
$script:PelUserWhitelistPath = Join-Path $script:PelUserListDir 'eigene_whitelist.txt'
$script:PelUserBlacklistPath = Join-Path $script:PelUserListDir 'eigene_blacklist.txt'
$script:PelExeOverridePath   = Join-Path $script:PelUserListDir 'exe_korrekturen.txt'

function Initialize-PelUserLists {
    try {
        if (-not [System.IO.Directory]::Exists($script:PelUserListDir)) { [void][System.IO.Directory]::CreateDirectory($script:PelUserListDir) }
        $utf8 = New-Object System.Text.UTF8Encoding($true)
        if (-not [System.IO.File]::Exists($script:PelUserWhitelistPath)) {
            [System.IO.File]::WriteAllText($script:PelUserWhitelistPath, (ConvertTo-PelLang "# Eigene Whitelist für den LAN Game Finder (Option 3)`r`n# Ein Spielname pro Zeile - wird zusätzlich zur eingebauten Liste berücksichtigt.`r`n# Zeilen mit # am Anfang werden ignoriert. Beispiel:`r`n# Medal of Honor Allied Assault`r`n"), $utf8)
        }
        if (-not [System.IO.File]::Exists($script:PelUserBlacklistPath)) {
            [System.IO.File]::WriteAllText($script:PelUserBlacklistPath, (ConvertTo-PelLang "# Eigene Blacklist für den LAN Game Finder (Option 3)`r`n# Ein Name (oder Namensteil als ganzes Wort) pro Zeile - solche Einträge werden nie verknüpft.`r`n# Tipp: Taucht ein falsches Programm in 'Lan Games' auf, hier seinen Namen eintragen. Beispiel:`r`n# Wallpaper Engine`r`n"), $utf8)
        }
        if (-not [System.IO.File]::Exists($script:PelExeOverridePath)) {
            [System.IO.File]::WriteAllText($script:PelExeOverridePath, (ConvertTo-PelLang "# EXE-Korrekturen für den LAN Game Finder (Option 3)`r`n# Format: Spielname | vollständiger Pfad zur richtigen .exe`r`n# Hat Vorrang vor der automatischen Auswahl. Spiele, die hier stehen, werden auch dann`r`n# verknüpft, wenn der Scan sie nicht selbst findet. Beispiel:`r`n# Battlefield 1942 | D:\Spiele\Battlefield 1942\BF1942.exe`r`n"), $utf8)
        }
    } catch { }
}

function Get-PelUserList([string]$Path) {
    $out = @()
    try {
        if ([System.IO.File]::Exists($Path)) {
            foreach ($ln in [System.IO.File]::ReadAllLines($Path, [System.Text.Encoding]::UTF8)) {
                $t = $ln.Trim()
                if ($t -and -not $t.StartsWith('#')) { $out += $t }
            }
        }
    } catch { }
    return $out
}

# Liefert die EXE-Korrekturen als Liste von @{ Name; Path; Key } (Key = vereinheitlichter Name).
function Get-PelExeOverrides {
    $out = @()
    foreach ($ln in @(Get-PelUserList $script:PelExeOverridePath)) {
        $parts = $ln -split '\|', 2
        if ($parts.Count -ne 2) { continue }
        $nm = $parts[0].Trim()
        $pt = $parts[1].Trim().Trim('"')
        if ($nm -and $pt) { $out += [pscustomobject]@{ Name = $nm; Path = $pt; Key = (ConvertTo-PelMatchText $nm) } }
    }
    return $out
}

# ------------------------------------------------------------------------------
# SPIELE: BEITRETEN ("Mitspielen"/"Join") & ERKENNUNG ("Wer spielt was")
# ------------------------------------------------------------------------------
# Gemeinsam genutzt vom Control Center (Live-Status -> "Mitspielen") und vom Server-
# Browser (Option 5 -> "Join"). Jede Regel beschreibt, wie ein Spiel direkt mit einem
# Server verbunden wird:
#   Exe      = typische Spiel-EXE(s) (klein geschrieben) - für die Erkennung laufender
#              Spiele und als bevorzugte EXE bei der Suche
#   Match    = Regex auf Spielname/GameSpy-"gamename"/Spielordner
#   Args     = Startparameter ({IP}/{PORT} werden ersetzt)
#   Uri      = Protokoll-Link statt EXE (z. B. Minecraft Bedrock, FiveM)
#   Steam    = $true -> bevorzugt steam://connect/IP:PORT (Source/GoldSrc)
#   Ports    = Standard-Spielports
#   QueryMap = Abfrageport -> Spielport (GameSpy/A2S melden oft den Abfrageport)
#   PortFallback = Regel darf auch allein anhand des Ports gewählt werden
# Egal welcher Weg: die Server-Adresse wird IMMER zusätzlich in die Zwischenablage
# kopiert, damit man sie im Spiel von Hand einfügen kann, falls der automatische
# Beitritt bei einem Spiel nicht greift.
$script:PelJoinRules = @(
    # --- Battlefield --------------------------------------------------------------
    @{ Key = 'bf1942';    Title = 'Battlefield 1942';    Exe = @('bf1942.exe');    Match = 'battlefield ?1942|bfield1942|\bbf ?1942\b'; Args = '+restart 1 +joinServer {IP}:{PORT}'; Ports = @(14567); QueryMap = @{ 23000 = 14567 }; PortFallback = $true }
    @{ Key = 'bfvietnam'; Title = 'Battlefield Vietnam'; Exe = @('bfvietnam.exe'); Match = 'battlefield ?vietnam|bfvietnam';           Args = '+restart 1 +joinServer {IP}:{PORT}'; Ports = @(15567); QueryMap = @{ 23000 = 15567 } }
    @{ Key = 'bf2142';    Title = 'Battlefield 2142';    Exe = @('bf2142.exe');    Match = 'battlefield ?2142|\bbf ?2142\b|\bstella\b'; Args = '+menu 1 +fullscreen 1 +joinServer {IP} +port {PORT}'; Ports = @(17567); QueryMap = @{ 29900 = 17567 } }
    @{ Key = 'bf2';       Title = 'Battlefield 2';       Exe = @('bf2.exe');       Match = 'battlefield ?2(?!\d)|\bbf2(?!\d)|battlefield2|project ?reality'; Args = '+menu 1 +fullscreen 1 +joinServer {IP} +port {PORT}'; Ports = @(16567); QueryMap = @{ 29900 = 16567 }; PortFallback = $true }
    # --- Unreal-Engine (Startparameter = Server-URL "IP:PORT") ---------------------
    @{ Key = 'ut2004';    Title = 'Unreal Tournament 2004'; Exe = @('ut2004.exe');  Match = 'ut ?2004|unreal tournament 2004'; Args = '{IP}:{PORT}'; Ports = @(7777); QueryMap = @{ 7778 = 7777; 7787 = 7777 } }
    @{ Key = 'ut2003';    Title = 'Unreal Tournament 2003'; Exe = @('ut2003.exe');  Match = 'ut ?2003|unreal tournament 2003|^ut2$'; Args = '{IP}:{PORT}'; Ports = @(7777); QueryMap = @{ 7778 = 7777; 7787 = 7777 } }
    @{ Key = 'ut3';       Title = 'Unreal Tournament 3';    Exe = @('ut3.exe');     Match = '\but ?3\b|ut3pc|unreal tournament 3'; Args = '{IP}:{PORT}'; Ports = @(7777); QueryMap = @{ 6500 = 7777 } }
    @{ Key = 'ut99';      Title = 'Unreal Tournament';      Exe = @('unrealtournament.exe'); Match = 'unreal ?tournament(?! ?(2003|2004|3\b))|\but ?99\b|^ut$'; Args = '{IP}:{PORT}'; Ports = @(7777); QueryMap = @{ 7778 = 7777 } }
    @{ Key = 'unrealgold'; Title = 'Unreal (Gold)';         Exe = @('unreal.exe');  Match = '^unreal( gold)?$|unreal ?gold'; Args = '{IP}:{PORT}'; Ports = @(7777); QueryMap = @{ 7778 = 7777 } }
