    $txtUrl.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtUrl.ForeColor = [System.Drawing.Color]::White
    $dlg.Controls.Add($txtUrl)

    $btnSave = New-Object System.Windows.Forms.Button
    $btnSave.Text = "Speichern"
    $btnSave.Location = New-Object System.Drawing.Point(435, 37)
    $btnSave.Size = New-Object System.Drawing.Size(100, 27)
    $btnSave.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnSave.ForeColor = [System.Drawing.Color]::White
