    $cmbFriends.Size = New-Object System.Drawing.Size(300, 25)
    $cmbFriends.DropDownStyle = 'DropDownList'
    $cmbFriends.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $cmbFriends.ForeColor = [System.Drawing.Color]::White
    $friends = Get-PelFriendsForDownloader
    foreach ($fr in $friends) { [void]$cmbFriends.Items.Add("$($fr.Name)  ($($fr.Ip))") }
    if ($cmbFriends.Items.Count -gt 0) { $cmbFriends.SelectedIndex = 0 }
    $dlg.Controls.Add($cmbFriends)

    $lblPort = New-Object System.Windows.Forms.Label
    $lblPort.Text = "Port:"
    $lblPort.Location = New-Object System.Drawing.Point(325, 106)
    $lblPort.Size = New-Object System.Drawing.Size(35, 20)
    $lblPort.ForeColor = [System.Drawing.Color]::White
    $dlg.Controls.Add($lblPort)

    $txtPort = New-Object System.Windows.Forms.TextBox
    $txtPort.Location = New-Object System.Drawing.Point(365, 103)
    $txtPort.Size = New-Object System.Drawing.Size(70, 25)
    $txtPort.Text = "9930"
    $txtPort.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtPort.ForeColor = [System.Drawing.Color]::White
    $dlg.Controls.Add($txtPort)

    $btnUseFriend = New-Object System.Windows.Forms.Button
    $btnUseFriend.Text = "Übernehmen"
    $btnUseFriend.Location = New-Object System.Drawing.Point(445, 102)
    $btnUseFriend.Size = New-Object System.Drawing.Size(90, 27)
    $btnUseFriend.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnUseFriend.ForeColor = [System.Drawing.Color]::White
    $btnUseFriend.FlatStyle = 'Flat'
    $btnUseFriend.Enabled = ($friends.Count -gt 0)
    $dlg.Controls.Add($btnUseFriend)
    if ($friends.Count -eq 0) {
        $lbl2.Text = "Keine Freunde gefunden (zuerst in Option 7 hinzufügen)."
    }

    $lbl3 = New-Object System.Windows.Forms.Label
    $lbl3.Text = "Eigene Verzeichnisse (Kategorien), eines pro Zeile - leer lassen für Standard (Windows Tools / Mods / Games):"
    $lbl3.Location = New-Object System.Drawing.Point(15, 145)
    $lbl3.Size = New-Object System.Drawing.Size(520, 35)
    $lbl3.ForeColor = [System.Drawing.Color]::White
    $lbl3.Font = $fontMain
    $dlg.Controls.Add($lbl3)

    $txtCats = New-Object System.Windows.Forms.TextBox
    $txtCats.Location = New-Object System.Drawing.Point(15, 182)
    $txtCats.Size = New-Object System.Drawing.Size(520, 120)
    $txtCats.Multiline = $true
    $txtCats.ScrollBars = 'Vertical'
    $txtCats.BackColor = [System.Drawing.Color]::FromArgb(40, 40, 40)
    $txtCats.ForeColor = [System.Drawing.Color]::White
    $isDefaultCats = (@($CurrentCategories) -join '|') -eq (@($script:PelDownloaderDefaultCategories) -join '|')
    if (-not $isDefaultCats) { $txtCats.Text = ($CurrentCategories -join "`r`n") }
    $dlg.Controls.Add($txtCats)

    $btnDetect = New-Object System.Windows.Forms.Button
    $btnDetect.Text = "Verzeichnisse automatisch vom Server finden"
    $btnDetect.Location = New-Object System.Drawing.Point(15, 310)
    $btnDetect.Size = New-Object System.Drawing.Size(320, 30)
    $btnDetect.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnDetect.ForeColor = [System.Drawing.Color]::White
    $btnDetect.FlatStyle = 'Flat'
    $dlg.Controls.Add($btnDetect)

    $lblStatus = New-Object System.Windows.Forms.Label
    $lblStatus.Text = ""
    $lblStatus.Location = New-Object System.Drawing.Point(15, 348)
    $lblStatus.Size = New-Object System.Drawing.Size(520, 20)
    $lblStatus.ForeColor = [System.Drawing.Color]::Gainsboro
    $dlg.Controls.Add($lblStatus)

    # ---- Eigenes Passwort für die eigenen freigegebenen Ordner (Gastgeber-Seite) ----------
    $sep1 = New-Object System.Windows.Forms.Label
    $sep1.BorderStyle = 'Fixed3D'
    $sep1.Location = New-Object System.Drawing.Point(15, 375)
    $sep1.Size = New-Object System.Drawing.Size(520, 2)
    $dlg.Controls.Add($sep1)

    $lbl4 = New-Object System.Windows.Forms.Label
    $lbl4.Text = "Eigenes Passwort für meine freigegebenen Ordner (an deine IP gebunden):"
    $lbl4.Location = New-Object System.Drawing.Point(15, 385)
    $lbl4.Size = New-Object System.Drawing.Size(520, 20)
    $lbl4.ForeColor = [System.Drawing.Color]::White
    $lbl4.Font = $fontMain
    $dlg.Controls.Add($lbl4)

    $lblOwnStatus = New-Object System.Windows.Forms.Label
    $lblOwnStatus.Location = New-Object System.Drawing.Point(15, 407)
    $lblOwnStatus.Size = New-Object System.Drawing.Size(520, 32)
    $lblOwnStatus.ForeColor = [System.Drawing.Color]::Gainsboro

    function Update-PelOwnPassStatusLabel {
        $info = Get-PelOwnPasswordInfo
        if ($info.HasPassword) {
            $lblOwnStatus.Text = "Passwortschutz AKTIV - gesetzt am $($info.SetLocal) für IP $($info.Ip). Musst du selbst an Freunde weitergeben."
        } else {
            $lblOwnStatus.Text = "Aktuell KEIN Passwort gesetzt - deine Ordner sind ohne Passwortabfrage im Manager erreichbar."
        }
    }
    Update-PelOwnPassStatusLabel
    $dlg.Controls.Add($lblOwnStatus)

    $txtOwnPass = New-Object System.Windows.Forms.TextBox
    $txtOwnPass.Location = New-Object System.Drawing.Point(15, 445)
    $txtOwnPass.Size = New-Object System.Drawing.Size(210, 25)
    $txtOwnPass.PasswordChar = '*'
    $txtOwnPass.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtOwnPass.ForeColor = [System.Drawing.Color]::White
    $dlg.Controls.Add($txtOwnPass)

    $btnSetOwnPass = New-Object System.Windows.Forms.Button
    $btnSetOwnPass.Text = "Passwort setzen"
    $btnSetOwnPass.Location = New-Object System.Drawing.Point(235, 444)
    $btnSetOwnPass.Size = New-Object System.Drawing.Size(140, 27)
    $btnSetOwnPass.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnSetOwnPass.ForeColor = [System.Drawing.Color]::White
    $btnSetOwnPass.FlatStyle = 'Flat'
    $dlg.Controls.Add($btnSetOwnPass)

    $btnResetOwnPass = New-Object System.Windows.Forms.Button
    $btnResetOwnPass.Text = "Zurücksetzen"
    $btnResetOwnPass.Location = New-Object System.Drawing.Point(385, 444)
    $btnResetOwnPass.Size = New-Object System.Drawing.Size(150, 27)
    $btnResetOwnPass.BackColor = [System.Drawing.Color]::FromArgb(150, 40, 40)
    $btnResetOwnPass.ForeColor = [System.Drawing.Color]::White
    $btnResetOwnPass.FlatStyle = 'Flat'
    $dlg.Controls.Add($btnResetOwnPass)

    $btnSetOwnPass.add_Click({
        if ([string]::IsNullOrWhiteSpace($txtOwnPass.Text)) {
            [PelI18n]::Show("Bitte ein Passwort eingeben.", "Hinweis", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
            return
        }
        $reminderFile = Set-PelOwnPassword -Password $txtOwnPass.Text
        $txtOwnPass.Text = ""
        Update-PelOwnPassStatusLabel
        if ($reminderFile) {
            [PelI18n]::Show("Passwort gesetzt und auf dem Desktop gespeichert, damit es nicht vergessen wird:`n$reminderFile`n`nGib es nur an Freunde weiter, denen du Zugriff erlauben willst - sie tragen es im Downloader-Fenster unter 'Server-Passwort' ein.", "Passwort gesetzt", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
        }
    })

    $btnResetOwnPass.add_Click({
        $confirm = [PelI18n]::Show("Eigenes Passwort wirklich entfernen? Deine Ordner sind danach ohne Passwortabfrage im Manager erreichbar (sofern in Caddy nicht separat geschützt).", "Passwort zurücksetzen", [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
        if ($confirm -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        Reset-PelOwnPassword
        Update-PelOwnPassStatusLabel
    })

    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Text = "Übernehmen & Schließen"
    $btnOk.Location = New-Object System.Drawing.Point(320, 480)
    $btnOk.Size = New-Object System.Drawing.Size(215, 30)
    $btnOk.BackColor = [System.Drawing.Color]::FromArgb(0, 150, 60)
    $btnOk.ForeColor = [System.Drawing.Color]::White
    $btnOk.FlatStyle = 'Flat'
    $btnOk.Font = $fontBold
    $dlg.Controls.Add($btnOk)

    $btnSave.add_Click({
        if ([string]::IsNullOrWhiteSpace($txtUrl.Text)) {
            [PelI18n]::Show("Bitte eine Server-Adresse eingeben.", "Hinweis", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
            return
        }
        $lblStatus.Text = "Adresse übernommen: $($txtUrl.Text)"
    })

    $btnUseFriend.add_Click({
        if ($cmbFriends.SelectedIndex -lt 0 -or $cmbFriends.SelectedIndex -ge $friends.Count) { return }
        $chosen = $friends[$cmbFriends.SelectedIndex]
        $port = if ([string]::IsNullOrWhiteSpace($txtPort.Text)) { "9930" } else { $txtPort.Text.Trim() }
        $txtUrl.Text = "http://$($chosen.Ip):$port"
        $lblStatus.Text = "Adresse von '$($chosen.Name)' übernommen: $($txtUrl.Text)"
    })

    $btnDetect.add_Click({
        if ([string]::IsNullOrWhiteSpace($txtUrl.Text)) {
            [PelI18n]::Show("Bitte zuerst eine Server-Adresse eintragen.", "Hinweis", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
            return
        }
        $lblStatus.Text = "Suche Verzeichnisse auf $($txtUrl.Text) ..."
        [System.Windows.Forms.Application]::DoEvents()
        $savedDl = Get-PelDownloaderSettings
        $pwForUrl = if ($txtUrl.Text.Trim().TrimEnd('/') -eq $savedDl.ServerUrl) { Unprotect-PelP2pPassword ([string]$savedDl.PasswordEnc) } else { '' }
        $found = Get-PelDownloaderTopFolders -RootUrl $txtUrl.Text -Headers (Get-PelDownloaderAuthHeaders $pwForUrl)
        if ($found.Count -gt 0) {
            $txtCats.Text = ($found -join "`r`n")
            $lblStatus.Text = "$($found.Count) Verzeichnis(se) gefunden und übernommen."
        } else {
            $lblStatus.Text = "Keine Verzeichnisse gefunden - ist der Server erreichbar und die Verzeichnisanzeige (z. B. 'file_server browse' in Caddy) aktiviert?"
        }
    })

    $btnOk.add_Click({
        $urlOut = $txtUrl.Text.Trim().TrimEnd('/')
        if ([string]::IsNullOrWhiteSpace($urlOut)) { $urlOut = $script:PelDownloaderDefaultUrl }
        $catLines = @($txtCats.Text -split "`r`n|`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
        $catsOut = if ($catLines.Count -gt 0) { $catLines } else { @($script:PelDownloaderDefaultCategories) }
        Save-PelDownloaderSettings -ServerUrl $urlOut -Categories $catsOut
        $script:dlgResult = [pscustomobject]@{ ServerUrl = $urlOut; Categories = $catsOut }
        $dlg.Tag = $script:dlgResult
        $dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $dlg.Close()
    })

    [void]$dlg.ShowDialog()
    return $dlg.Tag
}

# Schreibt die komplette Caddy/Docker-Anleitung (eigenen Download-Server fuer
# Option 1 einrichten) als .txt auf den Desktop - aufgerufen ueber den Button
# "Caddy/Docker Anleitung" im Tools/Mods/Games-Fenster. Der Text ist bewusst
# als reiner Text (keine Markdown-Zeichen) gehalten, damit er sich in Notepad
# angenehm liest.
function Invoke-PelWriteCaddyDockerGuide {
    param([string]$DesktopPath)

    $txtFile = Join-Path $DesktopPath "Caddy-Docker-Anleitung (Project Earth LAN Downloader).txt"
    $created = Get-Date -Format 'dd.MM.yyyy HH:mm'

    $guideBody = @'
EIGENEN DOWNLOAD-SERVER FUER DEN TOOLS/MODS/GAMES DOWNLOADER EINRICHTEN
Mit Docker Desktop + Caddy unter Windows 11
========================================================================

Diese Anleitung gehoert zum Button "Server & Freunde" in Option 1
(Tools, Mods & Games Downloader) des Project Earth LAN Managers.
Damit dieser Button eine eigene Adresse anbieten kann, braucht es
irgendwo einen HTTP-Server, der eure Ordner (Windows Tools / Mods /
Games oder eigene Verzeichnisse) als klickbare Verzeichnisliste
anzeigt. Genau das uebernimmt Caddy, ein leichter Webserver, den ihr
per Docker startet.


1. DOCKER DESKTOP INSTALLIEREN
------------------------------------------------------------------
 - Ladet Docker Desktop fuer Windows von docker.com herunter und
   installiert es.
 - Startet Docker Desktop einmal und wartet, bis unten links
   "Engine running" angezeigt wird (WSL2-Backend wird bei der
   Installation automatisch eingerichtet, falls es fehlt - ein
   Neustart kann dafuer noetig sein).
 - Prueft in einer PowerShell, ob alles funktioniert:

       docker --version
       docker run hello-world


2. ORDNERSTRUKTUR VORBEREITEN
------------------------------------------------------------------
Legt einen Ordner an, den Caddy spaeter freigibt, z. B.:

       C:\PEL-Downloads\
       |-- Windows Tools\
       |-- Mods\
       `-- Games\

Die Namen sind frei waehlbar - der Downloader kann sie spaeter
automatisch erkennen (siehe Punkt 6). Standardmaessig erwartet der
LAN Manager genau diese drei Ordner; eigene Namen funktionieren
ebenfalls, sobald ihr sie im Dialog "Server & Freunde" eintragt oder
automatisch suchen lasst.


3. CADDYFILE SCHREIBEN
------------------------------------------------------------------
Erstellt im selben Verzeichnis eine Datei ohne Endung namens
"Caddyfile" mit folgendem Inhalt:

       :9930 {
           root * /srv/downloads
           file_server browse
       }

 - ":9930" ist der Port, den der Downloader standardmaessig
   anspricht (derselbe Port, den auch die Firewall-Regel des LAN
   Managers fuer den Download-Server oeffnet).
 - "file_server browse" sorgt fuer die klickbare Verzeichnisliste,
   die der LAN Game Finder und der Downloader per HTTP auslesen.
 - "root * /srv/downloads" ist der Pfad INNERHALB des Containers -
   der wird im naechsten Schritt auf euren echten Windows-Ordner
   gemappt.


4. CADDY PER DOCKER STARTEN
------------------------------------------------------------------
Am einfachsten mit einer "docker-compose.yml" im selben Ordner:

       services:
         pel-downloader:
           image: caddy:2
           container_name: pel-downloader
           restart: unless-stopped
           ports:
             - "9930:9930"
           volumes:
             - "C:/PEL-Downloads:/srv/downloads"
             - "./Caddyfile:/etc/caddy/Caddyfile"

Dann in PowerShell im selben Ordner:

       docker compose up -d

Alternativ ohne Compose, direkt mit "docker run":

       docker run -d --name pel-downloader ^
         -p 9930:9930 ^
         -v "C:\PEL-Downloads:/srv/downloads" ^
         -v "%cd%\Caddyfile:/etc/caddy/Caddyfile" ^
         caddy:2

Testet lokal im Browser: http://localhost:9930/  - ihr solltet eure
Ordner (Windows Tools, Mods, Games) als klickbare Liste sehen.


5. FIREWALL & NETZWERK FREIGEBEN
------------------------------------------------------------------
Damit auch Freunde ueber euer P2P-Netzwerk zugreifen koennen,
muss Windows den Port 9930 fuer eingehende Verbindungen freigeben:

       New-NetFirewallRule -DisplayName "Project Earth LAN Downloader" `
         -Direction Inbound -Protocol TCP -LocalPort 9930 -Action Allow

Der LAN Manager selbst oeffnet fuer Option 1 nur eine AUSGEHENDE
Verbindung - wer selbst als Server hosten will, braucht diese
zusaetzliche eingehende Regel. Prueft ausserdem, dass ihr mit dem
gewuenschten P2P-Lobby verbunden seid (Control Center -> P2P-Netzwerk),
damit eure Freunde euch ueber die virtuelle IP (10.77.x.y) erreichen.


6. ADRESSE IM LAN MANAGER EINTRAGEN
------------------------------------------------------------------
 1. Oeffnet Option 1 -> "Server & Freunde".
 2. Tragt oben eure Adresse ein, z. B. http://<eure-P2P-IP>:9930,
    und klickt "Speichern".
 3. Optional: Klickt "Verzeichnisse automatisch vom Server finden",
    um eure Ordnernamen automatisch zu uebernehmen, statt sie von
    Hand einzutippen - das funktioniert, weil Caddys
    "file_server browse" dieselbe Art von Verzeichnisliste liefert,
    die auch der LAN Game Finder bereits versteht.
 4. "Uebernehmen & Schliessen" - das Downloader-Fenster laedt sich
    mit der neuen Adresse neu.

Die Einstellungen liegen danach in
C:\Project-Earth-Lan\downloader_server.json und bleiben auch nach
einem Neustart des Managers erhalten.


7. FREUNDEN ZUGRIFF GEBEN
------------------------------------------------------------------
Damit sich Spieler untereinander vernetzen koennen, ohne jedes Mal
IP und Port abzutippen:

 1. Tragt euch gegenseitig in Option 7 -> Freundesliste mit eurer
    virtuellen P2P-IP ein (falls noch nicht geschehen).
 2. Im Dialog "Server & Freunde" koennt ihr dann unter "Von einem
    Freund uebernehmen" einfach den Namen aus der Freundesliste
    auswaehlen, den Port eintragen (Standard 9930) und auf
    "Uebernehmen" klicken - der Downloader baut daraus automatisch
    http://<Freund-IP>:<Port> und laedt fortan von diesem Server
    statt vom eigenen.

So kann jeder in der Gruppe wahlweise seinen eigenen Server hosten
oder sich mit einem Klick auf den Server eines Freundes umschalten.


8. NUETZLICHE DOCKER-BEFEHLE
------------------------------------------------------------------
       docker compose logs -f        Live-Logs von Caddy ansehen
       docker compose restart        Nach Aenderung der Caddyfile neu laden
       docker compose down           Server stoppen

Nach jeder Aenderung an der Caddyfile reicht ein
"docker compose restart", damit die neue Konfiguration greift.


------------------------------------------------------------------
KURZ ZUSAMMENGEFASST: Docker Desktop hostet einen Caddy-Container,
der euren Windows-Ordner unter Port 9930 als durchsuchbare
Dateiliste freigibt. Der LAN Manager (Option 1) spricht diesen
Server ueber eine frei einstellbare Adresse an, die entweder
manuell, automatisch erkannt oder direkt aus der Freundesliste
(Option 7) uebernommen werden kann.
'@

    $header = "PROJECT EARTH LAN - CADDY/DOCKER ANLEITUNG`r`nErstellt am: $created`r`n" + ('=' * 72) + "`r`n`r`n"
    if ($script:PelLang -eq 'en') {
        $guideBody = $script:PelCaddyGuideEn
        $txtFile = Join-Path $DesktopPath "Caddy-Docker guide (Project Earth LAN downloader).txt"
        $header = "PROJECT EARTH LAN - CADDY/DOCKER GUIDE`r`nCreated on: $created`r`n" + ('=' * 72) + "`r`n`r`n"
    }
    $fullText = $header + $guideBody

    Set-Content -Path $txtFile -Value $fullText -Encoding UTF8 -Force
    return $txtFile
}

# ------------------------------------------------------------------------------
# OPTION 1: EIGENEN DATEI-SERVER HOSTEN (ersetzt Caddy/Docker für Normalnutzer)
# ------------------------------------------------------------------------------
# Eingebauter kleiner HTTP-Datei-Server, der genau das liefert, was der Downloader aus
# Option 1 erwartet: Ordneransicht mit Links (wie Caddy "file_server browse") und
# Dateien zum Herunterladen. Unterordner des Freigabe-Ordners = Kategorien im
# Downloader (Standard: "Windows Tools", "Mods", "Games").
#   - läuft im Control Center (wie Option 9) und bleibt aktiv, solange es offen ist
#   - nur erreichbar aus dem Heimnetz und dem P2P-Netz (10.77.x.y) - Verbindungen aus
#     dem Internet werden verworfen, eine Portfreigabe im Router ist NICHT nötig
#   - Passwortschutz über das vorhandene "Eigene Passwort" des Downloaders
#     (downloader_own_password.json, PBKDF2) - Freunde schicken es als HTTP-Basic-Auth
#   - nach 8 falschen Passwörtern wird die IP für 5 Minuten gesperrt
#   - nur lesen: kein Hochladen, kein Löschen, kein Verlassen des Freigabe-Ordners
#   - Einladungscode "PELF1:" + Base64url(Adresse | Passwort): Freunde klicken in
#     Option 1 auf "Einladung einfügen" - Adresse, Passwort und Kategorien sind drin
# Caddy/Docker bleibt als Profi-Variante (Anleitung) weiter möglich.
$script:PelFsConfigPath = 'C:\Project-Earth-Lan\fileserver.json'
$script:PelFsDefaultFolder = 'C:\Project-Earth-Lan\Freigabe'
$script:PelFsDefaultPort = 9930
$script:PelFsRecent = New-Object System.Collections.Generic.List[string]
$script:PelFsRecentSeq = 0
$script:PelFsPassStamp = ''
$script:PelFsUi = $null

$script:PelFsCode = @'
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

// Kleiner, nur lesender HTTP/1.1-Datei-Server fuer den Downloader (Option 1).
public static class PelFileServer
{
    static TcpListener _listener;
    static Thread _accept;
    static volatile bool _running;
    static string _rootSep = "";
    static int _port;
    static readonly object _pwLock = new object();
    static byte[] _salt;
    static byte[] _hash;
    static int _iter = 20000;
    static readonly ConcurrentDictionary<string, bool> _okTokens = new ConcurrentDictionary<string, bool>();
    static readonly ConcurrentDictionary<string, long[]> _fails = new ConcurrentDictionary<string, long[]>();
    static long _requests;
    static long _bytes;
    static int _active;

    // Ereignisse fuer das Control Center: "TYP|IP|Pfad|Bytes"
    public static readonly ConcurrentQueue<string> Events = new ConcurrentQueue<string>();

    public static bool IsRunning { get { return _running; } }
    public static int Port { get { return _port; } }
    public static string Root { get { return _rootSep; } }
    public static long Requests { get { return Interlocked.Read(ref _requests); } }
    public static long BytesSent { get { return Interlocked.Read(ref _bytes); } }
    public static int ActiveDownloads { get { return Thread.VolatileRead(ref _active); } }
    public static bool HasPassword { get { lock (_pwLock) { return _hash != null; } } }

    public static void SetPassword(string saltB64, string hashB64, int iterations)
    {
        lock (_pwLock)
        {
            if (string.IsNullOrEmpty(saltB64) || string.IsNullOrEmpty(hashB64)) { _salt = null; _hash = null; }
            else
            {
                _salt = Convert.FromBase64String(saltB64);
                _hash = Convert.FromBase64String(hashB64);
                _iter = iterations > 0 ? iterations : 20000;
            }
            _okTokens.Clear();
            _fails.Clear();
        }
    }

    public static void Start(string root, int port)
    {
        if (_running) Stop();
        string full = Path.GetFullPath(root);
        if (!Directory.Exists(full)) throw new DirectoryNotFoundException(full);
        string sep = Path.DirectorySeparatorChar.ToString();
        if (!full.EndsWith(sep)) full += sep;
        _rootSep = full;
        TcpListener l = new TcpListener(IPAddress.Any, port);
        l.Start(64);
        _listener = l;
        _port = port;
        Interlocked.Exchange(ref _requests, 0);
        Interlocked.Exchange(ref _bytes, 0);
        _running = true;
        _accept = new Thread(AcceptLoop);
        _accept.IsBackground = true;
        _accept.Name = "PEL-FileServer";
        _accept.Start(l);
    }

    public static void Stop()
    {
        _running = false;
        TcpListener l = _listener;
        _listener = null;
        if (l != null) { try { l.Stop(); } catch { } }
    }

    static void AcceptLoop(object o)
    {
        TcpListener l = (TcpListener)o;
        while (_running && ReferenceEquals(_listener, l))
        {
            TcpClient c = null;
            try { c = l.AcceptTcpClient(); }
            catch { if (!_running || !ReferenceEquals(_listener, l)) break; Thread.Sleep(100); continue; }
            ThreadPool.QueueUserWorkItem(Handle, c);
        }
    }

    static void Log(string type, string ip, string path, long bytes)
    {
        Events.Enqueue(type + "|" + ip + "|" + path + "|" + bytes);
        string dummy;
        while (Events.Count > 500 && Events.TryDequeue(out dummy)) { }
    }

    // Nur Heimnetz, P2P-Netz (10.77.x.y) und dieser PC - nie das Internet.
    public static bool IsAllowed(IPAddress a)
    {
        if (a == null) return false;
        if (a.IsIPv4MappedToIPv6) a = a.MapToIPv4();
        if (IPAddress.IsLoopback(a)) return true;
        if (a.AddressFamily != AddressFamily.InterNetwork) return false;
        byte[] b = a.GetAddressBytes();
        if (b[0] == 10) return true;
        if (b[0] == 172 && b[1] >= 16 && b[1] <= 31) return true;
        if (b[0] == 192 && b[1] == 168) return true;
        if (b[0] == 169 && b[1] == 254) return true;
        return false;
    }

    static string ReadHead(Stream s)
    {
        MemoryStream ms = new MemoryStream();
        int state = 0;
        while (ms.Length < 16384)
        {
            int b = s.ReadByte();
            if (b < 0) return null;
            ms.WriteByte((byte)b);
            if ((state == 0 || state == 2) && b == 13) state++;
            else if ((state == 1 || state == 3) && b == 10) { state++; if (state == 4) break; }
            else state = (b == 13) ? 1 : 0;
        }
        if (state != 4) return null;
        return Encoding.UTF8.GetString(ms.ToArray());
    }

    static void Send(Stream s, int code, string reason, string extraHeaders, string body, bool headOnly)
    {
        byte[] bb = Encoding.UTF8.GetBytes(body ?? "");
        string h = "HTTP/1.1 " + code + " " + reason + "\r\n" +
                   "Content-Type: text/html; charset=utf-8\r\n" +
                   "Content-Length: " + bb.Length + "\r\n" +
                   "Cache-Control: no-store\r\n" +
                   "Connection: close\r\n" +
                   "Server: PEL-FileServer\r\n" + (extraHeaders ?? "") + "\r\n";
        byte[] hb = Encoding.ASCII.GetBytes(h);
        s.Write(hb, 0, hb.Length);
        if (!headOnly && bb.Length > 0) s.Write(bb, 0, bb.Length);
        s.Flush();
    }

    static string Html(string t) { return WebUtility.HtmlEncode(t ?? ""); }

    static bool Locked(string ip)
    {
        long[] f;
        return _fails.TryGetValue(ip, out f) && f[1] > DateTime.UtcNow.Ticks;
    }

    static void RegisterFail(string ip)
    {
        long[] f = _fails.GetOrAdd(ip, delegate(string k) { return new long[2]; });
        lock (f)
        {
            f[0]++;
            if (f[0] >= 8) { f[0] = 0; f[1] = DateTime.UtcNow.AddMinutes(5).Ticks; Log("LOCK", ip, "", 0); }
        }
    }

    static bool FixedEquals(byte[] a, byte[] b)
    {
        if (a == null || b == null || a.Length != b.Length) return false;
        int d = 0;
        for (int i = 0; i < a.Length; i++) d |= a[i] ^ b[i];
        return d == 0;
    }

    // Basic-Auth: der Benutzername ist egal (Downloader schickt "pel"), nur das Passwort zaehlt.
    static bool CheckAuth(string header)
    {
        byte[] salt; byte[] hash; int iter;
        lock (_pwLock) { salt = _salt; hash = _hash; iter = _iter; }
        if (hash == null) return true;
        if (string.IsNullOrEmpty(header) || !header.StartsWith("Basic ", StringComparison.OrdinalIgnoreCase)) return false;
        string tok = header.Substring(6).Trim();
        bool ok;
        if (_okTokens.TryGetValue(tok, out ok) && ok) return true;
        string pw;
        try
        {
            string plain = Encoding.UTF8.GetString(Convert.FromBase64String(tok));
            int i = plain.IndexOf(':');
            pw = i >= 0 ? plain.Substring(i + 1) : plain;
        }
        catch { return false; }
        byte[] calc;
        using (Rfc2898DeriveBytes k = new Rfc2898DeriveBytes(pw, salt, iter)) { calc = k.GetBytes(hash.Length); }
        if (!FixedEquals(calc, hash)) return false;
        _okTokens[tok] = true;
        return true;
    }

    static string FormatSize(long n)
    {
        if (n >= 1073741824L) return (n / 1073741824.0).ToString("0.0") + " GB";
        if (n >= 1048576L) return (n / 1048576.0).ToString("0.0") + " MB";
        if (n >= 1024L) return (n / 1024.0).ToString("0") + " KB";
        return n + " B";
    }

    static bool Visible(FileSystemInfo i)
    {
        FileAttributes a = i.Attributes;
        if ((a & FileAttributes.Hidden) != 0 || (a & FileAttributes.System) != 0) return false;
        string n = i.Name.ToLowerInvariant();
        return n != "desktop.ini" && n != "thumbs.db";
    }

    static void Handle(object o)
    {
        TcpClient c = (TcpClient)o;
        string ip = "?";
        try
        {
            using (c)
            {
                IPEndPoint ep = c.Client.RemoteEndPoint as IPEndPoint;
                IPAddress addr = ep != null ? ep.Address : null;
                if (addr != null && addr.IsIPv4MappedToIPv6) addr = addr.MapToIPv4();
                ip = addr != null ? addr.ToString() : "?";
                if (!IsAllowed(addr)) { Log("DENY", ip, "", 0); return; }
                c.ReceiveTimeout = 15000;
                c.SendTimeout = 120000;
                c.NoDelay = true;
                NetworkStream ns = c.GetStream();
                string head = ReadHead(ns);
                if (head == null) return;
                Interlocked.Increment(ref _requests);

                string[] lines = head.Split(new string[] { "\r\n" }, StringSplitOptions.None);
                string[] rl = lines[0].Split(' ');
                if (rl.Length < 3) { Send(ns, 400, "Bad Request", null, "Bad Request", false); return; }
                string method = rl[0].ToUpperInvariant();
                string target = rl[1];
                bool headOnly = method == "HEAD";
                Dictionary<string, string> hdr = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 1; i < lines.Length; i++)
                {
                    int p = lines[i].IndexOf(':');
                    if (p > 0) hdr[lines[i].Substring(0, p).Trim()] = lines[i].Substring(p + 1).Trim();
                }
                if (method != "GET" && !headOnly) { Send(ns, 405, "Method Not Allowed", "Allow: GET, HEAD\r\n", "Nur Lesen erlaubt.", false); return; }

                if (Locked(ip)) { Send(ns, 429, "Too Many Requests", "Retry-After: 300\r\n", "Zu viele falsche Passwoerter - bitte 5 Minuten warten.", headOnly); return; }
                string auth;
                hdr.TryGetValue("Authorization", out auth);
                if (!CheckAuth(auth))
                {
                    if (!string.IsNullOrEmpty(auth)) { Log("AUTH", ip, "", 0); RegisterFail(ip); }
                    Send(ns, 401, "Unauthorized", "WWW-Authenticate: Basic realm=\"Project Earth LAN\", charset=\"UTF-8\"\r\n", "Passwort erforderlich.", headOnly);
                    return;
                }

                string path = target;
                int q = path.IndexOfAny(new char[] { '?', '#' });
                if (q >= 0) path = path.Substring(0, q);
                if (!path.StartsWith("/")) { Send(ns, 400, "Bad Request", null, "Bad Request", headOnly); return; }
                string decoded;
                try { decoded = Uri.UnescapeDataString(path); } catch { Send(ns, 400, "Bad Request", null, "Bad Request", headOnly); return; }
                string[] segs = decoded.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
                char[] bad = Path.GetInvalidFileNameChars();
                foreach (string sg in segs)
                {
                    if (sg == "." || sg == ".." || sg.IndexOfAny(bad) >= 0 || sg.Trim().Length == 0)
                    { Send(ns, 400, "Bad Request", null, "Bad Request", headOnly); return; }
                }
                string root = _rootSep;
                string sep = Path.DirectorySeparatorChar.ToString();
                string full = segs.Length == 0 ? root : Path.GetFullPath(Path.Combine(root, string.Join(sep, segs)));
                string cmp = full.EndsWith(sep) ? full : full + sep;
                if (!cmp.StartsWith(root, StringComparison.OrdinalIgnoreCase)) { Send(ns, 403, "Forbidden", null, "Forbidden", headOnly); return; }
                string rel = string.Join("/", segs);

                if (Directory.Exists(full))
                {
                    DirectoryInfo di = new DirectoryInfo(full);
                    if (segs.Length > 0 && !Visible(di)) { Send(ns, 404, "Not Found", null, "Nicht gefunden.", headOnly); return; }
                    if (!path.EndsWith("/")) { Send(ns, 301, "Moved Permanently", "Location: " + path + "/\r\n", "", headOnly); return; }
                    StringBuilder sb = new StringBuilder();
                    string title = "/" + rel + (rel.Length > 0 ? "/" : "");
                    sb.Append("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width\"><title>Project Earth LAN - ").Append(Html(title)).Append("</title>");
                    sb.Append("<style>body{font-family:Segoe UI,Arial,sans-serif;background:#191919;color:#eee;margin:24px}a{color:#6cb6ff;text-decoration:none}li{margin:4px 0}span{color:#999;margin-left:10px}</style></head><body>");
                    sb.Append("<h1>").Append(Html(title)).Append("</h1><ul>");
                    if (segs.Length > 0) sb.Append("<li><a href=\"../\">../</a></li>");
                    List<DirectoryInfo> dirs = new List<DirectoryInfo>();
                    List<FileInfo> files = new List<FileInfo>();
                    try
                    {
                        foreach (DirectoryInfo d in di.GetDirectories()) if (Visible(d)) dirs.Add(d);
                        foreach (FileInfo f in di.GetFiles()) if (Visible(f)) files.Add(f);
                    }
                    catch { }
                    dirs.Sort(delegate(DirectoryInfo x, DirectoryInfo y) { return string.Compare(x.Name, y.Name, StringComparison.OrdinalIgnoreCase); });
                    files.Sort(delegate(FileInfo x, FileInfo y) { return string.Compare(x.Name, y.Name, StringComparison.OrdinalIgnoreCase); });
                    foreach (DirectoryInfo d in dirs)
                        sb.Append("<li><a href=\"").Append(Uri.EscapeDataString(d.Name)).Append("/\">").Append(Html(d.Name)).Append("/</a></li>");
                    foreach (FileInfo f in files)
                        sb.Append("<li><a href=\"").Append(Uri.EscapeDataString(f.Name)).Append("\">").Append(Html(f.Name)).Append("</a><span>").Append(FormatSize(f.Length)).Append("</span></li>");
                    sb.Append("</ul></body></html>");
                    Send(ns, 200, "OK", null, sb.ToString(), headOnly);
                    return;
                }

                FileInfo fi = new FileInfo(full);
                if (!fi.Exists || !Visible(fi)) { Send(ns, 404, "Not Found", null, "Nicht gefunden.", headOnly); return; }
                long len = fi.Length;
                string fh = "HTTP/1.1 200 OK\r\n" +
                            "Content-Type: application/octet-stream\r\n" +
                            "Content-Length: " + len + "\r\n" +
                            "Content-Disposition: attachment; filename*=UTF-8''" + Uri.EscapeDataString(fi.Name) + "\r\n" +
                            "Connection: close\r\n" +
                            "Server: PEL-FileServer\r\n\r\n";
                byte[] fhb = Encoding.ASCII.GetBytes(fh);
                ns.Write(fhb, 0, fhb.Length);
                if (headOnly) { ns.Flush(); return; }
                Interlocked.Increment(ref _active);
                Log("GET", ip, rel, len);
                long sent = 0;
                try
                {
                    using (FileStream fs = new FileStream(full, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, 262144))
                    {
                        byte[] buf = new byte[262144];
                        int r;
                        while (_running && (r = fs.Read(buf, 0, buf.Length)) > 0)
                        {
                            ns.Write(buf, 0, r);
                            sent += r;
                            Interlocked.Add(ref _bytes, r);
                        }
                    }
                    ns.Flush();
                }
                finally
                {
                    Interlocked.Decrement(ref _active);
                    Log(sent == len ? "DONE" : "ABORT", ip, rel, sent);
                }
            }
        }
        catch { }
    }
}
'@

function Initialize-PelFileServerType {
    if (-not ('PelFileServer' -as [type])) { Add-Type -TypeDefinition $script:PelFsCode -Language CSharp }
}

# Text in der gewählten Sprache (für Texte mit Werten, die das Wörterbuch nicht kennt)
function Get-PelText([string]$De, [string]$En) { if ($script:PelLang -eq 'en') { return $En } return $De }

function Get-PelFileServerSettings {
    $s = [ordered]@{ Folder = $script:PelFsDefaultFolder; Port = $script:PelFsDefaultPort; Auto = $false }
    if (Test-Path -LiteralPath $script:PelFsConfigPath) {
        try {
            $o = Get-Content -LiteralPath $script:PelFsConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($o.Folder) { $s.Folder = [string]$o.Folder }
            if ([int]$o.Port -ge 1024 -and [int]$o.Port -le 65535) { $s.Port = [int]$o.Port }
            $s.Auto = [bool]$o.Auto
        } catch { }
    }
    return $s
}

function Save-PelFileServerSettings([string]$Folder, [int]$Port, [bool]$Auto) {
    try {
        if (-not (Test-Path -LiteralPath 'C:\Project-Earth-Lan')) { New-Item -ItemType Directory -Path 'C:\Project-Earth-Lan' -Force | Out-Null }
        ([ordered]@{ Folder = $Folder; Port = $Port; Auto = $Auto } | ConvertTo-Json) | Set-Content -LiteralPath $script:PelFsConfigPath -Encoding UTF8 -Force
    } catch { }
}

# Vorhandenes "Eigenes Passwort" (Option 1 -> Server & Freunde) als Rohdaten
function Get-PelOwnPasswordRecord {
    if (-not (Test-Path -LiteralPath $script:PelOwnPassConfigPath)) { return $null }
    try {
        $o = Get-Content -LiteralPath $script:PelOwnPassConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if ([string]::IsNullOrWhiteSpace([string]$o.PasswordHash) -or [string]::IsNullOrWhiteSpace([string]$o.Salt)) { return $null }
        return $o
    } catch { return $null }
}

# Passwort (neu) an den laufenden Server geben - auch wenn es in Option 1 geändert wurde
function Update-PelFileServerPassword {
    Initialize-PelFileServerType
    $stamp = ''
    try { if (Test-Path -LiteralPath $script:PelOwnPassConfigPath) { $stamp = (Get-Item -LiteralPath $script:PelOwnPassConfigPath).LastWriteTimeUtc.Ticks.ToString() } } catch { }
    $script:PelFsPassStamp = $stamp
    $rec = Get-PelOwnPasswordRecord
    if ($rec) { [PelFileServer]::SetPassword([string]$rec.Salt, [string]$rec.PasswordHash, 20000) }
    else { [PelFileServer]::SetPassword('', '', 0) }
}

function Test-PelFileServerPasswordChanged {
    $stamp = ''
    try { if (Test-Path -LiteralPath $script:PelOwnPassConfigPath) { $stamp = (Get-Item -LiteralPath $script:PelOwnPassConfigPath).LastWriteTimeUtc.Ticks.ToString() } } catch { }
    return ($stamp -ne $script:PelFsPassStamp)
}

# Freigabe-Ordner anlegen; ein neuer/leerer Ordner bekommt die Standard-Kategorien
function Initialize-PelShareFolder([string]$Folder) {
    if (-not (Test-Path -LiteralPath $Folder)) { New-Item -ItemType Directory -Path $Folder -Force | Out-Null }
    $hasSub = @(Get-ChildItem -LiteralPath $Folder -Directory -ErrorAction SilentlyContinue).Count -gt 0
    if (-not $hasSub) {
        foreach ($c in $script:PelDownloaderDefaultCategories) { New-Item -ItemType Directory -Path (Join-Path $Folder $c) -Force | Out-Null }
    }
}

function Start-PelFileServer {
    param([string]$Folder, [int]$Port)
    Initialize-PelFileServerType
    if ([PelFileServer]::IsRunning) { Stop-PelFileServer }
    Initialize-PelShareFolder $Folder
    # Firewall: nur Heimnetz (LocalSubnet) und P2P-Netz dürfen auf den TCP-Port
    $ruleName = "Project Earth LAN Datei-Server (TCP $Port)"
    try {
        if (-not (Get-NetFirewallRule -DisplayName $ruleName -ErrorAction SilentlyContinue)) {
            Get-NetFirewallRule -DisplayName 'Project Earth LAN Datei-Server*' -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue
            New-NetFirewallRule -DisplayName $ruleName -Direction Inbound -Action Allow -Protocol TCP -LocalPort $Port -RemoteAddress @('LocalSubnet', '10.77.0.0/16') -Profile Any -ErrorAction Stop | Out-Null
        }
    } catch { Write-PelLog -Level 'FILES' -Message "Firewall-Regel: $($_.Exception.Message)" }
    Update-PelFileServerPassword
    try { [PelFileServer]::Start($Folder, $Port) }
    catch { throw (Get-PelText "TCP-Port $Port ist schon belegt oder gesperrt (läuft dort schon ein anderer Server, z. B. Caddy?). Wähle einen anderen Port.`n`n$(Get-PelInnerMessage $_)" "TCP port $Port is already in use or blocked (is another server such as Caddy already running there?). Choose a different port.`n`n$(Get-PelInnerMessage $_)") }
    Write-PelLog -Level 'FILES' -Message "Datei-Server gestartet: TCP $Port, Ordner '$Folder', Passwort: $([PelFileServer]::HasPassword)"
}

function Stop-PelFileServer {
    if (-not ('PelFileServer' -as [type])) { return }
    if (-not [PelFileServer]::IsRunning) { return }
    [PelFileServer]::Stop()
    Write-PelLog -Level 'FILES' -Message 'Datei-Server beendet.'
}

function Test-PelFileServerRunning { return [bool](('PelFileServer' -as [type]) -and [PelFileServer]::IsRunning) }

# Adressen, unter denen Freunde den Server erreichen: P2P zuerst, dann Heimnetz
function Get-PelFileServerUrls([int]$Port) {
    $list = New-Object System.Collections.Generic.List[object]
    $p2p = @((Get-PelLocalIpSet).Keys | Where-Object { $_ -like '10.77.*' } | Sort-Object) | Select-Object -First 1
    if ($p2p) { $list.Add([pscustomobject]@{ Kind = 'P2P'; Url = "http://$($p2p):$Port" }) }
    $lan = Get-PelLanIpForInternet
    if (-not $lan -or $lan -like '10.77.*') {
        # LAN-Party ohne Internet: erste normale IPv4 dieses PCs nehmen
        $lan = @((Get-PelLocalIpSet).Keys | Where-Object { $_ -notlike '127.*' -and $_ -notlike '169.254.*' -and $_ -notlike '10.77.*' } | Sort-Object) | Select-Object -First 1
    }
    if ($lan) { $list.Add([pscustomobject]@{ Kind = 'LAN'; Url = "http://$($lan):$Port" }) }
    return $list
}

# ---- Einladungscode Datei-Server: "PELF1:" + Base64url(Adresse | Passwort) ---------------
function New-PelFileInviteCode([string]$Url, [string]$Password) {
    $raw = [System.Text.Encoding]::UTF8.GetBytes("$Url`n$Password")
    return 'PELF1:' + ([Convert]::ToBase64String($raw).TrimEnd('=').Replace('+', '-').Replace('/', '_'))
}

function ConvertFrom-PelFileInviteCode([string]$Text) {
    if (-not ($Text -match 'PELF1:([A-Za-z0-9_\-]+)')) { return $null }
    try {
        $b = $matches[1].Replace('-', '+').Replace('_', '/')
        while ($b.Length % 4) { $b += '=' }
        $parts = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b)) -split "`n", 2
        if (-not ($parts[0] -match '^https?://')) { return $null }
        $pw = if ($parts.Count -gt 1) { $parts[1] } else { '' }
        return [pscustomobject]@{ Url = $parts[0].TrimEnd('/'); Password = $pw }
    } catch { return $null }
}

function Format-PelBytes([double]$n) {
    if ($n -ge 1GB) { return ('{0:N1} GB' -f ($n / 1GB)) }
    if ($n -ge 1MB) { return ('{0:N1} MB' -f ($n / 1MB)) }
    if ($n -ge 1KB) { return ('{0:N0} KB' -f ($n / 1KB)) }
    return "$([int64]$n) B"
}

# Ereignis "TYP|IP|Pfad|Bytes" als lesbare Zeile (Name aus der Freundesliste, falls bekannt)
function Format-PelFileServerEvent([string]$Line) {
    $p = $Line -split '\|', 4
    if ($p.Count -lt 4) { return $Line }
    $who = $p[1]
    try { $fr = Get-PelFriendsForDownloader | Where-Object { $_.Ip -eq $p[1] } | Select-Object -First 1; if ($fr) { $who = "$($fr.Name) ($($p[1]))" } } catch { }
    $size = Format-PelBytes ([double]$p[3])
    switch ($p[0]) {
        'GET'   { return (Get-PelText "$who lädt: $($p[2]) ($size)" "$who is downloading: $($p[2]) ($size)") }
        'DONE'  { return (Get-PelText "$who fertig: $($p[2])" "$who finished: $($p[2])") }
        'ABORT' { return (Get-PelText "$who abgebrochen: $($p[2]) (nach $size)" "$who aborted: $($p[2]) (after $size)") }
        'AUTH'  { return (Get-PelText "$($who): falsches Passwort" "$($who): wrong password") }
        'LOCK'  { return (Get-PelText "$($who): 8x falsches Passwort - für 5 Minuten gesperrt" "$($who): wrong password 8 times - blocked for 5 minutes") }
        'DENY'  { return (Get-PelText "$($p[1]): abgewiesen (nicht aus Heimnetz/P2P-Netz)" "$($p[1]): rejected (not from home network/P2P network)") }
    }
    return $Line
}

# Vom Control-Center-Takt aufgerufen: Ereignisse abholen, Passwortänderungen übernehmen
function Receive-PelFileServerEvents {
    if (-not ('PelFileServer' -as [type])) { return }
    if ([PelFileServer]::IsRunning -and (Test-PelFileServerPasswordChanged)) { Update-PelFileServerPassword; Write-PelLog -Level 'FILES' -Message "Passwort übernommen (Schutz: $([PelFileServer]::HasPassword))." }
    $line = $null
    while ([PelFileServer]::Events.TryDequeue([ref]$line)) {
        $t = Format-PelFileServerEvent $line
        Write-PelLog -Level 'FILES' -Message $t
        $script:PelFsRecent.Add("[$(Get-Date -Format 'HH:mm:ss')] $t")
        $script:PelFsRecentSeq++
        while ($script:PelFsRecent.Count -gt 200) { $script:PelFsRecent.RemoveAt(0) }
    }
}

# ---- Dialog "Eigenen Datei-Server hosten" (Option 1, Teil 2) ------------------------------------------
# Nicht-modal (Control Center bleibt bedienbar). Die Handler greifen nur auf
# $script:PelFsUi zu, weil die lokalen Variablen nach dem Öffnen nicht mehr existieren.
function Update-PelFsDialogPassword {
    $u = $script:PelFsUi
    if (-not $u -or $u.Form.IsDisposed) { return }
    $rec = Get-PelOwnPasswordRecord
    if ($rec) {
        $plain = Unprotect-PelP2pPassword ([string]$rec.PasswordEnc)
        if ($plain) { $u.PwLabel.Text = (Get-PelText 'Passwortschutz AKTIV. Das Passwort steht im Einladungscode.' 'Password protection ACTIVE. The password is included in the invite code.') }
        else { $u.PwLabel.Text = (Get-PelText 'Passwortschutz AKTIV (gesetzt in Option 1). Es steht NICHT im Einladungscode - bitte separat weitergeben oder hier neu setzen.' 'Password protection ACTIVE (set in option 1). It is NOT in the invite code - share it separately or set it again here.') }
        $u.PwLabel.ForeColor = [System.Drawing.Color]::LightGreen
    } else {
        $u.PwLabel.Text = (Get-PelText 'Kein Passwort: jeder in deinem Heimnetz und in deiner P2P-Lobby kann die Dateien laden.' 'No password: everyone in your home network and your P2P lobby can download the files.')
        $u.PwLabel.ForeColor = [System.Drawing.Color]::Orange
    }
}

function Update-PelFsDialog {
    param([switch]$Force)
    Receive-PelFileServerEvents
    $u = $script:PelFsUi
    if (-not $u -or $u.Form.IsDisposed) { return }
    $running = Test-PelFileServerRunning
    foreach ($c in @($u.Folder, $u.Port, $u.Pick)) { $c.Enabled = -not $running }
    if ($running) {
        $u.Start.Text = (Get-PelText 'Freigabe beenden' 'Stop sharing')
        $u.Start.BackColor = [System.Drawing.Color]::FromArgb(160, 50, 40)
        $port = [PelFileServer]::Port
        # Adressen und Code nur alle 5 s neu ermitteln (Netzwerkkarten, DPAPI) - nicht jede Sekunde
        if ($Force -or [DateTime]::UtcNow -ge $u.NextNet) {
            $u.Urls = @(Get-PelFileServerUrls $port)
            $code = ''
            $best = $u.Urls | Select-Object -First 1
            if ($best) {
                $rec = Get-PelOwnPasswordRecord
                $plain = if ($rec) { Unprotect-PelP2pPassword ([string]$rec.PasswordEnc) } else { '' }
                $code = New-PelFileInviteCode $best.Url $plain
            }
            $u.CodeCache = $code
            $u.NextNet = [DateTime]::UtcNow.AddSeconds(5)
        }
        $urls = @($u.Urls)
        $act = [PelFileServer]::ActiveDownloads; $req = [PelFileServer]::Requests; $sent = Format-PelBytes ([PelFileServer]::BytesSent)
        $lines = @()
        $lines += (Get-PelText "Läuft (TCP $port)  |  Downloads aktiv: $act  |  Abrufe: $req  |  Übertragen: $sent" "Running (TCP $port)  |  Active downloads: $act  |  Requests: $req  |  Sent: $sent")
        foreach ($x in $urls) {
            if ($x.Kind -eq 'P2P') { $lines += (Get-PelText "P2P-Netz:  $($x.Url)   (für Freunde über das Internet)" "P2P network:  $($x.Url)   (for friends over the internet)") }
            else { $lines += (Get-PelText "Heimnetz:  $($x.Url)   (nur im selben Netzwerk)" "Home network:  $($x.Url)   (same network only)") }
        }
        if (-not ($urls | Where-Object { $_.Kind -eq 'P2P' })) { $lines += (Get-PelText 'Tipp: Für Freunde außerhalb deines Heimnetzes zuerst einer P2P-Lobby beitreten.' 'Tip: for friends outside your home network, join a P2P lobby first.') }
        $st = $lines -join "`r`n"
        if ($u.Status.Text -ne $st) { $u.Status.Text = $st }
        $u.Status.ForeColor = [System.Drawing.Color]::LightGreen
        if ($u.Code.Text -ne $u.CodeCache) { $u.Code.Text = $u.CodeCache }
    } else {
        $u.Start.Text = (Get-PelText 'Freigabe starten' 'Start sharing')
        $u.Start.BackColor = [System.Drawing.Color]::FromArgb(0, 135, 70)
        $u.Status.Text = (Get-PelText 'Nicht aktiv.' 'Not active.')
        $u.Status.ForeColor = [System.Drawing.Color]::LightGray
        $u.Code.Text = ''
        $u.NextNet = [DateTime]::MinValue
    }
    $u.Copy.Enabled = [bool]($running -and $u.Code.Text)
    if ($script:PelFsRecentSeq -ne $u.LogCount) {
        $u.Log.Text = ($script:PelFsRecent -join "`r`n")
        $u.LogCount = $script:PelFsRecentSeq
        $u.Log.SelectionStart = $u.Log.Text.Length
        $u.Log.ScrollToCaret()
    }
}

