    $btnOpen = New-FsButton (Get-PelText 'Öffnen' 'Open') 494 99 96 27 $grey
    [void](New-FsLabel (Get-PelText 'Einfach Dateien in die Unterordner kopieren (z. B. Windows Tools, Mods, Games). Neue Unterordner werden zu neuen Kategorien.' 'Simply copy files into the subfolders (e.g. Windows Tools, Mods, Games). New subfolders become new categories.') 15 130 575 36)

    [void](New-FsLabel 'Port (TCP):' 15 172 80 22)
    $numPort = New-Object System.Windows.Forms.NumericUpDown
    $numPort.Location = New-Object System.Drawing.Point(100, 170); $numPort.Size = New-Object System.Drawing.Size(90, 25)
