    $lblPw.ForeColor = [System.Drawing.Color]::Gainsboro
    $txtPw = New-FsText 12 62 200 $grpPw
    $btnPwNew = New-FsButton (Get-PelText 'Neu' 'New') 218 61 55 27 $grey $grpPw
    $btnPwSet = New-FsButton (Get-PelText 'Passwort setzen' 'Set password') 280 61 140 27 ([System.Drawing.Color]::FromArgb(0, 120, 215)) $grpPw
    $btnPwDel = New-FsButton (Get-PelText 'Entfernen' 'Remove') 426 61 137 27 ([System.Drawing.Color]::FromArgb(150, 40, 40)) $grpPw

