    $chkAuto.Text = (Get-PelText 'Beim Start des Managers automatisch freigeben' 'Share automatically when the manager starts')
    $chkAuto.Location = New-Object System.Drawing.Point(15, 314); $chkAuto.Size = New-Object System.Drawing.Size(575, 24)
