    $lblStatus.ForeColor = [System.Drawing.Color]::LightGray
    $lblStatus.Font = New-Object System.Drawing.Font('Consolas', 9)

    [void](New-FsLabel (Get-PelText 'Einladungscode (an Freunde schicken - enthält das Passwort):' 'Invite code (send to friends - contains the password):') 15 474 575 20)
    $txtCode = New-FsText 15 496 420
    $txtCode.ReadOnly = $true; $txtCode.BackColor = [System.Drawing.Color]::FromArgb(40, 40, 40)
    $btnCopy = New-FsButton (Get-PelText 'Einladung kopieren' 'Copy invite') 442 495 148 27 ([System.Drawing.Color]::FromArgb(0, 120, 215))

    $txtLog = New-Object System.Windows.Forms.TextBox
    $txtLog.Location = New-Object System.Drawing.Point(15, 530); $txtLog.Size = New-Object System.Drawing.Size(575, 140)
    $txtLog.Multiline = $true; $txtLog.ScrollBars = 'Vertical'; $txtLog.ReadOnly = $true
    $txtLog.BackColor = [System.Drawing.Color]::FromArgb(15, 15, 15); $txtLog.ForeColor = [System.Drawing.Color]::White
    $txtLog.Font = New-Object System.Drawing.Font('Consolas', 9)
    $f.Controls.Add($txtLog)

    $btnCaddy = New-FsButton (Get-PelText 'Profi-Variante: Caddy/Docker-Anleitung' 'Advanced: Caddy/Docker guide') 15 678 290 30 ([System.Drawing.Color]::FromArgb(90, 60, 130))
    $btnClose = New-FsButton (Get-PelText 'Schließen' 'Close') 490 678 100 30 $grey

    $tip = New-Object System.Windows.Forms.ToolTip
    $tip.SetToolTip($btnCopy, (Get-PelText 'Freunde klicken in Option 1 auf "Einladung einfügen" - Adresse, Passwort und Kategorien werden automatisch übernommen.' 'Friends click "Paste invite" in option 1 - address, password and categories are filled in automatically.'))
    $tip.SetToolTip($chkAuto, (Get-PelText 'Die Freigabe läuft, solange das Control Center offen ist (mit dem Autostart-Button oben also immer).' 'Sharing runs as long as the Control Center is open (so always, with autostart from option 8).'))

    $timer = New-Object System.Windows.Forms.Timer
    $timer.Interval = 1000
    $script:PelFsUi = [pscustomobject]@{ Form = $f; Title = $title; LogCount = -1; Status = $lblStatus; Code = $txtCode; Copy = $btnCopy; Start = $btnStart; Log = $txtLog
        PwLabel = $lblPw; PwText = $txtPw; Folder = $txtFolder; Port = $numPort; Pick = $btnPick; Auto = $chkAuto; Timer = $timer
        NextNet = [DateTime]::MinValue; Urls = @(); CodeCache = '' }

    $btnPick.Add_Click({
        $u = $script:PelFsUi
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = (Get-PelText 'Ordner wählen, den du für Freunde freigeben möchtest (Unterordner = Kategorien).' 'Choose the folder you want to share with friends (subfolders = categories).')
        if (Test-Path -LiteralPath $u.Folder.Text) { $dlg.SelectedPath = $u.Folder.Text }
        if ($dlg.ShowDialog($u.Form) -eq [System.Windows.Forms.DialogResult]::OK) { $u.Folder.Text = $dlg.SelectedPath }
        $dlg.Dispose()
    })
    $btnOpen.Add_Click({
        $u = $script:PelFsUi
        try { Initialize-PelShareFolder $u.Folder.Text; Start-Process explorer.exe -ArgumentList "`"$($u.Folder.Text)`"" }
        catch { Show-PelMsg ((Get-PelText 'Der Ordner konnte nicht geöffnet werden:' 'The folder could not be opened:') + "`n$($_.Exception.Message)") $u.Title ([System.Windows.Forms.MessageBoxIcon]::Warning) $u.Form }
    })
    $btnPwNew.Add_Click({ $script:PelFsUi.PwText.Text = New-PelRandomPassword 10 })
    $btnPwSet.Add_Click({
        $u = $script:PelFsUi
        if ($u.PwText.Text.Length -lt 4) { Show-PelMsg (Get-PelText "Bitte ein Passwort mit mindestens 4 Zeichen eingeben (oder 'Neu' klicken)." "Please enter a password with at least 4 characters (or click 'New').") $u.Title ([System.Windows.Forms.MessageBoxIcon]::Warning) $u.Form; return }
        [void](Set-PelOwnPassword -Password $u.PwText.Text)
        $u.PwText.Text = ''
        if (Test-PelFileServerRunning) { Update-PelFileServerPassword }
        Update-PelFsDialogPassword; Update-PelFsDialog -Force
        Show-PelMsg (Get-PelText "Passwort gesetzt. Es steht jetzt im Einladungscode und zur Sicherheit auch auf deinem Desktop ('Mein Downloader-Passwort (NICHT VERLIEREN).txt')." "Password set. It is now included in the invite code and, as a backup, on your desktop ('Mein Downloader-Passwort (NICHT VERLIEREN).txt').") $u.Title ([System.Windows.Forms.MessageBoxIcon]::Information) $u.Form
    })
    $btnPwDel.Add_Click({
        $u = $script:PelFsUi
        if (-not (Get-PelOwnPasswordRecord)) { return }
        $ans = [PelI18n]::Show($u.Form, (Get-PelText 'Passwort wirklich entfernen? Danach kann jeder in deinem Heimnetz und in deiner P2P-Lobby die freigegebenen Dateien laden.' 'Really remove the password? Afterwards everyone in your home network and your P2P lobby can download the shared files.'), $u.Title, [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        Reset-PelOwnPassword
        if (Test-PelFileServerRunning) { Update-PelFileServerPassword }
        Update-PelFsDialogPassword; Update-PelFsDialog -Force
    })
    $chkAuto.Add_CheckedChanged({
        $s0 = Get-PelFileServerSettings
        Save-PelFileServerSettings -Folder $s0.Folder -Port $s0.Port -Auto ([bool]$script:PelFsUi.Auto.Checked)
    })
    $btnStart.Add_Click({
        $u = $script:PelFsUi
        if (Test-PelFileServerRunning) { Stop-PelFileServer; Update-PelFsDialog -Force; return }
        $folder = $u.Folder.Text.Trim()
        if (-not $folder -or -not [System.IO.Path]::IsPathRooted($folder)) { Show-PelMsg (Get-PelText 'Bitte einen Freigabe-Ordner wählen (vollständiger Pfad, z. B. C:\Project-Earth-Lan\Freigabe).' 'Please choose a shared folder (full path, e.g. C:\Project-Earth-Lan\Freigabe).') $u.Title ([System.Windows.Forms.MessageBoxIcon]::Warning) $u.Form; return }
        $folder = $folder.TrimEnd('\')
        $drive = [System.IO.Path]::GetPathRoot($folder)
        $sys = @($env:windir, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:USERPROFILE, [System.Environment]::GetFolderPath('Desktop'), [System.Environment]::GetFolderPath('MyDocuments')) | Where-Object { $_ }
        if (($drive -and $folder -ieq $drive.TrimEnd('\')) -or ($sys | Where-Object { $folder -ieq $_.TrimEnd('\') })) {
            Show-PelMsg (Get-PelText 'Bitte kein ganzes Laufwerk und keinen Windows-, Programm- oder Benutzerordner freigeben, sondern einen eigenen Ordner (z. B. C:\Project-Earth-Lan\Freigabe).' 'Please do not share a whole drive or a Windows, program or user folder - use a dedicated folder instead (e.g. C:\Project-Earth-Lan\Freigabe).') $u.Title ([System.Windows.Forms.MessageBoxIcon]::Warning) $u.Form
            return
        }
        if (-not (Get-PelOwnPasswordRecord)) {
            $q = Get-PelText "Ohne Passwort freigeben? Dann kann jeder in deinem Heimnetz und in deiner P2P-Lobby die Dateien laden.`n`nEmpfohlen: 'Nein' klicken und oben ein Passwort setzen ('Neu' -> 'Passwort setzen')." "Share without a password? Then everyone in your home network and your P2P lobby can download the files.`n`nRecommended: click 'No' and set a password above ('New' -> 'Set password')."
            $ans = [PelI18n]::Show($u.Form, $q, $u.Title, [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
            if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        }
        $port = [int]$u.Port.Value
        $u.Form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            Start-PelFileServer -Folder $folder -Port $port
            Save-PelFileServerSettings -Folder $folder -Port $port -Auto ([bool]$u.Auto.Checked)
        } catch {
            Show-PelMsg ((Get-PelText 'Die Freigabe konnte nicht gestartet werden:' 'Sharing could not be started:') + "`n`n$($_.Exception.Message)") $u.Title ([System.Windows.Forms.MessageBoxIcon]::Error) $u.Form
        } finally { $u.Form.Cursor = [System.Windows.Forms.Cursors]::Default }
        Update-PelFsDialog -Force
    })
    $btnCopy.Add_Click({
        $u = $script:PelFsUi
        $code = $u.Code.Text
        if (-not $code) { return }
        $rec = Get-PelOwnPasswordRecord
        $pwNote = ''
        if ($rec -and -not (Unprotect-PelP2pPassword ([string]$rec.PasswordEnc))) { $pwNote = Get-PelText "`n`nHinweis: Das Passwort steht nicht im Code (es wurde in Option 1 gesetzt). Gib es separat weiter oder setze es hier neu." "`n`nNote: the password is not in the code (it was set in option 1). Share it separately or set it again here." }
        $ok = $false
        try { [System.Windows.Forms.Clipboard]::SetText($code); $ok = $true } catch { }
        if ($ok) { $msg = Get-PelText "Einladungscode kopiert.`n`nSchick ihn deinen Freunden (Discord, WhatsApp, ...). Sie öffnen Option 1 und klicken auf 'Einladung einfügen'." "Invite code copied.`n`nSend it to your friends (Discord, WhatsApp, ...). They open option 1 and click 'Paste invite'." }
        else { $msg = Get-PelText "Die Zwischenablage ist gerade blockiert. Hier der Code zum Abschreiben/Markieren:`n`n$code" "The clipboard is blocked right now. Here is the code to copy by hand:`n`n$code" }
        Show-PelMsg ($msg + $pwNote) $u.Title ([System.Windows.Forms.MessageBoxIcon]::Information) $u.Form
    })
    $btnCaddy.Add_Click({
        $desk = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::Desktop)
        $file = Invoke-PelWriteCaddyDockerGuide -DesktopPath $desk
        if ($file) { try { Start-Process -FilePath 'notepad.exe' -ArgumentList "`"$file`"" } catch { } }
    })
    $btnClose.Add_Click({ $script:PelFsUi.Form.Close() })
    $timer.Add_Tick({ try { Update-PelFsDialog } catch { } })
    $f.Add_FormClosed({
        if ($script:PelFsUi) { try { $script:PelFsUi.Timer.Stop(); $script:PelFsUi.Timer.Dispose() } catch { } }
        $script:PelFsUi = $null
    })

    Update-PelFsDialogPassword
    Update-PelFsDialog
    $timer.Start()
    if ($Owner) { $f.Show($Owner) } else { $f.Show() }
}

function Invoke-ToolsModsGames {
    $pelDlSettings = Get-PelDownloaderSettings
    $baseUrl = $pelDlSettings.ServerUrl
    $categories = @($pelDlSettings.Categories)
    $desktopPath = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::Desktop)
    $downloadBaseDir = Join-Path $desktopPath "Server_Downloads"

    if (-not (Test-Path -Path $downloadBaseDir)) {
        New-Item -ItemType Directory -Path $downloadBaseDir -Force | Out-Null
    }

    $form = (New-PelForm)
    $form.Text = "Tools, Mods, Games - HTTP Downloader"
    $form.Size = New-Object System.Drawing.Size(700, 752)
    $form.StartPosition = "CenterParent"
    $form.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $form.ForeColor = [System.Drawing.Color]::White

    $fontMain = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Regular)
    $fontBold = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)

    $lblHeader = New-Object System.Windows.Forms.Label
    $lblHeader.Text = "Server URL: $baseUrl"
    $lblHeader.Location = New-Object System.Drawing.Point(20, 18)
    $lblHeader.Size = New-Object System.Drawing.Size(490, 25)
    $lblHeader.Font = $fontBold
    $lblHeader.ForeColor = [System.Drawing.Color]::White
    $lblHeader.AutoEllipsis = $true
    $form.Controls.Add($lblHeader)

    # Zusätzlicher Button: eigene Server-Adresse setzen, Adresse eines Freundes
    # übernehmen (Freundesliste aus Option 7) oder Verzeichnisse automatisch
    # vom Server finden lassen - ohne die bisherige Standard-Funktion zu ändern.
    $btnServerSettings = New-Object System.Windows.Forms.Button
    $btnServerSettings.Text = "⚙ Server && Freunde"
    $btnServerSettings.Location = New-Object System.Drawing.Point(515, 13)
    $btnServerSettings.Size = New-Object System.Drawing.Size(145, 30)
    $btnServerSettings.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnServerSettings.ForeColor = [System.Drawing.Color]::White
    $btnServerSettings.FlatStyle = "Flat"
    $form.Controls.Add($btnServerSettings)

    $grpCategory = New-Object System.Windows.Forms.GroupBox
    $grpCategory.Text = "Kategorie auswählen"
    $grpCategory.Location = New-Object System.Drawing.Point(20, 45)
    $grpCategory.Size = New-Object System.Drawing.Size(640, 70)
    $grpCategory.ForeColor = [System.Drawing.Color]::White
    $grpCategory.Font = $fontMain

    $rbTools = New-Object System.Windows.Forms.RadioButton
    $rbTools.Text = "Windows Tools"
    $rbTools.Location = New-Object System.Drawing.Point(20, 25)
    $rbTools.Size = New-Object System.Drawing.Size(150, 30)
    $rbTools.Checked = $true
    $rbTools.ForeColor = [System.Drawing.Color]::White
    $grpCategory.Controls.Add($rbTools)

    $rbMods = New-Object System.Windows.Forms.RadioButton
    $rbMods.Text = "Mods"
    $rbMods.Location = New-Object System.Drawing.Point(180, 25)
    $rbMods.Size = New-Object System.Drawing.Size(110, 30)
    $rbMods.ForeColor = [System.Drawing.Color]::White
    $grpCategory.Controls.Add($rbMods)

    $rbGames = New-Object System.Windows.Forms.RadioButton
    $rbGames.Text = "Games"
    $rbGames.Location = New-Object System.Drawing.Point(310, 25)
    $rbGames.Size = New-Object System.Drawing.Size(150, 30)
    $rbGames.ForeColor = [System.Drawing.Color]::White
    $grpCategory.Controls.Add($rbGames)

    # Eigene (frei konfigurierte) Kategorien: werden nur eingeblendet, wenn über
    # den Button "Server & Freunde" eigene Verzeichnisse gespeichert wurden - der
    # Standardfall mit den drei festen Radio-Buttons bleibt sonst unverändert.
    $script:PelDlDefaultCatsJoined = ($script:PelDownloaderDefaultCategories -join '|')
    $usesCustomCats = (($categories -join '|') -ne $script:PelDlDefaultCatsJoined)

    $cmbCategory = New-Object System.Windows.Forms.ComboBox
    $cmbCategory.Location = New-Object System.Drawing.Point(20, 25)
    $cmbCategory.Size = New-Object System.Drawing.Size(590, 25)
    $cmbCategory.DropDownStyle = 'DropDownList'
    $cmbCategory.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $cmbCategory.ForeColor = [System.Drawing.Color]::White
    foreach ($cat in $categories) { [void]$cmbCategory.Items.Add($cat) }
    if ($cmbCategory.Items.Count -gt 0) { $cmbCategory.SelectedIndex = 0 }
    $grpCategory.Controls.Add($cmbCategory)

    $rbTools.Visible = -not $usesCustomCats
    $rbMods.Visible = -not $usesCustomCats
    $rbGames.Visible = -not $usesCustomCats
    $cmbCategory.Visible = $usesCustomCats

    $form.Controls.Add($grpCategory)

    # Liefert die aktuell gewählte Kategorie, egal ob Standard-Radiobuttons oder
    # die eigene (frei konfigurierte) Liste gerade aktiv ist.
    $getSelectedCategory = {
        if ($usesCustomCats) {
            if ($cmbCategory.SelectedItem) { [string]$cmbCategory.SelectedItem } else { $categories[0] }
        } else {
            if ($rbTools.Checked) { "Windows Tools" } elseif ($rbMods.Checked) { "Mods" } else { "Games" }
        }
    }

    $lblServerPass = New-Object System.Windows.Forms.Label
    $lblServerPass.Text = "🔒 Server-Passwort:"
    $lblServerPass.Location = New-Object System.Drawing.Point(20, 125)
    $lblServerPass.Size = New-Object System.Drawing.Size(130, 25)
    $lblServerPass.ForeColor = [System.Drawing.Color]::White
    $form.Controls.Add($lblServerPass)

    # Generisches Server-Passwort (nicht mehr an die Kategorie "Games" gebunden):
    # wird als HTTP-Basic-Auth beim Auslesen/Herunterladen mitgeschickt, falls der
    # Gastgeber für seinen Server ein eigenes Passwort gesetzt hat (siehe Button
    # "Server & Freunde" -> "Eigenes Passwort"). Muss manuell vom Gastgeber an
    # Freunde weitergegeben werden - der LAN Manager verteilt es nicht automatisch.
    $txtServerPass = New-Object System.Windows.Forms.TextBox
    $txtServerPass.Location = New-Object System.Drawing.Point(155, 122)
    $txtServerPass.Size = New-Object System.Drawing.Size(150, 25)
    $txtServerPass.PasswordChar = '*'
    $txtServerPass.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtServerPass.ForeColor = [System.Drawing.Color]::White
    $txtServerPass.Text = Unprotect-PelP2pPassword ([string]$pelDlSettings.PasswordEnc)
    $form.Controls.Add($txtServerPass)

    # Baut den Authorization-Header, falls ein Server-Passwort eingetragen wurde
    # (leer = kein Header, also unverändertes Verhalten für Server ohne Passwortschutz).
    $getAuthHeaders = {
        if ([string]::IsNullOrWhiteSpace($txtServerPass.Text)) { return @{} }
        $tok = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes("pel:$($txtServerPass.Text)"))
        return @{ Authorization = "Basic $tok" }
    }

    $btnScan = New-Object System.Windows.Forms.Button
    $btnScan.Text = "Ordner und Dateien auslesen"
    $btnScan.Location = New-Object System.Drawing.Point(310, 120)
    $btnScan.Size = New-Object System.Drawing.Size(205, 30)
    $btnScan.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnScan.ForeColor = [System.Drawing.Color]::White
    $btnScan.FlatStyle = "Flat"
    $form.Controls.Add($btnScan)

    # Einladungscode eines Freundes (Option 1 "Eigenen Datei-Server hosten") übernehmen:
    # Adresse, Passwort und Kategorien werden automatisch eingetragen.
    $btnPasteInvite = New-Object System.Windows.Forms.Button
    $btnPasteInvite.Text = "Einladung einfügen"
    $btnPasteInvite.Location = New-Object System.Drawing.Point(520, 120)
    $btnPasteInvite.Size = New-Object System.Drawing.Size(140, 30)
    $btnPasteInvite.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnPasteInvite.ForeColor = [System.Drawing.Color]::White
    $btnPasteInvite.FlatStyle = "Flat"
    $form.Controls.Add($btnPasteInvite)

    $lstFiles = New-Object System.Windows.Forms.ListBox
    $lstFiles.Location = New-Object System.Drawing.Point(20, 160)
    $lstFiles.Size = New-Object System.Drawing.Size(640, 220)
    $lstFiles.SelectionMode = "MultiExtended"
    $lstFiles.BackColor = [System.Drawing.Color]::FromArgb(40, 40, 40)
    $lstFiles.ForeColor = [System.Drawing.Color]::White
    $lstFiles.Font = $fontMain
    $form.Controls.Add($lstFiles)

    $btnDownload = New-Object System.Windows.Forms.Button
    $btnDownload.Text = "Ausgewählte Datei(en) herunterladen"
    $btnDownload.Location = New-Object System.Drawing.Point(20, 390)
    $btnDownload.Size = New-Object System.Drawing.Size(280, 35)
    $btnDownload.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnDownload.ForeColor = [System.Drawing.Color]::White
    $btnDownload.FlatStyle = "Flat"
    $btnDownload.Font = $fontBold
    $form.Controls.Add($btnDownload)

    $btnOpenFolder = New-Object System.Windows.Forms.Button
    $btnOpenFolder.Text = "Ordner öffnen"
    $btnOpenFolder.Location = New-Object System.Drawing.Point(310, 390)
    $btnOpenFolder.Size = New-Object System.Drawing.Size(140, 35)
    $btnOpenFolder.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnOpenFolder.ForeColor = [System.Drawing.Color]::White
    $btnOpenFolder.FlatStyle = "Flat"
    $btnOpenFolder.Font = $fontBold
    $form.Controls.Add($btnOpenFolder)

    # Zusätzlicher Button: schreibt die komplette Caddy/Docker-Anleitung (eigenen
    # Download-Server einrichten) als .txt auf den Desktop.
    $btnGuide = New-Object System.Windows.Forms.Button
    $btnGuide.Text = "📄 Caddy/Docker Anleitung"
    $btnGuide.Location = New-Object System.Drawing.Point(460, 390)
    $btnGuide.Size = New-Object System.Drawing.Size(200, 35)
    $btnGuide.BackColor = [System.Drawing.Color]::FromArgb(90, 60, 130)
    $btnGuide.ForeColor = [System.Drawing.Color]::White
    $btnGuide.FlatStyle = "Flat"
    $btnGuide.Font = $fontBold
    $form.Controls.Add($btnGuide)

    $progressBar = New-Object System.Windows.Forms.ProgressBar
    $progressBar.Location = New-Object System.Drawing.Point(20, 432)
    $progressBar.Size = New-Object System.Drawing.Size(640, 18)
    $progressBar.Minimum = 0
    $progressBar.Maximum = 100
    $progressBar.Value = 0
    $form.Controls.Add($progressBar)

    $txtDebug = New-Object System.Windows.Forms.TextBox
    $txtDebug.Location = New-Object System.Drawing.Point(20, 460)
    $txtDebug.Size = New-Object System.Drawing.Size(640, 190)
    $txtDebug.Multiline = $true
    $txtDebug.ScrollBars = "Vertical"
    $txtDebug.ReadOnly = $true
    $txtDebug.BackColor = [System.Drawing.Color]::FromArgb(15, 15, 15)
    $txtDebug.ForeColor = [System.Drawing.Color]::White
    $txtDebug.Font = New-Object System.Drawing.Font("Consolas", 9)
    $form.Controls.Add($txtDebug)

    # Option 1 Teil 2: eigener Datei-Server. Er läuft im Control Center (bleibt dort aktiv,
    # auch wenn dieses Fenster zu ist) - deshalb nur eine Bitte an das Control Center.
    $btnOwnServer = New-Object System.Windows.Forms.Button
    $btnOwnServer.Text = Get-PelText 'Eigener Datei-Server: selbst Dateien für Freunde anbieten ...' 'Own file server: offer files to friends yourself ...'
    $btnOwnServer.Location = New-Object System.Drawing.Point(20, 658)
    $btnOwnServer.Size = New-Object System.Drawing.Size(640, 34)
    $btnOwnServer.FlatStyle = 'Flat'
    $btnOwnServer.BackColor = [System.Drawing.Color]::FromArgb(0, 122, 204)
    $btnOwnServer.ForeColor = [System.Drawing.Color]::White
    $btnOwnServer.UseMnemonic = $false
    $btnOwnServer.Add_Click({
        try {
            Write-PelTextFileAtomic $script:PelFileServerReqFile ([string](Get-PelNowMs))
            [PelI18n]::Show($form, (Get-PelText "Der Datei-Server öffnet sich im Control Center (Hauptfenster).`n`nEr läuft dort weiter, auch wenn du dieses Fenster schließt." "The file server opens in the Control Center (main window).`n`nIt keeps running there even if you close this window."), 'Datei-Server', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
        } catch { }
    })
    $form.Controls.Add($btnOwnServer)

    $logCallback = {
        param([string]$msg)
        $time = Get-Date -Format "HH:mm:ss"
        [PelI18n]::Append($txtDebug, "[$time] $msg`r`n")
        $txtDebug.SelectionStart = $txtDebug.Text.Length
        $txtDebug.ScrollToCaret()
    }

    $btnScan.add_Click({
        $lstFiles.Items.Clear()
        $progressBar.Value = 0
        $category = & $getSelectedCategory
        
        &$logCallback "Kategorie gewählt: '$category'. Starte Auslesevorgang..."
        
        $targetCatUrl = "$baseUrl/$([System.Uri]::EscapeDataString($category))/"
        $authHeaders = & $getAuthHeaders
        $files = Get-HTTPDirectoryContent -targetUrl $targetCatUrl -logCallback $logCallback -Headers $authHeaders

        foreach ($file in $files) {
            [void]$lstFiles.Items.Add($file)
        }
        
        &$logCallback "Vorgang beendet. $($files.Count) Datei(en) erfasst."
        if ($files.Count -gt 0) {
            # Passwort hat funktioniert -> verschlüsselt für diesen Server merken
            if ($txtServerPass.Text -ne (Unprotect-PelP2pPassword ([string]$pelDlSettings.PasswordEnc))) {
                $encNow = Protect-PelP2pPassword $txtServerPass.Text
                Save-PelDownloaderSettings -ServerUrl $baseUrl -Categories $categories -PasswordEnc $encNow
                $pelDlSettings.PasswordEnc = $encNow
            }
        } else {
            &$logCallback (Get-PelText "Keine Dateien gefunden. Hat der Server ein Passwort? Dann oben eintragen - oder den Einladungscode des Freundes einfügen. Läuft seine Freigabe (Option 1) und seid ihr in derselben P2P-Lobby?" "No files found. Does the server have a password? Then enter it above - or paste your friend's invite code. Is their sharing (option 1) running and are you in the same P2P lobby?")
        }
    })

    $btnDownload.add_Click({
        if ($lstFiles.SelectedItems.Count -eq 0) {
            [PelI18n]::Show("Bitte wähle mindestens eine Datei aus der Liste aus.", "Hinweis", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning)
            return
        }

        $category = & $getSelectedCategory
        $targetDir = Join-Path $downloadBaseDir $category
        if (-not (Test-Path -Path $targetDir)) {
            New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
        }

        $selectedFiles = @($lstFiles.SelectedItems)
        $btnDownload.Enabled = $false
        $totalFiles = $selectedFiles.Count
        $currentFileIndex = 0

        foreach ($selectedFileRel in $selectedFiles) {
            $currentFileIndex++
            $fileName = [System.IO.Path]::GetFileName($selectedFileRel)
            $destinationFile = Join-Path $targetDir $fileName

            $escapedRelPath = ($selectedFileRel -split '/' | ForEach-Object { [System.Uri]::EscapeDataString($_) }) -join '/'
            $downloadUrl = "$baseUrl/$([System.Uri]::EscapeDataString($category))/$escapedRelPath"

            &$logCallback "[$currentFileIndex/$totalFiles] Starte Download von: $fileName"
            $progressBar.Value = 0

            try {
                $request = [System.Net.HttpWebRequest]::Create($downloadUrl)
                $request.Method = "GET"
                $request.UserAgent = "Mozilla/5.0"
                $authH = & $getAuthHeaders
                foreach ($hKey in $authH.Keys) { $request.Headers.Add($hKey, $authH[$hKey]) }
                
                $response = $request.GetResponse()
                $totalBytes = $response.ContentLength
                $responseStream = $response.GetResponseStream()
                $targetStream = [System.IO.File]::Create($destinationFile)

                $buffer = New-Object byte[] 1048576
                $bytesRead = 0
                $totalRead = 0
                $sw = [System.Diagnostics.Stopwatch]::StartNew()
                $lastLogTime = [System.Diagnostics.Stopwatch]::StartNew()

                while (($bytesRead = $responseStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
                    $targetStream.Write($buffer, 0, $bytesRead)
                    $totalRead += $bytesRead

                    if ($totalBytes -gt 0) {
                        $percent = [int](($totalRead / $totalBytes) * 100)
                        $progressBar.Value = [Math]::Min(100, $percent)
                    }

                    if ($lastLogTime.ElapsedMilliseconds -ge 1000 -or $totalRead -eq $totalBytes) {
                        $elapsedSec = $sw.Elapsed.TotalSeconds
                        if ($elapsedSec -gt 0) {
                            $bytesPerSec = $totalRead / $elapsedSec
                            $speedMBs = [Math]::Round($bytesPerSec / 1MB, 2)
                            $currentMB = [Math]::Round($totalRead / 1MB, 2)
                            $totalMB = [Math]::Round($totalBytes / 1MB, 2)
                            $percentVal = if ($totalBytes -gt 0) { [Math]::Min(100, [int](($totalRead / $totalBytes) * 100)) } else { 0 }
                            &$logCallback "Fortschritt: $percentVal% ($currentMB MB / $totalMB MB) | Speed: $speedMBs MB/s"
                        }
                        $lastLogTime.Restart()
                    }

                    [System.Windows.Forms.Application]::DoEvents()
                }

                $sw.Stop()
                $targetStream.Close()
                $responseStream.Close()
                $response.Close()

                $progressBar.Value = 100
                &$logCallback "DOWNLOAD ERFOLGREICH: $fileName"
            } catch {
                &$logCallback "DOWNLOAD FEHLER bei $fileName : $($_.Exception.Message)"
            }
        }

        $btnDownload.Enabled = $true
        [PelI18n]::Show("Download-Vorgang für alle ausgewählten Dateien abgeschlossen!", "Erfolg", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
    })

    $btnOpenFolder.add_Click({
        $category = & $getSelectedCategory
        $targetDir = Join-Path $downloadBaseDir $category
        
        if (-not (Test-Path -Path $targetDir)) {
            New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
        }
        
        Start-Process explorer.exe -ArgumentList "`"$targetDir`""
        &$logCallback "Zielordner im Explorer geöffnet: $targetDir"
    })

    $btnGuide.add_Click({
        $guideFile = Invoke-PelWriteCaddyDockerGuide -DesktopPath $desktopPath
        &$logCallback "Caddy/Docker-Anleitung gespeichert: $guideFile"
        $ans = [PelI18n]::Show("Die Anleitung wurde auf deinem Desktop gespeichert:`n$guideFile`n`nJetzt öffnen?", "Caddy/Docker Anleitung erstellt", [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Information)
        if ($ans -eq [System.Windows.Forms.DialogResult]::Yes) {
            try { Start-Process -FilePath 'notepad.exe' -ArgumentList "`"$guideFile`"" } catch { }
        }
    })

    $btnPasteInvite.add_Click({
        $typed = ''
        $clip = ''
        try { $clip = [System.Windows.Forms.Clipboard]::GetText() } catch { }
        $inv = ConvertFrom-PelFileInviteCode $clip
        if (-not $inv -and "$clip" -notmatch 'PEL1:') {
            try { Add-Type -AssemblyName Microsoft.VisualBasic } catch { }
            $typed = [Microsoft.VisualBasic.Interaction]::InputBox((Get-PelText 'Einladungscode des Datei-Servers einfügen (beginnt mit PELF1:):' 'Paste the file server invite code (starts with PELF1:):'), (Get-PelText 'Einladung einfügen' 'Paste invite'), '')
            if (-not $typed) { return }
            $inv = ConvertFrom-PelFileInviteCode $typed
        }
        if (-not $inv) {
            if ("$clip $typed" -match 'PEL1:') { $msg = Get-PelText "Das ist ein Lobby-Code (PEL1:). Den bitte im Control Center in der P2P-Box unter 'Einladung einfügen' verwenden.`n`nFür den Downloader brauchst du den Code aus Option 1 deines Freundes (beginnt mit PELF1:)." "This is a lobby code (PEL1:). Please use it in the Control Center, P2P box, 'Paste invite'.`n`nFor the downloader you need the code from your friend's option 1 (starts with PELF1:)." }
            else { $msg = Get-PelText "Das ist kein gültiger Einladungscode. Er beginnt mit 'PELF1:' - lass ihn dir vom Freund (Control Center -> 1. Downloader & Datei-Server -> Eigenen Datei-Server hosten -> 'Einladung kopieren') noch einmal schicken." "This is not a valid invite code. It starts with 'PELF1:' - ask your friend to send it again (Control Center -> 1. Downloader & file server -> Host your own file server -> 'Copy invite')." }
            [PelI18n]::Show($form, $msg, (Get-PelText 'Einladung einfügen' 'Paste invite'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
            return
        }
        &$logCallback (Get-PelText "Einladung erkannt: $($inv.Url) - suche Kategorien ..." "Invite recognized: $($inv.Url) - looking for categories ...")
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        [System.Windows.Forms.Application]::DoEvents()
        try { $found = @(Get-PelDownloaderTopFolders -RootUrl $inv.Url -Headers (Get-PelDownloaderAuthHeaders $inv.Password)) }
        finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
        $catsNew = if ($found.Count -gt 0) { $found } else { @($script:PelDownloaderDefaultCategories) }
        Save-PelDownloaderSettings -ServerUrl $inv.Url -Categories $catsNew -PasswordEnc (Protect-PelP2pPassword $inv.Password)
        if ($found.Count -gt 0) {
            [PelI18n]::Show($form, (Get-PelText "Server übernommen:`n$($inv.Url)`n`nKategorien: $($found -join ', ')`n`nDas Fenster wird neu geladen." "Server added:`n$($inv.Url)`n`nCategories: $($found -join ', ')`n`nThe window will reload."), (Get-PelText 'Einladung einfügen' 'Paste invite'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
        } else {
            [PelI18n]::Show($form, (Get-PelText "Die Adresse wurde übernommen, der Server antwortet aber gerade nicht:`n$($inv.Url)`n`nPrüfe: Läuft beim Freund die Freigabe (Option 1)? Seid ihr in derselben P2P-Lobby (Control Center, P2P-Box)?`nDanach einfach 'Ordner und Dateien auslesen' klicken." "The address was saved, but the server is not responding right now:`n$($inv.Url)`n`nCheck: is your friend's sharing (option 1) running? Are you in the same P2P lobby (Control Center, P2P box)?`nThen simply click 'Read folders and files'."), (Get-PelText 'Einladung einfügen' 'Paste invite'), [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
        }
        $form.Close()
        Invoke-ToolsModsGames
    })

    $btnServerSettings.add_Click({
        $res = Show-PelDownloaderServerDialog -CurrentUrl $baseUrl -CurrentCategories $categories
        if ($res) {
            [PelI18n]::Show("Einstellungen gespeichert:`nServer: $($res.ServerUrl)`nKategorien: $($res.Categories -join ', ')`n`nDas Fenster wird neu geladen.", "Downloader", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
            $form.Close()
            Invoke-ToolsModsGames
        }
    })

    &$logCallback "Tools, Mods, Games Manager gestartet."
    &$logCallback (Get-PelText "Tipp: Code von einem Freund? Oben auf 'Einladung einfügen' klicken. Selbst Dateien anbieten: Control Center -> 1. Downloader & Datei-Server -> Eigenen Datei-Server hosten." "Tip: got a code from a friend? Click 'Paste invite' above. To offer files yourself: Control Center -> 1. Downloader & file server -> Host your own file server.")
    if ($usesCustomCats) { &$logCallback "Eigene Verzeichnisse aktiv: $($categories -join ', ')" }
    [void]$form.ShowDialog()
}
# ------------------------------------------------------------------------------
# OPTION 2: Windows Remotedesktop
# ------------------------------------------------------------------------------

function Invoke-CreateOrUpdateUserDialog {
    $metric1Adapter = Get-NetIPInterface -AddressFamily IPv4 | Where-Object { $_.InterfaceMetric -eq 1 -and $_.ConnectionState -eq "Connected" } | Select-Object -First 1
    
    $ipMetric1 = "Keine IP (Metrik 1) gefunden"
    $adapterName = "N/A"

    if ($metric1Adapter) {
        $adapterObj = Get-NetAdapter -InterfaceIndex $metric1Adapter.InterfaceIndex -ErrorAction SilentlyContinue
        if ($adapterObj) { $adapterName = $adapterObj.Name }
        $ipObj = Get-NetIPAddress -InterfaceIndex $metric1Adapter.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($ipObj) { $ipMetric1 = $ipObj.IPAddress }
    }

    $userForm = (New-PelForm)
    $userForm.Text = "Lokales Benutzerkonto für RDP"
    $userForm.Size = New-Object System.Drawing.Size(430, 320)
    $userForm.StartPosition = "CenterParent"
    $userForm.FormBorderStyle = "Sizable"
    $userForm.MaximizeBox = $true
    $userForm.Add_Shown({ Enable-PelResizableForm $userForm }.GetNewClosure())
    $userForm.MaximizeBox = $false
    $userForm.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $userForm.ForeColor = [System.Drawing.Color]::White

    $lblInfo = New-Object System.Windows.Forms.Label
    $lblInfo.Text = "Erstelle oder ändere ein Passwort für RDP-Zugriffe.`n`nAdapter (Metrik 1): $adapterName`nAktuelle RDP-IP: $ipMetric1"
    $lblInfo.Location = New-Object System.Drawing.Point(20, 15)
    $lblInfo.Size = New-Object System.Drawing.Size(380, 60)
    $lblInfo.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
    $userForm.Controls.Add($lblInfo)

    $lblUser = New-Object System.Windows.Forms.Label
    $lblUser.Text = "Benutzername:"
    $lblUser.Location = New-Object System.Drawing.Point(20, 85)
    $lblUser.Size = New-Object System.Drawing.Size(380, 20)
    $userForm.Controls.Add($lblUser)

    $txtUser = New-Object System.Windows.Forms.TextBox
    $txtUser.Text = "RDPUser"
    $txtUser.Location = New-Object System.Drawing.Point(20, 105)
    $txtUser.Size = New-Object System.Drawing.Size(370, 25)
    $txtUser.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtUser.ForeColor = [System.Drawing.Color]::White
    $userForm.Controls.Add($txtUser)

    $lblPass = New-Object System.Windows.Forms.Label
    $lblPass.Text = "Neues Passwort:"
    $lblPass.Location = New-Object System.Drawing.Point(20, 140)
    $lblPass.Size = New-Object System.Drawing.Size(380, 20)
    $userForm.Controls.Add($lblPass)

    $txtPass = New-Object System.Windows.Forms.TextBox
    $txtPass.UseSystemPasswordChar = $true
    $txtPass.Location = New-Object System.Drawing.Point(20, 160)
    $txtPass.Size = New-Object System.Drawing.Size(370, 25)
    $txtPass.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtPass.ForeColor = [System.Drawing.Color]::White
    $userForm.Controls.Add($txtPass)

    $btnSave = New-Object System.Windows.Forms.Button
    $btnSave.Text = "Konto Speichern / Ändern"
    $btnSave.Location = New-Object System.Drawing.Point(20, 210)
    $btnSave.Size = New-Object System.Drawing.Size(370, 35)
    $btnSave.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnSave.FlatStyle = "Flat"
    $userForm.Controls.Add($btnSave)

    $btnSave.Add_Click({
        $username = $txtUser.Text.Trim()
        $password = $txtPass.Text.Trim()

        if ([string]::IsNullOrWhiteSpace($username) -or [string]::IsNullOrWhiteSpace($password)) {
            [PelI18n]::Show("Bitte wähle einen Benutzernamen und ein Passwort.", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
            return
        }

        try {
            $existingUser = Get-LocalUser -Name $username -ErrorAction SilentlyContinue
            if ($existingUser) {
                Set-LocalUser -Name $username -Password (ConvertTo-SecureString $password -AsPlainText -Force)
                Write-Host "Passwort für lokales Konto '$username' geändert."
                [PelI18n]::Show("Passwort für Benutzer '$username' wurde erfolgreich aktualisiert!`n`nVerbindungs-IP (Metrik 1): $ipMetric1", "Erfolg", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
            } else {
                New-LocalUser -Name $username -Password (ConvertTo-SecureString $password -AsPlainText -Force) -FullName "RDP Remote User" -Description "Erstellt via Project Earth LAN Manager"
                Add-LocalGroupMember -Group "Administratoren" -Member $username -ErrorAction SilentlyContinue
                Add-LocalGroupMember -Group "Remotedesktopbenutzer" -Member $username -ErrorAction SilentlyContinue
                Write-Host "Neuer lokaler Benutzer '$username' erstellt und zu Admins/RDP-Gruppe hinzugefügt."
                [PelI18n]::Show("Lokaler Benutzer '$username' wurde neu erstellt und für Remotedesktop berechtigt!`n`nVerbindungs-IP (Metrik 1): $ipMetric1", "Erfolg", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
            }
            $userForm.Close()
        } catch {
            [PelI18n]::Show("Fehler beim Erstellen/Ändern des Benutzers: $($_.Exception.Message)", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        }
    })

    [void]$userForm.ShowDialog()
}

function Invoke-PelRemoteDesktop {
    $rdpForm = (New-PelForm)
    $rdpForm.Text = "Remotedesktop (P2P / LAN)"
    $rdpForm.Size = New-Object System.Drawing.Size(430, 310)
    $rdpForm.StartPosition = "CenterParent"
    $rdpForm.FormBorderStyle = "Sizable"
    $rdpForm.MaximizeBox = $true
    $rdpForm.Add_Shown({ Enable-PelResizableForm $rdpForm }.GetNewClosure())
    $rdpForm.MaximizeBox = $false
    $rdpForm.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $rdpForm.ForeColor = [System.Drawing.Color]::White

    $lblIP = New-Object System.Windows.Forms.Label
    $lblIP.Text = "IP-Adresse des Ziel-PCs (virtuelle P2P-IP oder LAN-IP):"
    $lblIP.Location = New-Object System.Drawing.Point(20, 15)
    $lblIP.Size = New-Object System.Drawing.Size(370, 20)
    $rdpForm.Controls.Add($lblIP)

    $txtIP = New-Object System.Windows.Forms.TextBox
    $txtIP.Location = New-Object System.Drawing.Point(20, 35)
    $txtIP.Size = New-Object System.Drawing.Size(370, 25)
    $txtIP.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtIP.ForeColor = [System.Drawing.Color]::White
    $rdpForm.Controls.Add($txtIP)

    $btnConnect = New-Object System.Windows.Forms.Button
    $btnConnect.Text = "Verbinden (RDP Starten)"
    $btnConnect.Location = New-Object System.Drawing.Point(20, 75)
    $btnConnect.Size = New-Object System.Drawing.Size(370, 32)
    $btnConnect.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnConnect.FlatStyle = "Flat"
    $rdpForm.Controls.Add($btnConnect)

    $btnEnableRdp = New-Object System.Windows.Forms.Button
    $btnEnableRdp.Text = "RDP Hier Aktivieren"
    $btnEnableRdp.Location = New-Object System.Drawing.Point(20, 115)
    $btnEnableRdp.Size = New-Object System.Drawing.Size(180, 32)
    $btnEnableRdp.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnEnableRdp.FlatStyle = "Flat"
    $rdpForm.Controls.Add($btnEnableRdp)

    $btnDisableRdp = New-Object System.Windows.Forms.Button
    $btnDisableRdp.Text = "RDP Standard Sperren"
    $btnDisableRdp.Location = New-Object System.Drawing.Point(210, 115)
    $btnDisableRdp.Size = New-Object System.Drawing.Size(180, 32)
    $btnDisableRdp.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnDisableRdp.FlatStyle = "Flat"
    $rdpForm.Controls.Add($btnDisableRdp)

    $btnUserConfig = New-Object System.Windows.Forms.Button
    $btnUserConfig.Text = "RDP Konto erstellen / Passwort ändern"
    $btnUserConfig.Location = New-Object System.Drawing.Point(20, 155)
    $btnUserConfig.Size = New-Object System.Drawing.Size(370, 35)
    $btnUserConfig.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnUserConfig.FlatStyle = "Flat"
    $btnUserConfig.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
    $rdpForm.Controls.Add($btnUserConfig)

    $btnConnect.Add_Click({
        $targetIP = $txtIP.Text.Trim()
        if ([string]::IsNullOrWhiteSpace($targetIP)) {
            [PelI18n]::Show("Bitte gib eine gültige IP-Adresse ein.", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
            return
        }

        if (-not ($targetIP -contains ":")) {
            $targetIP = "$targetIP`:9870"
        }

        Write-Host "Starte Remotedesktopverbindung zu $targetIP..."
        Start-Process mstsc.exe -ArgumentList "/v:$targetIP"
        $rdpForm.Close()
    })

    $btnEnableRdp.Add_Click({
        try {
            $targetPort = 9870
            Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Terminal Server' -Name "fDenyTSConnections" -Value 0
            Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name "PortNumber" -Value $targetPort

            Enable-NetFirewallRule -DisplayGroup "Remote Desktop" -ErrorAction SilentlyContinue
            New-NetFirewallRule -DisplayName "RDP Port 9870 (Custom)" -Direction Inbound -Action Allow -Protocol TCP -LocalPort $targetPort -ErrorAction SilentlyContinue | Out-Null
            Restart-Service -Name "TermService" -Force -ErrorAction SilentlyContinue

            $desktopPath = [System.IO.Path]::Combine($env:USERPROFILE, "Desktop")
            $portTxtFile = Join-Path $desktopPath "RDP_Port.txt"
            
            $portInfoText = @"
==================================
RDP PORT INFORMATION
==================================
Der aktuell eingestellte RDP-Port lautet: $targetPort

Der Port wurde auf $targetPort geändert. 
Beim Verbinden im mstsc-Fenster muss daher 'IP-Adresse:$targetPort' angegeben werden.
==================================
"@
            Set-Content -Path $portTxtFile -Value $portInfoText -Encoding UTF8 -Force

            Write-Host "Remotedesktop wurde aktiviert! Aktueller Port auf $targetPort geändert."
            [PelI18n]::Show("Remotedesktop wurde erfolgreich aktiviert!`n`nDer RDP-Port wurde auf $targetPort geändert.`nEine Datei 'RDP_Port.txt' wurde auf dem Desktop erstellt.", "Erfolg", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
        } catch {
            [PelI18n]::Show("Fehler beim Aktivieren von RDP: $($_.Exception.Message)", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        }
    })

    $btnDisableRdp.Add_Click({
        try {
            Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Terminal Server' -Name "fDenyTSConnections" -Value 1
            Disable-NetFirewallRule -DisplayGroup "Remote Desktop" -ErrorAction SilentlyContinue
            Remove-NetFirewallRule -DisplayName "RDP Port 9870 (Custom)" -ErrorAction SilentlyContinue
            Restart-Service -Name "TermService" -Force -ErrorAction SilentlyContinue

            Write-Host "Remotedesktop wurde deaktiviert."
            [PelI18n]::Show("Remotedesktop wurde erfolgreich deaktiviert!", "Erfolg", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
        } catch {
            [PelI18n]::Show("Fehler beim Deaktivieren von RDP: $($_.Exception.Message)", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
        }
    })

    $btnUserConfig.Add_Click({
        Invoke-CreateOrUpdateUserDialog
    })

    [void]$rdpForm.ShowDialog()
}

# ------------------------------------------------------------------------------
# OPTION 3: Spielebibliothek (Spiele finden, verwalten, starten)
# ------------------------------------------------------------------------------
# Zeigt alle Spiele aus C:\Project-Earth-Lan\games.json. "Spiele scannen" ist der
# bisherige LAN Game Finder (Invoke-LanGameFinder), "Manuell suchen" die bisherige
# Option 4 (Invoke-ManualGameSearch) - beide schreiben jetzt in die Bibliothek.
# Beitreten (Server-Browser, Kommunikationszentrale, Control Center) sucht zuerst hier.
function Invoke-PelGameLibrary {
    # Net = Spiele der anderen Manager (Abgleich, games_netz.json), SyncUntil = Zeitpunkt,
    # bis zu dem nach "Abgleichen" auf Antworten gewartet wird, Editing = Umbenennen läuft
    $libState = @{ Lib = $null; Loading = $false; Stamp = [long]0; Net = @{}; NetStamp = [long]-1; SyncUntil = [long]0; Editing = $false }
    $cOrange = [System.Drawing.Color]::FromArgb(255, 170, 60)
    $cGreen = [System.Drawing.Color]::FromArgb(0, 135, 70)
    $cRed = [System.Drawing.Color]::FromArgb(160, 50, 40)
    $cBlue = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $cNormal = [System.Drawing.Color]::FromArgb(45, 45, 45)
    $fontMain = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
    $fontBold = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)

    $libForm = (New-PelForm)
    $libForm.Text = "Spielebibliothek"
    $libForm.Size = New-Object System.Drawing.Size(940, 640)
    $libForm.MinimumSize = New-Object System.Drawing.Size(900, 520)
    $libForm.StartPosition = "CenterScreen"
    $libForm.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $libForm.ForeColor = [System.Drawing.Color]::White
    $libForm.Font = $fontMain

    $mkBtn = {
        param([string]$Text, [int]$X, [int]$Y, [int]$W, $Back, [string]$Anchor)
        $b = New-Object System.Windows.Forms.Button
        $b.Text = $Text
        $b.Location = New-Object System.Drawing.Point($X, $Y)
        $b.Size = New-Object System.Drawing.Size($W, 40)
        $b.FlatStyle = 'Flat'
        $b.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $b.BackColor = $Back
        $b.ForeColor = [System.Drawing.Color]::White
        $b.Font = $fontBold
        $b.Anchor = $Anchor
        $libForm.Controls.Add($b)
        return $b
    }

    $lblFilter = New-Object System.Windows.Forms.Label
    $lblFilter.Text = "Suchen:"
    $lblFilter.Location = New-Object System.Drawing.Point(16, 27)
    $lblFilter.Size = New-Object System.Drawing.Size(62, 22)
    $libForm.Controls.Add($lblFilter)

    $txtFilter = New-Object System.Windows.Forms.TextBox
    $txtFilter.Location = New-Object System.Drawing.Point(80, 24)
    $txtFilter.Size = New-Object System.Drawing.Size(250, 26)
    $txtFilter.BackColor = [System.Drawing.Color]::FromArgb(15, 15, 15)
    $txtFilter.ForeColor = [System.Drawing.Color]::White
    $txtFilter.BorderStyle = 'FixedSingle'
    $libForm.Controls.Add($txtFilter)

    $btnScan = & $mkBtn "Spiele scannen" 346 16 170 $cBlue 'Top,Left'
    $btnManual = & $mkBtn "Manuell suchen" 524 16 170 $cNormal 'Top,Left'
    $btnAddExe = & $mkBtn ".exe hinzufügen" 702 16 170 $cNormal 'Top,Left'

    $lblInfo = New-Object System.Windows.Forms.Label
    $lblInfo.Text = "Alle Spiele dieses PCs an einer Stelle. Beim Beitreten (Server-Browser, Kommunikationszentrale, Control Center) sucht der Manager zuerst hier. Orange = haben andere, fehlt dir: startest du es, wird es automatisch aufgenommen. Doppelklick = Spiel testen, F2 = umbenennen."
    $lblInfo.Location = New-Object System.Drawing.Point(16, 64)
    $lblInfo.Size = New-Object System.Drawing.Size(892, 36)
    $lblInfo.ForeColor = [System.Drawing.Color]::FromArgb(170, 178, 190)
    $lblInfo.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Italic)
    $lblInfo.Anchor = 'Top,Left,Right'
    $libForm.Controls.Add($lblInfo)

    $lvGames = New-Object System.Windows.Forms.ListView
    $lvGames.Location = New-Object System.Drawing.Point(16, 104)
    $lvGames.Size = New-Object System.Drawing.Size(892, 364)
    $lvGames.View = 'Details'
    $lvGames.FullRowSelect = $true
    $lvGames.MultiSelect = $true
    $lvGames.HideSelection = $false
    $lvGames.LabelEdit = $true
    $lvGames.ShowItemToolTips = $true
    $lvGames.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
    $lvGames.ForeColor = [System.Drawing.Color]::White
    $lvGames.BorderStyle = 'FixedSingle'
    $lvGames.Anchor = 'Top,Bottom,Left,Right'
    [void]$lvGames.Columns.Add("Spiel", 270)
    [void]$lvGames.Columns.Add("Direktbeitritt", 100)
    [void]$lvGames.Columns.Add("Quelle", 90)
    [void]$lvGames.Columns.Add("Im Netz", 110)
    [void]$lvGames.Columns.Add("Pfad", 300)
    $libForm.Controls.Add($lvGames)

    $btnTest = & $mkBtn "Spiel testen" 16 480 150 $cGreen 'Bottom,Left'
    $btnChangeExe = & $mkBtn ".exe ändern" 174 480 130 $cNormal 'Bottom,Left'
    $btnOpenDir = & $mkBtn "Ordner öffnen" 312 480 130 $cNormal 'Bottom,Left'
    $btnRename = & $mkBtn "Umbenennen" 450 480 110 $cNormal 'Bottom,Left'
    $btnSync = & $mkBtn "Abgleichen" 604 480 146 $cBlue 'Bottom,Right'
    $btnRemove = & $mkBtn "Entfernen" 758 480 150 $cRed 'Bottom,Right'

    $chkLinks = New-Object System.Windows.Forms.CheckBox
    $chkLinks.Text = "Zusätzlich Verknüpfungen auf dem Desktop anlegen (Ordner 'Lan Games')"
    $chkLinks.Location = New-Object System.Drawing.Point(16, 530)
    $chkLinks.Size = New-Object System.Drawing.Size(520, 24)
    $chkLinks.Anchor = 'Bottom,Left'
    $libForm.Controls.Add($chkLinks)

    $chkNet = New-Object System.Windows.Forms.CheckBox
    $chkNet.Text = "Spiele der anderen anzeigen (orange)"
    $chkNet.Location = New-Object System.Drawing.Point(548, 530)
    $chkNet.Size = New-Object System.Drawing.Size(330, 24)
    $chkNet.Anchor = 'Bottom,Left'
    $chkNet.Checked = $true
    $libForm.Controls.Add($chkNet)

    $lblStatus = New-Object System.Windows.Forms.Label
    $lblStatus.Location = New-Object System.Drawing.Point(16, 562)
    $lblStatus.Size = New-Object System.Drawing.Size(892, 22)
    $lblStatus.ForeColor = [System.Drawing.Color]::LightGray
    $lblStatus.Anchor = 'Bottom,Left,Right'
    $libForm.Controls.Add($lblStatus)

    $tipLib = New-Object System.Windows.Forms.ToolTip
    [PelI18n]::Tip($tipLib, $btnScan, 'Durchsucht Steam, Epic, GOG, Ubisoft, EA und die Spieleordner nach LAN-fähigen Spielen (bisher Option 3).')
    [PelI18n]::Tip($tipLib, $btnManual, 'Ein bestimmtes Spiel auf allen Laufwerken suchen, auch in versteckten Ordnern (bisher Option 4).')
    [PelI18n]::Tip($tipLib, $btnAddExe, 'Eine Spiel-EXE selbst auswählen und eintragen.')
    [PelI18n]::Tip($tipLib, $btnRemove, 'Entfernt das Spiel nur aus der Liste - auf der Festplatte wird nichts gelöscht. Ein neuer Scan nimmt es nicht wieder auf.')
    [PelI18n]::Tip($tipLib, $chkLinks, 'Wie früher: pro Spiel eine Verknüpfung im Desktop-Ordner "Lan Games". Für den Manager selbst nicht nötig.')
    [PelI18n]::Tip($tipLib, $btnSync, 'Gleicht die Spielebibliothek sofort mit allen verbundenen Managern ab: wer hat welches Spiel, welche fehlen dir. Verschickt werden nur Spielnamen, EXE- und Ordnernamen - keine Pfade. Läuft über das Control Center.')
    [PelI18n]::Tip($tipLib, $chkNet, 'Zeigt auch Spiele, die andere Manager haben und dir fehlen. Startest du so ein Spiel (egal, wo es liegt), nimmt das Control Center es automatisch in deine Bibliothek auf.')

    # --- Liste füllen -----------------------------------------------------------
    function Get-PelLibStamp {
        try { return [System.IO.File]::GetLastWriteTimeUtc($script:PelGameLibPath).Ticks } catch { return 0 }
    }

    function Get-PelNetStamp {
        try { if ([System.IO.File]::Exists($script:PelNetLibPath)) { return [System.IO.File]::GetLastWriteTimeUtc($script:PelNetLibPath).Ticks } } catch { }
        return 0
    }

    # Anzeige "Im Netz": wie viele andere Manager das Spiel haben
    function Get-PelNetOwnersText($Owners) {
        $n = @($Owners).Count
        if ($n -eq 0) { return '' }
        if ($n -eq 1) { return [PelI18n]::Tr("1 anderer") }
        return ([PelI18n]::Tr("{0} andere") -f $n)
    }

    function Update-PelLibList {
        param([switch]$Reload)
        if ($Reload -or -not $libState.Lib) {
            $libState.Lib = Get-PelGameLibrary
            $libState.Stamp = Get-PelLibStamp
        }
        $ns = Get-PelNetStamp
        if ($Reload -or $ns -ne $libState.NetStamp) {
            $libState.Net = Get-PelNetLibraryView
            $libState.NetStamp = $ns
        }
        $keep = @{}
        foreach ($si in @($lvGames.SelectedItems)) {
            if ($si.Tag.IsNet) { $keep['net:' + (ConvertTo-PelNormName ([string]$si.Tag.Name))] = $true }
            else { $keep[([string]$si.Tag.Exe).ToLowerInvariant()] = $true }
        }
        $flt = $txtFilter.Text.Trim()
        $visible = @($libState.Lib.Games | Where-Object { -not $_.Hidden } | Sort-Object { [string]$_.Name })
        $direct = 0
        $missing = 0
        # Eigene Spiele den Einträgen der anderen zuordnen: gleicher Name oder (bei
        # eindeutigem EXE-Namen) gleiche EXE - so zählt auch ein umbenanntes Spiel.
        $ownNorm = @{}
        $ownLeaf = @{}
        $leafOwners = @{}
        foreach ($ne in @($libState.Net.Values)) {
            if ($ne.Exe -and -not (Test-PelGenericExe $ne.Exe)) { $leafOwners[([string]$ne.Exe).ToLowerInvariant()] = $ne.Owners }
        }
        $lvGames.BeginUpdate()
        $lvGames.Items.Clear()
        foreach ($g in $visible) {
            $exists = [System.IO.File]::Exists([string]$g.Exe)
            $isDirect = Test-PelLibraryDirectJoin $g
            if ($isDirect) { $direct++ }
            if (-not $exists) { $missing++ }
            $norm = ConvertTo-PelNormName ([string]$g.Name)
            $leaf = ''
            try { $leaf = ([System.IO.Path]::GetFileName([string]$g.Exe)).ToLowerInvariant() } catch { }
            if ($exists) { $ownNorm[$norm] = $true; if ($leaf) { $ownLeaf[$leaf] = $true } }
            $owners = @()
            if ($norm -and $libState.Net.ContainsKey($norm)) { $owners = @($libState.Net[$norm].Owners) }
            elseif ($leaf -and $leafOwners.ContainsKey($leaf)) { $owners = @($leafOwners[$leaf]) }
            if ($flt -and ([string]$g.Name).IndexOf($flt, [System.StringComparison]::OrdinalIgnoreCase) -lt 0 -and ([string]$g.Exe).IndexOf($flt, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
            $li = New-Object System.Windows.Forms.ListViewItem([string]$g.Name)
            [void][PelI18n]::AddSub($li, $(if ($isDirect) { "Ja" } else { "Nein" }))
            [void][PelI18n]::AddSub($li, [string]$g.Source)
            [void]$li.SubItems.Add((Get-PelNetOwnersText $owners))
            [void][PelI18n]::AddSub($li, $(if ($exists) { [string]$g.Exe } else { "(fehlt) " + [string]$g.Exe }))
            if (-not $exists) { $li.ForeColor = [System.Drawing.Color]::FromArgb(255, 110, 100) }
            if ($owners.Count -gt 0) { $li.ToolTipText = ([PelI18n]::Tr("Haben auch: {0}") -f ($owners -join ', ')) }
            $li.Tag = $g
            if ($keep.ContainsKey(([string]$g.Exe).ToLowerInvariant())) { $li.Selected = $true }
            [void]$lvGames.Items.Add($li)
        }
        # Spiele der anderen, die hier fehlen (orange). Ein Platzhalter, bis das Spiel auf
        # diesem PC gestartet oder über ".exe ändern" von Hand eingetragen wird.
        $netMissing = 0
        foreach ($nk in @($libState.Net.Keys | Sort-Object { [string]$libState.Net[$_].Name })) {
            $ne = $libState.Net[$nk]
            if ($ownNorm.ContainsKey($nk)) { continue }
            if ($ne.Exe -and -not (Test-PelGenericExe $ne.Exe) -and $ownLeaf.ContainsKey(([string]$ne.Exe).ToLowerInvariant())) { continue }
            $netMissing++
            if (-not $chkNet.Checked) { continue }
            if ($flt -and ([string]$ne.Name).IndexOf($flt, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
            $ruleKey = ''
            if ($ne.Exe) {
                $fake = if ($ne.Folder) { "X:\$($ne.Folder)\$($ne.Exe)" } else { "X:\$($ne.Exe)" }
                $ruleKey = Get-PelLibraryRuleKey ([string]$ne.Name) $fake
            } else { $ruleKey = Get-PelLibraryRuleKey ([string]$ne.Name) '' }
            $tag = [pscustomobject]@{ IsNet = $true; Name = [string]$ne.Name; Exe = ''; NetExe = [string]$ne.Exe; RuleKey = $ruleKey; Owners = @($ne.Owners) }
            $li = New-Object System.Windows.Forms.ListViewItem([string]$ne.Name)
            [void][PelI18n]::AddSub($li, $(if (Test-PelLibraryDirectJoin $tag) { "Ja" } else { "Nein" }))
            [void][PelI18n]::AddSub($li, "Im Netz")
            [void]$li.SubItems.Add((Get-PelNetOwnersText $ne.Owners))
            $pathTxt = [PelI18n]::Tr("Fehlt dir - haben: {0}") -f (@($ne.Owners) -join ', ')
            if ($ne.Exe) { $pathTxt += "  ($($ne.Exe))" }
            [void]$li.SubItems.Add($pathTxt)
            $li.ForeColor = $cOrange
            $li.ToolTipText = [PelI18n]::Tr("Startest du dieses Spiel, nimmt der Manager es automatisch auf. Oder mit '.exe ändern' den Ort selbst festlegen.")
            $li.Tag = $tag
            if ($keep.ContainsKey("net:$nk")) { $li.Selected = $true }
            [void]$lvGames.Items.Add($li)
        }
        $lvGames.EndUpdate()
        $libState.Loading = $true
        $chkLinks.Checked = [bool]$libState.Lib.MakeShortcuts
        $libState.Loading = $false
        $st = [PelI18n]::Tr("{0} Spiele in der Bibliothek, davon {1} mit Direktbeitritt.") -f $visible.Count, $direct
        if ($missing -gt 0) { $st += ' ' + ([PelI18n]::Tr("{0} Spiel(e) nicht mehr gefunden (rot).") -f $missing) }
        if ($netMissing -gt 0) { $st += ' ' + ([PelI18n]::Tr("{0} Spiel(e) haben andere, die dir fehlen.") -f $netMissing) }
        $lblStatus.Text = $st
    }

    function Save-PelLibFromWindow {
        if (-not (Save-PelGameLibrary $libState.Lib)) {
            Show-PelMsg "Die Spielebibliothek konnte nicht gespeichert werden. Details im Fehlerlog (Control Center -> Fehlerlog exportieren)." 'Spielebibliothek' ([System.Windows.Forms.MessageBoxIcon]::Error) $libForm
            return $false
        }
        $libState.Stamp = Get-PelLibStamp
        return $true
    }

    function Get-PelLibSelection {
        $all = @($lvGames.SelectedItems | ForEach-Object { $_.Tag })
        $sel = @($all | Where-Object { -not $_.IsNet })
        if ($all.Count -eq 0) {
            Show-PelMsg "Bitte zuerst ein Spiel in der Liste auswählen." 'Spielebibliothek' ([System.Windows.Forms.MessageBoxIcon]::Information) $libForm
        } elseif ($sel.Count -eq 0) {
            Show-PelMsg "Dieses Spiel haben andere Manager - dir fehlt es noch.`n`nLade es dir und starte es einfach (egal, in welchem Ordner es liegt): das Control Center nimmt es dann automatisch in deine Bibliothek auf und meldet es den anderen.`n`nLiegt es schon auf dem PC? Dann mit '.exe ändern' den Ort selbst festlegen." 'Spielebibliothek' ([System.Windows.Forms.MessageBoxIcon]::Information) $libForm
        }
        return $sel
    }

    # Namensvorschlag für eine selbst gewählte EXE: Produktname aus der Datei, sonst der
    # Ordnername (die EXE heißt oft nur "game.exe" oder "launcher.exe").
    function Get-PelExeDisplayName([string]$Path) {
        $n = ''
        try {
            $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($Path)
            foreach ($c in @($vi.ProductName, $vi.FileDescription)) {
                $t = ([string]$c).Trim()
                if ($t.Length -ge 3 -and $t -notmatch '(?i)^(game|launcher|setup|application|bootstrapper|unity|unreal)') { $n = $t; break }
            }
        } catch { }
        if (-not $n) { $n = [System.IO.Path]::GetFileName([System.IO.Path]::GetDirectoryName($Path)) }
        if (-not $n) { $n = [System.IO.Path]::GetFileNameWithoutExtension($Path) }
        return (Limit-PelText $n 80)
    }

    function Select-PelExeFile([string]$Title, [string]$StartDir = '') {
        $ofd = New-Object System.Windows.Forms.OpenFileDialog
        $ofd.Title = $Title
        $ofd.Filter = "Programme (*.exe)|*.exe"
        if ($StartDir -and [System.IO.Directory]::Exists($StartDir)) { $ofd.InitialDirectory = $StartDir }
        if ($ofd.ShowDialog($libForm) -eq [System.Windows.Forms.DialogResult]::OK) { return $ofd.FileName }
        return $null
    }

    # --- Aktionen ---------------------------------------------------------------
    $actTest = {
        $sel = @(Get-PelLibSelection)
        if ($sel.Count -eq 0) { return }
        if (Start-PelLibraryGame -Entry $sel[0] -Owner $libForm) { $lblStatus.Text = [PelI18n]::Tr("Gestartet: {0}") -f [string]$sel[0].Name }
    }
    $actChangeExe = {
        # Platzhalter (Spiel der anderen): Ort selbst festlegen = in die Bibliothek eintragen
        if ($lvGames.SelectedItems.Count -eq 1 -and $lvGames.SelectedItems[0].Tag.IsNet) {
            $ng = $lvGames.SelectedItems[0].Tag
            $newNet = Select-PelExeFile ([PelI18n]::Tr("Spiel-EXE für '{0}' auswählen") -f [string]$ng.Name)
            if (-not $newNet) { return }
            [void](Set-PelLibraryGame -Library $libState.Lib -Name ([string]$ng.Name) -Exe $newNet -Source 'Manuell' -Pinned)
            if (Save-PelLibFromWindow) { Update-PelLibList }
            return
        }
        $sel = @(Get-PelLibSelection)
        if ($sel.Count -eq 0) { return }
        $g = $sel[0]
        $new = Select-PelExeFile ([PelI18n]::Tr("Neue Spiel-EXE für '{0}' auswählen") -f [string]$g.Name) ([System.IO.Path]::GetDirectoryName([string]$g.Exe))
        if (-not $new) { return }
        $g.Exe = $new
        $g.Pinned = $true
        $g.Hidden = $false
        $g.Source = 'Manuell'
        $g.RuleKey = Get-PelLibraryRuleKey ([string]$g.Name) $new
        if (Save-PelLibFromWindow) { Update-PelLibList }
    }
    $actOpenDir = {
        $sel = @(Get-PelLibSelection)
        if ($sel.Count -eq 0) { return }
        $p = [string]$sel[0].Exe
        try {
            if ([System.IO.File]::Exists($p)) { Start-Process explorer.exe -ArgumentList "/select,`"$p`"" }
            else {
                $d = [System.IO.Path]::GetDirectoryName($p)
                if ([System.IO.Directory]::Exists($d)) { Start-Process explorer.exe -ArgumentList "`"$d`"" }
                else { Show-PelMsg "Der Ordner existiert nicht mehr:`n$d" 'Spielebibliothek' ([System.Windows.Forms.MessageBoxIcon]::Warning) $libForm }
            }
        } catch { }
    }
    $actRename = {
        if ($lvGames.SelectedItems.Count -eq 0 -or $lvGames.SelectedItems[0].Tag.IsNet) { [void](Get-PelLibSelection); return }
        $lvGames.SelectedItems[0].BeginEdit()
    }
    $actRemove = {
        $sel = @(Get-PelLibSelection)
        if ($sel.Count -eq 0) { return }
        $names = ($sel | Select-Object -First 8 | ForEach-Object { '- ' + [string]$_.Name }) -join "`n"
        if ($sel.Count -gt 8) { $names += "`n..." }
        $q = [PelI18n]::Show($libForm, ([PelI18n]::Tr("{0} Spiel(e) aus der Bibliothek entfernen?") -f $sel.Count) + "`n`n$names`n`n" + [PelI18n]::Tr("Auf der Festplatte wird nichts gelöscht. Ein neuer Scan nimmt die Spiele nicht wieder auf - über '.exe hinzufügen' oder 'Manuell suchen' lassen sie sich jederzeit zurückholen."), 'Spielebibliothek', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
        if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        foreach ($g in $sel) { $g.Hidden = $true }
        if (Save-PelLibFromWindow) { Update-PelLibList }
    }

    $btnTest.Add_Click($actTest)
    $btnChangeExe.Add_Click($actChangeExe)
    $btnOpenDir.Add_Click($actOpenDir)
    $btnRename.Add_Click($actRename)
    $btnRemove.Add_Click($actRemove)
    $lvGames.Add_DoubleClick($actTest)

    $ctx = (New-PelContextMenu)
    foreach ($ce in @(
            @{ Text = 'Spiel testen'; Act = $actTest },
            @{ Text = '.exe ändern'; Act = $actChangeExe },
            @{ Text = 'Ordner öffnen'; Act = $actOpenDir },
            @{ Text = 'Umbenennen'; Act = $actRename },
            @{ Text = 'Entfernen'; Act = $actRemove })) {
        $mi = New-Object System.Windows.Forms.ToolStripMenuItem($ce.Text)
        $mi.Add_Click($ce.Act)
        [void]$ctx.Items.Add($mi)
    }
    $lvGames.ContextMenuStrip = $ctx

    $lvGames.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Delete) { $_.Handled = $true; & $actRemove }
        elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::F2) { $_.Handled = $true; & $actRename }
        elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $_.Handled = $true; & $actTest }
    })

    # Umbenennen direkt in der Liste. Der neue Name gilt als bestätigt (ein Scan
    # überschreibt ihn nicht) und bestimmt die passende Join-Regel neu.
    $lvGames.Add_BeforeLabelEdit({
        if ($lvGames.Items[$_.Item].Tag.IsNet) { $_.CancelEdit = $true; return }
        $libState.Editing = $true
    })
    $lvGames.Add_AfterLabelEdit({
        $ev = $_
        $libState.Editing = $false
        if ($null -eq $ev.Label) { return }
        $newName = Limit-PelText ([string]$ev.Label) 80
        if (-not $newName) { $ev.CancelEdit = $true; return }
        $g = $lvGames.Items[$ev.Item].Tag
        $g.Name = $newName
        $g.Pinned = $true
        $g.RuleKey = Get-PelLibraryRuleKey $newName ([string]$g.Exe)
        if (-not (Save-PelLibFromWindow)) { $ev.CancelEdit = $true }
    })

    $txtFilter.Add_TextChanged({ Update-PelLibList })
    $chkNet.Add_CheckedChanged({ Update-PelLibList })

    # Abgleichen: läuft über das Control Center (dort hört der Live-Status auf Port 9928).
    # Die Antworten landen in games_netz.json - der Timer unten zeigt sie an.
    $btnSync.Add_Click({
        if (-not (Test-PelControlCenterRunning)) {
            Show-PelMsg "Der Abgleich läuft über das Control Center (Live-Status). Bitte das Control Center öffnen - danach gleicht es automatisch ab, auch ohne diesen Button." 'Spielebibliothek' ([System.Windows.Forms.MessageBoxIcon]::Information) $libForm
            return
        }
        if (-not (Request-PelLibrarySync)) {
            Show-PelMsg "Der Abgleich konnte nicht angestoßen werden (C:\Project-Earth-Lan nicht beschreibbar?)." 'Spielebibliothek' ([System.Windows.Forms.MessageBoxIcon]::Warning) $libForm
            return
        }
        $libState.SyncUntil = (Get-PelNowMs) + 6000
        $btnSync.Enabled = $false
        $lblStatus.Text = [PelI18n]::Tr("Abgleich läuft - die anderen Manager schicken ihre Listen ...")
    })

    # Alle 1,5 s: neue Listen der anderen oder eine Änderung an games.json (z. B. ein Spiel,
    # das das Control Center gerade automatisch aufgenommen hat) sofort anzeigen.
    $libTimer = New-Object System.Windows.Forms.Timer
    $libTimer.Interval = 1500
    $libTimer.Add_Tick({
        try {
            if ($libState.Editing) { return }
            $syncDone = ($libState.SyncUntil -gt 0 -and (Get-PelNowMs) -ge $libState.SyncUntil)
            if ((Get-PelLibStamp) -ne $libState.Stamp) { Update-PelLibList -Reload }
            elseif ((Get-PelNetStamp) -ne $libState.NetStamp -or $syncDone) { Update-PelLibList }
            if ($syncDone) {
                $libState.SyncUntil = 0
                $btnSync.Enabled = $true
                $since = (Get-PelNowMs) - 90000
                $reached = @((Read-PelNetLibrary).Values | Where-Object { $_.Seen -ge $since }).Count
                if ($reached -eq 0) {
                    $lblStatus.Text = [PelI18n]::Tr("Kein anderer Manager hat geantwortet. Sind die anderen online (Live-Status im Control Center, gleiche P2P-Lobby)?")
                } else {
                    $lblStatus.Text = ([PelI18n]::Tr("Abgleich fertig: {0} Manager erreicht.") -f $reached) + ' ' + $lblStatus.Text
                }
            }
        } catch { }
    })

    $btnScan.Add_Click({
        Invoke-LanGameFinder
        Update-PelLibList -Reload
    })
    $btnManual.Add_Click({
        Invoke-ManualGameSearch
        Update-PelLibList -Reload
    })
    $btnAddExe.Add_Click({
        $p = Select-PelExeFile ([PelI18n]::Tr("Spiel-EXE auswählen"))
        if (-not $p) { return }
        $g = Set-PelLibraryGame -Library $libState.Lib -Name (Get-PelExeDisplayName $p) -Exe $p -Source 'Manuell' -Pinned
        if ((Save-PelLibFromWindow) -and $g) {
            $txtFilter.Text = ''
            Update-PelLibList
            foreach ($it in $lvGames.Items) {
                if ($it.Tag -eq $g) { $it.Selected = $true; $it.EnsureVisible(); $it.BeginEdit(); break }
            }
        }
    })

    $chkLinks.Add_CheckedChanged({
        if ($libState.Loading) { return }
        $libState.Lib.MakeShortcuts = [bool]$chkLinks.Checked
        [void](Save-PelLibFromWindow)
    })

    # Beim Zurückkehren ins Fenster neu laden, aber nur wenn games.json inzwischen von
    # einem anderen Fenster geändert wurde (z. B. Beitreten im Server-Browser). Eigene
    # Speichervorgänge merken sich den Zeitstempel - so bricht z. B. das Umbenennen nach
    # dem Datei-Dialog nicht durch ein unnötiges Neuladen ab.
    $libForm.Add_Activated({
        if ((Get-PelLibStamp) -ne $libState.Stamp) { Update-PelLibList -Reload }
    })
    $libForm.Add_Shown({
        Update-PelLibList -Reload
        if (@($libState.Lib.Games | Where-Object { -not $_.Hidden }).Count -eq 0) {
            $lblStatus.Text = [PelI18n]::Tr("Die Bibliothek ist noch leer - 'Spiele scannen' findet die meisten Spiele automatisch.")
        }
        $libTimer.Start()
    })
    $libForm.Add_FormClosing({ $libTimer.Stop() })

    [void]$libForm.ShowDialog()
    $libTimer.Dispose()
    $tipLib.Dispose()
}

# ------------------------------------------------------------------------------
# Spiele scannen (bisher OPTION 3 "LAN Game Verknüpfung in Ordner auf Desktop") -
# wird jetzt aus der Spielebibliothek aufgerufen und schreibt dort hinein.
# ------------------------------------------------------------------------------
function Invoke-LanGameFinder {
    # Kennung in der Verknüpfungs-Beschreibung: nur so markierte Verknüpfungen werden bei
    # einem neuen Scan ersetzt - selbst angelegte (z. B. über Option 4) bleiben erhalten.
    $autoDesc = 'Project Earth LAN - automatisch erkannt (Option 3)'

    function New-GameShortcut {
        param ([string]$SourcePath, [string]$DestinationFolder, [string]$ShortcutName, [string]$Arguments = '', [string]$GameExe = '', [string]$Description = '')
        $cleanName = ($ShortcutName -replace '[\\/:*?"<>|]', '').Trim()
        if (-not $cleanName) { $cleanName = 'Spiel' }
        $shortcutPath = Join-Path -Path $DestinationFolder -ChildPath "$cleanName.lnk"
        $wshShell = New-Object -ComObject WScript.Shell
        $shortcut = $wshShell.CreateShortcut($shortcutPath)
        $shortcut.TargetPath = $SourcePath
        if ($Arguments) { $shortcut.Arguments = $Arguments }
        if ($GameExe) {
            $shortcut.WorkingDirectory = [System.IO.Path]::GetDirectoryName($GameExe)
            $shortcut.IconLocation = "$GameExe,0"
        } else {
            $shortcut.WorkingDirectory = [System.IO.Path]::GetDirectoryName($SourcePath)
        }
        if ($Description) { $shortcut.Description = $Description }
        $shortcut.Save()
    }

    $form = (New-PelForm)
    $form.Text = "Spiele scannen (Spielebibliothek)"
    $form.Size = New-Object System.Drawing.Size(760, 560)
    $form.StartPosition = "CenterParent"
    $form.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $form.ForeColor = [System.Drawing.Color]::White

    $fontMain = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)

    $btnDriveSelect = New-Object System.Windows.Forms.Button
    $btnDriveSelect.Location = New-Object System.Drawing.Point(20, 20)
    $btnDriveSelect.Size = New-Object System.Drawing.Size(165, 35)
    $btnDriveSelect.Text = "Festplatten Auswählen"
    $btnDriveSelect.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnDriveSelect.ForeColor = [System.Drawing.Color]::White
    $btnDriveSelect.FlatStyle = "Flat"
    $btnDriveSelect.Font = $fontMain

    $btnStartScan = New-Object System.Windows.Forms.Button
    $btnStartScan.Location = New-Object System.Drawing.Point(193, 20)
    $btnStartScan.Size = New-Object System.Drawing.Size(190, 35)
    $btnStartScan.Text = "Suche Starten"
    $btnStartScan.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnStartScan.ForeColor = [System.Drawing.Color]::White
    $btnStartScan.FlatStyle = "Flat"
    $btnStartScan.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)

    $btnOpenFolder = New-Object System.Windows.Forms.Button
    $btnOpenFolder.Location = New-Object System.Drawing.Point(391, 20)
    $btnOpenFolder.Size = New-Object System.Drawing.Size(165, 35)
    $btnOpenFolder.Text = "'Lan Games' öffnen"
    $btnOpenFolder.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnOpenFolder.ForeColor = [System.Drawing.Color]::White
    $btnOpenFolder.FlatStyle = "Flat"
    $btnOpenFolder.Font = $fontMain

    $btnLists = New-Object System.Windows.Forms.Button
    $btnLists.Location = New-Object System.Drawing.Point(564, 20)
    $btnLists.Size = New-Object System.Drawing.Size(156, 35)
    $btnLists.Text = "Eigene Listen ▾"
    $btnLists.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnLists.ForeColor = [System.Drawing.Color]::White
    $btnLists.FlatStyle = "Flat"
    $btnLists.Font = $fontMain

    $txtLog = New-Object System.Windows.Forms.TextBox
    $txtLog.Location = New-Object System.Drawing.Point(20, 75)
    $txtLog.Size = New-Object System.Drawing.Size(700, 420)
    $txtLog.Multiline = $true
    $txtLog.ScrollBars = "Vertical"
    $txtLog.ReadOnly = $true
    $txtLog.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
    $txtLog.ForeColor = [System.Drawing.Color]::White
    $txtLog.Font = New-Object System.Drawing.Font("Consolas", 9)

    $form.Controls.Add($btnDriveSelect)
    $form.Controls.Add($btnStartScan)
    $form.Controls.Add($btnOpenFolder)
    $form.Controls.Add($btnLists)
    $form.Controls.Add($txtLog)

    $global:SelectedDrives = @(Get-PSDrive -PSProvider FileSystem | Select-Object -ExpandProperty Root)

    $btnDriveSelect.Add_Click({
        $driveForm = (New-PelForm)
        $driveForm.Text = "Laufwerke Überprüfen"
        $driveForm.Size = New-Object System.Drawing.Size(300, 320)
        $driveForm.StartPosition = "CenterParent"
        $driveForm.BackColor = [System.Drawing.Color]::FromArgb(35, 35, 35)
        $driveForm.ForeColor = [System.Drawing.Color]::White

        $checkedListBox = New-Object System.Windows.Forms.CheckedListBox
        $checkedListBox.Location = New-Object System.Drawing.Point(20, 20)
        $checkedListBox.Size = New-Object System.Drawing.Size(240, 200)
        $checkedListBox.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
        $checkedListBox.ForeColor = [System.Drawing.Color]::White

        $allDrives = Get-PSDrive -PSProvider FileSystem | Select-Object -ExpandProperty Root
        foreach ($d in $allDrives) {
            $isChecked = $global:SelectedDrives -contains $d
            [void]$checkedListBox.Items.Add($d, $isChecked)
        }

        $btnConfirm = New-Object System.Windows.Forms.Button
        $btnConfirm.Location = New-Object System.Drawing.Point(20, 230)
        $btnConfirm.Size = New-Object System.Drawing.Size(240, 30)
        $btnConfirm.Text = "Übernehmen"
        $btnConfirm.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
        $btnConfirm.ForeColor = [System.Drawing.Color]::White
        $btnConfirm.FlatStyle = "Flat"
        $btnConfirm.Add_Click({
            # Als Kopie übernehmen - die Liste des Dialogs ist nach dem Schließen ungültig.
            $global:SelectedDrives = @($checkedListBox.CheckedItems | ForEach-Object { [string]$_ })
            $driveForm.Close()
        })

        $driveForm.Controls.Add($checkedListBox)
        $driveForm.Controls.Add($btnConfirm)
        [void]$driveForm.ShowDialog()
    })

    $btnOpenFolder.Add_Click({
        $desktopPath = [System.Environment]::GetFolderPath("Desktop")
        $lanGamesPath = Join-Path -Path $desktopPath -ChildPath "Lan Games"
        if (-not (Test-Path $lanGamesPath)) { New-Item -Path $lanGamesPath -ItemType Directory -Force | Out-Null }
        Invoke-Item $lanGamesPath
    })

    # Eigene Listen: Whitelist, Blacklist und EXE-Korrekturen als Textdateien (werden bei
    # Bedarf mit Erklärung angelegt und im Editor geöffnet).
    $listMenu = (New-PelContextMenu)
    foreach ($entry in @(
            @{ Text = 'Eigene Whitelist bearbeiten (zusätzliche Spiele)'; Path = $script:PelUserWhitelistPath },
            @{ Text = 'Eigene Blacklist bearbeiten (nie verknüpfen)'; Path = $script:PelUserBlacklistPath },
            @{ Text = 'EXE-Korrekturen bearbeiten (Spiel | richtige .exe)'; Path = $script:PelExeOverridePath })) {
        $mi = New-Object System.Windows.Forms.ToolStripMenuItem($entry.Text)
        $mi.Tag = $entry.Path
        $mi.Add_Click({
            Initialize-PelUserLists
            try { Start-Process -FilePath 'notepad.exe' -ArgumentList "`"$($this.Tag)`"" } catch { }
        })
        [void]$listMenu.Items.Add($mi)
    }
    $btnLists.Add_Click({ $listMenu.Show($btnLists, (New-Object System.Drawing.Point(0, $btnLists.Height))) })

    $btnStartScan.Add_Click({
        $btnStartScan.Enabled = $false
        try {
        $txtLog.Clear()
        $log = { param([string]$t) [PelI18n]::Append($txtLog, $t + "`r`n"); [System.Windows.Forms.Application]::DoEvents() }
        & $log "Starte Scan mit Whitelist, Blacklist, eigenen Listen und EXE-Bewertung ..."
        Initialize-PelUserLists

        # Ergebnisse landen in der Spielebibliothek. Verknüpfungen im Desktop-Ordner
        # "Lan Games" gibt es nur noch, wenn der Haken in der Bibliothek gesetzt ist.
        $scanLib = Get-PelGameLibrary
        $makeLinks = [bool]$scanLib.MakeShortcuts
        # Automatisch gefundene Einträge, deren EXE es nicht mehr gibt (Spiel deinstalliert),
        # fliegen raus; bestätigte und vom Nutzer entfernte bleiben unangetastet.
        foreach ($old in @($scanLib.Games | Where-Object { $_.Source -eq 'Scan' -and -not $_.Pinned -and -not $_.Hidden -and -not [System.IO.File]::Exists([string]$_.Exe) })) {
            [void]$scanLib.Games.Remove($old)
        }
        if ($makeLinks) { & $log "Verknüpfungen im Ordner 'Lan Games' werden zusätzlich angelegt." }

        $desktopPath = [System.Environment]::GetFolderPath("Desktop")
        $targetDir = Join-Path -Path $desktopPath -ChildPath "Lan Games"
        if ($makeLinks -and -not (Test-Path $targetDir)) { New-Item -Path $targetDir -ItemType Directory -Force | Out-Null }

        # Alte automatische Verknüpfungen entfernen - aber NUR die, die dieser Scan selbst
        # angelegt hat (Kennung in der Beschreibung). Beim allerersten Scan nach dem Update
        # haben noch keine Verknüpfungen eine Kennung: die bisherigen werden dann nicht
        # gelöscht, sondern in einen Unterordner verschoben (manuell angelegte lassen sich
        # von dort einfach zurückholen). Ohne Haken bleibt der Ordner völlig unberührt.
        $wshScan = New-Object -ComObject WScript.Shell
        $existing = @()
        if ($makeLinks) { $existing = @(Get-ChildItem -LiteralPath $targetDir -Filter '*.lnk' -File -ErrorAction SilentlyContinue) }
        $descs = @{}
        $migrated = $false
        foreach ($lnk in $existing) {
            $dsc = ''
            try { $dsc = [string]$wshScan.CreateShortcut($lnk.FullName).Description } catch { }
            $descs[$lnk.FullName] = $dsc
            if ($dsc -like 'Project Earth LAN*') { $migrated = $true }
        }
        if ($migrated) {
            $keptCount = 0
            foreach ($lnk in $existing) {
                if ([string]$descs[$lnk.FullName] -like "$autoDesc*") { Remove-Item -LiteralPath $lnk.FullName -Force -ErrorAction SilentlyContinue }
                else { $keptCount++ }
            }
            if ($keptCount -gt 0) { & $log "$keptCount eigene/manuelle Verknüpfung(en) bleiben erhalten." }
        } elseif ($existing.Count -gt 0) {
            $backupDir = Join-Path $targetDir '_Alte Verknüpfungen (vor Update)'
            if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -Path $backupDir -ItemType Directory -Force | Out-Null }
            foreach ($lnk in $existing) { Move-Item -LiteralPath $lnk.FullName -Destination (Join-Path $backupDir $lnk.Name) -Force -ErrorAction SilentlyContinue }
            & $log "Einmalige Umstellung: $($existing.Count) bisherige Verknüpfung(en) nach '_Alte Verknüpfungen (vor Update)' verschoben."
            & $log "  -> Selbst angelegte von dort einfach zurück in 'Lan Games' ziehen; sie bleiben ab jetzt bei jedem Scan erhalten."
        }

