        $ExtraWhitelist = @(
            'Medal of Honor', 'Medal of Honor Allied Assault', 'Call of Duty: United Offensive', 'Call of Duty: World at War', 'Soldier of Fortune II',
            'Starsiege: Tribes', 'Delta Force', 'Operation Flashpoint', 'Arma', 'Ghost Recon', 'Rainbow Six', 'Hidden & Dangerous 2', 'Worms', 'The Settlers',
            'Need for Speed', 'Command & Conquer', 'Red Alert', 'Serious Sam', 'Painkiller', 'Quake 4', "America's Army", 'Tactical Ops', 'Postal 2',
            'Red Orchestra', 'Rising Storm', 'Day of Infamy', 'Deep Rock Galactic', 'Valheim', 'Satisfactory', 'Raft', 'Grounded', 'Lethal Company',
            'Core Keeper', 'Empyrion - Galactic Survival', 'Astroneer', 'Barotrauma', 'DDNet', 'Age of Empires II', 'Age of Empires', 'Stronghold Crusader',
            'Halo', 'Crysis', 'Enemy Territory', 'Heroes of Might and Magic', 'Diablo II', 'Trackmania', 'Unreal Tournament'
        )
        $GameWhitelist = @(@(($RawText -split ',') | ForEach-Object { $_.Trim() } | Where-Object { $_ }) + $ExtraWhitelist + @(Get-PelUserList $script:PelUserWhitelistPath) | Select-Object -Unique)

        # --- Blacklist ------------------------------------------------------------------
        # Begriffe gelten als ganze Wörter/Wortgruppen. Bewusst NICHT mehr als Teilwort:
        # "mod" (traf "Garry's Mod", "Modern Warfare"), "driver" ("Race Driver: Grid"),
        # "flash" ("Operation Flashpoint"), "chrome" ("Chrome Trip"), "clone" ("One Clone
        # Left"), "edge", "client", "update", "windows", "player", "security".
        $NameBlacklist = @(
            # Programme & Werkzeuge
            '7-zip', '7 zip', 'winrar', 'docker', 'jdownloader', 'kodi', 'bandicam', 'total commander', 'sd card formatter',
            'google chrome', 'mozilla firefox', 'firefox', 'microsoft edge', 'opera gx', 'browser', 'java runtime', 'java se', 'java update', 'java tm',
            'adobe flash', 'flash player', 'visual c++', 'visual c', 'runtime', 'redistributable', 'redistributables', 'codec', 'codec pack', 'media player',
            'vlc', 'messenger', 'zerotier', 'hamachi', 'radmin vpn', 'tailscale', 'registry', 'sdk', 'plugin', 'nvidia', 'geforce', 'amd software',
            'amd chipset', 'radeon software', 'intel', 'realtek', 'windows sdk', 'windows kits', 'windows driver', 'microsoft office', 'office', 'net framework',
            'dotnet', 'antivirus', 'discord', 'microsoft teams', 'teams', 'zoom', 'skype', 'spotify', 'virtualbox', 'vmware', 'notepad', 'ccleaner',
            'helper', 'driver booster', 'drivers', 'worldbuilder', 'world builder', 'level editor', 'editor', 'unrealed', 'unreal engine', 'testapp',
            'mod organizer', 'mod manager', 'clonezilla', 'macrium',
            # Launcher & Plattformen
            'epic games launcher', 'ubisoft connect', 'ubisoft game launcher', 'uplay', 'rockstar games launcher', 'ea app', 'gog galaxy', 'battle net',
            'xbox', 'game bar', 'gameinput', 'gaming services', 'geforce experience', 'razer', 'logitech', 'corsair', 'msi afterburner', 'rivatuner',
            'cheat engine', 'wemod', 'overwolf', 'curseforge', 'teamspeak', 'mumble', 'obs studio', 'streamlabs', 'reshade',
            # Keine Spiele in Steam-/Epic-Bibliotheken
            'steamworks shared', 'steamvr', 'steam controller configs', 'steam linux runtime', 'proton', 'wallpaper engine', 'soundtrack', 'ost',
            'original soundtrack', 'artbook', 'art book', 'dedicated server', 'server', 'authoring tools', 'tools', 'tool', 'benchmark', '3dmark',
            'spacewar', 'source filmmaker', 'blender', 'soundpad', 'lossless scaling', 'rpg maker', 'aseprite', 'voicemod', 'fps monitor',
            'bonus content', 'digital extras', 'deluxe content', 'source sdk'
        ) + @(Get-PelUserList $script:PelUserBlacklistPath)
        $NameBlacklistExact = @('Steam', 'Origin', 'Java', 'Vortex', 'Launcher', 'Tools', 'Redist', 'Setup', 'Installer', 'Uninstall', 'Support', 'Engine', 'Common')

        $AllDiscoveredGames = New-Object System.Collections.Generic.List[object]

        # Steam: Bibliotheken + App-Manifeste (liefern den echten Spielnamen und die App-ID)
        $steamRoot = $null
        try { $steamRoot = (Get-ItemProperty "HKLM:\SOFTWARE\WOW6432Node\Valve\Steam" -Name "InstallPath" -ErrorAction Stop).InstallPath } catch { }
        if (-not $steamRoot) { try { $steamRoot = ((Get-ItemProperty "HKCU:\Software\Valve\Steam" -ErrorAction Stop).SteamPath) -replace '/', '\' } catch { } }
        $steamExe = $null
        if ($steamRoot) {
            $se = Join-Path $steamRoot 'steam.exe'
            if (Test-Path -LiteralPath $se) { $steamExe = $se }
            $steamLibs = @((Join-Path $steamRoot "steamapps"))
            $vdfPath = Join-Path $steamRoot "steamapps\libraryfolders.vdf"
            if (Test-Path $vdfPath) {
                foreach ($line in @(Get-Content $vdfPath -ErrorAction SilentlyContinue)) {
                    if ($line -match '"path"\s+"([^"]+)"') { $steamLibs += Join-Path ($matches[1] -replace '\\\\', '\') "steamapps" }
                }
            }
            foreach ($lib in @($steamLibs | Select-Object -Unique)) {
                $commonPath = Join-Path $lib "common"
                if (-not (Test-Path $commonPath)) { continue }
                $manifest = @{}
                foreach ($acf in @(Get-ChildItem -LiteralPath $lib -Filter 'appmanifest_*.acf' -File -ErrorAction SilentlyContinue)) {
                    try {
                        $t = [System.IO.File]::ReadAllText($acf.FullName)
                        $inst = [regex]::Match($t, '"installdir"\s+"([^"]*)"').Groups[1].Value
                        if ($inst) {
                            $manifest[$inst.ToLowerInvariant()] = [pscustomobject]@{
                                AppId = [regex]::Match($t, '"appid"\s+"(\d+)"').Groups[1].Value
                                Name  = [regex]::Match($t, '"name"\s+"([^"]*)"').Groups[1].Value
                            }
                        }
                    } catch { }
                }
                foreach ($sg in @(Get-ChildItem -Path $commonPath -Directory -Force -ErrorAction SilentlyContinue)) {
                    $mf = $manifest[$sg.Name.ToLowerInvariant()]
                    $nm = $sg.Name
                    $appId = ''
                    if ($mf) { if ($mf.Name) { $nm = $mf.Name }; $appId = $mf.AppId }
                    $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $nm; Path = $sg.FullName; Source = "Steam"; AppId = $appId; KnownExe = '' })
                }
            }
        }

        # Epic: das Manifest nennt die Start-EXE selbst ("LaunchExecutable") - die ist
        # verlässlicher als jede Suche.
        $epicManifestPath = "C:\ProgramData\Epic\EpicGamesLauncher\Data\Manifests"
        if (Test-Path $epicManifestPath) {
            foreach ($file in (Get-ChildItem -Path $epicManifestPath -Filter "*.item" -Force -ErrorAction SilentlyContinue)) {
                try {
                    $json = Read-PelTextFile $file.FullName | ConvertFrom-Json
                    if ($null -ne $json.DisplayName -and $null -ne $json.InstallLocation) {
                        $ke = ''
                        if ($json.LaunchExecutable) { $cand = Join-Path $json.InstallLocation $json.LaunchExecutable; if (Test-Path -LiteralPath $cand) { $ke = $cand } }
                        $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $json.DisplayName; Path = $json.InstallLocation; Source = "Epic"; AppId = ''; KnownExe = $ke })
                    }
                } catch { }
            }
        }

        foreach ($install in (Get-ItemProperty "HKLM:\SOFTWARE\WOW6432Node\Ubisoft\Launcher\Installs\*" -ErrorAction SilentlyContinue)) {
            if ($null -ne $install.InstallDir) {
                $AllDiscoveredGames.Add([PSCustomObject]@{ Name = (Split-Path $install.InstallDir -Leaf); Path = $install.InstallDir; Source = "Ubisoft"; AppId = ''; KnownExe = '' })
            }
        }
        # GOG: der Registry-Eintrag nennt die Spiel-EXE ebenfalls direkt ("exe")
        foreach ($install in (Get-ItemProperty "HKLM:\SOFTWARE\WOW6432Node\GOG.com\Games\*" -ErrorAction SilentlyContinue)) {
            if ($null -ne $install.GAMENAME -and $null -ne $install.path) {
                $ke = ''
                if ($install.exe -and (Test-Path -LiteralPath ([string]$install.exe))) { $ke = [string]$install.exe }
                $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $install.GAMENAME; Path = $install.path; Source = "GOG"; AppId = ''; KnownExe = $ke })
            }
        }
        foreach ($install in (Get-ItemProperty "HKLM:\SOFTWARE\WOW6432Node\Origin Games\*" -ErrorAction SilentlyContinue)) {
            if ($null -ne $install.DisplayName -and $null -ne $install.InstallDir) {
                $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $install.DisplayName; Path = $install.InstallDir; Source = "EA App"; AppId = ''; KnownExe = '' })
            }
        }

        foreach ($drive in $global:SelectedDrives) {
            foreach ($dir in @((Join-Path $drive "Games"), (Join-Path $drive "Spiele"), (Join-Path $drive "Program Files\ElAmigos"), (Join-Path $drive "Program Files (x86)\ElAmigos"))) {
                if (Test-Path $dir) {
                    foreach ($sd in (Get-ChildItem -Path $dir -Directory -Force -ErrorAction SilentlyContinue)) {
                        $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $sd.Name; Path = $sd.FullName; Source = "CustomDir"; AppId = ''; KnownExe = '' })
                    }
                }
            }
        }

        $regPaths = @(
            "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
            "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
            "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
        )
        foreach ($app in (Get-ItemProperty $regPaths -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -and $_.InstallLocation })) {
            $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $app.DisplayName; Path = $app.InstallLocation; Source = "Registry"; AppId = ''; KnownExe = '' })
        }

        # EXE-Korrekturen: gelten für gefundene Spiele und werden zusätzlich als eigene
        # Einträge übernommen (auch wenn der Scan das Spiel selbst nicht findet).
        $overrides = @{}
        foreach ($ov in @(Get-PelExeOverrides)) {
            $overrides[$ov.Key] = $ov
            if (Test-Path -LiteralPath $ov.Path) {
                $AllDiscoveredGames.Add([PSCustomObject]@{ Name = $ov.Name; Path = [System.IO.Path]::GetDirectoryName($ov.Path); Source = "Eigene Liste"; AppId = ''; KnownExe = $ov.Path })
            } else {
                & $log "[Eigene Liste] EXE nicht gefunden, übersprungen: $($ov.Name) -> $($ov.Path)"
            }
        }

        & $log "Gefunden: $($AllDiscoveredGames.Count) Einträge - wende Filter an und wähle die Spiel-EXE ..."

        $storeSources = @('Steam', 'Epic', 'Ubisoft', 'GOG', 'EA App', 'Eigene Liste')
        $gamesCount = 0
        $processedPaths = @{}
        $processedNames = @{}
        $skipBlack = New-Object System.Collections.Generic.List[string]
        $skipNoExe = New-Object System.Collections.Generic.List[string]
        $skipUnsafe = 0
        $skipNotWhite = 0

        # Eigene Liste zuerst (hat Vorrang), dann die Stores, dann Registry/Ordner
        $order = @{ 'Eigene Liste' = 0; 'Steam' = 1; 'Epic' = 1; 'GOG' = 1; 'Ubisoft' = 1; 'EA App' = 1; 'CustomDir' = 2; 'Registry' = 3 }
        foreach ($gameObj in @($AllDiscoveredGames | Sort-Object @{ Expression = { $order[[string]$_.Source] } })) {
            if ([string]::IsNullOrWhiteSpace($gameObj.Path) -or [string]::IsNullOrWhiteSpace($gameObj.Name)) { continue }
            $cleanPath = ([string]$gameObj.Path).Trim().Trim('"').TrimEnd('\')
            $pathKey = $cleanPath.ToLowerInvariant()
            $nameKey = ConvertTo-PelMatchText $gameObj.Name
            if ($processedPaths.ContainsKey($pathKey) -or $processedNames.ContainsKey($nameKey)) { continue }

            if ($gameObj.Source -ne 'Eigene Liste') {
                $bad = Find-PelBlacklistMatch -Name $gameObj.Name -Phrases $NameBlacklist -ExactNames $NameBlacklistExact
                if ($bad) { if ($gameObj.Source -in $storeSources) { $skipBlack.Add("$($gameObj.Name) ($bad)") }; continue }
                if ($gameObj.Source -notin $storeSources) {
                    if (-not (Find-PelWhitelistMatch -Name $gameObj.Name -Entries $GameWhitelist)) { $skipNotWhite++; continue }
                }
                if (Test-PelUnsafeGameRoot $cleanPath) { $skipUnsafe++; continue }
            }

            $driveMatch = $false
            foreach ($drive in $global:SelectedDrives) {
                if ($cleanPath.StartsWith([string]$drive, [System.StringComparison]::OrdinalIgnoreCase)) { $driveMatch = $true; break }
            }
            if (-not $driveMatch) { continue }
            if (-not (Test-Path -LiteralPath $cleanPath)) { continue }

            # Spiel-EXE bestimmen: eigene Korrektur > Angabe des Stores > Bewertung
            $exePath = $null
            $why = ''
            $ov = $overrides[$nameKey]
            if ($ov -and (Test-Path -LiteralPath $ov.Path)) { $exePath = $ov.Path; $why = 'eigene Korrektur' }
            elseif ($gameObj.KnownExe -and ([System.IO.Path]::GetFileNameWithoutExtension([string]$gameObj.KnownExe) -notmatch $script:PelExeExcludeNames)) {
                $exePath = [string]$gameObj.KnownExe; $why = "Angabe von $($gameObj.Source)"
            } else {
                $sel = Select-PelGameExe -Folder $cleanPath -GameName $gameObj.Name
                if ($sel) { $exePath = $sel.Path; $why = $sel.Reason }
            }
            if (-not $exePath) {
                if ($gameObj.Source -in $storeSources) { $skipNoExe.Add([string]$gameObj.Name) }
                continue
            }

            $rel = $exePath
            if ($exePath.StartsWith($cleanPath, [System.StringComparison]::OrdinalIgnoreCase)) { $rel = $exePath.Substring($cleanPath.Length).TrimStart('\') }
            try {
                $viaSteam = ($gameObj.Source -eq 'Steam' -and $gameObj.AppId -and $steamExe -and $why -ne 'eigene Korrektur')
                $libEntry = Set-PelLibraryGame -Library $scanLib -Name ([string]$gameObj.Name) -Exe $exePath -Source 'Scan' -AppId $(if ($viaSteam) { [string]$gameObj.AppId } else { '' })
                if ($libEntry -and $libEntry.Hidden) {
                    # Vom Nutzer aus der Bibliothek entfernt - nicht wieder aufnehmen.
                    $processedPaths[$pathKey] = $true
                    $processedNames[$nameKey] = $true
                    continue
                }
                if ($viaSteam) {
                    # Steam-Spiele über Steam starten (-applaunch): Steam setzt dabei alle
                    # nötigen Startparameter (z. B. "-game cstrike" bei Source-Spielen,
                    # Anticheat, DRM) - die ausgewählte EXE dient als Symbol und für die
                    # Spielerkennung/Mitspielen (steht in der Beschreibung).
                    if ($makeLinks) { New-GameShortcut -SourcePath $steamExe -Arguments "-applaunch $($gameObj.AppId)" -GameExe $exePath -DestinationFolder $targetDir -ShortcutName $gameObj.Name -Description "$autoDesc | exe=$exePath" }
                    & $log "[Steam] $($gameObj.Name)  ->  über Steam (App $($gameObj.AppId)), EXE: $rel ($why)"
                } else {
                    if ($makeLinks) { New-GameShortcut -SourcePath $exePath -DestinationFolder $targetDir -ShortcutName $gameObj.Name -Description $autoDesc }
                    & $log "[$($gameObj.Source)] $($gameObj.Name)  ->  $rel ($why)"
                }
                $processedPaths[$pathKey] = $true
                $processedNames[$nameKey] = $true
                $gamesCount++
            } catch {
                & $log "[$($gameObj.Source)] FEHLER bei $($gameObj.Name): $($_.Exception.Message)"
            }
        }

        & $log ""
        if (Save-PelGameLibrary $scanLib) {
            & $log "Fertig! $gamesCount LAN-Spiele gefunden und in die Spielebibliothek übernommen."
        } else {
            & $log "FEHLER: Die Spielebibliothek konnte nicht gespeichert werden (siehe Fehlerlog)."
        }
        if ($makeLinks) { & $log "Verknüpfungen liegen im Desktop-Ordner 'Lan Games'." }
        if ($skipBlack.Count -gt 0) { & $log "Ausgelassen (Blacklist, keine Spiele): $($skipBlack -join '; ')" }
        if ($skipNoExe.Count -gt 0) { & $log "Ausgelassen (keine passende Spiel-EXE gefunden): $($skipNoExe -join '; ')" }
        & $log "Nicht auf der Whitelist (Registry/Spieleordner): $skipNotWhite  |  Sammelordner übersprungen: $skipUnsafe"
        & $log "Falsche EXE oder fehlendes Spiel? -> 'Eigene Listen' (EXE-Korrekturen / Whitelist / Blacklist) und neu scannen."
        } finally {
            $btnStartScan.Enabled = $true
        }
    })

    [void]$form.ShowDialog()
}

# ------------------------------------------------------------------------------
# Manuelle Game Suche (bisher Option 4, jetzt Option 3 -> "Manuell suchen")
# ------------------------------------------------------------------------------
function Invoke-ManualGameSearch {
    # C#-Suchmotor: läuft in einem Hintergrund-Thread, die GUI bleibt bedienbar.
    # Durchsucht alle Laufwerke inkl. versteckter Dateien/Ordner und Systemdateien
    # (das Skript läuft dank Start-Prüfung immer mit Administratorrechten).
    if (-not ('EarthFileSearcher' -as [type])) {
        $searcherCode = @'
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Threading;

public class EarthSearchHit
{
    public string FullPath;
    public bool IsDirectory;
    public bool IsHidden;
}

public class EarthFileSearcher
{
    public ConcurrentQueue<EarthSearchHit> Hits = new ConcurrentQueue<EarthSearchHit>();
    public volatile bool CancelRequested;
    public volatile bool Finished;
    public volatile bool LimitReached;
    public volatile string CurrentDir = "";
    public int HitCount;
    public int ScannedCount;
    public int MaxHits = 1000;

    private string[] roots;
    private string[] words;
    private bool allTypes;
    private bool skipWindows;
    private string windowsDir;
    private Thread worker;

    public EarthFileSearcher(string[] roots, string[] words, bool allTypes, bool skipWindows)
    {
        this.roots = roots;
        this.words = words;
        this.allTypes = allTypes;
        this.skipWindows = skipWindows;
        string sr = Environment.GetEnvironmentVariable("SystemRoot");
        this.windowsDir = (sr == null) ? "" : sr.TrimEnd('\\');
    }

    public void Start()
    {
        worker = new Thread(new ThreadStart(Run));
        worker.IsBackground = true;
        worker.Start();
    }

    public void Cancel()
    {
        CancelRequested = true;
    }

    private void Run()
    {
        try
        {
            foreach (string root in roots)
            {
                if (CancelRequested || LimitReached) break;
                Walk(root);
            }
        }
        catch (Exception) { }
        Finished = true;
    }

    private bool Matches(string name)
    {
        for (int i = 0; i < words.Length; i++)
        {
            if (name.IndexOf(words[i], StringComparison.OrdinalIgnoreCase) < 0) return false;
        }
        return true;
    }

    private bool ShouldSkipDescent(string fullName, string name)
    {
        if (name.Equals("$Recycle.Bin", StringComparison.OrdinalIgnoreCase)) return true;
        if (name.Equals("System Volume Information", StringComparison.OrdinalIgnoreCase)) return true;
        if (skipWindows && windowsDir.Length > 0 &&
            string.Equals(fullName.TrimEnd('\\'), windowsDir, StringComparison.OrdinalIgnoreCase)) return true;
        return false;
    }

    private void AddHit(FileSystemInfo fi, bool isDir)
    {
        EarthSearchHit h = new EarthSearchHit();
        h.FullPath = fi.FullName;
        h.IsDirectory = isDir;
        h.IsHidden = (fi.Attributes & (FileAttributes.Hidden | FileAttributes.System)) != 0;
        Hits.Enqueue(h);
        HitCount++;
        if (HitCount >= MaxHits) LimitReached = true;
    }

    private void Walk(string root)
    {
        Stack<string> stack = new Stack<string>();
        stack.Push(root);

        while (stack.Count > 0)
        {
            if (CancelRequested || LimitReached) return;

            string dir = stack.Pop();
            CurrentDir = dir;

            IEnumerable<FileSystemInfo> entries;
            try
            {
                entries = new DirectoryInfo(dir).EnumerateFileSystemInfos();
            }
            catch (Exception)
            {
                continue;
            }

            try
            {
                foreach (FileSystemInfo fi in entries)
                {
                    if (CancelRequested || LimitReached) return;
                    ScannedCount++;

                    string name = fi.Name;
                    bool isDir = (fi.Attributes & FileAttributes.Directory) == FileAttributes.Directory;

                    if (isDir)
                    {
                        if (Matches(name)) AddHit(fi, true);

                        bool isReparse = (fi.Attributes & FileAttributes.ReparsePoint) == FileAttributes.ReparsePoint;
                        if (!isReparse && !ShouldSkipDescent(fi.FullName, name))
                        {
                            stack.Push(fi.FullName);
                        }
                    }
                    else
                    {
                        if ((allTypes || name.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)) && Matches(name))
                        {
                            AddHit(fi, false);
                        }
                    }
                }
            }
            catch (Exception)
            {
                // Zugriff verweigert o.ä. -> nächstes Verzeichnis
            }
        }
    }
}
'@
        Add-Type -TypeDefinition $searcherCode -Language CSharp
    }

    $state = @{ Searcher = $null }

    # --- Hilfsfunktionen -------------------------------------------------------
    function Get-LanGamesFolder {
        $desktopPath = [System.Environment]::GetFolderPath("Desktop")
        $path = Join-Path -Path $desktopPath -ChildPath "Lan Games"
        if (-not (Test-Path -LiteralPath $path)) {
            New-Item -Path $path -ItemType Directory -Force | Out-Null
        }
        return $path
    }

    # Haupt-EXE im gewählten Ordner: dieselbe Bewertung wie der LAN Game Finder (Option 3)
    # statt "größte Datei" - siehe Select-PelGameExe.
    function Find-MainExe {
        param ([string]$FolderPath)
        $sel = Select-PelGameExe -Folder $FolderPath -GameName ([System.IO.Path]::GetFileName($FolderPath.TrimEnd('\')))
        if ($sel) { return $sel.Path }
        return $null
    }

    function New-LanShortcut {
        param ([string]$TargetPath, [string]$DestinationFolder, [string]$ShortcutName, [string]$WorkingDirectory)
        $cleanName = ($ShortcutName -replace '[\\/:*?"<>|]', '').Trim()
        if ([string]::IsNullOrWhiteSpace($cleanName)) { $cleanName = "Spiel" }

        $wsh = New-Object -ComObject WScript.Shell
        $shortcutPath = Join-Path -Path $DestinationFolder -ChildPath "$cleanName.lnk"
        $counter = 2
        while (Test-Path -LiteralPath $shortcutPath) {
            $existing = $wsh.CreateShortcut($shortcutPath)
            if ($existing.TargetPath -ieq $TargetPath) { return "vorhanden" }
            $shortcutPath = Join-Path -Path $DestinationFolder -ChildPath "$cleanName ($counter).lnk"
            $counter++
        }
        $sc = $wsh.CreateShortcut($shortcutPath)
        $sc.TargetPath = $TargetPath
        $sc.WorkingDirectory = $WorkingDirectory
        # Kennung: manuell angelegt -> wird vom LAN Game Finder (Option 3) nie gelöscht
        $sc.Description = 'Project Earth LAN - manuell (Option 4)'
        $sc.Save()
        return "erstellt"
    }

    # --- GUI -------------------------------------------------------------------
    $form = (New-PelForm)
    $form.Text = "Manuelle Game Suche"
    $form.Size = New-Object System.Drawing.Size(900, 640)
    $form.MinimumSize = New-Object System.Drawing.Size(760, 520)
    $form.StartPosition = "CenterParent"
    $form.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $form.ForeColor = [System.Drawing.Color]::White

    $fontMain = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
    $fontBold = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)

    $lblSearch = New-Object System.Windows.Forms.Label
    $lblSearch.Text = "Spielname:"
    $lblSearch.Location = New-Object System.Drawing.Point(20, 20)
    $lblSearch.Size = New-Object System.Drawing.Size(80, 22)
    $lblSearch.ForeColor = [System.Drawing.Color]::White
    $lblSearch.Font = $fontBold

    $txtSearch = New-Object System.Windows.Forms.TextBox
    $txtSearch.Location = New-Object System.Drawing.Point(105, 17)
    $txtSearch.Size = New-Object System.Drawing.Size(490, 26)
    $txtSearch.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 50)
    $txtSearch.ForeColor = [System.Drawing.Color]::White
    $txtSearch.Font = $fontMain
    $txtSearch.Anchor = "Top,Left,Right"

    $btnSearch = New-Object System.Windows.Forms.Button
    $btnSearch.Text = "Suchen"
    $btnSearch.Location = New-Object System.Drawing.Point(605, 14)
    $btnSearch.Size = New-Object System.Drawing.Size(120, 30)
    $btnSearch.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnSearch.ForeColor = [System.Drawing.Color]::White
    $btnSearch.FlatStyle = "Flat"
    $btnSearch.Font = $fontBold
    $btnSearch.Anchor = "Top,Right"

    $btnStop = New-Object System.Windows.Forms.Button
    $btnStop.Text = "Stopp"
    $btnStop.Location = New-Object System.Drawing.Point(735, 14)
    $btnStop.Size = New-Object System.Drawing.Size(125, 30)
    $btnStop.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnStop.ForeColor = [System.Drawing.Color]::White
    $btnStop.FlatStyle = "Flat"
    $btnStop.Font = $fontMain
    $btnStop.Anchor = "Top,Right"

    $chkAllTypes = New-Object System.Windows.Forms.CheckBox
    $chkAllTypes.Text = "Alle Dateitypen anzeigen (nicht nur .exe)"
    $chkAllTypes.Location = New-Object System.Drawing.Point(105, 52)
    $chkAllTypes.Size = New-Object System.Drawing.Size(320, 24)
    $chkAllTypes.ForeColor = [System.Drawing.Color]::White
    $chkAllTypes.Font = $fontMain

    $chkSkipWindows = New-Object System.Windows.Forms.CheckBox
    $chkSkipWindows.Text = "Windows-Ordner überspringen (schneller)"
    $chkSkipWindows.Checked = $true
    $chkSkipWindows.Location = New-Object System.Drawing.Point(440, 52)
    $chkSkipWindows.Size = New-Object System.Drawing.Size(340, 24)
    $chkSkipWindows.ForeColor = [System.Drawing.Color]::White
    $chkSkipWindows.Font = $fontMain

    $lblStatus = New-Object System.Windows.Forms.Label
    $lblStatus.Text = "Suchbegriff eingeben - die Suche startet automatisch (mind. 2 Zeichen)."
    $lblStatus.Location = New-Object System.Drawing.Point(20, 84)
    $lblStatus.Size = New-Object System.Drawing.Size(840, 22)
    $lblStatus.ForeColor = [System.Drawing.Color]::LightGray
    $lblStatus.Font = $fontMain
    $lblStatus.Anchor = "Top,Left,Right"

    $listView = New-Object System.Windows.Forms.ListView
    $listView.Location = New-Object System.Drawing.Point(20, 112)
    $listView.Size = New-Object System.Drawing.Size(840, 390)
    $listView.View = "Details"
    $listView.FullRowSelect = $true
    $listView.MultiSelect = $true
    $listView.HideSelection = $false
    $listView.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
    $listView.ForeColor = [System.Drawing.Color]::White
    $listView.BorderStyle = "FixedSingle"
    $listView.Font = New-Object System.Drawing.Font("Consolas", 9)
    $listView.Anchor = "Top,Bottom,Left,Right"
    [void]$listView.Columns.Add("Name", 230)
    [void]$listView.Columns.Add("Typ", 70)
    [void]$listView.Columns.Add("Versteckt", 75)
    [void]$listView.Columns.Add("Pfad", 440)

    $btnOpen = New-Object System.Windows.Forms.Button
    $btnOpen.Text = "1. Verzeichnis öffnen"
    $btnOpen.Location = New-Object System.Drawing.Point(20, 515)
    $btnOpen.Size = New-Object System.Drawing.Size(410, 42)
    $btnOpen.BackColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
    $btnOpen.ForeColor = [System.Drawing.Color]::White
    $btnOpen.FlatStyle = "Flat"
    $btnOpen.Font = $fontBold
    $btnOpen.Anchor = "Bottom,Left"

    $btnShortcut = New-Object System.Windows.Forms.Button
    $btnShortcut.Text = "2. Zur Spielebibliothek hinzufügen"
    $btnShortcut.Location = New-Object System.Drawing.Point(450, 515)
    $btnShortcut.Size = New-Object System.Drawing.Size(410, 42)
    $btnShortcut.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnShortcut.ForeColor = [System.Drawing.Color]::White
    $btnShortcut.FlatStyle = "Flat"
    $btnShortcut.Font = $fontBold
    $btnShortcut.Anchor = "Bottom,Right"

    foreach ($ctrl in @($lblSearch, $txtSearch, $btnSearch, $btnStop, $chkAllTypes, $chkSkipWindows, $lblStatus, $listView, $btnOpen, $btnShortcut)) {
        $form.Controls.Add($ctrl)
    }

    # Timer: Verzögerung nach dem Tippen (dynamische Suche)
    $debounceTimer = New-Object System.Windows.Forms.Timer
    $debounceTimer.Interval = 600

    # Timer: Treffer aus dem Hintergrund-Thread in die Liste übernehmen
    $pollTimer = New-Object System.Windows.Forms.Timer
    $pollTimer.Interval = 150

    # --- Suche starten ---------------------------------------------------------
    function Start-ManualSearch {
        $debounceTimer.Stop()
        $pollTimer.Stop()
        if ($null -ne $state.Searcher) { $state.Searcher.Cancel() }
        $state.Searcher = $null
        $listView.Items.Clear()

        $text = $txtSearch.Text.Trim()
        if ($text.Length -lt 2) {
            $lblStatus.Text = "Suchbegriff eingeben - die Suche startet automatisch (mind. 2 Zeichen)."
            return
        }

        $words = [string[]]@($text -split '\s+' | Where-Object { $_ })
        $roots = [string[]]@(
            [System.IO.DriveInfo]::GetDrives() |
                Where-Object { $_.IsReady -and ($_.DriveType -eq 'Fixed' -or $_.DriveType -eq 'Removable') } |
                ForEach-Object { $_.RootDirectory.FullName }
        )
        if ($roots.Count -eq 0) {
            $lblStatus.Text = "Keine durchsuchbaren Laufwerke gefunden."
            return
        }

        $searcher = [EarthFileSearcher]::new($roots, $words, [bool]$chkAllTypes.Checked, [bool]$chkSkipWindows.Checked)
        $state.Searcher = $searcher
        $lblStatus.Text = "Suche läuft..."
        $searcher.Start()
        $pollTimer.Start()
    }

    $debounceTimer.Add_Tick({ Start-ManualSearch })

    $pollTimer.Add_Tick({
        $s = $state.Searcher
        if ($null -eq $s) { $pollTimer.Stop(); return }

        $hit = $null
        $added = 0
        $listView.BeginUpdate()
        while ($added -lt 200 -and $s.Hits.TryDequeue([ref]$hit)) {
            $li = New-Object System.Windows.Forms.ListViewItem([System.IO.Path]::GetFileName($hit.FullPath))
            [void][PelI18n]::AddSub($li, $(if ($hit.IsDirectory) { "Ordner" } else { "Datei" }))
            [void][PelI18n]::AddSub($li, $(if ($hit.IsHidden) { "Ja" } else { "" }))
            [void][PelI18n]::AddSub($li, $hit.FullPath)
            $li.Tag = $hit
            [void]$listView.Items.Add($li)
            $added++
        }
        $listView.EndUpdate()

        if ($s.Finished -and $s.Hits.IsEmpty) {
            $pollTimer.Stop()
            if ($s.LimitReached) {
                $lblStatus.Text = "Limit von $($s.MaxHits) Treffern erreicht - bitte Suchbegriff eingrenzen."
            } else {
                $lblStatus.Text = "Fertig: $($listView.Items.Count) Treffer ($($s.ScannedCount) Einträge durchsucht)."
            }
        } else {
            $cur = [string]$s.CurrentDir
            if ($cur.Length -gt 80) { $cur = $cur.Substring(0, 77) + "..." }
            $lblStatus.Text = "Suche läuft... $($listView.Items.Count) Treffer | $($s.ScannedCount) Einträge | $cur"
        }
    })

    # --- Ereignisse ------------------------------------------------------------
    $txtSearch.Add_TextChanged({
        $debounceTimer.Stop()
        $debounceTimer.Start()
    })

    $txtSearch.Add_KeyDown({
        if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) {
            $_.SuppressKeyPress = $true
            Start-ManualSearch
        }
    })

    $chkAllTypes.Add_CheckedChanged({ if ($txtSearch.Text.Trim().Length -ge 2) { $debounceTimer.Stop(); $debounceTimer.Start() } })
    $chkSkipWindows.Add_CheckedChanged({ if ($txtSearch.Text.Trim().Length -ge 2) { $debounceTimer.Stop(); $debounceTimer.Start() } })

    $btnSearch.Add_Click({ Start-ManualSearch })

    $btnStop.Add_Click({
        $debounceTimer.Stop()
        $pollTimer.Stop()
        if ($null -ne $state.Searcher) {
            $state.Searcher.Cancel()
            $lblStatus.Text = "Suche abgebrochen: $($listView.Items.Count) Treffer."
        }
    })

    # Option 1: Verzeichnis öffnen (bei Dateien wird die Datei im Explorer markiert)
    $btnOpen.Add_Click({
        $sel = @($listView.SelectedItems)
        if ($sel.Count -eq 0) {
            [PelI18n]::Show("Bitte zuerst einen Treffer in der Liste auswählen.", "Hinweis", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
            return
        }
        if ($sel.Count -gt 5) {
            $answer = [PelI18n]::Show("Es sind $($sel.Count) Treffer ausgewählt. Wirklich $($sel.Count) Explorer-Fenster öffnen?", "Bestätigung", [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
            if ($answer -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        }
        foreach ($item in $sel) {
            $hit = $item.Tag
            try {
                if ($hit.IsDirectory) {
                    Start-Process explorer.exe -ArgumentList "`"$($hit.FullPath)`""
                } else {
                    Start-Process explorer.exe -ArgumentList "/select,`"$($hit.FullPath)`""
                }
            } catch {
                [PelI18n]::Show("Verzeichnis konnte nicht geöffnet werden:`n$($hit.FullPath)`n$($_.Exception.Message)", "Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
            }
        }
    })

    $listView.Add_DoubleClick({ $btnOpen.PerformClick() })

    # Option 2: Treffer in die Spielebibliothek übernehmen (bestätigt). Eine Verknüpfung in
    # 'Lan Games' gibt es zusätzlich nur, wenn der Haken in der Bibliothek gesetzt ist.
    $btnShortcut.Add_Click({
        $sel = @($listView.SelectedItems)
        if ($sel.Count -eq 0) {
            [PelI18n]::Show("Bitte zuerst einen Treffer in der Liste auswählen.", "Hinweis", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
            return
        }

        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        $report = [System.Collections.Generic.List[string]]::new()
        $created = 0
        $searchLib = Get-PelGameLibrary
        $lanFolder = $null
        try {
            if ($searchLib.MakeShortcuts) { $lanFolder = Get-LanGamesFolder }

            foreach ($item in $sel) {
                $hit = $item.Tag
                try {
                    if ($hit.IsDirectory) {
                        if (Test-PelUnsafeGameRoot $hit.FullPath) {
                            $report.Add("Übersprungen (Sammelordner, bitte den Spielordner selbst wählen): $($hit.FullPath)")
                            continue
                        }
                        $lblStatus.Text = "Suche Haupt-EXE in: $($hit.FullPath)"
                        [System.Windows.Forms.Application]::DoEvents()
                        $exe = Find-MainExe -FolderPath $hit.FullPath
                        $name = [System.IO.Path]::GetFileName($hit.FullPath)
                        if ($exe) {
                            $targetPath = $exe
                            $workDir = [System.IO.Path]::GetDirectoryName($exe)
                        } else {
                            $report.Add("Keine Spiel-EXE im Ordner gefunden - bitte die .exe selbst auswählen: $name")
                            continue
                        }
                    } else {
                        $targetPath = $hit.FullPath
                        $workDir = [System.IO.Path]::GetDirectoryName($hit.FullPath)
                        $name = [System.IO.Path]::GetFileNameWithoutExtension($hit.FullPath)
                        if (-not $targetPath.EndsWith('.exe', [System.StringComparison]::OrdinalIgnoreCase)) {
                            $report.Add("Keine .exe - übersprungen: $name")
                            continue
                        }
                    }

                    [void](Set-PelLibraryGame -Library $searchLib -Name $name -Exe $targetPath -Source 'Suche' -Pinned)
                    $created++
                    if ($lanFolder) {
                        $result = New-LanShortcut -TargetPath $targetPath -DestinationFolder $lanFolder -ShortcutName $name -WorkingDirectory $workDir
                        if ($result -ne "erstellt") { $report.Add("Verknüpfung bereits vorhanden: $name") }
                    }
                } catch {
                    $report.Add("Fehler bei $($hit.FullPath): $($_.Exception.Message)")
                }
            }
            if ($created -gt 0 -and -not (Save-PelGameLibrary $searchLib)) {
                $report.Add("Die Spielebibliothek konnte nicht gespeichert werden (siehe Fehlerlog).")
            }
        } finally {
            $form.Cursor = [System.Windows.Forms.Cursors]::Default
        }

        $lblStatus.Text = "$created Spiel(e) in die Spielebibliothek übernommen."
        $msg = "$created Spiel(e) wurden in die Spielebibliothek übernommen (Option 3)."
        if ($report.Count -gt 0) { $msg += "`n`n" + ($report -join "`n") }
        [PelI18n]::Show($msg, "Zur Spielebibliothek", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
    })

    $form.Add_Shown({ $txtSearch.Focus() })

    $form.Add_FormClosing({
        $debounceTimer.Stop()
        $pollTimer.Stop()
        if ($null -ne $state.Searcher) { $state.Searcher.Cancel() }
    })

    [void]$form.ShowDialog()

    $debounceTimer.Dispose()
    $pollTimer.Dispose()
}

#region ====== Turniere & Matchmaking (Option 4) - Kern ======
# ------------------------------------------------------------------------------
# Netzwerk: eigener Dienst auf Port 9877 (TCP für Nachrichten, UDP für die automatische
# Suche per Beacon) - gebaut wie der Chat (Port 9874). Jede Option läuft als eigener
# Prozess, deshalb gibt es keinen gemeinsamen Kanal mit dem Chat.
# Nachrichten: eine JSON-Zeile pro Nachricht, Feld "t" = Typ, "v" = 1.
# Vertrauen: Rechte hängen an der Absender-IP der TCP-Verbindung. Im P2P-Netz ist diese
# IP durch die Engine abgesichert (Pakete mit fremder Absender-IP werden verworfen). In
# einem echten LAN gilt das nur, soweit man den Mitspielern traut - so steht es auch in
# der Hilfe. Die HMAC-Signatur mit $script:PelNetworkSecret kennzeichnet nur "echter
# Manager" (das Secret steht öffentlich im Code) und schützt nicht vor anderen Managern.
# Spieler-Kennung: die ersten 12 Hex-Zeichen des SHA256 über den MachineKey aus
# p2p_settings.json - stabil über Neustarts, der Schlüssel selbst wird nie verschickt.
# ------------------------------------------------------------------------------
$script:PelMmPort = 9877
$script:PelMmDir = 'C:\Project-Earth-Lan\matchmaking'
$script:PelMmResultsPath = 'C:\Project-Earth-Lan\matchmaking\ergebnisse.json'
$script:PelMmSettingsPath = 'C:\Project-Earth-Lan\matchmaking\einstellungen.json'
# Familienregeln decken viele verschiedene Spiele ab (z. B. "source" = CS, TF2, L4D ...):
# dort entscheidet der Spielname über die Warteschlange, nicht die Regel.
$script:PelMmFamilyRules = @('source', 'a2s', 'quake3', 'unreal')

$script:PelTourneyCode = @'
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

public class EarthTourneyPeer
{
    public TcpClient Client;
    public StreamWriter Writer;
    public bool Outgoing;
    public string Id;
    public string Name = "";
    public string Ip = "";
    public string Version = "";
}

// Dienst für Option 4 (Turniere & Matchmaking), Port 9877. Aufbau wie EarthChatNode:
// UDP-Beacon zum Finden, eine TCP-Verbindung je Teilnehmer, eine Textzeile je Nachricht.
// Unterschiede: feste Spieler-Kennung statt Zufalls-ID, HMAC im Handshake, Zeilen bis
// 64 KB (Turnierstand), Zeilen werden mit Längenbegrenzung gelesen (kein Speicher-
// Überlauf durch endlose Zeilen). Den Inhalt der Nachrichten wertet PowerShell aus.
public class EarthTourneyNode
{
    private static long lastBanLoad;
    private static HashSet<string> bannedIps = new HashSet<string>();
    private static readonly object banLock = new object();
    private static bool IsIpBanned(string ip)
    {
        long now = Environment.TickCount;
        lock (banLock)
        {
            if (now - lastBanLoad > 4000 || now < lastBanLoad)
            {
                lastBanLoad = now;
                try
                {
                    HashSet<string> next = new HashSet<string>();
                    string path = @"C:\Project-Earth-Lan\ip_bans.json";
                    if (File.Exists(path))
                    {
                        string txt = File.ReadAllText(path, Encoding.UTF8);
                        foreach (Match m in Regex.Matches(txt, @"""Ip""\s*:\s*""([^""]*)""[^}]*?""Deleted""\s*:\s*(true|false)"))
                        {
                            if (m.Groups[2].Value == "false") next.Add(m.Groups[1].Value);
                        }
                    }
                    bannedIps = next;
                }
                catch (Exception) { }
            }
            return bannedIps.Contains(ip);
        }
    }

    public const int PortNumber = 9877;
    public const int MaxLine = 65536;
    private static readonly Regex idRx = new Regex("^[0-9a-f]{12}$");

    public ConcurrentQueue<string> Events = new ConcurrentQueue<string>();
    public string NodeId;
    public string NodeName;
    public string BindIp;
    public string Mask = "";
    public string Version = "";
    public string Secret = "";
    public volatile bool ScanRunning;
    public int ScanDone;
    public int ScanTotal;

    private TcpListener listener;
    private UdpClient beaconRx;
    private volatile bool running;
    private volatile bool scanCancel;
    private readonly object peerLock = new object();
    private readonly Dictionary<string, EarthTourneyPeer> peers = new Dictionary<string, EarthTourneyPeer>();
    private readonly Dictionary<string, int> lastDial = new Dictionary<string, int>();

    public EarthTourneyNode(string bindIp, string nodeId, string nodeName, string version, string secret)
    {
        BindIp = bindIp;
        NodeId = nodeId;
        NodeName = CleanName(nodeName);
        Version = CleanName(version);
        Secret = secret ?? "";
    }

    private static string CleanName(string s)
    {
        if (s == null) return "";
        s = s.Replace("\r", " ").Replace("\n", " ").Replace("|", "/").Trim();
        if (s.Length > 32) s = s.Substring(0, 32);
        return s;
    }

    private string Mac(string text)
    {
        using (HMACSHA256 h = new HMACSHA256(Encoding.UTF8.GetBytes(Secret)))
        {
            return Convert.ToBase64String(h.ComputeHash(Encoding.UTF8.GetBytes(text)));
        }
    }

    public string Start()
    {
        try
        {
            listener = new TcpListener(IPAddress.Parse(BindIp), PortNumber);
            listener.Start();
            running = true;
            Thread t = new Thread(AcceptLoop);
            t.IsBackground = true;
            t.Start();
            StartBeacon();
            return null;
        }
        catch (Exception ex)
        {
            return ex.Message;
        }
    }

    public void Stop()
    {
        running = false;
        scanCancel = true;
        try { if (listener != null) listener.Stop(); } catch (Exception) { }
        try { if (beaconRx != null) beaconRx.Close(); } catch (Exception) { }
        foreach (EarthTourneyPeer p in SnapshotPeers()) { try { p.Client.Close(); } catch (Exception) { } }
    }

    private List<EarthTourneyPeer> SnapshotPeers()
    {
        List<EarthTourneyPeer> list = new List<EarthTourneyPeer>();
        lock (peerLock) { foreach (KeyValuePair<string, EarthTourneyPeer> kv in peers) list.Add(kv.Value); }
        return list;
    }

    // ---------------- Automatische Erkennung (UDP-Beacon) ----------------
    private void StartBeacon()
    {
        try
        {
            beaconRx = new UdpClient(AddressFamily.InterNetwork);
            beaconRx.Client.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, true);
            beaconRx.Client.Bind(new IPEndPoint(IPAddress.Any, PortNumber));
            try { beaconRx.Client.IOControl((IOControlCode)(-1744830452), new byte[] { 0, 0, 0, 0 }, null); } catch (Exception) { }
            Thread rt = new Thread(BeaconRxLoop);
            rt.IsBackground = true;
            rt.Start();
        }
        catch (Exception)
        {
            beaconRx = null;
            Events.Enqueue("SYS|Automatische Suche (UDP 9877) nicht verfuegbar - andere Teilnehmer werden per Scan gesucht.");
        }
        Thread tt = new Thread(BeaconTxLoop);
        tt.IsBackground = true;
        tt.Start();
    }

    private void BeaconRxLoop()
    {
        IPEndPoint ep = new IPEndPoint(IPAddress.Any, 0);
        while (running)
        {
            byte[] d;
            try { d = beaconRx.Receive(ref ep); }
            catch (Exception)
            {
                if (!running) break;
                Thread.Sleep(50);
                continue;
            }
            try
            {
                if (d.Length > 512) continue;
                string ip = ep.Address.ToString();
                if (IsIpBanned(ip)) continue;
                string[] f = Encoding.UTF8.GetString(d).Split('|');
                if (f.Length < 4 || f[0] != "PETOUR1B" || f[1] == NodeId || !idRx.IsMatch(f[1])) continue;
                if (f[3] != Mac("PETOUR1B|" + f[1] + "|" + f[2])) continue;
                if (ip == BindIp || IsConnectedIp(ip)) continue;
                int now = Environment.TickCount;
                int last;
                lock (lastDial)
                {
                    if (lastDial.TryGetValue(ip, out last) && (now - last) < 4000) continue;
                    lastDial[ip] = now;
                }
                string ipc = ip;
                Thread t = new Thread(() =>
                {
                    TcpClient c = TryConnect(ipc, 1500);
                    if (c != null) StartOutgoing(c);
                });
                t.IsBackground = true;
                t.Start();
            }
            catch (Exception) { }
        }
    }

    private void BeaconTxLoop()
    {
        UdpClient tx = null;
        IPEndPoint bc1 = new IPEndPoint(IPAddress.Broadcast, PortNumber);
        IPEndPoint bc2 = null;
        try
        {
            tx = new UdpClient(new IPEndPoint(IPAddress.Parse(BindIp), 0));
            tx.EnableBroadcast = true;
            if (!string.IsNullOrEmpty(Mask))
            {
                uint ipN = ToUInt(IPAddress.Parse(BindIp));
                uint mk = ToUInt(IPAddress.Parse(Mask));
                bc2 = new IPEndPoint(IPAddress.Parse(FromUInt(ipN | ~mk)), PortNumber);
            }
        }
        catch (Exception) { return; }
        while (running)
        {
            try
            {
                string core = "PETOUR1B|" + NodeId + "|" + NodeName;
                byte[] msg = Encoding.UTF8.GetBytes(core + "|" + Mac(core));
                tx.Send(msg, msg.Length, bc1);
                if (bc2 != null) tx.Send(msg, msg.Length, bc2);
            }
            catch (Exception) { }
            for (int i = 0; i < 30 && running; i++) Thread.Sleep(100);
        }
        try { tx.Close(); } catch (Exception) { }
    }

    public static uint ToUInt(IPAddress a)
    {
        byte[] b = a.GetAddressBytes();
        return ((uint)b[0] << 24) | ((uint)b[1] << 16) | ((uint)b[2] << 8) | (uint)b[3];
    }

    public static string FromUInt(uint v)
    {
        return string.Format("{0}.{1}.{2}.{3}", (v >> 24) & 255, (v >> 16) & 255, (v >> 8) & 255, v & 255);
    }

    // Adressen für den Scan (wie EarthChatNet.HostRange - der Chat-Typ ist in diesem
    // Prozess nicht geladen). Große Netze (/16 im P2P) werden auf das eigene /24 begrenzt.
    public static string[] HostRange(string ip, string mask, int maxHosts)
    {
        uint ipN = ToUInt(IPAddress.Parse(ip));
        uint mk = ToUInt(IPAddress.Parse(mask));
        uint net = ipN & mk;
        uint bcast = net | ~mk;
        if (bcast - net < 2) return new string[0];
        uint first = net + 1;
        uint last = bcast - 1;
        if ((long)(last - first) + 1 > maxHosts)
        {
            net = ipN & 0xFFFFFF00u;
            first = net + 1;
            last = (net | 0xFFu) - 1;
        }
        List<string> list = new List<string>();
        for (uint x = first; x <= last; x++) list.Add(FromUInt(x));
        return list.ToArray();
    }

    [DllImport("user32.dll")]
    private static extern bool FlashWindow(IntPtr hwnd, bool invert);

    // Taskleisten-Eintrag blinken lassen (Bereit-Check, während das Fenster im Hintergrund ist)
    public static void Flash(IntPtr hwnd)
    {
        try { FlashWindow(hwnd, true); } catch (Exception) { }
    }

    // ---------------- Verbindungen ----------------
    private void AcceptLoop()
    {
        while (running)
        {
            try
            {
                TcpClient c = listener.AcceptTcpClient();
                EarthTourneyPeer p = new EarthTourneyPeer();
                p.Client = c;
                p.Outgoing = false;
                p.Ip = ((IPEndPoint)c.Client.RemoteEndPoint).Address.ToString();
                Thread t = new Thread(() => PeerLoop(p));
                t.IsBackground = true;
                t.Start();
            }
            catch (Exception)
            {
                if (!running) break;
                Thread.Sleep(50);
            }
        }
    }

    private static string ReadLimitedLine(StreamReader rd)
    {
        StringBuilder sb = new StringBuilder();
        while (true)
        {
            int c = rd.Read();
            if (c < 0) return sb.Length > 0 ? sb.ToString() : null;
            if (c == '\n') return sb.ToString();
            if (c == '\r') continue;
            sb.Append((char)c);
            if (sb.Length > MaxLine) throw new IOException("Zeile zu lang");
        }
    }

    private void Send(EarthTourneyPeer p, string line)
    {
        try
        {
            lock (p) { p.Writer.WriteLine(line); }
        }
        catch (Exception) { }
    }

    private void PeerLoop(EarthTourneyPeer p)
    {
        try
        {
            if (IsIpBanned(p.Ip)) return;
            NetworkStream ns = p.Client.GetStream();
            p.Client.NoDelay = true;
            p.Client.Client.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.KeepAlive, true);
            p.Writer = new StreamWriter(ns, new UTF8Encoding(false));
            p.Writer.AutoFlush = true;
            p.Writer.NewLine = "\n";
            StreamReader rd = new StreamReader(ns, Encoding.UTF8);
            string core = "PETOUR1|" + NodeId + "|" + NodeName + "|" + Version;
            Send(p, "HELLO|" + core + "|" + Mac(core));
            p.Client.ReceiveTimeout = 5000;
            string line = ReadLimitedLine(rd);
            if (line == null || line.Length > 512) return;
            string[] f = line.Split('|');
            if (f.Length != 6 || f[0] != "HELLO" || f[1] != "PETOUR1") return;
            if (!idRx.IsMatch(f[2]) || f[2] == NodeId) return;
            if (f[5] != Mac("PETOUR1|" + f[2] + "|" + f[3] + "|" + f[4])) return;
            p.Id = f[2];
            p.Name = CleanName(f[3]);
            p.Version = CleanName(f[4]);
            if (!Register(p)) return;
            p.Client.ReceiveTimeout = 0;
            while (running)
            {
                line = ReadLimitedLine(rd);
                if (line == null) break;
                if (line.Length == 0) continue;
                Events.Enqueue("MSG|" + p.Id + "|" + p.Ip + "|" + line);
            }
        }
        catch (Exception) { }
        finally
        {
            Unregister(p);
            try { p.Client.Close(); } catch (Exception) { }
        }
    }

    // Doppelte Verbindung (beide Seiten haben sich gleichzeitig gefunden): es bleibt die,
    // die der Teilnehmer mit der kleineren Kennung aufgebaut hat - auf beiden Seiten gleich.
    private bool Register(EarthTourneyPeer p)
    {
        lock (peerLock)
        {
            EarthTourneyPeer ex;
            if (peers.TryGetValue(p.Id, out ex))
            {
                string exInit = ex.Outgoing ? NodeId : ex.Id;
                string newInit = p.Outgoing ? NodeId : p.Id;
                if (string.CompareOrdinal(newInit, exInit) < 0)
                {
                    peers[p.Id] = p;
                    try { ex.Client.Close(); } catch (Exception) { }
                    Events.Enqueue("PEER+|" + p.Id + "|" + p.Name + "|" + p.Ip + "|" + p.Version);
                    return true;
                }
                return false;
            }
            peers[p.Id] = p;
        }
        Events.Enqueue("PEER+|" + p.Id + "|" + p.Name + "|" + p.Ip + "|" + p.Version);
        return true;
    }

    private void Unregister(EarthTourneyPeer p)
    {
        bool removed = false;
        lock (peerLock)
        {
            EarthTourneyPeer cur;
            if (p.Id != null && peers.TryGetValue(p.Id, out cur) && object.ReferenceEquals(cur, p))
            {
                peers.Remove(p.Id);
                removed = true;
            }
        }
        if (removed) Events.Enqueue("PEER-|" + p.Id + "|" + p.Name + "|" + p.Ip + "|" + p.Version);
    }

    // ---------------- Senden ----------------
    private static string CleanLine(string s)
    {
        if (s == null) return "";
        return s.Replace("\r", " ").Replace("\n", " ");
    }

    public int Broadcast(string line)
    {
        line = CleanLine(line);
        if (line.Length > MaxLine) return 0;
        List<EarthTourneyPeer> list = SnapshotPeers();
        foreach (EarthTourneyPeer p in list) Send(p, line);
        return list.Count;
    }

    public bool SendTo(string peerId, string line)
    {
        line = CleanLine(line);
        if (line.Length > MaxLine) return false;
        EarthTourneyPeer p = null;
        lock (peerLock) { peers.TryGetValue(peerId, out p); }
        if (p == null) return false;
        Send(p, line);
        return true;
    }

    public int PeerCount()
    {
        lock (peerLock) { return peers.Count; }
    }

    public string[] GetPeers()
    {
        List<string> l = new List<string>();
        lock (peerLock)
        {
            foreach (KeyValuePair<string, EarthTourneyPeer> kv in peers) l.Add(kv.Value.Id + "|" + kv.Value.Name + "|" + kv.Value.Ip + "|" + kv.Value.Version);
        }
        return l.ToArray();
    }

    private bool IsConnectedIp(string ip)
    {
        lock (peerLock)
        {
            foreach (KeyValuePair<string, EarthTourneyPeer> kv in peers) { if (kv.Value.Ip == ip) return true; }
        }
        return false;
    }

    private TcpClient TryConnect(string ip, int timeoutMs)
    {
        TcpClient c = new TcpClient(AddressFamily.InterNetwork);
        try
        {
            IAsyncResult ar = c.BeginConnect(IPAddress.Parse(ip), PortNumber, null, null);
            if (ar.AsyncWaitHandle.WaitOne(timeoutMs))
            {
                c.EndConnect(ar);
                return c;
            }
        }
        catch (Exception) { }
        try { c.Close(); } catch (Exception) { }
        return null;
    }

    private void StartOutgoing(TcpClient c)
    {
        EarthTourneyPeer p = new EarthTourneyPeer();
        p.Client = c;
        p.Outgoing = true;
        p.Ip = ((IPEndPoint)c.Client.RemoteEndPoint).Address.ToString();
        Thread t = new Thread(() => PeerLoop(p));
        t.IsBackground = true;
        t.Start();
    }

    public void ConnectTo(string ip)
    {
        Thread t = new Thread(() =>
        {
            IPAddress a;
            if (!IPAddress.TryParse(ip, out a)) { Events.Enqueue("SYS|Ungueltige Adresse: " + ip); return; }
            if (ip == BindIp) { Events.Enqueue("SYS|Das ist die eigene Adresse."); return; }
            if (IsConnectedIp(ip)) { Events.Enqueue("SYS|Bereits verbunden mit " + ip); return; }
            TcpClient c = TryConnect(ip, 2000);
            if (c == null) Events.Enqueue("SYS|Keine Verbindung zu " + ip + ":9877 (Option 4 dort nicht geoeffnet?)");
            else StartOutgoing(c);
        });
        t.IsBackground = true;
        t.Start();
    }

    public void ScanAsync(string[] ips)
    {
        if (ScanRunning) return;
        ScanRunning = true;
        scanCancel = false;
        ScanDone = 0;
        ScanTotal = ips.Length;
        Thread t = new Thread(() =>
        {
            try
            {
                int w, c2;
                ThreadPool.GetMinThreads(out w, out c2);
                if (w < 100) ThreadPool.SetMinThreads(100, c2);
                ParallelOptions po = new ParallelOptions();
                po.MaxDegreeOfParallelism = 48;
                Parallel.ForEach(ips, po, ip =>
                {
                    if (scanCancel || !running) return;
                    if (ip != BindIp && !IsConnectedIp(ip))
                    {
                        TcpClient c = TryConnect(ip, 600);
                        if (c != null) StartOutgoing(c);
                    }
                    Interlocked.Increment(ref ScanDone);
                });
            }
            catch (Exception) { }
            ScanRunning = false;
            Events.Enqueue("SCAN|done");
        });
        t.IsBackground = true;
        t.Start();
    }
}
'@

function Initialize-PelTourneyTypes {
    if (-not ('EarthTourneyNode' -as [type])) { Add-Type -TypeDefinition $script:PelTourneyCode -Language CSharp }
}

# ---- Grundlagen ---------------------------------------------------------------------
function Get-PelMmPlayerId {
    $set = Get-PelP2pSettings
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $h = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes([string]$set.MachineKey)) } finally { $sha.Dispose() }
    return ((($h | Select-Object -First 6) | ForEach-Object { $_.ToString('x2') }) -join '')
}

function ConvertTo-PelIpNumber([string]$Ip) {
    $a = $null
    if (-not [System.Net.IPAddress]::TryParse($Ip, [ref]$a)) { return [uint64]::MaxValue }
    $b = $a.GetAddressBytes()
    if ($b.Count -ne 4) { return [uint64]::MaxValue }
    return ([uint64]$b[0] -shl 24) + ([uint64]$b[1] -shl 16) + ([uint64]$b[2] -shl 8) + [uint64]$b[3]
}

# Koordinator = Teilnehmer mit der niedrigsten IP unter allen verbundenen Option-4-
# Fenstern (inklusive dem eigenen). Jeder berechnet das selbst - keine Wahl nötig; geht
# der Koordinator, übernimmt automatisch der nächste.
function Get-PelMmCoordinator {
    param([string]$SelfId, [string]$SelfIp, $Peers)
    $best = $SelfId
    $bestN = ConvertTo-PelIpNumber $SelfIp
    foreach ($p in @($Peers.Values)) {
        $n = ConvertTo-PelIpNumber ([string]$p.Ip)
        if ($n -lt $bestN -or ($n -eq $bestN -and [string]::CompareOrdinal([string]$p.Id, $best) -lt 0)) { $best = [string]$p.Id; $bestN = $n }
    }
    return $best
}

# Spielmodi: Need = Spieler je Match, Teams = 2 (Teamspiel) oder 0 (Jeder gegen jeden).
function Get-PelMmModes {
    return @(
        [pscustomobject]@{ Key = '1v1'; Label = '1 gegen 1'; Need = 2; Teams = 2 }
        [pscustomobject]@{ Key = '2v2'; Label = '2 gegen 2'; Need = 4; Teams = 2 }
        [pscustomobject]@{ Key = '3v3'; Label = '3 gegen 3'; Need = 6; Teams = 2 }
        [pscustomobject]@{ Key = '4v4'; Label = '4 gegen 4'; Need = 8; Teams = 2 }
        [pscustomobject]@{ Key = '5v5'; Label = '5 gegen 5'; Need = 10; Teams = 2 }
        [pscustomobject]@{ Key = 'ffa4'; Label = 'Jeder gegen jeden (4)'; Need = 4; Teams = 0 }
        [pscustomobject]@{ Key = 'ffa8'; Label = 'Jeder gegen jeden (8)'; Need = 8; Teams = 0 }
    )
}
function Get-PelMmMode([string]$Key) { return (Get-PelMmModes | Where-Object { $_.Key -eq $Key } | Select-Object -First 1) }

# Einheitlicher Schlüssel für "dasselbe Spiel" über PCs hinweg: die Join-Regel, wenn es
# eine eindeutige gibt (auf PC A "Call of Duty 4", auf PC B "COD4 Modern Warfare"),
# sonst der vereinheitlichte Name.
function Get-PelMmGameKey([string]$Name, [string]$RuleKey = '') {
    if (-not $RuleKey) { $RuleKey = Get-PelLibraryRuleKey $Name '' }
    if ($RuleKey -and $script:PelMmFamilyRules -notcontains $RuleKey) { return "r:$RuleKey" }
    $n = ConvertTo-PelNormName $Name
    if (-not $n) { return '' }
    return "n:$n"
}

# Liegt das Spiel mit diesem Schlüssel in der eigenen Bibliothek?
function Find-PelMmLibraryGame([string]$GameKey, [string]$GameName, $Library = $null) {
    if (-not $Library) { $Library = Get-PelGameLibrary }
    $rule = $null
    if ($GameKey -like 'r:*') { $rule = Get-PelRuleByKey $GameKey.Substring(2) }
    $hit = Find-PelLibraryGame -Rule $rule -GameName $GameName -Library $Library
    if ($hit) { return $hit }
    foreach ($g in @($Library.Games | Where-Object { -not $_.Hidden -and [System.IO.File]::Exists([string]$_.Exe) })) {
        if ((Get-PelMmGameKey ([string]$g.Name) ([string]$g.RuleKey)) -eq $GameKey) { return $g }
    }
    return $null
}

# ---- Wertung (Elo) --------------------------------------------------------------------
# Jeder Manager berechnet die Wertung selbst aus den bestätigten Ergebnissen - so haben
# alle dieselben Zahlen, ohne dass eine Stelle sie verwaltet. Start 1000, K = 40 für die
# ersten 10 Spiele eines Spielers, danach 24. Teamstärke = Durchschnitt der Mitglieder.
# Jeder gegen jeden fließt nicht in die Wertung ein (nur Teamspiele und 1 gegen 1).
function Get-PelMmRatings {
    param($Results, [string]$GameKey)
    $r = @{}
    $list = @($Results | Where-Object { $_.GameKey -eq $GameKey -and @($_.Teams).Count -eq 2 -and ([int]$_.Winner -ge -1 -and [int]$_.Winner -le 1) } | Sort-Object { [string]$_.Time })
    foreach ($res in $list) {
        $teams = @(@($res.Teams[0]), @($res.Teams[1]))
        if ($teams[0].Count -eq 0 -or $teams[1].Count -eq 0) { continue }
        foreach ($id in @($teams[0] + $teams[1])) { if (-not $r.ContainsKey([string]$id)) { $r[[string]$id] = @{ Rating = 1000.0; Games = 0 } } }
        $avg = @(0.0, 0.0)
        for ($ti = 0; $ti -lt 2; $ti++) {
            $sum = 0.0
            foreach ($id in $teams[$ti]) { $sum += $r[[string]$id].Rating }
            $avg[$ti] = $sum / $teams[$ti].Count
        }
        $w = [int]$res.Winner
        for ($ti = 0; $ti -lt 2; $ti++) {
            $opp = 1 - $ti
            $exp = 1.0 / (1.0 + [Math]::Pow(10.0, ($avg[$opp] - $avg[$ti]) / 400.0))
            $score = 0.5
            if ($w -eq $ti) { $score = 1.0 } elseif ($w -eq $opp) { $score = 0.0 }
            foreach ($id in $teams[$ti]) {
                $e = $r[[string]$id]
                $k = 24.0
                if ($e.Games -lt 10) { $k = 40.0 }
                $e.Rating = $e.Rating + $k * ($score - $exp)
                $e.Games = $e.Games + 1
            }
        }
    }
    return $r
}

function Get-PelMmRatingOf($Ratings, [string]$Id) {
    if ($Ratings.ContainsKey($Id)) { return [double]$Ratings[$Id].Rating }
    return 1000.0
}

# ---- Teambildung -----------------------------------------------------------------------
# Bis 10 Spieler: alle Aufteilungen prüfen (Spieler 1 fest in Team A, damit jede
# Aufteilung nur einmal vorkommt - bei 5 gegen 5 sind das 126), die mit der kleinsten
# Differenz der Wertungssummen gewinnt. Mehr Spieler: nach Wertung im Wechsel verteilen
# (Schlangenverfahren A B B A A B ...). -Random: einfach mischen.
function New-PelMmTeams {
    param([string[]]$Ids, $Ratings, [switch]$Random, [int]$Seed = 0)
    $n = $Ids.Count
    if ($n -lt 2) { return @(, @($Ids)) }
    $half = [int][Math]::Floor($n / 2)
    if ($Random) {
        $rng = if ($Seed) { New-Object System.Random($Seed) } else { New-Object System.Random }
        $shuf = @($Ids | Sort-Object { $rng.Next() })
        return @(, @($shuf[0..($half - 1)])) + @(, @($shuf[$half..($n - 1)]))
    }
    $rt = @($Ids | ForEach-Object { Get-PelMmRatingOf $Ratings $_ })
    if ($n -le 10) {
        $bestMask = -1
        $bestDiff = [double]::MaxValue
        $total = 0.0
        foreach ($x in $rt) { $total += $x }
        for ($mask = 1; $mask -lt (1 -shl $n); $mask += 2) {
            $cnt = 0; $sumA = 0.0
            for ($i = 0; $i -lt $n; $i++) { if ($mask -band (1 -shl $i)) { $cnt++; $sumA += $rt[$i] } }
            if ($cnt -ne $half) { continue }
            $diff = [Math]::Abs($total - 2 * $sumA)
            if ($diff -lt $bestDiff - 1e-9) { $bestDiff = $diff; $bestMask = $mask }
        }
        $a = New-Object System.Collections.Generic.List[string]
        $b = New-Object System.Collections.Generic.List[string]
        for ($i = 0; $i -lt $n; $i++) { if ($bestMask -band (1 -shl $i)) { $a.Add($Ids[$i]) } else { $b.Add($Ids[$i]) } }
        return @(, @($a.ToArray())) + @(, @($b.ToArray()))
    }
    $sorted = @(0..($n - 1) | Sort-Object { - $rt[$_] })
    $a = New-Object System.Collections.Generic.List[string]
    $b = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt $n; $i++) {
        $toA = (($i % 4) -eq 0 -or ($i % 4) -eq 3)
        if ($toA) { $a.Add($Ids[$sorted[$i]]) } else { $b.Add($Ids[$sorted[$i]]) }
    }
    return @(, @($a.ToArray())) + @(, @($b.ToArray()))
}

# ---- Ergebnisse (Datei) -----------------------------------------------------------------
function Get-PelMmResults {
    $list = New-Object System.Collections.Generic.List[object]
    try {
        if ([System.IO.File]::Exists($script:PelMmResultsPath)) {
            $j = Read-PelTextFile $script:PelMmResultsPath | ConvertFrom-Json
            foreach ($x in @($j.Results)) {
                if ($x -and $x.Id -and $x.GameKey) { $list.Add((ConvertTo-PelMmResult $x)) }
            }
        }
    } catch {
        Write-PelLog "Matchmaking-Ergebnisse nicht lesbar: $($_.Exception.Message)" 'WARN'
        try { Copy-Item -LiteralPath $script:PelMmResultsPath -Destination ("$($script:PelMmResultsPath).defekt_" + (Get-Date -Format 'yyyyMMdd_HHmmss')) -Force } catch { }
    }
    return $list
}

# Bringt ein empfangenes oder gelesenes Ergebnis in eine feste, geprüfte Form.
function ConvertTo-PelMmResult($x) {
    $teams = @()
    foreach ($t in @($x.Teams | Select-Object -First 16)) {
        $teams += , @(@($t) | Where-Object { [string]$_ -match '^[0-9a-f]{12}$' } | Select-Object -First 16 | ForEach-Object { [string]$_ })
    }
    $names = @{}
    if ($x.Names) {
        foreach ($p in $x.Names.PSObject.Properties) {
            if ($p.Name -match '^[0-9a-f]{12}$') { $names[$p.Name] = Limit-PelText ([string]$p.Value) 32 }
        }
    }
    $winner = 0
    [void][int]::TryParse([string]$x.Winner, [ref]$winner)
    return [pscustomobject]@{
        Id          = Limit-PelText ([string]$x.Id) 40
        Time        = Limit-PelText ([string]$x.Time) 25
        GameKey     = Limit-PelText ([string]$x.GameKey) 64
        Game        = Limit-PelText ([string]$x.Game) 80
        Mode        = Limit-PelText ([string]$x.Mode) 8
        Teams       = $teams
        Names       = $names
        Winner      = $winner
        WinnerId    = Limit-PelText ([string]$x.WinnerId) 12
        By          = Limit-PelText ([string]$x.By) 12
        ConfirmedBy = Limit-PelText ([string]$x.ConfirmedBy) 12
    }
}

function Save-PelMmResults($Results) {
    try {
        $keep = @($Results | Sort-Object { [string]$_.Time } | Select-Object -Last 2000)
        $root = [ordered]@{ Version = 1; Results = @($keep | ForEach-Object {
                    [ordered]@{
                        Id = $_.Id; Time = $_.Time; GameKey = $_.GameKey; Game = $_.Game; Mode = $_.Mode
                        Teams = @($_.Teams | ForEach-Object { , @($_) }); Names = $_.Names; Winner = $_.Winner
                        WinnerId = $_.WinnerId; By = $_.By; ConfirmedBy = $_.ConfirmedBy
                    }
                })
        }
        Write-PelTextFileAtomic $script:PelMmResultsPath (ConvertTo-Json -InputObject $root -Depth 6 -Compress)
        return $true
    } catch {
        Write-PelLog "Matchmaking-Ergebnisse konnten nicht gespeichert werden: $($_.Exception.Message)" 'ERROR'
        return $false
    }
}

function Get-PelMmSettings {
    $s = [pscustomobject]@{ CanHost = $false; RandomTeams = $false; AutoJoin = $false; LastGame = ''; LastMode = '2v2' }
    try {
        if ([System.IO.File]::Exists($script:PelMmSettingsPath)) {
            $j = Read-PelTextFile $script:PelMmSettingsPath | ConvertFrom-Json
            foreach ($k in @('CanHost', 'RandomTeams', 'AutoJoin')) { if ($null -ne $j.$k) { $s.$k = [bool]$j.$k } }
            if ($j.LastGame) { $s.LastGame = [string]$j.LastGame }
            if ($j.LastMode -and (Get-PelMmMode ([string]$j.LastMode))) { $s.LastMode = [string]$j.LastMode }
        }
    } catch { }
    return $s
}

function Save-PelMmSettings($Settings) {
    try { Write-PelTextFileAtomic $script:PelMmSettingsPath (ConvertTo-Json -InputObject $Settings) } catch { }
}

# ---- Zustand und Nachrichten ------------------------------------------------------------
# Der Zustand eines Option-4-Fensters. Koordinator-Teil (Q, Pending) wird nur genutzt,
# solange dieser PC Koordinator ist; der Spieler-Teil gilt immer.
function New-PelMmState {
    param([string]$MyId, [string]$MyName, [string]$MyIp)
    return @{
        MyId = $MyId; MyName = $MyName; MyIp = $MyIp
        Peers = @{}; Coord = $MyId
        Q = @{}; Pending = @{}; Rev = 0; LastStateSent = [datetime]::MinValue; Dirty = $true
        MyQueue = $null; LastQueueSent = [datetime]::MinValue
        State = $null; Proposal = $null; Matches = @{}
        Results = (New-Object System.Collections.Generic.List[object])
        Ui = (New-Object System.Collections.Generic.List[object])
    }
}

# Ausgehende Nachricht: To = Spieler-ID oder '*' (alle, inklusive sich selbst).
function New-PelMmOut([string]$To, [hashtable]$Msg) {
    $Msg['v'] = 1
    return [pscustomobject]@{ To = $To; Msg = $Msg }
}

function Get-PelMmName($Mm, [string]$Id) {
    if ($Id -eq $Mm.MyId) { return [string]$Mm.MyName }
    if ($Mm.Peers.ContainsKey($Id)) { return [string]$Mm.Peers[$Id].Name }
    return $Id
}

function Get-PelMmIpOf($Mm, [string]$Id) {
    if ($Id -eq $Mm.MyId) { return [string]$Mm.MyIp }
    if ($Mm.Peers.ContainsKey($Id)) { return [string]$Mm.Peers[$Id].Ip }
    return ''
}

function Update-PelMmCoordinator($Mm) {
    $old = $Mm.Coord
    $Mm.Coord = Get-PelMmCoordinator -SelfId $Mm.MyId -SelfIp $Mm.MyIp -Peers $Mm.Peers
    return ($old -ne $Mm.Coord)
}

# Spieler meldet sich (erneut) beim Koordinator. Wird alle 10 s wiederholt, damit ein
# neuer Koordinator die Warteschlange ohne eigenen Zustand wieder aufbauen kann.
function Get-PelMmQueueOut($Mm) {
    if (-not $Mm.MyQueue) { return @() }
    $q = $Mm.MyQueue
    $Mm.LastQueueSent = [datetime]::UtcNow
    return @(New-PelMmOut $Mm.Coord @{ t = 'MM_QUEUE'; game = $q.Game; key = $q.GameKey; mode = $q.Mode; rnd = [bool]$q.Random; host = [bool]$q.CanHost })
}

# Verarbeitet eine empfangene (oder an sich selbst gesendete) Nachricht. Gibt die daraus
# folgenden ausgehenden Nachrichten zurück; Hinweise für die Oberfläche landen in $Mm.Ui.
function Receive-PelMmMessage {
    param($Mm, [string]$From, $Msg, [datetime]$Now = [datetime]::UtcNow)
    $outs = New-Object System.Collections.Generic.List[object]
    if (-not $Msg -or -not $Msg.t) { return $outs }
    $isCoordMsg = @('MM_STATE', 'MM_PROPOSE', 'MM_CANCEL', 'MM_GO') -contains [string]$Msg.t
    if ($isCoordMsg -and $From -ne $Mm.Coord) { return $outs }
    $iAmCoord = ($Mm.Coord -eq $Mm.MyId)
    switch ([string]$Msg.t) {
        'INFO' {
            if ($Mm.Peers.ContainsKey($From)) {
                $p = $Mm.Peers[$From]
                $p.Games = @(@($Msg.games) | Select-Object -First 500 | ForEach-Object { Limit-PelText ([string]$_.k) 64 } | Where-Object { $_ })
                $p.CanHost = [bool]$Msg.host
                $Mm.Ui.Add(@{ Kind = 'peers' })
            }
        }
        'MM_QUEUE' {
            if (-not $iAmCoord) { break }
            $mode = Get-PelMmMode ([string]$Msg.mode)
            $key = Limit-PelText ([string]$Msg.key) 64
            if (-not $mode -or -not $key) { break }
            # Steckt der Spieler gerade in einem Bereit-Check: nur das Lebenszeichen
            # auffrischen (sonst würde er nach 25 s mitten im 30-s-Check entfernt).
            foreach ($pm in $Mm.Pending.Values) {
                if ($pm.Players -contains $From) {
                    foreach ($k in @($Mm.Q.Keys)) { foreach ($qe in @($Mm.Q[$k])) { if ($qe.Id -eq $From) { $qe.Seen = $Now } } }
                    return $outs
                }
            }
            $qk = "$key|$($mode.Key)"
            foreach ($k in @($Mm.Q.Keys)) {
                if ($k -ne $qk) {
                    $before = $Mm.Q[$k].Count
                    $Mm.Q[$k] = @($Mm.Q[$k] | Where-Object { $_.Id -ne $From })
                    if ($Mm.Q[$k].Count -ne $before) { $Mm.Dirty = $true }
                    if ($Mm.Q[$k].Count -eq 0) { $Mm.Q.Remove($k) }
                }
            }
            if (-not $Mm.Q.ContainsKey($qk)) { $Mm.Q[$qk] = @() }
            $entry = $Mm.Q[$qk] | Where-Object { $_.Id -eq $From } | Select-Object -First 1
            if ($entry) {
                $entry.Seen = $Now; $entry.Random = [bool]$Msg.rnd; $entry.CanHost = [bool]$Msg.host
            } else {
                $Mm.Q[$qk] = @($Mm.Q[$qk]) + @([pscustomobject]@{ Id = $From; Game = (Limit-PelText ([string]$Msg.game) 80); GameKey = $key; Mode = $mode.Key; Random = [bool]$Msg.rnd; CanHost = [bool]$Msg.host; Since = $Now; Seen = $Now })
                $Mm.Dirty = $true
            }
        }
        'MM_LEAVE' {
            if (-not $iAmCoord) { break }
            foreach ($k in @($Mm.Q.Keys)) {
                $before = $Mm.Q[$k].Count
                $Mm.Q[$k] = @($Mm.Q[$k] | Where-Object { $_.Id -ne $From })
                if ($Mm.Q[$k].Count -ne $before) { $Mm.Dirty = $true }
                if ($Mm.Q[$k].Count -eq 0) { $Mm.Q.Remove($k) }
            }
            foreach ($pm in @($Mm.Pending.Values)) { if ($pm.Players -contains $From) { $pm.Declined[$From] = $true } }
        }
        'MM_READY' {
            if (-not $iAmCoord) { break }
            $mid = [string]$Msg.match
            if (-not $Mm.Pending.ContainsKey($mid)) { break }
            $pm = $Mm.Pending[$mid]
            if ($pm.Players -notcontains $From) { break }
            if ([bool]$Msg.ready) { $pm.Ready[$From] = $true } else { $pm.Declined[$From] = $true }
            $pm.HasGame[$From] = [bool]$Msg.has
        }
        'MM_STATE' {
            $Mm.State = $Msg
            $Mm.Ui.Add(@{ Kind = 'state' })
        }
        'MM_PROPOSE' {
            $teams = @($Msg.teams)
            $all = @($teams | ForEach-Object { @($_) } | ForEach-Object { [string]$_ })
            if ($all -notcontains $Mm.MyId) { break }
            $Mm.Proposal = [pscustomobject]@{
                Match = Limit-PelText ([string]$Msg.match) 40; Game = Limit-PelText ([string]$Msg.game) 80; GameKey = Limit-PelText ([string]$Msg.key) 64
                Mode = [string]$Msg.mode; Teams = $teams; Names = $Msg.names; Deadline = $Now.AddSeconds([Math]::Min([Math]::Max([int]$Msg.secs, 5), 60))
            }
            $Mm.Ui.Add(@{ Kind = 'propose' })
        }
        'MM_CANCEL' {
            $mid = [string]$Msg.match
            if ($Mm.Proposal -and $Mm.Proposal.Match -eq $mid) { $Mm.Proposal = $null }
            $dropped = @(@($Msg.dropped) | ForEach-Object { [string]$_ })
            if ($dropped -contains $Mm.MyId) { $Mm.MyQueue = $null }
            $Mm.Ui.Add(@{ Kind = 'cancel'; Dropped = ($dropped -contains $Mm.MyId); Names = @($dropped | ForEach-Object { Get-PelMmName $Mm $_ }) })
        }
        'MM_GO' {
            $mid = Limit-PelText ([string]$Msg.match) 40
            $teams = @($Msg.teams)
            $all = @($teams | ForEach-Object { @($_) } | ForEach-Object { [string]$_ })
            if ($all -notcontains $Mm.MyId) { break }
            $hostId = [string]$Msg.hostId
            $ip = [string]$Msg.ip
            $port = 0
            [void][int]::TryParse([string]$Msg.port, [ref]$port)
            if ($port -lt 0 -or $port -gt 65535) { $port = 0 }
            # Die Adresse muss zu dem passen, was DIESER PC selbst über den Gastgeber weiß -
            # ein Koordinator kann so niemanden auf eine fremde Adresse schicken.
            if ($hostId -and ($ip -ne (Get-PelMmIpOf $Mm $hostId))) { $hostId = ''; $ip = '' }
            if (-not $hostId) { $ip = '' }
            $Mm.Proposal = $null
            $Mm.MyQueue = $null
            $names = @{}
            if ($Msg.names) { foreach ($p in $Msg.names.PSObject.Properties) { if ($p.Name -match '^[0-9a-f]{12}$') { $names[$p.Name] = Limit-PelText ([string]$p.Value) 32 } } }
            $Mm.Matches[$mid] = [pscustomobject]@{
                Match = $mid; Game = Limit-PelText ([string]$Msg.game) 80; GameKey = Limit-PelText ([string]$Msg.key) 64; Mode = [string]$Msg.mode
                Teams = @($teams | ForEach-Object { , @(@($_) | ForEach-Object { [string]$_ }) }); Names = $names
                HostId = $hostId; Ip = $ip; Port = $port; Time = $Now; Status = 'läuft'; Report = $null
            }
            $Mm.Ui.Add(@{ Kind = 'go'; Match = $mid })
        }
        'REPORT' {
            $mid = [string]$Msg.match
            if (-not $Mm.Matches.ContainsKey($mid)) { break }
            $m = $Mm.Matches[$mid]
            $all = @($m.Teams | ForEach-Object { @($_) })
            if ($all -notcontains $From) { break }
            $w = 0
            [void][int]::TryParse([string]$Msg.winner, [ref]$w)
            $m.Report = [pscustomobject]@{ By = $From; Winner = $w; WinnerId = [string]$Msg.winnerId }
            $m.Status = 'gemeldet'
            $Mm.Ui.Add(@{ Kind = 'report'; Match = $mid })
        }
        'REJECT' {
            $mid = [string]$Msg.match
            if (-not $Mm.Matches.ContainsKey($mid)) { break }
            $m = $Mm.Matches[$mid]
            if (@($m.Teams | ForEach-Object { @($_) }) -notcontains $From) { break }
            $m.Report = $null
            $m.Status = 'abgelehnt'
            $Mm.Ui.Add(@{ Kind = 'reject'; Match = $mid; By = (Get-PelMmName $Mm $From) })
        }
        'RESULT' {
            $res = ConvertTo-PelMmResult $Msg.result
            if (-not $res.Id -or -not $res.GameKey) { break }
            $all = @($res.Teams | ForEach-Object { @($_) })
            # Nur ein Teilnehmer des Matches darf das Ergebnis bestätigen, und nicht der,
            # der es gemeldet hat.
            if ($all -notcontains $From -or $res.ConfirmedBy -ne $From -or $res.By -eq $From) { break }
            if (@($Mm.Results | Where-Object { $_.Id -eq $res.Id }).Count -gt 0) { break }
            $Mm.Results.Add($res)
            if ($Mm.Matches.ContainsKey($res.Id)) { $Mm.Matches[$res.Id].Status = 'bestätigt' }
            $Mm.Ui.Add(@{ Kind = 'result'; Match = $res.Id })
        }
    }
    return $outs
}

# Koordinator-Takt (jede Sekunde, nur auf dem Koordinator): veraltete Einträge entfernen,
# Bereit-Checks auswerten, neue Matches vorschlagen, Warteschlangen an alle melden.
function Invoke-PelMmCoordinatorTick {
    param($Mm, [datetime]$Now = [datetime]::UtcNow, [int]$Seed = 0)
    $outs = New-Object System.Collections.Generic.List[object]
    if ($Mm.Coord -ne $Mm.MyId) { return $outs }
    $online = @{ $Mm.MyId = $true }
    foreach ($id in $Mm.Peers.Keys) { $online[$id] = $true }

    # 1. Einträge ohne Lebenszeichen (25 s) oder von getrennten Teilnehmern entfernen
    foreach ($k in @($Mm.Q.Keys)) {
        $before = @($Mm.Q[$k]).Count
        $Mm.Q[$k] = @($Mm.Q[$k] | Where-Object { $online.ContainsKey($_.Id) -and ($Now - $_.Seen).TotalSeconds -lt 25 })
        if ($Mm.Q[$k].Count -ne $before) { $Mm.Dirty = $true }
        if ($Mm.Q[$k].Count -eq 0) { $Mm.Q.Remove($k) }
    }

    # 2. Laufende Bereit-Checks
    foreach ($mid in @($Mm.Pending.Keys)) {
        $pm = $Mm.Pending[$mid]
        foreach ($id in $pm.Players) { if (-not $online.ContainsKey($id)) { $pm.Declined[$id] = $true } }
        $allReady = (@($pm.Players | Where-Object { -not $pm.Ready.ContainsKey($_) }).Count -eq 0)
        $failed = ($pm.Declined.Count -gt 0) -or ($Now -gt $pm.Deadline)
        if ($allReady -and $pm.Declined.Count -eq 0) {
            # Gastgeber: wer "Ich kann hosten" gewählt hat und das Spiel besitzt, sonst
            # irgendwer mit "Ich kann hosten"; findet sich niemand, einigen sich die
            # Spieler selbst (Adresse bleibt leer).
            $hostId = ''
            foreach ($id in $pm.Players) { if ($pm.CanHost[$id] -and $pm.HasGame[$id]) { $hostId = $id; break } }
            if (-not $hostId) { foreach ($id in $pm.Players) { if ($pm.CanHost[$id]) { $hostId = $id; break } } }
            $port = 0
            if ($pm.GameKey -like 'r:*') {
                $rule = Get-PelRuleByKey $pm.GameKey.Substring(2)
                if ($rule -and @($rule.Ports).Count -gt 0) { $port = [int](@($rule.Ports)[0]) }
            }
            $go = @{ t = 'MM_GO'; match = $mid; game = $pm.Game; key = $pm.GameKey; mode = $pm.Mode; teams = $pm.Teams; names = $pm.Names; hostId = $hostId; ip = $(if ($hostId) { Get-PelMmIpOf $Mm $hostId } else { '' }); port = $port }
            foreach ($id in $pm.Players) { $outs.Add((New-PelMmOut $id $go.Clone())) }
            # Die Spieler dieses Matches verlassen alle Warteschlangen.
            foreach ($k in @($Mm.Q.Keys)) {
                $Mm.Q[$k] = @($Mm.Q[$k] | Where-Object { $pm.Players -notcontains $_.Id })
                if ($Mm.Q[$k].Count -eq 0) { $Mm.Q.Remove($k) }
            }
            $Mm.Pending.Remove($mid)
            $Mm.Dirty = $true
        } elseif ($failed) {
            # Abgelehnt: nur wer abgelehnt hat (oder weg ist), fliegt raus - die anderen
            # hatten evtl. erst Sekunden Zeit. Zeit abgelaufen: auch wer nicht reagiert hat.
            # Alle übrigen bleiben vorne in der Warteschlange und kommen zuerst dran.
            $timedOut = ($Now -gt $pm.Deadline)
            $dropped = @($pm.Players | Where-Object { $pm.Declined.ContainsKey($_) -or ($timedOut -and -not $pm.Ready.ContainsKey($_)) })
            foreach ($k in @($Mm.Q.Keys)) {
                $Mm.Q[$k] = @($Mm.Q[$k] | Where-Object { $dropped -notcontains $_.Id })
                if ($Mm.Q[$k].Count -eq 0) { $Mm.Q.Remove($k) }
            }
            $cancel = @{ t = 'MM_CANCEL'; match = $mid; dropped = $dropped }
            foreach ($id in $pm.Players) { $outs.Add((New-PelMmOut $id $cancel.Clone())) }
            $Mm.Pending.Remove($mid)
            $Mm.Dirty = $true
        }
    }

    # 3. Neue Matches: genug freie Spieler in einer Warteschlange -> Bereit-Check
    $busy = @{}
    foreach ($pm in $Mm.Pending.Values) { foreach ($id in $pm.Players) { $busy[$id] = $true } }
    foreach ($k in @($Mm.Q.Keys)) {
        $entries = @($Mm.Q[$k] | Where-Object { -not $busy.ContainsKey($_.Id) } | Sort-Object { $_.Since })
        if ($entries.Count -eq 0) { continue }
        $mode = Get-PelMmMode $entries[0].Mode
        if (-not $mode -or $entries.Count -lt $mode.Need) { continue }
        $pick = @($entries | Select-Object -First $mode.Need)
        $ids = [string[]]@($pick | ForEach-Object { $_.Id })
        if ($mode.Teams -eq 2) {
            $ratings = Get-PelMmRatings -Results $Mm.Results -GameKey $entries[0].GameKey
            $wantRandom = (@($pick | Where-Object { $_.Random }).Count * 2) -gt $pick.Count
            $teams = New-PelMmTeams -Ids $ids -Ratings $ratings -Random:$wantRandom -Seed $Seed
        } else {
            $teams = @(, $ids)
        }
        $mid = ([guid]::NewGuid().ToString('N')).Substring(0, 12)
        $names = @{}
        foreach ($id in $ids) { $names[$id] = Get-PelMmName $Mm $id }
        $pm = [pscustomobject]@{
            Id = $mid; GameKey = $entries[0].GameKey; Game = $entries[0].Game; Mode = $mode.Key; Teams = $teams; Names = $names
            Players = $ids; Deadline = $Now.AddSeconds(30); Ready = @{}; Declined = @{}; HasGame = @{}; CanHost = @{}
        }
        foreach ($e in $pick) { $pm.CanHost[$e.Id] = [bool]$e.CanHost; $busy[$e.Id] = $true }
        $Mm.Pending[$mid] = $pm
        $prop = @{ t = 'MM_PROPOSE'; match = $mid; game = $pm.Game; key = $pm.GameKey; mode = $mode.Key; teams = $teams; names = $names; secs = 30 }
        foreach ($id in $ids) { $outs.Add((New-PelMmOut $id $prop.Clone())) }
        $Mm.Dirty = $true
    }

    # 4. Warteschlangen melden: bei Änderung sofort, sonst alle 5 s (für Neuankömmlinge)
    if ($Mm.Dirty -or ($Now - $Mm.LastStateSent).TotalSeconds -ge 5) {
        if ($Mm.Dirty) { $Mm.Rev++ }
        $Mm.Dirty = $false
        $Mm.LastStateSent = $Now
        $qs = @()
        foreach ($k in @($Mm.Q.Keys | Sort-Object)) {
            $e = @($Mm.Q[$k])
            if ($e.Count -eq 0) { continue }
            $mode = Get-PelMmMode $e[0].Mode
            $qs += , @{ game = $e[0].Game; key = $e[0].GameKey; mode = $e[0].Mode; need = $(if ($mode) { $mode.Need } else { 0 }); players = @($e | ForEach-Object { $_.Id }); names = @($e | ForEach-Object { Get-PelMmName $Mm $_.Id }) }
        }
        $outs.Add((New-PelMmOut '*' @{ t = 'MM_STATE'; rev = $Mm.Rev; queues = $qs; checks = $Mm.Pending.Count }))
    }
    return $outs
}
#endregion

# Firewall-Regeln für Option 4 (Präfix "Project Earth" -> Uninstall-PEL entfernt sie mit).
# Einmal anlegen und stehen lassen (wie beim Postfach), damit der erste Start nicht jedes
# Mal Regeln neu schreibt.
function Enable-PelMmFirewall {
    try {
        foreach ($proto in @('TCP', 'UDP')) {
            $name = "Project Earth LAN Turniere 9877 ($proto)"
            if (-not (Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue)) {
                New-NetFirewallRule -DisplayName $name -Direction Inbound -Action Allow -Protocol $proto -LocalPort $script:PelMmPort -RemoteAddress Any -Profile Any -ErrorAction Stop | Out-Null
            }
        }
    } catch {
        Write-PelLog "Firewall-Regel für Port 9877 konnte nicht angelegt werden: $($_.Exception.Message)" 'WARN'
    }
}

# ------------------------------------------------------------------------------
# OPTION 4: Turniere & Matchmaking
# ------------------------------------------------------------------------------
# Reiter "Matchmaking": Warteschlange je Spiel und Modus, faire Teams nach Wertung,
# Bereit-Check, Beitreten über die Spielebibliothek, Ergebnis melden und bestätigen.
# Reiter "Turniere": folgt mit dem nächsten Update.
# Alles läuft über den Dienst auf Port 9877 (siehe EarthTourneyNode). Der Koordinator
# (niedrigste IP) führt die Warteschlangen; jeder Manager rechnet die Wertung selbst.
# ---- Turnier-Planer (Option 4, Reiter "Turniere") ---------------------------------------
# Formate: K.-o. (mit Freilosen, falls die Teilnehmerzahl keine Zweierpotenz ist) und
# Jeder gegen jeden (Sieg 3 Punkte, Unentschieden 1, Niederlage 0).
# Wer ein Turnier anlegt, ist der Organisator: SEIN Manager hält den gültigen Stand und
# verteilt ihn an alle offenen Option-4-Fenster (TR_STATE). Alle anderen schicken nur
# Wünsche an ihn (anmelden, Ergebnis melden, bestätigen) - so gibt es genau eine Wahrheit.
# Ergebnisse zählen erst, wenn die Gegenseite bestätigt oder der Organisator sie einträgt.
# Vertrauen wie beim Matchmaking: Absender sind im P2P-Netz abgesichert, im normalen LAN
# setzt das Turnier voraus, dass man seinen Mitspielern traut.
# Gespeichert wird in C:\Project-Earth-Lan\matchmaking\turniere.json (auch für den
# Intranet-Block "Turnier (live)", Option 11).
$script:PelTrPath = 'C:\Project-Earth-Lan\matchmaking\turniere.json'
$script:PelTrMaxKo = 64
$script:PelTrMaxRr = 16

function New-PelTournament {
    param([string]$Name, [string]$GameKey, [string]$Game, [string]$Format, [int]$TeamSize, [string]$Owner, [string]$OwnerName)
    if ($Format -notin @('ko', 'rr')) { $Format = 'ko' }
    return [pscustomobject]@{
        Id = (New-PelIntranetId); Name = (Limit-PelText $Name 60); GameKey = (Limit-PelText $GameKey 64); Game = (Limit-PelText $Game 80)
        Format = $Format; TeamSize = [Math]::Max(1, [Math]::Min(5, $TeamSize)); Owner = $Owner; OwnerName = (Limit-PelText $OwnerName 40)
        State = 'signup'; Created = (Get-Date).ToString('yyyy-MM-ddTHH:mm:sszzz'); Rev = 1
        Signups = @(); Entrants = @(); Matches = @(); Champion = ''
    }
}

# Setzreihenfolge für einen Baum der Größe 2^k: 1 gegen die schwächste Position usw. -
# dadurch bekommen die Besten die Freilose und treffen erst spät aufeinander.
function Get-PelTrSeedOrder([int]$Size) {
    $order = @(1, 2)
    while ($order.Count -lt $Size) {
        $n = $order.Count * 2
        $next = New-Object System.Collections.Generic.List[int]
        foreach ($s in $order) { $next.Add($s); $next.Add($n + 1 - $s) }
        $order = $next.ToArray()
    }
    return $order
}

function Get-PelTrMatch($T, [string]$Id) { return (@($T.Matches) | Where-Object { $_.Id -eq $Id } | Select-Object -First 1) }
function Get-PelTrEntrant($T, [string]$Id) { return (@($T.Entrants) | Where-Object { $_.Id -eq $Id } | Select-Object -First 1) }

function Get-PelTrEntrantName($T, [string]$Id) {
    if ($Id -eq 'BYE') { return (Get-PelText 'Freilos' 'Bye') }
    if (-not $Id) { return '?' }
    $e = Get-PelTrEntrant $T $Id
    if ($e) { return [string]$e.Name }
    return '?'
}

function New-PelTrMatch([string]$Id, [int]$Round, [int]$Slot, [string]$A, [string]$B) {
    return [pscustomobject]@{ Id = $Id; Round = $Round; Slot = $Slot; A = $A; B = $B; Winner = ''; Reported = ''; ReportedBy = ''; Confirmed = $false; Next = ''; NextSide = '' }
}

# Teams bilden: nach Wertung im Schlangenverfahren (1-2-3-3-2-1 ...), sonst gemischt.
# Wer bei ungerader Aufteilung übrig bleibt, wird nicht eingeteilt (Rückgabe .Rest).
function New-PelTrTeams {
    param($Signups, [int]$Size, $Ratings, [switch]$Random)
    $list = @($Signups)
    $count = [int][Math]::Floor($list.Count / $Size)
    $teams = @()
    if ($count -lt 1) { return [pscustomobject]@{ Teams = @(); Rest = $list } }
    if ($Random) { $sorted = @($list | Sort-Object { Get-Random }) }
    else { $sorted = @($list | Sort-Object @{ Expression = { Get-PelMmRatingOf $Ratings ([string]$_.Id) }; Descending = $true }, Name) }
    $use = $sorted[0..($count * $Size - 1)]
    $rest = @()
    if ($sorted.Count -gt $count * $Size) { $rest = $sorted[($count * $Size)..($sorted.Count - 1)] }
    $buckets = @()
    for ($i = 0; $i -lt $count; $i++) { $buckets += , (New-Object System.Collections.Generic.List[object]) }
    for ($i = 0; $i -lt $use.Count; $i++) {
        $round = [int][Math]::Floor($i / $count)
        $pos = $i % $count
        if ($round % 2 -eq 1) { $pos = $count - 1 - $pos }
        $buckets[$pos].Add($use[$i])
    }
    foreach ($b in $buckets) { $teams += , @($b.ToArray()) }
    return [pscustomobject]@{ Teams = $teams; Rest = @($rest) }
}

# Startet das Turnier: Teilnehmer (bzw. Teams) festlegen, setzen, Spiele erzeugen.
# Rückgabe: $null bei Erfolg, sonst ein Fehlertext für die Anzeige.
function Start-PelTournament {
    param($T, $Ratings, [switch]$RandomTeams, [switch]$RandomSeed)
    if ($T.State -ne 'signup') { return (Get-PelText 'Das Turnier läuft bereits.' 'The tournament is already running.') }
    if (-not $Ratings) { $Ratings = @{} }
    $entrants = New-Object System.Collections.Generic.List[object]
    $n = 0
    if ($T.TeamSize -le 1) {
        foreach ($s in @($T.Signups)) {
            $n++
            $entrants.Add([pscustomobject]@{ Id = "e$n"; Name = [string]$s.Name; Members = @([string]$s.Id); MemberNames = @([string]$s.Name) })
        }
    } else {
        $tm = New-PelTrTeams -Signups $T.Signups -Size $T.TeamSize -Ratings $Ratings -Random:$RandomTeams
        foreach ($team in @($tm.Teams)) {
            $n++
            $names = @($team | ForEach-Object { [string]$_.Name })
            $entrants.Add([pscustomobject]@{ Id = "e$n"; Name = ((Get-PelText 'Team {0}' 'Team {0}') -f $names[0]); Members = @($team | ForEach-Object { [string]$_.Id }); MemberNames = $names })
        }
    }
    $max = $script:PelTrMaxKo
    if ($T.Format -eq 'rr') { $max = $script:PelTrMaxRr }
    if ($entrants.Count -lt 2) { return (Get-PelText 'Zu wenige Teilnehmer - es braucht mindestens 2 (bei Teams: genug Spieler für 2 Teams).' 'Not enough participants - at least 2 are needed (for teams: enough players for 2 teams).') }
    if ($entrants.Count -gt $max) { return ((Get-PelText 'Zu viele Teilnehmer für dieses Format (höchstens {0}).' 'Too many participants for this format (at most {0}).') -f $max) }

    # Setzen: nach Wertung (Durchschnitt der Mitglieder) oder zufällig
    $strength = @{}
    foreach ($e in $entrants) {
        $sum = 0.0
        foreach ($m in @($e.Members)) { $sum += Get-PelMmRatingOf $Ratings ([string]$m) }
        $strength[$e.Id] = $sum / [Math]::Max(1, @($e.Members).Count)
    }
    if ($RandomSeed) { $seeded = @($entrants | Sort-Object { Get-Random }) }
    else { $seeded = @($entrants | Sort-Object @{ Expression = { $strength[$_.Id] }; Descending = $true }, Name) }
    $T.Entrants = $seeded

    $matches = New-Object System.Collections.Generic.List[object]
    if ($T.Format -eq 'ko') {
        $size = 2
        while ($size -lt $seeded.Count) { $size *= 2 }
        $rounds = [int][Math]::Round([Math]::Log($size, 2))
        $order = Get-PelTrSeedOrder $size
        for ($r = 1; $r -le $rounds; $r++) {
            $cnt = $size / [Math]::Pow(2, $r)
            for ($s = 1; $s -le $cnt; $s++) {
                $a = ''; $b = ''
                if ($r -eq 1) {
                    $sa = $order[($s - 1) * 2]; $sb = $order[($s - 1) * 2 + 1]
                    if ($sa -le $seeded.Count) { $a = $seeded[$sa - 1].Id } else { $a = 'BYE' }
                    if ($sb -le $seeded.Count) { $b = $seeded[$sb - 1].Id } else { $b = 'BYE' }
                }
                $m = New-PelTrMatch "r$($r)m$s" $r $s $a $b
                if ($r -lt $rounds) {
                    $m.Next = "r$($r + 1)m$([int][Math]::Ceiling($s / 2))"
                    if ($s % 2 -eq 1) { $m.NextSide = 'A' } else { $m.NextSide = 'B' }
                }
                $matches.Add($m)
            }
        }
    } else {
        # Rundenturnier nach dem Kreisverfahren; bei ungerader Zahl hat jede Runde ein Freilos
        $ids = New-Object System.Collections.Generic.List[string]
        foreach ($e in $seeded) { $ids.Add($e.Id) }
        if ($ids.Count % 2 -eq 1) { $ids.Add('BYE') }
        $cnt = $ids.Count
        $arr = $ids.ToArray()
        for ($r = 1; $r -lt $cnt; $r++) {
            $slot = 0
            for ($i = 0; $i -lt $cnt / 2; $i++) {
                $a = $arr[$i]; $b = $arr[$cnt - 1 - $i]
                if ($a -eq 'BYE' -or $b -eq 'BYE') { continue }
                $slot++
                if ($r % 2 -eq 0) { $tmp = $a; $a = $b; $b = $tmp }
                $matches.Add((New-PelTrMatch "r$($r)m$slot" $r $slot $a $b))
            }
            # alle außer dem ersten eine Position weiterdrehen
            $last = $arr[$cnt - 1]
            for ($k = $cnt - 1; $k -gt 1; $k--) { $arr[$k] = $arr[$k - 1] }
            $arr[1] = $last
        }
    }
    $T.Matches = $matches.ToArray()
    $T.State = 'running'
    Update-PelTrProgress $T
    $T.Rev = [int]$T.Rev + 1
    return $null
}

# Trägt Sieger in die nächste Runde ein, erledigt Freilose und prüft, ob das Turnier fertig ist.
function Update-PelTrProgress($T) {
    if ($T.State -eq 'signup') { return }
    $changed = $true
    $guard = 0
    while ($changed -and $guard -lt 200) {
        $changed = $false
        $guard++
        foreach ($m in @($T.Matches)) {
            if (-not $m.Confirmed -and $m.A -and $m.B) {
                if ($m.A -eq 'BYE' -and $m.B -ne 'BYE') { $m.Winner = 'B'; $m.Confirmed = $true; $changed = $true }
                elseif ($m.B -eq 'BYE' -and $m.A -ne 'BYE') { $m.Winner = 'A'; $m.Confirmed = $true; $changed = $true }
            }
            if ($T.Format -eq 'ko' -and $m.Confirmed -and $m.Next -and $m.Winner -in @('A', 'B')) {
                $win = if ($m.Winner -eq 'A') { $m.A } else { $m.B }
                $nx = Get-PelTrMatch $T $m.Next
                if ($nx) {
                    if ($m.NextSide -eq 'A' -and $nx.A -ne $win) { $nx.A = $win; $changed = $true }
                    if ($m.NextSide -eq 'B' -and $nx.B -ne $win) { $nx.B = $win; $changed = $true }
                }
            }
        }
    }
    $T.Champion = ''
    if ($T.Format -eq 'ko') {
        $final = @($T.Matches) | Where-Object { -not $_.Next } | Select-Object -First 1
        if ($final -and $final.Confirmed -and $final.Winner -in @('A', 'B')) {
            $T.Champion = if ($final.Winner -eq 'A') { $final.A } else { $final.B }
        }
    } elseif (@($T.Matches).Count -gt 0 -and -not (@($T.Matches) | Where-Object { -not $_.Confirmed })) {
        $top = @(Get-PelTrStandings $T) | Select-Object -First 1
        if ($top) { $T.Champion = $top.Id }
    }
    if ($T.Champion) { $T.State = 'done' } else { $T.State = 'running' }
}

# Ergebnis setzen. -Final: gilt sofort (Organisator oder bestätigt), sonst nur "gemeldet".
function Set-PelTrResult {
    param($T, [string]$MatchId, [string]$Winner, [string]$By, [switch]$Final)
    $m = Get-PelTrMatch $T $MatchId
    if (-not $m) { return $false }
    if ($Winner -notin @('A', 'B', 'D')) { return $false }
    if ($Winner -eq 'D' -and $T.Format -eq 'ko') { return $false }
    if (-not $m.A -or -not $m.B -or $m.A -eq 'BYE' -or $m.B -eq 'BYE') { return $false }
    if ($Final) {
        # Ein bereits bestätigtes K.-o.-Spiel darf nur geändert werden, solange der Sieger
        # in der nächsten Runde noch nicht gespielt hat.
        if ($m.Confirmed -and $T.Format -eq 'ko' -and $m.Next) {
            $nx = Get-PelTrMatch $T $m.Next
            if ($nx -and $nx.Confirmed) { return $false }
            if ($nx -and $m.Winner -ne $Winner) { if ($m.NextSide -eq 'A') { $nx.A = '' } else { $nx.B = '' }; $nx.Reported = ''; $nx.ReportedBy = '' }
        }
        $m.Winner = $Winner; $m.Confirmed = $true; $m.Reported = ''; $m.ReportedBy = ''
    } else {
        if ($m.Confirmed) { return $false }
        $m.Reported = $Winner; $m.ReportedBy = $By
    }
    Update-PelTrProgress $T
    $T.Rev = [int]$T.Rev + 1
    return $true
}

# Auf welcher Seite spielt dieser Spieler in diesem Spiel? 'A', 'B' oder ''
function Get-PelTrSide($T, $Match, [string]$PlayerId) {
    foreach ($side in @('A', 'B')) {
        $e = Get-PelTrEntrant $T ([string]$Match.$side)
        if ($e -and @($e.Members) -contains $PlayerId) { return $side }
    }
    return ''
}

function Get-PelTrStandings($T) {
    $tab = @{}
    foreach ($e in @($T.Entrants)) { $tab[$e.Id] = [pscustomobject]@{ Id = $e.Id; Name = $e.Name; Played = 0; Won = 0; Draw = 0; Lost = 0; Points = 0 } }
    foreach ($m in @($T.Matches)) {
        if (-not $m.Confirmed -or -not $tab.ContainsKey([string]$m.A) -or -not $tab.ContainsKey([string]$m.B)) { continue }
        $a = $tab[$m.A]; $b = $tab[$m.B]
        $a.Played++; $b.Played++
        switch ($m.Winner) {
            'A' { $a.Won++; $a.Points += 3; $b.Lost++ }
            'B' { $b.Won++; $b.Points += 3; $a.Lost++ }
            'D' { $a.Draw++; $b.Draw++; $a.Points++; $b.Points++ }
        }
    }
    return @($tab.Values | Sort-Object @{ Expression = 'Points'; Descending = $true }, @{ Expression = 'Won'; Descending = $true }, Name)
}

function Get-PelTrRoundName($T, [int]$Round) {
    if ($T.Format -eq 'ko') {
        $max = (@($T.Matches) | Measure-Object -Property Round -Maximum).Maximum
        switch ([int]$max - $Round) {
            0 { return (Get-PelText 'Finale' 'Final') }
            1 { return (Get-PelText 'Halbfinale' 'Semi-final') }
            2 { return (Get-PelText 'Viertelfinale' 'Quarter-final') }
            3 { return (Get-PelText 'Achtelfinale' 'Round of 16') }
        }
    }
    return ((Get-PelText 'Runde {0}' 'Round {0}') -f $Round)
}

function Get-PelTrStateText($T) {
    switch ($T.State) {
        'signup' { return (Get-PelText 'Anmeldung offen' 'Sign-up open') }
        'running' { return (Get-PelText 'läuft' 'running') }
        'done' { return (Get-PelText 'beendet' 'finished') }
    }
    return ''
}

function Get-PelTrFormatText($T) {
    $f = Get-PelText 'K.-o.' 'Knockout'
    if ($T.Format -eq 'rr') { $f = Get-PelText 'Jeder gegen jeden' 'Round robin' }
    if ([int]$T.TeamSize -gt 1) { $f += ', ' + ('{0} gegen {0}' -f $T.TeamSize) }
    return $f
}

# Textübersicht (Turnierbaum bzw. Tabelle) - für das Fenster und das Intranet
function Format-PelTrOverview($T) {
    $sb = New-Object System.Text.StringBuilder
    if ($T.State -eq 'signup') {
        [void]$sb.AppendLine(((Get-PelText 'Anmeldung offen - {0} angemeldet.' 'Sign-up open - {0} registered.') -f @($T.Signups).Count))
        return $sb.ToString()
    }
    if ($T.Champion) { [void]$sb.AppendLine(((Get-PelText 'Sieger: {0}' 'Winner: {0}') -f (Get-PelTrEntrantName $T $T.Champion))); [void]$sb.AppendLine() }
    if ($T.Format -eq 'rr') {
        [void]$sb.AppendLine(('{0,-3} {1,-24} {2,3} {3,3} {4,3} {5,3} {6,5}' -f '#', (Get-PelText 'Teilnehmer' 'Participant'), 'Sp', 'S', 'U', 'N', (Get-PelText 'Pkt' 'Pts')))
        $i = 0
        foreach ($s in @(Get-PelTrStandings $T)) {
            $i++
            $nm = [string]$s.Name
            if ($nm.Length -gt 24) { $nm = $nm.Substring(0, 24) }
            [void]$sb.AppendLine(('{0,-3} {1,-24} {2,3} {3,3} {4,3} {5,3} {6,5}' -f $i, $nm, $s.Played, $s.Won, $s.Draw, $s.Lost, $s.Points))
        }
        return $sb.ToString()
    }
    foreach ($r in @(@($T.Matches) | ForEach-Object { [int]$_.Round } | Sort-Object -Unique)) {
        [void]$sb.AppendLine((Get-PelTrRoundName $T $r))
        foreach ($m in @(@($T.Matches) | Where-Object { [int]$_.Round -eq $r } | Sort-Object Slot)) {
            if ($m.A -eq 'BYE' -or $m.B -eq 'BYE') { continue }
            $a = Get-PelTrEntrantName $T $m.A; $b = Get-PelTrEntrantName $T $m.B
            if (-not $m.A) { $a = '...' }; if (-not $m.B) { $b = '...' }
            $res = ''
            if ($m.Confirmed -and $m.Winner -eq 'A') { $res = '  ->  ' + $a }
            elseif ($m.Confirmed -and $m.Winner -eq 'B') { $res = '  ->  ' + $b }
            [void]$sb.AppendLine(('  {0}  vs.  {1}{2}' -f $a, $b, $res))
        }
    }
    return $sb.ToString()
}

# Prüft ein Turnier aus dem Netz oder aus der Datei und bringt es in eine feste Form.
function Repair-PelTournament($x) {
    if (-not $x -or [string]$x.Id -notmatch '^[a-z0-9]{4,16}$' -or [string]$x.Owner -notmatch '^[0-9a-f]{12}$') { return $null }
    $t = New-PelTournament -Name ([string]$x.Name) -GameKey ([string]$x.GameKey) -Game ([string]$x.Game) -Format ([string]$x.Format) -TeamSize ([int]$x.TeamSize) -Owner ([string]$x.Owner) -OwnerName ([string]$x.OwnerName)
    $t.Id = [string]$x.Id
    if ([string]$x.State -in @('signup', 'running', 'done')) { $t.State = [string]$x.State }
    $t.Created = Limit-PelText ([string]$x.Created) 30
    $rev = 0; [void][int]::TryParse([string]$x.Rev, [ref]$rev); $t.Rev = $rev
    $t.Signups = @(@($x.Signups) | Select-Object -First 128 | Where-Object { $_ -and [string]$_.Id -match '^[0-9a-z]{4,16}$' } | ForEach-Object { [pscustomobject]@{ Id = [string]$_.Id; Name = (Limit-PelText ([string]$_.Name) 32) } })
    $ids = @{}
    $t.Entrants = @(@($x.Entrants) | Select-Object -First $script:PelTrMaxKo | Where-Object { $_ -and [string]$_.Id -match '^e\d{1,3}$' } | ForEach-Object {
            $ids[[string]$_.Id] = $true
            [pscustomobject]@{ Id = [string]$_.Id; Name = (Limit-PelText ([string]$_.Name) 40); Members = @(@($_.Members) | Select-Object -First 5 | ForEach-Object { Limit-PelText ([string]$_) 16 }); MemberNames = @(@($_.MemberNames) | Select-Object -First 5 | ForEach-Object { Limit-PelText ([string]$_) 32 }) }
        })
    $okSide = { param($v) ($v -eq '' -or $v -eq 'BYE' -or $ids.ContainsKey($v)) }
    $t.Matches = @(@($x.Matches) | Select-Object -First 200 | Where-Object { $_ -and [string]$_.Id -match '^r\d{1,3}m\d{1,3}$' -and (& $okSide ([string]$_.A)) -and (& $okSide ([string]$_.B)) } | ForEach-Object {
            $m = New-PelTrMatch ([string]$_.Id) ([int]$_.Round) ([int]$_.Slot) ([string]$_.A) ([string]$_.B)
            if ([string]$_.Winner -in @('A', 'B', 'D')) { $m.Winner = [string]$_.Winner }
            if ([string]$_.Reported -in @('A', 'B', 'D')) { $m.Reported = [string]$_.Reported }
            $m.ReportedBy = Limit-PelText ([string]$_.ReportedBy) 16
            $m.Confirmed = [bool]$_.Confirmed
            if ([string]$_.Next -match '^r\d{1,3}m\d{1,3}$') { $m.Next = [string]$_.Next }
            if ([string]$_.NextSide -in @('A', 'B')) { $m.NextSide = [string]$_.NextSide }
            $m
        })
    if ([string]$x.Champion -and $ids.ContainsKey([string]$x.Champion)) { $t.Champion = [string]$x.Champion }
    return $t
}

function Get-PelTournaments {
    $list = New-Object System.Collections.Generic.List[object]
    try {
        if ([System.IO.File]::Exists($script:PelTrPath)) {
            foreach ($x in @(Read-PelTextFile $script:PelTrPath | ConvertFrom-Json)) { $t = Repair-PelTournament $x; if ($t) { $list.Add($t) } }
        }
    } catch { Write-PelLog "Turniere nicht lesbar: $($_.Exception.Message)" 'WARN' }
    # Komma: die Liste als Ganzes zurückgeben (sonst macht PowerShell ein Array daraus)
    return , $list
}

function Save-PelTournaments($List) {
    try {
        $dir = Split-Path -Parent $script:PelTrPath
        if (-not [System.IO.Directory]::Exists($dir)) { [void][System.IO.Directory]::CreateDirectory($dir) }
        $keep = @($List | Sort-Object { [string]$_.Created } | Select-Object -Last 30)
        $json = '[]'
        if ($keep.Count -gt 0) { $json = ConvertTo-Json -InputObject $keep -Depth 6 -Compress }
        Write-PelTextFileAtomic $script:PelTrPath $json
    } catch { Write-PelLog "Turniere konnten nicht gespeichert werden: $($_.Exception.Message)" 'ERROR' }
}

