    $lvTrMatches = & $mkList $tabTr 400 244 600 176 'Top,Bottom,Left,Right' @((Get-PelText 'Runde' 'Round'), 110, (Get-PelText 'Paarung' 'Pairing'), 290, (Get-PelText 'Stand' 'Status'), 190)
