    $btnTrWinB = & $mkBtn $tabTr (Get-PelText 'Sieg rechts' 'Right wins') 542 426 136 $cBtn 'Bottom,Left'
    $btnTrDraw = & $mkBtn $tabTr (Get-PelText 'Unentschieden' 'Draw') 684 426 110 $cBtn 'Bottom,Left'
    $btnTrConfirm = & $mkBtn $tabTr (Get-PelText 'Bestätigen' 'Confirm') 800 426 104 $cGreen 'Bottom,Left'
    $btnTrReject = & $mkBtn $tabTr (Get-PelText 'Ablehnen' 'Reject') 910 426 90 $cRed 'Bottom,Left'
    $btnTrPlay = & $mkBtn $tabTr (Get-PelText 'Spiel starten' 'Start game') 400 466 140 $cBtn 'Bottom,Left'
    $lblTrHint = & $mkLabel $tabTr '' 548 473 452 22
    $lblTrHint.Anchor = 'Bottom,Left,Right'
    $lblTrHint.ForeColor = $cQuiet
    $rtbTr = New-Object System.Windows.Forms.RichTextBox
    $rtbTr.Location = New-Object System.Drawing.Point(400, 506)
    $rtbTr.Size = New-Object System.Drawing.Size(600, 108)
    $rtbTr.Anchor = 'Bottom,Left,Right'
    $rtbTr.ReadOnly = $true
    $rtbTr.BackColor = $cList
    $rtbTr.ForeColor = [System.Drawing.Color]::White
    $rtbTr.BorderStyle = 'FixedSingle'
    $rtbTr.Font = New-Object System.Drawing.Font('Consolas', 9)
