    function Get-PelTrSelected {
        if ($lvTr.SelectedItems.Count -eq 0) { return $null }
        $id = [string]$lvTr.SelectedItems[0].Tag
        return ($tr.List | Where-Object { $_.Id -eq $id } | Select-Object -First 1)
    }
    function Get-PelTrSelectedMatch($T) {
        if (-not $T -or $lvTrMatches.SelectedItems.Count -eq 0) { return $null }
        return (Get-PelTrMatch $T ([string]$lvTrMatches.SelectedItems[0].Tag))
    }
    function Test-PelTrOwner($T) { return ($T -and $ui.Mm -and $T.Owner -eq $ui.Mm.MyId) }

    function Send-PelTrState($T, [string]$To = '*') {
        if (-not $ui.Node -or -not $T) { return }
        $json = ConvertTo-Json -InputObject @{ t = 'TR_STATE'; v = 1; tr = $T } -Depth 8 -Compress
        if ($To -eq '*') { [void]$ui.Node.Broadcast($json) } else { [void]$ui.Node.SendTo($To, $json) }
    }
    function Send-PelTrOwnStates([string]$To = '*') {
        if (-not $ui.Mm) { return }
        foreach ($t in @($tr.List | Where-Object { $_.Owner -eq $ui.Mm.MyId } | Sort-Object { [string]$_.Created } | Select-Object -Last 5)) { Send-PelTrState $t $To }
    }
    # Änderung am eigenen Turnier: speichern, an alle verteilen, anzeigen
    function Complete-PelTrChange($T) {
        Save-PelTournaments $tr.List
        Send-PelTrState $T '*'
        Update-PelTrView
    }
    # Wunsch an den Organisator; ist man es selbst, wird er direkt hier verarbeitet
    function Send-PelTrRequest($T, [hashtable]$Msg) {
        $Msg['v'] = 1
        $Msg['id'] = $T.Id
        if (Test-PelTrOwner $T) { Receive-PelTrMessage $ui.Mm.MyId (ConvertTo-Json -InputObject $Msg -Compress | ConvertFrom-Json); return }
        if (-not $ui.Node -or -not $ui.Mm.Peers.ContainsKey($T.Owner)) {
            Show-PelMsg ((Get-PelText "Der Organisator ({0}) ist gerade nicht verbunden. Sein Option-4-Fenster muss offen sein." "The organizer ({0}) is not connected right now. Their option 4 window has to be open.") -f $T.OwnerName) (Get-PelText 'Turniere' 'Tournaments') ([System.Windows.Forms.MessageBoxIcon]::Information) $form
            return
        }
        [void]$ui.Node.SendTo($T.Owner, (ConvertTo-Json -InputObject $Msg -Compress))
        $lblTrHint.Text = Get-PelText 'Gesendet - der Stand kommt gleich vom Organisator.' 'Sent - the organizer will update the status shortly.'
    }

    function Receive-PelTrMessage([string]$From, $M) {
        $kind = [string]$M.t
        if ($kind -eq 'TR_STATE') {
            $x = Repair-PelTournament $M.tr
            if (-not $x -or $x.Owner -ne $From -or $From -eq $ui.Mm.MyId) { return }
            $old = $tr.List | Where-Object { $_.Id -eq $x.Id } | Select-Object -First 1
            if ($old -and ($old.Owner -ne $From -or [int]$x.Rev -le [int]$old.Rev)) { return }
            if ($old) { [void]$tr.List.Remove($old) }
            $tr.List.Add($x)
            Save-PelTournaments $tr.List
            Update-PelTrView
            return
        }
        $t = $tr.List | Where-Object { $_.Id -eq [string]$M.id } | Select-Object -First 1
        if (-not $t) { return }
        if ($kind -eq 'TR_DELETE') {
            if ($t.Owner -eq $From -and $From -ne $ui.Mm.MyId) { [void]$tr.List.Remove($t); Save-PelTournaments $tr.List; Update-PelTrView }
            return
        }
        # Alles Weitere entscheidet nur der Organisator
        if (-not (Test-PelTrOwner $t)) { return }
        $who = $ui.Mm.MyName
        if ($From -ne $ui.Mm.MyId) { if (-not $ui.Mm.Peers.ContainsKey($From)) { return }; $who = [string]$ui.Mm.Peers[$From].Name }
        switch ($kind) {
            'TR_SIGNUP' {
                if ($t.State -ne 'signup' -or @($t.Signups | Where-Object { $_.Id -eq $From }).Count -gt 0 -or @($t.Signups).Count -ge 128) { return }
                $t.Signups = @($t.Signups) + @([pscustomobject]@{ Id = $From; Name = (Limit-PelText $who 32) })
                $t.Rev = [int]$t.Rev + 1
                Add-PelMmLog ((Get-PelText 'Turnier {0}: {1} hat sich angemeldet.' 'Tournament {0}: {1} signed up.') -f $t.Name, $who) ([System.Drawing.Color]::LightGreen)
            }
            'TR_WITHDRAW' {
                if ($t.State -ne 'signup') { return }
                $t.Signups = @($t.Signups | Where-Object { $_.Id -ne $From })
                $t.Rev = [int]$t.Rev + 1
            }
            'TR_REPORT' {
                $m = Get-PelTrMatch $t ([string]$M.match)
                if (-not $m -or $m.Confirmed) { return }
                if (-not (Get-PelTrSide $t $m $From)) { return }
                if (-not (Set-PelTrResult -T $t -MatchId $m.Id -Winner ([string]$M.w) -By $From)) { return }
                Add-PelMmLog ((Get-PelText 'Turnier {0}: {1} hat ein Ergebnis gemeldet.' 'Tournament {0}: {1} reported a result.') -f $t.Name, $who) ([System.Drawing.Color]::LightGray)
            }
            'TR_CONFIRM' {
                $m = Get-PelTrMatch $t ([string]$M.match)
                if (-not $m -or $m.Confirmed -or -not $m.Reported) { return }
                $side = Get-PelTrSide $t $m $From
                if (-not $side -or $side -eq (Get-PelTrSide $t $m $m.ReportedBy)) { return }
                if (-not (Set-PelTrResult -T $t -MatchId $m.Id -Winner $m.Reported -By $From -Final)) { return }
            }
            'TR_REJECT' {
                $m = Get-PelTrMatch $t ([string]$M.match)
                if (-not $m -or $m.Confirmed -or -not $m.Reported) { return }
                $side = Get-PelTrSide $t $m $From
                if (-not $side -or $side -eq (Get-PelTrSide $t $m $m.ReportedBy)) { return }
                $m.Reported = ''; $m.ReportedBy = ''
                $t.Rev = [int]$t.Rev + 1
            }
            default { return }
        }
        Complete-PelTrChange $t
    }

    function Get-PelTrMatchStatus($T, $M) {
        if ($M.Confirmed) {
            switch ($M.Winner) {
                'A' { return ((Get-PelText 'Sieg {0}' '{0} won') -f (Get-PelTrEntrantName $T $M.A)) }
                'B' { return ((Get-PelText 'Sieg {0}' '{0} won') -f (Get-PelTrEntrantName $T $M.B)) }
                'D' { return (Get-PelText 'Unentschieden' 'Draw') }
            }
        }
        if (-not $M.A -or -not $M.B) { return (Get-PelText 'wartet auf Gegner' 'waiting for opponent') }
        if ($M.Reported) {
            $w = Get-PelText 'Unentschieden' 'draw'
            if ($M.Reported -eq 'A') { $w = Get-PelTrEntrantName $T $M.A } elseif ($M.Reported -eq 'B') { $w = Get-PelTrEntrantName $T $M.B }
            return ((Get-PelText 'gemeldet: {0} - bitte bestätigen' 'reported: {0} - please confirm') -f $w)
        }
        return (Get-PelText 'offen' 'open')
    }

    function Update-PelTrButtons {
        $t = Get-PelTrSelected
        $own = Test-PelTrOwner $t
        $me = ''
        if ($ui.Mm) { $me = $ui.Mm.MyId }
        $signed = $t -and @($t.Signups | Where-Object { $_.Id -eq $me }).Count -gt 0
        $btnTrSign.Enabled = ($t -and $t.State -eq 'signup')
        if ($signed) { $btnTrSign.Text = Get-PelText 'Abmelden' 'Withdraw' } else { $btnTrSign.Text = Get-PelText 'Anmelden' 'Sign up' }
        $btnTrAddName.Enabled = ($own -and $t.State -eq 'signup')
        $btnTrRemove.Enabled = ($own -and $t.State -eq 'signup' -and $lvTrPeople.SelectedItems.Count -gt 0)
        $btnTrStart.Enabled = ($own -and $t.State -eq 'signup')
        $chkTrRandom.Enabled = $btnTrStart.Enabled
        $btnTrDel.Enabled = [bool]$t
        $btnTrPlay.Enabled = [bool]$t
        $m = Get-PelTrSelectedMatch $t
        $side = ''
        if ($m) { $side = Get-PelTrSide $t $m $me }
        $open = ($m -and $m.A -and $m.B -and $m.A -ne 'BYE' -and $m.B -ne 'BYE')
        $canSet = ($open -and ($own -or ($side -and -not $m.Confirmed)))
        $btnTrWinA.Enabled = $canSet
        $btnTrWinB.Enabled = $canSet
        $btnTrDraw.Enabled = ($canSet -and $t.Format -eq 'rr')
        $otherSide = ($m -and $m.Reported -and -not $m.Confirmed -and ($own -or ($side -and $side -ne (Get-PelTrSide $t $m $m.ReportedBy))))
        $btnTrConfirm.Enabled = [bool]$otherSide
        $btnTrReject.Enabled = [bool]$otherSide
        if ($open) {
            $btnTrWinA.Text = (Get-PelText 'Sieg: {0}' 'Win: {0}') -f (Limit-PelText (Get-PelTrEntrantName $t $m.A) 14)
            $btnTrWinB.Text = (Get-PelText 'Sieg: {0}' 'Win: {0}') -f (Limit-PelText (Get-PelTrEntrantName $t $m.B) 14)
        } else {
            $btnTrWinA.Text = Get-PelText 'Sieg links' 'Left wins'
            $btnTrWinB.Text = Get-PelText 'Sieg rechts' 'Right wins'
        }
        if (-not $t) { $lblTrHint.Text = '' }
        elseif ($own) { $lblTrHint.Text = Get-PelText 'Du bist Organisator: Ergebnisse, die du einträgst, gelten sofort.' 'You are the organizer: results you enter count immediately.' }
        elseif ($side) { $lblTrHint.Text = Get-PelText 'Du spielst mit: Ergebnis melden, die Gegenseite bestätigt.' 'You are playing: report the result, the other side confirms.' }
        else { $lblTrHint.Text = '' }
    }

    function Update-PelTrView {
        $selId = ''
        $t0 = Get-PelTrSelected
        if ($t0) { $selId = $t0.Id }
        $lvTr.BeginUpdate()
        $lvTr.Items.Clear()
        foreach ($t in @($tr.List | Sort-Object @{ Expression = { if ($_.State -eq 'done') { 1 } else { 0 } } }, @{ Expression = { [string]$_.Created }; Descending = $true })) {
            $it = New-Object System.Windows.Forms.ListViewItem([string]$t.Name)
            [void]$it.SubItems.Add([string]$t.Game)
            [void]$it.SubItems.Add((Get-PelTrStateText $t))
            $it.Tag = $t.Id
            if (Test-PelTrOwner $t) { $it.ForeColor = [System.Drawing.Color]::LightSkyBlue } elseif ($t.State -eq 'done') { $it.ForeColor = [System.Drawing.Color]::Gray }
            [void]$lvTr.Items.Add($it)
            if ($t.Id -eq $selId) { $it.Selected = $true }
        }
        $lvTr.EndUpdate()
        if ($lvTr.SelectedItems.Count -eq 0 -and $lvTr.Items.Count -gt 0) { $lvTr.Items[0].Selected = $true }
        Update-PelTrDetails
    }

    function Update-PelTrDetails {
        $t = Get-PelTrSelected
        $lvTrPeople.BeginUpdate(); $lvTrPeople.Items.Clear()
        $selMatch = ''
        if ($lvTrMatches.SelectedItems.Count -gt 0) { $selMatch = [string]$lvTrMatches.SelectedItems[0].Tag }
        $lvTrMatches.BeginUpdate(); $lvTrMatches.Items.Clear()
        if (-not $t) {
            $lblTrInfo.Text = Get-PelText 'Links ein Turnier auswählen oder ein neues anlegen.' 'Select a tournament on the left or create a new one.'
            $rtbTr.Text = ''
        } else {
            $lblTrInfo.Text = "{0}  -  {1}`n{2}  ·  {3}  ·  {4}" -f $t.Name, $t.Game, (Get-PelTrFormatText $t), (Get-PelTrStateText $t), ((Get-PelText 'Organisator: {0}' 'Organizer: {0}') -f $t.OwnerName)
            $ratings = @{}
            if ($ui.Mm) { $ratings = Get-PelMmRatings $ui.Mm.Results $t.GameKey }
            if ($t.State -eq 'signup') {
                foreach ($s in @($t.Signups)) {
                    $it = New-Object System.Windows.Forms.ListViewItem([string]$s.Name)
                    $manual = -not ([string]$s.Id -match '^[0-9a-f]{12}$')
                    if ($manual) { [void]$it.SubItems.Add((Get-PelText '(ohne Manager, vom Organisator eingetragen)' '(no manager, added by the organizer)')) } else { [void]$it.SubItems.Add('') }
                    [void]$it.SubItems.Add(([string][int](Get-PelMmRatingOf $ratings ([string]$s.Id))))
                    $it.Tag = $s.Id
                    [void]$lvTrPeople.Items.Add($it)
                }
            } else {
                foreach ($e in @($t.Entrants)) {
                    $it = New-Object System.Windows.Forms.ListViewItem([string]$e.Name)
                    [void]$it.SubItems.Add((@($e.MemberNames) -join ', '))
                    $sum = 0.0
                    foreach ($mid in @($e.Members)) { $sum += Get-PelMmRatingOf $ratings ([string]$mid) }
                    [void]$it.SubItems.Add(([string][int]($sum / [Math]::Max(1, @($e.Members).Count))))
                    $it.Tag = $e.Id
                    if ($t.Champion -eq $e.Id) { $it.ForeColor = [System.Drawing.Color]::Gold }
                    [void]$lvTrPeople.Items.Add($it)
                }
                foreach ($m in @($t.Matches | Sort-Object Round, Slot)) {
                    if ($m.A -eq 'BYE' -or $m.B -eq 'BYE') { continue }
                    $a = Get-PelTrEntrantName $t $m.A; $b = Get-PelTrEntrantName $t $m.B
                    if (-not $m.A) { $a = '...' }; if (-not $m.B) { $b = '...' }
                    $it = New-Object System.Windows.Forms.ListViewItem((Get-PelTrRoundName $t ([int]$m.Round)))
                    [void]$it.SubItems.Add("$a  vs.  $b")
                    [void]$it.SubItems.Add((Get-PelTrMatchStatus $t $m))
                    $it.Tag = $m.Id
                    if ($m.Confirmed) { $it.ForeColor = [System.Drawing.Color]::Gray }
                    elseif ($m.Reported) { $it.ForeColor = [System.Drawing.Color]::Orange }
                    elseif ($ui.Mm -and (Get-PelTrSide $t $m $ui.Mm.MyId)) { $it.ForeColor = [System.Drawing.Color]::LightGreen }
                    [void]$lvTrMatches.Items.Add($it)
                    if ($m.Id -eq $selMatch) { $it.Selected = $true }
                }
            }
            $rtbTr.Text = Format-PelTrOverview $t
        }
        $lvTrPeople.EndUpdate()
        $lvTrMatches.EndUpdate()
        Update-PelTrButtons
    }

