    # ---- Hilfsfunktionen ---------------------------------------------------------
    function Add-PelMmLog([string]$Text, $Color = $null) {
        if (-not $Color) { $Color = [System.Drawing.Color]::White }
        $line = "[{0}] {1}`n" -f (Get-Date -Format 'HH:mm:ss'), [PelI18n]::Tr($Text)
        $rtLog.SelectionStart = $rtLog.TextLength
        $rtLog.SelectionColor = $Color
        $rtLog.AppendText($line)
        $rtLog.ScrollToCaret()
        Write-PelLog $Text
    }

    function Get-PelMmModeLabel([string]$Key) {
        $md = Get-PelMmMode $Key
        if ($md) { return [PelI18n]::Tr($md.Label) }
        return $Key
    }

    function Format-PelMmTeams($Match) {
        $parts = @()
        foreach ($t in @($Match.Teams)) {
            $nm = @(@($t) | ForEach-Object {
                    $id = [string]$_
                    if ($Match.Names -and $Match.Names.ContainsKey($id)) { [string]$Match.Names[$id] } else { Get-PelMmName $ui.Mm $id }
                })
            $parts += ($nm -join ', ')
        }
        if (@($Match.Teams).Count -eq 2) { return ($parts -join (' ' + [PelI18n]::Tr('gegen') + ' ')) }
        return ($parts -join ' | ')
    }

    function Get-PelMmTeamIndex($Match, [string]$Id) {
        for ($i = 0; $i -lt @($Match.Teams).Count; $i++) { if (@($Match.Teams[$i]) -contains $Id) { return $i } }
        return -1
    }

    function Import-PelMmLibrary {
        $ui.Lib = Get-PelGameLibrary
        $ui.Games = @($ui.Lib.Games | Where-Object { -not $_.Hidden -and [System.IO.File]::Exists([string]$_.Exe) } | Sort-Object { [string]$_.Name } |
                ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Key = (Get-PelMmGameKey ([string]$_.Name) ([string]$_.RuleKey)) } } |
                Where-Object { $_.Key })
        $ui.MyKeys = @{}
        foreach ($g in $ui.Games) { $ui.MyKeys[$g.Key] = $g.Name }
        $keep = [string]$cbGame.SelectedItem
        if (-not $keep) { $keep = $mmSet.LastGame }
        $cbGame.Items.Clear()
        foreach ($g in $ui.Games) { [void]$cbGame.Items.Add($g.Name) }
        $idx = [Math]::Max(0, $cbGame.Items.IndexOf($keep))
        if ($cbGame.Items.Count -gt 0) { $cbGame.SelectedIndex = $idx }
        $btnQueue.Enabled = ($cbGame.Items.Count -gt 0)
        if ($cbGame.Items.Count -eq 0) {
            Add-PelMmLog "Deine Spielebibliothek ist leer - bitte zuerst in Option 3 'Spiele scannen'." ([System.Drawing.Color]::Orange)
        }
    }

    function Get-PelMmSelectedGame {
        if ($cbGame.SelectedIndex -lt 0 -or $cbGame.SelectedIndex -ge $ui.Games.Count) { return $null }
        return $ui.Games[$cbGame.SelectedIndex]
    }

    function Get-PelMmInfoMsg {
        $g = @($ui.Games | Select-Object -First 300 | ForEach-Object { @{ n = $_.Name; k = $_.Key } })
        return @{ t = 'INFO'; games = $g; host = [bool]$chkHost.Checked }
    }

    # Ausgehende Nachrichten: '*' an alle (und an sich selbst), eine ID direkt, die
    # eigene ID nur lokal. Lokal zugestellte Nachrichten laufen einmal durch JSON, damit
    # sie sich genau wie empfangene verhalten.
    function Send-PelMmOuts($Outs, [int]$Depth = 0) {
        if ($Depth -gt 4) { return }
        foreach ($o in @($Outs)) {
            if (-not $o -or -not $o.Msg) { continue }
            $json = ConvertTo-Json -InputObject $o.Msg -Depth 8 -Compress
            $self = $false
            if ($o.To -eq '*') {
                if ($ui.Node) { [void]$ui.Node.Broadcast($json) }
                $self = $true
            } elseif ($o.To -eq $ui.Mm.MyId) {
                $self = $true
            } elseif ($ui.Node) {
                [void]$ui.Node.SendTo([string]$o.To, $json)
            }
            if ($self) {
                $m = $json | ConvertFrom-Json
                $more = Receive-PelMmMessage -Mm $ui.Mm -From $ui.Mm.MyId -Msg $m
                Send-PelMmOuts $more ($Depth + 1)
            }
        }
    }

    function Update-PelMmStatus {
        $mm = $ui.Mm
        if (-not $ui.Node) { return }
        $coordName = Get-PelMmName $mm $mm.Coord
        if ($mm.Coord -eq $mm.MyId) { $coordName = [PelI18n]::Tr('du') }
        $lblNet.Text = [PelI18n]::Tr("Port 9877 auf {0} ({1}) - {2} verbunden - Koordinator: {3}") -f $ui.Adapter.Ip, $ui.Adapter.Name, $mm.Peers.Count, $coordName
        if ($mm.MyQueue) {
            $btnQueue.Text = [PelI18n]::Tr("Suche abbrechen")
            $btnQueue.BackColor = $cRed
            $lblMyQueue.Text = [PelI18n]::Tr("Du wartest ...")
        } else {
            $btnQueue.Text = [PelI18n]::Tr("Suchen")
            $btnQueue.BackColor = $cBlue
            $lblMyQueue.Text = ''
        }
    }

    function Update-PelMmPeersView {
        $mm = $ui.Mm
        $g = Get-PelMmSelectedGame
        $ratings = @{}
        if ($g) { $ratings = Get-PelMmRatings -Results $mm.Results -GameKey $g.Key }
        $fmtR = {
            param([string]$id)
            if ($ratings.ContainsKey($id)) { return ("{0} ({1})" -f [Math]::Round($ratings[$id].Rating), $ratings[$id].Games) }
            return '1000 (0)'
        }
        $lvPeers.BeginUpdate()
        $lvPeers.Items.Clear()
        $me = New-Object System.Windows.Forms.ListViewItem(([string]$mm.MyName + ' ' + [PelI18n]::Tr('(du)')))
        [void]$me.SubItems.Add([string]$mm.MyIp)
        [void]$me.SubItems.Add((& $fmtR $mm.MyId))
        [void]$me.SubItems.Add([string]$ui.Games.Count)
        [void]$me.SubItems.Add([string]$script:PelVersion)
        $me.ForeColor = $cQuiet
        [void]$lvPeers.Items.Add($me)
        foreach ($p in @($mm.Peers.Values | Sort-Object { [string]$_.Name })) {
            $li = New-Object System.Windows.Forms.ListViewItem([string]$p.Name)
            [void]$li.SubItems.Add([string]$p.Ip)
            [void]$li.SubItems.Add((& $fmtR ([string]$p.Id)))
            $common = @(@($p.Games) | Where-Object { $ui.MyKeys.ContainsKey([string]$_) }).Count
            [void]$li.SubItems.Add([string]$common)
            [void]$li.SubItems.Add([string]$p.Version)
            if ([string]$p.Version -ne [string]$script:PelVersion) { $li.ForeColor = [System.Drawing.Color]::Orange }
            [void]$lvPeers.Items.Add($li)
        }
        $lvPeers.EndUpdate()
    }

    function Update-PelMmQueuesView {
        $st = $ui.Mm.State
        $lvQueues.BeginUpdate()
        $lvQueues.Items.Clear()
        if ($st) {
            foreach ($q in @($st.queues)) {
                if (-not $q) { continue }
                $li = New-Object System.Windows.Forms.ListViewItem((Limit-PelText ([string]$q.game) 80))
                [void]$li.SubItems.Add((Get-PelMmModeLabel ([string]$q.mode)))
                [void]$li.SubItems.Add(("{0} / {1}" -f @($q.players).Count, [int]$q.need))
                [void]$li.SubItems.Add(((@($q.names) | Select-Object -First 10 | ForEach-Object { Limit-PelText ([string]$_) 32 }) -join ', '))
                if (@($q.players) -contains $ui.Mm.MyId) { $li.ForeColor = [System.Drawing.Color]::LightGreen }
                elseif (-not $ui.MyKeys.ContainsKey([string]$q.key)) { $li.ForeColor = $cQuiet }
                [void]$lvQueues.Items.Add($li)
            }
        }
        $lvQueues.EndUpdate()
    }

    function Update-PelMmMatchesView {
        $mm = $ui.Mm
        $sel = ''
        if ($lvMatches.SelectedItems.Count -gt 0) { $sel = [string]$lvMatches.SelectedItems[0].Tag }
        $lvMatches.BeginUpdate()
        $lvMatches.Items.Clear()
        foreach ($m in @($mm.Matches.Values | Sort-Object { $_.Time } -Descending)) {
            $li = New-Object System.Windows.Forms.ListViewItem(([datetime]$m.Time).ToLocalTime().ToString('HH:mm'))
            [void]$li.SubItems.Add([string]$m.Game)
            [void]$li.SubItems.Add((Get-PelMmModeLabel ([string]$m.Mode)))
            [void]$li.SubItems.Add((Format-PelMmTeams $m))
            $hostName = '-'
            if ($m.HostId) { $hostName = if ($m.HostId -eq $mm.MyId) { [PelI18n]::Tr('du') } else { Get-PelMmName $mm $m.HostId } }
            [void]$li.SubItems.Add($hostName)
            $status = [PelI18n]::Tr([string]$m.Status)
            if ($m.Status -eq 'gemeldet' -and $m.Report) {
                $status = [PelI18n]::Tr("gemeldet von {0}") -f (Get-PelMmName $mm $m.Report.By)
            }
            [void]$li.SubItems.Add($status)
            if ($m.Status -eq 'bestätigt') { $li.ForeColor = $cQuiet }
            elseif ($m.Status -eq 'gemeldet') { $li.ForeColor = [System.Drawing.Color]::Orange }
            $li.Tag = $m.Match
            if ($m.Match -eq $sel) { $li.Selected = $true }
            [void]$lvMatches.Items.Add($li)
        }
        if ($lvMatches.SelectedItems.Count -eq 0 -and $lvMatches.Items.Count -gt 0) { $lvMatches.Items[0].Selected = $true }
        $lvMatches.EndUpdate()
    }

    function Get-PelMmSelectedMatch {
        if ($lvMatches.SelectedItems.Count -eq 0) {
            Show-PelMsg "Bitte zuerst ein Match in der Liste 'Deine Matches' auswählen." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Information) $form
            return $null
        }
        $mid = [string]$lvMatches.SelectedItems[0].Tag
        if ($ui.Mm.Matches.ContainsKey($mid)) { return $ui.Mm.Matches[$mid] }
        return $null
    }

    function Update-PelMmCheckPanel([datetime]$Now) {
        $p = $ui.Mm.Proposal
        if (-not $p) {
            if ($grpCheck.Visible) { $grpCheck.Visible = $false }
            return
        }
        $left = [int][Math]::Ceiling(($p.Deadline - $Now).TotalSeconds)
        if ($left -lt 0) { $left = 0 }
        $lblCountdown.Text = "$left s"
        if (-not $grpCheck.Visible) {
            $namesHt = @{}
            if ($p.Names) { foreach ($pr in $p.Names.PSObject.Properties) { $namesHt[$pr.Name] = [string]$pr.Value } }
            $fake = [pscustomobject]@{ Teams = @($p.Teams); Names = $namesHt }
            $has = [bool](Find-PelMmLibraryGame $p.GameKey $p.Game $ui.Lib)
            $txt = [PelI18n]::Tr("{0} - {1}") -f $p.Game, (Get-PelMmModeLabel $p.Mode)
            $txt += "`n" + (Format-PelMmTeams $fake)
            if (-not $has) { $txt += "`n" + [PelI18n]::Tr("Achtung: Das Spiel liegt nicht in deiner Spielebibliothek (Option 3).") }
            $lblCheck.Text = $txt
            $answered = $ui.Answered.ContainsKey([string]$p.Match)
            $btnReady.Enabled = -not $answered
            $btnDecline.Enabled = -not $answered
            $grpCheck.Visible = $true
            $grpCheck.BringToFront()
        }
    }

    function Invoke-PelMmJoin([string]$MatchId) {
        $mm = $ui.Mm
        if (-not $mm.Matches.ContainsKey($MatchId)) { return }
        $m = $mm.Matches[$MatchId]
        if ($m.HostId -eq $mm.MyId) {
            $g = Find-PelMmLibraryGame $m.GameKey $m.Game $ui.Lib
            if (-not $g) {
                Show-PelMsg "Das Spiel liegt nicht in deiner Spielebibliothek (Option 3). Bitte dort hinzufügen und dann erneut klicken." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form
                return
            }
            if (Start-PelLibraryGame -Entry $g -Owner $form) {
                $portTxt = if ($m.Port -gt 0) { " (Port $($m.Port))" } else { '' }
                Add-PelMmLog ([PelI18n]::Tr("Du bist Gastgeber: Im Spiel ein LAN-/Mehrspieler-Spiel eröffnen{0}. Die anderen verbinden sich mit {1}.") -f $portTxt, $mm.MyIp) ([System.Drawing.Color]::LightGreen)
            }
        } elseif ($m.HostId) {
            $key = ''
            if ($m.GameKey -like 'r:*') { $key = $m.GameKey.Substring(2) }
            $res = Invoke-PelJoinGame -Ip $m.Ip -Port $m.Port -GameName $m.Game -Key $key -ParentForm $form
            if ($res) { Add-PelMmLog ([string]$res) ([System.Drawing.Color]::LightGreen) }
        } else {
            Show-PelMsg "Niemand in diesem Match hat 'Ich kann hosten' gewählt. Einigt euch im Chat, wer das Spiel eröffnet - die anderen treten dann über den Server-Browser (Option 5) oder 'Mitspielen' im Control Center bei." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Information) $form
        }
    }

    function Invoke-PelMmUiEvent($U) {
        $mm = $ui.Mm
        switch ([string]$U.Kind) {
            'peers' { Update-PelMmPeersView }
            'state' { Update-PelMmQueuesView }
            'propose' {
                Update-PelMmCheckPanel ([datetime]::UtcNow)
                Add-PelMmLog "Match gefunden - bitte innerhalb von 30 Sekunden bestätigen." ([System.Drawing.Color]::LightSkyBlue)
                try { [System.Media.SystemSounds]::Exclamation.Play() } catch { }
                try {
                    if ($form.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal }
                    $form.Activate()
                    [EarthTourneyNode]::Flash($form.Handle)
                } catch { }
            }
            'cancel' {
                if ($U.Dropped) {
                    Add-PelMmLog "Du wurdest aus der Warteschlange genommen (nicht bestätigt oder abgelehnt)." ([System.Drawing.Color]::Orange)
                } else {
                    Add-PelMmLog ([PelI18n]::Tr("Match abgebrochen - nicht bestätigt haben: {0}. Du bleibst in der Warteschlange.") -f (@($U.Names) -join ', ')) ([System.Drawing.Color]::Orange)
                }
                Update-PelMmStatus
            }
            'go' {
                $m = $mm.Matches[[string]$U.Match]
                Update-PelMmMatchesView
                Update-PelMmStatus
                if (-not $m) { break }
                if ($m.HostId -eq $mm.MyId) {
                    Add-PelMmLog "Match startet - du bist Gastgeber. Klicke 'Beitreten / Spiel starten' und eröffne im Spiel ein LAN-/Mehrspieler-Spiel." ([System.Drawing.Color]::LightGreen)
                } elseif ($m.HostId) {
                    Add-PelMmLog ([PelI18n]::Tr("Match startet - Gastgeber ist {0} ({1}). Sobald das Spiel dort offen ist: 'Beitreten / Spiel starten'.") -f (Get-PelMmName $mm $m.HostId), $m.Ip) ([System.Drawing.Color]::LightGreen)
                    if ($chkAuto.Checked) {
                        $ui.AutoJoinAt = [datetime]::UtcNow.AddSeconds(20)
                        $ui.AutoJoinMatch = $m.Match
                    }
                } else {
                    Add-PelMmLog "Match startet - niemand hat 'Ich kann hosten' gewählt. Einigt euch im Chat, wer das Spiel eröffnet." ([System.Drawing.Color]::Orange)
                }
                try { [System.Media.SystemSounds]::Asterisk.Play() } catch { }
                try { [EarthTourneyNode]::Flash($form.Handle) } catch { }
            }
            'report' {
                $m = $mm.Matches[[string]$U.Match]
                if ($m -and $m.Report -and $m.Report.By -ne $mm.MyId) {
                    Add-PelMmLog ([PelI18n]::Tr("{0} hat ein Ergebnis gemeldet - bitte prüfen und bestätigen oder ablehnen.") -f (Get-PelMmName $mm $m.Report.By)) ([System.Drawing.Color]::Orange)
                }
                Update-PelMmMatchesView
            }
            'reject' {
                Add-PelMmLog ([PelI18n]::Tr("{0} hat das gemeldete Ergebnis abgelehnt - bitte neu melden.") -f [string]$U.By) ([System.Drawing.Color]::Orange)
                Update-PelMmMatchesView
            }
            'result' {
                [void](Save-PelMmResults $mm.Results)
                if ($mm.Matches.ContainsKey([string]$U.Match)) { Add-PelMmLog "Ergebnis bestätigt - Wertung aktualisiert." ([System.Drawing.Color]::LightGreen) }
                Update-PelMmMatchesView
                Update-PelMmPeersView
            }
        }
    }

    # Ein Takt (alle 200 ms): Ereignisse des Dienstes abholen, als Koordinator die
    # Warteschlangen führen, Lebenszeichen senden, Oberfläche aktualisieren. Nie
    # verschachtelt: öffnet ein Aufruf darin einen Dialog (z. B. Beitreten), läuft der
    # Timer weiter, der nächste Takt wird dann einfach übersprungen.
    function Invoke-PelMmPump {
        $mm = $ui.Mm
        $node = $ui.Node
        if (-not $node -or -not $mm) { return }
        $now = [datetime]::UtcNow
        $ev = $null
        $n = 0
        $peersChanged = $false
        while ($n -lt 300 -and $node.Events.TryDequeue([ref]$ev)) {
            $n++
            $kind = (([string]$ev) -split '\|', 2)[0]
            if ($kind -eq 'PEER+' -or $kind -eq 'PEER-') {
                $f = ([string]$ev) -split '\|'
                if ($f.Count -ge 5) {
                    if ($kind -eq 'PEER+') {
                        $isNew = -not $mm.Peers.ContainsKey($f[1])
                        $mm.Peers[$f[1]] = [pscustomobject]@{ Id = $f[1]; Name = $f[2]; Ip = $f[3]; Version = $f[4]; Games = @(); CanHost = $false }
                        Send-PelMmOuts @(New-PelMmOut $f[1] (Get-PelMmInfoMsg))
                        Send-PelTrOwnStates $f[1]
                        if ($isNew) { Add-PelMmLog ([PelI18n]::Tr("Verbunden: {0} ({1})") -f $f[2], $f[3]) ([System.Drawing.Color]::LightGray) }
                    } elseif ($mm.Peers.ContainsKey($f[1])) {
                        $mm.Peers.Remove($f[1])
                        Add-PelMmLog ([PelI18n]::Tr("Getrennt: {0}") -f $f[2]) ([System.Drawing.Color]::Gray)
                    }
                    $peersChanged = $true
                }
            } elseif ($kind -eq 'MSG') {
                $f = ([string]$ev) -split '\|', 4
                # Nur von verbundenen Teilnehmern und nur über deren bekannte Adresse.
                if ($f.Count -eq 4 -and $mm.Peers.ContainsKey($f[1]) -and $mm.Peers[$f[1]].Ip -eq $f[2]) {
                    $m = $null
                    try { $m = $f[3] | ConvertFrom-Json } catch { $m = $null }
                    if ($m -and ([string]$m.t).StartsWith('TR_')) {
                        Receive-PelTrMessage $f[1] $m
                    } elseif ($m) {
                        $outs = Receive-PelMmMessage -Mm $mm -From $f[1] -Msg $m -Now $now
                        Send-PelMmOuts $outs
                    }
                }
            } elseif ($kind -eq 'SYS') {
                Add-PelMmLog (([string]$ev).Substring(4)) ([System.Drawing.Color]::Gray)
            }
        }
        if ($peersChanged) {
            if (Update-PelMmCoordinator $mm) {
                $mm.Dirty = $true
                if ($mm.MyQueue) { Send-PelMmOuts (Get-PelMmQueueOut $mm) }
            }
            Update-PelMmPeersView
            Update-PelMmStatus
        }
        if ($mm.Coord -eq $mm.MyId) { Send-PelMmOuts (Invoke-PelMmCoordinatorTick -Mm $mm -Now $now) }
        if ($mm.MyQueue -and ($now - $mm.LastQueueSent).TotalSeconds -ge 10) { Send-PelMmOuts (Get-PelMmQueueOut $mm) }
        if ($mm.Ui.Count -gt 0) {
            $items = $mm.Ui.ToArray()
            $mm.Ui.Clear()
            foreach ($u in $items) { Invoke-PelMmUiEvent $u }
        }
        Update-PelMmCheckPanel $now
        # Eigene Turniere alle 20 Sekunden erneut verteilen (für später Dazugekommene
        # und falls eine Nachricht verloren ging)
        if (($now - $tr.LastBroadcast).TotalSeconds -ge 20) { $tr.LastBroadcast = $now; Send-PelTrOwnStates '*' }
        if ($ui.AutoJoinAt -and $now -ge $ui.AutoJoinAt) {
            $mid = $ui.AutoJoinMatch
            $ui.AutoJoinAt = $null
            Invoke-PelMmJoin $mid
        }
    }

    function Start-PelMmNode {
        if ($ui.Node) { try { $ui.Node.Stop() } catch { }; $ui.Node = $null }
        $a = $ui.Adapter
        $myId = Get-PelMmPlayerId
        $name = Get-PelDisplayName
        $ui.Mm = New-PelMmState -MyId $myId -MyName $name -MyIp ([string]$a.Ip)
        $ui.Mm.Results = Get-PelMmResults
        $ui.Answered = @{}
        $node = New-Object EarthTourneyNode -ArgumentList ([string]$a.Ip), $myId, $name, ([string]$script:PelVersion), ([string]$script:PelNetworkSecret)
        $node.Mask = [string]$a.Mask
        $err = $node.Start()
        if ($err) {
            $lblNet.Text = [PelI18n]::Tr("Port 9877: FEHLER - {0}") -f $err
            $lblNet.ForeColor = [System.Drawing.Color]::FromArgb(255, 110, 100)
            Add-PelMmLog ([PelI18n]::Tr("Dienst konnte nicht starten: {0} (Option 4 schon offen oder Port belegt?)") -f $err) ([System.Drawing.Color]::FromArgb(255, 110, 100))
            return
        }
        $ui.Node = $node
        $lblNet.ForeColor = $cQuiet
        Add-PelMmLog ([PelI18n]::Tr("Port 9877 geöffnet auf {0}. Suche nach anderen Managern mit offener Option 4 ...") -f $a.Ip) ([System.Drawing.Color]::LightGray)
        try { $node.ScanAsync([string[]]([EarthTourneyNode]::HostRange([string]$a.Ip, [string]$a.Mask, 1022))) } catch { }
        Update-PelMmStatus
        Update-PelMmPeersView
        Update-PelMmQueuesView
        Update-PelMmMatchesView
    }

    function Save-PelMmWindowSettings {
        $mmSet.CanHost = [bool]$chkHost.Checked
        $mmSet.RandomTeams = [bool]$chkRandom.Checked
        $mmSet.AutoJoin = [bool]$chkAuto.Checked
        $g = Get-PelMmSelectedGame
        if ($g) { $mmSet.LastGame = $g.Name }
        if ($cbMode.SelectedIndex -ge 0) { $mmSet.LastMode = $modes[$cbMode.SelectedIndex].Key }
        Save-PelMmSettings $mmSet
    }

    # ---- Ereignisse --------------------------------------------------------------
    $btnQueue.Add_Click({
        $mm = $ui.Mm
        if (-not $mm -or -not $ui.Node) { return }
        if ($mm.MyQueue) {
            Send-PelMmOuts @(New-PelMmOut $mm.Coord @{ t = 'MM_LEAVE' })
            $mm.MyQueue = $null
            Add-PelMmLog "Suche abgebrochen." ([System.Drawing.Color]::LightGray)
        } else {
            $g = Get-PelMmSelectedGame
            if (-not $g -or $cbMode.SelectedIndex -lt 0) { return }
            $md = $modes[$cbMode.SelectedIndex]
            $mm.MyQueue = [pscustomobject]@{ Game = $g.Name; GameKey = $g.Key; Mode = $md.Key; Random = [bool]$chkRandom.Checked; CanHost = [bool]$chkHost.Checked }
            Send-PelMmOuts (Get-PelMmQueueOut $mm)
            Add-PelMmLog ([PelI18n]::Tr("Suche: {0} - {1}. Sobald genug Spieler da sind, kommt der Bereit-Check.") -f $g.Name, (Get-PelMmModeLabel $md.Key)) ([System.Drawing.Color]::LightSkyBlue)
            Save-PelMmWindowSettings
        }
        Update-PelMmStatus
    })

    $btnReady.Add_Click({
        $p = $ui.Mm.Proposal
        if (-not $p) { return }
        $has = [bool](Find-PelMmLibraryGame $p.GameKey $p.Game $ui.Lib)
        Send-PelMmOuts @(New-PelMmOut $ui.Mm.Coord @{ t = 'MM_READY'; match = $p.Match; ready = $true; has = $has })
        $ui.Answered[[string]$p.Match] = $true
        $btnReady.Enabled = $false
        $btnDecline.Enabled = $false
        $lblCheck.Text += "`n" + [PelI18n]::Tr("Bestätigt - warte auf die anderen ...")
    })
    $btnDecline.Add_Click({
        $p = $ui.Mm.Proposal
        if (-not $p) { return }
        Send-PelMmOuts @(New-PelMmOut $ui.Mm.Coord @{ t = 'MM_READY'; match = $p.Match; ready = $false; has = $true })
        $ui.Answered[[string]$p.Match] = $true
        $ui.Mm.Proposal = $null
        $ui.Mm.MyQueue = $null
        $grpCheck.Visible = $false
        Update-PelMmStatus
    })

    $btnJoin.Add_Click({
        $m = Get-PelMmSelectedMatch
        if ($m) { Invoke-PelMmJoin $m.Match }
    })

    $btnReport.Add_Click({
        $m = Get-PelMmSelectedMatch
        if (-not $m) { return }
        if ($m.Status -eq 'bestätigt') { Show-PelMsg "Für dieses Match gibt es schon ein bestätigtes Ergebnis." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Information) $form; return }
        $dlg = (New-PelForm)
        $dlg.Text = "Ergebnis melden"
        $dlg.Size = New-Object System.Drawing.Size(520, 260)
        $dlg.StartPosition = 'CenterParent'
        $dlg.FormBorderStyle = 'FixedDialog'
        $dlg.MaximizeBox = $false
        $dlg.MinimizeBox = $false
        $dlg.BackColor = $cBg
        $dlg.ForeColor = [System.Drawing.Color]::White
        $dlg.Font = $fMain
        $cbRes = New-Object System.Windows.Forms.ComboBox
        $cbRes.DropDownStyle = 'DropDownList'
        $cbRes.Location = New-Object System.Drawing.Point(20, 60)
        $cbRes.Size = New-Object System.Drawing.Size(460, 26)
        $cbRes.BackColor = $cInput
        $cbRes.ForeColor = [System.Drawing.Color]::White
        $dlg.Controls.Add($cbRes)
        [void](& $mkLabel $dlg ([PelI18n]::Tr("Wer hat gewonnen? ({0})") -f $m.Game) 20 24 460)
        $choices = New-Object System.Collections.Generic.List[object]
        $teamCount = @($m.Teams).Count
        if ($teamCount -eq 2) {
            for ($ti = 0; $ti -lt 2; $ti++) {
                $nm = @(@($m.Teams[$ti]) | ForEach-Object { if ($m.Names.ContainsKey([string]$_)) { $m.Names[[string]$_] } else { Get-PelMmName $ui.Mm ([string]$_) } }) -join ', '
                [void]$cbRes.Items.Add(([PelI18n]::Tr("Gewonnen: {0}") -f $nm))
                $choices.Add(@{ Winner = $ti; WinnerId = '' })
            }
            [void]$cbRes.Items.Add([PelI18n]::Tr("Unentschieden"))
            $choices.Add(@{ Winner = -1; WinnerId = '' })
        } else {
            foreach ($id in @($m.Teams[0])) {
                $nm = if ($m.Names.ContainsKey([string]$id)) { $m.Names[[string]$id] } else { Get-PelMmName $ui.Mm ([string]$id) }
                [void]$cbRes.Items.Add(([PelI18n]::Tr("Gewonnen: {0}") -f $nm))
                $choices.Add(@{ Winner = 2; WinnerId = [string]$id })
            }
        }
        $cbRes.SelectedIndex = 0
        $bOk = & $mkBtn $dlg "Melden" 20 150 220 $cBlue 'Top,Left'
        $bCancel = & $mkBtn $dlg "Abbrechen" 260 150 220 $cBtn 'Top,Left'
        $bOk.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $bCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        $dlg.AcceptButton = $bOk
        $dlg.CancelButton = $bCancel
        if ($dlg.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $c = $choices[$cbRes.SelectedIndex]
        $msg = @{ t = 'REPORT'; match = $m.Match; winner = $c.Winner; winnerId = $c.WinnerId }
        $outs = @(@($m.Teams | ForEach-Object { @($_) }) | ForEach-Object { New-PelMmOut ([string]$_) $msg.Clone() })
        Send-PelMmOuts $outs
        Add-PelMmLog "Ergebnis gemeldet - ein Gegner muss es noch bestätigen." ([System.Drawing.Color]::LightGray)
    })

    $btnConfirm.Add_Click({
        $m = Get-PelMmSelectedMatch
        if (-not $m) { return }
        $mm = $ui.Mm
        if (-not $m.Report) { Show-PelMsg "Für dieses Match wurde noch kein Ergebnis gemeldet." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Information) $form; return }
        if ($m.Report.By -eq $mm.MyId) { Show-PelMsg "Du hast das Ergebnis selbst gemeldet - bestätigen muss ein Gegner." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Information) $form; return }
        if (@($m.Teams).Count -eq 2 -and (Get-PelMmTeamIndex $m $mm.MyId) -eq (Get-PelMmTeamIndex $m $m.Report.By)) {
            Show-PelMsg "Bestätigen kann nur jemand aus dem gegnerischen Team." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Information) $form
            return
        }
        $res = @{
            Id = $m.Match; Time = [datetime]::UtcNow.ToString('s'); GameKey = $m.GameKey; Game = $m.Game; Mode = $m.Mode
            Teams = @($m.Teams | ForEach-Object { , @($_) }); Names = $m.Names; Winner = [int]$m.Report.Winner; WinnerId = [string]$m.Report.WinnerId
            By = [string]$m.Report.By; ConfirmedBy = $mm.MyId
        }
        Send-PelMmOuts @(New-PelMmOut '*' @{ t = 'RESULT'; result = $res })
    })

    $btnRejectRes.Add_Click({
        $m = Get-PelMmSelectedMatch
        if (-not $m -or -not $m.Report) { return }
        $outs = @(@($m.Teams | ForEach-Object { @($_) }) | ForEach-Object { New-PelMmOut ([string]$_) @{ t = 'REJECT'; match = $m.Match } })
        Send-PelMmOuts $outs
    })

    $chkHost.Add_CheckedChanged({
        if (-not $ui.Node) { return }
        if ($ui.Mm.MyQueue) { $ui.Mm.MyQueue.CanHost = [bool]$chkHost.Checked; Send-PelMmOuts (Get-PelMmQueueOut $ui.Mm) }
        Send-PelMmOuts @(New-PelMmOut '*' (Get-PelMmInfoMsg))
        Save-PelMmWindowSettings
    })
    $chkRandom.Add_CheckedChanged({ Save-PelMmWindowSettings })
    $chkAuto.Add_CheckedChanged({ Save-PelMmWindowSettings })
    $cbGame.Add_SelectedIndexChanged({ if ($ui.Mm) { Update-PelMmPeersView } })

    $btnRescan.Add_Click({
        if (-not $ui.Node) { Start-PelMmNode; return }
        try { $ui.Node.ScanAsync([string[]]([EarthTourneyNode]::HostRange([string]$ui.Adapter.Ip, [string]$ui.Adapter.Mask, 1022))) } catch { }
        Import-PelMmLibrary
        Send-PelMmOuts @(New-PelMmOut '*' (Get-PelMmInfoMsg))
        Add-PelMmLog "Suche nach anderen Managern gestartet." ([System.Drawing.Color]::LightGray)
    })

    $btnConnectIp.Add_Click({
        if (-not $ui.Node) { return }
        $d = (New-PelForm)
        $d.Text = "Per IP verbinden"
        $d.Size = New-Object System.Drawing.Size(420, 170)
        $d.StartPosition = 'CenterParent'
        $d.FormBorderStyle = 'FixedDialog'
        $d.MaximizeBox = $false
        $d.MinimizeBox = $false
        $d.BackColor = $cBg
        $d.ForeColor = [System.Drawing.Color]::White
        $d.Font = $fMain
        [void](& $mkLabel $d "IP-Adresse des anderen PCs (Option 4 muss dort offen sein):" 16 16 380)
        $tb = New-Object System.Windows.Forms.TextBox
        $tb.Location = New-Object System.Drawing.Point(16, 44)
        $tb.Size = New-Object System.Drawing.Size(372, 26)
        $tb.BackColor = $cInput
        $tb.ForeColor = [System.Drawing.Color]::White
        $d.Controls.Add($tb)
        $bo = & $mkBtn $d "Verbinden" 16 84 180 $cBlue 'Top,Left'
        $bc = & $mkBtn $d "Abbrechen" 208 84 180 $cBtn 'Top,Left'
        $bo.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $bc.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        $d.AcceptButton = $bo
        $d.CancelButton = $bc
        if ($d.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
            $ipTxt = $tb.Text.Trim()
            $tmp = $null
            if ([System.Net.IPAddress]::TryParse($ipTxt, [ref]$tmp)) { $ui.Node.ConnectTo($ipTxt) }
            else { Show-PelMsg "Das ist keine gültige IP-Adresse." 'Turniere & Matchmaking' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form }
        }
    })

    $btnAdapter.Add_Click({
        $r = Select-PelNetworkAdapter -ParentForm $form
        if (-not $r) { return }
        $cur = Get-PelSelectedAdapter
        if (-not $cur) { return }
        if ($ui.Mm -and $ui.Mm.MyQueue) { Send-PelMmOuts @(New-PelMmOut $ui.Mm.Coord @{ t = 'MM_LEAVE' }) }
        $ui.Adapter = $cur
        Start-PelMmNode
    })

    $timer = New-Object System.Windows.Forms.Timer
    $timer.Interval = 200
    $timer.Add_Tick({
        if ($ui.InTick) { return }
        $ui.InTick = $true
        try { Invoke-PelMmPump }
        catch { Write-PelLog "Matchmaking-Takt: $($_.Exception.Message)" 'ERROR' }
        finally { $ui.InTick = $false }
    })

    $form.Add_Shown({
        $idxMode = 1
        for ($i = 0; $i -lt $modes.Count; $i++) { if ($modes[$i].Key -eq $mmSet.LastMode) { $idxMode = $i } }
        $cbMode.SelectedIndex = $idxMode
        Import-PelMmLibrary
        Start-PelMmNode
        Update-PelTrView
        $timer.Start()
    })

    $form.Add_FormClosing({
        $timer.Stop()
        try {
            if ($ui.Mm -and $ui.Mm.MyQueue -and $ui.Node) { Send-PelMmOuts @(New-PelMmOut $ui.Mm.Coord @{ t = 'MM_LEAVE' }) }
        } catch { }
        try { if ($ui.Mm) { [void](Save-PelMmResults $ui.Mm.Results) } } catch { }
        try { Save-PelTournaments $tr.List } catch { }
        Save-PelMmWindowSettings
        if ($ui.Node) { try { $ui.Node.Stop() } catch { } }
    })

    [void]$form.ShowDialog()
    $timer.Dispose()
    $tip.Dispose()
}
#endregion

