            Modes = @(@('', 'Standard')); Maps = @('Dedicated'); MapNote = (Get-PelText 'Bei Valheim ist die "Karte" der Name der Welt.' 'For Valheim the "map" is the name of the world.'); Internet = $true; Env = @('SteamAppId=892970') }
