function Get-PelServerTemplate([string]$Key) {
    return (Get-PelServerTemplates | Where-Object { $_.Key -eq $Key } | Select-Object -First 1)
}

# Nur Zeichen, die in .bat-Dateien und Spielparametern keinen Ärger machen
function ConvertTo-PelServerSafe([string]$Text, [int]$Max = 60) {
    return (Limit-PelText ((([string]$Text) -replace '["%^&|<>`]', '') -replace '[\x00-\x1f]', ' ') $Max)
}

function ConvertTo-PelServerSlug([string]$Text) {
    $t = (([string]$Text) -replace '[^A-Za-z0-9_-]+', '_').Trim('_')
    if (-not $t) { $t = 'Server' }
    if ($t.Length -gt 40) { $t = $t.Substring(0, 40) }
    return $t
}

# Setzt Schlüssel in einer INI-artigen Textdatei (Zeilen "Schlüssel=Wert").
#   $Keys: Hashtable Schlüssel -> Wert. $Section: nur in diesem Abschnitt (leer = überall);
#   fehlt ein Schlüssel im Abschnitt, wird er dort ergänzt. Anführungszeichen des
#   Originalwerts bleiben erhalten.
function Set-PelIniValues([string]$Text, [string]$Section, $Keys) {
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($l in (([string]$Text) -replace "`r", '' -split "`n")) { $lines.Add($l) }
    $cur = ''
    $done = @{}
    $secEnd = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $l = $lines[$i]
        if ($l -match '^\s*\[(.+?)\]\s*$') {
            if ($Section -and $cur -eq $Section) { $secEnd = $i }
            $cur = $matches[1]
            continue
        }
        if ($Section -and $cur -ne $Section) { continue }
        if ($l -match '^(\s*)([^=;#\s][^=]*?)\s*=\s*(.*)$') {
            $k = $matches[2].Trim()
            foreach ($key in @($Keys.Keys)) {
                if ($k -ieq $key) {
                    $v = [string]$Keys[$key]
                    if ($matches[3].Trim().StartsWith('"')) { $v = '"' + $v + '"' }
                    $lines[$i] = "$($matches[1])$k=$v"
                    $done[$key] = $true
                }
            }
        }
    }
    if ($Section) {
        if ($cur -eq $Section) { $secEnd = $lines.Count }
        $missing = @($Keys.Keys | Where-Object { -not $done.ContainsKey($_) })
        if ($missing.Count -gt 0) {
            if ($secEnd -lt 0) {
                $lines.Add("[$Section]")
                $secEnd = $lines.Count
            }
            # vor den Leerzeilen am Abschnittsende einfügen, nicht dahinter
            while ($secEnd -gt 0 -and -not $lines[$secEnd - 1].Trim() -and $lines[$secEnd - 1] -notmatch '^\s*\[') { $secEnd-- }
            foreach ($k in $missing) { $lines.Insert($secEnd, "$k=$($Keys[$k])"); $secEnd++ }
        }
    }
    return ($lines -join "`r`n")
}

# ExampleServerOptions.txt von F.E.A.R. finden. Der Server legt sie normalerweise hier ab:
#   %PUBLIC%\Documents\Monolith Productions\FEAR\ServerOptions\ExampleServerOptions.txt
# (XP: All Users\Documents\...). Gesucht wird deshalb bis 3 Ordnerebenen tief unter
# "Monolith Productions" (öffentlich und eigene Dokumente) sowie neben der EXE.
# $Preferred: vom Nutzer gewählte Options-Datei (hat Vorrang, wenn vorhanden).
function Find-PelFearExampleOptions([string]$ExeDir, [string]$Preferred = '') {
    if ($Preferred -and [System.IO.File]::Exists($Preferred)) { return $Preferred }
    $dirs = New-Object System.Collections.Generic.List[string]
    if ($ExeDir) {
        $dirs.Add($ExeDir)
        $dirs.Add((Join-Path $ExeDir 'ServerOptions'))
        try { $dirs.Add([System.IO.Path]::GetDirectoryName($ExeDir)) } catch { }
    }
    foreach ($d in $dirs) {
        if (-not $d -or -not [System.IO.Directory]::Exists($d)) { continue }
        $p = Join-Path $d 'ExampleServerOptions.txt'
        if ([System.IO.File]::Exists($p)) { return $p }
    }
    $roots = @()
    if ($env:PUBLIC) { $roots += (Join-Path $env:PUBLIC 'Documents\Monolith Productions') }
    if ($env:ALLUSERSPROFILE) { $roots += (Join-Path $env:ALLUSERSPROFILE 'Documents\Monolith Productions') }
    $docs = [Environment]::GetFolderPath('MyDocuments')
    if ($docs) { $roots += (Join-Path $docs 'Monolith Productions') }
    $others = New-Object System.Collections.Generic.List[object]
    foreach ($root in $roots) {
        if (-not [System.IO.Directory]::Exists($root)) { continue }
        $hits = @(Get-ChildItem -LiteralPath $root -Filter '*.txt' -File -Recurse -Depth 3 -ErrorAction SilentlyContinue | Where-Object { $_.Name -notlike 'PEL_*' })
        $ex = $hits | Where-Object { $_.Name -ieq 'ExampleServerOptions.txt' } | Select-Object -First 1
        if ($ex) { return $ex.FullName }
        # sonst eine vom FEARServer-Einrichtungsfenster angelegte Datei (ServerOptions0000.txt ...)
        foreach ($h in $hits) {
            if ($h.DirectoryName -notmatch '(?i)ServerOptions$' -and $h.Name -notmatch '(?i)ServerOptions') { continue }
            try { if ((Read-PelTextFile $h.FullName) -match '(?im)^\s*\[ServerSettings\]') { $others.Add($h) } } catch { }
        }
    }
    if ($others.Count -gt 0) { return (@($others | Sort-Object LastWriteTime -Descending)[0]).FullName }
    return ''
}

# Alle Options-Dateien neben $Path (für die Kartenliste), ohne PEL_-Kopien
function Get-PelFearOptionFiles([string]$Path) {
    $out = New-Object System.Collections.Generic.List[string]
    if (-not $Path -or -not [System.IO.File]::Exists($Path)) { return , $out }
    $out.Add($Path)
    try {
        foreach ($f in @(Get-ChildItem -LiteralPath ([System.IO.Path]::GetDirectoryName($Path)) -Filter '*.txt' -File -ErrorAction SilentlyContinue)) {
            if ($f.Name -like 'PEL_*' -or $f.FullName -ieq $Path) { continue }
            if ($f.Name -notmatch '(?i)ServerOptions') { continue }
            $out.Add($f.FullName)
        }
    } catch { }
    return , $out
}

# "Docks" -> "Worlds\ReleaseMultiplayer\Docks" (so stehen die Karten in der Options-Datei)
function ConvertTo-PelFearMapPath([string]$Map) {
    $m = ([string]$Map).Trim().Trim('"')
    if (-not $m) { return '' }
    if ($m -notmatch '[\\/]') { $m = 'Worlds\ReleaseMultiplayer\' + $m }
    return ($m -replace '/', '\')
}

# Legt den Abschnitt [$To] an, falls er fehlt - als Kopie von [$From] (ohne Karten).
# F.E.A.R. speichert SessionName, MaxPlayers, Limits und Karten im Abschnitt des Spielmodus.
function Add-PelFearModeSection([string]$Text, [string]$From, [string]$To) {
    $lines = @((([string]$Text) -replace "`r", '') -split "`n")
    foreach ($l in $lines) { if ($l -match '^\s*\[(.+?)\]\s*$' -and $matches[1].Trim() -ieq $To) { return $Text } }
    $copy = New-Object System.Collections.Generic.List[string]
    $cur = ''
    foreach ($l in $lines) {
        if ($l -match '^\s*\[(.+?)\]\s*$') { $cur = $matches[1].Trim(); continue }
        if ($From -and $cur -ieq $From -and $l -notmatch '^\s*Mission\d+\s*=' -and $l.Trim()) { $copy.Add($l) }
    }
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($l in $lines) { $out.Add($l) }
    while ($out.Count -gt 0 -and -not $out[$out.Count - 1].Trim()) { $out.RemoveAt($out.Count - 1) }
    $out.Add("[$To]")
    foreach ($l in $copy) { $out.Add($l) }
    return ($out -join "`r`n")
}

# Wert eines Schlüssels in einem Abschnitt (oder '')
function Get-PelIniValue([string]$Text, [string]$Section, [string]$Key) {
    $cur = ''
    foreach ($l in ((([string]$Text) -replace "`r", '') -split "`n")) {
        if ($l -match '^\s*\[(.+?)\]\s*$') { $cur = $matches[1].Trim(); continue }
        if ($cur -ieq $Section -and $l -match '^\s*([^=]+?)\s*=\s*(.*)$' -and $matches[1] -ieq $Key) { return $matches[2].Trim().Trim('"') }
    }
    return ''
}

# Welcher Abschnitt der Options-Datei hat die Karten für den Spielmodus? Genau gleich
# benannt, sonst ein Abschnitt, dessen Name den Modus enthält, sonst - wenn es nur einen
# Abschnitt mit Karten gibt - dieser. Rückgabe: Abschnittsname oder ''.
function Resolve-PelFearSection([string]$Text, [string]$Mode, [switch]$Strict) {
    $secs = New-Object System.Collections.Generic.List[string]
    $cur = ''
    foreach ($l in (([string]$Text) -replace "`r", '' -split "`n")) {
        if ($l -match '^\s*\[(.+?)\]\s*$') { $cur = $matches[1].Trim(); continue }
        if ($l -match '^\s*Mission\d+\s*=' -and -not $secs.Contains($cur)) { $secs.Add($cur) }
    }
    if (-not $Mode) { $Mode = 'DeathMatch' }
    foreach ($x in $secs) { if ($x -ieq $Mode) { return $x } }
    $norm = ($Mode -replace '[^A-Za-z]', '')
    foreach ($x in $secs) { if (($x -replace '[^A-Za-z]', '') -ieq $norm) { return $x } }
    if ($Strict) { return '' }
    foreach ($x in $secs) { if ($x -like "*$Mode*") { return $x } }
    if ($secs.Count -eq 1) { return $secs[0] }
    return ''
}

# Alle Karten (MissionN=...) aus einer F.E.A.R.-Options-Datei. $Section leer = aus allen
# Abschnitten; sonst nur aus diesem Abschnitt (z. B. [CTF]).
function Get-PelFearMissions([string]$Path, [string]$Section = '') {
    $list = New-Object System.Collections.Generic.List[string]
    if (-not $Path -or -not [System.IO.File]::Exists($Path)) { return , $list }
    $cur = ''
    foreach ($l in ((Read-PelTextFile $Path) -replace "`r", '' -split "`n")) {
        if ($l -match '^\s*\[(.+?)\]\s*$') { $cur = $matches[1].Trim(); continue }
        if ($Section -and $cur -ine $Section) { continue }
        if ($l -match '^\s*Mission\d+\s*=\s*"?([^"]+?)"?\s*$') {
            $m = $matches[1].Trim()
            if ($m -and -not $list.Contains($m)) { $list.Add($m) }
        }
    }
    return , $list
}

# Setzt $Map als erste Karte (Mission0) im Abschnitt $Section, die übrigen Karten
# bleiben als Rotation dahinter. Rückgabe: neuer Text oder $null, wenn es den Abschnitt
# (oder Mission-Zeilen darin) nicht gibt.
function Set-PelFearStartMap([string]$Text, [string]$Section, [string]$Map) {
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($l in (([string]$Text) -replace "`r", '' -split "`n")) { $lines.Add($l) }
    $cur = ''
    $idx = New-Object System.Collections.Generic.List[int]
    $maps = New-Object System.Collections.Generic.List[string]
    $quoted = $false
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match '^\s*\[(.+?)\]\s*$') { $cur = $matches[1].Trim(); continue }
        if ($cur -ine $Section) { continue }
        if ($lines[$i] -match '^\s*Mission\d+\s*=\s*(")?([^"]*?)"?\s*$') {
            if ($matches[1]) { $quoted = $true }
            $idx.Add($i)
            $maps.Add($matches[2].Trim())
        }
    }
    if ($idx.Count -eq 0) { return $null }
    $new = New-Object System.Collections.Generic.List[string]
    $new.Add($Map)
    foreach ($m in $maps) { if ($m -and $m -ine $Map) { $new.Add($m) } }
    $first = $idx[0]
    for ($k = $idx.Count - 1; $k -ge 0; $k--) { $lines.RemoveAt($idx[$k]) }
    for ($k = 0; $k -lt $new.Count; $k++) {
        $v = if ($quoted) { '"' + $new[$k] + '"' } else { $new[$k] }
        $lines.Insert($first + $k, "Mission$k=$v")
    }
    return ($lines -join "`r`n")
}

# Quake-3-artige .cfg (Jedi Academy, ClanMod): Werte von "set/seta NAME ..." ersetzen
# (fehlende werden vor der map-Zeile ergänzt) und die map-Zeile auf $Map setzen.
# exec-Zeilen für Dateien, die es in $CfgDir nicht gibt, werden auskommentiert.
function Set-PelQ3Cvars([string]$Text, $Vars, [string]$Map, [string]$CfgDir = '') {
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($l in (([string]$Text) -replace "`r", '' -split "`n")) { $lines.Add($l) }
    $done = @{}
    $mapIdx = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $l = $lines[$i]
        if ($l -match '^\s*(seta|set|sets|setu)\s+"?([A-Za-z0-9_]+)"?\s') {
            $n = $matches[2]
            foreach ($k in @($Vars.Keys)) {
                if ($n -ieq $k) { $lines[$i] = ('{0} {1} "{2}"' -f $matches[1], $k, [string]$Vars[$k]); $done[$k] = $true }
            }
        } elseif ($l -match '^\s*(map|devmap)\s+\S+') {
            $mapIdx = $i
        } elseif ($CfgDir -and $l -match '^\s*exec\s+"?([^"\s]+)"?') {
            $f = $matches[1]
            if (-not [System.IO.File]::Exists((Join-Path $CfgDir $f))) { $lines[$i] = "// $l   (PEL: Datei fehlt)" }
        }
    }
    $add = New-Object System.Collections.Generic.List[string]
    foreach ($k in @($Vars.Keys)) { if (-not $done.ContainsKey($k)) { $add.Add(('seta {0} "{1}"' -f $k, [string]$Vars[$k])) } }
    if ($mapIdx -ge 0) {
        if ($Map) { $lines[$mapIdx] = "map $Map" }
        $lines.InsertRange($mapIdx, $add)
    } else {
        while ($lines.Count -gt 0 -and -not $lines[$lines.Count - 1].Trim()) { $lines.RemoveAt($lines.Count - 1) }
        $lines.AddRange($add)
        if ($Map) { $lines.Add("map $Map") }
    }
    return ($lines -join "`r`n") + "`r`n"
}

# Eingebaute Jedi-Academy-Vorlage: mit ClanMod komplett, ohne ClanMod ohne den ClanMod-Teil
function Get-PelJkaCfgTemplate([bool]$ClanMod) {
    $t = [string]$script:PelJkaClanCfgTemplate
    if ($ClanMod) { return $t }
    $out = New-Object System.Collections.Generic.List[string]
    $skip = $false
    $all = @(($t -replace "`r", '') -split "`n")
    for ($i = 0; $i -lt $all.Count; $i++) {
        $l = $all[$i]
        if (-not $skip -and $i + 1 -lt $all.Count -and $all[$i + 1] -match 'BEGIN CLAN MOD SETTINGS') { $skip = $true }
        if ($skip -and $l -match '^\s*(map|devmap)\s') { $skip = $false }
        if (-not $skip -and $l -notmatch '^\s*set\s+cm_') { $out.Add($l) }
    }
    return ($out -join "`r`n")
}

# ---- F.E.A.R.: Multiplayer-Karten direkt aus dem Spiel lesen ------------------------------
# BUGFIX: Die Kartenliste kam bisher nur aus einer Options-Datei. Ohne eigene Datei (oder mit
# der eingebauten Vorlage) stand dort nur "Docks" - andere Karten waren nicht auswählbar.
# Jetzt werden zusätzlich die Spielarchive (*.Arch00, Format "LTAR" der Jupiter-EX-Engine)
# und lose Karten (Worlds\...\*.World00p, z. B. eigene Karten) gelesen.
# LTAR (Version 3, little-endian): Kopf 48 Bytes (u. a. Länge der Namenstabelle, Zahl der
# Ordner und Dateien), danach Namenstabelle, Dateieinträge (je 32 Bytes, erstes Feld =
# Namensposition) und Ordnereinträge (je 16 Bytes: Name, erstes Kind, nächster Bruder,
# Dateizahl). Die Dateien gehören der Reihe nach zu den Ordnern (Ordner 1 hat die ersten
# n Dateien usw.). Gelesen wird nur dieses Inhaltsverzeichnis, nicht die Spieldaten.
function Get-PelFearArchiveWorlds([string]$Path) {
    $res = New-Object System.Collections.Generic.List[string]
    $fs = $null
    try {
        $fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        $br = New-Object System.IO.BinaryReader($fs)
        if ($fs.Length -lt 48) { return $res.ToArray() }
        $magic = [System.Text.Encoding]::ASCII.GetString($br.ReadBytes(4))
        $ver = $br.ReadUInt32()
        if ($magic -ne 'LTAR' -or $ver -ne 3) { return $res.ToArray() }
        $nameLen = $br.ReadUInt32()
        $dirCount = $br.ReadUInt32()
        $fileCount = $br.ReadUInt32()
        # Plausibilität (beschädigte oder fremde Dateien nicht blind einlesen)
        if ($nameLen -gt 67108864 -or $dirCount -gt 200000 -or $fileCount -gt 2000000) { return $res.ToArray() }
        $need = 48 + [long]$nameLen + [long]$fileCount * 32 + [long]$dirCount * 16
        if ($need -gt $fs.Length) { return $res.ToArray() }
        $fs.Position = 48
        $names = $br.ReadBytes([int]$nameLen)
        $getName = {
            param([long]$Off)
            if ($Off -lt 0 -or $Off -ge $names.Length) { return '' }
            $e = [Array]::IndexOf($names, [byte]0, [int]$Off)
            if ($e -lt 0) { $e = $names.Length }
            return [System.Text.Encoding]::ASCII.GetString($names, [int]$Off, [int]($e - $Off))
        }
        $fileName = New-Object 'string[]' $fileCount
        for ($i = 0; $i -lt $fileCount; $i++) {
            $fileName[$i] = & $getName ([long]$br.ReadUInt32())
            [void]$br.ReadBytes(28)
        }
        $dName = New-Object 'string[]' $dirCount
        $dChild = New-Object 'int[]' $dirCount
        $dNext = New-Object 'int[]' $dirCount
        $dFiles = New-Object 'int[]' $dirCount
        $sum = [long]0
        for ($i = 0; $i -lt $dirCount; $i++) {
            $dName[$i] = & $getName ([long]$br.ReadUInt32())
            $dChild[$i] = $br.ReadInt32()
            $dNext[$i] = $br.ReadInt32()
            $dFiles[$i] = [int]$br.ReadUInt32()
            $sum += $dFiles[$i]
        }
        if ($sum -ne $fileCount) {
            # Aufbau unbekannt - lieber nichts als falsche Karten
            Write-PelLog "F.E.A.R.-Archiv ${Path}: Inhaltsverzeichnis nicht erkannt ($sum/$fileCount)." 'WARN'
            return $res.ToArray()
        }
        # Vollständige Ordnerpfade: entweder stehen sie schon im Namen (mit \), sonst über
        # den Baum (erstes Kind / nächster Bruder) ab Ordner 0 zusammensetzen
        $full = New-Object 'string[]' $dirCount
        $hasSep = $false
        foreach ($n in $dName) { if ($n -match '[\\/]') { $hasSep = $true; break } }
        if ($hasSep -or $dirCount -le 1) { for ($i = 0; $i -lt $dirCount; $i++) { $full[$i] = $dName[$i] -replace '/', '\' } }
        else {
            $stack = New-Object System.Collections.Generic.Stack[object]
            $stack.Push(@(0, ''))
            $guard = 0
            while ($stack.Count -gt 0 -and $guard -lt 400000) {
                $guard++
                $it = $stack.Pop()
                $ix = [int]$it[0]
                $parent = [string]$it[1]
                while ($ix -ge 0 -and $ix -lt $dirCount -and -not $full[$ix] -and $guard -lt 400000) {
                    $guard++
                    $p = if ($parent -and $dName[$ix]) { "$parent\$($dName[$ix])" } elseif ($dName[$ix]) { $dName[$ix] } else { $parent }
                    $full[$ix] = $(if ($p) { $p } else { '.' })
                    if ($dChild[$ix] -gt 0 -and $dChild[$ix] -lt $dirCount) { $stack.Push(@($dChild[$ix], $p)) }
                    $ix = $dNext[$ix]
                }
            }
        }
        $fi = 0
        for ($i = 0; $i -lt $dirCount; $i++) {
            $dir = [string]$full[$i]
            for ($k = 0; $k -lt $dFiles[$i]; $k++) {
                $fn = $fileName[$fi]
                $fi++
                if ($fn -notmatch '(?i)^(.+)\.world00p$') { continue }
                $base = $matches[1]
                if ($dir -notmatch '(?i)multiplayer') { continue }
                $mp = ($dir.Trim('\', '.') + '\' + $base)
                if ($mp -notmatch '(?i)^worlds\\') { $mp = 'Worlds\' + $mp }
                if (-not $res.Contains($mp)) { $res.Add($mp) }
            }
        }
    } catch {
        Write-PelLog "F.E.A.R.-Archiv $Path nicht lesbar: $($_.Exception.Message)" 'WARN'
    } finally { if ($fs) { $fs.Dispose() } }
    return $res.ToArray()
}

# Alle Multiplayer-Karten neben der Server-EXE: Archive (*.Arch00) im EXE-Ordner und eine
# Ebene darüber, dazu lose Karten unter Worlds\*Multiplayer*\*.World00p. Zwischengespeichert,
# bis sich die Dateien ändern.
$script:PelFearMapCache = @{}
function Get-PelFearMapList([string]$ExeDir) {
    if (-not $ExeDir -or -not [System.IO.Directory]::Exists($ExeDir)) { return @() }
    $dirs = New-Object System.Collections.Generic.List[string]
    $dirs.Add($ExeDir)
    try { $up = [System.IO.Path]::GetDirectoryName($ExeDir); if ($up) { $dirs.Add($up) } } catch { }
    $arch = New-Object System.Collections.Generic.List[object]
    foreach ($d in $dirs) {
        foreach ($f in @(Get-ChildItem -LiteralPath $d -Filter '*.Arch00' -File -ErrorAction SilentlyContinue | Sort-Object Name | Select-Object -First 60)) { $arch.Add($f) }
    }
    $loose = New-Object System.Collections.Generic.List[object]
    foreach ($d in $dirs) {
        $w = Join-Path $d 'Worlds'
        if (-not [System.IO.Directory]::Exists($w)) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $w -Filter '*.World00p' -File -Recurse -Depth 4 -ErrorAction SilentlyContinue | Select-Object -First 500)) { $loose.Add([pscustomobject]@{ Root = $d; File = $f }) }
    }
    # ToArray(): @(List[object]) wirft "Argument types do not match"
    $sig = (@($arch.ToArray() + @($loose | ForEach-Object { $_.File }) | ForEach-Object { '{0}|{1}|{2}' -f $_.FullName, $_.Length, $_.LastWriteTimeUtc.Ticks }) -join ';')
    $ck = $ExeDir.ToLowerInvariant()
    if ($script:PelFearMapCache.ContainsKey($ck) -and $script:PelFearMapCache[$ck].Sig -eq $sig) { return $script:PelFearMapCache[$ck].List }
    $list = New-Object System.Collections.Generic.List[string]
    foreach ($a in $arch) { foreach ($m in (Get-PelFearArchiveWorlds $a.FullName)) { if (-not $list.Contains($m)) { $list.Add($m) } } }
    foreach ($x in $loose) {
        $rel = $x.File.FullName.Substring($x.Root.Length).TrimStart('\', '/') -replace '/', '\' -replace '(?i)\.world00p$', ''
        if ($rel -notmatch '(?i)multiplayer') { continue }
        if (-not $list.Contains($rel)) { $list.Add($rel) }
    }
    $arr = @($list | Sort-Object)
    $script:PelFearMapCache[$ck] = @{ Sig = $sig; List = $arr }
    return $arr
}

# ---- Jedi Academy: server.cfg als Menü und Karten aus dem base-Ordner ---------------------
# Das Fenster "server.cfg & Maps" im Server-Baukasten zeigt alle wichtigen Einstellungen in
# derselben Reihenfolge wie eine typische server.cfg (Abschnitte 1-5), dazu alle übrigen
# Zeilen der bisherigen Datei (unverändert übernommen - z. B. ClanMod-Werte, exec-Zeilen)
# und die Map-Rotation (immer am Ende). Daraus schreibt der Baukasten die PEL_-Kopie.
# Typen: text, pass (Passwort, sichtbar), int (Min/Max), bool (0/1), list (feste Auswahl),
# mask (Zahl mit Vorschlägen - Bitmasken wie g_weaponDisable, eigene Zahl erlaubt).
# Achtung: g_gametype in Jedi Academy: 7 = Siege, 8 = CTF (in vielen Beispiel-Configs aus
# dem Netz vertauscht). Die Werte hier stammen aus dem Spielcode (gametype_t).
function Get-PelJkaCvarDefs {
    $d = {
        param([int]$Sec, [string]$Name, [string]$Type, $Def, [string]$De, [string]$En, [int]$Min = 0, [int]$Max = 0, $Choices = $null)
        [pscustomobject]@{ Sec = $Sec; Name = $Name; Type = $Type; Default = [string]$Def; Label = (Get-PelText $De $En); Min = $Min; Max = $Max; Choices = $Choices }
    }
    $modes = @(@('0', 'Free For All (FFA)'), @('1', 'Holocron'), @('2', 'Jedi Master'), @('3', (Get-PelText 'Duel (1 gegen 1)' 'Duel (1 vs 1)')), @('4', (Get-PelText 'Power Duel (2 gegen 1)' 'Power Duel (2 vs 1)')), @('6', 'Team FFA'), @('7', 'Siege'), @('8', 'Capture The Flag (CTF)'), @('9', 'Capture The Ysalamiri (CTY)'))
    $ranks = @(@('0', (Get-PelText 'keine Macht' 'no force')), @('1', 'Initiate'), @('2', 'Padawan'), @('3', 'Jedi'), @('4', 'Jedi Adept'), @('5', 'Jedi Guardian'), @('6', 'Jedi Knight'), @('7', (Get-PelText 'Jedi-Meister' 'Jedi Master')))
    $weap = @(@('0', (Get-PelText 'alle Waffen erlaubt' 'all weapons allowed')), @('524279', (Get-PelText 'nur Lichtschwert' 'saber only')))
    $force = @(@('0', (Get-PelText 'alle Machtkräfte erlaubt' 'all force powers allowed')), @('163837', (Get-PelText 'keine Machtkräfte' 'no force powers')))
    return @(
        (& $d 1 'sv_hostname' 'text' 'Project Earth LAN' 'Servername (Farbcodes ^1-^7 erlaubt)' 'Server name (colour codes ^1-^7 allowed)')
        (& $d 1 'g_motd' 'text' '' 'Begrüßung (Message of the Day, Ladebildschirm)' 'Message of the day (loading screen)')
        (& $d 1 'sv_maxclients' 'int' 16 'Maximale Spieleranzahl' 'Maximum players' 1 32)
        (& $d 1 'sv_privateClients' 'int' 0 'Reservierte Slots für Admins/VIPs' 'Reserved slots for admins/VIPs' 0 32)
        (& $d 1 'sv_privatePassword' 'pass' '' 'Passwort für die reservierten Slots' 'Password for the reserved slots')
        (& $d 1 'g_password' 'pass' '' 'Server-Passwort (leer = offen, g_needpass setzt der Baukasten)' 'Server password (empty = open, the builder sets g_needpass)')
        (& $d 1 'rconPassword' 'pass' '' 'RCON-Passwort für die Fernwartung (sehr wichtig!)' 'RCON password for remote admin (very important!)')
        (& $d 2 'sv_fps' 'int' 20 'Server-Tickrate (Standard 20)' 'Server tick rate (default 20)' 10 125)
        (& $d 2 'sv_maxRate' 'int' 25000 'Maximale Bandbreite pro Spieler (0 = unbegrenzt)' 'Maximum bandwidth per player (0 = unlimited)' 0 100000)
        (& $d 2 'sv_pure' 'bool' 1 'Nur originale Spieldateien (Anti-Cheat)' 'Original game files only (anti-cheat)')
        (& $d 2 'sv_allowDownload' 'bool' 0 'Spieler dürfen fehlende Karten/Skins laden' 'Players may download missing maps/skins')
        (& $d 2 'sv_floodProtect' 'bool' 1 'Schutz vor Chat-Spam' 'Chat spam protection')
        (& $d 2 'sv_minPing' 'int' 0 'Mindest-Ping (0 = aus)' 'Minimum ping (0 = off)' 0 999)
        (& $d 2 'sv_maxPing' 'int' 0 'Höchst-Ping (0 = aus)' 'Maximum ping (0 = off)' 0 999)
        (& $d 2 'sv_cheats' 'bool' 0 'Cheats erlauben (nur zum Testen)' 'Allow cheats (testing only)')
        (& $d 3 'g_gametype' 'list' 0 'Spielmodus' 'Game mode' 0 0 $modes)
        (& $d 3 'fraglimit' 'int' 30 'Kill-Limit pro Map (0 = aus)' 'Kill limit per map (0 = off)' 0 9999)
        (& $d 3 'duel_fraglimit' 'int' 10 'Gewonnene Duelle bis zum Mapwechsel (Duell-Modi)' 'Duels won until map change (duel modes)' 0 999)
        (& $d 3 'timelimit' 'int' 20 'Zeitlimit pro Map in Minuten (0 = aus)' 'Time limit per map in minutes (0 = off)' 0 999)
        (& $d 3 'capturelimit' 'int' 10 'Flaggen-Limit (CTF/CTY, 0 = aus)' 'Capture limit (CTF/CTY, 0 = off)' 0 999)
        (& $d 4 'g_weaponDisable' 'mask' 0 'Waffen sperren (Bitmaske)' 'Disable weapons (bit mask)' 0 0 $weap)
        (& $d 4 'g_duelWeaponDisable' 'mask' 524279 'Waffen sperren im Duell (Bitmaske)' 'Disable weapons in duel (bit mask)' 0 0 $weap)
        (& $d 4 'g_forcePowerDisable' 'mask' 0 'Machtkräfte sperren (Bitmaske)' 'Disable force powers (bit mask)' 0 0 $force)
        (& $d 4 'g_maxForceRank' 'list' 7 'Maximale Machtstufe (7 = Jedi-Meister)' 'Maximum force rank (7 = Jedi Master)' 0 0 $ranks)
        (& $d 4 'g_forceRegenTime' 'int' 200 'Macht-Regeneration in ms (kleiner = schneller)' 'Force regeneration in ms (lower = faster)' 0 10000)
        (& $d 4 'g_forceBasedTeams' 'bool' 0 'Helle/Dunkle Seite bestimmt das Team' 'Light/dark side decides the team')
        (& $d 4 'g_saberLocking' 'bool' 1 'Lichtschwert-Gefechte (Saber Locks)' 'Saber locks')
        (& $d 4 'g_dismember' 'int' 0 'Abtrennen von Gliedmaßen (0 = aus, 100 = immer)' 'Dismemberment (0 = off, 100 = always)' 0 100)
        (& $d 4 'g_friendlyFire' 'bool' 0 'Eigenbeschuss im Team' 'Friendly fire')
        (& $d 4 'g_allowVote' 'bool' 1 'Abstimmungen erlauben (Map, Kick ...)' 'Allow votes (map, kick ...)')
        (& $d 4 'g_allowNPC' 'bool' 0 'NPCs erlauben (Befehl npc spawn)' 'Allow NPCs (npc spawn command)')
        (& $d 5 'bot_enable' 'bool' 1 'Bots erlauben' 'Allow bots')
        (& $d 5 'bot_minplayers' 'int' 0 'Freie Plätze bis zu dieser Zahl mit Bots füllen (0 = aus)' 'Fill free slots with bots up to this number (0 = off)' 0 32)
    )
}

function Get-PelJkaCfgSectionName([int]$Sec) {
    switch ($Sec) {
        1 { return (Get-PelText 'Server-Identifikation & Basis-Einstellungen' 'Server identification & basic settings') }
        2 { return (Get-PelText 'Netzwerk- & Performance-Einstellungen' 'Network & performance settings') }
        3 { return (Get-PelText 'Spielmodus-Konfiguration' 'Game mode configuration') }
        4 { return (Get-PelText 'Gameplay & Lichtschwert-Einstellungen' 'Gameplay & saber settings') }
        5 { return (Get-PelText 'Bot-Einstellungen' 'Bot settings') }
        6 { return (Get-PelText 'Map-Rotation' 'Map rotation') }
        default { return (Get-PelText 'Weitere Einstellungen (aus der bisherigen server.cfg)' 'More settings (from the previous server.cfg)') }
    }
}

function New-PelJkaCfgModel {
    return [pscustomobject]@{
        Vars = [ordered]@{}; Extra = (New-Object System.Collections.Generic.List[string])
        Rotation = (New-Object System.Collections.Generic.List[string]); StartMap = ''
    }
}

# Gespeichertes Modell (aus .pel.json oder dem Fenster) in eine saubere Form bringen
function ConvertTo-PelJkaCfgModel($Obj) {
    $m = New-PelJkaCfgModel
    if (-not $Obj) { return $m }
    if ($Obj.Vars -is [System.Collections.IDictionary]) { foreach ($k in @($Obj.Vars.Keys)) { $m.Vars[[string]$k] = [string]$Obj.Vars[$k] } }
    elseif ($Obj.Vars) { foreach ($p in $Obj.Vars.PSObject.Properties) { $m.Vars[[string]$p.Name] = [string]$p.Value } }
    # foreach direkt über die Liste: @(List[string]) wirft "Argument types do not match"
    foreach ($x in $Obj.Extra) { if ($null -ne $x -and $m.Extra.Count -lt 2000) { $m.Extra.Add([string]$x) } }
    foreach ($x in $Obj.Rotation) { if ($x -and $m.Rotation.Count -lt 100) { $m.Rotation.Add([string]$x) } }
    $m.StartMap = [string]$Obj.StartMap
    return $m
}

# Wert hinter "set NAME": in Anführungszeichen bis zum nächsten ", sonst bis zum Kommentar
function Get-PelQ3CfgValue([string]$Rest) {
    $r = ([string]$Rest).Trim()
    if ($r.StartsWith('"')) {
        $e = $r.IndexOf('"', 1)
        if ($e -gt 0) { return $r.Substring(1, $e - 1) }
        return $r.Substring(1)
    }
    $c = $r.IndexOf('//')
    if ($c -ge 0) { $r = $r.Substring(0, $c) }
    return $r.Trim()
}

# Wert für die .cfg: keine Anführungszeichen, kein ";" (würde in der Konsole einen zweiten
# Befehl starten) und keine Zeilenumbrüche. Farbcodes (^1) bleiben erhalten.
function ConvertTo-PelQ3CfgText([string]$Text, [int]$Max = 100) {
    return (Limit-PelText ((([string]$Text) -replace '["`;]', '') -replace '[\x00-\x1f]', ' ') $Max)
}

# Kartenname für map/vstr: nur Buchstaben, Ziffern, / _ - .
function ConvertTo-PelJkaMapName([string]$Map) {
    $m = (([string]$Map).Trim().Trim('"') -replace '\\', '/')
    if ($m -notmatch '^[A-Za-z0-9_./-]{1,64}$' -or $m -match '\.\.') { return '' }
    return $m
}

# server.cfg (oder Vorlage) einlesen: bekannte Einstellungen -> Vars, Rotation aus den
# "set dN ""map ...; set nextmap vstr dM"""-Zeilen bzw. der map-Zeile, alles andere (ohne
# Kommentare) -> Extra.
function Read-PelJkaCfgText([string]$Text) {
    $known = @{}
    foreach ($x in Get-PelJkaCvarDefs) { $known[$x.Name.ToLowerInvariant()] = $x.Name }
    $m = New-PelJkaCfgModel
    $rot = @{}
    $startVstr = ''
    foreach ($raw in ((([string]$Text) -replace "`r", '') -split "`n")) {
        $l = $raw.Trim()
        if (-not $l -or $l.StartsWith('//')) { continue }
        if ($l -match '^(?i)(seta|set|sets|setu)\s+"?([A-Za-z0-9_]+)"?\s*(.*)$') {
            $n = $matches[2]
            $v = Get-PelQ3CfgValue $matches[3]
            $key = $n.ToLowerInvariant()
            if ($key -eq 'g_needpass' -or $key -eq 'nextmap') { continue }
            if ($known.ContainsKey($key)) { $m.Vars[$known[$key]] = $v; continue }
            if ($v -match '(?i)vstr') {
                $mp = ''; $nx = ''
                if ($v -match '(?i)(^|;)\s*(map|devmap)\s+([^\s;"]+)') { $mp = $matches[3] }
                if ($v -match '(?i)nextmap\s+"?vstr\s+([A-Za-z0-9_]+)') { $nx = $matches[1].ToLowerInvariant() }
                if ($mp) { $rot[$key] = [pscustomobject]@{ Map = $mp; Next = $nx }; continue }
            }
            $m.Extra.Add($l)
            continue
        }
        if ($l -match '^(?i)(map|devmap)\s+"?([^\s";]+)') { $m.StartMap = $matches[2]; continue }
        if ($l -match '^(?i)vstr\s+"?([A-Za-z0-9_]+)') { $startVstr = $matches[1].ToLowerInvariant(); continue }
        $m.Extra.Add($l)
    }
    if ($rot.Count -gt 0) {
        # Reihenfolge der nextmap-Kette folgen (ab dem vstr-Start), Rest nach Namen (d2 vor d10)
        $keys = @($rot.Keys | Sort-Object { [regex]::Replace([string]$_, '\d+', { param($mm) $mm.Value.PadLeft(6, '0') }) })
        $cur = if ($startVstr -and $rot.ContainsKey($startVstr)) { $startVstr } else { $keys[0] }
        $seen = @{}
        while ($cur -and $rot.ContainsKey($cur) -and -not $seen.ContainsKey($cur)) {
            $seen[$cur] = $true
            $m.Rotation.Add([string]$rot[$cur].Map)
            $cur = [string]$rot[$cur].Next
        }
        foreach ($k in $keys) { if (-not $seen.ContainsKey($k)) { $m.Rotation.Add([string]$rot[$k].Map) } }
        if (-not $m.StartMap -and $m.Rotation.Count -gt 0) { $m.StartMap = $m.Rotation[0] }
    }
    return $m
}

# Grundlage für ein neues Menü: server.cfg im base- bzw. Mod-Ordner, sonst eingebaute Vorlage
function Get-PelJkaCfgBase($Tpl, [string]$ExeDir) {
    $sub = if ($Tpl.FsGame) { [string]$Tpl.FsGame } else { 'base' }
    $src = if ($ExeDir) { Join-Path (Join-Path $ExeDir $sub) 'server.cfg' } else { '' }
    $txt = ''
    $from = ''
    try { if ($src -and [System.IO.File]::Exists($src)) { $txt = Read-PelTextFile $src; $from = $src } } catch { $txt = '' }
    if (-not $from) { $txt = Get-PelJkaCfgTemplate ([bool]$Tpl.FsGame) }
    return [pscustomobject]@{ Model = (Read-PelJkaCfgText $txt); Source = $from }
}

# Wert einer Einstellung im Modell (Groß-/Kleinschreibung egal) oder $null
function Get-PelJkaCfgVar($Model, [string]$Name) {
    foreach ($k in @($Model.Vars.Keys)) { if ([string]$k -ieq $Name) { return [string]$Model.Vars[$k] } }
    return $null
}

function Set-PelJkaCfgVar($Model, [string]$Name, [string]$Value) {
    foreach ($k in @($Model.Vars.Keys)) { if ([string]$k -ieq $Name -and [string]$k -cne $Name) { $Model.Vars.Remove($k) } }
    $Model.Vars[$Name] = $Value
}

# Fertige server.cfg im Aufbau der Vorlage (Abschnitte 1-5, weitere Zeilen, Map-Rotation). $StartMap: Karte, mit der der
# Server startet; Rotation ab 2 Karten über "set dN ... vstr", sonst nur "map ...".
# $CfgDir: exec-Zeilen für Dateien, die dort fehlen, werden auskommentiert.
function ConvertTo-PelJkaCfgText($Model, [string]$StartMap = '', [string]$CfgDir = '', [string]$Title = 'Jedi Academy') {
    $out = New-Object System.Collections.Generic.List[string]
    $bar = '// ' + ('=' * 67)
    $sub = '// ' + ('-' * 67)
    $line = {
        param([string]$Cmd, [string]$Comment)
        if (-not $Comment) { return $Cmd }
        return ($Cmd.PadRight(41) + ' // ' + $Comment)
    }
    $out.Add($bar)
    $out.Add('// ' + (ConvertTo-PelQ3CfgText ($Title.ToUpperInvariant() + ' - SERVER CONFIGURATION (server.cfg)') 80))
    $out.Add('// ' + ((Get-PelText 'Erstellt vom Project Earth LAN Manager (Server-Baukasten) am {0}' 'Created by Project Earth LAN Manager (server builder) on {0}') -f (Get-Date -Format 'dd.MM.yyyy HH:mm')))
    $out.Add($bar)
    $defs = @(Get-PelJkaCvarDefs)
    for ($sec = 1; $sec -le 5; $sec++) {
        $out.Add('')
        $out.Add($sub)
        $out.Add("// $sec. " + (Get-PelJkaCfgSectionName $sec))
        $out.Add($sub)
        foreach ($df in @($defs | Where-Object { $_.Sec -eq $sec })) {
            $v = Get-PelJkaCfgVar $Model $df.Name
            if ($null -eq $v) { $v = $df.Default }
            if ($df.Type -in @('text', 'pass')) {
                $max = if ($df.Name -eq 'g_motd') { 150 } else { 64 }
                $val = '"' + (ConvertTo-PelQ3CfgText $v $max) + '"'
            } else {
                $n = 0
                $val = if ([int]::TryParse(([string]$v).Trim(), [ref]$n)) { [string]$n } else { [string]$df.Default }
                if ($df.Type -eq 'bool') { $val = $(if ($val -ne '0') { '1' } else { '0' }) }
                if ($df.Type -eq 'int' -and $df.Max -gt 0) { $val = [string][Math]::Max($df.Min, [Math]::Min($df.Max, [int]$val)) }
            }
            if ($df.Name -eq 'g_gametype') {
                $out.Add((Get-PelText '// g_gametype Optionen:' '// g_gametype options:'))
                $out.Add('// 0 = Free For All (FFA)     4 = Power Duel     8 = Capture The Flag (CTF)')
                $out.Add('// 1 = Holocron               6 = Team FFA       9 = Capture The Ysalamiri')
                $out.Add('// 2 = Jedi Master            7 = Siege')
                $out.Add('// 3 = Duel')
            }
            if ($df.Name -eq 'g_password') {
                # g_needpass passend zum Passwort - so kann es nicht vergessen werden
                $pwSet = [bool](ConvertTo-PelQ3CfgText $v 64)
                $out.Add((& $line ('seta g_needpass ' + $(if ($pwSet) { '1' } else { '0' })) (Get-PelText '1 = Passwortschutz aktiv (automatisch)' '1 = password protection active (automatic)')))
            }
            $out.Add((& $line "seta $($df.Name) $val" $df.Label))
        }
    }
    # 7. übrige Zeilen der bisherigen server.cfg (ClanMod, exec ...)
    $extra = New-Object System.Collections.Generic.List[string]
    foreach ($x in $Model.Extra) {
        $t = ([string]$x).Trim()
        if (-not $t) { continue }
        # Rotation und Start stehen in Abschnitt 6 - doppelte Startbefehle hier auslassen
        if ($t -match '^(?i)(map|devmap|vstr)\s') { continue }
        if ($CfgDir -and $t -match '^(?i)exec\s+"?([^"\s]+)"?') {
            $f = $matches[1]
            if (-not [System.IO.File]::Exists((Join-Path $CfgDir $f))) { $t = "// $t   (PEL: Datei fehlt)" }
        }
        $extra.Add($t)
    }
    # Nummern fortlaufend: mit weiteren Zeilen sind diese 6. und die Rotation 7., sonst 6.
    $rotNo = 6
    if ($extra.Count -gt 0) {
        $out.Add('')
        $out.Add($sub)
        $out.Add('// 6. ' + (Get-PelJkaCfgSectionName 7))
        $out.Add($sub)
        foreach ($t in $extra) { $out.Add($t) }
        $rotNo = 7
    }
    # Map-Rotation (am Ende, weil "map"/"vstr" den Server starten)
    $rot = New-Object System.Collections.Generic.List[string]
    foreach ($r in $Model.Rotation) { $mm = ConvertTo-PelJkaMapName $r; if ($mm -and $rot.Count -lt 60) { $rot.Add($mm) } }
    $start = ConvertTo-PelJkaMapName $StartMap
    if (-not $start) { $start = ConvertTo-PelJkaMapName $Model.StartMap }
    $out.Add('')
    $out.Add($sub)
    $out.Add("// $rotNo. " + (Get-PelJkaCfgSectionName 6))
    $out.Add($sub)
    if ($rot.Count -ge 2) {
        $si = -1
        for ($i = 0; $i -lt $rot.Count; $i++) { if ($rot[$i] -ieq $start) { $si = $i; break } }
        if ($si -lt 0 -and $start) { $rot.Insert(0, $start); $si = 0 }
        if ($si -lt 0) { $si = 0 }
        for ($i = 0; $i -lt $rot.Count; $i++) {
            $nx = if ($i + 1 -lt $rot.Count) { $i + 2 } else { 1 }
            $out.Add(('set d{0} "map {1}; set nextmap vstr d{2}"' -f ($i + 1), $rot[$i], $nx))
        }
        $out.Add((& $line "vstr d$($si + 1)" ((Get-PelText 'Startet die Rotation mit {0}' 'Starts the rotation with {0}') -f $rot[$si])))
    } else {
        if (-not $start) { $start = if ($rot.Count -gt 0) { $rot[0] } else { 'mp/ffa1' } }
        $out.Add((& $line "map $start" (Get-PelText 'Startkarte (für eine Rotation mindestens 2 Karten wählen)' 'Start map (choose at least 2 maps for a rotation)')))
    }
    return (($out -join "`r`n") + "`r`n")
}

# Karten in einer .pk3 (ZIP): maps/*.bsp -> "mp/ffa1", dazu Name und Spielmodi aus
# scripts/*.arena. Gelesen wird nur das Inhaltsverzeichnis (schnell, auch bei assets0.pk3).
function Get-PelPk3Maps([string]$Path, [string]$Label = '') {
    $res = New-Object System.Collections.Generic.List[object]
    try { Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop } catch { }
    $zip = $null
    $arena = @{}
    try {
        $zip = [System.IO.Compression.ZipFile]::OpenRead($Path)
        foreach ($en in $zip.Entries) {
            $fn = ([string]$en.FullName) -replace '\\', '/'
            if ($fn -match '^(?i)maps/(.+)\.bsp$') {
                $res.Add([pscustomobject]@{ Map = $matches[1]; LongName = ''; Types = ''; Source = $(if ($Label) { $Label } else { [System.IO.Path]::GetFileName($Path) }) })
            } elseif ($fn -match '^(?i)scripts/[^/]+\.arena$' -and $en.Length -lt 262144) {
                $sr = $null
                try {
                    $sr = New-Object System.IO.StreamReader($en.Open())
                    $at = $sr.ReadToEnd()
                    foreach ($blk in [regex]::Matches($at, '\{([^}]*)\}')) {
                        $b = $blk.Groups[1].Value
                        $mm = [regex]::Match($b, '(?i)\bmap\s+"([^"]+)"')
                        if (-not $mm.Success) { continue }
                        $ln = [regex]::Match($b, '(?i)\blongname\s+"([^"]+)"')
                        $ty = [regex]::Match($b, '(?i)\btype\s+"([^"]+)"')
                        $arena[$mm.Groups[1].Value.ToLowerInvariant()] = @{ Long = $(if ($ln.Success) { $ln.Groups[1].Value } else { '' }); Types = $(if ($ty.Success) { $ty.Groups[1].Value } else { '' }) }
                    }
                } catch { } finally { if ($sr) { $sr.Dispose() } }
            }
        }
    } catch {
        Write-PelLog "Karten aus $Path nicht lesbar: $($_.Exception.Message)" 'WARN'
    } finally { if ($zip) { $zip.Dispose() } }
    foreach ($r in $res) {
        $a = $arena[([string]$r.Map).ToLowerInvariant()]
        if ($a) { $r.LongName = Limit-PelText $a.Long 60; $r.Types = Limit-PelText $a.Types 80 }
    }
    return $res.ToArray()
}

# Alle Karten im base-Ordner (und im Mod-Ordner, z. B. clanmod): .pk3-Archive und lose
# maps\*.bsp. Ergebnis wird zwischengespeichert, bis sich die Dateien ändern.
$script:PelJkaMapCache = @{}
function Get-PelJkaMapList([string]$ExeDir, [string]$FsGame = '', [switch]$Force) {
    if (-not $ExeDir -or -not [System.IO.Directory]::Exists($ExeDir)) { return @() }
    $subs = @('base')
    if ($FsGame -and $FsGame -ine 'base') { $subs += $FsGame }
    $files = New-Object System.Collections.Generic.List[object]
    foreach ($s in $subs) {
        $dir = Join-Path $ExeDir $s
        if (-not [System.IO.Directory]::Exists($dir)) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter '*.pk3' -File -ErrorAction SilentlyContinue | Sort-Object Name | Select-Object -First 500)) { $files.Add([pscustomobject]@{ Sub = $s; File = $f }) }
        $md = Join-Path $dir 'maps'
        if ([System.IO.Directory]::Exists($md)) {
            foreach ($f in @(Get-ChildItem -LiteralPath $md -Filter '*.bsp' -File -Recurse -Depth 3 -ErrorAction SilentlyContinue | Select-Object -First 500)) { $files.Add([pscustomobject]@{ Sub = $s; File = $f }) }
        }
    }
    $sig = (@($files | ForEach-Object { '{0}|{1}|{2}' -f $_.File.FullName, $_.File.Length, $_.File.LastWriteTimeUtc.Ticks }) -join ';')
    $ck = ("$ExeDir|$FsGame").ToLowerInvariant()
    if (-not $Force -and $script:PelJkaMapCache.ContainsKey($ck) -and $script:PelJkaMapCache[$ck].Sig -eq $sig) { return $script:PelJkaMapCache[$ck].List }
    $all = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($x in $files) {
        if ($x.File.Extension -ieq '.pk3') {
            foreach ($r in (Get-PelPk3Maps $x.File.FullName "$($x.Sub)\$($x.File.Name)")) {
                $k = ([string]$r.Map).ToLowerInvariant()
                if ($seen.ContainsKey($k)) { continue }
                $seen[$k] = $true
                $all.Add($r)
            }
        } else {
            $root = Join-Path (Join-Path $ExeDir $x.Sub) 'maps'
            $rel = $x.File.FullName.Substring($root.Length).TrimStart('\', '/') -replace '\\', '/'
            $mapName = $rel -replace '(?i)\.bsp$', ''
            $k = $mapName.ToLowerInvariant()
            if ($seen.ContainsKey($k)) { continue }
            $seen[$k] = $true
            $all.Add([pscustomobject]@{ Map = $mapName; LongName = ''; Types = ''; Source = "$($x.Sub)\maps" })
        }
    }
    $list = @($all | Sort-Object Map)
    $script:PelJkaMapCache[$ck] = @{ Sig = $sig; List = $list }
    return $list
}

# Karten aus dem Spielordner (falls vorhanden), sonst die bekannten Standardkarten
function Get-PelServerMaps($Tpl, [string]$ExeDir, [string]$Mode = '', [string]$OptionsFile = '') {
    $maps = New-Object System.Collections.Generic.List[string]
    if ($Tpl.Key -eq 'fear') {
        # F.E.A.R.: Karten aus der Options-Datei - erst die des Spielmodus, sonst alle
        # aus allen Options-Dateien im selben Ordner; sonst aus der eingebauten Vorlage
        $src = Find-PelFearExampleOptions $ExeDir $OptionsFile
        $all = New-Object System.Collections.Generic.List[string]
        foreach ($f in (Get-PelFearOptionFiles $src)) {
            $txt = ''
            try { $txt = Read-PelTextFile $f } catch { continue }
            $sec = Resolve-PelFearSection $txt $Mode -Strict
            if ($sec) { foreach ($m in (Get-PelFearMissions $f $sec)) { if (-not $maps.Contains($m)) { $maps.Add($m) } } }
            foreach ($m in (Get-PelFearMissions $f '')) { if (-not $all.Contains($m)) { $all.Add($m) } }
        }
        if ($maps.Count -eq 0) { foreach ($m in $all) { $maps.Add($m) } }
        # dazu alle Multiplayer-Karten aus den Spielarchiven und eigene (lose) Karten
        try { foreach ($m in @(Get-PelFearMapList $ExeDir)) { $hit = $false; foreach ($x in $maps) { if ($x -ieq $m) { $hit = $true; break } }; if (-not $hit) { $maps.Add($m) } } } catch { }
        if ($maps.Count -eq 0) { $maps.Add('Worlds\ReleaseMultiplayer\Docks') }
        return , $maps
    }
    if ($Tpl.MapDir -and $ExeDir) {
        try {
            $md = [System.IO.Path]::GetFullPath((Join-Path $ExeDir $Tpl.MapDir))
            if ([System.IO.Directory]::Exists($md)) {
                foreach ($f in @(Get-ChildItem -LiteralPath $md -Filter $Tpl.MapExt -File -ErrorAction SilentlyContinue | Sort-Object Name | Select-Object -First 300)) { $maps.Add([System.IO.Path]::GetFileNameWithoutExtension($f.Name)) }
            }
        } catch { }
    }
    # Jedi Academy: Karten aus den .pk3-Archiven im base- bzw. Mod-Ordner (auch eigene Karten)
    if ($Tpl.Key -in @('jka', 'jkaclan') -and $ExeDir) {
        try { foreach ($x in @(Get-PelJkaMapList $ExeDir ([string]$Tpl.FsGame))) { if (-not $maps.Contains([string]$x.Map)) { $maps.Add([string]$x.Map) } } } catch { }
    }
    foreach ($m in @($Tpl.Maps)) { if (-not $maps.Contains($m)) { $maps.Add($m) } }
    return , $maps
}

# Server-EXE zur Vorlage suchen: Spielebibliothek (auch eine Ebene darüber/darunter),
# Steam-Ordner. Rückgabe: vollständiger Pfad oder ''.
function Find-PelServerExe($Tpl) {
    if (@($Tpl.Exe).Count -eq 0) { return '' }
    $dirs = New-Object System.Collections.Generic.List[string]
    # zuerst die über SteamCMD geladenen Server
    try {
        $sroot = Join-Path $script:PelSteamCmdDir 'servers'
        if ([System.IO.Directory]::Exists($sroot)) { foreach ($sd in [System.IO.Directory]::GetDirectories($sroot)) { $dirs.Add($sd) } }
    } catch { }
    try {
        foreach ($g in @((Get-PelGameLibrary).Games | Where-Object { -not $_.Hidden -and $_.Exe })) {
            $d = [System.IO.Path]::GetDirectoryName([string]$g.Exe)
            if ($d -and -not $dirs.Contains($d)) { $dirs.Add($d) }
            $up = [System.IO.Path]::GetDirectoryName($d)
            if ($up -and -not $dirs.Contains($up)) { $dirs.Add($up) }
        }
    } catch { }
    try { foreach ($sc in @(Get-PelSteamCommonFolders)) { foreach ($d in @(Get-ChildItem -LiteralPath $sc -Directory -ErrorAction SilentlyContinue)) { $dirs.Add($d.FullName) } } } catch { }
    foreach ($d in $dirs) {
        foreach ($sub in @('', 'System', 'GameData', 'bin', 'game\bin\win64')) {
            foreach ($x in @($Tpl.Exe)) {
                $p = if ($sub) { Join-Path (Join-Path $d $sub) $x } else { Join-Path $d $x }
                try {
                    if ([System.IO.File]::Exists($p)) {
                        # hlds/srcds gibt es für viele Spiele - nur nehmen, wenn der Spielordner (z. B. tf) daneben liegt
                        if ($Tpl.Game -and -not [System.IO.Directory]::Exists((Join-Path ([System.IO.Path]::GetDirectoryName($p)) $Tpl.Game))) { continue }
                        return $p
                    }
                } catch { }
            }
        }
    }
    return ''
}

# Baut die Startzeile. $Cfg: Key, Name, Exe, Port, Max, Password, Mode, Map, Internet, Extra.
# -WriteFiles: nötige Einstellungsdateien (F.E.A.R., UT2004) wirklich anlegen.
# Rückgabe: Args (Parameterzeile), Notes (Hinweise), Files (angelegte Dateien), Ports.
function New-PelServerCommand($Cfg, [switch]$WriteFiles) {
    $tpl = Get-PelServerTemplate ([string]$Cfg.Key)
    $r = [pscustomobject]@{ Args = ''; Notes = (New-Object System.Collections.Generic.List[string]); Files = (New-Object System.Collections.Generic.List[string]); Ports = @() }
    if (-not $tpl) { $r.Notes.Add('Unbekannte Vorlage.'); return $r }
    $name = ConvertTo-PelServerSafe $Cfg.Name 60
    if (-not $name) { $name = 'Project Earth LAN' }
    $pw = ConvertTo-PelServerSafe $Cfg.Password 32
    $port = [int]$Cfg.Port
    if ($port -lt 1024 -or $port -gt 65535) { $port = [int]$tpl.Port }
    $max = [Math]::Max(2, [Math]::Min(64, [int]$Cfg.Max))
    $map = ConvertTo-PelServerSafe $Cfg.Map 64
    $mode = ConvertTo-PelServerSafe $Cfg.Mode 60
    $exe = [string]$Cfg.Exe
    $exeDir = if ($exe) { [System.IO.Path]::GetDirectoryName($exe) } else { '' }
    $slug = ConvertTo-PelServerSlug ("$($tpl.Key)_$name")
    $a = New-Object System.Collections.Generic.List[string]
    $r.Ports = @("$port")
    switch ($tpl.Key) {
        'fear' {
            # Grundlage: gefundene/gewählte Options-Datei, sonst die eingebaute Vorlage.
            # Die Kopie (PEL_...) kommt in den ServerOptions-Ordner des Servers.
            $gt = if ($mode) { $mode } else { 'DeathMatch' }
            $ex = Find-PelFearExampleOptions $exeDir ([string]$Cfg.OptionsFile)
            if ($ex) {
                $optDir = [System.IO.Path]::GetDirectoryName($ex)
                $r.Notes.Add(((Get-PelText 'Grundlage: {0}' 'Based on: {0}') -f $ex))
            } else {
                $pub = if ($env:PUBLIC) { Join-Path $env:PUBLIC 'Documents' } else { [Environment]::GetFolderPath('CommonDocuments') }
                $optDir = Join-Path $pub 'Monolith Productions\FEAR\ServerOptions'
                $r.Notes.Add(((Get-PelText 'Keine eigene Options-Datei gefunden - es wird die eingebaute F.E.A.R.-Combat-Vorlage benutzt (Ablage: {0}). Eigene Datei über "Options-Datei ..." wählen.' 'No own options file found - the built-in F.E.A.R. Combat template is used (stored in: {0}). Pick your own file via "Options file ...".') -f $optDir))
            }
            $opt = Join-Path $optDir ("PEL_$slug`_ServerOptions.txt")
            $mapPath = ConvertTo-PelFearMapPath $map
            $txt = if ($ex) { Read-PelTextFile $ex } else { $script:PelFearOptionsTemplate }
            # fehlt der Abschnitt für den Spielmodus, wird er aus dem bisherigen Modus übernommen
            $had = [bool](@((([string]$txt) -replace "`r", '') -split "`n" | Where-Object { $_ -match '^\s*\[(.+?)\]\s*$' -and $matches[1].Trim() -ieq $gt }).Count)
            if (-not $had) {
                $fromSec = Get-PelIniValue $txt 'ServerSettings' 'GameType'
                if (-not $fromSec) { $fromSec = 'DeathMatch' }
                $txt = Add-PelFearModeSection $txt $fromSec $gt
                $r.Notes.Add(((Get-PelText 'Abschnitt [{0}] fehlte in der Options-Datei und wurde aus [{1}] übernommen - die Karte muss zum Spielmodus passen.' 'Section [{0}] was missing in the options file and was taken from [{1}] - the map must fit the game mode.') -f $gt, $fromSec))
                if (-not $mapPath) { $r.Notes.Add((Get-PelText 'Bitte eine Karte für diesen Spielmodus eintragen.' 'Please enter a map for this game mode.')) }
            }
            $txt = Set-PelIniValues $txt 'ServerSettings' @{ GameType = $gt; Port = "$port"; UsePassword = $(if ($pw) { '1' } else { '0' }); Password = $pw; Dedicated = '1'; LANOnly = $(if ($Cfg.Internet) { '0' } else { '1' }) }
            $txt = Set-PelIniValues $txt $gt @{ SessionName = $name; MaxPlayers = "$max" }
            # Eigene Map-Rotation (ab 2 Karten) ersetzt alle MissionN-Zeilen des Modus,
            # sonst bleibt es beim bisherigen Verhalten (Startkarte vorne, Rest dahinter)
            $rot = Get-PelServerRotation $Cfg $mapPath -Fear
            if ($rot.Count -ge 2) {
                $txt = Set-PelIniList $txt $gt 'Mission' $rot -Indexed
                $r.Notes.Add(((Get-PelText 'Map-Rotation: {0} Karten, Start: {1}' 'Map rotation: {0} maps, start: {1}') -f $rot.Count, $rot[0]))
            } elseif ($mapPath) {
                $t2 = Set-PelFearStartMap $txt $gt $mapPath
                if ($null -ne $t2) { $txt = $t2 } else { $txt = Set-PelIniValues $txt $gt @{ Mission0 = $mapPath } }
            }
            if ($WriteFiles) {
                if (-not [System.IO.Directory]::Exists($optDir)) { [void][System.IO.Directory]::CreateDirectory($optDir) }
                [System.IO.File]::WriteAllText($opt, $txt, (New-Object System.Text.UTF8Encoding($false)))
                $r.Files.Add($opt)
            }
            $a.Add("-optionsfile `"$opt`"")
            $r.Ports = @("$port", "$($port + 1)")
        }
        'ut2004' {
            if (-not $map) { $map = 'DM-Rankin' }
            $gameClass = $(if ($mode) { $mode } else { 'XGame.xDeathMatch' })
            $url = "$map`?Game=$gameClass`?MaxPlayers=$max"
            $iniName = "PEL_$slug.ini"
            $srcIni = if ($exeDir) { Join-Path $exeDir 'UT2004.ini' } else { '' }
            $rot = Get-PelServerRotation $Cfg $map
            $rotSec = [string]$script:PelUtMapListSections[$gameClass]
            if ($rot.Count -ge 2) {
                if ($srcIni -and [System.IO.File]::Exists($srcIni) -and $rotSec) { $r.Notes.Add(((Get-PelText 'Map-Rotation: {0} Karten, Start: {1} (in [{2}])' 'Map rotation: {0} maps, start: {1} (in [{2}])') -f $rot.Count, $rot[0], $rotSec)) }
                else { $r.Notes.Add((Get-PelText 'Map-Rotation braucht die UT2004.ini neben der Server-EXE (System-Ordner) - ohne sie startet nur die Startkarte.' 'Map rotation needs UT2004.ini next to the server EXE (System folder) - without it only the start map runs.')) }
            }
            if ($srcIni -and [System.IO.File]::Exists($srcIni)) {
                if ($WriteFiles) {
                    $txt = Read-PelTextFile $srcIni
                    $txt = Set-PelIniValues $txt 'Engine.GameReplicationInfo' @{ ServerName = $name; ShortName = $name }
                    $txt = Set-PelIniValues $txt 'Engine.AccessControl' @{ GamePassword = $pw }
                    if ($rot.Count -ge 2 -and $rotSec) {
                        $txt = Set-PelIniList $txt $rotSec 'Maps' $rot
                        $txt = Set-PelIniValues $txt $rotSec @{ MapNum = '0' }
                    }
                    $iniPath = Join-Path $exeDir $iniName
                    [System.IO.File]::WriteAllText($iniPath, $txt, (New-Object System.Text.UTF8Encoding($false)))
                    $r.Files.Add($iniPath)
                }
                $a.Add("server $url port=$port ini=$iniName log=PEL_$slug.log")
            } else {
                $r.Notes.Add((Get-PelText 'UT2004.ini nicht gefunden - Servername und Passwort bleiben wie in der Standard-Einstellung.' 'UT2004.ini not found - server name and password stay at the default settings.'))
                $a.Add("server $url port=$port log=PEL_$slug.log")
            }
            $r.Ports = @("$port-$($port + 1)", "$($port + 10)")
        }
        { [bool]$tpl.Srcds } {
            # hlds/srcds: CS 1.6, CS:Source, TF2, L4D2, Garry's Mod, DoD:S, HL2DM
            if (-not $map) { $map = [string]@($tpl.Maps)[0] }
            $a.Add("-console -game $($tpl.Game) -port $port +maxplayers $max")
            if ($mode -and $tpl.ModeCvar) { $a.Add("+$($tpl.ModeCvar) $mode") }
            # Map-Rotation: eigene mapcycle-Datei (das Original mapcycle.txt bleibt unverändert)
            $rot = $null
            if (Test-PelServerRotation $tpl) { $rot = Get-PelServerRotation $Cfg $map }
            if ($rot -and $rot.Count -ge 2) {
                $map = $rot[0]
                $cyc = "PEL_$slug`_mapcycle.txt"
                $gdir = if ($exeDir) { Join-Path $exeDir ([string]$tpl.Game) } else { '' }
                if ($WriteFiles -and $gdir) {
                    $body = (($rot.ToArray()) -join "`r`n") + "`r`n"
                    # hlds liest aus dem Spielordner, neuere srcds zuerst aus cfg - deshalb bei srcds beide
                    $targets = @($gdir)
                    if ($tpl.Key -ne 'cs16') { $targets += (Join-Path $gdir 'cfg') }
                    foreach ($td in $targets) {
                        if (-not [System.IO.Directory]::Exists($td)) { [void][System.IO.Directory]::CreateDirectory($td) }
                        $cp = Join-Path $td $cyc
                        [System.IO.File]::WriteAllText($cp, $body, (New-Object System.Text.UTF8Encoding($false)))
                        $r.Files.Add($cp)
                    }
                }
                $a.Add("+mapcyclefile $cyc")
                $r.Notes.Add(((Get-PelText 'Map-Rotation: {0} Karten, Start: {1}' 'Map rotation: {0} maps, start: {1}') -f $rot.Count, $rot[0]))
            }
            $a.Add("+map $map")
            $a.Add("+sv_lan $(if ($Cfg.Internet) { '0' } else { '1' })")
            $a.Add("+hostname `"$name`"")
            if ($pw) { $a.Add("+sv_password `"$pw`"") }
        }
        'cs2' {
            if (-not $map) { $map = 'de_dust2' }
            $gm = @(([string]$(if ($mode) { $mode } else { '0 1' })) -split ' ')
            $a.Add("-dedicated -console -port $port -maxplayers $max")
            $a.Add("+game_type $($gm[0]) +game_mode $($gm[1]) +map $map")
            $a.Add("+sv_lan $(if ($Cfg.Internet) { '0' } else { '1' })")
            $a.Add("+hostname `"$name`"")
            if ($pw) { $a.Add("+sv_password `"$pw`"") }
        }
        'valheim' {
            $world = ConvertTo-PelServerSlug $(if ($map) { $map } else { 'Dedicated' })
            $a.Add("-nographics -batchmode -name `"$name`" -port $port -world `"$world`"")
            if ($pw) { $a.Add("-password `"$pw`"") }
            $a.Add("-public $(if ($Cfg.Internet) { '1' } else { '0' })")
            if (-not $pw -or $pw.Length -lt 5) { $r.Notes.Add((Get-PelText 'Valheim verlangt ein Passwort mit mindestens 5 Zeichen (und es darf nicht im Servernamen vorkommen).' 'Valheim requires a password with at least 5 characters (and it must not be part of the server name).')) }
            elseif ($name.IndexOf($pw, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { $r.Notes.Add((Get-PelText 'Valheim: das Passwort darf nicht im Servernamen vorkommen.' 'Valheim: the password must not be part of the server name.')) }
            $r.Ports = @("$port-$($port + 2)")
        }
        'cod4' {
            if (-not $map) { $map = 'mp_crash' }
            $a.Add("+set dedicated $(if ($Cfg.Internet) { '2' } else { '1' }) +set net_port $port")
            $a.Add("+set sv_hostname `"$name`" +set sv_maxclients $max +set g_gametype $(if ($mode) { $mode } else { 'dm' })")
            if ($pw) { $a.Add("+set g_password `"$pw`"") }
            # Map-Rotation: sv_mapRotation "gametype dm map A map B ...", map_rotate startet die erste
            $rot = Get-PelServerRotation $Cfg $map
            if ($rot.Count -ge 2) {
                $a.Add("+set sv_mapRotation `"gametype $(if ($mode) { $mode } else { 'dm' }) map $(($rot.ToArray()) -join ' map ')`"")
                $a.Add('+map_rotate')
                $r.Notes.Add(((Get-PelText 'Map-Rotation: {0} Karten, Start: {1}' 'Map rotation: {0} maps, start: {1}') -f $rot.Count, $rot[0]))
            } else { $a.Add("+map $map") }
        }
        'q3' {
            if (-not $map) { $map = 'q3dm17' }
            $a.Add("+set dedicated $(if ($Cfg.Internet) { '2' } else { '1' }) +set net_port $port")
            $a.Add("+set sv_hostname `"$name`" +set sv_maxclients $max +set g_gametype $(if ($mode) { $mode } else { '0' })")
            if ($pw) { $a.Add("+set g_password `"$pw`"") }
            # Map-Rotation: eigene PEL_...cfg in baseq3 mit vstr-Kette (pelrot1 -> pelrot2 -> ...),
            # die letzte Zeile "vstr pelrot1" startet die erste Karte
            $rot = Get-PelServerRotation $Cfg $map
            if ($rot.Count -ge 2) {
                $rcfg = "PEL_$slug`_rotation.cfg"
                $bq = if ($exeDir) { Join-Path $exeDir 'baseq3' } else { '' }
                if ($WriteFiles -and $bq) {
                    $cl = New-Object System.Collections.Generic.List[string]
                    $cl.Add('// Map-Rotation - erstellt vom Project Earth LAN Manager (Server-Baukasten)')
                    for ($i = 0; $i -lt $rot.Count; $i++) {
                        $nx = (($i + 1) % $rot.Count) + 1
                        $cl.Add(('set pelrot{0} "map {1} ; set nextmap vstr pelrot{2}"' -f ($i + 1), $rot[$i], $nx))
                    }
                    $cl.Add('vstr pelrot1')
                    if (-not [System.IO.Directory]::Exists($bq)) { [void][System.IO.Directory]::CreateDirectory($bq) }
                    $rp = Join-Path $bq $rcfg
                    [System.IO.File]::WriteAllText($rp, (($cl -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))
                    $r.Files.Add($rp)
                }
                $a.Add("+exec $rcfg")
                $r.Notes.Add(((Get-PelText 'Map-Rotation: {0} Karten, Start: {1} (Wechsel bei fraglimit/timelimit)' 'Map rotation: {0} maps, start: {1} (changes at fraglimit/timelimit)') -f $rot.Count, $rot[0]))
            } else { $a.Add("+map $map") }
        }
        { $_ -in @('jka', 'jkaclan') } {
            if (-not $map) { $map = 'mp/ffa1' }
            $base = if ($tpl.FsGame) { $tpl.FsGame } else { 'base' }
            if ($tpl.FsGame) {
                $a.Add("+set fs_game $($tpl.FsGame)")
                if ($exeDir -and -not [System.IO.Directory]::Exists((Join-Path $exeDir $tpl.FsGame))) { $r.Notes.Add(((Get-PelText 'Der Mod-Ordner "{0}" wurde neben der EXE nicht gefunden - ist ClanMod installiert?' 'The mod folder "{0}" was not found next to the EXE - is ClanMod installed?') -f $tpl.FsGame)) }
            }
            $a.Add("+set dedicated $(if ($Cfg.Internet) { '2' } else { '1' }) +set net_port $port")
            # Eigene Kopie der server.cfg (PEL_...cfg) im Mod- bzw. base-Ordner, aufgebaut wie
            # eine kommentierte server.cfg (Abschnitte 1-7). Grundlage: die Einstellungen aus
            # dem Fenster "server.cfg & Maps", sonst die vorhandene server.cfg bzw. die
            # eingebaute Vorlage. Name, Spieler, Modus, Passwort und Startkarte kommen aus dem
            # Baukasten und haben Vorrang.
            $cfgDir = if ($exeDir) { Join-Path $exeDir $base } else { '' }
            $srcCfg = if ($cfgDir) { Join-Path $cfgDir 'server.cfg' } else { '' }
            $useOwn = [bool]($srcCfg -and [System.IO.File]::Exists($srcCfg))
            $cfgName = "PEL_$slug.cfg"
            $model = $null
            if ($Cfg.JkaCfg) {
                $model = ConvertTo-PelJkaCfgModel $Cfg.JkaCfg
                $r.Notes.Add((Get-PelText 'server.cfg aus dem Menü "server.cfg & Maps".' 'server.cfg from the "server.cfg & maps" menu.'))
                if ($model.Rotation.Count -ge 2) { $r.Notes.Add(((Get-PelText 'Map-Rotation: {0} Karten.' 'Map rotation: {0} maps.') -f $model.Rotation.Count)) }
            } elseif ($useOwn) { $r.Notes.Add(((Get-PelText 'Grundlage: {0}' 'Based on: {0}') -f $srcCfg)) }
            else { $r.Notes.Add((Get-PelText 'Keine server.cfg gefunden - es wird die eingebaute Vorlage benutzt.' 'No server.cfg found - the built-in template is used.')) }
            if ($max -gt 32) { $r.Notes.Add((Get-PelText 'Jedi Academy erlaubt höchstens 32 Spieler - es werden 32 eingetragen.' 'Jedi Academy allows at most 32 players - 32 will be used.')) }
            if ($WriteFiles -and $cfgDir) {
                if (-not $model) { $model = (Get-PelJkaCfgBase $tpl $exeDir).Model }
                # Servername mit Farbcodes (^1) aus dem Menü behalten, wenn er zum Namen im
                # Baukasten passt (dort werden ^ für die .bat entfernt)
                $mvName = Get-PelJkaCfgVar $model 'sv_hostname'
                if (-not ($mvName -and (ConvertTo-PelServerSafe $mvName 60) -eq $name)) {
                    $hn = ConvertTo-PelQ3CfgText ([string]$Cfg.Name) 60
                    Set-PelJkaCfgVar $model 'sv_hostname' $(if ($hn) { $hn } else { $name })
                }
                Set-PelJkaCfgVar $model 'sv_maxclients' ([string][Math]::Min(32, $max))
                Set-PelJkaCfgVar $model 'g_gametype' $(if ($mode) { $mode } else { '0' })
                Set-PelJkaCfgVar $model 'g_password' $pw
                $txt = ConvertTo-PelJkaCfgText $model $map $cfgDir ([string]$tpl.Title)
                if (-not [System.IO.Directory]::Exists($cfgDir)) { [void][System.IO.Directory]::CreateDirectory($cfgDir) }
                $cfgPath = Join-Path $cfgDir $cfgName
                [System.IO.File]::WriteAllText($cfgPath, $txt, (New-Object System.Text.UTF8Encoding($false)))
                $r.Files.Add($cfgPath)
            }
            $a.Add("+exec $cfgName")
        }
        default { }
    }
    $extra = ([string]$Cfg.Extra) -replace '[\r\n]+', ' '
    $extra = ($extra -replace '[%&|<>^]', '').Trim()
    if ($extra) { $a.Add($extra) }
    $r.Args = ($a -join ' ').Trim()
    return $r
}

# ---- Map-Rotation für die übrigen Vorlagen (01.10.2026) ------------------------------------
# Jedi Academy hat seine Rotation im Fenster "server.cfg & Maps". Für die anderen Spiele gibt
# es im Baukasten den Knopf "Map-Rotation ...": mehrere Karten wählen und in Spielreihenfolge
# anordnen. Die erste Karte ist die Startkarte. So landet die Rotation beim Spiel:
#   F.E.A.R.:   Mission0, Mission1 ... im Abschnitt des Spielmodus der PEL_-Options-Datei
#   UT2004:     Maps=... im Kartenlisten-Abschnitt des Spieltyps der PEL_-ini
#               (z. B. [XInterface.MapListDeathMatch], MapNum=0 = von vorne beginnen;
#               Quelle: UnrealAdminWiki "Running a Multi-Game Map Cycle (UT2004)")
#   hlds/srcds: eigene Datei PEL_..._mapcycle.txt + "+mapcyclefile" (bei srcds zusätzlich im
#               Ordner cfg, weil neuere Source-Server dort zuerst suchen)
#   CoD4:       +set sv_mapRotation "gametype dm map ... map ..." und +map_rotate
#   Quake III:  eigene PEL_..._rotation.cfg in baseq3 (vstr-Kette über nextmap)
# Nicht dabei: CS2 (Kartengruppen in gamemodes_server.txt), L4D2 (Kampagnen), Valheim (eine
# Welt) und "Eigenes Spiel" (unbekanntes Format).
$script:PelRotationKeys = @('fear', 'ut2004', 'cs16', 'css', 'tf2', 'gmod', 'dods', 'hl2dm', 'cod4', 'q3')
function Test-PelServerRotation($Tpl) {
    return [bool]($Tpl -and ($script:PelRotationKeys -contains [string]$Tpl.Key))
}

# UT2004: Abschnitt der Kartenliste je Spieltyp
$script:PelUtMapListSections = @{
    'XGame.xDeathMatch' = 'XInterface.MapListDeathMatch'
    'XGame.xTeamGame' = 'XInterface.MapListTeamDeathMatch'
    'XGame.xCTFGame' = 'XInterface.MapListCaptureTheFlag'
    'XGame.xBombingRun' = 'XInterface.MapListBombingRun'
    'XGame.xDoubleDom' = 'XInterface.MapListDoubleDomination'
