# Hinweis im Rotationsfenster: wo und wie die Rotation gespeichert wird
function Get-PelServerRotationHint($Tpl) {
    $k = [string]$Tpl.Key
    $h = ''
    if ($k -eq 'fear') { $h = Get-PelText 'F.E.A.R.: wird als Mission0, Mission1 ... in den Abschnitt des Spielmodus der PEL_-Options-Datei geschrieben. Die Karten müssen zum Spielmodus passen (z. B. CTF-Karten für CTF).' 'F.E.A.R.: written as Mission0, Mission1 ... into the game mode section of the PEL_ options file. The maps must fit the game mode (e.g. CTF maps for CTF).' }
    elseif ($k -eq 'ut2004') { $h = Get-PelText 'UT2004: wird als Kartenliste des Spieltyps in die PEL_-Kopie der UT2004.ini geschrieben. Die Karten müssen zum Modus passen (DM-, CTF-, BR-, DOM-, ONS-, AS-).' 'UT2004: written as the map list of the game type into the PEL_ copy of UT2004.ini. The maps must fit the mode (DM-, CTF-, BR-, DOM-, ONS-, AS-).' }
    elseif ($k -eq 'cod4') { $h = Get-PelText 'Call of Duty 4: wird als sv_mapRotation in die Startzeile geschrieben, der Server startet mit map_rotate.' 'Call of Duty 4: written as sv_mapRotation into the command line, the server starts with map_rotate.' }
    elseif ($k -eq 'q3') { $h = Get-PelText 'Quake III: wird als PEL_..._rotation.cfg im Ordner baseq3 angelegt. Die Karte wechselt, sobald fraglimit oder timelimit erreicht ist.' 'Quake III: created as PEL_..._rotation.cfg in the baseq3 folder. The map changes as soon as fraglimit or timelimit is reached.' }
    elseif ($Tpl.Srcds) { $h = Get-PelText 'Wird als eigene Datei PEL_..._mapcycle.txt im Spielordner angelegt und mit +mapcyclefile geladen. Nach jeder Karte (Zeit- oder Rundenlimit) folgt die nächste.' 'Created as its own file PEL_..._mapcycle.txt in the game folder and loaded with +mapcyclefile. After each map (time or round limit) the next one follows.' }
    return ($h + ' ' + (Get-PelText 'Die erste Karte ist die Startkarte; ab 2 Karten wird rotiert.' 'The first map is the start map; from 2 maps on it rotates.')).Trim()
}

# Rotation aus $Cfg.Rotation bereinigen und so drehen, dass sie mit der Startkarte beginnt
# (Reihenfolge bleibt erhalten). Steht die Startkarte nicht in der Rotation, kommt sie vorne
# dazu. -Fear: Kartennamen in Worlds\...-Pfade umwandeln, Leerzeichen erlaubt.
# Rückgabe: List[string] (leer = keine Rotation).
function Get-PelServerRotation($Cfg, [string]$Start, [switch]$Fear) {
    $list = New-Object System.Collections.Generic.List[string]
    $src = @()
    if ($Cfg -and $Cfg.PSObject.Properties['Rotation']) { $src = @($Cfg.Rotation) }
    foreach ($x in $src) {
        # ; würde in .cfg-Dateien und Startzeilen weitere Befehle erlauben
        $m = ((ConvertTo-PelServerSafe ([string]$x) 96) -replace ';', '').Trim()
        if ($Fear) { $m = ConvertTo-PelFearMapPath $m } else { $m = $m -replace '\s', '' }
        if ($m -and $list.Count -lt 100) { $list.Add($m) }
    }
    if ($list.Count -eq 0) { return , $list }
    $st = ([string]$Start -replace ';', '').Trim()
    if ($Fear) { $st = ConvertTo-PelFearMapPath $st } else { $st = $st -replace '\s', '' }
    if ($st) {
        $ix = -1
        for ($i = 0; $i -lt $list.Count; $i++) { if ($list[$i] -ieq $st) { $ix = $i; break } }
        if ($ix -gt 0) {
            $turned = New-Object System.Collections.Generic.List[string]
            for ($i = 0; $i -lt $list.Count; $i++) { $turned.Add($list[($ix + $i) % $list.Count]) }
            $list = $turned
        } elseif ($ix -lt 0) { $list.Insert(0, $st) }
    }
    return , $list
}

# Mehrfach-Schlüssel in einem INI-Abschnitt ersetzen: alle Zeilen "Key=..." (mit -Indexed
# "Key0=", "Key1=" ...) im Abschnitt entfernen und $Values an derselben Stelle neu einfügen.
# Fehlt der Abschnitt, wird er am Ende angelegt. Anführungszeichen des Originals bleiben.
function Set-PelIniList([string]$Text, [string]$Section, [string]$Key, $Values, [switch]$Indexed) {
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($l in (([string]$Text) -replace "`r", '' -split "`n")) { $lines.Add($l) }
    $rx = '^\s*' + [regex]::Escape($Key) + $(if ($Indexed) { '\d+' } else { '' }) + '\s*=\s*(")?'
    $cur = ''
    $secStart = -1
    $secEnd = -1
    $first = -1
    $quoted = $false
    $rm = New-Object System.Collections.Generic.List[int]
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match '^\s*\[(.+?)\]\s*$') {
            if ($secStart -ge 0 -and $secEnd -lt 0) { $secEnd = $i }
            $cur = $matches[1].Trim()
            if ($cur -ieq $Section -and $secStart -lt 0) { $secStart = $i }
            continue
        }
        if ($cur -ine $Section) { continue }
        if ($lines[$i] -match $rx) {
            if ($matches[1]) { $quoted = $true }
            if ($first -lt 0) { $first = $i }
            $rm.Add($i)
        }
    }
    if ($secStart -ge 0 -and $secEnd -lt 0) { $secEnd = $lines.Count }
    for ($k = $rm.Count - 1; $k -ge 0; $k--) {
        $lines.RemoveAt($rm[$k])
        if ($rm[$k] -lt $secEnd) { $secEnd-- }
    }
    if ($secStart -lt 0) {
        while ($lines.Count -gt 0 -and -not $lines[$lines.Count - 1].Trim()) { $lines.RemoveAt($lines.Count - 1) }
        $lines.Add("[$Section]")
        $at = $lines.Count
    } elseif ($first -ge 0) {
        $at = $first
    } else {
        # vor den Leerzeilen am Abschnittsende einfügen, nicht dahinter
        $at = $secEnd
        while ($at -gt $secStart + 1 -and -not $lines[$at - 1].Trim()) { $at-- }
    }
    $n = 0
    foreach ($v in @($Values)) {
        $val = if ($quoted) { '"' + [string]$v + '"' } else { [string]$v }
        $kn = if ($Indexed) { "$Key$n" } else { $Key }
        $lines.Insert($at + $n, "$kn=$val")
        $n++
    }
    return ($lines -join "`r`n")
}

# .bat + .pel.json schreiben. Rückgabe: Pfad der .bat
function Save-PelServerBat($Cfg) {
    if (-not [System.IO.Directory]::Exists($script:PelServerDir)) { [void][System.IO.Directory]::CreateDirectory($script:PelServerDir) }
    $tpl = Get-PelServerTemplate ([string]$Cfg.Key)
    $exe = [string]$Cfg.Exe
    if (-not $exe -or -not [System.IO.File]::Exists($exe)) { throw (Get-PelText 'Die Server-EXE wurde nicht gefunden - bitte über "Durchsuchen" auswählen.' 'The server EXE was not found - please select it via "Browse".') }
    $name = ConvertTo-PelServerSafe $Cfg.Name 60
    if (-not $name) { $name = 'Server' }
    $cmd = New-PelServerCommand $Cfg -WriteFiles
    $fileBase = ((ConvertTo-PelServerSafe "$($tpl.Title) - $name" 90) -replace '[\\/:*?]', '_')
    $bat = Join-Path $script:PelServerDir "$fileBase.bat"
    $args2 = ([string]$cmd.Args).Replace('%', '%%')
    $lines = @(
        '@echo off'
        'chcp 65001 >nul'
        "rem PEL-SERVER v1 - erstellt vom Project Earth LAN Manager (Server-Baukasten, Option 5)"
        "rem Spiel: $($tpl.Title) | Port: $([int]$Cfg.Port)"
        "rem Einstellungen: $fileBase.pel.json - am besten im Server-Baukasten ändern"
        "title PEL Server - $name"
    ) + @(@($tpl.Env) | Where-Object { $_ } | ForEach-Object { "set $_" }) + @(
        "cd /d `"$([System.IO.Path]::GetDirectoryName($exe))`""
        "`"$exe`" $args2"
    )
    [System.IO.File]::WriteAllText($bat, (($lines -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))
    $o = [ordered]@{
        Version = 1; Key = [string]$Cfg.Key; Name = $name; Exe = $exe; Port = [int]$Cfg.Port; Max = [int]$Cfg.Max
        Password = [string]$Cfg.Password; Mode = [string]$Cfg.Mode; Map = [string]$Cfg.Map; Internet = [bool]$Cfg.Internet; Extra = [string]$Cfg.Extra; OptionsFile = [string]$Cfg.OptionsFile
        Ports = @($cmd.Ports); Files = @($cmd.Files); Bat = $bat
    }
    # Map-Rotation (Knopf "Map-Rotation ..."), Reihenfolge wie gewählt
    $o['Rotation'] = @(@($(if ($Cfg.PSObject.Properties['Rotation']) { $Cfg.Rotation } else { @() })) | Where-Object { $_ } | ForEach-Object { [string]$_ })
    # Jedi Academy: Einstellungen aus "server.cfg & Maps" mitspeichern (zum späteren Ändern)
    if ($Cfg.JkaCfg) {
        $jm = ConvertTo-PelJkaCfgModel $Cfg.JkaCfg
        $o['JkaCfg'] = [ordered]@{ Vars = $jm.Vars; Extra = $jm.Extra.ToArray(); Rotation = $jm.Rotation.ToArray(); StartMap = [string]$jm.StartMap }
    }
    Write-PelTextFileAtomic (Join-Path $script:PelServerDir "$fileBase.pel.json") (ConvertTo-Json -InputObject $o -Depth 5)
    return $bat
}

# Gespeicherte Server (.bat mit "rem PEL-SERVER" + .pel.json)
function Get-PelSavedServers {
    $list = New-Object System.Collections.Generic.List[object]
    if (-not [System.IO.Directory]::Exists($script:PelServerDir)) { return @() }
    foreach ($j in @(Get-ChildItem -LiteralPath $script:PelServerDir -Filter '*.pel.json' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
        try {
            $c = Read-PelTextFile $j.FullName | ConvertFrom-Json
            $bat = Join-Path $script:PelServerDir ($j.Name -replace '\.pel\.json$', '.bat')
            if (-not [System.IO.File]::Exists($bat)) { continue }
            if ((Read-PelTextFile $bat) -notmatch 'rem PEL-SERVER') { continue }
            $c | Add-Member -NotePropertyName Bat -NotePropertyValue $bat -Force
            $c | Add-Member -NotePropertyName Json -NotePropertyValue $j.FullName -Force
            $list.Add($c)
        } catch { }
    }
    # als Array - @(List[object]) beim Aufrufer würde "Argument types do not match" werfen
    return $list.ToArray()
}

