function Get-PelSteamCmdExe { return (Join-Path $script:PelSteamCmdDir 'steamcmd.exe') }
function Test-PelSteamCmdInstalled { return [System.IO.File]::Exists((Get-PelSteamCmdExe)) }
function Get-PelSteamCmdAppDir($App) { return (Join-Path (Join-Path $script:PelSteamCmdDir 'servers') ([string]$App.Dir)) }

# Installiert = Steam-Manifest oder Server-EXE vorhanden
function Get-PelSteamCmdAppState($App) {
    $dir = Get-PelSteamCmdAppDir $App
    $exe = if ($App.Exe) { Join-Path $dir ([string]$App.Exe) } else { '' }
    $man = Join-Path $dir ('steamapps\appmanifest_{0}.acf' -f [int]$App.AppId)
    $exeOk = [bool]($exe -and [System.IO.File]::Exists($exe))
    return [pscustomobject]@{ Dir = $dir; Exe = $exe; ExeFound = $exeOk; Installed = ($exeOk -or [System.IO.File]::Exists($man)) }
}

# Lädt steamcmd.zip von Valve und übernimmt nur steamcmd.exe. Fragt NICHT selbst nach -
# das macht der Aufrufer (Dialog mit Quelle und Ziel).
function Install-PelSteamCmd {
    if (Test-PelSteamCmdInstalled) { return (Get-PelSteamCmdExe) }
    if (-not [System.IO.Directory]::Exists($script:PelSteamCmdDir)) { [void][System.IO.Directory]::CreateDirectory($script:PelSteamCmdDir) }
    $zip = Join-Path $script:PelSteamCmdDir 'steamcmd.zip'
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    $wc = New-Object System.Net.WebClient
    try { $wc.DownloadFile($script:PelSteamCmdUrl, $zip) } finally { $wc.Dispose() }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $z = [System.IO.Compression.ZipFile]::OpenRead($zip)
    try {
        foreach ($e in $z.Entries) {
            if ([System.IO.Path]::GetFileName($e.FullName) -ieq 'steamcmd.exe') {
                [System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, (Get-PelSteamCmdExe), $true)
            }
        }
    } finally { $z.Dispose() }
    try { [System.IO.File]::Delete($zip) } catch { }
    if (-not (Test-PelSteamCmdInstalled)) { throw (Get-PelText 'steamcmd.exe war nicht im Download enthalten.' 'steamcmd.exe was not contained in the download.') }
    Write-PelLog "SteamCMD installiert: $(Get-PelSteamCmdExe)"
    return (Get-PelSteamCmdExe)
}

# Parameter für SteamCMD: Zielordner, anonym anmelden, App laden/prüfen, beenden
function Get-PelSteamCmdArgs($App) {
    $parts = New-Object System.Collections.Generic.List[string]
    $parts.Add("+force_install_dir `"$(Get-PelSteamCmdAppDir $App)`"")
    $parts.Add('+login anonymous')
    if ($App.Config) { $parts.Add([string]$App.Config) }
    $parts.Add(('+app_update {0} validate' -f [int]$App.AppId))
    $parts.Add('+quit')
    return ($parts -join ' ')
}

# Startet SteamCMD sichtbar in einem eigenen Fenster. Rückgabe: Prozess
function Start-PelSteamCmdApp($App) {
    if (-not (Test-PelSteamCmdInstalled)) { throw (Get-PelText 'SteamCMD ist noch nicht installiert.' 'SteamCMD is not installed yet.') }
    $dir = Get-PelSteamCmdAppDir $App
    if (-not [System.IO.Directory]::Exists($dir)) { [void][System.IO.Directory]::CreateDirectory($dir) }
    $argText = Get-PelSteamCmdArgs $App
    Write-PelLog "SteamCMD: $($App.Title) (App $($App.AppId)) -> $dir"
    return (Start-Process -FilePath (Get-PelSteamCmdExe) -ArgumentList $argText -WorkingDirectory $script:PelSteamCmdDir -PassThru)
}
