        $bJka.UseMnemonic = $false
        $lblNotes = & $add (New-DkLabel '' $x 348 $w 60)
        $lblNotes.ForeColor = [System.Drawing.Color]::FromArgb(255, 190, 90)
        [void](& $add (New-DkLabel (Get-PelText 'So wird der Server gestartet (Vorschau):' 'This is how the server is started (preview):') $x 412 $w 20))
        $txtPrev = New-Object System.Windows.Forms.TextBox
        $txtPrev.Multiline = $true; $txtPrev.ReadOnly = $true; $txtPrev.ScrollBars = 'Vertical'
        $txtPrev.Location = New-Object System.Drawing.Point($x, 434)
        $txtPrev.Size = New-Object System.Drawing.Size($w, 104)
        $txtPrev.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20); $txtPrev.ForeColor = [System.Drawing.Color]::LightGreen
        $txtPrev.Font = New-Object System.Drawing.Font('Consolas', 9)
        [void](& $add $txtPrev)
        $bSave = & $add (New-DkButton (Get-PelText 'Als .bat speichern' 'Save as .bat') $x 548 200 36)
        $bSaveStart = & $add (New-DkButton (Get-PelText 'Speichern & starten' 'Save & start') ($x + 210) 548 220 36 $true)
        $bClose = & $add (New-DkButton (Get-PelText 'Schließen' 'Close') ($x + 540) 548 130 36)
        $lblInfo = & $add (New-DkLabel (Get-PelText 'Gespeichert wird in C:\Project-Earth-Lan\server. Die .bat kann auch per Doppelklick gestartet werden. Firewall-Regeln für den Port legt "Speichern & starten" automatisch an.' 'Saved to C:\Project-Earth-Lan\server. The .bat can also be started by double-click. "Save & start" creates firewall rules for the port automatically.') $x 592 $w 40)
        $lblInfo.ForeColor = [System.Drawing.Color]::FromArgb(170, 178, 190)
        $lblInfo.Font = New-Object System.Drawing.Font('Segoe UI', 8.5, [System.Drawing.FontStyle]::Italic)

        $getCfg = {
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            $mv = ''
            if ($cbMode.SelectedIndex -ge 0 -and $cbMode.SelectedIndex -lt @($t.Modes).Count) { $mv = [string]$t.Modes[$cbMode.SelectedIndex][0] }
            return [pscustomobject]@{
                Key = $t.Key; Name = $txtName.Text; Exe = $txtExe.Text.Trim(); Port = [int]$numPort.Value; Max = [int]$numMax.Value
                Password = $txtPw.Text; Mode = $mv; Map = $cbMap.Text.Trim(); Internet = [bool]$chkNet.Checked; Extra = $txtExtra.Text
                OptionsFile = $(if ($t.Key -eq 'fear') { [string]$bs.FearOptions } else { '' })
                JkaCfg = $(if ($t.Key -in @('jka', 'jkaclan')) { $bs.JkaCfg } else { $null })
                Rotation = $(if (Test-PelServerRotation $t) { , ([string[]]@($bs.Rotation)) } else { , ([string[]]@()) })
            }
        }
        # Knopftext zeigt, wie viele Karten in der Rotation sind
        $updRotBtn = {
            $n = @($bs.Rotation).Count
            $bRot.Text = $(if ($n -gt 0) { (Get-PelText 'Map-Rotation ({0}) ...' 'Map rotation ({0}) ...') -f $n } else { Get-PelText 'Map-Rotation ...' 'Map rotation ...' })
            $bRot.BackColor = $(if ($n -ge 2) { [System.Drawing.Color]::FromArgb(0, 135, 70) } else { $cBtn })
        }
        $updatePreview = {
            if ($bs.Loading) { return }
            $c = & $getCfg
            $cmd = New-PelServerCommand $c
            $exe = if ($c.Exe) { "`"$($c.Exe)`"" } else { (Get-PelText '<Server-EXE fehlt>' '<server EXE missing>') }
            $txtPrev.Text = "$exe $($cmd.Args)".Trim() + "`r`n`r`n" + ((Get-PelText 'Ports für die Firewall: {0}' 'Ports for the firewall: {0}') -f (@($cmd.Ports) -join ', '))
            $notes = @($cmd.Notes)
            if ($c.Exe -and -not [System.IO.File]::Exists($c.Exe)) { $notes += (Get-PelText 'Die Server-EXE gibt es an diesem Ort nicht.' 'The server EXE does not exist at this location.') }
            $lblNotes.Text = ($notes -join "`n")
        }
        # Kartenliste füllen (F.E.A.R.: aus der Options-Datei, passend zum Spielmodus)
        $fillMaps = {
            param([bool]$Defaults = $true)
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            $keep = $cbMap.Text
            $mv = ''
            if ($cbMode.SelectedIndex -ge 0 -and $cbMode.SelectedIndex -lt @($t.Modes).Count) { $mv = [string]$t.Modes[$cbMode.SelectedIndex][0] }
            $cbMap.Items.Clear()
            $exeDir = ''
            try { if ($txtExe.Text) { $exeDir = [System.IO.Path]::GetDirectoryName($txtExe.Text) } } catch { }
            foreach ($m in (Get-PelServerMaps $t $exeDir $mv ([string]$bs.FearOptions))) { [void]$cbMap.Items.Add($m) }
            $cbMap.Enabled = $true
            if ($Defaults -and $cbMap.Items.Count -gt 0) { $cbMap.SelectedIndex = 0 }
            elseif ($Defaults) { $cbMap.Text = '' }
            else { $cbMap.Text = $keep }
            # mit Rotation bleibt deren erste Karte die Startkarte
            if ($Defaults -and @($bs.Rotation).Count -gt 0) { $cbMap.Text = [string]@($bs.Rotation)[0] }
        }
        $applyTemplate = {
            param([bool]$Defaults = $true)
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            $bs.Loading = $true
            try {
                $cbMode.Items.Clear()
                foreach ($m in @($t.Modes)) { [void]$cbMode.Items.Add([string]$m[1]) }
                if ($cbMode.Items.Count -gt 0) { $cbMode.SelectedIndex = 0 }
                $cbMode.Enabled = ($cbMode.Items.Count -gt 1)
                $chkNet.Enabled = [bool]$t.Internet
                if (-not $t.Internet) { $chkNet.Checked = $false }
                if ($Defaults) {
                    $numPort.Value = [decimal][int]$t.Port
                    $numMax.Value = [decimal][int]$t.Max
                    if (-not $txtExe.Text -or -not [System.IO.File]::Exists($txtExe.Text) -or ((@($t.Exe).Count -gt 0) -and (@($t.Exe) -notcontains [System.IO.Path]::GetFileName($txtExe.Text)))) { $txtExe.Text = Find-PelServerExe $t }
                    if (-not $txtName.Text) {
                        $me = ''
                        try { $me = Get-PelDisplayName } catch { }
                        $txtName.Text = "$me$(if ($me) { ' - ' } else { '' })Project Earth LAN"
                    }
                }
                $bOpt.Visible = ($t.Key -eq 'fear')
                $bJka.Visible = ($t.Key -in @('jka', 'jkaclan'))
                $bRot.Visible = (Test-PelServerRotation $t)
                & $updRotBtn
                & $fillMaps $Defaults
            } finally { $bs.Loading = $false }
            & $updatePreview
        }
        $loadSaved = {
            $bs.Saved = @(Get-PelSavedServers)
            $lbSaved.Items.Clear()
            foreach ($sv in $bs.Saved) {
                $t = Get-PelServerTemplate ([string]$sv.Key)
                [void]$lbSaved.Items.Add(("{0} - {1}" -f $(if ($t) { $t.Title } else { $sv.Key }), $sv.Name))
            }
        }
        $showSaved = {
            param($sv)
            $idx = 0
            for ($i = 0; $i -lt $tpls.Count; $i++) { if ($tpls[$i].Key -eq [string]$sv.Key) { $idx = $i } }
            $bs.Loading = $true
            $cbGame.SelectedIndex = $idx
            $txtExe.Text = [string]$sv.Exe
            $bs.FearOptions = [string]$sv.OptionsFile
            $bs.JkaCfg = $(if ($sv.JkaCfg) { ConvertTo-PelJkaCfgModel $sv.JkaCfg } else { $null })
            # ältere .pel.json haben noch keine Rotation
            $bs.Rotation = @(@($(if ($sv.PSObject.Properties['Rotation']) { $sv.Rotation } else { @() })) | Where-Object { $_ } | ForEach-Object { [string]$_ })
            $bs.Loading = $false
            & $applyTemplate $false
            $bs.Loading = $true
            try {
                $txtName.Text = [string]$sv.Name
                $txtPw.Text = [string]$sv.Password
                $numPort.Value = [decimal][Math]::Max(1024, [Math]::Min(65535, [int]$sv.Port))
                $numMax.Value = [decimal][Math]::Max(2, [Math]::Min(64, [int]$sv.Max))
                $t = $tpls[$idx]
                for ($i = 0; $i -lt @($t.Modes).Count; $i++) { if ([string]$t.Modes[$i][0] -eq [string]$sv.Mode) { $cbMode.SelectedIndex = $i } }
                & $fillMaps $false
                $cbMap.Text = [string]$sv.Map
                $chkNet.Checked = [bool]$sv.Internet -and $chkNet.Enabled
                $txtExtra.Text = [string]$sv.Extra
            } finally { $bs.Loading = $false }
            & $updatePreview
        }
        $saveNow = {
            $c = & $getCfg
            if (-not $c.Exe -or -not [System.IO.File]::Exists($c.Exe)) { Show-Msg (Get-PelText 'Bitte zuerst die Server-EXE auswählen ("Suchen" oder "Durchsuchen").' 'Please select the server EXE first ("Find" or "Browse").'); return $null }
            try {
                $bat = Save-PelServerBat $c
                Write-PelLog "Server-Baukasten: $bat gespeichert."
                & $loadSaved
                for ($i = 0; $i -lt $bs.Saved.Count; $i++) { if ($bs.Saved[$i].Bat -eq $bat) { $lbSaved.SelectedIndex = $i } }
                return $bat
            } catch { Show-Msg ((Get-PelText "Speichern fehlgeschlagen:`n{0}" "Saving failed:`n{0}") -f $_.Exception.Message) 'Server-Baukasten' ([System.Windows.Forms.MessageBoxIcon]::Error); return $null }
        }
        $startBat = {
            param([string]$Bat, $Sv)
            $ports = @($Sv.Ports | Where-Object { $_ })
            if ($ports.Count -gt 0) { [void](Add-FirewallAllow "Project Earth LAN Server $(ConvertTo-PelServerSafe $Sv.Name 40)" '' ([string[]]$ports)) }
            Add-ManagedServerEntry ([string]$Sv.Name) $Bat ''
            $lblNotes.Text = (Get-PelText "Gestartet: {0} - er erscheint unten im Server-Manager und im Server-Browser." "Started: {0} - it appears in the server manager below and in the server browser.") -f $Sv.Name
        }

        # SteamCMD-Fenster: Server laden/aktualisieren und danach direkt im Baukasten bauen
        $openSteam = {
            $apps = @(Get-PelSteamCmdApps)
            $ss = @{ Proc = $null; App = $null }
            $sd = (New-PelForm)
            $sd.Text = Get-PelText 'SteamCMD - Dedicated Server mit einem Klick' 'SteamCMD - dedicated servers with one click'
            $sd.Size = New-Object System.Drawing.Size(880, 600)
            $sd.MinimumSize = New-Object System.Drawing.Size(880, 600)
            $sd.StartPosition = 'CenterParent'
            $sd.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
            $sd.ForeColor = $cWhite
            $sd.Font = $fontMain
            $lblTop = New-DkLabel (Get-PelText "Lädt offizielle Dedicated Server über Valves SteamCMD - anonym, ohne Steam-Konto. Ziel: C:\Project-Earth-Lan\steamcmd\servers`n1. Spiel wählen  2. 'Installieren / Aktualisieren'  3. Wenn fertig: 'Im Baukasten bauen'" "Downloads official dedicated servers via Valve's SteamCMD - anonymously, no Steam account. Target: C:\Project-Earth-Lan\steamcmd\servers`n1. Pick a game  2. 'Install / update'  3. When done: 'Build in builder'") 14 10 840 48
            $lv = New-DkListView 14 62 840 380 @((Get-PelText 'Spiel' 'Game'), 'App-ID', 'Status', (Get-PelText 'Ordner' 'Folder')) @(250, 80, 200, 290)
            $bInst = New-DkButton (Get-PelText 'Installieren / Aktualisieren' 'Install / update') 14 452 250 38 $true
            $bBuild = New-DkButton (Get-PelText 'Im Baukasten bauen' 'Build in builder') 272 452 200 38
            $bOpen = New-DkButton (Get-PelText 'Ordner öffnen' 'Open folder') 480 452 160 38
            $bClose2 = New-DkButton (Get-PelText 'Schließen' 'Close') 724 452 130 38
            $lblSt = New-DkLabel '' 14 498 840 56
            $lblSt.ForeColor = [System.Drawing.Color]::FromArgb(255, 190, 90)
            $sd.Controls.AddRange(@($lblTop, $lv, $bInst, $bBuild, $bOpen, $bClose2, $lblSt))
            $refresh = {
                $sel = if ($lv.SelectedIndices.Count -gt 0) { $lv.SelectedIndices[0] } else { -1 }
                $lv.BeginUpdate()
                try {
                    $lv.Items.Clear()
                    foreach ($app in $apps) {
                        $st = Get-PelSteamCmdAppState $app
                        $txt = if ($ss.App -and $ss.App.Key -eq $app.Key -and $ss.Proc -and -not $ss.Proc.HasExited) { Get-PelText 'wird geladen ...' 'downloading ...' }
                               elseif ($st.ExeFound) { Get-PelText 'installiert' 'installed' }
                               elseif ($st.Installed) { Get-PelText 'installiert (EXE fehlt noch)' 'installed (EXE still missing)' }
                               else { Get-PelText 'nicht installiert' 'not installed' }
                        $it = New-Object System.Windows.Forms.ListViewItem([string]$app.Title)
                        [void]$it.SubItems.Add([string]$app.AppId)
                        [void]$it.SubItems.Add($txt)
                        [void]$it.SubItems.Add($(if ($st.Installed) { $st.Dir } else { '' }))
                        if ($st.ExeFound) { $it.ForeColor = [System.Drawing.Color]::LightGreen }
                        [void]$lv.Items.Add($it)
                    }
                    if ($sel -ge 0 -and $sel -lt $lv.Items.Count) { $lv.Items[$sel].Selected = $true }
                } finally { $lv.EndUpdate() }
                $busy = [bool]($ss.Proc -and -not $ss.Proc.HasExited)
                $bInst.Enabled = -not $busy
            }
            $getApp = {
                if ($lv.SelectedIndices.Count -eq 0) { Show-Msg (Get-PelText 'Bitte zuerst ein Spiel in der Liste auswählen.' 'Please select a game in the list first.') 'SteamCMD'; return $null }
                return $apps[$lv.SelectedIndices[0]]
            }
            $tmr = New-Object System.Windows.Forms.Timer
            $tmr.Interval = 1000
            $tmr.Add_Tick({
                if (-not $ss.Proc -or -not $ss.Proc.HasExited) { return }
                $code = 0
                try { $code = [int]$ss.Proc.ExitCode } catch { }
                $app = $ss.App
                $ss.Proc = $null
                & $refresh
                $st = Get-PelSteamCmdAppState $app
                if ($st.Installed) {
                    $lblSt.Text = (Get-PelText "Fertig: {0}. Jetzt 'Im Baukasten bauen' klicken - Servername, Karte und Passwort eintragen, speichern, starten." "Done: {0}. Now click 'Build in builder' - enter server name, map and password, save, start.") -f $app.Title
                } else {
                    $lblSt.Text = (Get-PelText "SteamCMD wurde beendet (Code {0}), {1} ist aber noch nicht vollständig da. Einfach nochmal 'Installieren / Aktualisieren' klicken - es geht dort weiter, wo es aufgehört hat." "SteamCMD exited (code {0}), but {1} is not complete yet. Just click 'Install / update' again - it continues where it stopped.") -f $code, $app.Title
                }
            })
            $lv.Add_SelectedIndexChanged({
                if ($lv.SelectedIndices.Count -eq 0) { return }
                $app = $apps[$lv.SelectedIndices[0]]
                if ($ss.Proc -and -not $ss.Proc.HasExited) { return }
                $lblSt.Text = if ($app.Note) { [string]$app.Note } else { '' }
            })
            $bInst.Add_Click({
                $app = & $getApp
                if (-not $app) { return }
                if ($ss.Proc -and -not $ss.Proc.HasExited) { Show-Msg (Get-PelText 'SteamCMD läuft gerade schon - bitte warten, bis das Fenster zu ist.' 'SteamCMD is already running - please wait until its window has closed.') 'SteamCMD'; return }
                if (-not (Test-PelSteamCmdInstalled)) {
                    $q = [PelI18n]::Show($sd, ((Get-PelText "SteamCMD ist noch nicht da.`n`nJetzt direkt von Valve laden?`n`nQuelle: {0}`nZiel: {1}`n`nSteamCMD ist Valves offizielles Kommandozeilen-Tool für Dedicated Server. Angemeldet wird nur anonym - kein Steam-Konto, kein Passwort." "SteamCMD is not there yet.`n`nDownload it directly from Valve now?`n`nSource: {0}`nTarget: {1}`n`nSteamCMD is Valve's official command line tool for dedicated servers. It only logs in anonymously - no Steam account, no password.") -f $script:PelSteamCmdUrl, $script:PelSteamCmdDir), 'SteamCMD', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
                    if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { return }
                    $lblSt.Text = Get-PelText 'Lade SteamCMD von Valve ...' 'Downloading SteamCMD from Valve ...'
                    $sd.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
                    [System.Windows.Forms.Application]::DoEvents()
                    try { [void](Install-PelSteamCmd) }
                    catch { $lblSt.Text = ''; Show-Msg ((Get-PelText "SteamCMD konnte nicht geladen werden:`n{0}`n`nIst der PC mit dem Internet verbunden?" "SteamCMD could not be downloaded:`n{0}`n`nIs the PC connected to the internet?") -f $_.Exception.Message) 'SteamCMD' ([System.Windows.Forms.MessageBoxIcon]::Error); return }
                    finally { $sd.Cursor = [System.Windows.Forms.Cursors]::Default }
                }
                try {
                    $ss.Proc = Start-PelSteamCmdApp $app
                    $ss.App = $app
                } catch { Show-Msg ((Get-PelText "SteamCMD konnte nicht gestartet werden:`n{0}" "SteamCMD could not be started:`n{0}") -f $_.Exception.Message) 'SteamCMD' ([System.Windows.Forms.MessageBoxIcon]::Error); return }
                $lblSt.Text = (Get-PelText "SteamCMD lädt {0} im eigenen Fenster. Beim allerersten Mal aktualisiert sich SteamCMD zuerst selbst - das ist normal. Du kannst hier solange weiterarbeiten." "SteamCMD is downloading {0} in its own window. The very first time SteamCMD updates itself first - that is normal. You can keep working here meanwhile.") -f $app.Title
                & $refresh
            })
            $bBuild.Add_Click({
                $app = & $getApp
                if (-not $app) { return }
                $st = Get-PelSteamCmdAppState $app
                if (-not $st.Installed) { Show-Msg ((Get-PelText "{0} ist noch nicht installiert - erst 'Installieren / Aktualisieren' klicken." "{0} is not installed yet - click 'Install / update' first.") -f $app.Title) 'SteamCMD'; return }
                $idx = -1
                for ($i = 0; $i -lt $tpls.Count; $i++) { if ($tpls[$i].Key -eq [string]$app.Tpl) { $idx = $i } }
                if ($idx -lt 0) { return }
                $bs.Loading = $true
                $cbGame.SelectedIndex = $idx
                $txtExe.Text = if ($st.ExeFound) { $st.Exe } else { '' }
                if ($app.Tpl -eq 'custom') { $txtExtra.Text = '' }
                $bs.Loading = $false
                & $applyTemplate $true
                if ($app.Tpl -eq 'custom') { $lblNotes.Text = (Get-PelText "{0}: freie Vorlage - die Startparameter stehen in der Server-Doku des Spiels und gehören ins Feld 'Zusätzliche Parameter'." "{0}: free template - the start parameters are in the game's server documentation and go into 'Additional parameters'.") -f $app.Title }
                $sd.Close()
            })
            $bOpen.Add_Click({
                $app = & $getApp
                $p = if ($app) { Get-PelSteamCmdAppDir $app } else { $script:PelSteamCmdDir }
                if (-not [System.IO.Directory]::Exists($p)) { $p = $script:PelSteamCmdDir }
                if (-not [System.IO.Directory]::Exists($p)) { [void][System.IO.Directory]::CreateDirectory($p) }
                try { Start-Process explorer.exe -ArgumentList "`"$p`"" } catch { }
            })
            $bClose2.Add_Click({ $sd.Close() })
            $sd.Add_Shown({ & $refresh; $tmr.Start() })
            $sd.Add_FormClosed({ $tmr.Stop(); $tmr.Dispose() })
            [void]$sd.ShowDialog($d)
            $sd.Dispose()
        }

        # ---- Jedi Academy: Fenster "server.cfg & Maps" ------------------------------------
        # Alle Einstellungen der server.cfg in der Reihenfolge der Datei (links, Abschnitte
        # 1-5 und weitere Zeilen), rechts die Map-Rotation mit den Karten aus dem base-Ordner. Eigene
        # Karten (.pk3/.bsp) lassen sich suchen und in den base-Ordner kopieren, eine
        # vorhandene server.cfg lässt sich einfügen. "Übernehmen" überträgt Name, Spieler,
        # Modus, Passwort und Startkarte zurück in den Baukasten.
        $openJkaCfg = {
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            if ($t.Key -notin @('jka', 'jkaclan')) { return }
            $exeDir = ''
            try { if ($txtExe.Text.Trim()) { $exeDir = [System.IO.Path]::GetDirectoryName($txtExe.Text.Trim()) } } catch { }
            $baseDir = if ($exeDir) { Join-Path $exeDir 'base' } else { '' }
            $cfgDir = if ($exeDir) { Join-Path $exeDir $(if ($t.FsGame) { $t.FsGame } else { 'base' }) } else { '' }
            if ($bs.JkaCfg) { $model = ConvertTo-PelJkaCfgModel $bs.JkaCfg; $srcInfo = Get-PelText 'Grundlage: deine gespeicherten Einstellungen' 'Based on: your saved settings' }
            else {
                $base0 = Get-PelJkaCfgBase $t $exeDir
                $model = $base0.Model
                $srcInfo = if ($base0.Source) { (Get-PelText 'Grundlage: {0}' 'Based on: {0}') -f $base0.Source } else { Get-PelText 'Grundlage: eingebaute Vorlage (keine server.cfg im Spielordner gefunden)' 'Based on: built-in template (no server.cfg found in the game folder)' }
            }
            # Werte aus dem Baukasten haben Vorrang (Name mit Farbcodes bleibt, wenn er passt)
            $mvName = Get-PelJkaCfgVar $model 'sv_hostname'
            if ($txtName.Text.Trim() -and -not ($mvName -and (ConvertTo-PelServerSafe $mvName 60) -eq (ConvertTo-PelServerSafe $txtName.Text 60))) { Set-PelJkaCfgVar $model 'sv_hostname' (ConvertTo-PelQ3CfgText $txtName.Text 60) }
            Set-PelJkaCfgVar $model 'sv_maxclients' ([string][Math]::Min(32, [int]$numMax.Value))
            if ($cbMode.SelectedIndex -ge 0) { Set-PelJkaCfgVar $model 'g_gametype' ([string]$t.Modes[$cbMode.SelectedIndex][0]) }
            Set-PelJkaCfgVar $model 'g_password' (ConvertTo-PelServerSafe $txtPw.Text 32)
            $defs = @(Get-PelJkaCvarDefs)
            $js = @{ Found = @(); Ctl = @{}; Result = $null }
            $cHead = [System.Drawing.Color]::LightSkyBlue
            $cMuted = [System.Drawing.Color]::FromArgb(170, 178, 190)
            $fHint = New-Object System.Drawing.Font('Segoe UI', 8.5, [System.Drawing.FontStyle]::Italic)

            $jd = (New-PelForm)
            $jd.Text = (Get-PelText '{0} - server.cfg & Maps' '{0} - server.cfg & maps') -f $t.Title
            $jd.Size = New-Object System.Drawing.Size(1200, 780)
            $jd.MinimumSize = New-Object System.Drawing.Size(1200, 600)
            $jd.StartPosition = 'CenterParent'
            $jd.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
            $jd.ForeColor = $cWhite
            $jd.Font = $fontMain
            try {
                $wa = [System.Windows.Forms.Screen]::FromControl($d).WorkingArea
                if ($jd.Height -gt $wa.Height) { $jd.Height = $wa.Height }
            } catch { }
            $cw = $jd.ClientSize.Width
            $ch = $jd.ClientSize.Height
            $jtip = New-Object System.Windows.Forms.ToolTip
            $lblTop = New-DkLabel ((Get-PelText 'Alle Einstellungen der server.cfg - aufgebaut wie die Datei selbst. Der Baukasten schreibt daraus eine eigene Kopie (PEL_...cfg), die Original-server.cfg bleibt unverändert.  {0}' 'All settings of the server.cfg - laid out like the file itself. The builder writes its own copy (PEL_...cfg) from it, the original server.cfg stays unchanged.  {0}') -f $srcInfo) 14 8 ($cw - 28) 38
            $lblTop.ForeColor = $cMuted
            $lblTop.Anchor = 'Top,Left,Right'
            $jd.Controls.Add($lblTop)

            # -- links: Abschnitte 1-5 und weitere Zeilen (scrollbar) --
            $pL = New-Object System.Windows.Forms.Panel
            $pL.Location = New-Object System.Drawing.Point(14, 50)
            $pL.Size = New-Object System.Drawing.Size(610, ($ch - 50 - 56))
            $pL.Anchor = 'Top,Bottom,Left'
            $pL.AutoScroll = $true
            $pL.BackColor = [System.Drawing.Color]::FromArgb(35, 35, 35)
            $jd.Controls.Add($pL)
            $y = 8
            $lastSec = 0
            foreach ($df in $defs) {
                if ($df.Sec -ne $lastSec) {
                    $lastSec = $df.Sec
                    $h = New-DkLabel ("$($df.Sec). " + (Get-PelJkaCfgSectionName $df.Sec)) 8 ($y + 4) 560 22
                    $h.Font = New-Object System.Drawing.Font('Segoe UI', 10.5, [System.Drawing.FontStyle]::Bold)
                    $h.ForeColor = $cHead
                    $pL.Controls.Add($h)
                    $y += 32
                    if ($df.Sec -eq 3) {
                        $hn = New-DkLabel (Get-PelText 'Jedi Academy: 7 = Siege, 8 = CTF (in vielen Beispielen aus dem Netz vertauscht).' 'Jedi Academy: 7 = Siege, 8 = CTF (swapped in many examples on the web).') 8 $y 560 18
                        $hn.Font = $fHint
                        $hn.ForeColor = $cMuted
                        $pL.Controls.Add($hn)
                        $y += 20
                    }
                }
                $lb = New-DkLabel $df.Label 8 ($y + 2) 320 34
                $pL.Controls.Add($lb)
                $ln = New-DkLabel $df.Name 8 ($y + 20) 320 16
                $ln.Font = New-Object System.Drawing.Font('Consolas', 8)
                $ln.ForeColor = $cMuted
                $pL.Controls.Add($ln)
                $lb.Height = 18
                $jtip.SetToolTip($lb, "$($df.Name): $($df.Label)")
                $v = Get-PelJkaCfgVar $model $df.Name
                if ($null -eq $v) { $v = $df.Default }
                $cx = 336; $cwid = 236
                switch ($df.Type) {
                    { $_ -in @('text', 'pass') } {
                        $c = New-DkText $cx ($y + 4) $(if ($df.Name -eq 'rconPassword') { $cwid - 70 } else { $cwid }) 26
                        $c.MaxLength = $(if ($df.Name -eq 'g_motd') { 150 } else { 64 })
                        $c.Text = [string]$v
                        $pL.Controls.Add($c)
                        if ($df.Name -eq 'rconPassword') {
                            $bR = New-DkButton (Get-PelText 'Zufall' 'Random') ($cx + $cwid - 64) ($y + 3) 64 28
                            $bR.Tag = $c
                            $bR.Add_Click({
                                # zufälliges RCON-Passwort (12 Zeichen, ohne verwechselbare Zeichen)
                                $chars = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'
                                $rng = New-Object System.Security.Cryptography.RNGCryptoServiceProvider
                                $bytes = New-Object byte[] 12
                                $rng.GetBytes($bytes)
                                $rng.Dispose()
                                $this.Tag.Text = -join @($bytes | ForEach-Object { $chars[[int]$_ % $chars.Length] })
                            })
                            $pL.Controls.Add($bR)
                        }
                    }
                    'int' {
                        $c = New-Object System.Windows.Forms.NumericUpDown
                        $c.Location = New-Object System.Drawing.Point($cx, ($y + 4))
                        $c.Size = New-Object System.Drawing.Size(110, 26)
                        $c.Minimum = $df.Min
                        $c.Maximum = $(if ($df.Max -gt 0) { $df.Max } else { 999999 })
                        $c.BackColor = $cInput; $c.ForeColor = $cWhite
                        $n = 0
                        if (-not [int]::TryParse(([string]$v).Trim(), [ref]$n)) { $n = [int]$df.Default }
                        $c.Value = [decimal][Math]::Max([int]$c.Minimum, [Math]::Min([int]$c.Maximum, $n))
                        $pL.Controls.Add($c)
                    }
                    'bool' {
                        $c = New-DkCheck (Get-PelText 'an' 'on') $cx ($y + 6) 120 ([string]$v -ne '0' -and [string]$v -ne '')
                        $pL.Controls.Add($c)
                    }
                    default {
                        # list = feste Auswahl, mask = Vorschläge oder eigene Zahl
                        $c = New-Object System.Windows.Forms.ComboBox
                        $c.Location = New-Object System.Drawing.Point($cx, ($y + 4))
                        $c.Size = New-Object System.Drawing.Size($cwid, 26)
                        $c.DropDownStyle = if ($df.Type -eq 'list') { 'DropDownList' } else { 'DropDown' }
                        $c.BackColor = $cInput; $c.ForeColor = $cWhite; $c.FlatStyle = 'Flat'
                        $hit = -1
                        foreach ($ch2 in @($df.Choices)) {
                            $ix = $c.Items.Add(('{0} - {1}' -f $ch2[0], $ch2[1]))
                            if ([string]$ch2[0] -eq ([string]$v).Trim()) { $hit = $ix }
                        }
                        if ($hit -ge 0) { $c.SelectedIndex = $hit }
                        elseif ($df.Type -eq 'list') { $c.SelectedIndex = $c.Items.Add(([string]$v).Trim()) }
                        else { $c.Text = ([string]$v).Trim() }
                        $pL.Controls.Add($c)
                    }
                }
                $js.Ctl[$df.Name] = $c
                $y += 42
            }
            $h7 = New-DkLabel (Get-PelJkaCfgSectionName 7) 8 ($y + 6) 560 22
            $h7.Font = New-Object System.Drawing.Font('Segoe UI', 10.5, [System.Drawing.FontStyle]::Bold)
            $h7.ForeColor = $cHead
            $pL.Controls.Add($h7)
            $y += 32
            $h7b = New-DkLabel (Get-PelText 'Alle übrigen Zeilen (z. B. ClanMod-Werte, exec ...) - eine pro Zeile, werden unverändert übernommen.' 'All other lines (e.g. ClanMod values, exec ...) - one per line, kept unchanged.') 8 $y 560 34
            $h7b.Font = $fHint
            $h7b.ForeColor = $cMuted
            $pL.Controls.Add($h7b)
            $y += 36
            $txtX = New-DkText 8 $y 566 220
            $txtX.Multiline = $true; $txtX.ScrollBars = 'Both'; $txtX.WordWrap = $false; $txtX.AcceptsReturn = $true
            $txtX.Font = New-Object System.Drawing.Font('Consolas', 9)
            $txtX.Text = ($model.Extra.ToArray() -join "`r`n")
            $pL.Controls.Add($txtX)
            $sp = New-DkLabel '' 8 ($y + 230) 10 10
            $pL.Controls.Add($sp)

            # -- rechts: Map-Rotation --
            $rx = 640
            $rw = $cw - $rx - 14
            $pR = New-Object System.Windows.Forms.Panel
            $pR.Location = New-Object System.Drawing.Point($rx, 50)
            $pR.Size = New-Object System.Drawing.Size($rw, ($ch - 50 - 56))
            $pR.Anchor = 'Top,Bottom,Left,Right'
            $pR.AutoScroll = $true
            $jd.Controls.Add($pR)
            $h6 = New-DkLabel (Get-PelJkaCfgSectionName 6) 0 4 ($rw - 20) 22
            $h6.Font = New-Object System.Drawing.Font('Segoe UI', 10.5, [System.Drawing.FontStyle]::Bold)
            $h6.ForeColor = $cHead
            $pR.Controls.Add($h6)
            $lblFound = New-DkLabel (Get-PelText 'Karten im base-Ordner' 'Maps in the base folder') 0 32 300 20
            $pR.Controls.Add($lblFound)
            $txtFilter = New-DkText 310 30 ($rw - 330) 24
            $jtip.SetToolTip($txtFilter, (Get-PelText 'Filter: Teil des Kartennamens, z. B. ffa, duel, ctf, siege' 'Filter: part of the map name, e.g. ffa, duel, ctf, siege'))
            $pR.Controls.Add($txtFilter)
            $lbFound = New-Object System.Windows.Forms.ListBox
            $lbFound.Location = New-Object System.Drawing.Point(0, 58)
            $lbFound.Size = New-Object System.Drawing.Size(($rw - 20), 200)
            $lbFound.SelectionMode = 'MultiExtended'
            $lbFound.BackColor = $cList; $lbFound.ForeColor = $cWhite; $lbFound.BorderStyle = 'FixedSingle'
            $lbFound.IntegralHeight = $false
            $lbFound.HorizontalScrollbar = $true
            $pR.Controls.Add($lbFound)
            $bScan = New-DkButton (Get-PelText 'Maps im base-Ordner suchen' 'Search maps in base folder') 0 264 230 32
            $bAddFile = New-DkButton (Get-PelText 'Map-Datei hinzufügen (.pk3/.bsp) ...' 'Add map file (.pk3/.bsp) ...') 236 264 250 32
            $bToRot = New-DkButton (Get-PelText 'In Rotation einfügen' 'Insert into rotation') 0 300 230 32 $true
            $pR.Controls.AddRange(@($bScan, $bAddFile, $bToRot))
            $lblScan = New-DkLabel '' 236 306 ($rw - 256) 24
            $lblScan.ForeColor = $cMuted
            $lblScan.Font = $fHint
            $pR.Controls.Add($lblScan)
            $lblRot = New-DkLabel (Get-PelText 'Rotation - Reihenfolge = Spielreihenfolge (ab 2 Karten, sonst nur Startkarte)' 'Rotation - order = play order (from 2 maps, otherwise start map only)') 0 344 ($rw - 20) 20
            $pR.Controls.Add($lblRot)
            $lbRot = New-Object System.Windows.Forms.ListBox
            $lbRot.Location = New-Object System.Drawing.Point(0, 366)
            $lbRot.Size = New-Object System.Drawing.Size(($rw - 140), 190)
            $lbRot.BackColor = $cList; $lbRot.ForeColor = $cWhite; $lbRot.BorderStyle = 'FixedSingle'
            $lbRot.IntegralHeight = $false
            $pR.Controls.Add($lbRot)
            $bRUp = New-DkButton (Get-PelText 'Nach oben' 'Up') ($rw - 132) 366 112 30
            $bRDown = New-DkButton (Get-PelText 'Nach unten' 'Down') ($rw - 132) 400 112 30
            $bRDel = New-DkButton (Get-PelText 'Entfernen' 'Remove') ($rw - 132) 434 112 30
            $bRDel.BackColor = [System.Drawing.Color]::FromArgb(160, 50, 40)
            $bRClr = New-DkButton (Get-PelText 'Alle leeren' 'Clear all') ($rw - 132) 468 112 30
            $pR.Controls.AddRange(@($bRUp, $bRDown, $bRDel, $bRClr))
            $txtMapIn = New-DkText 0 564 ($rw - 260) 26
            $jtip.SetToolTip($txtMapIn, (Get-PelText 'Kartenname von Hand, z. B. mp/ffa3 (ohne maps/ und .bsp)' 'Map name by hand, e.g. mp/ffa3 (without maps/ and .bsp)'))
            $bMapIn = New-DkButton (Get-PelText 'Eintippen & einfügen' 'Type & insert') ($rw - 252) 562 232 30
            $pR.Controls.AddRange(@($txtMapIn, $bMapIn))
            $lblDl = New-DkLabel (Get-PelText 'Eigene Karten brauchen auch die Mitspieler (gleiche .pk3 im base-Ordner) - oder "Spieler dürfen fehlende Karten laden" einschalten.' 'Custom maps are needed by the other players too (same .pk3 in the base folder) - or switch on "Players may download missing maps".') 0 598 ($rw - 20) 36
            $lblDl.Font = $fHint
            $lblDl.ForeColor = $cMuted
            $pR.Controls.Add($lblDl)
            foreach ($r0 in $model.Rotation) { [void]$lbRot.Items.Add([string]$r0) }
            if ($lbRot.Items.Count -eq 0 -and $cbMap.Text.Trim()) { [void]$lbRot.Items.Add($cbMap.Text.Trim()) }

            # -- unten --
            $by = $ch - 46
            $bImport = New-DkButton (Get-PelText 'Vorhandene server.cfg einfügen ...' 'Insert existing server.cfg ...') 14 $by 270 36
            $bPrev = New-DkButton (Get-PelText 'Vorschau / speichern unter ...' 'Preview / save as ...') 290 $by 230 36
            $bDefaults = New-DkButton (Get-PelText 'Standardwerte' 'Defaults') 526 $by 150 36
            $bOk = New-DkButton (Get-PelText 'Übernehmen' 'Apply') ($cw - 14 - 130 - 8 - 170) $by 170 36 $true
            $bEsc = New-DkButton (Get-PelText 'Abbrechen' 'Cancel') ($cw - 14 - 130) $by 130 36
            foreach ($b0 in @($bImport, $bPrev, $bDefaults)) { $b0.Anchor = 'Bottom,Left' }
            foreach ($b0 in @($bOk, $bEsc)) { $b0.Anchor = 'Bottom,Right' }
            $jd.Controls.AddRange(@($bImport, $bPrev, $bDefaults, $bOk, $bEsc))
            $jd.CancelButton = $bEsc

            # Werte aus den Feldern lesen bzw. hineinschreiben
            $readCtl = {
                param($Df)
                $c = $js.Ctl[$Df.Name]
                switch ($Df.Type) {
                    { $_ -in @('text', 'pass') } { return $c.Text }
                    'int' { return [string][int]$c.Value }
                    'bool' { return $(if ($c.Checked) { '1' } else { '0' }) }
                    default { if ($c.Text -match '^\s*(-?\d+)') { return $matches[1] } else { return [string]$Df.Default } }
                }
            }
            $writeCtl = {
                param($Df, [string]$V)
                $c = $js.Ctl[$Df.Name]
                switch ($Df.Type) {
                    { $_ -in @('text', 'pass') } { $c.Text = $V }
                    'int' { $n = 0; if ([int]::TryParse($V.Trim(), [ref]$n)) { $c.Value = [decimal][Math]::Max([int]$c.Minimum, [Math]::Min([int]$c.Maximum, $n)) } }
                    'bool' { $c.Checked = ($V.Trim() -ne '0' -and $V.Trim() -ne '') }
                    default {
                        $hit = -1
                        for ($i = 0; $i -lt $c.Items.Count; $i++) { if (([string]$c.Items[$i]) -match '^\s*(-?\d+)' -and $matches[1] -eq $V.Trim()) { $hit = $i } }
                        if ($hit -ge 0) { $c.SelectedIndex = $hit }
                        elseif ($c.DropDownStyle -eq 'DropDownList') { $c.SelectedIndex = $c.Items.Add($V.Trim()) }
                        else { $c.Text = $V.Trim() }
                    }
                }
            }
            $collect = {
                $m = New-PelJkaCfgModel
                foreach ($df in $defs) { $m.Vars[$df.Name] = [string](& $readCtl $df) }
                foreach ($xl in ($txtX.Text -split "`r?`n")) { if ($xl.Trim()) { $m.Extra.Add($xl.Trim()) } }
                foreach ($it in $lbRot.Items) { $mm = ConvertTo-PelJkaMapName ([string]$it); if ($mm) { $m.Rotation.Add($mm) } }
                $m.StartMap = $(if ($m.Rotation.Count -gt 0) { $m.Rotation[0] } else { '' })
                return $m
            }
            $fillFound = {
                $f = $txtFilter.Text.Trim()
                $lbFound.BeginUpdate()
                try {
                    $lbFound.Items.Clear()
                    foreach ($x in $js.Found) {
                        $s = [string]$x.Map
                        if ($x.LongName) { $s += '  -  ' + $x.LongName }
                        if ($x.Types) { $s += '  [' + $x.Types + ']' }
                        $s += '   (' + $x.Source + ')'
                        if ($f -and $s.IndexOf($f, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
                        [void]$lbFound.Items.Add($s)
                    }
                } finally { $lbFound.EndUpdate() }
            }
            $scan = {
                param([bool]$Force = $false)
                if (-not $exeDir) { $lblScan.Text = Get-PelText 'Erst die Server-EXE im Baukasten wählen.' 'Select the server EXE in the builder first.'; return }
                $jd.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
                $lblScan.Text = Get-PelText 'Suche Karten ...' 'Searching maps ...'
                [System.Windows.Forms.Application]::DoEvents()
                try {
                    if ($Force) { $js.Found = @(Get-PelJkaMapList $exeDir ([string]$t.FsGame) -Force) } else { $js.Found = @(Get-PelJkaMapList $exeDir ([string]$t.FsGame)) }
                    $lblScan.Text = (Get-PelText '{0} Karten gefunden' '{0} maps found') -f $js.Found.Count
                } catch { $lblScan.Text = [string]$_.Exception.Message } finally { $jd.Cursor = [System.Windows.Forms.Cursors]::Default }
                & $fillFound
            }
            $addRot = {
                param([string]$Map)
                $mm = ConvertTo-PelJkaMapName $Map
                if (-not $mm) { return $false }
                foreach ($it in $lbRot.Items) { if ([string]$it -ieq $mm) { return $false } }
                if ($lbRot.Items.Count -ge 60) { return $false }
                [void]$lbRot.Items.Add($mm)
                return $true
            }

            $txtFilter.Add_TextChanged({ & $fillFound })
            $bScan.Add_Click({ & $scan $true })
            $bToRot.Add_Click({
                $n = 0
                foreach ($it in @($lbFound.SelectedItems)) { if ([string]$it -match '^(\S+)') { if (& $addRot $matches[1]) { $n++ } } }
                if ($n -eq 0 -and $lbFound.SelectedItems.Count -eq 0) { $lblScan.Text = Get-PelText 'Erst oben Karten markieren (Strg/Umschalt für mehrere).' 'Select maps above first (Ctrl/Shift for several).' }
            })
            $lbFound.Add_DoubleClick({ if ($lbFound.SelectedItem -and [string]$lbFound.SelectedItem -match '^(\S+)') { [void](& $addRot $matches[1]) } })
            $bMapIn.Add_Click({
                $raw = ($txtMapIn.Text.Trim() -replace '^(?i)maps[\\/]', '' -replace '(?i)\.bsp$', '')
                if (-not (& $addRot $raw)) { Show-Msg (Get-PelText 'Ungültiger oder doppelter Kartenname. Erlaubt: Buchstaben, Ziffern, / _ - . (z. B. mp/ffa3).' 'Invalid or duplicate map name. Allowed: letters, digits, / _ - . (e.g. mp/ffa3).'); return }
                $txtMapIn.Text = ''
            })
            $bRUp.Add_Click({
                $i = $lbRot.SelectedIndex
                if ($i -le 0) { return }
                $v0 = $lbRot.Items[$i]; $lbRot.Items.RemoveAt($i); $lbRot.Items.Insert($i - 1, $v0); $lbRot.SelectedIndex = $i - 1
            })
            $bRDown.Add_Click({
                $i = $lbRot.SelectedIndex
                if ($i -lt 0 -or $i -ge $lbRot.Items.Count - 1) { return }
                $v0 = $lbRot.Items[$i]; $lbRot.Items.RemoveAt($i); $lbRot.Items.Insert($i + 1, $v0); $lbRot.SelectedIndex = $i + 1
            })
            $bRDel.Add_Click({
                $i = $lbRot.SelectedIndex
                if ($i -lt 0) { return }
                $lbRot.Items.RemoveAt($i)
                if ($lbRot.Items.Count -gt 0) { $lbRot.SelectedIndex = [Math]::Min($i, $lbRot.Items.Count - 1) }
            })
            $bRClr.Add_Click({ $lbRot.Items.Clear() })

            # Eigene Karte von irgendwo auswählen: .pk3 bzw. .bsp in den base-Ordner kopieren
            # (nur nach Rückfrage), danach neu suchen und die Karten in die Rotation einfügen.
            $bAddFile.Add_Click({
                if (-not $baseDir -or -not [System.IO.Directory]::Exists($exeDir)) { Show-Msg (Get-PelText 'Bitte zuerst im Baukasten die Server-EXE (jampded.exe / openjkded) wählen - daneben liegt der base-Ordner.' 'Please select the server EXE (jampded.exe / openjkded) in the builder first - the base folder is next to it.'); return }
                $ofd = New-Object System.Windows.Forms.OpenFileDialog
                $ofd.Title = Get-PelText 'Jedi-Academy-Karte auswählen (.pk3 oder .bsp)' 'Select Jedi Academy map (.pk3 or .bsp)'
                $ofd.Filter = (Get-PelText 'Jedi-Academy-Karten (*.pk3;*.bsp)|*.pk3;*.bsp|Alle Dateien (*.*)|*.*' 'Jedi Academy maps (*.pk3;*.bsp)|*.pk3;*.bsp|All files (*.*)|*.*')
                $ofd.Multiselect = $true
                if ([System.IO.Directory]::Exists($baseDir)) { $ofd.InitialDirectory = $baseDir }
                if ($ofd.ShowDialog($jd) -ne [System.Windows.Forms.DialogResult]::OK) { return }
                $newMaps = New-Object System.Collections.Generic.List[string]
                foreach ($fp in $ofd.FileNames) {
                    $ext = [System.IO.Path]::GetExtension($fp).ToLowerInvariant()
                    $leaf = [System.IO.Path]::GetFileName($fp)
                    if ($ext -eq '.pk3') {
                        $inside = @(Get-PelPk3Maps $fp)
                        if ($inside.Count -eq 0) { Show-Msg ((Get-PelText "In {0} ist keine Karte (maps/*.bsp) enthalten - vermutlich ein Skin- oder Mod-Paket." "{0} contains no map (maps/*.bsp) - probably a skin or mod package.") -f $leaf); continue }
                        $target = Join-Path $baseDir $leaf
                    } elseif ($ext -eq '.bsp') {
                        $inside = @([pscustomobject]@{ Map = [System.IO.Path]::GetFileNameWithoutExtension($fp) })
                        $target = Join-Path (Join-Path $baseDir 'maps') $leaf
                    } else { continue }
                    $same = $false
                    try { $same = ([System.IO.Path]::GetFullPath($fp) -ieq [System.IO.Path]::GetFullPath($target)) } catch { }
                    if (-not $same) {
                        $q = [PelI18n]::Show($jd, ((Get-PelText "Der Server lädt Karten nur aus seinem base-Ordner.`n`n{0}`n-> {1}`n`nJetzt dorthin kopieren? (Das Original bleibt, wo es ist. Die Kopie bleibt im Spielordner, bis du sie selbst löschst.)" "The server only loads maps from its base folder.`n`n{0}`n-> {1}`n`nCopy it there now? (The original stays where it is. The copy stays in the game folder until you delete it yourself.)") -f $fp, $target), 'Jedi Academy', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
                        if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { continue }
                        if ([System.IO.File]::Exists($target)) {
                            $q2 = [PelI18n]::Show($jd, ((Get-PelText "{0} gibt es dort schon. Überschreiben?" "{0} already exists there. Overwrite?") -f $leaf), 'Jedi Academy', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
                            if ($q2 -ne [System.Windows.Forms.DialogResult]::Yes) { continue }
                        }
                        try {
                            $tdir = [System.IO.Path]::GetDirectoryName($target)
                            if (-not [System.IO.Directory]::Exists($tdir)) { [void][System.IO.Directory]::CreateDirectory($tdir) }
                            [System.IO.File]::Copy($fp, $target, $true)
                            Write-PelLog "Server-Baukasten (Jedi Academy): Karte $fp nach $target kopiert."
                        } catch { Show-Msg ((Get-PelText "Kopieren fehlgeschlagen:`n{0}`n`nLiegt das Spiel unter C:\Programme? Dann fehlen evtl. Schreibrechte." "Copying failed:`n{0}`n`nIs the game under C:\Program Files? Write permissions may be missing.") -f $_.Exception.Message) 'Jedi Academy' ([System.Windows.Forms.MessageBoxIcon]::Error); continue }
                    }
                    foreach ($im in $inside) { $newMaps.Add([string]$im.Map) }
                }
                if ($newMaps.Count -eq 0) { return }
                & $scan $true
                $n = 0
                foreach ($nm in $newMaps) { if (& $addRot $nm) { $n++ } }
                $lblScan.Text = (Get-PelText '{0} neue Karte(n) in die Rotation eingefügt' '{0} new map(s) inserted into the rotation') -f $n
            })

            # Vorhandene server.cfg (von dir, aus dem Netz, von einem anderen Server) einfügen
            $bImport.Add_Click({
                $ofd = New-Object System.Windows.Forms.OpenFileDialog
                $ofd.Title = Get-PelText 'Vorhandene server.cfg einfügen' 'Insert existing server.cfg'
                $ofd.Filter = (Get-PelText 'Konfiguration (*.cfg)|*.cfg|Textdateien (*.txt)|*.txt|Alle Dateien (*.*)|*.*' 'Configuration (*.cfg)|*.cfg|Text files (*.txt)|*.txt|All files (*.*)|*.*')
                if ($cfgDir -and [System.IO.Directory]::Exists($cfgDir)) { $ofd.InitialDirectory = $cfgDir }
                if ($ofd.ShowDialog($jd) -ne [System.Windows.Forms.DialogResult]::OK) { return }
                try {
                    $fi = New-Object System.IO.FileInfo($ofd.FileName)
                    if ($fi.Length -gt 1048576) { Show-Msg (Get-PelText 'Die Datei ist größer als 1 MB - das ist keine server.cfg.' 'The file is larger than 1 MB - that is not a server.cfg.'); return }
                    $im = Read-PelJkaCfgText (Read-PelTextFile $ofd.FileName)
                } catch { Show-Msg ((Get-PelText "Datei nicht lesbar:`n{0}" "File not readable:`n{0}") -f $_.Exception.Message) 'Jedi Academy' ([System.Windows.Forms.MessageBoxIcon]::Error); return }
                $nv = 0
                foreach ($df in $defs) {
                    $iv = Get-PelJkaCfgVar $im $df.Name
                    if ($null -ne $iv) { & $writeCtl $df $iv; $nv++ }
                }
                $txtX.Text = ($im.Extra.ToArray() -join "`r`n")
                if ($im.Rotation.Count -gt 0 -or $im.StartMap) {
                    $lbRot.Items.Clear()
                    if ($im.Rotation.Count -gt 0) { foreach ($rm in $im.Rotation) { [void](& $addRot $rm) } } else { [void](& $addRot $im.StartMap) }
                }
                Write-PelLog "Server-Baukasten (Jedi Academy): server.cfg eingefügt: $($ofd.FileName)"
                Show-Msg ((Get-PelText "Eingefügt aus {0}:`n`n{1} Einstellungen übernommen`n{2} weitere Zeilen`n{3} Karten in der Rotation`n`nKommentare der Datei werden nicht übernommen - der Baukasten schreibt eigene." "Inserted from {0}:`n`n{1} settings taken over`n{2} more lines`n{3} maps in the rotation`n`nComments of the file are not taken over - the builder writes its own.") -f [System.IO.Path]::GetFileName($ofd.FileName), $nv, $im.Extra.Count, $lbRot.Items.Count)
            })
            $bDefaults.Add_Click({
                $q = [PelI18n]::Show($jd, (Get-PelText "Alle Felder der Abschnitte 1-5 auf Standardwerte setzen?`n`nRotation und weitere Zeilen bleiben unverändert." "Reset all fields of sections 1-5 to defaults?`n`nRotation and more lines stay unchanged."), 'Jedi Academy', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
                if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { return }
                foreach ($df in $defs) { if ($df.Name -notin @('sv_hostname', 'g_password', 'rconPassword', 'sv_privatePassword')) { & $writeCtl $df ([string]$df.Default) } }
            })
            $bPrev.Add_Click({
                $m = & $collect
                $txt = ConvertTo-PelJkaCfgText $m '' $cfgDir ([string]$t.Title)
                $pv = (New-PelForm)
                $pv.Text = Get-PelText 'Vorschau server.cfg' 'Preview server.cfg'
                $pv.Size = New-Object System.Drawing.Size(900, 680)
                $pv.StartPosition = 'CenterParent'
                $pv.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
                $pv.ForeColor = $cWhite
                $tb = New-Object System.Windows.Forms.TextBox
                $tb.Multiline = $true; $tb.ReadOnly = $true; $tb.ScrollBars = 'Both'; $tb.WordWrap = $false
                $tb.Location = New-Object System.Drawing.Point(12, 12)
                $tb.Size = New-Object System.Drawing.Size(($pv.ClientSize.Width - 24), ($pv.ClientSize.Height - 70))
                $tb.Anchor = 'Top,Bottom,Left,Right'
                $tb.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20); $tb.ForeColor = [System.Drawing.Color]::LightGreen
                $tb.Font = New-Object System.Drawing.Font('Consolas', 9.5)
                $tb.Text = $txt
                $bc = New-DkButton (Get-PelText 'Kopieren' 'Copy') 12 ($pv.ClientSize.Height - 48) 140 36
                $bsv = New-DkButton (Get-PelText 'Speichern unter ...' 'Save as ...') 160 ($pv.ClientSize.Height - 48) 180 36
                $bx = New-DkButton (Get-PelText 'Schließen' 'Close') ($pv.ClientSize.Width - 152) ($pv.ClientSize.Height - 48) 140 36
                $bc.Anchor = 'Bottom,Left'; $bsv.Anchor = 'Bottom,Left'; $bx.Anchor = 'Bottom,Right'
                $bc.Add_Click({ [void](Set-PelClipboard $tb.Text) })
                $bsv.Add_Click({
                    $sfd = New-Object System.Windows.Forms.SaveFileDialog
                    $sfd.Filter = (Get-PelText 'Konfiguration (*.cfg)|*.cfg' 'Configuration (*.cfg)|*.cfg')
                    $sfd.FileName = 'server.cfg'
                    if ($cfgDir -and [System.IO.Directory]::Exists($cfgDir)) { $sfd.InitialDirectory = $cfgDir }
                    if ($sfd.ShowDialog($pv) -ne [System.Windows.Forms.DialogResult]::OK) { return }
                    try { [System.IO.File]::WriteAllText($sfd.FileName, $tb.Text, (New-Object System.Text.UTF8Encoding($false))); Write-PelLog "Server-Baukasten (Jedi Academy): server.cfg gespeichert: $($sfd.FileName)" }
                    catch { Show-Msg ((Get-PelText "Speichern fehlgeschlagen:`n{0}" "Saving failed:`n{0}") -f $_.Exception.Message) 'Jedi Academy' ([System.Windows.Forms.MessageBoxIcon]::Error) }
                })
                $bx.Add_Click({ $pv.Close() })
                $pv.Controls.AddRange(@($tb, $bc, $bsv, $bx))
                [void]$pv.ShowDialog($jd)
                $pv.Dispose()
            })
            $bEsc.Add_Click({ $jd.Close() })
            $bOk.Add_Click({
                $m = & $collect
                if (-not (ConvertTo-PelQ3CfgText (Get-PelJkaCfgVar $m 'rconPassword') 64)) {
                    $q = [PelI18n]::Show($jd, (Get-PelText "Es ist kein RCON-Passwort gesetzt - dann kann niemand den Server aus der Ferne verwalten (Map wechseln, kicken ...).`n`nTrotzdem übernehmen?" "No RCON password is set - then nobody can administer the server remotely (change map, kick ...).`n`nApply anyway?"), 'Jedi Academy', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
                    if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { return }
                }
                $js.Result = $m
                $jd.Close()
            })
            # "&" in Texten ("Server-Identifikation & ...") sonst als Tastenkürzel verschluckt
            $noMn = {
                param($Parent)
                foreach ($cc in $Parent.Controls) {
                    if ($cc -is [System.Windows.Forms.Label] -or $cc -is [System.Windows.Forms.ButtonBase]) { $cc.UseMnemonic = $false }
                    if ($cc.Controls.Count -gt 0) { & $noMn $cc }
                }
            }
            & $noMn $jd
            $jd.Add_Shown({ & $scan $false })
            [void]$jd.ShowDialog($d)
            $jd.Dispose()
            if (-not $js.Result) { return }
            # zurück in den Baukasten: Name, Spieler, Modus, Passwort, Startkarte
            $m = $js.Result
            $bs.JkaCfg = $m
            $bs.Loading = $true
            try {
                $hn = Get-PelJkaCfgVar $m 'sv_hostname'
                if ($hn) { $txtName.Text = $hn }
                $mc = 0
                if ([int]::TryParse([string](Get-PelJkaCfgVar $m 'sv_maxclients'), [ref]$mc)) { $numMax.Value = [decimal][Math]::Max([int]$numMax.Minimum, [Math]::Min([int]$numMax.Maximum, $mc)) }
                $gt = [string](Get-PelJkaCfgVar $m 'g_gametype')
                for ($i = 0; $i -lt @($t.Modes).Count; $i++) { if ([string]$t.Modes[$i][0] -eq $gt) { $cbMode.SelectedIndex = $i } }
                $txtPw.Text = [string](Get-PelJkaCfgVar $m 'g_password')
                if ($m.Rotation.Count -gt 0) {
                    $inRot = $false
                    foreach ($rm in $m.Rotation) { if ($rm -ieq $cbMap.Text.Trim()) { $inRot = $true } }
                    if (-not $inRot) { $cbMap.Text = $m.Rotation[0] }
                }
                & $fillMaps $false
            } finally { $bs.Loading = $false }
            & $updatePreview
        }

        # ---- Fenster "Map-Rotation" (alle Spiele außer Jedi Academy) ----------------------
        # Links alle bekannten Karten (Spielordner, Options-Datei bzw. Vorlage) mit Filter,
        # rechts die Rotation. Reihenfolge per Knopf oder mit der Maus ziehen (auch von links
        # nach rechts an eine bestimmte Stelle). Die erste Karte ist die Startkarte;
        # "Übernehmen" trägt sie als Karte in den Baukasten ein.
        $openRot = {
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            if (-not (Test-PelServerRotation $t)) { return }
            $mv = ''
            if ($cbMode.SelectedIndex -ge 0 -and $cbMode.SelectedIndex -lt @($t.Modes).Count) { $mv = [string]$t.Modes[$cbMode.SelectedIndex][0] }
            $exeDir = ''
            try { if ($txtExe.Text.Trim()) { $exeDir = [System.IO.Path]::GetDirectoryName($txtExe.Text.Trim()) } } catch { }
            $allMaps = New-Object System.Collections.Generic.List[string]
            try { foreach ($m0 in (Get-PelServerMaps $t $exeDir $mv ([string]$bs.FearOptions))) { if ($m0 -and -not $allMaps.Contains([string]$m0)) { $allMaps.Add([string]$m0) } } } catch { }
            $rs = @{ Done = $false; Result = @(); DragIx = -1; DragFrom = ''; DownPt = [System.Drawing.Point]::Empty }
            $cMuted = [System.Drawing.Color]::FromArgb(170, 178, 190)
            $fHint = New-Object System.Drawing.Font('Segoe UI', 8.5, [System.Drawing.FontStyle]::Italic)
            $cRed = [System.Drawing.Color]::FromArgb(160, 50, 40)

            $rd = (New-PelForm)
            $rd.Text = (Get-PelText 'Map-Rotation - {0}' 'Map rotation - {0}') -f $t.Title
            $rd.Size = New-Object System.Drawing.Size(980, 620)
            $rd.MinimumSize = New-Object System.Drawing.Size(860, 520)
            $rd.StartPosition = 'CenterParent'
            $rd.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
            $rd.ForeColor = $cWhite
            $rd.Font = $fontMain
            $rtip = New-Object System.Windows.Forms.ToolTip
            $cw = $rd.ClientSize.Width
            $ch = $rd.ClientSize.Height

            $lblHead = New-DkLabel (Get-PelText 'Karten links auswählen und mit "Hinzufügen" (oder Doppelklick / Ziehen) in die Rotation übernehmen. Rechts die Reihenfolge festlegen: Knöpfe oder Einträge mit der Maus verschieben.' 'Select maps on the left and add them to the rotation with "Add" (or double-click / drag). Set the order on the right: buttons or move entries with the mouse.') 14 10 ($cw - 28) 40
            $lblHead.Anchor = 'Top,Left,Right'
            $rd.Controls.Add($lblHead)

            # -- links: verfügbare Karten --
            $lw = 380
            $lblAll = New-DkLabel ((Get-PelText 'Verfügbare Karten ({0})' 'Available maps ({0})') -f $allMaps.Count) 14 58 180 22
            $txtFlt = New-DkText 198 56 ($lw - 184) 24
            $rtip.SetToolTip($txtFlt, (Get-PelText 'Filter: Teil des Kartennamens, z. B. dm, ctf, dust' 'Filter: part of the map name, e.g. dm, ctf, dust'))
            $lbAll = New-Object System.Windows.Forms.ListBox
            $lbAll.Location = New-Object System.Drawing.Point(14, 86)
            $lbAll.Size = New-Object System.Drawing.Size($lw, ($ch - 86 - 150))
            $lbAll.SelectionMode = 'MultiExtended'
            $lbAll.BackColor = $cList; $lbAll.ForeColor = $cWhite; $lbAll.BorderStyle = 'FixedSingle'
            $lbAll.IntegralHeight = $false
            $lbAll.HorizontalScrollbar = $true
            $lbAll.Anchor = 'Top,Bottom,Left'
            $txtOwn = New-DkText 14 ($ch - 140) ($lw - 150) 26
            $txtOwn.Anchor = 'Bottom,Left'
            $rtip.SetToolTip($txtOwn, (Get-PelText 'Kartenname von Hand (z. B. eigene Karte, die nicht in der Liste steht)' 'Map name by hand (e.g. a custom map that is not in the list)'))
            $bOwn = New-DkButton (Get-PelText 'Eintippen & dazu' 'Type & add') (14 + $lw - 142) ($ch - 142) 142 30
            $bOwn.Anchor = 'Bottom,Left'
            $rd.Controls.AddRange(@($lblAll, $txtFlt, $lbAll, $txtOwn, $bOwn))

            # -- Mitte: Hinzufügen --
            $mx = 14 + $lw + 12
            $bAddSel = New-DkButton (Get-PelText 'Hinzufügen  >' 'Add  >') $mx 140 120 34 $true
            $bAddAll = New-DkButton (Get-PelText 'Alle  >>' 'All  >>') $mx 180 120 30
            $rtip.SetToolTip($bAddAll, (Get-PelText 'Alle Karten der Liste links (mit Filter: nur die gefilterten) anhängen' 'Append all maps of the left list (with filter: only the filtered ones)'))
            $rd.Controls.AddRange(@($bAddSel, $bAddAll))

            # -- rechts: Rotation --
            $rx = $mx + 132
            $bw = 124
            $rlw = $cw - $rx - 14 - $bw - 8
            $lblR = New-DkLabel (Get-PelText 'Rotation - Reihenfolge = Spielreihenfolge' 'Rotation - order = play order') $rx 58 ($rlw + $bw) 22
            $lblR.Anchor = 'Top,Left,Right'
            $lbR = New-Object System.Windows.Forms.ListBox
            $lbR.Location = New-Object System.Drawing.Point($rx, 86)
            $lbR.Size = New-Object System.Drawing.Size($rlw, ($ch - 86 - 150))
            $lbR.SelectionMode = 'MultiExtended'
            $lbR.BackColor = $cList; $lbR.ForeColor = $cWhite; $lbR.BorderStyle = 'FixedSingle'
            $lbR.IntegralHeight = $false
            $lbR.HorizontalScrollbar = $true
            $lbR.AllowDrop = $true
            $lbR.Anchor = 'Top,Bottom,Left,Right'
            $bx = $cw - 14 - $bw
            $bTop = New-DkButton (Get-PelText 'Als Start' 'As start') $bx 86 $bw 30
            $rtip.SetToolTip($bTop, (Get-PelText 'Markierte Karte an den Anfang (= Startkarte)' 'Move selected map to the top (= start map)'))
            $bUp = New-DkButton (Get-PelText 'Nach oben' 'Up') $bx 122 $bw 30
            $bDown = New-DkButton (Get-PelText 'Nach unten' 'Down') $bx 158 $bw 30
            $bShuf = New-DkButton (Get-PelText 'Mischen' 'Shuffle') $bx 206 $bw 30
            $rtip.SetToolTip($bShuf, (Get-PelText 'Reihenfolge zufällig mischen' 'Shuffle the order randomly'))
            $bRem = New-DkButton (Get-PelText 'Entfernen' 'Remove') $bx 254 $bw 30
            $bRem.BackColor = $cRed
            $bClr = New-DkButton (Get-PelText 'Alle leeren' 'Clear all') $bx 290 $bw 30
            foreach ($b0 in @($bTop, $bUp, $bDown, $bShuf, $bRem, $bClr)) { $b0.Anchor = 'Top,Right' }
            $lblCnt = New-DkLabel '' $rx ($ch - 140) ($rlw + $bw) 22
            $lblCnt.Anchor = 'Bottom,Left,Right'
            $rd.Controls.AddRange(@($lblR, $lbR, $bTop, $bUp, $bDown, $bShuf, $bRem, $bClr, $lblCnt))

            # -- unten: Hinweis + Knöpfe --
            $lblHint = New-DkLabel (Get-PelServerRotationHint $t) 14 ($ch - 104) ($cw - 28) 52
            $lblHint.Font = $fHint
            $lblHint.ForeColor = $cMuted
            $lblHint.Anchor = 'Bottom,Left,Right'
            $bOk = New-DkButton (Get-PelText 'Übernehmen' 'Apply') ($cw - 14 - 130 - 8 - 170) ($ch - 46) 170 36 $true
            $bEsc = New-DkButton (Get-PelText 'Abbrechen' 'Cancel') ($cw - 14 - 130) ($ch - 46) 130 36
            foreach ($b0 in @($bOk, $bEsc)) { $b0.Anchor = 'Bottom,Right' }
            $rd.Controls.AddRange(@($lblHint, $bOk, $bEsc))
            $rd.CancelButton = $bEsc
            foreach ($cc in $rd.Controls) { if ($cc -is [System.Windows.Forms.Label] -or $cc -is [System.Windows.Forms.ButtonBase]) { $cc.UseMnemonic = $false } }

            # bisherige Rotation, sonst die gewählte Karte als Start
            foreach ($r0 in @($bs.Rotation)) { if ($r0) { [void]$lbR.Items.Add([string]$r0) } }
            if ($lbR.Items.Count -eq 0 -and $cbMap.Text.Trim()) { [void]$lbR.Items.Add($cbMap.Text.Trim()) }

            $fillAll = {
                $f = $txtFlt.Text.Trim()
                $lbAll.BeginUpdate()
                try {
                    $lbAll.Items.Clear()
                    foreach ($m1 in $allMaps) { if (-not $f -or $m1.IndexOf($f, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { [void]$lbAll.Items.Add($m1) } }
                } finally { $lbAll.EndUpdate() }
            }
            $updCnt = {
                $n = $lbR.Items.Count
                if ($n -eq 0) { $lblCnt.Text = Get-PelText 'Keine Rotation - es läuft nur die Karte aus dem Baukasten.' 'No rotation - only the map from the builder runs.' }
                elseif ($n -eq 1) { $lblCnt.Text = (Get-PelText '1 Karte = nur Startkarte ({0}). Für eine Rotation mindestens 2 Karten.' '1 map = start map only ({0}). For a rotation at least 2 maps.') -f $lbR.Items[0] }
                else { $lblCnt.Text = (Get-PelText '{0} Karten - Start: {1}, danach der Reihe nach, am Ende wieder von vorne.' '{0} maps - start: {1}, then in order, at the end from the top again.') -f $n, $lbR.Items[0] }
            }
            # Karten an Position $At einfügen (-1 = hinten anhängen)
            $insMaps = {
                param($Maps, [int]$At = -1)
                $pos = if ($At -lt 0 -or $At -gt $lbR.Items.Count) { $lbR.Items.Count } else { $At }
                $lbR.ClearSelected()
                foreach ($m2 in @($Maps)) {
                    $mm = (([string]$m2) -replace '[";]', '').Trim()
                    if (-not $mm -or $lbR.Items.Count -ge 100) { continue }
                    $lbR.Items.Insert($pos, $mm)
                    $lbR.SetSelected($pos, $true)
                    $pos++
                }
                & $updCnt
            }
            # markierte Einträge um $Dir verschieben (-1 hoch, +1 runter), Auswahl bleibt
            $moveSel = {
                param([int]$Dir)
                $sel = @($lbR.SelectedIndices | ForEach-Object { [int]$_ } | Sort-Object)
                if ($sel.Count -eq 0) { return }
                if ($Dir -lt 0 -and $sel[0] -le 0) { return }
                if ($Dir -gt 0 -and $sel[$sel.Count - 1] -ge $lbR.Items.Count - 1) { return }
                if ($Dir -gt 0) { [array]::Reverse($sel) }
                $lbR.BeginUpdate()
                try {
                    foreach ($i in $sel) {
                        $it = $lbR.Items[$i]
                        $lbR.Items.RemoveAt($i)
                        $lbR.Items.Insert($i + $Dir, $it)
                    }
                    $lbR.ClearSelected()
                    foreach ($i in $sel) { $lbR.SetSelected($i + $Dir, $true) }
                } finally { $lbR.EndUpdate() }
                & $updCnt
            }

            $txtFlt.Add_TextChanged({ & $fillAll })
            $bAddSel.Add_Click({ & $insMaps @($lbAll.SelectedItems | ForEach-Object { [string]$_ }) })
            $bAddAll.Add_Click({ & $insMaps @($lbAll.Items | ForEach-Object { [string]$_ }) })
            $lbAll.Add_DoubleClick({ if ($lbAll.SelectedItem) { & $insMaps @([string]$lbAll.SelectedItem) } })
            $bOwn.Add_Click({
                $v = $txtOwn.Text.Trim()
                if (-not $v) { return }
                & $insMaps @($v)
                $txtOwn.Text = ''
            })
            $txtOwn.Add_KeyDown({ param($s, $e) if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $e.SuppressKeyPress = $true; $bOwn.PerformClick() } })
            $bUp.Add_Click({ & $moveSel (-1) })
            $bDown.Add_Click({ & $moveSel 1 })
            $bTop.Add_Click({
                if ($lbR.SelectedIndex -le 0) { return }
                $i = $lbR.SelectedIndex
                $it = $lbR.Items[$i]
                $lbR.Items.RemoveAt($i)
                $lbR.Items.Insert(0, $it)
                $lbR.ClearSelected()
                $lbR.SetSelected(0, $true)
                & $updCnt
            })
            $bShuf.Add_Click({
                $items = @($lbR.Items | ForEach-Object { [string]$_ })
                if ($items.Count -lt 2) { return }
                $rnd = New-Object System.Random
                for ($i = $items.Count - 1; $i -gt 0; $i--) { $j = $rnd.Next($i + 1); $tmp = $items[$i]; $items[$i] = $items[$j]; $items[$j] = $tmp }
                $lbR.Items.Clear()
                foreach ($it in $items) { [void]$lbR.Items.Add($it) }
                & $updCnt
            })
            $bRem.Add_Click({
                $sel = @($lbR.SelectedIndices | ForEach-Object { [int]$_ } | Sort-Object -Descending)
                foreach ($i in $sel) { $lbR.Items.RemoveAt($i) }
                & $updCnt
            })
            $lbR.Add_KeyDown({ param($s, $e) if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Delete) { $bRem.PerformClick() } })
            $bClr.Add_Click({ $lbR.Items.Clear(); & $updCnt })

            # Ziehen mit der Maus: in der Rotation verschieben oder von links an eine Stelle einfügen.
            # Gezogen wird erst nach ein paar Pixeln Bewegung, damit Klicks/Mehrfachauswahl normal gehen.
            $dragStart = {
                param($Lb, [string]$From, $e)
                if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Left) { $rs.DragIx = -1; return }
                $rs.DragIx = $Lb.IndexFromPoint($e.Location)
                $rs.DragFrom = $From
                $rs.DownPt = $e.Location
            }
            $dragMove = {
                param($Lb, $e)
                if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Left -or $rs.DragIx -lt 0) { return }
                $ds = [System.Windows.Forms.SystemInformation]::DragSize
                if ([Math]::Abs($e.X - $rs.DownPt.X) -lt $ds.Width -and [Math]::Abs($e.Y - $rs.DownPt.Y) -lt $ds.Height) { return }
                $ix = $rs.DragIx
                $rs.DragIx = -1
                if ($ix -ge $Lb.Items.Count) { return }
                $rs.DragIx = $ix
                [void]$Lb.DoDragDrop([string]$Lb.Items[$ix], [System.Windows.Forms.DragDropEffects]::Move -bor [System.Windows.Forms.DragDropEffects]::Copy)
                $rs.DragIx = -1
            }
            $lbR.Add_MouseDown({ param($s, $e) & $dragStart $lbR 'rot' $e })
            $lbR.Add_MouseMove({ param($s, $e) & $dragMove $lbR $e })
            $lbAll.Add_MouseDown({ param($s, $e) & $dragStart $lbAll 'all' $e })
            $lbAll.Add_MouseMove({ param($s, $e) & $dragMove $lbAll $e })
            $lbR.Add_DragOver({
                param($s, $e)
                if (-not $e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::Text)) { $e.Effect = [System.Windows.Forms.DragDropEffects]::None; return }
                $e.Effect = $(if ($rs.DragFrom -eq 'rot') { [System.Windows.Forms.DragDropEffects]::Move } else { [System.Windows.Forms.DragDropEffects]::Copy })
            })
            $lbR.Add_DragDrop({
                param($s, $e)
                $pt = $lbR.PointToClient((New-Object System.Drawing.Point($e.X, $e.Y)))
                $to = $lbR.IndexFromPoint($pt)
                if ($to -lt 0) { $to = $lbR.Items.Count }
                if ($rs.DragFrom -eq 'rot') {
                    $from = $rs.DragIx
                    if ($from -lt 0 -or $from -ge $lbR.Items.Count -or $from -eq $to) { return }
                    $it = $lbR.Items[$from]
                    $lbR.Items.RemoveAt($from)
                    if ($to -gt $from) { $to-- }
                    if ($to -gt $lbR.Items.Count) { $to = $lbR.Items.Count }
                    $lbR.Items.Insert($to, $it)
                    $lbR.ClearSelected()
                    $lbR.SetSelected($to, $true)
                    & $updCnt
                } else {
                    & $insMaps @([string]$e.Data.GetData([System.Windows.Forms.DataFormats]::Text)) $to
                }
            })

            $bEsc.Add_Click({ $rd.Close() })
            $bOk.Add_Click({
                $rs.Result = @($lbR.Items | ForEach-Object { [string]$_ } | Where-Object { $_ })
                $rs.Done = $true
                $rd.Close()
            })
            & $fillAll
            & $updCnt
            [void]$rd.ShowDialog($d)
            $rd.Dispose()
            if (-not $rs.Done) { return }
            $bs.Rotation = @($rs.Result)
            if (@($bs.Rotation).Count -gt 0) {
                $bs.Loading = $true
                try { $cbMap.Text = [string]@($bs.Rotation)[0] } finally { $bs.Loading = $false }
            }
            & $updRotBtn
            & $updatePreview
        }

        $bSteam.Add_Click({ & $openSteam })
        $bJka.Add_Click({ & $openJkaCfg })
        $cbGame.Add_SelectedIndexChanged({ if (-not $bs.Loading) { $bs.JkaCfg = $null; $bs.Rotation = @(); & $applyTemplate $true } })
        $bRot.Add_Click({ & $openRot })
        foreach ($c in @($txtName, $txtPw, $txtExtra, $txtExe)) { $c.Add_TextChanged({ & $updatePreview }) }
        $cbMap.Add_TextChanged({ & $updatePreview })
        $cbMode.Add_SelectedIndexChanged({
            if (-not $bs.Loading -and $tpls[[Math]::Max(0, $cbGame.SelectedIndex)].Key -eq 'fear') {
                $bs.Loading = $true
                try { & $fillMaps $true } finally { $bs.Loading = $false }
            }
            & $updatePreview
        })
        $bOpt.Add_Click({
            $ofd = New-Object System.Windows.Forms.OpenFileDialog
            $ofd.Title = (Get-PelText 'F.E.A.R.-Options-Datei auswählen (z. B. ExampleServerOptions.txt)' 'Select F.E.A.R. options file (e.g. ExampleServerOptions.txt)')
            $ofd.Filter = 'Server-Optionen (*.txt)|*.txt|Alle Dateien (*.*)|*.*'
            $cur = Find-PelFearExampleOptions $(if ($txtExe.Text) { [System.IO.Path]::GetDirectoryName($txtExe.Text) } else { '' }) ([string]$bs.FearOptions)
            if ($cur) { $ofd.InitialDirectory = [System.IO.Path]::GetDirectoryName($cur) }
            elseif ($env:PUBLIC -and [System.IO.Directory]::Exists((Join-Path $env:PUBLIC 'Documents\Monolith Productions'))) { $ofd.InitialDirectory = (Join-Path $env:PUBLIC 'Documents\Monolith Productions') }
            if ($ofd.ShowDialog($d) -ne [System.Windows.Forms.DialogResult]::OK) { return }
            if ([System.IO.Path]::GetFileName($ofd.FileName) -like 'PEL_*') { Show-Msg (Get-PelText 'Bitte das Original wählen (z. B. ExampleServerOptions.txt), nicht eine PEL_-Kopie des Baukastens.' 'Please pick the original (e.g. ExampleServerOptions.txt), not a PEL_ copy made by the builder.'); return }
            $bs.FearOptions = $ofd.FileName
            $bs.Loading = $true
            try { & $fillMaps $true } finally { $bs.Loading = $false }
            & $updatePreview
        })
        $numPort.Add_ValueChanged({ & $updatePreview })
        $numMax.Add_ValueChanged({ & $updatePreview })
        $chkNet.Add_CheckedChanged({ & $updatePreview })
        $bFind.Add_Click({
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            $p = Find-PelServerExe $t
            if ($p) { $txtExe.Text = $p; & $applyTemplate $false }
            else { Show-Msg ((Get-PelText "Keine passende Server-EXE gefunden ({0}).`n`nBitte mit 'Durchsuchen' selbst auswählen - der Server liegt oft in einem eigenen Ordner (z. B. 'FEAR Standalone Server' oder 'HLServer')." "No matching server EXE found ({0}).`n`nPlease select it yourself with 'Browse' - the server often lives in its own folder (e.g. 'FEAR Standalone Server' or 'HLServer').") -f (@($t.Exe) -join ', ')) }
        })
        $bBrowse.Add_Click({
            $t = $tpls[[Math]::Max(0, $cbGame.SelectedIndex)]
            $ofd = New-Object System.Windows.Forms.OpenFileDialog
            $ofd.Title = (Get-PelText 'Server-EXE auswählen' 'Select server EXE')
            $flt = if (@($t.Exe).Count -gt 0) { (@($t.Exe) -join ';') } else { '*.exe' }
            $ofd.Filter = "Server ($flt)|$flt|Programme (*.exe)|*.exe"
            if ($txtExe.Text -and [System.IO.File]::Exists($txtExe.Text)) { $ofd.InitialDirectory = [System.IO.Path]::GetDirectoryName($txtExe.Text) }
            if ($ofd.ShowDialog($d) -eq [System.Windows.Forms.DialogResult]::OK) { $txtExe.Text = $ofd.FileName; & $applyTemplate $false }
        })
        $lbSaved.Add_SelectedIndexChanged({
            if ($lbSaved.SelectedIndex -ge 0 -and $lbSaved.SelectedIndex -lt $bs.Saved.Count) { & $showSaved $bs.Saved[$lbSaved.SelectedIndex] }
        })
        $bNew.Add_Click({ $lbSaved.ClearSelected(); $bs.FearOptions = ''; $bs.JkaCfg = $null; $bs.Rotation = @(); $txtName.Text = ''; $txtPw.Text = ''; $txtExtra.Text = ''; & $applyTemplate $true })
        $bSave.Add_Click({
            $bat = & $saveNow
            if ($bat) { $lblNotes.Text = (Get-PelText 'Gespeichert: {0}' 'Saved: {0}') -f $bat }
        })
        $bSaveStart.Add_Click({
            $bat = & $saveNow
            if (-not $bat) { return }
            $sv = @($bs.Saved | Where-Object { $_.Bat -eq $bat }) | Select-Object -First 1
            if ($sv) { & $startBat $bat $sv }
        })
        $bStartSaved.Add_Click({
            if ($lbSaved.SelectedIndex -lt 0) { Show-Msg (Get-PelText 'Bitte links einen gespeicherten Server auswählen.' 'Please select a saved server on the left.'); return }
            $sv = $bs.Saved[$lbSaved.SelectedIndex]
            & $startBat ([string]$sv.Bat) $sv
        })
        $lbSaved.Add_DoubleClick({ $bStartSaved.PerformClick() })
        $bDel.Add_Click({
            if ($lbSaved.SelectedIndex -lt 0) { return }
            $sv = $bs.Saved[$lbSaved.SelectedIndex]
            $q = [PelI18n]::Show($d, ((Get-PelText "Server '{0}' löschen?`n`nEntfernt die .bat, die Einstellungen und die vom Baukasten angelegten PEL_-Dateien. Das Spiel selbst bleibt unverändert." "Delete server '{0}'?`n`nRemoves the .bat, the settings and the PEL_ files created by the builder. The game itself is not changed.") -f $sv.Name), 'Server-Baukasten', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
            if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { return }
            foreach ($f in @(@($sv.Files) + @([string]$sv.Bat, [string]$sv.Json))) {
                # nur eigene Dateien: die .bat/.json im Server-Ordner und PEL_-Kopien
                if (-not $f) { continue }
                $leaf = [System.IO.Path]::GetFileName($f)
                if ($f.StartsWith($script:PelServerDir, [System.StringComparison]::OrdinalIgnoreCase) -or $leaf.StartsWith('PEL_')) {
                    try { if ([System.IO.File]::Exists($f)) { [System.IO.File]::Delete($f) } } catch { }
                }
            }
            & $loadSaved
        })
        $bDir.Add_Click({
            if (-not [System.IO.Directory]::Exists($script:PelServerDir)) { [void][System.IO.Directory]::CreateDirectory($script:PelServerDir) }
            try { Start-Process explorer.exe -ArgumentList "`"$($script:PelServerDir)`"" } catch { }
        })
        $bClose.Add_Click({ $d.Close() })
        $d.Add_Shown({
            & $loadSaved
            $cbGame.SelectedIndex = 0
        })
        [void]$d.ShowDialog($form)
        $d.Dispose()
    }

    # ===================================================================================
    # GUI
    # ===================================================================================
