    if ($script:PelLang -eq 'en') { [PelI18n]::Load([IO.File]::ReadAllText((Join-Path $env:APPDATA 'ProjectEarthLan\PelI18n_en.txt'))); [PelI18n]::Enabled = $true }
} catch { }
