function New-PelContextMenu { $m = New-Object -TypeName System.Windows.Forms.ContextMenuStrip; if ([PelI18n]::Enabled) { [PelI18n]::AttachStrip($m) }; return $m }
'@

$script:PelKodiSteuerungScript = @'
<#
==============================================================================
 KODI-STEUERUNG - Fernbedienung mit Live-Fenster (PowerShell 5.1, WinForms)
==============================================================================
#>
param(
    [string]$Befehl = '',
    [string]$Url = '',
    [string]$Taste = '',
    [string]$KodiHost = '',
    [int]$Port = 0,
    [string]$Benutzer = '',
    [string]$Passwort = ''
)

$ErrorActionPreference = 'Continue'
Add-Type -AssemblyName System.Security
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

# ------------------------------------------------------------------------------
# Globaler Tastatur-Hook fuer die Mediensteuerung: Space/Pfeiltasten sollen auch
# dann wirken, wenn gerade das eingebettete mpv-/VLC-Videobild (ein fremdes,
# per --wid/--drawable-hwnd eingebettetes Prozessfenster) den Tastaturfokus hat -
# ein normaler WinForms-KeyDown-Handler bekommt diese Tasten dann NICHT mehr, weil
# Windows sie direkt an den mpv/VLC-Prozess liefert. Der Low-Level-Hook sieht jeden
# Tastendruck im System, wirkt hier aber NUR, wenn dieses Fenster (Kodi-Steuerung)
# gerade im Vordergrund ist - andere Programme sind nie betroffen.
# Hinweis: Dieser Text steckt selbst in einem Single-Quote-Here-String - ein innerer
# @'...'@ wuerde ihn vorzeitig beenden. Deshalb hier ein Double-Quote-Here-String,
# dessen Anfuehrungszeichen als Platzhalter (U+00A4) geschrieben und zur Laufzeit ersetzt werden.
$ksHookCs = @"
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;

public static class KsKeyHook
{
    private delegate IntPtr LowLevelProc(int nCode, IntPtr wParam, IntPtr lParam);

    [StructLayout(LayoutKind.Sequential)]
    private struct RECT { public int Left; public int Top; public int Right; public int Bottom; }

    [DllImport(¤user32.dll¤, CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelProc lpfn, IntPtr hMod, uint dwThreadId);

    [DllImport(¤user32.dll¤, CharSet = CharSet.Auto, SetLastError = true)]
    private static extern bool UnhookWindowsHookEx(IntPtr hhk);

    [DllImport(¤user32.dll¤, CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport(¤kernel32.dll¤, CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr GetModuleHandle(string lpModuleName);

    [DllImport(¤user32.dll¤)]
    private static extern IntPtr GetForegroundWindow();

    [DllImport(¤user32.dll¤)]
    private static extern IntPtr GetAncestor(IntPtr hwnd, uint gaFlags);

    [DllImport(¤user32.dll¤)]
    private static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);

    [DllImport(¤user32.dll¤)]
    private static extern bool IsWindowVisible(IntPtr hWnd);

    private const int WH_KEYBOARD_LL = 13;
    private const int WH_MOUSE_LL = 14;
    private const int WM_KEYDOWN = 0x0100;
    private const int WM_SYSKEYDOWN = 0x0104;
    private const int WM_KEYUP = 0x0101;
    private const int WM_SYSKEYUP = 0x0105;
    private const int WM_LBUTTONDOWN = 0x0201;
    private const uint GA_ROOT = 2;

    // Sentinel-Wert in der Keys-Warteschlange fuer ¤Linksklick auf das Videobild¤.
    public const int MouseClickMarker = -1;

    private static IntPtr keyHookId = IntPtr.Zero;
    private static IntPtr mouseHookId = IntPtr.Zero;
    private static LowLevelProc keyProc = KeyboardHookCallback;
    private static LowLevelProc mouseProc = MouseHookCallback;

    // Von PowerShell gesetzt/gelesen:
    public static IntPtr TargetHwnd = IntPtr.Zero;   // Hauptfenster Kodi-Steuerung
    public static IntPtr VideoAreaHwnd = IntPtr.Zero; // Panel, in das mpv/VLC eingebettet wird
    // Eingeblendete Leisten ueber dem Video (Suche, Bedienknoepfe): Klicks dort sind
    // normale Klicks und werden NICHT als Pause abgefangen.
    public static IntPtr[] ExcludeHwnds = new IntPtr[0];
    public static bool Enabled = true;
    public static int ToggleKey = 0;
    public static int[] WatchedKeys = new int[0];
    public static ConcurrentQueue<int> Keys = new ConcurrentQueue<int>();
    // true, solange ein Textfeld/Auswahlfeld des Fensters den Fokus hat: dann Tasten normal durchlassen.
    public static volatile bool TextFocus = false;
    private static HashSet<int> downKeys = new HashSet<int>();

    private static bool IsOurWindowForeground()
    {
        IntPtr fg = GetForegroundWindow();
        if (fg == TargetHwnd) return true;
        IntPtr fgRoot = GetAncestor(fg, GA_ROOT);
        return fgRoot == TargetHwnd;
    }

    public static bool Start(IntPtr targetHwnd, IntPtr videoAreaHwnd)
    {
        TargetHwnd = targetHwnd;
        VideoAreaHwnd = videoAreaHwnd;
        using (Process curProcess = Process.GetCurrentProcess())
        using (ProcessModule curModule = curProcess.MainModule)
        {
            IntPtr hMod = GetModuleHandle(curModule.ModuleName);
            if (keyHookId == IntPtr.Zero) keyHookId = SetWindowsHookEx(WH_KEYBOARD_LL, keyProc, hMod, 0);
            if (mouseHookId == IntPtr.Zero) mouseHookId = SetWindowsHookEx(WH_MOUSE_LL, mouseProc, hMod, 0);
        }
        return keyHookId != IntPtr.Zero && mouseHookId != IntPtr.Zero;
    }

    public static void Stop()
    {
        if (keyHookId != IntPtr.Zero) { UnhookWindowsHookEx(keyHookId); keyHookId = IntPtr.Zero; }
        if (mouseHookId != IntPtr.Zero) { UnhookWindowsHookEx(mouseHookId); mouseHookId = IntPtr.Zero; }
    }

    private static bool IsRepeatable(int vk) { return vk >= 37 && vk <= 40; }

    private static IntPtr KeyboardHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode >= 0)
        {
            int msg = (int)wParam;
            if (msg == WM_KEYUP || msg == WM_SYSKEYUP)
            {
                downKeys.Remove(Marshal.ReadInt32(lParam));
            }
            else if (TargetHwnd != IntPtr.Zero && (msg == WM_KEYDOWN || msg == WM_SYSKEYDOWN) && IsOurWindowForeground())
            {
                int vk = Marshal.ReadInt32(lParam);
                bool isToggle = (ToggleKey != 0 && vk == ToggleKey);
                bool isWatched = false;
                if (!isToggle && Enabled && !TextFocus)
                {
                    for (int i = 0; i < WatchedKeys.Length; i++) { if (WatchedKeys[i] == vk) { isWatched = true; break; } }
                }
                if (isToggle || isWatched)
                {
                    bool repeat = downKeys.Contains(vk);
                    downKeys.Add(vk);
                    if (!repeat || IsRepeatable(vk)) Keys.Enqueue(vk);
                    return (IntPtr)1;
                }
            }
        }
        return CallNextHookEx(keyHookId, nCode, wParam, lParam);
    }

    private static IntPtr MouseHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode >= 0 && (int)wParam == WM_LBUTTONDOWN && Enabled && TargetHwnd != IntPtr.Zero && VideoAreaHwnd != IntPtr.Zero)
        {
            if (IsOurWindowForeground())
            {
                int x = Marshal.ReadInt32(lParam, 0);
                int y = Marshal.ReadInt32(lParam, 4);
                RECT r;
                if (GetWindowRect(VideoAreaHwnd, out r))
                {
                    if (x >= r.Left && x <= r.Right && y >= r.Top && y <= r.Bottom)
                    {
                        IntPtr[] ex = ExcludeHwnds;
                        for (int i = 0; i < ex.Length; i++)
                        {
                            RECT er;
                            if (ex[i] != IntPtr.Zero && IsWindowVisible(ex[i]) && GetWindowRect(ex[i], out er) && x >= er.Left && x <= er.Right && y >= er.Top && y <= er.Bottom)
                                return CallNextHookEx(mouseHookId, nCode, wParam, lParam);
                        }
                        Keys.Enqueue(MouseClickMarker);
                        return (IntPtr)1;
                    }
                }
            }
        }
        return CallNextHookEx(mouseHookId, nCode, wParam, lParam);
    }
}
"@
$ksHookCs = $ksHookCs.Replace([string][char]0xA4, [string][char]34)
$script:KsHookError = ''
$script:KsHookOk = $false
try { Add-Type -TypeDefinition $ksHookCs -Language CSharp -ErrorAction Stop } catch { $script:KsHookError = $_.Exception.Message }

function Get-KsKeyLabel([int]$vk) {
    if ($vk -le 0) { return '(keine)' }
    try { return ([System.Windows.Forms.Keys]$vk).ToString() } catch { return "VK$vk" }
}

# ------------------------------------------------------------------------------
# Einstellungen & Pfade
# ------------------------------------------------------------------------------
$ksBase = $env:APPDATA
if (-not $ksBase) { $ksBase = [Environment]::GetFolderPath('ApplicationData') }
if (-not $ksBase) { $ksBase = $HOME }

$script:KsDir  = Join-Path $ksBase 'KodiSteuerung'
$script:KsFile = Join-Path $script:KsDir 'einstellungen.json'
$script:Ks = @{
    Host = '192.168.1.50'
    Port = 8080
    User = 'kodi'
    Pass = ''
    Player = 'auto'
    LiveAuto = $false
    ShortcutsEnabled = $true
    ToggleKey = 120
}

function Read-KsSettings {
    try {
        if (Test-Path -LiteralPath $script:KsFile) {
            $o = [System.IO.File]::ReadAllText($script:KsFile, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
            if ($o.Host) { $script:Ks.Host = [string]$o.Host }
            if ($o.Port) { $script:Ks.Port = [int]$o.Port }
            if ($null -ne $o.User) { $script:Ks.User = [string]$o.User }
            if ($o.Player) { $script:Ks.Player = [string]$o.Player }
            if ($null -ne $o.LiveAuto) { $script:Ks.LiveAuto = [bool]$o.LiveAuto }
            if ($null -ne $o.ShortcutsEnabled) { $script:Ks.ShortcutsEnabled = [bool]$o.ShortcutsEnabled }
            if ($o.ToggleKey) { $script:Ks.ToggleKey = [int]$o.ToggleKey }
            if ($o.PassEnc) {
                try {
                    $b = [System.Security.Cryptography.ProtectedData]::Unprotect(
                        [Convert]::FromBase64String([string]$o.PassEnc),
                        $null,
                        [System.Security.Cryptography.DataProtectionScope]::CurrentUser
                    )
                    $script:Ks.Pass = [System.Text.Encoding]::UTF8.GetString($b)
                } catch { }
            }
        }
    } catch { }
}

function Save-KsSettings {
    try {
        if (-not (Test-Path -LiteralPath $script:KsDir)) {
            New-Item -Path $script:KsDir -ItemType Directory -Force | Out-Null
        }
        $enc = ''
        if ($script:Ks.Pass) {
            $enc = [Convert]::ToBase64String(
                [System.Security.Cryptography.ProtectedData]::Protect(
                    [System.Text.Encoding]::UTF8.GetBytes($script:Ks.Pass),
                    $null,
                    [System.Security.Cryptography.DataProtectionScope]::CurrentUser
                )
            )
        }
        $o = [ordered]@{
            Host = $script:Ks.Host
            Port = $script:Ks.Port
            User = $script:Ks.User
            PassEnc = $enc
            Player = $script:Ks.Player
            LiveAuto = $script:Ks.LiveAuto
            ShortcutsEnabled = $script:Ks.ShortcutsEnabled
            ToggleKey = $script:Ks.ToggleKey
        }
        [System.IO.File]::WriteAllText($script:KsFile, ($o | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($false)))
    } catch { }
}

function Get-KsBaseUrl {
    return ('http://{0}:{1}' -f $script:Ks.Host, $script:Ks.Port)
}

# ------------------------------------------------------------------------------
# JSON-RPC Kommunikation
# ------------------------------------------------------------------------------
$script:KsRpcId = 0

function Invoke-Kodi {
    param(
        [string]$Method,
        $Params = $null,
        [int]$TimeoutMs = 2500
    )
    $r = @{ Ok = $false; Result = $null; Error = '' }
    $script:KsRpcId++
    $body = [ordered]@{ jsonrpc = '2.0'; method = $Method; id = $script:KsRpcId }
    if ($null -ne $Params) { $body.params = $Params }

    try {
        $json = $body | ConvertTo-Json -Compress -Depth 8
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
        $req = [System.Net.HttpWebRequest]::Create((Get-KsBaseUrl) + '/jsonrpc')
        $req.Method = 'POST'
        $req.ContentType = 'application/json'
        $req.Timeout = $TimeoutMs
        $req.ReadWriteTimeout = $TimeoutMs
        $req.KeepAlive = $true

        if ($script:Ks.User -or $script:Ks.Pass) {
            $tok = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($script:Ks.User + ':' + $script:Ks.Pass))
            $req.Headers.Add('Authorization', 'Basic ' + $tok)
        }

        $req.ContentLength = $bytes.Length
        $rs = $req.GetRequestStream()
        try { $rs.Write($bytes, 0, $bytes.Length) } finally { $rs.Dispose() }

        $resp = $null
        try {
            $resp = $req.GetResponse()
        } catch [System.Net.WebException] {
            if ($_.Exception.Response) { $resp = $_.Exception.Response } else { throw }
        }

        try {
            $code = [int]$resp.StatusCode
            $sr = New-Object System.IO.StreamReader($resp.GetResponseStream(), [System.Text.Encoding]::UTF8)
            $text = $sr.ReadToEnd()
            $sr.Dispose()
        } finally {
            if ($resp) { $resp.Close() }
        }

        if ($code -eq 401) {
            $r.Error = 'Benutzername oder Passwort falsch (Kodi: Einstellungen -> Dienste -> Steuerung).'
            return $r
        }
        if ($code -ne 200) {
            $r.Error = "Kodi antwortet mit Fehler $code."
            return $r
        }

        $o = $text | ConvertFrom-Json
        if ($o.PSObject.Properties['error'] -and $o.error) {
            $r.Error = [string]$o.error.message
            return $r
        }

        $r.Ok = $true
        $r.Result = $o.result
    } catch {
        $r.Error = "Kodi nicht erreichbar ($(Get-KsBaseUrl)): $($_.Exception.Message)"
    }
    return $r
}

$script:KsLastError = ''
function Get-KsPlayer {
    $script:KsLastError = ''
    $r = Invoke-Kodi 'Player.GetActivePlayers'
    if (-not $r.Ok) {
        $script:KsLastError = $r.Error
        return $null
    }
    $list = @($r.Result)
    $p = $list | Where-Object { $_.type -eq 'video' } | Select-Object -First 1
    if (-not $p) { $p = $list | Select-Object -First 1 }
    return $p
}

function Invoke-KsPlayerCmd {
    param(
        [string]$Method,
        [hashtable]$Extra = @{}
    )
    $p = Get-KsPlayer
    if (-not $p) {
        if ($script:KsLastError) { return @{ Ok = $false; Error = $script:KsLastError } }
        return @{ Ok = $false; Error = 'Gerade läuft nichts auf Kodi.' }
    }
    $params = @{ playerid = [int]$p.playerid }
    foreach ($k in $Extra.Keys) { $params[$k] = $Extra[$k] }
    return (Invoke-Kodi $Method $params)
}

function Get-KsVolume {
    $r = Invoke-Kodi 'Application.GetProperties' @{ properties = @('volume', 'muted') }
    if ($r.Ok) { return $r.Result }
    return $null
}

function Set-KsVolumeStep([int]$Delta) {
    $v = Get-KsVolume
    if (-not $v) { return }
    $n = [Math]::Max(0, [Math]::Min(100, [int]$v.volume + $Delta))
    [void](Invoke-Kodi 'Application.SetVolume' @{ volume = $n })
}

function Format-KsTime($t) {
    if (-not $t) { return '0:00' }
    $s = [int]$t.hours * 3600 + [int]$t.minutes * 60 + [int]$t.seconds
    $h = [int][Math]::Floor($s / 3600)
    $m = [int][Math]::Floor(($s % 3600) / 60)
    $sec = $s % 60
    if ($h -gt 0) { return ('{0}:{1:00}:{2:00}' -f $h, $m, $sec) }
    return ('{0}:{1:00}' -f $m, $sec)
}

function Get-KsSeconds($t) {
    if (-not $t) { return 0 }
    return [int]$t.hours * 3600 + [int]$t.minutes * 60 + [int]$t.seconds
}

function Get-KsNowPlaying {
    $p = Get-KsPlayer
    if (-not $p) { return $null }
    $pid_ = [int]$p.playerid
    $it = Invoke-Kodi 'Player.GetItem' @{ playerid = $pid_; properties = @('title', 'showtitle', 'season', 'episode', 'artist', 'album', 'thumbnail', 'fanart', 'file', 'year') }
    $pr = Invoke-Kodi 'Player.GetProperties' @{ playerid = $pid_; properties = @('time', 'totaltime', 'percentage', 'speed') }
    $item = $null; if ($it.Ok) { $item = $it.Result.item }
    $prop = $null; if ($pr.Ok) { $prop = $pr.Result }

    $titel = ''
    if ($item) {
        $titel = [string]$item.title
        if (-not $titel) { $titel = [string]$item.label }
        if ($item.showtitle) {
            $titel = "{0} - S{1:00}E{2:00} {3}" -f $item.showtitle, [int]$item.season, [int]$item.episode, $titel
        } elseif ($item.artist -and @($item.artist).Count -gt 0) {
            $titel = (@($item.artist) -join ', ') + ' - ' + $titel
        }
        if (-not $titel) { $titel = [System.IO.Path]::GetFileName([string]$item.file) }
    }

    return [pscustomobject]@{
        PlayerId = $pid_
        Type     = [string]$p.type
        Title    = $titel
        File     = $(if ($item) { [string]$item.file } else { '' })
        Thumb    = $(if ($item) { if ($item.thumbnail) { [string]$item.thumbnail } else { [string]$item.fanart } } else { '' })
        Time     = $(if ($prop) { $prop.time } else { $null })
        Total    = $(if ($prop) { $prop.totaltime } else { $null })
        Percent  = $(if ($prop) { [double]$prop.percentage } else { 0 })
        Speed    = $(if ($prop) { [int]$prop.speed } else { 0 })
    }
}

function Get-KsMirrorUrl([string]$File) {
    if (-not $File) { return '' }
    if ($File -match '^(?i)(https?|rtsp|rtmp|rtmps|mms|udp|rtp|srt)://') { return ($File -split '\|')[0] }
    if ($File -match '^(?i)(pvr|dvd|bluray|iso9660|plugin|upnp)://') { return '' }
    $u = (Get-KsBaseUrl) + '/vfs/' + [Uri]::EscapeDataString($File)
    if ($script:Ks.User -or $script:Ks.Pass) {
        $u = $u -replace '^http://', ('http://' + [Uri]::EscapeDataString($script:Ks.User) + ':' + [Uri]::EscapeDataString($script:Ks.Pass) + '@')
    }
    return $u
}

# ------------------------------------------------------------------------------
# Kommandozeilenmodus
# ------------------------------------------------------------------------------
Read-KsSettings
if ($KodiHost) { $script:Ks.Host = $KodiHost }
if ($Port -gt 0) { $script:Ks.Port = $Port }
if ($Benutzer) { $script:Ks.User = $Benutzer }
if ($Passwort) { $script:Ks.Pass = $Passwort }

if ($Befehl) {
    $res = $null
    switch ($Befehl.ToLower()) {
        'playpause' { $res = Invoke-KsPlayerCmd 'Player.PlayPause' }
        'stop'      { $res = Invoke-KsPlayerCmd 'Player.Stop' }
        'weiter'    { $res = Invoke-KsPlayerCmd 'Player.GoTo' @{ to = 'next' } }
        'zurueck'   { $res = Invoke-KsPlayerCmd 'Player.GoTo' @{ to = 'previous' } }
        'vor'       { $res = Invoke-KsPlayerCmd 'Player.Seek' @{ value = @{ step = 'smallforward' } } }
        'rueck'     { $res = Invoke-KsPlayerCmd 'Player.Seek' @{ value = @{ step = 'smallbackward' } } }
        'lauter'    { Set-KsVolumeStep 5; $res = @{ Ok = $true } }
        'leiser'    { Set-KsVolumeStep -5; $res = @{ Ok = $true } }
        'stumm'     { $res = Invoke-Kodi 'Application.SetMute' @{ mute = 'toggle' } }
        'vollbild'  { $res = Invoke-Kodi 'GUI.SetFullscreen' @{ fullscreen = 'toggle' } }
        'oeffnen'   { if (-not $Url) { Write-Host 'Bitte -Url angeben.'; exit 2 }; $res = Invoke-Kodi 'Player.Open' @{ item = @{ file = $Url } } }
        'taste'     { if (@('Up','Down','Left','Right','Select','Back','Home','Info','ContextMenu','ShowOSD') -notcontains $Taste) { Write-Host 'Bitte -Taste angeben.'; exit 2 }; $res = Invoke-Kodi ('Input.' + $Taste) }
        'status'    {
            $np = Get-KsNowPlaying
            if ($np) {
                Write-Host ("{0}  [{1} / {2}]  {3:0}%{4}" -f $np.Title, (Format-KsTime $np.Time), (Format-KsTime $np.Total), $np.Percent, $(if ($np.Speed -eq 0) { '  (Pause)' } else { '' }))
            } elseif ($script:KsLastError) {
                Write-Host ('Fehler: ' + $script:KsLastError); exit 1
            } else {
                Write-Host 'Kodi: nichts in Wiedergabe.'
            }
            exit 0
        }
        default { Write-Host "Unbekannter Befehl '$Befehl'."; exit 2 }
    }
    if ($res -and $res.Ok) { Write-Host 'OK'; exit 0 } else { Write-Host ("Fehler: " + $res.Error); exit 1 }
}

