# ---- Bedienknöpfe (01.10.2026) -----------------------------------------------------
# Spulen, Lautstärke, Titel wechseln, Stop und Play/Pause wieder als Knöpfe - einmal fest
# unter dem Video und einmal als Leiste, die im Vollbild bei Mausbewegung eingeblendet
# wird. Alles wirkt wie die Tastenkürzel NUR auf die lokale Wiedergabe dieses PCs.
$script:KsLoopBtns = New-Object System.Collections.ArrayList
$script:KsTip = New-Object System.Windows.Forms.ToolTip
function New-KsControlBar([int]$W) {
    $p = New-Object System.Windows.Forms.Panel
    $p.Size = New-Object System.Drawing.Size($W, 40)
    $p.BackColor = [System.Drawing.Color]::FromArgb(16, 18, 22)
    $defs = @(
        @{ T = ([string][char]0x00AB + ' Titel'); W = 78; A = 'prevtrack'; Tip = 'Vorheriger Titel der Wiedergabeliste (Bild hoch)' }
        @{ T = ([string][char]0x00AB + ' 10 s'); W = 74; A = 'rew'; Tip = '10 Sekunden zurück (Pfeil links)' }
        @{ T = 'Play / Pause'; W = 112; A = 'play'; Tip = 'Abspielen bzw. Pause (Leertaste oder Klick ins Bild)'; Acc = $true }
        @{ T = 'Stop'; W = 64; A = 'stop'; Tip = 'Wiedergabe beenden (S)' }
        @{ T = ('10 s ' + [string][char]0x00BB); W = 74; A = 'ff'; Tip = '10 Sekunden vor (Pfeil rechts)' }
        @{ T = ('Titel ' + [string][char]0x00BB); W = 78; A = 'nexttrack'; Tip = 'Nächster Titel der Wiedergabeliste (Bild runter)' }
        @{ T = 'Leiser'; W = 70; A = 'voldown'; Tip = 'Leiser (Pfeil runter)' }
        @{ T = 'Lauter'; W = 70; A = 'volup'; Tip = 'Lauter (Pfeil hoch)' }
        @{ T = 'Stumm'; W = 70; A = 'mute'; Tip = 'Ton aus / an' }
        @{ T = 'Schleife: Aus'; W = 128; A = 'loop'; Tip = 'Schleife umschalten: Aus / Liste / Titel (L)' }
    )
    $x = 6
    foreach ($d in $defs) {
        $b = New-KsButton $d.T $x 4 $d.W 32 ([bool]$d.Acc)
        $b.Tag = $d.A
        # Knöpfe sollen den Tastaturfokus nicht behalten (sonst löst die Leertaste den Knopf aus)
        $b.TabStop = $false
        $b.Add_Click({ param($s, $e) Invoke-KsControl ([string]$s.Tag); Restore-KsMainFocus })
        [PelI18n]::Tip($script:KsTip, $b, $d.Tip)
        if ($d.A -eq 'loop') { [void]$script:KsLoopBtns.Add($b) }
        $p.Controls.Add($b)
        $x += $d.W + 6
    }
    return $p
}

# ---- Scrubbing-Leiste (01.10.2026) -------------------------------------------------
# Fortschrittsbalken mit aktueller Zeit und Gesamtlänge der lokalen Wiedergabe. Klicken
# oder Ziehen springt an die Stelle (gesprungen wird beim Loslassen). Position und Länge
# liest ein Hintergrund-Runspace alle 0,5 s bei mpv (IPC-Pipe) bzw. VLC (RC-Schnittstelle)
# ab - so friert das Fenster beim Abfragen nie ein (siehe $script:KsPos).
$script:KsScrubs = New-Object System.Collections.ArrayList
$script:KsScrubFont = New-Object System.Drawing.Font('Segoe UI', 8.5)
$script:KsBrTrack = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(70, 75, 85))
$script:KsBrFill = New-Object System.Drawing.SolidBrush($cAcc)
$script:KsBrKnob = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
$script:KsScrubPad = 70

function Format-KsSec([double]$Sec) {
    if ($Sec -lt 0) { return '--:--' }
    $t = [int][Math]::Floor($Sec)
    $h = [int][Math]::Floor($t / 3600)
    $m = [int][Math]::Floor(($t % 3600) / 60)
    if ($h -gt 0) { return ('{0}:{1:00}:{2:00}' -f $h, $m, ($t % 60)) }
    return ('{0}:{1:00}' -f $m, ($t % 60))
}

# Mausposition -> Anteil 0..1 auf dem Balken ($null, wenn keine Länge bekannt)
function Get-KsScrubFrac($Ctl, [int]$X) {
    $len = [double]$script:KsPos.Len
    if ($len -le 0) { return $null }
    $x0 = $script:KsScrubPad
    $x1 = $Ctl.ClientSize.Width - $script:KsScrubPad
    if ($x1 -le $x0) { return $null }
    return [Math]::Max(0.0, [Math]::Min(1.0, ($X - $x0) / [double]($x1 - $x0)))
}

function New-KsScrubBar([int]$W) {
    $p = New-Object System.Windows.Forms.Panel
    $p.Size = New-Object System.Drawing.Size($W, 26)
    $p.BackColor = [System.Drawing.Color]::FromArgb(16, 18, 22)
    $p.Cursor = [System.Windows.Forms.Cursors]::Hand
    $p.Tag = @{ Drag = $false; DragPos = 0.0 }
    # gegen Flackern beim häufigen Neuzeichnen
    try { $p.GetType().GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'NonPublic, Instance').SetValue($p, $true, $null) } catch { }
    $p.Add_Paint({
        param($s, $e)
        $g = $e.Graphics
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $w = $s.ClientSize.Width
        $h = $s.ClientSize.Height
        $x0 = $script:KsScrubPad
        $x1 = $w - $script:KsScrubPad
        if ($x1 -le $x0 + 10) { return }
        $len = [double]$script:KsPos.Len
        $pos = [double]$script:KsPos.Pos
        if ($s.Tag.Drag -and $len -gt 0) { $pos = $s.Tag.DragPos * $len }
        $has = ($len -gt 0 -and $pos -ge 0)
        $cy = [int]($h / 2)
        $g.FillRectangle($script:KsBrTrack, $x0, ($cy - 2), ($x1 - $x0), 4)
        if ($has) {
            $xf = $x0 + [int](($x1 - $x0) * [Math]::Max(0.0, [Math]::Min(1.0, $pos / $len)))
            if ($xf -gt $x0) { $g.FillRectangle($script:KsBrFill, $x0, ($cy - 2), ($xf - $x0), 4) }
            $g.FillEllipse($script:KsBrKnob, ($xf - 6), ($cy - 6), 12, 12)
        }
        $flagsL = [System.Windows.Forms.TextFormatFlags]::Right -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter
        $flagsR = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter
        $tl = $(if ($has) { Format-KsSec $pos } else { '--:--' })
        if ($script:KsPos.Paused -and $has) { $tl = [string][char]0x2016 + ' ' + $tl }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $tl, $script:KsScrubFont, (New-Object System.Drawing.Rectangle(0, 0, ($x0 - 8), $h)), $cText, $flagsL)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $(if ($len -gt 0) { Format-KsSec $len } else { '--:--' }), $script:KsScrubFont, (New-Object System.Drawing.Rectangle(($x1 + 8), 0, ($w - $x1 - 8), $h)), $cDim, $flagsR)
    })
    $p.Add_MouseDown({
        param($s, $e)
        if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
        $f = Get-KsScrubFrac $s $e.X
        if ($null -eq $f) { return }
        $s.Tag.Drag = $true
        $s.Tag.DragPos = $f
        $s.Capture = $true
        $s.Invalidate()
    })
    $p.Add_MouseMove({
        param($s, $e)
        if (-not $s.Tag.Drag) { return }
        $f = Get-KsScrubFrac $s $e.X
        if ($null -ne $f) { $s.Tag.DragPos = $f; $s.Invalidate() }
    })
    $p.Add_MouseUp({
        param($s, $e)
        if (-not $s.Tag.Drag) { return }
        $s.Tag.Drag = $false
        $s.Capture = $false
        $len = [double]$script:KsPos.Len
        if ($len -gt 0) { Send-KsLocalSeekAbs ($s.Tag.DragPos * $len) }
        $s.Invalidate()
        Restore-KsMainFocus
    })
    [void]$script:KsScrubs.Add($p)
    return $p
}

