# Helper Funktionen
function Add-KsLog([string]$t) {
    [PelI18n]::Append($txtLog, (Get-Date -Format 'HH:mm:ss') + '  ' + $t + "`r`n")
}

function Find-KsMirrorPlayer {
    $want = [string]$cmbPlayer.SelectedItem
    $vlc = $null; $mpv = $null
    foreach ($p in @(
            (Join-Path $env:ProgramFiles 'VideoLAN\VLC\vlc.exe'),
            (Join-Path ${env:ProgramFiles(x86)} 'VideoLAN\VLC\vlc.exe'))) {
        if ($p -and (Test-Path -LiteralPath $p)) { $vlc = $p; break }
    }
    if (-not $vlc) {
        try {
            $d = (Get-ItemProperty 'HKLM:\SOFTWARE\VideoLAN\VLC' -ErrorAction Stop).InstallDir
            if ($d -and (Test-Path (Join-Path $d 'vlc.exe'))) { $vlc = Join-Path $d 'vlc.exe' }
        } catch { }
    }
    $c = Get-Command mpv.exe -ErrorAction SilentlyContinue
    if ($c) { $mpv = $c.Source }
    foreach ($p in @((Join-Path $env:ProgramFiles 'mpv\mpv.exe'), (Join-Path $PSScriptRoot 'mpv.exe'), (Join-Path $PSScriptRoot 'mpv\mpv.exe'))) {
        if (-not $mpv -and $p -and (Test-Path -LiteralPath $p)) { $mpv = $p }
    }
    if ($want -eq 'VLC' -and $vlc) { return @{ Kind = 'vlc'; Path = $vlc } }
    if ($want -eq 'mpv' -and $mpv) { return @{ Kind = 'mpv'; Path = $mpv } }
    if ($want -eq 'auto') {
        if ($mpv) { return @{ Kind = 'mpv'; Path = $mpv } }
        if ($vlc) { return @{ Kind = 'vlc'; Path = $vlc } }
    }
    return $null
}

function Install-KsVlc {
    if ($st.Installer) { Add-KsLog 'VLC wird bereits installiert...'; return }
    if ($st.VlcTried) { Add-KsLog 'Bitte VLC manuell von videolan.org installieren.'; return }
    $st.VlcTried = $true
    $wg = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $wg) {
        $p = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
        if (Test-Path -LiteralPath $p) { $wg = $p }
    }
    if (-not $wg) {
        Add-KsLog 'VLC fehlt. Bitte manuell von videolan.org installieren.'
        return
    }
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $wg.Source
        $psi.Arguments = 'install --id VideoLAN.VLC --exact --silent --accept-package-agreements --accept-source-agreements --disable-interactivity'
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $st.Installer = [System.Diagnostics.Process]::Start($psi)
        $st.InstallStart = Get-Date
        $lblLiveInfo.Text = 'VLC wird via winget installiert...'
        Add-KsLog 'VLC nicht gefunden - Installation wird gestartet.'
    } catch {
        $st.Installer = $null
        Add-KsLog "VLC-Installation fehlgeschlagen: $($_.Exception.Message)"
    }
}

function Watch-KsVlcInstall {
    if (-not $st.Installer) { return }
    if (-not $st.Installer.HasExited) {
        if (((Get-Date) - $st.InstallStart).TotalMinutes -gt 10) {
            try { $st.Installer.Kill() } catch { }
            $st.Installer = $null
        }
        return
    }
    $code = $st.Installer.ExitCode
    $st.Installer.Dispose()
    $st.Installer = $null
    $cmbPlayer.SelectedItem = 'auto'
    if (Find-KsMirrorPlayer) {
        Add-KsLog 'VLC erfolgreich installiert.'
        $pend = $st.PendingMirror
        $st.PendingMirror = $null
        if ($pend) { Start-KsMirror -Source $pend.Source -StartSec $pend.StartSec -Title $pend.Title }
    } else {
        $st.PendingMirror = $null
        $lblLiveInfo.Text = 'VLC konnte nicht installiert werden.'
    }
}

# Absolut spulen (Scrubbing-Leiste) - wie alle Knöpfe nur auf diesem PC
function Send-KsLocalSeekAbs([double]$Sec) {
    if (-not $st.Mirror -or $st.Mirror.HasExited) { return }
    if ($Sec -lt 0) { $Sec = 0 }
    $script:KsPos.Pos = $Sec
    if ($st.MirrorKind -eq 'mpv') { Send-KsMpvCommand @('seek', [Math]::Round($Sec, 1), 'absolute') }
    else { [void](Invoke-KsVlcRc ('seek {0}' -f [int]$Sec)) }
}

# Hintergrund-Abfrage von Position, Länge und Pause (läuft in eigenem Runspace, $sync =
# $script:KsPos). mpv: get_property über die IPC-Pipe (Antworten an request_id erkennen,
# mpv schickt dazwischen auch Ereignisse). VLC: get_time/get_length über die RC-Schnittstelle.
$ksPosWorker = {
    function Read-Num([string]$V) {
        $d = 0.0
        if ([double]::TryParse(([string]$V).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { return $d }
        return -1.0
    }
    while ($sync.Run) {
        $kind = [string]$sync.Kind
        $pos = -1.0; $len = -1.0; $paused = $false; $ok = $false
        try {
            if ($kind -eq 'mpv') {
                $c = New-Object System.IO.Pipes.NamedPipeClientStream('.', [string]$sync.Pipe, [System.IO.Pipes.PipeDirection]::InOut)
                try {
                    $c.Connect(300)
                    $wr = New-Object System.IO.StreamWriter($c)
                    $wr.AutoFlush = $true
                    $rd = New-Object System.IO.StreamReader($c)
                    $wr.Write('{"command":["get_property","time-pos"],"request_id":901}' + "`n" + '{"command":["get_property","duration"],"request_id":902}' + "`n" + '{"command":["get_property","pause"],"request_id":903}' + "`n")
                    $got = @{}
                    $until = (Get-Date).AddMilliseconds(900)
                    while ($got.Count -lt 3 -and (Get-Date) -lt $until) {
                        $tk = $rd.ReadLineAsync()
                        if (-not $tk.Wait(450)) { break }
                        $line = $tk.Result
                        if ($null -eq $line) { break }
                        if ($line -match '"request_id"\s*:\s*(90[123])') {
                            $id = $matches[1]
                            $val = ''
                            if ($line -match '"data"\s*:\s*([^,}]+)') { $val = $matches[1] }
                            $got[$id] = $val
                        }
                    }
                    if ($got.ContainsKey('901')) { $pos = Read-Num $got['901'] }
                    if ($got.ContainsKey('902')) { $len = Read-Num $got['902'] }
                    if ($got.ContainsKey('903')) { $paused = ([string]$got['903']).Trim() -eq 'true' }
                    $ok = $true
                } finally { $c.Dispose() }
            } elseif ($kind -eq 'vlc') {
                $tc = New-Object System.Net.Sockets.TcpClient
                try {
                    $iar = $tc.BeginConnect('127.0.0.1', [int]$sync.VlcPort, $null, $null)
                    if ($iar.AsyncWaitHandle.WaitOne(300)) {
                        $tc.EndConnect($iar)
                        $ns = $tc.GetStream()
                        $b = [System.Text.Encoding]::ASCII.GetBytes("get_time`r`nget_length`r`n")
                        $ns.Write($b, 0, $b.Length)
                        $sb = New-Object System.Text.StringBuilder
                        $buf = New-Object byte[] 512
                        $until = (Get-Date).AddMilliseconds(900)
                        $nums = @()
                        while ((Get-Date) -lt $until) {
                            if ($ns.DataAvailable) {
                                $n = $ns.Read($buf, 0, 512)
                                if ($n -le 0) { break }
                                [void]$sb.Append([System.Text.Encoding]::ASCII.GetString($buf, 0, $n))
                                $nums = @([regex]::Matches($sb.ToString(), '(?m)^\s*(?:>\s*)?(\d+)\s*\r?$') | ForEach-Object { $_.Groups[1].Value })
                                if ($nums.Count -ge 2) { break }
                            } else { Start-Sleep -Milliseconds 20 }
                        }
                        if ($nums.Count -ge 1) { $pos = Read-Num $nums[0] }
                        if ($nums.Count -ge 2) { $len = Read-Num $nums[1] }
                        $ok = $true
                    }
                } finally { $tc.Close() }
            }
        } catch { }
        # nur übernehmen, wenn in der Zwischenzeit nicht gestoppt/gewechselt wurde
        if ($ok -and [string]$sync.Kind -eq $kind) {
            if ($pos -ge 0) { $sync.Pos = $pos }
            if ($len -gt 0) { $sync.Len = $len }
            $sync.Paused = $paused
        }
        Start-Sleep -Milliseconds 500
    }
}

function Stop-KsMirror {
    if ($st.Mirror) {
        try { if (-not $st.Mirror.HasExited) { $st.Mirror.Kill() } } catch { }
        try { $st.Mirror.Dispose() } catch { }
        $st.Mirror = $null
    }
    $st.MirrorKind = ''
    $st.MirrorFile = ''
    $script:KsPos.Kind = ''
    $script:KsPos.Pos = -1.0
    $script:KsPos.Len = -1.0
    $script:KsPos.Paused = $false
    $picCover.Visible = $true
    $pLive.Refresh()
}

$script:KsPlayerLog = Join-Path ([System.IO.Path]::GetTempPath()) 'kodi-steuerung-player.log'
# Feste lokale Steuerkanäle für die Fernbedienung (siehe Send-KsLocalAction weiter
# unten): mpv bekommt eine benannte Pipe (JSON-IPC), VLC ein RC-Interface auf einem
# lokalen TCP-Port. Beides wirkt NUR auf den lokalen Mirror-Prozess dieses PCs, nicht
# auf den entfernten Kodi-Player - andere PCs im Netzwerk sind davon nicht betroffen.
$script:KsMpvPipeName = 'PelKodiMirror'
# Position/Länge der lokalen Wiedergabe für die Scrubbing-Leiste. Wird vom Hintergrund-
# Runspace ($ksPosWorker) geschrieben und vom Fenster gelesen. Kind: '' | mpv | vlc
$script:KsPos = [hashtable]::Synchronized(@{ Run = $true; Kind = ''; Pos = -1.0; Len = -1.0; Paused = $false; Pipe = 'PelKodiMirror'; VlcPort = 42011 })
$script:KsVlcRcPort = 42011
$script:KsVlcVol = 256
$script:KsVlcMuteVol = 256
$script:KsLast = $null
# Lokale Wiedergabeliste (unabhaengig von Kodi und von anderen PCs). Loop: off | list | one
$script:KsPl = @{ Items = (New-Object System.Collections.ArrayList); Index = -1; Loop = 'off'; Active = $false; Fail = 0; Form = $null; Lb = $null; BtnLoop = $null }

function Start-KsMirror {
    param([string]$Source = '', [int]$StartSec = -1, [string]$Title = '', [switch]$KeepList)
    if (-not $KeepList) { $script:KsPl.Active = $false }
    $np = $st.Np
    if (-not $Source) {
        if (-not $np) { Add-KsLog 'Nichts zum Abspielen ausgewählt.'; return }
        $Source = Get-KsMirrorUrl $np.File
        if (-not $Source) { Add-KsLog "Diese Quelle lässt sich nicht lokal abspielen."; return }
        if ($StartSec -lt 0) { $StartSec = Get-KsSeconds $np.Time }
        if (-not $Title) { $Title = $np.Title }
    }
    if ($StartSec -lt 0) { $StartSec = 0 }
    $script:KsLast = @{ Source = $Source; Title = $Title }
    $script:KsVlcVol = 256
    $pl = Find-KsMirrorPlayer
    if (-not $pl) {
        $st.PendingMirror = @{ Source = $Source; StartSec = $StartSec; Title = $Title }
        Install-KsVlc
        return
    }
    Stop-KsMirror
    $hwnd = $pLive.Handle.ToInt64()
    if ($pl.Kind -eq 'mpv') {
        $args_ = @("--wid=$hwnd", '--volume=100', '--no-osc', '--no-input-default-bindings', '--osd-level=0', '--keep-open=no', '--force-window=yes', "--start=$StartSec", "--input-ipc-server=\\.\pipe\$script:KsMpvPipeName", "--log-file=`"$script:KsPlayerLog`"", "`"$Source`"")
    } else {
        $args_ = @('-I', 'dummy', '--dummy-quiet', '--play-and-exit', "--drawable-hwnd=$hwnd", '--audio', '--no-video-title-show', '--network-caching=1500', "--start-time=$StartSec", '--no-snapshot-preview', '--extraintf=rc', "--rc-host=127.0.0.1:$script:KsVlcRcPort", '--rc-quiet', '--file-logging', "--logfile=`"$script:KsPlayerLog`"", '--log-verbose=1', "`"$Source`"")
    }
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $pl.Path
        $psi.Arguments = ($args_ -join ' ')
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $st.Mirror = [System.Diagnostics.Process]::Start($psi)
        $st.MirrorKind = $pl.Kind
        $script:KsPos.Pos = [double]$StartSec
        $script:KsPos.Len = -1.0
        $script:KsPos.Kind = $pl.Kind
        $st.MirrorStart = Get-Date
        $st.MirrorFile = $(if ($np) { $np.File } else { $Source })
        $st.MirrorTitle = $(if ($Title) { $Title } else { [System.IO.Path]::GetFileName(($Source -split '\?')[0]) })
        $picCover.Visible = $false
        try { $form.ActiveControl = $null } catch { }
        $lblLiveInfo.Text = "Wiedergabe über $($pl.Kind.ToUpper()) - Ton am PC."
        $lblTitle.Text = $st.MirrorTitle
        Add-KsLog "Wiedergabe gestartet ($($pl.Kind))."
    } catch { Add-KsLog "Fehler beim Starten der Wiedergabe: $($_.Exception.Message)" }
}

# ------------------------------------------------------------------------------
# Lokale Fernbedienung: steuert AUSSCHLIESSLICH die Wiedergabe auf diesem PC (den
# gerade laufenden mpv-/VLC-Mirror-Prozess), niemals den entfernten Kodi-Player. So
# können mehrere PCs, die sich alle mit demselben Kodi verbinden, unabhängig
# voneinander verschiedene Titel schauen, ohne sich gegenseitig zu steuern.
# ------------------------------------------------------------------------------
function Send-KsMpvCommand([object[]]$Cmd) {
    try {
        $json = (@{ command = $Cmd } | ConvertTo-Json -Compress) + "`n"
        $pipe = New-Object System.IO.Pipes.NamedPipeClientStream('.', $script:KsMpvPipeName, [System.IO.Pipes.PipeDirection]::Out)
        $pipe.Connect(300)
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
        $pipe.Write($bytes, 0, $bytes.Length)
        $pipe.Flush()
        $pipe.Dispose()
    } catch { Add-KsLog "Steuerung (mpv) fehlgeschlagen: $($_.Exception.Message)" }
}

# VLC wird ueber sein Remote-Control-Interface (RC) gesteuert. Nur echte RC-Befehle
# (pause, volume, seek, get_time) - die frueher genutzten "key ..."-Hotkeynamen gab es nicht.
function Invoke-KsVlcRc([string]$Line, [bool]$Reply = $false) {
    $result = ''
    try {
        $tc = New-Object System.Net.Sockets.TcpClient
        $iar = $tc.BeginConnect('127.0.0.1', $script:KsVlcRcPort, $null, $null)
        if (-not $iar.AsyncWaitHandle.WaitOne(400)) { $tc.Close(); throw 'Zeitüberschreitung' }
        $tc.EndConnect($iar)
        $s = $tc.GetStream()
        $bytes = [System.Text.Encoding]::ASCII.GetBytes($Line + "`r`n")
        $s.Write($bytes, 0, $bytes.Length)
        $s.Flush()
        if ($Reply) {
            $sb = New-Object System.Text.StringBuilder
            $buf = New-Object byte[] 512
            $until = (Get-Date).AddMilliseconds(800)
            while ((Get-Date) -lt $until) {
                if ($s.DataAvailable) {
                    $n = $s.Read($buf, 0, 512)
                    if ($n -le 0) { break }
                    [void]$sb.Append([System.Text.Encoding]::ASCII.GetString($buf, 0, $n))
                    if ($sb.ToString() -match '(?m)^\s*\d+\s*$') { break }
                } else { Start-Sleep -Milliseconds 20 }
            }
            $result = $sb.ToString()
        } else {
            Start-Sleep -Milliseconds 60
        }
        $tc.Close()
    } catch { Add-KsLog "Steuerung (VLC) fehlgeschlagen: $($_.Exception.Message)" }
    return $result
}

function Send-KsVlcSeekRel([int]$Delta) {
    $r = Invoke-KsVlcRc 'get_time' $true
    if ($r -match '(?m)^\s*(\d+)\s*$') {
        $target = [int]$Matches[1] + $Delta
        if ($target -lt 0) { $target = 0 }
        [void](Invoke-KsVlcRc "seek $target")
    }
}

function Send-KsLocalAction([string]$What) {
    if (-not $st.Mirror -or $st.Mirror.HasExited) { Add-KsLog 'Es läuft gerade keine lokale Wiedergabe auf diesem PC.'; return }
    if ($st.MirrorKind -eq 'mpv') {
        switch ($What) {
            'playpause' { Send-KsMpvCommand @('cycle', 'pause') }
            'rew'       { Send-KsMpvCommand @('seek', -10, 'relative') }
            'ff'        { Send-KsMpvCommand @('seek', 10, 'relative') }
            'prev'      { Send-KsMpvCommand @('seek', -60, 'relative') }
            'next'      { Send-KsMpvCommand @('seek', 60, 'relative') }
            'voldown'   { Send-KsMpvCommand @('add', 'volume', -5) }
            'volup'     { Send-KsMpvCommand @('add', 'volume', 5) }
            'mute'      { Send-KsMpvCommand @('cycle', 'mute') }
        }
    } else {
        switch ($What) {
            'playpause' { [void](Invoke-KsVlcRc 'pause') }
            'rew'       { Send-KsVlcSeekRel -10 }
            'ff'        { Send-KsVlcSeekRel 10 }
            'prev'      { Send-KsVlcSeekRel -60 }
            'next'      { Send-KsVlcSeekRel 60 }
            'voldown'   { $script:KsVlcVol = [Math]::Max(0, $script:KsVlcVol - 13); [void](Invoke-KsVlcRc "volume $($script:KsVlcVol)") }
            'volup'     { $script:KsVlcVol = [Math]::Min(512, $script:KsVlcVol + 13); [void](Invoke-KsVlcRc "volume $($script:KsVlcVol)") }
            'mute'      {
                # BUGFIX: "Stumm" stellte bei VLC nur auf 0 - jetzt Umschalter mit Rückkehr zur alten Lautstärke
                if ($script:KsVlcVol -gt 0) { $script:KsVlcMuteVol = $script:KsVlcVol; $script:KsVlcVol = 0 }
                else { $script:KsVlcVol = $(if ($script:KsVlcMuteVol -gt 0) { $script:KsVlcMuteVol } else { 256 }) }
                [void](Invoke-KsVlcRc "volume $($script:KsVlcVol)")
            }
        }
    }
}

# ------------------------------------------------------------------------------
# Lokale Wiedergabeliste, Schleife, Stopp und Tastenkuerzel-Verteiler
# ------------------------------------------------------------------------------
function Get-KsLoopText {
    switch ($script:KsPl.Loop) { 'list' { return 'Schleife: Liste' } 'one' { return 'Schleife: Titel' } default { return 'Schleife: Aus' } }
}

function Refresh-KsPlaylistUi {
    try { Update-KsToggleLabel } catch { }
    foreach ($lb0 in $script:KsLoopBtns) { try { $lb0.Text = Get-KsLoopText } catch { } }
    $f = $script:KsPl.Form
    if (-not $f -or $f.IsDisposed) { return }
    $lb = $script:KsPl.Lb
    $lb.BeginUpdate()
    $lb.Items.Clear()
    for ($i = 0; $i -lt $script:KsPl.Items.Count; $i++) {
        $mark = if ($script:KsPl.Active -and $i -eq $script:KsPl.Index) { [string][char]0x25B6 + ' ' } else { '     ' }
        [void]$lb.Items.Add(('{0}{1:00}. {2}' -f $mark, ($i + 1), $script:KsPl.Items[$i].Title))
    }
    $lb.EndUpdate()
    $script:KsPl.BtnLoop.Text = Get-KsLoopText
}

function Stop-KsUser {
    $script:KsPl.Active = $false
    $script:KsPl.Fail = 0
    Stop-KsMirror
    $lblLiveInfo.Text = 'Wiedergabe aus.'
    $lblTitle.Text = 'Nichts in lokaler Wiedergabe'
    Refresh-KsPlaylistUi
}

function Step-KsLoop {
    $script:KsPl.Loop = switch ($script:KsPl.Loop) { 'off' { 'list' } 'list' { 'one' } default { 'off' } }
    Add-KsLog (Get-KsLoopText)
    Refresh-KsPlaylistUi
}

function Start-KsPlaylistItem([int]$Index) {
    if ($Index -lt 0 -or $Index -ge $script:KsPl.Items.Count) { return }
    $it = $script:KsPl.Items[$Index]
    $script:KsPl.Index = $Index
    Start-KsMirror -Source $it.Src -Title $it.Title -KeepList
    $script:KsPl.Active = $true
    Refresh-KsPlaylistUi
}

function Step-KsPlaylist([int]$Dir) {
    $n = $script:KsPl.Items.Count
    if ($n -eq 0) { Add-KsLog 'Die Wiedergabeliste ist leer.'; return }
    if (-not $script:KsPl.Active -or $script:KsPl.Index -lt 0) {
        Start-KsPlaylistItem $(if ($Dir -gt 0) { 0 } else { $n - 1 })
        return
    }
    $i = $script:KsPl.Index + $Dir
    if ($i -ge $n) { if ($script:KsPl.Loop -eq 'list') { $i = 0 } else { Stop-KsUser; return } }
    if ($i -lt 0) { $i = $(if ($script:KsPl.Loop -eq 'list') { $n - 1 } else { 0 }) }
    Start-KsPlaylistItem $i
}

function Add-KsPlaylist([object[]]$Entries) {
    $first = $script:KsPl.Items.Count
    foreach ($e in $Entries) {
        if ($e -and $e.Src) { [void]$script:KsPl.Items.Add([pscustomobject]@{ Title = [string]$e.Title; Src = [string]$e.Src }) }
    }
    $added = $script:KsPl.Items.Count - $first
    $running = $false
    try { $running = [bool]($st.Mirror -and -not $st.Mirror.HasExited) } catch { }
    Refresh-KsPlaylistUi
    Add-KsLog "$added Titel in der Wiedergabeliste ($($script:KsPl.Items.Count) insgesamt)."
    if ($added -gt 0 -and -not $running) { Start-KsPlaylistItem $first }
}

# Wiedergabeliste durch $Entries ersetzen und ab $StartAt abspielen ("Ganzen Ordner abspielen",
# "Ab hier abspielen"). Rückgabe: Anzahl Titel.
function Start-KsPlaylistNew([object[]]$Entries, [int]$StartAt = 0) {
    $script:KsPl.Items.Clear()
    $script:KsPl.Index = -1
    $script:KsPl.Active = $false
    foreach ($e in $Entries) {
        if ($e -and $e.Src) { [void]$script:KsPl.Items.Add([pscustomobject]@{ Title = [string]$e.Title; Src = [string]$e.Src }) }
    }
    $n = $script:KsPl.Items.Count
    Refresh-KsPlaylistUi
    if ($n -eq 0) { return 0 }
    if ($StartAt -lt 0 -or $StartAt -ge $n) { $StartAt = 0 }
    Add-KsLog "$n Titel in der Wiedergabeliste ($n insgesamt)."
    Start-KsPlaylistItem $StartAt
    return $n
}

# Wird alle 40 ms aufgerufen: erkennt das Ende eines Titels und startet den naechsten
# bzw. wiederholt ihn (Schleife). Bricht ab, wenn ein Titel sofort wieder endet.
function Invoke-KsPlaylistTick {
    if (-not $st.Mirror) { return }
    $exited = $false
    try { $exited = $st.Mirror.HasExited } catch { $exited = $true }
    if (-not $exited) { return }
    $ran = ((Get-Date) - $st.MirrorStart).TotalSeconds
    $last = $script:KsLast
    Stop-KsMirror
    $lblLiveInfo.Text = 'Wiedergabe beendet.'
    if ($ran -lt 3) { $script:KsPl.Fail++ } else { $script:KsPl.Fail = 0 }
    if ($script:KsPl.Fail -ge 3) {
        Add-KsLog 'Titel endet sofort wieder - Schleife/Liste gestoppt.'
        $script:KsPl.Active = $false
        $script:KsPl.Fail = 0
        Refresh-KsPlaylistUi
        return
    }
    if ($script:KsPl.Loop -eq 'one' -and $last) {
        Start-KsMirror -Source $last.Source -Title $last.Title -KeepList
        return
    }
    if ($script:KsPl.Active) {
        $n = $script:KsPl.Index + 1
        if ($n -ge $script:KsPl.Items.Count) {
            if ($script:KsPl.Loop -eq 'list' -and $script:KsPl.Items.Count -gt 0) { $n = 0 }
            else {
                $script:KsPl.Active = $false
                $lblTitle.Text = 'Wiedergabeliste beendet'
                Refresh-KsPlaylistUi
                return
            }
        }
        Start-KsPlaylistItem $n
    }
}

function Invoke-KsShortcut([int]$Vk) {
    switch ($Vk) {
        (-1) {
            # Klick ins Bild: Suchfeld/Trefferliste loslassen, damit die Leisten wieder ausblenden
            try { if ($lbFind.Visible) { $lbFind.Visible = $false; Set-KsOverlayBounds }; $form.ActiveControl = $null } catch { }
            Send-KsLocalAction 'playpause'
        }
        32   { Send-KsLocalAction 'playpause' }
        37   { Send-KsLocalAction 'rew' }
        39   { Send-KsLocalAction 'ff' }
        38   { Send-KsLocalAction 'volup' }
        40   { Send-KsLocalAction 'voldown' }
        83   { Stop-KsUser }
        76   { Step-KsLoop }
        33   { Step-KsPlaylist -1 }
        34   { Step-KsPlaylist 1 }
    }
}

# Bedienknöpfe (unter dem Video und in der Vollbild-Leiste)
function Invoke-KsControl([string]$What) {
    switch ($What) {
        'play' {
            $running = $false
            try { $running = [bool]($st.Mirror -and -not $st.Mirror.HasExited) } catch { }
            if ($running) { Send-KsLocalAction 'playpause'; return }
            # nichts läuft: Wiedergabeliste fortsetzen, sonst den letzten Titel erneut starten
            if ($script:KsPl.Items.Count -gt 0) { Start-KsPlaylistItem $(if ($script:KsPl.Index -ge 0 -and $script:KsPl.Index -lt $script:KsPl.Items.Count) { $script:KsPl.Index } else { 0 }); return }
            if ($script:KsLast) { Start-KsMirror -Source $script:KsLast.Source -Title $script:KsLast.Title; return }
            Add-KsLog 'Nichts zum Abspielen ausgewählt.'
        }
        'stop'      { Stop-KsUser }
        'loop'      { Step-KsLoop }
        'prevtrack' { Step-KsPlaylist -1 }
        'nexttrack' { Step-KsPlaylist 1 }
        default     { Send-KsLocalAction $What }
    }
}

function Show-KsPlaylist {
    if ($script:KsPl.Form -and -not $script:KsPl.Form.IsDisposed) {
        $script:KsPl.Form.WindowState = 'Normal'
        $script:KsPl.Form.Activate()
        return
    }
    $f = (New-PelForm)
    $f.Text = 'Wiedergabeliste (lokal auf diesem PC)'
    $f.Size = New-Object System.Drawing.Size(500, 620)
    $f.MinimumSize = New-Object System.Drawing.Size(500, 620)
    $f.StartPosition = 'CenterScreen'
    $f.BackColor = $cBack
    $f.ForeColor = $cText
    $f.Font = $fMain
    $script:KsPl.Form = $f

    $lb = New-Object System.Windows.Forms.ListBox
    $lb.Location = New-Object System.Drawing.Point(12, 12)
    $lb.Size = New-Object System.Drawing.Size(460, 380)
    $lb.BackColor = $cPanel
    $lb.ForeColor = $cText
    $lb.BorderStyle = 'None'
    $lb.Anchor = 'Top, Left, Right, Bottom'
    $script:KsPl.Lb = $lb

    $bPrev  = New-KsButton 'Zurück' 12 400 108 34
    $bPause = New-KsButton 'Pause / Weiter' 126 400 108 34 $true
    $bStop  = New-KsButton 'Stopp' 240 400 108 34
    $bNext  = New-KsButton 'Weiter' 354 400 118 34
    $bVolD  = New-KsButton 'Leiser' 12 440 108 34
    $bVolU  = New-KsButton 'Lauter' 126 440 108 34
    $bLoop  = New-KsButton (Get-KsLoopText) 240 440 232 34
    $bDel   = New-KsButton 'Entfernen' 12 480 228 34
    $bClear = New-KsButton 'Liste leeren' 246 480 226 34
    $script:KsPl.BtnLoop = $bLoop
    $hint = New-KsLabel 'Doppelklick = Titel abspielen. In "Medien auswählen" per Rechtsklick ganze Ordner abspielen oder hier anhängen.' 12 524 460 44
    $hint.ForeColor = $cDim
    foreach ($c in @($bPrev, $bPause, $bStop, $bNext, $bVolD, $bVolU, $bLoop, $bDel, $bClear, $hint)) { $c.Anchor = 'Left, Bottom' }
    $f.Controls.AddRange(@($lb, $bPrev, $bPause, $bStop, $bNext, $bVolD, $bVolU, $bLoop, $bDel, $bClear, $hint))

    $bPrev.Add_Click({ Step-KsPlaylist -1 })
    $bNext.Add_Click({ Step-KsPlaylist 1 })
    $bPause.Add_Click({ Send-KsLocalAction 'playpause' })
    $bStop.Add_Click({ Stop-KsUser })
    $bVolD.Add_Click({ Send-KsLocalAction 'voldown' })
    $bVolU.Add_Click({ Send-KsLocalAction 'volup' })
    $bLoop.Add_Click({ Step-KsLoop })
    $bDel.Add_Click({
        $i = $script:KsPl.Lb.SelectedIndex
        if ($i -lt 0) { return }
        $script:KsPl.Items.RemoveAt($i)
        if ($i -le $script:KsPl.Index) { $script:KsPl.Index-- }
        Refresh-KsPlaylistUi
    })
    $bClear.Add_Click({
        $script:KsPl.Items.Clear()
        $script:KsPl.Index = -1
        Refresh-KsPlaylistUi
    })
    $lb.Add_DoubleClick({
        $i = $script:KsPl.Lb.SelectedIndex
        if ($i -ge 0) { Start-KsPlaylistItem $i }
    })
    $f.Add_FormClosed({ $script:KsPl.Form = $null })
    Refresh-KsPlaylistUi
    $f.Show()
}

function Update-KsStatus {
    if (-not $st.Connected) { return }
    $np = Get-KsNowPlaying
    $st.Np = $np
    if (-not $np -and $script:KsLastError) {
        $st.Connected = $false
        $lblConn.Text = 'Verbindung verloren'
        $lblConn.ForeColor = [System.Drawing.Color]::Orange
        Add-KsLog $script:KsLastError
        return
    }
    if ($chkLiveAuto.Checked) {
        if ($np -and $np.File -ne $st.LastFile) {
            $st.LastFile = $np.File
            if (Get-KsMirrorUrl $np.File) { Start-KsMirror -Title $np.Title }
        } elseif (-not $np) { $st.LastFile = '' }
    }
    if ($st.Mirror -and $st.Mirror.HasExited) {
        Stop-KsMirror
        $lblLiveInfo.Text = 'Wiedergabe beendet.'
    }
}

function Connect-Ks {
    $script:Ks.Host = $txtHost.Text.Trim()
    $p = 0
    if ([int]::TryParse($txtPort.Text.Trim(), [ref]$p) -and $p -gt 0) { $script:Ks.Port = $p }
    $script:Ks.User = $txtUser.Text
    $script:Ks.Pass = $txtPass.Text
    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
    try {
        $r = Invoke-Kodi 'JSONRPC.Ping' $null 4000
        if ($r.Ok) {
            $ver = Invoke-Kodi 'Application.GetProperties' @{ properties = @('name', 'version') }
            $vt = ''
            if ($ver.Ok) { $vt = ' ' + [string]$ver.Result.version.major + '.' + [string]$ver.Result.version.minor }
            $st.Connected = $true
            [void](Invoke-Kodi 'Application.SetMute' @{ mute = $true })
            $lblConn.Text = "Verbunden mit Kodi$vt"
            $lblConn.ForeColor = [System.Drawing.Color]::LightGreen
            Save-KsSettings
            Add-KsLog "Verbunden mit $(Get-KsBaseUrl)."
            Update-KsStatus
        } else {
            $st.Connected = $false
            $lblConn.Text = 'Keine Verbindung'
            $lblConn.ForeColor = [System.Drawing.Color]::Orange
            Add-KsLog $r.Error
        }
    } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
}

function Require-Ks {
    if (-not $st.Connected) { Add-KsLog 'Bitte zuerst verbinden.'; return $false }
    return $true
}

# ------------------------------------------------------------------------------
# Medien-Browser (vollständig korrigiertes Scoping)
# ------------------------------------------------------------------------------
function Get-KsImage([string]$Thumb) {
    if (-not $Thumb) { return $null }
    try {
        $u = (Get-KsBaseUrl) + '/image/' + [Uri]::EscapeDataString($Thumb)
        $wc = New-Object System.Net.WebClient
        if ($script:Ks.User -or $script:Ks.Pass) {
            $wc.Credentials = New-Object System.Net.NetworkCredential($script:Ks.User, $script:Ks.Pass)
        }
        $bytes = $wc.DownloadData($u)
        $wc.Dispose()
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        return [System.Drawing.Image]::FromStream($ms)
    } catch { return $null }
}

function Format-KsRuntime($sec) {
    $s = 0; try { $s = [int]$sec } catch { }
    if ($s -le 0) { return '' }
    $h = [int][Math]::Floor($s / 3600)
    $m = [int][Math]::Floor(($s % 3600) / 60)
    if ($h -gt 0) { return ('{0} Std. {1:00} Min.' -f $h, $m) }
    return ('{0} Min.' -f $m)
}

function Get-KsMediaItems($View) {
    $out = New-Object System.Collections.Generic.List[object]
    $err = ''
    $add = { param($h) $out.Add([pscustomobject]$h) }
    switch ($View.Type) {
        'movies' {
            $r = Invoke-Kodi 'VideoLibrary.GetMovies' @{ properties = @('title', 'year', 'thumbnail', 'runtime', 'rating', 'plot', 'playcount', 'file'); sort = @{ method = 'sorttitle'; ignorearticle = $true } } 15000
            if ($r.Ok) {
                foreach ($m in @($r.Result.movies)) {
                    if ($m) { & $add @{ Kind = 'movie'; Id = [int]$m.movieid; Title = [string]$m.title; Sub = ('{0}   {1}   {2}' -f $m.year, (Format-KsRuntime $m.runtime), $(if ([int]$m.playcount -gt 0) { 'gesehen' } else { '' })).Trim(); Thumb = [string]$m.thumbnail; File = [string]$m.file; Plot = [string]$m.plot; Open = $null } }
                }
            } else { $err = $r.Error }
        }
        'recent' {
            $r = Invoke-Kodi 'VideoLibrary.GetRecentlyAddedMovies' @{ properties = @('title', 'year', 'thumbnail', 'runtime', 'plot', 'file'); limits = @{ start = 0; end = 25 } } 15000
            if ($r.Ok) {
                foreach ($m in @($r.Result.movies)) {
                    if ($m) { & $add @{ Kind = 'movie'; Id = [int]$m.movieid; Title = [string]$m.title; Sub = ('Film   {0}   {1}' -f $m.year, (Format-KsRuntime $m.runtime)).Trim(); Thumb = [string]$m.thumbnail; File = [string]$m.file; Plot = [string]$m.plot; Open = $null } }
                }
            } else { $err = $r.Error }
        }
        'tvshows' {
            $r = Invoke-Kodi 'VideoLibrary.GetTVShows' @{ properties = @('title', 'year', 'thumbnail', 'episode', 'watchedepisodes', 'plot'); sort = @{ method = 'sorttitle'; ignorearticle = $true } } 15000
            if ($r.Ok) {
                foreach ($s in @($r.Result.tvshows)) {
                    if ($s) { & $add @{ Kind = 'folder'; Id = [int]$s.tvshowid; Title = [string]$s.title; Sub = ('{0}   {1} Folgen' -f $s.year, $s.episode); Thumb = [string]$s.thumbnail; File = ''; Plot = [string]$s.plot; Open = @{ Type = 'seasons'; TvShowId = [int]$s.tvshowid; Title = [string]$s.title } } }
                }
            } else { $err = $r.Error }
        }
        'seasons' {
            $r = Invoke-Kodi 'VideoLibrary.GetSeasons' @{ tvshowid = [int]$View.TvShowId; properties = @('season', 'thumbnail', 'episode', 'watchedepisodes') } 15000
            if ($r.Ok) {
                foreach ($s in @($r.Result.seasons)) {
                    if ($s) {
                        $nm = if ([int]$s.season -eq 0) { 'Specials' } else { 'Staffel ' + $s.season }
                        & $add @{ Kind = 'folder'; Id = [int]$s.season; Title = $nm; Sub = ('{0} Folgen' -f $s.episode); Thumb = [string]$s.thumbnail; File = ''; Plot = ''; Open = @{ Type = 'episodes'; TvShowId = [int]$View.TvShowId; Season = [int]$s.season; Title = "$($View.Title) - $nm" } }
                    }
                }
            } else { $err = $r.Error }
        }
        'episodes' {
            $r = Invoke-Kodi 'VideoLibrary.GetEpisodes' @{ tvshowid = [int]$View.TvShowId; season = [int]$View.Season; properties = @('title', 'episode', 'season', 'thumbnail', 'runtime', 'plot', 'playcount', 'file'); sort = @{ method = 'episode' } } 15000
            if ($r.Ok) {
                foreach ($e in @($r.Result.episodes)) {
                    if ($e) { & $add @{ Kind = 'episode'; Id = [int]$e.episodeid; Title = ('{0:00}. {1}' -f [int]$e.episode, $e.title); Sub = (Format-KsRuntime $e.runtime); Thumb = [string]$e.thumbnail; File = [string]$e.file; Plot = [string]$e.plot; Open = $null } }
                }
            } else { $err = $r.Error }
        }
        'artists' {
            $r = Invoke-Kodi 'AudioLibrary.GetArtists' @{ properties = @('thumbnail'); sort = @{ method = 'artist'; ignorearticle = $true } } 15000
            if ($r.Ok) {
                foreach ($a in @($r.Result.artists)) {
                    if ($a) { & $add @{ Kind = 'folder'; Id = [int]$a.artistid; Title = [string]$a.artist; Sub = 'Interpret'; Thumb = [string]$a.thumbnail; File = ''; Plot = ''; Open = @{ Type = 'albums'; ArtistId = [int]$a.artistid; Title = [string]$a.artist } } }
                }
            } else { $err = $r.Error }
        }
        'albums' {
            $r = Invoke-Kodi 'AudioLibrary.GetSongs' @{ filter = @{ artistid = [int]$View.ArtistId }; properties = @('title', 'file', 'track', 'album', 'thumbnail') } 20000
            if ($r.Ok) {
                foreach ($s in @($r.Result.songs | Sort-Object { [string]$_.album }, { [int]$_.track })) {
                    if ($s) { & $add @{ Kind = 'song'; Id = [int]$s.songid; Title = ('{0:00}. {1}' -f [int]$s.track, $s.title); Sub = [string]$s.album; Thumb = [string]$s.thumbnail; File = [string]$s.file; Plot = ''; Open = $null } }
                }
            } else { $err = $r.Error }
        }
        'sources' {
            foreach ($media in @('video', 'music')) {
                $r = Invoke-Kodi 'Files.GetSources' @{ media = $media } 10000
                if ($r.Ok) {
                    foreach ($s in @($r.Result.sources)) {
                        if ($s) { & $add @{ Kind = 'folder'; Id = 0; Title = [string]$s.label; Sub = "$media-Quelle"; Thumb = ''; File = [string]$s.file; Plot = [string]$s.file; Open = @{ Type = 'dir'; Path = [string]$s.file; Media = $media; Title = [string]$s.label } } }
                    }
                } elseif (-not $err) { $err = $r.Error }
            }
        }
        'dir' {
            $r = Invoke-Kodi 'Files.GetDirectory' @{ directory = [string]$View.Path; media = [string]$View.Media; properties = @('title', 'thumbnail', 'size', 'runtime'); sort = @{ method = 'label'; ignorearticle = $true } } 20000
            if ($r.Ok) {
                foreach ($f in @($r.Result.files)) {
                    if ($f) {
                        if ([string]$f.filetype -eq 'directory') {
                            & $add @{ Kind = 'folder'; Id = 0; Title = [string]$f.label; Sub = 'Ordner'; Thumb = [string]$f.thumbnail; File = [string]$f.file; Plot = [string]$f.file; Open = @{ Type = 'dir'; Path = [string]$f.file; Media = [string]$View.Media; Title = "$($View.Title) / $($f.label)" } }
                        } else {
                            & $add @{ Kind = 'file'; Id = 0; Title = [string]$f.label; Sub = ''; Thumb = [string]$f.thumbnail; File = [string]$f.file; Plot = [string]$f.file; Open = $null }
                        }
                    }
                }
            } else { $err = $r.Error }
        }
    }
    return @{ Items = $out.ToArray(); Error = $err }
}

# Sammelt alle abspielbaren Dateien eines Ordners (Unterordner bis Tiefe 4, max. 500 Titel).
function Add-KsDirPlayables([string]$Path, [string]$Media, [int]$Depth, $List, [int]$Limit) {
    if ($List.Count -ge $Limit -or $Depth -gt 4) { return }
    $r = Invoke-Kodi 'Files.GetDirectory' @{ directory = $Path; media = $Media; properties = @('title'); sort = @{ method = 'label'; ignorearticle = $true } } 20000
    if (-not $r.Ok) { return }
    $files = @($r.Result.files)
    foreach ($f in $files) {
        if (-not $f) { continue }
        if ($List.Count -ge $Limit) { return }
        if ([string]$f.filetype -eq 'directory') { continue }
        $src = Get-KsMirrorUrl ([string]$f.file)
        if ($src) { $List.Add([pscustomobject]@{ Title = [string]$f.label; Src = $src }) }
    }
    foreach ($f in $files) {
        if (-not $f) { continue }
        if ($List.Count -ge $Limit) { return }
        if ([string]$f.filetype -eq 'directory') { Add-KsDirPlayables ([string]$f.file) $Media ($Depth + 1) $List $Limit }
    }
}

function Get-KsFolderPlayables($Open) {
    $list = New-Object System.Collections.Generic.List[object]
    $limit = 500
    switch ($Open.Type) {
        'dir' { Add-KsDirPlayables ([string]$Open.Path) ([string]$Open.Media) 0 $list $limit }
        'seasons' {
            $r = Invoke-Kodi 'VideoLibrary.GetEpisodes' @{ tvshowid = [int]$Open.TvShowId; properties = @('title', 'episode', 'season', 'file') } 20000
            if ($r.Ok) {
                foreach ($e in @($r.Result.episodes | Sort-Object { [int]$_.season }, { [int]$_.episode })) {
                    if ($e -and $list.Count -lt $limit) {
                        $src = Get-KsMirrorUrl ([string]$e.file)
                        if ($src) { $list.Add([pscustomobject]@{ Title = ('{0} S{1:00}E{2:00} {3}' -f $Open.Title, [int]$e.season, [int]$e.episode, $e.title); Src = $src }) }
                    }
                }
            }
        }
        'episodes' {
            $r = Invoke-Kodi 'VideoLibrary.GetEpisodes' @{ tvshowid = [int]$Open.TvShowId; season = [int]$Open.Season; properties = @('title', 'episode', 'season', 'file'); sort = @{ method = 'episode' } } 20000
            if ($r.Ok) {
                foreach ($e in @($r.Result.episodes)) {
                    if ($e -and $list.Count -lt $limit) {
                        $src = Get-KsMirrorUrl ([string]$e.file)
                        if ($src) { $list.Add([pscustomobject]@{ Title = ('{0}  E{1:00}  {2}' -f $Open.Title, [int]$e.episode, $e.title); Src = $src }) }
                    }
                }
            }
        }
        'albums' {
            $r = Invoke-Kodi 'AudioLibrary.GetSongs' @{ filter = @{ artistid = [int]$Open.ArtistId }; properties = @('title', 'file', 'track', 'album') } 20000
            if ($r.Ok) {
                foreach ($s in @($r.Result.songs | Sort-Object { [string]$_.album }, { [int]$_.track })) {
                    if ($s -and $list.Count -lt $limit) {
                        $src = Get-KsMirrorUrl ([string]$s.file)
                        if ($src) { $list.Add([pscustomobject]@{ Title = ('{0} - {1}' -f $Open.Title, $s.title); Src = $src }) }
                    }
                }
            }
        }
    }
    return @{ Items = $list.ToArray(); Limit = ($list.Count -ge $limit) }
}

$script:KsMb = @{
    Stack     = New-Object System.Collections.ArrayList
    Items     = @()
    Thumb     = ''
    Form      = $null
    LblPath   = $null
    BtnBack   = $null
    TxtSearch = $null
    Lv        = $null
    Pic       = $null
    LblSel    = $null
    LblSub    = $null
    TxtPlot   = $null
    BtnPlayIt = $null
    StartView = $null
    LblMsg    = $null
}

# $StartView: direkt diese Ansicht öffnen (z. B. eine Serie aus der Suche), sonst "Filme"
function Show-KsMediaBrowser($StartView = $null) {
    if ($script:KsMb.Form -and -not $script:KsMb.Form.IsDisposed) {
        $script:KsMb.Form.WindowState = 'Normal'
        $script:KsMb.Form.TopMost = [bool]$st.Full
        $script:KsMb.Form.Activate()
        if ($StartView) {
            $script:KsMb.Stack.Clear()
            & $script:KsMbLoad $StartView $true
        }
        return
    }
    $script:KsMb.StartView = $StartView
    $script:KsMb.Stack.Clear()
    $script:KsMb.Items = @()
    $script:KsMb.Thumb = ''

    $f = (New-PelForm)
    $f.Text = 'Kodi - Medien auswählen'
    $f.Size = New-Object System.Drawing.Size(1100, 700)
    $f.MinimumSize = New-Object System.Drawing.Size(900, 560)
    $f.StartPosition = 'CenterScreen'
    $f.BackColor = $cBack
    $f.ForeColor = $cText
    $f.Font = $fMain
    $f.TopMost = [bool]$st.Full
    $script:KsMb.Form = $f

    # Kategorien
    $cats = @(
        @{ T = 'Filme'; V = @{ Type = 'movies'; Title = 'Filme' } }
        @{ T = 'Serien'; V = @{ Type = 'tvshows'; Title = 'Serien' } }
        @{ T = 'Neu hinzugefügt'; V = @{ Type = 'recent'; Title = 'Neu hinzugefügt' } }
        @{ T = 'Musik'; V = @{ Type = 'artists'; Title = 'Musik' } }
        @{ T = 'Dateien / Quellen'; V = @{ Type = 'sources'; Title = 'Dateien' } }
    )
    $script:KsCatBtns = @()
    $y = 12
    foreach ($c in $cats) {
        $b = New-KsButton $c.T 12 $y 180 40
        $b.Tag = $c.V
        $f.Controls.Add($b)
        $script:KsCatBtns += $b
        $y += 46
    }

    $btnBackNav = New-KsButton ([string][char]0x2190 + ' Zurück') 204 12 110 32
    $script:KsMb.BtnBack = $btnBackNav

    $lblPath = New-KsLabel 'Bereich links wählen' 322 18 420 22
    $lblPath.Font = $fBold
    $lblPath.AutoEllipsis = $true
    $script:KsMb.LblPath = $lblPath

    $lblSearch = New-KsLabel 'Suchen:' 750 18 56 22
    $txtSearch = New-KsText 806 14 270 ''
    $script:KsMb.TxtSearch = $txtSearch

    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = New-Object System.Drawing.Point(204, 52)
    $lv.Size = New-Object System.Drawing.Size(560, 588)
    $lv.View = 'Details'
    $lv.FullRowSelect = $true
    $lv.HideSelection = $false
    $lv.MultiSelect = $false
    $lv.BackColor = $cPanel
    $lv.ForeColor = $cText
    $lv.BorderStyle = 'None'
    [void]$lv.Columns.Add('Titel', 330)
    [void]$lv.Columns.Add('Info', 210)
    $script:KsMb.Lv = $lv

    # Details
    $pic = New-Object System.Windows.Forms.PictureBox
    $pic.Location = New-Object System.Drawing.Point(776, 52)
    $pic.Size = New-Object System.Drawing.Size(300, 300)
    $pic.SizeMode = 'Zoom'
    $pic.BackColor = [System.Drawing.Color]::Black
    $script:KsMb.Pic = $pic

    $lblSel = New-KsLabel '' 776 358 300 44
    $lblSel.Font = $fBold
    $script:KsMb.LblSel = $lblSel

    $lblSub = New-KsLabel '' 776 402 300 20
    $lblSub.ForeColor = $cDim
    $script:KsMb.LblSub = $lblSub

    $txtPlot = New-Object System.Windows.Forms.TextBox
    $txtPlot.Location = New-Object System.Drawing.Point(776, 424)
    $txtPlot.Size = New-Object System.Drawing.Size(300, 60)
    $txtPlot.Multiline = $true
    $txtPlot.ReadOnly = $true
    $txtPlot.ScrollBars = 'Vertical'
    $txtPlot.BackColor = $cBack
    $txtPlot.ForeColor = $cDim
    $txtPlot.BorderStyle = 'None'
    $script:KsMb.TxtPlot = $txtPlot

    # Der frühere Knopf "Ordner öffnen" entfällt: Ordner öffnet jetzt ein Doppelklick,
    # alles Weitere (ganzen Ordner abspielen ...) steht im Rechtsklick-Menü.
    $btnPlayIt = New-KsButton 'Abspielen (auf diesem PC)' 776 490 300 34 $true
    $btnQueueIt = New-KsButton 'In Wiedergabeliste (Datei oder ganzer Ordner)' 776 530 300 32
    $script:KsMb.BtnPlayIt = $btnPlayIt
    $lblMbHint = New-KsLabel 'Doppelklick: Ordner öffnen bzw. Titel abspielen. Rechtsklick: ganzen Ordner abspielen, ab hier abspielen, in die Wiedergabeliste ...' 776 568 300 54
    $lblMbHint.ForeColor = $cDim
    $lblMbHint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5, [System.Drawing.FontStyle]::Italic)

    $lblMsg = New-KsLabel '' 776 624 300 40
    $lblMsg.ForeColor = $cDim
    $script:KsMb.LblMsg = $lblMsg

    $f.Controls.AddRange(@($btnBackNav, $lblPath, $lblSearch, $txtSearch, $lv, $pic, $lblSel, $lblSub, $txtPlot, $btnPlayIt, $btnQueueIt, $lblMbHint, $lblMsg))

    # Anker-Verhalten für Resizing
    $lblPath.Anchor = 'Top, Left, Right'
    $lblSearch.Anchor = 'Top, Right'
    $txtSearch.Anchor = 'Top, Right'
    $lv.Anchor = 'Top, Left, Right, Bottom'
    foreach ($c in @($pic, $lblSel, $lblSub, $txtPlot, $btnPlayIt, $btnQueueIt, $lblMbHint, $lblMsg)) {
        $c.Anchor = 'Top, Right'
    }

    # Methoden
    $script:KsMbFill = {
        if (-not $script:KsMb.Form -or $script:KsMb.Form.IsDisposed) { return }
        $q = $script:KsMb.TxtSearch.Text.Trim()
        $script:KsMb.Lv.BeginUpdate()
        $script:KsMb.Lv.Items.Clear()
        foreach ($it in $script:KsMb.Items) {
            if ($q -and ($it.Title -notlike "*$q*")) { continue }
            $li = New-Object System.Windows.Forms.ListViewItem($(if ($it.Open) { [string][char]0x25B8 + ' ' + $it.Title } else { $it.Title }))
            [void][PelI18n]::AddSub($li, [string]$it.Sub)
            $li.Tag = $it
            if ($it.Sub -like '*gesehen' -and $it.Kind -ne 'folder') { $li.ForeColor = $cDim }
            [void]$script:KsMb.Lv.Items.Add($li)
        }
        $script:KsMb.Lv.EndUpdate()
        $script:KsMb.LblMsg.Text = '{0} Einträge' -f $script:KsMb.Lv.Items.Count
    }

    $script:KsMbLoad = {
        param($view, [bool]$push)
        if (-not $script:KsMb.Form -or $script:KsMb.Form.IsDisposed) { return }
        $script:KsMb.Form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            $res = Get-KsMediaItems $view
            if ($push) { [void]$script:KsMb.Stack.Add($view) }
            $script:KsMb.Items = @($res.Items)
            $script:KsMb.LblPath.Text = [string]$view.Title
            $script:KsMb.TxtSearch.Text = ''
            & $script:KsMbFill
            if ($res.Error) { $script:KsMb.LblMsg.Text = $res.Error }
            elseif ($script:KsMb.Items.Count -eq 0) { $script:KsMb.LblMsg.Text = 'Hier ist nichts.' }
        } finally {
            if (-not $script:KsMb.Form.IsDisposed) {
                $script:KsMb.Form.Cursor = [System.Windows.Forms.Cursors]::Default
            }
        }
        $script:KsMb.BtnBack.Enabled = ($script:KsMb.Stack.Count -gt 1)
    }

    $script:KsMbSel = {
        if ($script:KsMb.Lv -and $script:KsMb.Lv.SelectedItems.Count -gt 0) { return $script:KsMb.Lv.SelectedItems[0].Tag }
        return $null
    }

    $script:KsMbPlay = {
        $it = & $script:KsMbSel
        if (-not $it) { $script:KsMb.LblMsg.Text = 'Bitte zuerst etwas auswählen.'; return }
        # Ordner (auch Serie, Staffel, Interpret): ganzen Inhalt abspielen
        if ($it.Open) { & $script:KsMbPlayFolder $it.Open $it.Title; return }
        if (-not $it.File) { $script:KsMb.LblMsg.Text = 'Das lässt sich nicht direkt abspielen.'; return }
        $src = Get-KsMirrorUrl $it.File
        if (-not $src) { $script:KsMb.LblMsg.Text = 'Diese Quelle lässt sich nicht lokal abspielen.'; return }
        Start-KsMirror -Source $src -Title $it.Title
        $script:KsMb.LblMsg.Text = "Wird auf diesem PC abgespielt: $($it.Title)"
    }

    $script:KsMbQueue = {
        $it = & $script:KsMbSel
        if (-not $it) { $script:KsMb.LblMsg.Text = 'Bitte zuerst etwas auswählen.'; return }
        $script:KsMb.Form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            if ($it.Open) {
                $res = Get-KsFolderPlayables $it.Open
                $ents = @($res.Items)
                if ($ents.Count -eq 0) { $script:KsMb.LblMsg.Text = 'Hier wurde nichts Abspielbares gefunden.'; return }
                Add-KsPlaylist $ents
                $script:KsMb.LblMsg.Text = ('{0} Titel in die Wiedergabeliste gelegt.{1}' -f $ents.Count, $(if ($res.Limit) { ' (Limit 500 erreicht)' } else { '' }))
            } elseif ($it.File) {
                $src = Get-KsMirrorUrl $it.File
                if (-not $src) { $script:KsMb.LblMsg.Text = 'Diese Quelle lässt sich nicht lokal abspielen.'; return }
                Add-KsPlaylist @([pscustomobject]@{ Title = $it.Title; Src = $src })
                $script:KsMb.LblMsg.Text = "In die Wiedergabeliste gelegt: $($it.Title)"
            } else {
                $script:KsMb.LblMsg.Text = 'Das lässt sich nicht abspielen.'
            }
        } finally {
            if (-not $script:KsMb.Form.IsDisposed) { $script:KsMb.Form.Cursor = [System.Windows.Forms.Cursors]::Default }
        }
    }

    $script:KsMbOpenSel = {
        $it = & $script:KsMbSel
        if (-not $it) { return }
        if ($it.Open) { & $script:KsMbLoad $it.Open $true } else { & $script:KsMbPlay }
    }

    # Ganzen Ordner (bzw. Serie, Staffel, Interpret) abspielen: ersetzt die Wiedergabeliste
    $script:KsMbPlayFolder = {
        param($Open, [string]$Title)
        $script:KsMb.Form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            $res = Get-KsFolderPlayables $Open
            $ents = @($res.Items)
            if ($ents.Count -eq 0) { $script:KsMb.LblMsg.Text = 'Hier wurde nichts Abspielbares gefunden.'; return }
            [void](Start-KsPlaylistNew $ents 0)
            $script:KsMb.LblMsg.Text = ('{0} Titel werden abgespielt: {1}{2}' -f $ents.Count, $Title, $(if ($res.Limit) { ' (Limit 500 erreicht)' } else { '' }))
        } finally {
            if (-not $script:KsMb.Form.IsDisposed) { $script:KsMb.Form.Cursor = [System.Windows.Forms.Cursors]::Default }
        }
    }

    # Alle abspielbaren Einträge der aktuellen Liste (in der angezeigten Reihenfolge, Filter
    # beachtet). Rückgabe: @{ Entries; Start } - Start = Position des markierten Eintrags.
    $script:KsMbListEntries = {
        $ents = New-Object System.Collections.Generic.List[object]
        $start = 0
        $selIt = & $script:KsMbSel
        foreach ($li in $script:KsMb.Lv.Items) {
            $x = $li.Tag
            if (-not $x -or $x.Open -or -not $x.File) { continue }
            $src = Get-KsMirrorUrl ([string]$x.File)
            if (-not $src) { continue }
            if ($selIt -and [object]::ReferenceEquals($x, $selIt)) { $start = $ents.Count }
            $ents.Add([pscustomobject]@{ Title = [string]$x.Title; Src = $src })
        }
        return @{ Entries = $ents.ToArray(); Start = $start }
    }

    # "Ab hier abspielen": alle Titel dieser Liste, beginnend beim markierten
    $script:KsMbPlayFromHere = {
        $r0 = & $script:KsMbListEntries
        if (@($r0.Entries).Count -eq 0) { $script:KsMb.LblMsg.Text = 'Hier wurde nichts Abspielbares gefunden.'; return }
        [void](Start-KsPlaylistNew @($r0.Entries) $r0.Start)
        $script:KsMb.LblMsg.Text = ('{0} Titel in der Wiedergabeliste, Start bei Nr. {1}.' -f @($r0.Entries).Count, ($r0.Start + 1))
    }

    # "Alles hier abspielen": ganzer aktueller Ordner (bei Dateien inkl. Unterordnern),
    # bei Listen wie "Filme" alle angezeigten Einträge
    $script:KsMbPlayView = {
        $cur = $null
        if ($script:KsMb.Stack.Count -gt 0) { $cur = $script:KsMb.Stack[$script:KsMb.Stack.Count - 1] }
        if ($cur -and @('dir', 'seasons', 'episodes', 'albums') -contains [string]$cur.Type -and -not $script:KsMb.TxtSearch.Text.Trim()) {
            & $script:KsMbPlayFolder $cur ([string]$cur.Title)
            return
        }
        $r0 = & $script:KsMbListEntries
        if (@($r0.Entries).Count -eq 0) { $script:KsMb.LblMsg.Text = 'Hier wurde nichts Abspielbares gefunden.'; return }
        [void](Start-KsPlaylistNew @($r0.Entries) 0)
        $script:KsMb.LblMsg.Text = ('{0} Titel in der Wiedergabeliste, Start bei Nr. {1}.' -f @($r0.Entries).Count, 1)
    }

    # Rechtsklick-Menü (je nach Auswahl: Ordner oder Datei)
    $cmMb = New-PelContextMenu
    $miOpen = $cmMb.Items.Add('Öffnen')
    $miPlay = $cmMb.Items.Add('Abspielen')
    $miPlayFolder = $cmMb.Items.Add('Ganzen Ordner abspielen')
    $miQueueFolder = $cmMb.Items.Add('Ganzen Ordner in die Wiedergabeliste')
    $miQueue = $cmMb.Items.Add('In die Wiedergabeliste')
    $miFromHere = $cmMb.Items.Add('Ab hier der Reihe nach abspielen')
    $miSep = New-Object System.Windows.Forms.ToolStripSeparator
    [void]$cmMb.Items.Add($miSep)
    $miPlayView = $cmMb.Items.Add('Alles in dieser Ansicht abspielen')
    $miOpen.Font = New-Object System.Drawing.Font($miOpen.Font, [System.Drawing.FontStyle]::Bold)
    # Das Fenster ist nicht modal (Show statt ShowDialog) - lokale Variablen gibt es beim
    # Rechtsklick nicht mehr, deshalb liegen die Einträge im Skript-Bereich
    $script:KsMbMi = @{ Open = $miOpen; Play = $miPlay; PlayFolder = $miPlayFolder; QueueFolder = $miQueueFolder; Queue = $miQueue; FromHere = $miFromHere; Sep = $miSep; PlayView = $miPlayView }
    $cmMb.Add_Opening({
        param($s, $e)
        $it = & $script:KsMbSel
        $isFolder = [bool]($it -and $it.Open)
        $isFile = [bool]($it -and -not $it.Open -and $it.File)
        $mi = $script:KsMbMi
        $mi.Open.Visible = $isFolder
        $mi.PlayFolder.Visible = $isFolder
        $mi.QueueFolder.Visible = $isFolder
        $mi.Play.Visible = $isFile
        $mi.Queue.Visible = $isFile
        $mi.FromHere.Visible = $isFile
        $mi.Sep.Visible = ($isFolder -or $isFile)
        $mi.PlayView.Enabled = ($script:KsMb.Lv.Items.Count -gt 0)
    })
    $miOpen.Add_Click({ & $script:KsMbOpenSel })
    $miPlay.Add_Click({ & $script:KsMbPlay })
    $miPlayFolder.Add_Click({ $it = & $script:KsMbSel; if ($it -and $it.Open) { & $script:KsMbPlayFolder $it.Open $it.Title } })
    $miQueueFolder.Add_Click({ & $script:KsMbQueue })
    $miQueue.Add_Click({ & $script:KsMbQueue })
    $miFromHere.Add_Click({ & $script:KsMbPlayFromHere })
    $miPlayView.Add_Click({ & $script:KsMbPlayView })
    $lv.ContextMenuStrip = $cmMb
    # Rechtsklick markiert zuerst den Eintrag unter der Maus
    $lv.Add_MouseDown({
        param($s, $e)
        if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Right) { return }
        $hit = $script:KsMb.Lv.GetItemAt($e.X, $e.Y)
        if ($hit) { $hit.Selected = $true; $hit.Focused = $true }
    })

    # Event-Handler
    foreach ($b in $script:KsCatBtns) {
        $b.Add_Click({
            param($s, $e)
            foreach ($x in $script:KsCatBtns) { $x.BackColor = $cBtn }
            $s.BackColor = $cAcc
            $script:KsMb.Stack.Clear()
            & $script:KsMbLoad $s.Tag $true
        })
    }

    $btnBackNav.Add_Click({
        if ($script:KsMb.Stack.Count -gt 1) {
            $script:KsMb.Stack.RemoveAt($script:KsMb.Stack.Count - 1)
            & $script:KsMbLoad $script:KsMb.Stack[$script:KsMb.Stack.Count - 1] $false
        }
    })

    $txtSearch.Add_TextChanged({ & $script:KsMbFill })
    # Doppelklick (und Enter): Ordner öffnen, Datei abspielen. Ganzen Ordner abspielen oder
    # in die Wiedergabeliste legen geht über das Rechtsklick-Menü.
    $lv.Add_DoubleClick({ & $script:KsMbOpenSel })
    $lv.Add_KeyDown({
        if ($_.KeyCode -eq 'Enter') {
            $_.SuppressKeyPress = $true
            & $script:KsMbOpenSel
        } elseif ($_.KeyCode -eq 'Back') {
            $script:KsMb.BtnBack.PerformClick()
        }
    })
    $lv.Add_SelectedIndexChanged({
        $it = & $script:KsMbSel
        if (-not $it) { return }
        $script:KsMb.LblSel.Text = $it.Title
        $script:KsMb.LblSub.Text = $it.Sub
        $script:KsMb.TxtPlot.Text = $it.Plot
        $script:KsMb.BtnPlayIt.Text = $(if ($it.Open) { 'Ganzen Ordner abspielen' } else { 'Abspielen (auf diesem PC)' })
        if ($it.Thumb -ne $script:KsMb.Thumb) {
            $script:KsMb.Thumb = $it.Thumb
            $old = $script:KsMb.Pic.Image
            $script:KsMb.Pic.Image = $null
            if ($old) { $old.Dispose() }
            $script:KsMb.Pic.Image = Get-KsImage $it.Thumb
        }
    })
    $btnPlayIt.Add_Click({ & $script:KsMbPlay })
    $btnQueueIt.Add_Click({ & $script:KsMbQueue })

    $f.Add_Shown({
        if ($script:KsMb.StartView) {
            $sv0 = $script:KsMb.StartView
            $script:KsMb.StartView = $null
            $script:KsMb.Stack.Clear()
            & $script:KsMbLoad $sv0 $true
        } elseif ($script:KsCatBtns -and $script:KsCatBtns.Count -gt 0) {
            $script:KsCatBtns[0].PerformClick()
        }
    })
    $f.Add_FormClosed({
        if ($script:KsMb.Pic.Image) { $script:KsMb.Pic.Image.Dispose() }
        $script:KsMb.Form = $null
    })

    $f.Show()
}

# Vollbildsteuerung
function Enter-KsFullscreen {
    if ($st.Full) { return }
    $scr = [System.Windows.Forms.Screen]::FromControl($form)
    $st.FullSaved = @{
        BorderStyle = $form.FormBorderStyle
        WindowState = $form.WindowState
        Bounds      = $form.Bounds
        TopMost     = $form.TopMost
        PLoc        = $pLive.Location
        PSize       = $pLive.Size
        PAnchor     = $pLive.Anchor
    }
    foreach ($c in @($pConn, $lblLive, $pScrub, $pCtl, $pLiveBar, $lblShortcuts, $lblToggleStatus, $btnSetToggleKey, $pNow, $pRight)) { $c.Visible = $false }
    $form.WindowState = 'Normal'
    $form.FormBorderStyle = 'None'
    $form.Bounds = $scr.Bounds
    $form.TopMost = $true
    $pLive.Anchor = 'Top, Left, Right, Bottom'
    $pLive.Location = New-Object System.Drawing.Point(0, 0)
    $pLive.Size = $form.ClientSize
    $st.Full = $true
    $btnFullExit.Text = [string][char]0x2715 + '  Vollbild verlassen (ESC)'
    # Medienauswahl muss im Vollbild vor dem (TopMost-)Fenster liegen
    if ($script:KsMb.Form -and -not $script:KsMb.Form.IsDisposed) { $script:KsMb.Form.TopMost = $true }
    Show-KsOverlay
}

function Exit-KsFullscreen {
    if (-not $st.Full -or -not $st.FullSaved) { return }
    $sv = $st.FullSaved
    $btnFullExit.Text = 'Vollbild'
    if ($fOvBot.Visible) { $fOvBot.Hide() }
    if ($script:KsMb.Form -and -not $script:KsMb.Form.IsDisposed) { $script:KsMb.Form.TopMost = $false }
    $form.TopMost = $sv.TopMost
    $form.FormBorderStyle = $sv.BorderStyle
    $form.Bounds = $sv.Bounds
    $form.WindowState = $sv.WindowState
    $pLive.Anchor = $sv.PAnchor
    $pLive.Location = $sv.PLoc
    $pLive.Size = $sv.PSize
    foreach ($c in @($pConn, $lblLive, $pScrub, $pCtl, $pLiveBar, $lblShortcuts, $lblToggleStatus, $btnSetToggleKey, $pNow, $pRight)) { $c.Visible = $true }
    $st.Full = $false
    $st.FullSaved = $null
    Show-KsOverlay
}

# ------------------------------------------------------------------------------
# Einblend-Leisten über dem Video: erscheinen bei Mausbewegung über dem Videobereich,
# verschwinden nach 3 Sekunden ohne Bewegung. Die Maus wird per Timer abgefragt, weil
# das eingebettete mpv-/VLC-Fenster (fremder Prozess) die Mausereignisse selbst bekommt.
# Nicht ausgeblendet wird, solange nichts läuft, im Suchfeld getippt wird oder die Maus
# über einer Leiste steht. Das Video-Fenster von mpv/VLC liegt nach jedem Start oben -
# deshalb holt Show-KsOverlay die Leisten jedes Mal wieder nach vorne.
# ------------------------------------------------------------------------------
$script:KsOv = @{ Until = (Get-Date); LastPos = [System.Drawing.Point]::Empty; Owned = $false }

# Leisten-Fenster an den Videobereich anpassen (Fenster verschoben, Größe, Vollbild)
function Set-KsOverlayBounds {
    $r = $pLive.RectangleToScreen($pLive.ClientRectangle)
    $hTop = $(if ($lbFind.Visible) { 46 + $lbFind.Height + 6 } else { 44 })
    $bt = New-Object System.Drawing.Rectangle($r.X, $r.Y, $r.Width, [Math]::Min($hTop, $r.Height))
    if ($fOvTop.Bounds -ne $bt) { $fOvTop.Bounds = $bt }
    $bb = New-Object System.Drawing.Rectangle($r.X, ($r.Bottom - 26 - 68), $r.Width, 68)
    if ($fOvBot.Bounds -ne $bb) { $fOvBot.Bounds = $bb }
}

function Show-KsOverlay {
    if ($form.WindowState -eq 'Minimized' -or -not $form.Visible) { return }
    $script:KsOv.Until = (Get-Date).AddSeconds(3)
    if (-not $script:KsOv.Owned) {
        # Owner erst setzen, wenn das Hauptfenster existiert (sonst Fehler beim Anzeigen)
        $fOvTop.Owner = $form
        $fOvBot.Owner = $form
        $script:KsOv.Owned = $true
    }
    Set-KsOverlayBounds
    $wasMain = ([System.Windows.Forms.Form]::ActiveForm -eq $form)
    $shown = $false
    if (-not $fOvTop.Visible) { $fOvTop.Show(); $shown = $true }
    if ($st.Full) { if (-not $fOvBot.Visible) { $fOvBot.Show(); $shown = $true } }
    elseif ($fOvBot.Visible) { $fOvBot.Hide() }
    # Ersatzfenster ohne ShowWithoutActivation (falls KsOverlayForm nicht kompiliert): Fokus zurück
    if ($shown -and $wasMain -and $fOvTop.GetType().Name -ne 'KsOverlayForm') { try { $form.Activate() } catch { } }
}

function Hide-KsOverlay {
    if ($lbFind.Visible) { $lbFind.Visible = $false }
    foreach ($o in @($fOvTop, $fOvBot)) { if ($o.Visible) { $o.Hide() } }
}

# Fokus zurück ans Hauptfenster (sonst wirken die Tastenkürzel nicht, solange eine Leiste
# aktiv ist - der Tastatur-Hook prüft das Vordergrundfenster)
function Restore-KsMainFocus {
    try {
        if ($fOvTop.ContainsFocus -or $fOvBot.ContainsFocus -or [System.Windows.Forms.Form]::ActiveForm -eq $fOvTop -or [System.Windows.Forms.Form]::ActiveForm -eq $fOvBot) { $form.Activate() }
        $form.ActiveControl = $null
    } catch { }
}

function Update-KsOverlay {
    if ($form.WindowState -eq 'Minimized' -or -not $form.Visible) { if ($fOvTop.Visible -or $fOvBot.Visible) { Hide-KsOverlay }; return }
    $pos = [System.Windows.Forms.Cursor]::Position
    $moved = ($pos -ne $script:KsOv.LastPos)
    $script:KsOv.LastPos = $pos
    $inside = $pLive.RectangleToScreen($pLive.ClientRectangle).Contains($pos)
    # nur reagieren, wenn eines unserer Fenster vorne ist (nicht, wenn ein anderes Programm darüber liegt)
    $act = [System.Windows.Forms.Form]::ActiveForm
    $ours = ($act -eq $form -or $act -eq $fOvTop -or $act -eq $fOvBot)
    if ($inside -and $moved -and $ours) { Show-KsOverlay }
    if ($fOvTop.Visible) { Set-KsOverlayBounds }
    $running = $false
    try { $running = [bool]($st.Mirror -and -not $st.Mirror.HasExited) } catch { }
    if (-not $running) {
        if ($ours -and (-not $fOvTop.Visible -or ($st.Full -and -not $fOvBot.Visible))) { Show-KsOverlay }
        return
    }
    if (-not $fOvTop.Visible -and -not $fOvBot.Visible) { return }
    $busy = ($txtFind.Focused -or $lbFind.Focused)
    foreach ($o in @($fOvTop, $fOvBot)) { if ($o.Visible -and $o.Bounds.Contains($pos)) { $busy = $true } }
    if ($busy) { $script:KsOv.Until = (Get-Date).AddSeconds(3); return }
    if ((Get-Date) -gt $script:KsOv.Until) { Hide-KsOverlay }
}

# ------------------------------------------------------------------------------
# Suche in der Kodi-Bibliothek (Leiste über dem Video). Treffer: Filme, Serien, Folgen,
# Musiktitel und Interpreten (je höchstens 25). Doppelklick/Enter: Film, Folge oder
# Titel spielt sofort ab, Serie/Interpret öffnet die Medienauswahl an dieser Stelle.
# ------------------------------------------------------------------------------
$script:KsFind = @{ Items = @(); Due = $null; Last = '' }

function Get-KsTr([string]$Text) {
    try { if ([PelI18n]::Enabled) { return [PelI18n]::Tr($Text) } } catch { }
    return $Text
}

function Find-KsMedia([string]$Q) {
    $out = New-Object System.Collections.Generic.List[object]
    $lim = @{ start = 0; end = 25 }
    $flt = { param([string]$Field) @{ field = $Field; operator = 'contains'; value = $Q } }
    $r = Invoke-Kodi 'VideoLibrary.GetMovies' @{ filter = (& $flt 'title'); properties = @('title', 'year', 'file'); limits = $lim; sort = @{ method = 'sorttitle'; ignorearticle = $true } } 8000
    if ($r.Ok) { foreach ($m in @($r.Result.movies)) { if ($m) { $out.Add([pscustomobject]@{ Kind = 'movie'; Label = ('[{0}]  {1} ({2})' -f (Get-KsTr 'Film'), $m.title, $m.year); Title = [string]$m.title; File = [string]$m.file; Open = $null }) } } }
    $r = Invoke-Kodi 'VideoLibrary.GetTVShows' @{ filter = (& $flt 'title'); properties = @('title', 'year'); limits = $lim } 8000
    if ($r.Ok) { foreach ($t in @($r.Result.tvshows)) { if ($t) { $out.Add([pscustomobject]@{ Kind = 'show'; Label = ('[{0}]  {1}' -f (Get-KsTr 'Serie'), $t.title); Title = [string]$t.title; File = ''; Open = @{ Type = 'seasons'; TvShowId = [int]$t.tvshowid; Title = [string]$t.title } }) } } }
    $r = Invoke-Kodi 'VideoLibrary.GetEpisodes' @{ filter = (& $flt 'title'); properties = @('title', 'showtitle', 'season', 'episode', 'file'); limits = $lim } 8000
    if ($r.Ok) { foreach ($e in @($r.Result.episodes)) { if ($e) { $tt = ('{0} S{1:00}E{2:00} {3}' -f $e.showtitle, [int]$e.season, [int]$e.episode, $e.title); $out.Add([pscustomobject]@{ Kind = 'episode'; Label = ('[{0}]  {1}' -f (Get-KsTr 'Folge'), $tt); Title = $tt; File = [string]$e.file; Open = $null }) } } }
    $r = Invoke-Kodi 'AudioLibrary.GetArtists' @{ filter = (& $flt 'artist'); limits = $lim } 8000
    if ($r.Ok) { foreach ($a in @($r.Result.artists)) { if ($a) { $out.Add([pscustomobject]@{ Kind = 'artist'; Label = ('[{0}]  {1}' -f (Get-KsTr 'Interpret'), $a.artist); Title = [string]$a.artist; File = ''; Open = @{ Type = 'albums'; ArtistId = [int]$a.artistid; Title = [string]$a.artist } }) } } }
    $r = Invoke-Kodi 'AudioLibrary.GetSongs' @{ filter = (& $flt 'title'); properties = @('title', 'artist', 'file'); limits = $lim } 8000
    if ($r.Ok) { foreach ($so in @($r.Result.songs)) { if ($so) { $tt = ('{0} - {1}' -f (@($so.artist) -join ', '), $so.title); $out.Add([pscustomobject]@{ Kind = 'song'; Label = ('[{0}]  {1}' -f (Get-KsTr 'Musik'), $tt); Title = $tt; File = [string]$so.file; Open = $null }) } } }
    return , $out
}

function Invoke-KsFind {
    $q = $txtFind.Text.Trim()
    $script:KsFind.Due = $null
    if ($q.Length -lt 2) { $lbFind.Visible = $false; $script:KsFind.Items = @(); $script:KsFind.Last = ''; return }
    if ($q -eq $script:KsFind.Last -and $lbFind.Visible) { return }
    if (-not (Require-Ks)) { return }
    $script:KsFind.Last = $q
    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
    try { $res = Find-KsMedia $q } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
    $script:KsFind.Items = @($res.ToArray())
    $lbFind.BeginUpdate()
    $lbFind.Items.Clear()
    foreach ($it in $script:KsFind.Items) { [void]$lbFind.Items.Add([string]$it.Label) }
    if ($lbFind.Items.Count -eq 0) { [void]$lbFind.Items.Add((Get-KsTr 'Keine Treffer in der Kodi-Bibliothek.')) }
    $lbFind.EndUpdate()
    $lbFind.Visible = $true
    Show-KsOverlay
}

function Open-KsFindHit {
    $i = $lbFind.SelectedIndex
    if ($i -lt 0 -or $i -ge @($script:KsFind.Items).Count) { return }
    $it = $script:KsFind.Items[$i]
    $lbFind.Visible = $false
    Set-KsOverlayBounds
    Restore-KsMainFocus
    if ($it.Open) {
        Show-KsMediaBrowser $it.Open
        return
    }
    $src = Get-KsMirrorUrl $it.File
    if (-not $src) { Add-KsLog 'Diese Quelle lässt sich nicht lokal abspielen.'; return }
    Start-KsMirror -Source $src -Title $it.Title
    Show-KsOverlay
}

# System-Ereignisse
$btnMedia.Add_Click({ if (Require-Ks) { Show-KsMediaBrowser } })
$btnConnect.Add_Click({ Connect-Ks })
$txtPass.Add_KeyDown({ if ($_.KeyCode -eq 'Enter') { $_.SuppressKeyPress = $true; Connect-Ks } })

$btnLiveStop.Add_Click({ Stop-KsUser })
$btnPlaylist.Add_Click({ Show-KsPlaylist })
$btnFullPc.Add_Click({ if ($st.Full) { Exit-KsFullscreen } else { Enter-KsFullscreen } })
# Knopf in der Einblend-Leiste: Vollbild an/aus
$btnFullExit.Add_Click({ Restore-KsMainFocus; if ($st.Full) { Exit-KsFullscreen } else { Enter-KsFullscreen } })
$btnOvMedia.Add_Click({ if (Require-Ks) { Show-KsMediaBrowser } })
# Esc in einem Leisten-Fenster: Trefferliste schließen bzw. Vollbild verlassen
foreach ($ov in @($fOvTop, $fOvBot)) {
    $ov.Add_KeyDown({
        param($s, $e)
        if ($e.KeyCode -ne 'Escape') { return }
        $e.Handled = $true
        $e.SuppressKeyPress = $true
        if ($lbFind.Visible) { $lbFind.Visible = $false; Set-KsOverlayBounds; Restore-KsMainFocus }
        elseif ($st.Full) { Restore-KsMainFocus; Exit-KsFullscreen }
        else { Restore-KsMainFocus }
    })
}

# Suche: nach kurzer Tipp-Pause (0,6 s) oder sofort mit Enter; Pfeil runter springt in
# die Trefferliste, Esc schließt sie
$txtFind.Add_TextChanged({ $script:KsFind.Due = (Get-Date).AddMilliseconds(600); Show-KsOverlay })
$txtFind.Add_KeyDown({
    param($s, $e)
    if ($e.KeyCode -eq 'Enter') {
        $e.SuppressKeyPress = $true
        if ($lbFind.Visible -and $lbFind.Items.Count -gt 0 -and $script:KsFind.Last -eq $txtFind.Text.Trim()) { if ($lbFind.SelectedIndex -lt 0) { $lbFind.SelectedIndex = 0 }; Open-KsFindHit }
        else { Invoke-KsFind }
    } elseif ($e.KeyCode -eq 'Down' -and $lbFind.Visible -and $lbFind.Items.Count -gt 0) {
        $e.SuppressKeyPress = $true
        if ($lbFind.SelectedIndex -lt 0) { $lbFind.SelectedIndex = 0 }
        $lbFind.Focus() | Out-Null
    }
})
$lbFind.Add_DoubleClick({ Open-KsFindHit })
$lbFind.Add_KeyDown({
    param($s, $e)
    if ($e.KeyCode -eq 'Enter') { $e.SuppressKeyPress = $true; Open-KsFindHit }
})
$chkLiveAuto.Add_CheckedChanged({ $script:Ks.LiveAuto = $chkLiveAuto.Checked; Save-KsSettings })
$cmbPlayer.Add_SelectedIndexChanged({ $script:Ks.Player = [string]$cmbPlayer.SelectedItem; Save-KsSettings })

# Play/Pause per Linksklick auf den Videobereich - laeuft jetzt ueber den
# globalen Maus-Hook (KsKeyHook), damit es auch waehrend echter Wiedergabe
# funktioniert (dann liegt das eingebettete mpv-/VLC-Fenster ueber $picCover
# und ein normales WinForms-Klick-Ereignis wuerde nicht mehr ankommen).

$playOwnUrl = {
    $u = $txtUrl.Text.Trim()
    if (-not $u) { Add-KsLog 'Bitte eine Adresse eingeben.'; return }
    Start-KsMirror -Source $u -Title $u
}
$btnOpen.Add_Click({ & $playOwnUrl })
$txtUrl.Add_KeyDown({ if ($_.KeyCode -eq 'Enter') { $_.SuppressKeyPress = $true; & $playOwnUrl } })

$script:KsAwaitingToggleKey = $false

$btnSetToggleKey.Add_Click({
    $script:KsAwaitingToggleKey = $true
    $lblToggleStatus.Text = 'Bitte jetzt die gewünschte Taste drücken ... (Esc = abbrechen)'
    $form.Focus() | Out-Null
})

$form.Add_KeyDown({
    param($s, $e)
    if ($script:KsAwaitingToggleKey) {
        $script:KsAwaitingToggleKey = $false
        $e.Handled = $true
        $e.SuppressKeyPress = $true
        if ($e.KeyCode -ne 'Escape') {
            $script:Ks.ToggleKey = [int]$e.KeyCode
            if ($script:KsHookOk) { [KsKeyHook]::ToggleKey = $script:Ks.ToggleKey }
            Save-KsSettings
        }
        Update-KsToggleLabel
        return
    }
    # Esc schließt zuerst die Trefferliste der Suche, erst danach das Vollbild
    if ($e.KeyCode -eq 'Escape' -and $lbFind.Visible) {
        $lbFind.Visible = $false
        Set-KsOverlayBounds
        $form.ActiveControl = $null
        $e.Handled = $true
        $e.SuppressKeyPress = $true
        return
    }
    if ($e.KeyCode -eq 'Escape' -and $st.Full) {
        Exit-KsFullscreen
        $e.Handled = $true
        $e.SuppressKeyPress = $true
        return
    }
    # Notfall-Weg, falls der globale Hook nicht laeuft: Kuerzel direkt am Fenster.
    if (-not $script:KsHookOk -and $script:Ks.ShortcutsEnabled -and -not ($form.ActiveControl -is [System.Windows.Forms.TextBoxBase]) -and -not ($form.ActiveControl -is [System.Windows.Forms.ComboBox])) {
        $k = [int]$e.KeyCode
        if (@(32, 37, 38, 39, 40, 83, 76, 33, 34) -contains $k) {
            Invoke-KsShortcut $k
            $e.Handled = $true
            $e.SuppressKeyPress = $true
        }
    }
})

# In Eingabefeldern duerfen Leertaste/Pfeile/Buchstaben normal getippt werden.
foreach ($tf in @($txtHost, $txtPort, $txtUser, $txtPass, $txtUrl, $cmbPlayer, $txtFind, $lbFind)) {
    $tf.Add_Enter({ if ($script:KsHookOk) { [KsKeyHook]::TextFocus = $true } })
    $tf.Add_Leave({ if ($script:KsHookOk) { [KsKeyHook]::TextFocus = $false } })
}

# Schneller Poll-Timer (40 ms) fuer die vom globalen Tastatur-/Maus-Hook erfassten
# Ereignisse - bewusst getrennt vom normalen 1-Sekunden-Status-Timer weiter unten,
# damit sich Pause/Vor-/Zurueckspulen/Lautstaerke sofort reaktionsschnell anfuehlen.
$ksHookTimer = New-Object System.Windows.Forms.Timer
$ksHookTimer.Interval = 40
$ksHookTimer.Add_Tick({
    if ($script:KsHookOk) {
        $vk = 0
        while ([KsKeyHook]::Keys.TryDequeue([ref]$vk)) {
            if ($vk -eq $script:Ks.ToggleKey -and $script:Ks.ToggleKey -ne 0) {
                $script:Ks.ShortcutsEnabled = -not $script:Ks.ShortcutsEnabled
                [KsKeyHook]::Enabled = $script:Ks.ShortcutsEnabled
                Save-KsSettings
                Update-KsToggleLabel
                continue
            }
            try { Invoke-KsShortcut $vk } catch { Add-KsLog "Tastenkürzel-Fehler: $($_.Exception.Message)" }
        }
    }
    try { Invoke-KsPlaylistTick } catch { }
    try { Update-KsOverlay } catch { }
    try { if ($script:KsFind.Due -and (Get-Date) -ge $script:KsFind.Due) { Invoke-KsFind } } catch { $script:KsFind.Due = $null }
})

# Scrubbing-Leisten 4x pro Sekunde neu zeichnen (die Werte kommen aus dem Runspace)
$ksScrubTimer = New-Object System.Windows.Forms.Timer
$ksScrubTimer.Interval = 250
$ksScrubTimer.Add_Tick({
    foreach ($sc in $script:KsScrubs) { try { if ($sc.Visible -and $sc.TopLevelControl.Visible) { $sc.Invalidate() } } catch { } }
})

$timer = New-Object System.Windows.Forms.Timer
$timer.Interval = 1000
$timer.Add_Tick({
    try { Watch-KsVlcInstall } catch { }
    try { Update-KsStatus } catch { }
})

$form.Add_Shown({
    Add-KsLog 'Kodi-Steuerung bereit.'
    if ($script:Ks.Host -and ($script:Ks.Pass -or (Test-Path -LiteralPath $script:KsFile))) { Connect-Ks }
    if ('KsKeyHook' -as [type]) {
        [KsKeyHook]::WatchedKeys = @(32, 37, 38, 39, 40, 83, 76, 33, 34)
        [KsKeyHook]::Enabled = $script:Ks.ShortcutsEnabled
        [KsKeyHook]::ToggleKey = $script:Ks.ToggleKey
        $script:KsHookOk = [bool][KsKeyHook]::Start($form.Handle, $pLive.Handle)
        # Klicks auf die Einblend-Leisten sind normale Klicks (keine Pause)
        [KsKeyHook]::ExcludeHwnds = [IntPtr[]]@($fOvTop.Handle, $fOvBot.Handle)
    }
    Show-KsOverlay
    if ($script:KsHookOk) { Add-KsLog 'Tastenkürzel aktiv (auch bei laufendem Video).' }
    else { Add-KsLog ('Tastatur-Hook nicht verfügbar - Kürzel nur bei Fokus im Fenster. ' + $script:KsHookError) }
    $ksHookTimer.Start()
    $timer.Start()
    # Hintergrund-Abfrage für die Scrubbing-Leiste
    try {
        $script:KsPosRs = [runspacefactory]::CreateRunspace()
        $script:KsPosRs.Open()
        $script:KsPosRs.SessionStateProxy.SetVariable('sync', $script:KsPos)
        $script:KsPosPs = [powershell]::Create()
        $script:KsPosPs.Runspace = $script:KsPosRs
        [void]$script:KsPosPs.AddScript($ksPosWorker.ToString())
        [void]$script:KsPosPs.BeginInvoke()
    } catch { Add-KsLog "Fortschrittsanzeige nicht verfügbar: $($_.Exception.Message)" }
    $ksScrubTimer.Start()
})

$form.Add_Move({ try { if ($fOvTop.Visible -or $fOvBot.Visible) { Set-KsOverlayBounds } } catch { } })
$form.Add_Resize({ try { if ($fOvTop.Visible -or $fOvBot.Visible) { Set-KsOverlayBounds } } catch { } })

$form.Add_FormClosing({
    try { $fOvTop.Close(); $fOvBot.Close() } catch { }
    $ksScrubTimer.Stop()
    $script:KsPos.Run = $false
    try { if ($script:KsPosPs) { $script:KsPosPs.Stop(); $script:KsPosPs.Dispose() }; if ($script:KsPosRs) { $script:KsPosRs.Dispose() } } catch { }
    $timer.Stop()
    $ksHookTimer.Stop()
    if ($script:KsHookOk) { [KsKeyHook]::Stop() }
    if ($script:KsPl.Form -and -not $script:KsPl.Form.IsDisposed) { $script:KsPl.Form.Close() }
    Stop-KsMirror
    $script:Ks.Player = [string]$cmbPlayer.SelectedItem
    $script:Ks.LiveAuto = $chkLiveAuto.Checked
    if ($st.Connected) { Save-KsSettings }
    if ($script:KsMb.Form -and -not $script:KsMb.Form.IsDisposed) { $script:KsMb.Form.Close() }
})

[void]$form.ShowDialog()
'@

function Invoke-KodiSteuerung {
    try {
        $ksDir = Join-Path $env:APPDATA 'ProjectEarthLan'
        New-Item -Path $ksDir -ItemType Directory -Force | Out-Null
        $ksScriptPath = Join-Path $ksDir 'Kodi-Steuerung.ps1'
        # Bei jedem Start neu ablegen, damit das Begleit-Skript immer der aktuell im
        # Manager eingebetteten Version entspricht (z. B. nach einem Update des Managers).
        # Sprachkern (PelI18n) + Wörterbuch für das Begleitskript bereitstellen
        [System.IO.File]::WriteAllText((Join-Path $ksDir 'PelI18n.cs'), $script:PelI18nCode, (New-Object System.Text.UTF8Encoding($true)))
        [System.IO.File]::WriteAllText((Join-Path $ksDir 'PelI18n_en.txt'), $script:PelI18nDictEn, (New-Object System.Text.UTF8Encoding($true)))
        $ksText = $script:PelKodiSteuerungScript
        $ksAnchor = '[System.Windows.Forms.Application]::EnableVisualStyles()'
        $ksPos = $ksText.IndexOf($ksAnchor)
        if ($ksPos -ge 0) { $ksPos += $ksAnchor.Length; $ksText = $ksText.Substring(0, $ksPos) + "`r`n" + $script:PelKodiI18nBoot + $ksText.Substring($ksPos) }
        Set-Content -Path $ksScriptPath -Value $ksText -Encoding UTF8 -Force
        $started = $false
        try {
            Start-Process -FilePath 'powershell.exe' -ArgumentList "-NoProfile -ExecutionPolicy Bypass -STA -WindowStyle Hidden -File `"$ksScriptPath`"" -ErrorAction Stop | Out-Null
            $started = $true
        } catch { }
        if (-not $started) {
            throw "Konnte PowerShell nicht starten, um die Kodi-Steuerung zu oeffnen."
        }
    } catch {
        [PelI18n]::Show("Die Kodi-Steuerung konnte nicht gestartet werden:`n`n$($_.Exception.Message)`n`nStelle sicher, dass Kodi im Netzwerk laeuft und unter Einstellungen -> Dienste -> Steuerung die Option 'Steuerung ueber HTTP erlauben' aktiviert ist.", "Kodi Streaming", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
    }
}

#region ====== Intranet für LAN-Partys (Option 11) ======
# ------------------------------------------------------------------------------
# OPTION 11: INTRANET
# ------------------------------------------------------------------------------
# Eine eigene Seite für die LAN-Party, direkt aus dem Manager - ohne Webserver-Software,
# ohne fremde Dienste, ohne Schriften oder Skripte aus dem Internet.
#   - Ansehen:    findet Intranets anderer Manager im Heimnetz und in der P2P-Lobby
#                 (TCP 9931, /pel/info.json) und zeigt sie direkt im Fenster an.
#   - Baukasten:  Seite aus Blöcken zusammenstellen oder eine Vorlage nehmen und
#                 anpassen. Die Seite wird hier erzeugt (fertiges HTML) und vom
#                 eingebauten Server ausgeliefert, solange Option 11 offen ist.
#   - Einbetten:  Veranstalter mit eigenem Intranet tragen nur dessen Adresse ein -
#                 die Manager der Gäste zeigen dann genau diese Seite an.
# Sicherheit: Der Server nimmt nur Verbindungen aus Heimnetz, P2P-Netz (10.77.x.y) und
# von diesem PC an (Firewall-Regel UND Prüfung im Server). Gäste können nur lesen.
# Einzige Schreib-Aktion: Umfrage-Stimme bzw. Eintrag in eine Bestellliste, pro PC genau
# ein Eintrag je Block, Texte hart begrenzt. Alle Texte werden HTML-maskiert, es gibt
# kein eigenes JavaScript im Baukasten. Eingebettete Adressen müssen im lokalen Netz
# liegen (private IP oder lokaler Name wie "lan.local").
# Anzeige im Fenster: WebBrowser-Steuerelement von Windows (im .NET Framework enthalten,
# keine Zusatzsoftware). Die eigene Seite ist dafür bewusst einfach gebaut (IE11-tauglich).
# Moderne Veranstalter-Seiten sehen darin evtl. nicht perfekt aus - dafür gibt es den
# Button "Im Browser öffnen".
# ------------------------------------------------------------------------------
$script:PelIntranetDir          = 'C:\Project-Earth-Lan\intranet'
$script:PelIntranetConfigPath   = 'C:\Project-Earth-Lan\intranet\intranet.json'
$script:PelIntranetEntriesPath  = 'C:\Project-Earth-Lan\intranet\mitmachen.json'
$script:PelIntranetDownloadDir  = 'C:\Project-Earth-Lan\intranet\downloads'
$script:PelIntranetLogosDir     = 'C:\Project-Earth-Lan\intranet\logos'
# Eigene Speisen und Getränke der Orga zum Wiederverwenden (Fenster "Speisen & Getränke")
$script:PelIntranetSortimentPath = 'C:\Project-Earth-Lan\intranet\sortiment.json'
$script:PelIntranetDefaultPort  = 9931
$script:PelIntranetLastHtml     = ''
$script:PelIntranetLastEmbed    = ''

$script:PelIntranetCode = @'
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;

// Intranet-Server fuer Option 11 (Standard-Port TCP 9931). Liefert die fertige Seite aus,
// die PowerShell per SetContent uebergibt, dazu das Logo und die Dateien aus dem
// Download-Ordner (nur lesen, nur oberste Ordnerebene). Einzige Schreib-Aktion: Stimme in
// einer Umfrage bzw. Eintrag in einer Bestellliste - pro PC (IP) ein Eintrag je Block.
public static class PelIntranetServer
{
    static TcpListener _listener;
    static volatile bool _running;
    static int _port;
    static readonly object _lk = new object();
    static byte[] _page = new byte[0];
    static byte[] _pageEmbed = new byte[0];
    static byte[] _info = new byte[0];
    static string _dlDir = "";
    static string _logo = "";
    static string _header = "";
    static string _logosDir = "";
    static long _rev = 0;
    static long _requests = 0;
    // Block-Id -> Anzahl Antworten (Umfrage, 1-12), -1 (Bestellliste), -2 (Bestellung
    // mit Speisekarte) oder -3 (Sitzplan & Check-in)
    static Dictionary<string, int> _blocks = new Dictionary<string, int>();
    // Speisekarten-Bloecke: Artikelnamen, Preise (invariant, leer = ohne Preis), Bestellschluss
    static Dictionary<string, string[]> _menuNames = new Dictionary<string, string[]>();
    static Dictionary<string, decimal[]> _menuPrices = new Dictionary<string, decimal[]>();
    // Je Artikel: im Intranet bestellbar? (false = nur vor Ort an der Theke oder ausverkauft)
    static Dictionary<string, bool[]> _menuOnline = new Dictionary<string, bool[]>();
    static HashSet<string> _menuClosed = new HashSet<string>();
    static bool _menuEnglish = false;
    // Sitzplan-Bloecke (Art -3): gueltige Plaetze (ohne gesperrte), Platzwahl geschlossen
    static Dictionary<string, HashSet<string>> _seats = new Dictionary<string, HashSet<string>>();
    static HashSet<string> _seatClosed = new HashSet<string>();
    public const int MenuMaxQty = 20;
    public const int MenuMaxItemsPerOrder = 60;
    static readonly ConcurrentDictionary<string, ConcurrentDictionary<string, string>> _entries = new ConcurrentDictionary<string, ConcurrentDictionary<string, string>>();
    static readonly ConcurrentDictionary<string, long[]> _rate = new ConcurrentDictionary<string, long[]>();

    // Ereignisse fuer PowerShell: "SUBMIT|IP|Block", "DL|IP|Datei", bei Speisekarten zusaetzlich
    // "ORDER|IP|Block" (neu/geaendert) bzw. "OCANCEL|IP|Block" (vom Gast zurueckgezogen)
    public static readonly ConcurrentQueue<string> Events = new ConcurrentQueue<string>();

    public static bool IsRunning { get { return _running; } }
    public static int Port { get { return _port; } }
    public static long Revision { get { return Interlocked.Read(ref _rev); } }
    public static long Requests { get { return Interlocked.Read(ref _requests); } }

    public static void SetContent(string page, string pageEmbed, string infoJson, string dlDir, string logoPath, long rev)
    {
        lock (_lk)
        {
            _page = Encoding.UTF8.GetBytes(page ?? "");
            _pageEmbed = Encoding.UTF8.GetBytes(pageEmbed ?? (page ?? ""));
            _info = Encoding.UTF8.GetBytes(infoJson ?? "{}");
            _dlDir = dlDir ?? "";
            _logo = logoPath ?? "";
        }
        Interlocked.Exchange(ref _rev, rev);
    }

    // Kopfbild (bis 5 MB) und Ordner fuer den Block "Logos & Sponsoren" (je Bild bis 2 MB)
    public static void SetImages(string headerPath, string logosDir)
    {
        lock (_lk) { _header = headerPath ?? ""; _logosDir = logosDir ?? ""; }
    }

    static string ImageType(string ext)
    {
        ext = (ext ?? "").ToLowerInvariant();
        if (ext == ".png") return "image/png";
        if (ext == ".gif") return "image/gif";
        if (ext == ".jpg" || ext == ".jpeg") return "image/jpeg";
        return null;
    }

    static void ServeImage(Stream s, string fullPath, long max, bool headOnly)
    {
        FileInfo fi = string.IsNullOrEmpty(fullPath) ? null : new FileInfo(fullPath);
        string type = fi == null ? null : ImageType(fi.Extension);
        if (fi == null || !fi.Exists || type == null || fi.Length > max) { SendText(s, 404, "Not Found", "Kein Bild.", headOnly); return; }
        Send(s, 200, "OK", type, File.ReadAllBytes(fi.FullName), null, headOnly);
    }

    public static bool ValidId(string id)
    {
        if (string.IsNullOrEmpty(id) || id.Length > 16) return false;
        foreach (char c in id) if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))) return false;
        return true;
    }

    public static void SetBlocks(string[] defs)
    {
        Dictionary<string, int> d = new Dictionary<string, int>();
        if (defs != null)
        {
            foreach (string s in defs)
            {
                string[] p = (s ?? "").Split('|');
                int n;
                if (p.Length == 2 && ValidId(p[0]) && int.TryParse(p[1], out n) && n >= -3 && n <= 12 && n != 0) d[p[0]] = n;
            }
        }
        lock (_lk) { _blocks = d; }
    }

    // Speisekarte eines Blocks setzen (Namen und Preise in derselben Reihenfolge wie die
    // Formularfelder q0, q1, ...). Preise als invarianter Text ("7.50"), leer = ohne Preis.
    public static void SetMenu(string id, string[] names, string[] prices, bool closed, bool english)
    {
        SetMenu(id, names, prices, closed, english, null);
    }

    // online: je Artikel bestellbar (null = alle bestellbar, wie bisher)
    public static void SetMenu(string id, string[] names, string[] prices, bool closed, bool english, bool[] online)
    {
        if (!ValidId(id)) return;
        int n = names == null ? 0 : Math.Min(names.Length, 250);
        string[] nm = new string[n];
        decimal[] pr = new decimal[n];
        for (int i = 0; i < n; i++)
        {
            nm[i] = Clean(names[i], 60);
            decimal v;
            pr[i] = (prices != null && i < prices.Length && decimal.TryParse(prices[i], System.Globalization.NumberStyles.Number, System.Globalization.CultureInfo.InvariantCulture, out v) && v >= 0 && v < 10000) ? v : -1;
        }
        bool[] on = new bool[n];
        for (int i = 0; i < n; i++) on[i] = online == null || (i < online.Length && online[i]);
        lock (_lk)
        {
            _menuNames[id] = nm;
            _menuPrices[id] = pr;
            _menuOnline[id] = on;
            if (closed) _menuClosed.Add(id); else _menuClosed.Remove(id);
            _menuEnglish = english;
        }
    }

    // ---- Sitzplan & Check-in -----------------------------------------------------------
    // Eintrag: Name <TAB> Platz <TAB> Status (reserviert|eingecheckt) <TAB> ReserviertMs <TAB> EincheckMs
    public static void SetSeats(string id, string[] seats, bool closed, bool english)
    {
        if (!ValidId(id)) return;
        HashSet<string> h = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (seats != null) foreach (string x in seats) { string c = Clean(x, 12); if (c.Length > 0 && h.Count < 1500) h.Add(c); }
        lock (_lk)
        {
            _seats[id] = h;
            if (closed) _seatClosed.Add(id); else _seatClosed.Remove(id);
            _menuEnglish = english;
        }
    }

    static long NowMs() { return (DateTime.UtcNow.Ticks - 621355968000000000L) / 10000; }

    // Wer sitzt auf diesem Platz (ausser 'exceptKey')? null = frei
    static string SeatOwner(ConcurrentDictionary<string, string> b, string seat, string exceptKey)
    {
        foreach (KeyValuePair<string, string> kv in b)
        {
            if (kv.Key == exceptKey) continue;
            if (string.Equals(Field(kv.Value, 1), seat, StringComparison.OrdinalIgnoreCase)) return kv.Key;
        }
        return null;
    }

    // Orga: Gast eintragen oder aendern (key = IP oder "o:<id>"). Rueckgabe: Fehlertext oder null.
    public static string SetSeatEntry(string id, string key, string name, string seat, string status)
    {
        if (!ValidId(id)) return "Block ungueltig.";
        IPAddress a;
        if (string.IsNullOrEmpty(key) || (!IPAddress.TryParse(key, out a) && !(key.StartsWith("o:") && ValidId(key.Substring(2))))) return "Schluessel ungueltig.";
        if (status != "reserviert" && status != "eingecheckt") return "Status ungueltig.";
        HashSet<string> valid;
        lock (_lk) { _seats.TryGetValue(id, out valid); }
        name = Clean(name, 32);
        seat = Clean(seat, 12);
        if (name.Length == 0) return _menuEnglish ? "Please enter a name." : "Bitte einen Namen eintragen.";
        if (seat.Length > 0)
        {
            if (valid == null || !valid.Contains(seat)) return (_menuEnglish ? "Unknown seat: " : "Diesen Platz gibt es nicht: ") + seat;
        }
        ConcurrentDictionary<string, string> b = Bucket(id);
        lock (b)
        {
            if (seat.Length > 0)
            {
                string other = SeatOwner(b, seat, key);
                string ov;
                if (other != null) return (_menuEnglish ? "Seat already taken by " : "Platz ist schon vergeben an ") + (b.TryGetValue(other, out ov) ? Field(ov, 0) : other);
            }
            string old;
            b.TryGetValue(key, out old);
            string resMs = old != null && Field(old, 3).Length > 0 ? Field(old, 3) : NowMs().ToString();
            string inMs = status == "eingecheckt" ? (old != null && Field(old, 2) == "eingecheckt" && Field(old, 4).Length > 0 ? Field(old, 4) : NowMs().ToString()) : "";
            b[key] = name + "\t" + seat + "\t" + status + "\t" + resMs + "\t" + inMs;
        }
        return null;
    }

    public static bool RemoveEntry(string id, string key)
    {
        ConcurrentDictionary<string, string> b;
        string old;
        return _entries.TryGetValue(id ?? "", out b) && b.TryRemove(key ?? "", out old);
    }

    static string MySeatHtml(string id, string ip)
    {
        ConcurrentDictionary<string, string> b;
        string v;
        if (!_entries.TryGetValue(id ?? "", out b) || !b.TryGetValue(ip, out v)) return "";
        bool en = _menuEnglish;
        bool checkedIn = Field(v, 2) == "eingecheckt";
        string seat = Field(v, 1);
        string h = "<b>" + (en ? "Your seat: " : "Dein Platz: ") + WebUtility.HtmlEncode(seat.Length > 0 ? seat : (en ? "(none yet)" : "(noch keiner)")) + "</b> <span class=\"tag\">" +
                   (checkedIn ? (en ? "checked in" : "eingecheckt") : (en ? "reserved" : "reserviert")) + "</span>";
        h += "<div class=\"muted\">" + WebUtility.HtmlEncode(Field(v, 0)) + " - " + (checkedIn ? (en ? "Have fun! Seat changes via the organizers." : "Viel Spass! Platzwechsel bitte über die Orga.") : (en ? "Please check in at the organizer desk when you arrive." : "Bitte bei der Ankunft am Orga-Tisch einchecken.")) + "</div>";
        return h;
    }

    // Feld Nr. idx eines Speisekarten-Eintrags: Name, Platz, Notiz, Artikel, Status, Zeit
    public static string Field(string value, int idx)
    {
        string[] f = (value ?? "").Split('\t');
        return idx < f.Length ? f[idx] : "";
    }

    static readonly string[] _states = new string[] { "neu", "bestellt", "unterwegs", "da", "storniert" };

    // Orga setzt den Status einer Bestellung (neu, bestellt, unterwegs, da, storniert).
    public static bool SetEntryStatus(string id, string ip, string status)
    {
        if (Array.IndexOf(_states, status) < 0) return false;
        ConcurrentDictionary<string, string> b;
        if (!_entries.TryGetValue(id ?? "", out b)) return false;
        string old;
        if (!b.TryGetValue(ip ?? "", out old)) return false;
        string[] f = old.Split('\t');
        if (f.Length < 6) return false;
        f[4] = status;
        b[ip] = string.Join("\t", f);
        return true;
    }

    static string StateText(string st, bool en)
    {
        switch (st)
        {
            case "bestellt": return en ? "ordered" : "bestellt";
            case "unterwegs": return en ? "on the way" : "unterwegs";
            case "da": return en ? "ready for pick-up" : "abholbereit";
            case "storniert": return en ? "cancelled" : "storniert";
            default: return en ? "received" : "eingegangen";
        }
    }

    // "Deine Bestellung" fuer den anfragenden PC als kleines, maskiertes HTML-Stueck
    static string MyOrderHtml(string id, string ip)
    {
        ConcurrentDictionary<string, string> b;
        string v;
        if (!_entries.TryGetValue(id ?? "", out b) || !b.TryGetValue(ip, out v)) return "";
        string[] nm; decimal[] pr; bool en;
        lock (_lk) { _menuNames.TryGetValue(id, out nm); _menuPrices.TryGetValue(id, out pr); en = _menuEnglish; }
        if (nm == null) return "";
        System.Globalization.CultureInfo ci = System.Globalization.CultureInfo.GetCultureInfo(en ? "en-GB" : "de-DE");
        StringBuilder sb = new StringBuilder();
        decimal sum = 0; bool anyPrice = false;
        foreach (string part in Field(v, 3).Split(';'))
        {
            string[] iq = part.Split(':');
            int i, q;
            if (iq.Length != 2 || !int.TryParse(iq[0], out i) || !int.TryParse(iq[1], out q) || i < 0 || i >= nm.Length) continue;
            if (sb.Length > 0) sb.Append(", ");
            sb.Append(q).Append("x ").Append(WebUtility.HtmlEncode(nm[i]));
            if (pr != null && i < pr.Length && pr[i] >= 0) { sum += pr[i] * q; anyPrice = true; }
        }
        string st = Field(v, 4);
        string h = "<b>" + (en ? "Your order" : "Deine Bestellung") + "</b> <span class=\"tag\">" + WebUtility.HtmlEncode(StateText(st, en)) + "</span><div>" + sb.ToString() + "</div>";
        if (anyPrice) h += "<div class=\"muted\">" + (en ? "Total: " : "Summe: ") + WebUtility.HtmlEncode(sum.ToString("N2", ci)) + " &euro;</div>";
        if (st == "neu") h += "<div class=\"muted\">" + (en ? "You can still change it: just order again, or set everything to 0 to withdraw it." : "Du kannst sie noch ändern: einfach neu bestellen - alles auf 0 = zurückziehen.") + "</div>";
        return h;
    }

    // Kleine Antwortseite fuer abgelehnte Bestellungen (mit Link zurueck)
    static void SendNotice(Stream s, int code, string reason, string msg, string back)
    {
        string h = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Project Earth LAN</title><style>body{background:#191919;color:#e8e8e8;font-family:Segoe UI,Tahoma,Arial,sans-serif;padding:40px}a{color:#6cb6ff}</style></head><body><p>" +
                   WebUtility.HtmlEncode(msg) + "</p><p><a href=\"" + back + "\">" + (_menuEnglish ? "Back" : "Zur&uuml;ck") + "</a></p></body></html>";
        Send(s, code, reason, "text/html; charset=utf-8", Encoding.UTF8.GetBytes(h), null, false);
    }

    static string Clean(string s, int max)
    {
        if (s == null) return "";
        StringBuilder sb = new StringBuilder();
        foreach (char c in s)
        {
            if (sb.Length >= max) break;
            sb.Append(char.IsControl(c) ? ' ' : c);
        }
        return sb.ToString().Trim();
    }

    static ConcurrentDictionary<string, string> Bucket(string id)
    {
        return _entries.GetOrAdd(id, delegate(string k) { return new ConcurrentDictionary<string, string>(); });
    }

    public static void SetEntries(string id, string[] lines)
    {
        if (!ValidId(id)) return;
        ConcurrentDictionary<string, string> b = Bucket(id);
        b.Clear();
        if (lines == null) return;
        foreach (string ln in lines)
        {
            if (b.Count >= 500) break;
            string l = ln ?? "";
            int p = l.IndexOf('\t');
            if (p <= 0) continue;
            string ip = l.Substring(0, p);
            IPAddress a;
            // Schluessel = IP des Gast-PCs, bei von der Orga angelegten Gaesten "o:<id>"
            if (!IPAddress.TryParse(ip, out a) && !(ip.StartsWith("o:") && ValidId(ip.Substring(2)))) continue;
            b[ip] = l.Substring(p + 1);
        }
    }

    public static string[] GetEntries(string id)
    {
        List<string> l = new List<string>();
        ConcurrentDictionary<string, string> b;
        if (_entries.TryGetValue(id ?? "", out b)) foreach (KeyValuePair<string, string> kv in b) l.Add(kv.Key + "\t" + kv.Value);
        l.Sort(StringComparer.Ordinal);
        return l.ToArray();
    }

    public static void ClearEntries(string id)
    {
        ConcurrentDictionary<string, string> b;
        if (_entries.TryGetValue(id ?? "", out b)) b.Clear();
    }

    public static void Start(int port)
    {
        if (_running) Stop();
        TcpListener l = new TcpListener(IPAddress.Any, port);
        l.Start(64);
        _listener = l;
        _port = port;
        _running = true;
        Thread t = new Thread(AcceptLoop);
        t.IsBackground = true;
        t.Name = "PEL-Intranet";
        t.Start(l);
    }

    public static void Stop()
    {
        _running = false;
        TcpListener l = _listener;
        _listener = null;
        if (l != null) { try { l.Stop(); } catch { } }
    }

    static void AcceptLoop(object o)
    {
        TcpListener l = (TcpListener)o;
        while (_running && ReferenceEquals(_listener, l))
        {
            TcpClient c = null;
            try { c = l.AcceptTcpClient(); }
            catch { if (!_running || !ReferenceEquals(_listener, l)) break; Thread.Sleep(100); continue; }
            ThreadPool.QueueUserWorkItem(Handle, c);
        }
    }

    // Nur Heimnetz, P2P-Netz (10.77.x.y) und dieser PC - nie das Internet.
    public static bool IsAllowed(IPAddress a)
    {
        if (a == null) return false;
        if (a.IsIPv4MappedToIPv6) a = a.MapToIPv4();
        if (IPAddress.IsLoopback(a)) return true;
        if (a.AddressFamily != AddressFamily.InterNetwork) return false;
        byte[] b = a.GetAddressBytes();
        if (b[0] == 10) return true;
        if (b[0] == 172 && b[1] >= 16 && b[1] <= 31) return true;
        if (b[0] == 192 && b[1] == 168) return true;
        if (b[0] == 169 && b[1] == 254) return true;
        return false;
    }

    static string ReadHead(Stream s)
    {
        MemoryStream ms = new MemoryStream();
        int state = 0;
        while (ms.Length < 16384)
        {
            int b = s.ReadByte();
            if (b < 0) return null;
            ms.WriteByte((byte)b);
            if ((state == 0 || state == 2) && b == 13) state++;
            else if ((state == 1 || state == 3) && b == 10) { state++; if (state == 4) break; }
            else state = (b == 13) ? 1 : 0;
        }
        if (state != 4) return null;
        return Encoding.UTF8.GetString(ms.ToArray());
    }

    static void Send(Stream s, int code, string reason, string type, byte[] body, string extra, bool headOnly)
    {
        if (body == null) body = new byte[0];
        string h = "HTTP/1.1 " + code + " " + reason + "\r\n" +
                   "Content-Type: " + type + "\r\n" +
                   "Content-Length: " + body.Length + "\r\n" +
                   "Cache-Control: no-store\r\n" +
                   "X-Content-Type-Options: nosniff\r\n" +
                   "Connection: close\r\n" +
                   "Server: PEL-Intranet\r\n" + (extra ?? "") + "\r\n";
        byte[] hb = Encoding.ASCII.GetBytes(h);
        s.Write(hb, 0, hb.Length);
        if (!headOnly && body.Length > 0) s.Write(body, 0, body.Length);
        s.Flush();
    }

    static void SendText(Stream s, int code, string reason, string text, bool headOnly)
    {
        Send(s, code, reason, "text/plain; charset=utf-8", Encoding.UTF8.GetBytes(text ?? ""), null, headOnly);
    }

    static bool RateOk(string ip)
    {
        long now = DateTime.UtcNow.Ticks;
        long[] r = _rate.GetOrAdd(ip, delegate(string k) { return new long[2]; });
        lock (r)
        {
            if (now - r[0] > TimeSpan.TicksPerMinute) { r[0] = now; r[1] = 0; }
            r[1]++;
            return r[1] <= 20;
        }
    }

    static Dictionary<string, string> ParseForm(string body)
    {
        Dictionary<string, string> d = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (string part in (body ?? "").Split('&'))
        {
            int p = part.IndexOf('=');
            // bis 250 Artikel einer Speisekarte (q0..q249) plus Name, Platz, Notiz
            if (p <= 0 || d.Count >= 300) continue;
            try
            {
                string k = Uri.UnescapeDataString(part.Substring(0, p).Replace('+', ' '));
                string v = Uri.UnescapeDataString(part.Substring(p + 1).Replace('+', ' '));
                d[k] = v;
            }
            catch { }
        }
        return d;
    }

    static void Handle(object o)
    {
        TcpClient c = (TcpClient)o;
        try
        {
            using (c)
            {
                IPEndPoint ep = c.Client.RemoteEndPoint as IPEndPoint;
                IPAddress addr = ep != null ? ep.Address : null;
                if (addr != null && addr.IsIPv4MappedToIPv6) addr = addr.MapToIPv4();
                if (!IsAllowed(addr)) return;
                string ip = addr.ToString();
                c.ReceiveTimeout = 15000;
                c.SendTimeout = 120000;
                c.NoDelay = true;
                NetworkStream ns = c.GetStream();
                string head = ReadHead(ns);
                if (head == null) return;
                Interlocked.Increment(ref _requests);

                string[] lines = head.Split(new string[] { "\r\n" }, StringSplitOptions.None);
                string[] rl = lines[0].Split(' ');
                if (rl.Length < 3) { SendText(ns, 400, "Bad Request", "Bad Request", false); return; }
                string method = rl[0].ToUpperInvariant();
                string target = rl[1];
                bool headOnly = method == "HEAD";
                Dictionary<string, string> hdr = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 1; i < lines.Length; i++)
                {
                    int p = lines[i].IndexOf(':');
                    if (p > 0) hdr[lines[i].Substring(0, p).Trim()] = lines[i].Substring(p + 1).Trim();
                }
                string path = target;
                string query = "";
                int hs = path.IndexOf('#');
                if (hs >= 0) path = path.Substring(0, hs);
                int q = path.IndexOf('?');
                if (q >= 0) { query = path.Substring(q + 1); path = path.Substring(0, q); }

                if (method == "POST")
                {
                    if (path == "/pel/submit") HandleSubmit(ns, hdr, ip);
                    else SendText(ns, 404, "Not Found", "Nicht gefunden.", false);
                    return;
                }
                if (method != "GET" && !headOnly)
                {
                    Send(ns, 405, "Method Not Allowed", "text/plain; charset=utf-8", Encoding.UTF8.GetBytes("Nicht erlaubt."), "Allow: GET, HEAD, POST\r\n", false);
                    return;
                }
                if (path == "/" || path == "/index.html")
                {
                    bool embed = ("&" + query + "&").IndexOf("&embed=1&", StringComparison.Ordinal) >= 0;
                    byte[] b;
                    lock (_lk) { b = embed ? _pageEmbed : _page; }
                    Send(ns, 200, "OK", "text/html; charset=utf-8", b, null, headOnly);
                    return;
                }
                if (path == "/pel/info.json")
                {
                    byte[] b;
                    lock (_lk) { b = _info; }
                    Send(ns, 200, "OK", "application/json; charset=utf-8", b, null, headOnly);
                    return;
                }
                if (path == "/pel/rev") { SendText(ns, 200, "OK", Revision.ToString(), headOnly); return; }
                if (path == "/pel/my")
                {
                    string mid = "";
                    foreach (string qp in query.Split('&')) { if (qp.StartsWith("b=", StringComparison.Ordinal)) mid = qp.Substring(2); }
                    int mk = 0;
                    bool mknown;
                    lock (_lk) { mknown = ValidId(mid) && _blocks.TryGetValue(mid, out mk); }
                    string frag = !mknown ? "" : (mk == -3 ? MySeatHtml(mid, ip) : MyOrderHtml(mid, ip));
                    Send(ns, 200, "OK", "text/html; charset=utf-8", Encoding.UTF8.GetBytes(frag), null, headOnly);
                    return;
                }
                if (path == "/pel/logo")
                {
                    string lp;
                    lock (_lk) { lp = _logo; }
                    FileInfo fi = string.IsNullOrEmpty(lp) ? null : new FileInfo(lp);
                    if (fi == null || !fi.Exists || fi.Length > 2097152) { SendText(ns, 404, "Not Found", "Kein Logo.", headOnly); return; }
                    string ext = fi.Extension.ToLowerInvariant();
                    string type = ext == ".png" ? "image/png" : (ext == ".gif" ? "image/gif" : "image/jpeg");
                    Send(ns, 200, "OK", type, File.ReadAllBytes(fi.FullName), null, headOnly);
                    return;
                }
                if (path == "/pel/header")
                {
                    string hp;
                    lock (_lk) { hp = _header; }
                    ServeImage(ns, hp, 5242880, headOnly);
                    return;
                }
                if (path.StartsWith("/pel/img/", StringComparison.Ordinal))
                {
                    // Nur Bilder direkt im Logo-Ordner - kein Pfad, keine versteckten Dateien
                    string nm;
                    try { nm = Uri.UnescapeDataString(path.Substring(9)); } catch { SendText(ns, 400, "Bad Request", "Bad Request", headOnly); return; }
                    string ld;
                    lock (_lk) { ld = _logosDir; }
                    if (string.IsNullOrEmpty(ld) || nm.Length == 0 || nm.Length > 120 || nm.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0 || nm.StartsWith("."))
                    { SendText(ns, 404, "Not Found", "Kein Bild.", headOnly); return; }
                    string root = Path.GetFullPath(ld).TrimEnd('\\');
                    FileInfo lf = new FileInfo(Path.Combine(root, nm));
                    if (!lf.Exists || (lf.Attributes & (FileAttributes.Hidden | FileAttributes.System)) != 0 ||
                        !string.Equals((lf.DirectoryName ?? "").TrimEnd('\\'), root, StringComparison.OrdinalIgnoreCase))
                    { SendText(ns, 404, "Not Found", "Kein Bild.", headOnly); return; }
                    ServeImage(ns, lf.FullName, 2097152, headOnly);
                    return;
                }
                if (path.StartsWith("/dl/", StringComparison.Ordinal)) { ServeDownload(ns, path.Substring(4), ip, headOnly); return; }
                SendText(ns, 404, "Not Found", "Nicht gefunden.", headOnly);
            }
        }
        catch { }
    }

    static void ServeDownload(NetworkStream ns, string enc, string ip, bool headOnly)
    {
        string name;
        try { name = Uri.UnescapeDataString(enc); } catch { SendText(ns, 400, "Bad Request", "Bad Request", headOnly); return; }
        string dir;
        lock (_lk) { dir = _dlDir; }
        if (string.IsNullOrEmpty(dir) || name.Length == 0 || name.Length > 200 || name == "." || name == ".." ||
            name.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0)
        { SendText(ns, 404, "Not Found", "Nicht gefunden.", headOnly); return; }
        string root = Path.GetFullPath(dir).TrimEnd('\\');
        FileInfo fi = new FileInfo(Path.Combine(root, name));
        if (!fi.Exists || (fi.Attributes & (FileAttributes.Hidden | FileAttributes.System)) != 0 ||
            !string.Equals((fi.DirectoryName ?? "").TrimEnd('\\'), root, StringComparison.OrdinalIgnoreCase))
        { SendText(ns, 404, "Not Found", "Nicht gefunden.", headOnly); return; }
        long len = fi.Length;
        string fh = "HTTP/1.1 200 OK\r\n" +
                    "Content-Type: application/octet-stream\r\n" +
                    "Content-Length: " + len + "\r\n" +
                    "Content-Disposition: attachment; filename*=UTF-8''" + Uri.EscapeDataString(fi.Name) + "\r\n" +
                    "X-Content-Type-Options: nosniff\r\n" +
                    "Connection: close\r\n" +
                    "Server: PEL-Intranet\r\n\r\n";
        byte[] fhb = Encoding.ASCII.GetBytes(fh);
        ns.Write(fhb, 0, fhb.Length);
        if (headOnly) { ns.Flush(); return; }
        using (FileStream fs = new FileStream(fi.FullName, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, 262144))
        {
            byte[] buf = new byte[262144];
            int r;
            while (_running && (r = fs.Read(buf, 0, buf.Length)) > 0) ns.Write(buf, 0, r);
        }
        ns.Flush();
        Events.Enqueue("DL|" + ip + "|" + fi.Name);
        string dummy;
        while (Events.Count > 500 && Events.TryDequeue(out dummy)) { }
    }

    static void HandleSubmit(NetworkStream ns, Dictionary<string, string> hdr, string ip)
    {
        string cl;
        int len = 0;
        if (!hdr.TryGetValue("Content-Length", out cl) || !int.TryParse(cl, out len) || len < 0 || len > 16384)
        { SendText(ns, 413, "Payload Too Large", "Zu gross.", false); return; }
        byte[] buf = new byte[len];
        int got = 0;
        while (got < len) { int r = ns.Read(buf, got, len - got); if (r <= 0) break; got += r; }
        if (got < len) return;
        if (!RateOk(ip)) { SendText(ns, 429, "Too Many Requests", "Bitte kurz warten und dann erneut versuchen.", false); return; }
        Dictionary<string, string> f = ParseForm(Encoding.UTF8.GetString(buf));
        string id;
        f.TryGetValue("b", out id);
        int kind = 0;
        bool known;
        lock (_lk) { known = id != null && _blocks.TryGetValue(id, out kind); }
        if (!known) { SendText(ns, 404, "Not Found", "Diesen Block gibt es nicht (mehr).", false); return; }
        ConcurrentDictionary<string, string> b = Bucket(id);
        if (b.Count >= 500 && !b.ContainsKey(ip)) { SendText(ns, 429, "Too Many Requests", "Die Liste ist voll.", false); return; }
        string orderEvent = null;
        string eflag;
        f.TryGetValue("e", out eflag);
        string back = (eflag == "1" ? "/?embed=1" : "/") + "#b-" + id;
        if (kind == -3)
        {
            HashSet<string> valid; bool closed3;
            lock (_lk) { _seats.TryGetValue(id, out valid); closed3 = _seatClosed.Contains(id); }
            bool en3 = _menuEnglish;
            string n3, s3;
            f.TryGetValue("n", out n3);
            f.TryGetValue("s", out s3);
            n3 = Clean(n3, 32);
            s3 = Clean(s3, 12);
            string old3;
            b.TryGetValue(ip, out old3);
            if (old3 != null && Field(old3, 2) == "eingecheckt")
            { SendNotice(ns, 409, "Conflict", en3 ? "You are already checked in - please ask the organizers to change your seat." : "Du bist schon eingecheckt - Platzwechsel bitte über die Orga.", back); return; }
            if (s3.Length == 0)
            {
                // "kein Platz" = eigene Reservierung aufheben
                if (old3 != null) { string gone3; b.TryRemove(ip, out gone3); orderEvent = "SEAT"; }
            }
            else
            {
                if (closed3) { SendNotice(ns, 403, "Forbidden", en3 ? "Seat selection is closed - please ask the organizers." : "Die Platzwahl ist geschlossen - bitte an die Orga wenden.", back); return; }
                if (valid == null || !valid.Contains(s3)) { SendNotice(ns, 400, "Bad Request", en3 ? "This seat does not exist." : "Diesen Platz gibt es nicht.", back); return; }
                if (n3.Length == 0) { SendNotice(ns, 400, "Bad Request", en3 ? "Please enter your name." : "Bitte deinen Namen eintragen.", back); return; }
                // Pruefen und Eintragen in einem Schritt - zwei Gaeste, die gleichzeitig
                // denselben Platz waehlen, bekommen ihn nicht beide
                bool taken3;
                lock (b)
                {
                    taken3 = SeatOwner(b, s3, ip) != null;
                    if (!taken3)
                    {
                        string res3 = old3 != null && Field(old3, 3).Length > 0 ? Field(old3, 3) : NowMs().ToString();
                        b[ip] = n3 + "\t" + s3 + "\treserviert\t" + res3 + "\t";
                    }
                }
                if (taken3) { SendNotice(ns, 409, "Conflict", en3 ? "Sorry, this seat was just taken - please choose another one." : "Dieser Platz ist leider gerade vergeben worden - bitte einen anderen wählen.", back); return; }
                orderEvent = "SEAT";
            }
        }
        else if (kind == -2)
        {
            string[] nm; bool[] onl; bool closed;
            lock (_lk) { _menuNames.TryGetValue(id, out nm); _menuOnline.TryGetValue(id, out onl); closed = _menuClosed.Contains(id); }
            bool en = _menuEnglish;
            if (nm == null || nm.Length == 0) { SendNotice(ns, 404, "Not Found", en ? "This menu has no items (yet)." : "Diese Speisekarte hat (noch) keine Artikel.", back); return; }
            StringBuilder items = new StringBuilder();
            int total = 0;
            for (int i = 0; i < nm.Length; i++)
            {
                string qv; int qn;
                if (!f.TryGetValue("q" + i, out qv) || !int.TryParse(qv, out qn) || qn <= 0) continue;
                // Nur vor Ort / ausverkauft: nicht ueber das Intranet bestellbar
                if (onl != null && i < onl.Length && !onl[i]) continue;
                if (qn > MenuMaxQty) qn = MenuMaxQty;
                if (items.Length > 0) items.Append(';');
                items.Append(i).Append(':').Append(qn);
                total += qn;
            }
            if (total > MenuMaxItemsPerOrder) { SendNotice(ns, 400, "Bad Request", en ? "Too many items in one order (max. 60)." : "Zu viele Artikel in einer Bestellung (höchstens 60).", back); return; }
            string old;
            b.TryGetValue(ip, out old);
            string oldState = old != null ? Field(old, 4) : "";
            // Hat die Orga schon bestellt, darf der Gast nichts mehr aendern - sonst stimmt die
            // Sammelbestellung nicht mehr mit dem ueberein, was geliefert wird.
            if (old != null && oldState != "neu" && oldState != "storniert")
            { SendNotice(ns, 409, "Conflict", en ? "Your order is already being handled (" + StateText(oldState, true) + "). Please ask the organizers for changes." : "Deine Bestellung wird schon bearbeitet (" + StateText(oldState, false) + "). Änderungen bitte direkt bei der Orga.", back); return; }
            if (total == 0)
            {
                if (old != null) { string gone; b.TryRemove(ip, out gone); orderEvent = "OCANCEL"; }
            }
            else
            {
                if (closed) { SendNotice(ns, 403, "Forbidden", en ? "Orders are closed - the organizers are not taking orders right now." : "Bestellschluss - die Orga nimmt gerade keine Bestellungen an.", back); return; }
                string n, seat, note;
                f.TryGetValue("n", out n);
                f.TryGetValue("s", out seat);
                f.TryGetValue("c", out note);
                n = Clean(n, 32);
                if (n.Length == 0) { SendNotice(ns, 400, "Bad Request", en ? "Please enter your name." : "Bitte deinen Namen eintragen.", back); return; }
                long ms = (DateTime.UtcNow.Ticks - 621355968000000000L) / 10000;
                b[ip] = n + "\t" + Clean(seat, 16) + "\t" + Clean(note, 120) + "\t" + items.ToString() + "\tneu\t" + ms;
                orderEvent = "ORDER";
            }
        }
        else if (kind > 0)
        {
            string v;
            int choice;
            if (!f.TryGetValue("v", out v) || !int.TryParse(v, out choice) || choice < 0 || choice >= kind)
            { SendText(ns, 400, "Bad Request", "Bitte eine Antwort auswaehlen.", false); return; }
            b[ip] = choice.ToString();
        }
        else
        {
            string n, t;
            f.TryGetValue("n", out n);
            f.TryGetValue("t", out t);
            n = Clean(n, 32);
            t = Clean(t, 120);
            if (n.Length == 0 && t.Length == 0) { string old; b.TryRemove(ip, out old); }
            else { if (n.Length == 0) n = "?"; b[ip] = n + "\t" + t; }
        }
        Events.Enqueue("SUBMIT|" + ip + "|" + id);
        if (orderEvent != null) Events.Enqueue(orderEvent + "|" + ip + "|" + id);
        string dummy;
        while (Events.Count > 500 && Events.TryDequeue(out dummy)) { }
        // PowerShell baut die Seite im Sekundentakt neu. Kurz warten, damit der Gast
        // seinen Eintrag nach dem Absenden direkt sieht.
        Thread.Sleep(1500);
        Send(ns, 303, "See Other", "text/plain; charset=utf-8", new byte[0], "Location: " + back + "\r\n", false);
    }
}

// Sucht Intranets anderer Manager: TCP-Verbindung auf den Port, dann /pel/info.json.
// Mehrere Adressen parallel (begrenzt), jede mit kurzem Zeitlimit - das Fenster bleibt
// dabei bedienbar, PowerShell holt die Treffer per Timer aus "Found" ab.
public class PelIntranetScanner
{
    public string[] Ips = new string[0];
    public int Port = 9931;
    public int TimeoutMs = 400;
    public readonly ConcurrentQueue<string> Found = new ConcurrentQueue<string>();
    public volatile bool Finished;
    public volatile bool Cancel;
    public int Done;
    public int Total;
    int _next = -1;

    public void Start()
    {
        Total = Ips.Length;
        Thread t = new Thread(Run);
        t.IsBackground = true;
        t.Name = "PEL-IntranetScan";
        t.Start();
    }

    void Run()
    {
        try
        {
            int n = Math.Max(1, Math.Min(48, Total));
            Thread[] ws = new Thread[n];
            for (int i = 0; i < n; i++)
            {
                ws[i] = new Thread(Worker);
                ws[i].IsBackground = true;
                ws[i].Start();
            }
            foreach (Thread w in ws) w.Join();
        }
        catch { }
        Finished = true;
    }

    void Worker()
    {
        while (!Cancel)
        {
            int i = Interlocked.Increment(ref _next);
            if (i >= Ips.Length) break;
            Probe(Ips[i]);
            Interlocked.Increment(ref Done);
        }
    }

    void Probe(string ip)
    {
        try
        {
            using (TcpClient c = new TcpClient())
            {
                IAsyncResult ar = c.BeginConnect(ip, Port, null, null);
                if (!ar.AsyncWaitHandle.WaitOne(TimeoutMs)) return;
                c.EndConnect(ar);
                c.ReceiveTimeout = 2500;
                c.SendTimeout = 2500;
                NetworkStream ns = c.GetStream();
                byte[] req = Encoding.ASCII.GetBytes("GET /pel/info.json HTTP/1.1\r\nHost: " + ip + "\r\nConnection: close\r\n\r\n");
                ns.Write(req, 0, req.Length);
                MemoryStream ms = new MemoryStream();
                byte[] buf = new byte[4096];
                int r;
                while (ms.Length < 32768 && (r = ns.Read(buf, 0, buf.Length)) > 0) ms.Write(buf, 0, r);
                string s = Encoding.UTF8.GetString(ms.ToArray());
                int p = s.IndexOf("\r\n\r\n", StringComparison.Ordinal);
                if (p < 0 || s.IndexOf(" 200 ", StringComparison.Ordinal) < 0 || s.IndexOf(" 200 ", StringComparison.Ordinal) > p) return;
                string body = s.Substring(p + 4);
                if (body.IndexOf("\"PelIntranet\"", StringComparison.Ordinal) < 0) return;
                Found.Enqueue(ip + "\t" + body);
            }
        }
        catch { }
    }
}
'@

function Initialize-PelIntranetTypes {
    if (-not ('PelIntranetServer' -as [type])) { Add-Type -TypeDefinition $script:PelIntranetCode -Language CSharp }
}

# ---- Blöcke und Vorlagen ----------------------------------------------------------------
# Key = interner Name (steht in intranet.json), Text = was im Feld "Inhalt" steht.
function Get-PelIntranetBlockTypes {
    return @(
        [pscustomobject]@{ Key = 'news';      Name = (Get-PelText 'News' 'News');                              Hint = (Get-PelText 'Eine Meldung pro Zeile: Überschrift | Text' 'One item per line: headline | text') }
        [pscustomobject]@{ Key = 'schedule';  Name = (Get-PelText 'Zeitplan' 'Schedule');                      Hint = (Get-PelText 'Eine Zeile pro Programmpunkt: Uhrzeit | Programmpunkt' 'One line per item: time | what happens') }
        [pscustomobject]@{ Key = 'servers';   Name = (Get-PelText 'Spiele-Server' 'Game servers');             Hint = (Get-PelText 'Eine Zeile pro Server: Spiel | IP:Port  (im Manager erscheint dann "Mitspielen")' 'One line per server: game | IP:port  (the manager then shows "Join")') }
        [pscustomobject]@{ Key = 'events';    Name = (Get-PelText 'Spieleabende (live)' 'Game nights (live)'); Hint = (Get-PelText 'Zeigt automatisch die geplanten Spieleabende aus dem Spieleabend-Planer. Inhalt: optionaler Einleitungstext.' 'Automatically shows the planned game nights from the game night planner. Content: optional intro text.') }
        [pscustomobject]@{ Key = 'tourney';   Name = (Get-PelText 'Turnier (live)' 'Tournament (live)');       Hint = (Get-PelText 'Zeigt automatisch ein Turnier aus Option 4 (Turnierbaum oder Tabelle). Inhalt: Name des Turniers - leer = das aktuellste.' 'Automatically shows a tournament from option 4 (bracket or table). Content: tournament name - empty = the latest one.') }
        [pscustomobject]@{ Key = 'results';   Name = (Get-PelText 'Ergebnisse (live)' 'Results (live)');       Hint = (Get-PelText 'Zeigt automatisch die letzten bestätigten Ergebnisse aus Option 4 (Matchmaking). Inhalt: optionaler Einleitungstext.' 'Automatically shows the latest confirmed results from option 4 (matchmaking). Content: optional intro text.') }
        [pscustomobject]@{ Key = 'downloads'; Name = (Get-PelText 'Downloads' 'Downloads');                    Hint = (Get-PelText 'Listet alle Dateien aus dem Download-Ordner (Einstellungen -> Ordner öffnen). Inhalt: optionaler Einleitungstext.' 'Lists all files in the download folder (settings -> open folder). Content: optional intro text.') }
        [pscustomobject]@{ Key = 'rules';     Name = (Get-PelText 'Regeln' 'Rules');                           Hint = (Get-PelText 'Eine Regel pro Zeile.' 'One rule per line.') }
        [pscustomobject]@{ Key = 'seatmap';   Name = (Get-PelText 'Sitzplan & Check-in' 'Seat map & check-in');   Hint = (Get-PelText 'Eine Zeile pro Reihe: Reihe | Plätze, z. B. "A | 1-12" oder "C | 1-6, -, 7-12" (- = Gang). Gesperrt: A1, B5. Info: Hinweis. Gäste wählen ihren Platz, die Orga checkt sie ein.' 'One line per row: row | seats, e.g. "A | 1-12" or "C | 1-6, -, 7-12" (- = aisle). Gesperrt: A1, B5 (blocked). Info: note. Guests pick their seat, the organizers check them in.') }
        [pscustomobject]@{ Key = 'seating';   Name = (Get-PelText 'Sitzplan' 'Seating plan');                  Hint = (Get-PelText 'Eine Zeile pro Platz: Platz | Name' 'One line per seat: seat | name') }
        [pscustomobject]@{ Key = 'poll';      Name = (Get-PelText 'Umfrage' 'Poll');                           Hint = (Get-PelText 'Titel = Frage. Eine Antwort pro Zeile (höchstens 12). Jeder PC hat eine Stimme und kann sie ändern.' 'Title = question. One answer per line (max. 12). Every PC has one vote and can change it.') }
        [pscustomobject]@{ Key = 'menu';      Name = (Get-PelText 'Bestellung mit Speisekarte' 'Orders with menu');  Hint = (Get-PelText '[Kategorie], darunter: Artikel | Preis | Beschreibung | Optionen (eigen, vor Ort, ausverkauft). Info: Hinweis. Link: Lieferdienst | Telefon | https://... Orga: IPs der Orga-PCs. Bequemer: Button "Speisen & Getränke".' '[Category], below it: item | price | description | options (own, on site, sold out). Info: note. Link: delivery service | phone | https://... Orga: IPs of organizer PCs. Easier: button "Food & drinks".') }
        [pscustomobject]@{ Key = 'prices';    Name = (Get-PelText 'Preisliste' 'Price list');                  Hint = (Get-PelText '[Kategorie], darunter: Artikel | Preis | Hinweis. Preis frei wählbar (7,50 = mit Währung, oder Text wie "frei" / "5 € pro Tag"). Währung: CHF (optional, Standard €). Info: Hinweis für Gäste.' 'Own prices set by the organizers. [Category], below it: item | price | note. Price is free (7.50 = shown with currency, or text like "free" / "5 per day"). Currency: CHF (optional, default EUR). Info: note for guests.') }
        [pscustomobject]@{ Key = 'orders';    Name = (Get-PelText 'Bestellliste (z. B. Pizza)' 'Order list (e.g. pizza)'); Hint = (Get-PelText 'Inhalt = Hinweis für die Gäste (z. B. "Bestellung bis 22 Uhr"). Jeder PC hat einen Eintrag und kann ihn ändern.' 'Content = note for the guests (e.g. "orders until 10 pm"). Every PC has one entry and can change it.') }
        [pscustomobject]@{ Key = 'logos';     Name = (Get-PelText 'Logos & Sponsoren' 'Logos & sponsors');   Hint = (Get-PelText 'Zeigt alle Bilder aus dem Logo-Ordner ("Bilder hinzufügen"). Optional eine Zeile pro Bild: Dateiname | Name | https://... (Link).' 'Shows all images from the logo folder ("Add images"). Optional one line per image: file name | name | https://... (link).') }
        [pscustomobject]@{ Key = 'contact';   Name = (Get-PelText 'Orga-Kontakt' 'Organizer contact');         Hint = (Get-PelText 'Freier Text, eine Angabe pro Zeile.' 'Free text, one line per detail.') }
        [pscustomobject]@{ Key = 'text';      Name = (Get-PelText 'Freier Text' 'Free text');                  Hint = (Get-PelText 'Freier Text. Leerzeile = neuer Absatz.' 'Free text. Empty line = new paragraph.') }
    )
}

function Get-PelIntranetBlockType([string]$Key) {
    return (Get-PelIntranetBlockTypes | Where-Object { $_.Key -eq $Key } | Select-Object -First 1)
}

function New-PelIntranetId {
    $chars = 'abcdefghijklmnopqrstuvwxyz0123456789'
    $rng = New-Object System.Security.Cryptography.RNGCryptoServiceProvider
    $bytes = New-Object byte[] 8
    $rng.GetBytes($bytes)
    $rng.Dispose()
    return -join ($bytes | ForEach-Object { $chars[$_ % $chars.Length] })
}

function New-PelIntranetBlock {
    param([string]$Type, [string]$Title, [string]$Text = '', [bool]$Wide = $false, [bool]$Visible = $true)
    # Closed: nur für "Bestellung mit Speisekarte" - Bestellschluss (von der Orga umschaltbar)
    return [pscustomobject]@{ Id = (New-PelIntranetId); Type = $Type; Title = $Title; Text = $Text; Wide = $Wide; Visible = $Visible; Closed = $false }
}

function Get-PelIntranetTemplates {
    return @(
        [pscustomobject]@{ Key = 'classic'; Name = (Get-PelText 'Klassische LAN-Party' 'Classic LAN party') }
        [pscustomobject]@{ Key = 'tourney'; Name = (Get-PelText 'Turnier-Event' 'Tournament event') }
        [pscustomobject]@{ Key = 'friends'; Name = (Get-PelText 'Kleine Freundes-LAN' 'Small LAN with friends') }
        [pscustomobject]@{ Key = 'big'; Name = (Get-PelText 'Große LAN-Party (mit Speisekarte)' 'Big LAN party (with menu)') }
    )
}

