                $blocks.Add((New-PelIntranetBlock 'schedule' 'Zeitplan' "Fr 16:00 | Einlass & Aufbau`nFr 19:00 | Begrüßung`nFr 20:00 | Turnierstart`nSa 13:00 | Bestellschluss Mittagessen`nSa 19:00 | Bestellschluss Abendessen`nSo 12:00 | Finale & Siegerehrung"))
