                $blocks.Add((New-PelIntranetBlock 'rules' 'Regeln' "Fair spielen - kein Cheaten.`nNachtruhe im Schlafbereich.`nNotausgänge freihalten.`nBei Problemen: Orga-Tisch." $true))
                $blocks.Add((New-PelIntranetBlock 'contact' 'Orga-Kontakt' 'Orga-Tisch am Eingang.'))
