        }
        default {
            if ($en) {
                $blocks.Add((New-PelIntranetBlock 'news' 'News' "Welcome! | Great to have you here. Everything for tonight is on this page.`nPower & network | Please only use the power strip at your seat."))
                $blocks.Add((New-PelIntranetBlock 'schedule' 'Schedule' "18:00 | Doors open & setup`n19:30 | Welcome`n20:00 | First tournament`n22:00 | Pizza orders close`n00:00 | Midnight round"))
                $blocks.Add((New-PelIntranetBlock 'servers' 'Servers' ''))
                $blocks.Add((New-PelIntranetBlock 'downloads' 'Downloads' 'Patches, maps and tools for tonight.'))
                $blocks.Add((New-PelIntranetBlock 'results' 'Results' ''))
                $blocks.Add((New-PelIntranetBlock 'orders' 'Pizza list' 'Orders until 10 pm. Enter your name and what you want.'))
                $blocks.Add((New-PelIntranetBlock 'rules' 'Rules' "Play fair - no cheating.`nBring your own headset.`nPlease clean up after yourself.`nProblems? Talk to the organizers." $true))
                $blocks.Add((New-PelIntranetBlock 'contact' 'Organizers' 'Questions? Come to the organizer desk.'))
            } else {
                $blocks.Add((New-PelIntranetBlock 'news' 'News' "Willkommen! | Schön, dass du da bist. Hier findest du alles für den Abend.`nStrom & Netzwerk | Bitte nur die Steckdosenleiste an deinem Platz nutzen."))
                $blocks.Add((New-PelIntranetBlock 'schedule' 'Zeitplan' "18:00 | Einlass & Aufbau`n19:30 | Begrüßung`n20:00 | Erstes Turnier`n22:00 | Pizza-Bestellung schließt`n00:00 | Mitternachts-Runde"))
                $blocks.Add((New-PelIntranetBlock 'servers' 'Server' ''))
                $blocks.Add((New-PelIntranetBlock 'downloads' 'Downloads' 'Patches, Maps und Tools für heute Abend.'))
                $blocks.Add((New-PelIntranetBlock 'results' 'Ergebnisse' ''))
                $blocks.Add((New-PelIntranetBlock 'orders' 'Pizza-Liste' 'Bestellung bis 22 Uhr. Name und Wunsch eintragen.'))
                $blocks.Add((New-PelIntranetBlock 'rules' 'Regeln' "Fair spielen - kein Cheaten.`nEigenes Headset mitbringen.`nMüll bitte selbst wegräumen.`nBei Problemen: Orga ansprechen." $true))
                $blocks.Add((New-PelIntranetBlock 'contact' 'Orga-Kontakt' 'Bei Fragen einfach an den Orga-Tisch kommen.'))
            }
        }
    }
    return $blocks
}

function New-PelIntranetConfig {
    $name = Get-PelText 'Unsere LAN-Party' 'Our LAN party'
    return [pscustomobject]@{
        Version     = 1
        Mode        = 'own'
        ExternUrl   = ''
        Port        = $script:PelIntranetDefaultPort
        AutoPublish = $false
        Template    = 'classic'
        Event       = [pscustomobject]@{
            Title = $name; Date = ''; Place = ''; Organizer = (Limit-PelText (Get-PelDisplayName) 60)
            Countdown = ''; CountdownText = (Get-PelText 'bis zum Start' 'until kick-off'); Accent = '#f28c28'; Logo = ''
            # Eigenes Kopfbild: 'banner' = Bild über dem Kopfbereich, 'background' = Hintergrund
            # des Kopfbereichs. HideTitle: Titel/Datum/Ort ausblenden (stehen schon im Bild).
            LogoSize = 'M'; Header = ''; HeaderMode = 'banner'; HideTitle = $false
        }
        Blocks      = @(New-PelIntranetTemplate 'classic')
    }
}

# Bringt eine gelesene oder importierte Konfiguration in eine feste, geprüfte Form.
# Alles, was hier nicht vorkommt, wird verworfen (auch aus fremden .zip-Dateien).
function Repair-PelIntranetConfig($c) {
    $d = New-PelIntranetConfig
    if (-not $c) { return $d }
    if ([string]$c.Mode -in @('own', 'extern')) { $d.Mode = [string]$c.Mode }
    $u = Test-PelIntranetUrl ([string]$c.ExternUrl)
    if ($u) { $d.ExternUrl = $u } else { $d.ExternUrl = '' }
    if ($d.Mode -eq 'extern' -and -not $d.ExternUrl) { $d.Mode = 'own' }
    $p = 0
    if ([int]::TryParse([string]$c.Port, [ref]$p) -and $p -ge 1024 -and $p -le 65535) { $d.Port = $p }
    $d.AutoPublish = [bool]$c.AutoPublish
    if ([string]$c.Template -in @('classic', 'tourney', 'friends', 'big')) { $d.Template = [string]$c.Template }
    if ($c.Event) {
        $d.Event.Title = Limit-PelText ([string]$c.Event.Title) 80
        if (-not $d.Event.Title) { $d.Event.Title = Get-PelText 'Unsere LAN-Party' 'Our LAN party' }
        $d.Event.Date = Limit-PelText ([string]$c.Event.Date) 60
        $d.Event.Place = Limit-PelText ([string]$c.Event.Place) 80
        $d.Event.Organizer = Limit-PelText ([string]$c.Event.Organizer) 60
        $d.Event.CountdownText = Limit-PelText ([string]$c.Event.CountdownText) 40
        $cd = [string]$c.Event.Countdown
        $dt = [datetime]::MinValue
        if ($cd -and [datetime]::TryParseExact($cd, 'yyyy-MM-ddTHH:mm', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$dt)) { $d.Event.Countdown = $cd } else { $d.Event.Countdown = '' }
        if ([string]$c.Event.Accent -match '^#[0-9a-fA-F]{6}$') { $d.Event.Accent = ([string]$c.Event.Accent).ToLowerInvariant() }
        if ([string]$c.Event.Logo -match '^logo\.(png|jpg|gif)$') { $d.Event.Logo = [string]$c.Event.Logo } else { $d.Event.Logo = '' }
        if ([string]$c.Event.LogoSize -in @('S', 'M', 'L')) { $d.Event.LogoSize = [string]$c.Event.LogoSize }
        if ([string]$c.Event.Header -match '^header\.(png|jpg|gif)$') { $d.Event.Header = [string]$c.Event.Header } else { $d.Event.Header = '' }
        if ([string]$c.Event.HeaderMode -in @('banner', 'background')) { $d.Event.HeaderMode = [string]$c.Event.HeaderMode }
        $d.Event.HideTitle = [bool]$c.Event.HideTitle
    }
    $keys = @(Get-PelIntranetBlockTypes | ForEach-Object { $_.Key })
    $list = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($b in @($c.Blocks | Select-Object -First 30)) {
        if (-not $b -or [string]$b.Type -notin $keys) { continue }
        $id = [string]$b.Id
        if ($id -notmatch '^[a-z0-9]{4,16}$' -or $seen.ContainsKey($id)) { $id = New-PelIntranetId }
        $seen[$id] = $true
        $txt = ([string]$b.Text) -replace "`r", ''
        # Speisekarten großer LAN-Partys brauchen mehr Platz als die übrigen Blöcke
        $maxTxt = if ([string]$b.Type -eq 'menu') { 16000 } elseif ([string]$b.Type -eq 'prices') { 8000 } else { 4000 }
        if ($txt.Length -gt $maxTxt) { $txt = $txt.Substring(0, $maxTxt) }
        $vis = $true
        if ($null -ne $b.Visible) { $vis = [bool]$b.Visible }
        $list.Add([pscustomobject]@{ Id = $id; Type = [string]$b.Type; Title = (Limit-PelText ([string]$b.Title) 60); Text = $txt; Wide = [bool]$b.Wide; Visible = $vis; Closed = [bool]$b.Closed })
    }
    # BUGFIX: @(List[object]) als Eigenschaftswert wirft "Argument types do not match" - deshalb ToArray()
    if ($null -ne $c.Blocks) { $d.Blocks = $list.ToArray() }
    return $d
}

function Get-PelIntranetConfig {
    try {
        if ([System.IO.File]::Exists($script:PelIntranetConfigPath)) {
            return (Repair-PelIntranetConfig (Read-PelTextFile $script:PelIntranetConfigPath | ConvertFrom-Json))
        }
    } catch {
        Write-PelLog -Level 'INTRANET' -Message "intranet.json nicht lesbar: $($_.Exception.Message)"
        try { Copy-Item -LiteralPath $script:PelIntranetConfigPath -Destination ("$($script:PelIntranetConfigPath).defekt_" + (Get-Date -Format 'yyyyMMdd_HHmmss')) -Force } catch { }
    }
    return (New-PelIntranetConfig)
}

function Initialize-PelIntranetFolders {
    foreach ($p in @($script:PelIntranetDir, $script:PelIntranetDownloadDir, $script:PelIntranetLogosDir)) {
        if (-not [System.IO.Directory]::Exists($p)) { [void][System.IO.Directory]::CreateDirectory($p) }
    }
}

function Save-PelIntranetConfig($Cfg) {
    try {
        Initialize-PelIntranetFolders
        Write-PelTextFileAtomic $script:PelIntranetConfigPath (ConvertTo-Json -InputObject $Cfg -Depth 5)
        return $true
    } catch {
        Write-PelLog -Level 'INTRANET' -Message "intranet.json konnte nicht gespeichert werden: $($_.Exception.Message)"
        return $false
    }
}

# Nur Adressen im lokalen Netz: private IPv4 (Heimnetz, P2P 10.77.x.y) oder ein lokaler
# Name ohne Punkt bzw. mit .local/.lan/.home/.intranet/.internal/.home.arpa. So kann
# niemand über das Intranet fremde Seiten aus dem Internet in die Manager schleusen.
function Test-PelIntranetUrl([string]$Url) {
    $t = ([string]$Url).Trim()
    if (-not $t) { return $null }
    if ($t -notmatch '^[a-zA-Z][a-zA-Z0-9+.-]*://') { $t = "http://$t" }
    $u = $null
    if (-not [Uri]::TryCreate($t, [UriKind]::Absolute, [ref]$u)) { return $null }
    if ($u.Scheme -notin @('http', 'https')) { return $null }
    if ($u.UserInfo) { return $null }
    $h = $u.Host.ToLowerInvariant()
    $ip = $null
    if ([System.Net.IPAddress]::TryParse($h, [ref]$ip)) {
        if ($ip.AddressFamily -ne [System.Net.Sockets.AddressFamily]::InterNetwork) { return $null }
        $b = $ip.GetAddressBytes()
        $private = ($b[0] -eq 10) -or ($b[0] -eq 172 -and $b[1] -ge 16 -and $b[1] -le 31) -or ($b[0] -eq 192 -and $b[1] -eq 168) -or ($b[0] -eq 169 -and $b[1] -eq 254) -or ($b[0] -eq 127)
        if (-not $private) { return $null }
    } else {
        if ($h -notmatch '^[a-z0-9-]+(\.[a-z0-9-]+)*$') { return $null }
        $local = ($h -notmatch '\.') -or ($h -match '\.(local|lan|home|intranet|internal|home\.arpa)$')
        if (-not $local) { return $null }
    }
    return $u.AbsoluteUri
}

# ---- Seite erzeugen ---------------------------------------------------------------------
function ConvertTo-PelHtml([string]$Text) { return [System.Net.WebUtility]::HtmlEncode([string]$Text) }

function Get-PelIntranetLines([string]$Text) {
    return @(([string]$Text) -split "`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
}

function Split-PelIntranetLine([string]$Line) {
    $i = $Line.IndexOf('|')
    if ($i -lt 0) { return @($Line.Trim(), '') }
    return @($Line.Substring(0, $i).Trim(), $Line.Substring($i + 1).Trim())
}

function Get-PelIntranetHeaderPath($Cfg) {
    if (-not $Cfg.Event.Header) { return '' }
    $p = Join-Path $script:PelIntranetDir ([string]$Cfg.Event.Header)
    if ([System.IO.File]::Exists($p)) { return $p }
    return ''
}

# Bilder im Logo-Ordner (Block "Logos & Sponsoren"): höchstens 24, je bis 2 MB
function Get-PelIntranetLogoFiles {
    $list = @()
    try {
        if ([System.IO.Directory]::Exists($script:PelIntranetLogosDir)) {
            $list = @(Get-ChildItem -LiteralPath $script:PelIntranetLogosDir -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Extension -match '^\.(png|jpe?g|gif)$' -and $_.Length -le 2097152 -and -not ($_.Attributes -band [System.IO.FileAttributes]::Hidden) } |
                Sort-Object Name | Select-Object -First 24)
        }
    } catch { }
    return $list
}

# Bildquelle für die Seite: über den Server (/pel/...) oder - in der Vorschau ohne Server -
# eingebettet als data:-Adresse. ?v= sorgt dafür, dass ein ausgetauschtes Bild neu geladen wird.
function Get-PelIntranetImageSrc([string]$Path, [bool]$Server, [string]$Url, [long]$MaxInline = 3145728) {
    if (-not $Path -or -not [System.IO.File]::Exists($Path)) { return '' }
    $fi = New-Object System.IO.FileInfo($Path)
    if ($Server) { return ($Url + '?v=' + $fi.LastWriteTimeUtc.Ticks) }
    if ($fi.Length -gt $MaxInline) { return '' }
    $ext = $fi.Extension.TrimStart('.').ToLowerInvariant()
    if ($ext -eq 'jpg') { $ext = 'jpeg' }
    try { return ('data:image/' + $ext + ';base64,' + [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($Path))) } catch { return '' }
}

function Get-PelIntranetLogoPath($Cfg) {
    if (-not $Cfg.Event.Logo) { return '' }
    $p = Join-Path $script:PelIntranetDir ([string]$Cfg.Event.Logo)
    if ([System.IO.File]::Exists($p)) { return $p }
    return ''
}

function Get-PelIntranetDownloads {
    $list = @()
    try {
        if ([System.IO.Directory]::Exists($script:PelIntranetDownloadDir)) {
            $list = @(Get-ChildItem -LiteralPath $script:PelIntranetDownloadDir -File -ErrorAction Stop |
                Where-Object { -not ($_.Attributes -band [System.IO.FileAttributes]::Hidden) -and -not ($_.Attributes -band [System.IO.FileAttributes]::System) -and $_.Name -notin @('desktop.ini', 'Thumbs.db') } |
                Sort-Object Name | Select-Object -First 60)
        }
    } catch { }
    return $list
}

# Einträge der Mitmach-Blöcke (Umfrage/Bestellliste). Läuft der Server, gelten seine
# Daten (aktuell); sonst die zuletzt gespeicherten aus mitmachen.json.
function Get-PelIntranetEntries([string]$Id) {
    if (('PelIntranetServer' -as [type]) -and [PelIntranetServer]::IsRunning) { return @([PelIntranetServer]::GetEntries($Id)) }
    try {
        if ([System.IO.File]::Exists($script:PelIntranetEntriesPath)) {
            $j = Read-PelTextFile $script:PelIntranetEntriesPath | ConvertFrom-Json
            if ($j -and $j.$Id) { return @($j.$Id | ForEach-Object { [string]$_ }) }
        }
    } catch { }
    return @()
}

function Save-PelIntranetEntries($Cfg) {
    if (-not ('PelIntranetServer' -as [type])) { return }
    try {
        $o = [ordered]@{}
        foreach ($b in @($Cfg.Blocks | Where-Object { $_.Type -in @('poll', 'orders', 'menu', 'seatmap') })) {
            $o[[string]$b.Id] = @([PelIntranetServer]::GetEntries([string]$b.Id))
        }
        Initialize-PelIntranetFolders
        Write-PelTextFileAtomic $script:PelIntranetEntriesPath (ConvertTo-Json -InputObject $o -Depth 3)
    } catch { Write-PelLog -Level 'INTRANET' -Message "mitmachen.json: $($_.Exception.Message)" }
}

function Import-PelIntranetEntries($Cfg) {
    if (-not ('PelIntranetServer' -as [type])) { return }
    $j = $null
    try { if ([System.IO.File]::Exists($script:PelIntranetEntriesPath)) { $j = Read-PelTextFile $script:PelIntranetEntriesPath | ConvertFrom-Json } } catch { $j = $null }
    foreach ($b in @($Cfg.Blocks | Where-Object { $_.Type -in @('poll', 'orders', 'menu', 'seatmap') })) {
        $lines = @()
        if ($j -and $j.([string]$b.Id)) { $lines = @($j.([string]$b.Id) | ForEach-Object { [string]$_ }) }
        [PelIntranetServer]::SetEntries([string]$b.Id, [string[]]$lines)
    }
}

function Get-PelIntranetPollOptions($Block) {
    return @(Get-PelIntranetLines $Block.Text | Select-Object -First 12 | ForEach-Object { Limit-PelText $_ 60 })
}

# ---- Bestellung mit Speisekarte ------------------------------------------------------------
# Inhalt des Blocks (eine Angabe pro Zeile):
#   [Pizza]                                   Kategorie
#   Margherita | 7,50 | Tomate, Mozzarella    Artikel | Preis | Beschreibung (Preis optional)
#   Info: Bestellung bis 19 Uhr               Hinweis für die Gäste
#   Link: Pizzeria Roma | 06184 1234 | https://...   Lieferdienst oder Lokal (Telefon/Adresse optional)
#   Orga: 10.77.0.5, 192.168.1.20             Orga-PCs, die bei jeder Bestellung eine Meldung bekommen
#   Internet: nein                            LAN ohne Internet: Lieferdienst-Links und Karte ausblenden
# Eigene Speisen und Getraenke der Orga (4. Feld "Optionen", mit Komma getrennt):
#   Chili con Carne | 4,50 | selbst gekocht | eigen            eigenes Angebot, online bestellbar
#   Cola 0,5 l | 2,00 | | eigen, vor Ort                       nur vor Ort (Theke/Kasse), nicht bestellbar
#   Hot Dog | 2,50 | | eigen, ausverkauft                      wird angezeigt, ist aber nicht bestellbar
# Ohne Optionen bleibt alles wie bisher (Lieferdienst-Artikel, im Intranet bestellbar).
# Bequemer geht es im Fenster "Speisen & Getränke bearbeiten" (Tabelle, Sortiment).
# Jeder PC hat EINE Bestellung (mehrere Artikel, je bis 20 Stück) und kann sie ändern, bis
# die Orga sie auf "bestellt" setzt. Die Orga verwaltet alles in Option 11 unter
# "Bestellungen verwalten" (Status, Sammelbestellung kopieren, CSV, Bestellschluss).
function Get-PelIntranetMenuSample {
    if ($script:PelLang -eq 'en') {
        return "Info: Orders close 1 hour before delivery. Pay cash at the organizer desk.`nLink: Lieferando | https://www.lieferando.de`nLink: Wolt | https://wolt.com/de/deu`nLink: Uber Eats | https://www.ubereats.com/de`nLink: Domino's | https://www.dominos.de`n[Pizza]`nMargherita | 7.50 | tomato, mozzarella`nSalami | 8.50`nTuna | 9.00 | tuna, onions`nVegetarian | 8.90 | peppers, mushrooms, olives`n[Pasta]`nSpaghetti Bolognese | 8.00`nPenne Arrabbiata | 7.50 | spicy`n[From the organizers]`nChili con carne | 4.50 | home-made, with bread | own`nHot dog | 2.50 | | own`n[Drinks (organizer counter)]`nCola 0.5 l | 2.00 | | own, on site`nWater 0.5 l | 1.50 | | own, on site`nEnergy drink | 2.50 | | own, on site"
    }
    return "Info: Bestellschluss 1 Stunde vor Lieferung. Bezahlt wird bar am Orga-Tisch.`nLink: Lieferando | https://www.lieferando.de`nLink: Wolt | https://wolt.com/de/deu`nLink: Uber Eats | https://www.ubereats.com/de`nLink: Domino's | https://www.dominos.de`n[Pizza]`nMargherita | 7,50 | Tomate, Mozzarella`nSalami | 8,50`nThunfisch | 9,00 | Thunfisch, Zwiebeln`nVegetarisch | 8,90 | Paprika, Pilze, Oliven`n[Pasta]`nSpaghetti Bolognese | 8,00`nPenne Arrabbiata | 7,50 | scharf`n[Von der Orga]`nChili con Carne | 4,50 | selbst gekocht, mit Brot | eigen`nHot Dog | 2,50 | | eigen`n[Getränke (Orga-Theke)]`nCola 0,5 l | 2,00 | | eigen, vor Ort`nWasser 0,5 l | 1,50 | | eigen, vor Ort`nEnergy-Drink | 2,50 | | eigen, vor Ort"
}

# Optionen eines Speisekarten-Artikels (4. Feld, mit Komma getrennt). Unbekannte Woerter
# werden ignoriert - so bleiben aeltere Speisekarten unveraendert gueltig.
#   eigen / orga / own              = eigenes Angebot der Orga (kein Lieferdienst)
#   vor Ort / Theke / offline       = nur vor Ort kaufen, im Intranet nicht bestellbar
#   ausverkauft / sold out          = wird angezeigt, ist aber gerade nicht bestellbar
function Get-PelIntranetMenuFlags([string]$Text) {
    $f = [pscustomobject]@{ Own = $false; Online = $true; SoldOut = $false }
    foreach ($w in @(([string]$Text) -split '[,;]' | ForEach-Object { ($_.Trim().ToLowerInvariant()) -replace '[\s\-]+', '' } | Where-Object { $_ })) {
        if ($w -in @('eigen', 'eigenes', 'orga', 'own', 'selbst', 'selbstgemacht')) { $f.Own = $true }
        elseif ($w -in @('vorort', 'nurvorort', 'theke', 'kasse', 'offline', 'onsite')) { $f.Online = $false }
        elseif ($w -in @('ausverkauft', 'soldout')) { $f.SoldOut = $true }
        elseif ($w -in @('online', 'bestellbar')) { $f.Online = $true }
    }
    return $f
}

# Optionen wieder als Text fuer das 4. Feld (Gegenstueck zu Get-PelIntranetMenuFlags)
function ConvertTo-PelIntranetMenuFlagText([bool]$Own, [bool]$Online, [bool]$SoldOut) {
    $w = New-Object System.Collections.Generic.List[string]
    if ($script:PelLang -eq 'en') {
        if ($Own) { $w.Add('own') }; if (-not $Online) { $w.Add('on site') }; if ($SoldOut) { $w.Add('sold out') }
    } else {
        if ($Own) { $w.Add('eigen') }; if (-not $Online) { $w.Add('vor Ort') }; if ($SoldOut) { $w.Add('ausverkauft') }
    }
    return ($w -join ', ')
}

function Get-PelIntranetMenu($Block) {
    $m = [pscustomobject]@{
        Notes = (New-Object System.Collections.Generic.List[string]); Orga = (New-Object System.Collections.Generic.List[string])
        Links = (New-Object System.Collections.Generic.List[object]); Items = (New-Object System.Collections.Generic.List[object])
        NoInternet = $false
    }
    $cat = ''
    foreach ($ln in @(Get-PelIntranetLines ([string]$Block.Text))) {
        if ($ln -match '^\[(.+)\]$') { $cat = Limit-PelText $matches[1] 40; continue }
        if ($ln -match '^(?i)(info|hinweis)\s*:\s*(.+)$') { if ($m.Notes.Count -lt 10) { $m.Notes.Add((Limit-PelText $matches[2] 200)) }; continue }
        # "Internet: nein" = LAN ohne Internet: Lieferdienst-Links und Karte nicht anzeigen
        if ($ln -match '^(?i)internet\s*:\s*(.+)$') { if ($matches[1].Trim() -match '^(?i)(nein|no|aus|off|ohne|kein|keins|none)$') { $m.NoInternet = $true }; continue }
        if ($ln -match '^(?i)orga\s*:\s*(.+)$') {
            foreach ($ip in @($matches[1] -split '[,;\s]+')) {
                $a = $null
                if ($ip -match '^\d{1,3}(\.\d{1,3}){3}$' -and [System.Net.IPAddress]::TryParse($ip, [ref]$a)) {
                    $bb = $a.GetAddressBytes()
                    $private = ($bb[0] -eq 10) -or ($bb[0] -eq 172 -and $bb[1] -ge 16 -and $bb[1] -le 31) -or ($bb[0] -eq 192 -and $bb[1] -eq 168)
                    if ($private -and -not $m.Orga.Contains($ip) -and $m.Orga.Count -lt 10) { $m.Orga.Add($ip) }
                }
            }
            continue
        }
        if ($ln -match '^(?i)(link|lieferdienst|lokal|restaurant)\s*:\s*(.+)$') {
            $parts = @($matches[2] -split '\|' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            if ($parts.Count -eq 0 -or $m.Links.Count -ge 20) { continue }
            $lk = [pscustomobject]@{ Name = (Limit-PelText $parts[0] 60); Url = ''; Info = (New-Object System.Collections.Generic.List[string]) }
            foreach ($px in @($parts | Select-Object -Skip 1)) {
                $u = $null
                if (-not $lk.Url -and $px -match '^https?://' -and [Uri]::TryCreate($px, [UriKind]::Absolute, [ref]$u) -and $u.Scheme -in @('http', 'https') -and -not $u.UserInfo) { $lk.Url = $u.AbsoluteUri }
                elseif ($lk.Info.Count -lt 3) { $lk.Info.Add((Limit-PelText $px 80)) }
            }
            $m.Links.Add($lk)
            continue
        }
        if ($m.Items.Count -ge 200) { continue }
        $parts = @($ln -split '\|' | ForEach-Object { $_.Trim() })
        $name = Limit-PelText $parts[0] 60
        if (-not $name) { continue }
        $price = $null
        $desc = ''
        if ($parts.Count -ge 2) {
            $pt = ($parts[1] -replace '(?i)\s*(eur|euro)\s*$', '' -replace '\s*€\s*$', '').Trim()
            $pv = [decimal]0
            if ($pt -match '^\d{1,4}([.,]\d{1,2})?$' -and [decimal]::TryParse(($pt -replace ',', '.'), [System.Globalization.NumberStyles]::Number, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$pv)) { $price = $pv }
            elseif ($pt) { $desc = Limit-PelText $pt 80 }
        }
        if ($parts.Count -ge 3) { $desc = (@($desc, (Limit-PelText $parts[2] 80)) | Where-Object { $_ }) -join ' - ' }
        $fl = Get-PelIntranetMenuFlags $(if ($parts.Count -ge 4) { $parts[3] } else { '' })
        $m.Items.Add([pscustomobject]@{ Cat = $cat; Name = $name; Price = $price; Desc = $desc; Own = $fl.Own; Online = $fl.Online; SoldOut = $fl.SoldOut })
    }
    return $m
}

# Preisliste (Block 'prices'): Die Orga legt die Preise frei fest. Eine Zeile pro Artikel:
#   Artikel | Preis | Hinweis      [Kategorie] gruppiert, Info: Hinweis, Währung: CHF (Standard EUR)
# Eine reine Zahl (7,50) wird mit Währung und zwei Nachkommastellen angezeigt, jeder andere Text
# (frei, 5 EUR pro Tag, ab 3 ...) unverändert.
function Get-PelIntranetPriceList($Block) {
    $m = [pscustomobject]@{
        Notes = (New-Object System.Collections.Generic.List[string]); Currency = [string][char]0x20AC
        Items = (New-Object System.Collections.Generic.List[object])
    }
    $ci = [System.Globalization.CultureInfo]::GetCultureInfo($(if ($script:PelLang -eq 'en') { 'en-GB' } else { 'de-DE' }))
    $cat = ''
    foreach ($ln in @(Get-PelIntranetLines ([string]$Block.Text))) {
        if ($ln -match '^\[(.+)\]$') { $cat = Limit-PelText $matches[1] 40; continue }
        if ($ln -match '^(?i)(info|hinweis)\s*:\s*(.+)$') { if ($m.Notes.Count -lt 10) { $m.Notes.Add((Limit-PelText $matches[2] 200)) }; continue }
        if ($ln -match '^(?i)(währung|waehrung|currency)\s*:\s*(.+)$') {
            $cur = (Limit-PelText $matches[2] 8).Trim()
            if ($cur) { $m.Currency = $cur }
            continue
        }
        if ($m.Items.Count -ge 100) { continue }
        $parts = @($ln -split '\|' | ForEach-Object { $_.Trim() })
        $name = Limit-PelText $parts[0] 60
        if (-not $name) { continue }
        $priceText = ''
        $desc = ''
        if ($parts.Count -ge 2 -and $parts[1]) {
            $pt = $parts[1].Trim()
            $pv = [decimal]0
            if ($pt -match '^\d{1,5}([.,]\d{1,2})?$' -and [decimal]::TryParse(($pt -replace ',', '.'), [System.Globalization.NumberStyles]::Number, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$pv)) {
                $priceText = $pv.ToString('N2', $ci) + ' ' + $m.Currency
            } else { $priceText = Limit-PelText $pt 40 }
        }
        if ($parts.Count -ge 3) { $desc = Limit-PelText $parts[2] 80 }
        $m.Items.Add([pscustomobject]@{ Cat = $cat; Name = $name; Price = $priceText; Desc = $desc })
    }
    return $m
}

function Get-PelIntranetPriceSample {
    if ($script:PelLang -eq 'en') {
        return "Info: Pay cash at the organizer desk.`n[Entry]`nWeekend (Fri-Sun) | 25 | incl. power and network`nDay ticket | 12`n[Drinks]`nCola, Fanta (0.5 l) | 1.50 | deposit 0.25`nWater (0.5 l) | 1`n[Snacks]`nPizza slice | 2.50`nTournament entry | free"
    }
    return "Info: Bezahlung bar am Orga-Tisch.`n[Teilnahme]`nWochenende (Fr-So) | 25 | inkl. Strom und Netzwerk`nTagesticket | 12`n[Getränke]`nCola, Fanta (0,5 l) | 1,50 | Pfand 0,25`nWasser (0,5 l) | 1`n[Snacks]`nPizza-Stück | 2,50`nTurnier-Startgeld | frei"
}

# ---- Speisen & Getränke als Tabelle (Fenster "Speisen & Getränke bearbeiten") --------------
# Zerlegt den Inhalt eines Blocks 'menu' oder 'prices' in Artikelzeilen (so wie getippt) und
# die übrigen Angaben (Info:, Link:, Orga:, Währung:). Das Fenster arbeitet mit den Zeilen
# und schreibt sie danach wieder als Text in den Block - so bleiben das bewährte Textformat,
# Export/Import und ältere Manager unverändert.
function Get-PelIntranetItemRows([string]$Text, [string]$Type) {
    $res = [pscustomobject]@{ Rows = (New-Object System.Collections.Generic.List[object]); Extra = (New-Object System.Collections.Generic.List[string]); NoInternet = $false }
    $extraRx = if ($Type -eq 'menu') { '^(?i)(info|hinweis|orga|link|lieferdienst|lokal|restaurant)\s*:' } else { '^(?i)(info|hinweis|währung|waehrung|currency)\s*:' }
    $cat = ''
    foreach ($ln in @(Get-PelIntranetLines $Text)) {
        if ($ln -match '^\[(.*)\]$') { $cat = Limit-PelText $matches[1] 40; continue }
        if ($Type -eq 'menu' -and $ln -match '^(?i)internet\s*:\s*(.+)$') {
            if ($matches[1].Trim() -match '^(?i)(nein|no|aus|off|ohne|kein|keins|none)$') { $res.NoInternet = $true }
            continue
        }
        if ($ln -match $extraRx) { $res.Extra.Add($ln); continue }
        $parts = @($ln -split '\|' | ForEach-Object { $_.Trim() })
        if (-not $parts[0]) { continue }
        $fl = Get-PelIntranetMenuFlags $(if ($parts.Count -ge 4) { $parts[3] } else { '' })
        $res.Rows.Add([pscustomobject]@{
                Cat = $cat; Name = (Limit-PelText $parts[0] 60)
                Price = $(if ($parts.Count -ge 2) { Limit-PelText $parts[1] 40 } else { '' })
                Desc = $(if ($parts.Count -ge 3) { Limit-PelText $parts[2] 80 } else { '' })
                Own = $fl.Own; Online = $fl.Online; SoldOut = $fl.SoldOut
            })
    }
    return $res
}

# Gegenstück: Zeilen wieder als Blocktext. "[Kategorie]" nur, wenn sie wechselt; eine leere
# Kategorie nach einer gefüllten wird als "[ ]" geschrieben (sonst erbt der Artikel die
# Kategorie davor). "|" in Feldern wird zu "/", weil es das Trennzeichen ist.
function ConvertTo-PelIntranetItemText($Rows, [string[]]$Extra, [string]$Type, [bool]$NoInternet) {
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($x in $Extra) { if ($x -and $x.Trim() -and $x.Trim() -notmatch '^(?i)internet\s*:') { $out.Add($x.Trim()) } }
    if ($Type -eq 'menu' -and $NoInternet) { $out.Add($(if ($script:PelLang -eq 'en') { 'Internet: no' } else { 'Internet: nein' })) }
    $cat = ''
    # foreach direkt über die Liste: @(List[object]) wirft "Argument types do not match"
    foreach ($r in $Rows) {
        if (-not $r) { continue }
        $c = Limit-PelText (([string]$r.Cat) -replace '[\[\]|]', '') 40
        if ($c -ne $cat) { $out.Add($(if ($c) { "[$c]" } else { '[ ]' })); $cat = $c }
        $n = Limit-PelText (([string]$r.Name) -replace '\|', '/') 60
        $p = Limit-PelText (([string]$r.Price) -replace '\|', '/') 40
        $ds = Limit-PelText (([string]$r.Desc) -replace '\|', '/') 80
        $fl = if ($Type -eq 'menu') { ConvertTo-PelIntranetMenuFlagText ([bool]$r.Own) ([bool]$r.Online) ([bool]$r.SoldOut) } else { '' }
        if ($fl) { $out.Add("$n | $p | $ds | $fl") }
        elseif ($ds) { $out.Add("$n | $p | $ds") }
        elseif ($p) { $out.Add("$n | $p") }
        else { $out.Add($n) }
    }
    return ($out -join "`n")
}

# Sortiment: eigene Artikel (Speisen, Getränke, Preise) für die nächste LAN-Party merken.
# Liegt nur auf diesem PC (intranet\sortiment.json), wird nicht an Gäste verteilt.
function Read-PelIntranetSortiment {
    try {
        if ([System.IO.File]::Exists($script:PelIntranetSortimentPath)) {
            $j = Read-PelTextFile $script:PelIntranetSortimentPath | ConvertFrom-Json
            return @(@($j.Items) | Where-Object { $_ -and $_.Name } | Select-Object -First 500 | ForEach-Object {
                    $on = $true
                    if ($null -ne $_.Online) { $on = [bool]$_.Online }
                    [pscustomobject]@{
                        Cat = (Limit-PelText ([string]$_.Cat) 40); Name = (Limit-PelText ([string]$_.Name) 60)
                        Price = (Limit-PelText ([string]$_.Price) 40); Desc = (Limit-PelText ([string]$_.Desc) 80)
                        Own = $true; Online = $on; SoldOut = $false
                    }
                })
        }
    } catch { Write-PelLog -Level 'INTRANET' -Message "sortiment.json nicht lesbar: $($_.Exception.Message)" }
    return @()
}

function Save-PelIntranetSortiment($Items) {
    try {
        Initialize-PelIntranetFolders
        $list = @($Items | Where-Object { $_ } | Select-Object -First 500 | ForEach-Object {
                [ordered]@{ Cat = [string]$_.Cat; Name = [string]$_.Name; Price = [string]$_.Price; Desc = [string]$_.Desc; Online = [bool]$_.Online }
            })
        Write-PelTextFileAtomic $script:PelIntranetSortimentPath (ConvertTo-Json -InputObject ([ordered]@{ Version = 1; Items = $list }) -Depth 4)
        return $true
    } catch {
        Write-PelLog -Level 'INTRANET' -Message "sortiment.json konnte nicht gespeichert werden: $($_.Exception.Message)"
        return $false
    }
}

function Format-PelIntranetMoney($Value) {
    $ci = [System.Globalization.CultureInfo]::GetCultureInfo($(if ($script:PelLang -eq 'en') { 'en-GB' } else { 'de-DE' }))
    return (([decimal]$Value).ToString('N2', $ci) + ' ' + [char]0x20AC)
}

function Get-PelIntranetOrderStateText([string]$State) {
    switch ($State) {
        'bestellt' { return (Get-PelText 'bestellt' 'ordered') }
        'unterwegs' { return (Get-PelText 'unterwegs' 'on the way') }
        'da' { return (Get-PelText 'abholbereit' 'ready for pick-up') }
        'storniert' { return (Get-PelText 'storniert' 'cancelled') }
        default { return (Get-PelText 'neu' 'new') }
    }
}

# Einen gespeicherten Eintrag ("IP<TAB>Name<TAB>Platz<TAB>Notiz<TAB>i:q;i:q<TAB>Status<TAB>Zeit")
# in ein lesbares Objekt verwandeln.
function ConvertFrom-PelIntranetOrder([string]$Line, $Menu) {
    $f = $Line -split "`t"
    if ($f.Count -lt 7) { return $null }
    $o = [pscustomobject]@{
        Ip = $f[0]; Name = $f[1]; Seat = $f[2]; Note = $f[3]; State = $f[5]; Time = [datetime]::MinValue
        Items = (New-Object System.Collections.Generic.List[object]); Count = 0; Sum = [decimal]0; HasPrice = $false; Text = ''
    }
    $ms = [long]0
    if ([long]::TryParse($f[6], [ref]$ms) -and $ms -gt 0) { $o.Time = [DateTimeOffset]::FromUnixTimeMilliseconds($ms).LocalDateTime }
    $txt = New-Object System.Collections.Generic.List[string]
    foreach ($part in ($f[4] -split ';')) {
        $iq = $part -split ':'
        $i = 0; $q = 0
        if ($iq.Count -ne 2 -or -not [int]::TryParse($iq[0], [ref]$i) -or -not [int]::TryParse($iq[1], [ref]$q) -or $q -le 0) { continue }
        if (-not $Menu -or $i -lt 0 -or $i -ge $Menu.Items.Count) { continue }
        $it = $Menu.Items[$i]
        $o.Items.Add([pscustomobject]@{ Index = $i; Name = $it.Name; Qty = $q; Price = $it.Price; Own = [bool]$it.Own })
        $o.Count += $q
        if ($null -ne $it.Price) { $o.Sum += ([decimal]$it.Price * $q); $o.HasPrice = $true }
        $txt.Add("${q}x $($it.Name)")
    }
    $o.Text = $txt -join ', '
    return $o
}

# Zeilen einer Sammelbestellung, getrennt nach Lieferdienst und eigenem Angebot der Orga
# (das eine wird beim Lieferdienst bestellt, das andere selbst zubereitet bzw. an der Theke
# ausgegeben). Gibt es nur eine Sorte, bleibt die Liste ohne Zwischenueberschriften.
function Get-PelIntranetTotalLines($Tot, [string]$Format = '{0}x {1}', [string]$Indent = '') {
    $out = New-Object System.Collections.Generic.List[string]
    $ext = @($Tot.Rows | Where-Object { -not $_.Own })
    $own = @($Tot.Rows | Where-Object { $_.Own })
    if ($ext.Count -gt 0 -and $own.Count -gt 0) {
        $out.Add($Indent + (Get-PelText 'Für den Lieferdienst:' 'For the delivery service:'))
        foreach ($r in $ext) { $out.Add($Indent + '  ' + ($Format -f $r.Qty, $r.Name)) }
        $out.Add($Indent + (Get-PelText 'Eigenes Angebot der Orga (selbst zubereiten / Theke):' 'Own offer of the organizers (prepare yourselves / counter):'))
        foreach ($r in $own) { $out.Add($Indent + '  ' + ($Format -f $r.Qty, $r.Name)) }
    } else {
        foreach ($r in @($Tot.Rows)) { $out.Add($Indent + ($Format -f $r.Qty, $r.Name)) }
    }
    return $out.ToArray()
}

function Get-PelIntranetOrders($Block, $Menu = $null) {
    if (-not $Menu) { $Menu = Get-PelIntranetMenu $Block }
    return @(Get-PelIntranetEntries ([string]$Block.Id) | ForEach-Object { ConvertFrom-PelIntranetOrder ([string]$_) $Menu } | Where-Object { $_ } | Sort-Object Time)
}

# Summe je Artikel über mehrere Bestellungen: "12x Margherita, 3x Cola ..." (für den Anruf
# beim Lieferdienst und die Übersicht auf der Seite)
function Get-PelIntranetOrderTotals($Orders) {
    $by = @{}
    $own = @{}
    $order = New-Object System.Collections.Generic.List[string]
    $sum = [decimal]0
    $has = $false
    foreach ($o in @($Orders)) {
        foreach ($it in $o.Items) {
            if (-not $by.ContainsKey($it.Name)) { $by[$it.Name] = 0; $own[$it.Name] = [bool]$it.Own; $order.Add($it.Name) }
            $by[$it.Name] += $it.Qty
        }
        if ($o.HasPrice) { $sum += $o.Sum; $has = $true }
    }
    # Own: eigenes Angebot der Orga - wird getrennt vom Lieferdienst ausgewiesen
    $rows = @($order | Sort-Object @{ Expression = { $by[$_] }; Descending = $true }, @{ Expression = { $_ } } | ForEach-Object { [pscustomobject]@{ Name = $_; Qty = $by[$_]; Own = $own[$_] } })
    return [pscustomobject]@{ Rows = $rows; Sum = $sum; HasPrice = $has; Orders = @($Orders).Count }
}

# ---- Sitzplan & Check-in ---------------------------------------------------------------------
# Inhalt: eine Zeile pro Reihe "A | 1-12" (Plätze A1..A12), mehrere Bereiche mit Komma,
# "-" = Gang (Lücke). "Gesperrt: A1, B5" = nicht wählbar (z. B. Orga, Technik).
# "Info: ..." = Hinweis für die Gäste. Höchstens 30 Reihen, 60 Plätze je Reihe.
# Gast wählt seinen Platz (einer pro PC, änderbar bis zum Check-in), die Orga checkt am
# Eingang ein ("Check-in verwalten"), kann Plätze ändern und Gäste ohne PC eintragen.
function Get-PelIntranetSeatSample {
    return (Get-PelText "Info: Such dir deinen Platz aus und melde dich bei der Ankunft am Orga-Tisch.`nA | 1-12`nB | 1-12`nC | 1-6, -, 7-12`nD | 1-6, -, 7-12`nGesperrt: A1" "Info: Pick your seat and check in at the organizer desk when you arrive.`nA | 1-12`nB | 1-12`nC | 1-6, -, 7-12`nD | 1-6, -, 7-12`nGesperrt: A1")
}

function Get-PelIntranetSeatMap($Block) {
    $m = [pscustomobject]@{ Rows = (New-Object System.Collections.Generic.List[object]); Blocked = @{}; Notes = (New-Object System.Collections.Generic.List[string]); All = (New-Object System.Collections.Generic.List[string]) }
    $seen = @{}
    foreach ($ln in @(Get-PelIntranetLines ([string]$Block.Text))) {
        if ($ln -match '^(?i)(info|hinweis)\s*:\s*(.+)$') { if ($m.Notes.Count -lt 5) { $m.Notes.Add((Limit-PelText $matches[2] 200)) }; continue }
        if ($ln -match '^(?i)(gesperrt|blocked)\s*:\s*(.+)$') {
            foreach ($x in @($matches[2] -split '[,;\s]+' | Where-Object { $_ })) { $m.Blocked[$x.ToUpperInvariant()] = $true }
            continue
        }
        $pp = $ln -split '\|', 2
        if ($pp.Count -ne 2) { continue }
        $lab = (($pp[0].Trim()) -replace '[^A-Za-z0-9]', '')
        if (-not $lab -or $lab.Length -gt 4 -or $m.Rows.Count -ge 30) { continue }
        $cells = New-Object System.Collections.Generic.List[string]
        foreach ($part in @($pp[1] -split ',')) {
            $t = $part.Trim()
            if ($t -eq '-') { $cells.Add(''); continue }
            $a = 0; $b = 0
            if ($t -match '^(\d{1,3})\s*-\s*(\d{1,3})$') { $a = [int]$matches[1]; $b = [int]$matches[2] }
            elseif ($t -match '^(\d{1,3})$') { $a = [int]$matches[1]; $b = $a }
            else { continue }
            if ($b -lt $a) { $tmp = $a; $a = $b; $b = $tmp }
            for ($i = $a; $i -le $b -and $cells.Count -lt 70; $i++) {
                $seat = ($lab + $i).ToUpperInvariant()
                if ($seen.ContainsKey($seat)) { continue }
                $seen[$seat] = $true
                $cells.Add($seat)
                $m.All.Add($seat)
            }
        }
        if ($cells.Count -gt 0) { $m.Rows.Add([pscustomobject]@{ Label = $lab.ToUpperInvariant(); Cells = $cells }) }
    }
    return $m
}

# Einträge des Sitzplans: Schlüssel (IP oder o:<id>), Name, Platz, Status, Zeiten
function Get-PelIntranetSeatEntries($Block) {
    return @(Get-PelIntranetEntries ([string]$Block.Id) | ForEach-Object {
            $f = ([string]$_) -split "`t"
            if ($f.Count -ge 4) {
                $res = [datetime]::MinValue; $in = [datetime]::MinValue
                $ms = [long]0
                if ($f.Count -ge 5 -and [long]::TryParse($f[4], [ref]$ms) -and $ms -gt 0) { $res = [DateTimeOffset]::FromUnixTimeMilliseconds($ms).LocalDateTime }
                $ms = [long]0
                if ($f.Count -ge 6 -and [long]::TryParse($f[5], [ref]$ms) -and $ms -gt 0) { $in = [DateTimeOffset]::FromUnixTimeMilliseconds($ms).LocalDateTime }
                [pscustomobject]@{ Key = $f[0]; Name = $f[1]; Seat = $f[2]; State = $f[3]; Reserved = $res; CheckedIn = $in }
            }
        })
}

# ---- Meldung "Neue Bestellung" für die Orga -----------------------------------------------
# EIN Fenster unten rechts (bleibt im Vordergrund), das neue Bestellungen sammelt - bei
# großen LAN-Partys würde ein Fenster pro Bestellung den Bildschirm zupflastern.
# Wird von Option 11 (Veranstalter-PC) und vom Control Center (weitere Orga-PCs, siehe
# PEORD1) benutzt. -OpenAction: was "Bestellungen öffnen" macht (leer = Button ausblenden).
$script:PelOrderNotify = $null
function Show-PelOrderNotification {
    param([string]$Heading, [string]$Line, [scriptblock]$OpenAction = $null, [string]$OpenText = '')
    $f = $script:PelOrderNotify
    if (-not $f -or $f.IsDisposed) {
        $f = (New-PelForm)
        $f.Text = 'Project Earth LAN - ' + [PelI18n]::Tr('Bestellungen')
        $f.Size = New-Object System.Drawing.Size(500, 300)
        $f.StartPosition = 'Manual'
        $f.FormBorderStyle = 'FixedDialog'
        $f.MaximizeBox = $false
        $f.MinimizeBox = $true
        $f.ShowInTaskbar = $true
        $f.TopMost = $true
        $f.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
        $f.ForeColor = [System.Drawing.Color]::White
        $f.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Regular)
        try {
            $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
            $f.Location = New-Object System.Drawing.Point(($wa.Right - $f.Width - 12), ($wa.Bottom - $f.Height - 12))
        } catch { $f.StartPosition = 'CenterScreen' }
        $lh = New-Object System.Windows.Forms.Label
        $lh.Location = New-Object System.Drawing.Point(12, 10)
        $lh.Size = New-Object System.Drawing.Size(460, 22)
        $lh.Font = New-Object System.Drawing.Font('Segoe UI', 10.5, [System.Drawing.FontStyle]::Bold)
        $lh.ForeColor = [System.Drawing.Color]::FromArgb(255, 170, 60)
        $f.Controls.Add($lh)
        $lb = New-Object System.Windows.Forms.ListBox
        $lb.Location = New-Object System.Drawing.Point(12, 38)
        $lb.Size = New-Object System.Drawing.Size(460, 158)
        $lb.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
        $lb.ForeColor = [System.Drawing.Color]::White
        $lb.BorderStyle = 'FixedSingle'
        $lb.HorizontalScrollbar = $true
        $f.Controls.Add($lb)
        $bo = New-Object System.Windows.Forms.Button
        $bo.Location = New-Object System.Drawing.Point(12, 206)
        $bo.Size = New-Object System.Drawing.Size(290, 40)
        $bo.FlatStyle = 'Flat'
        $bo.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $bo.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
        $bo.ForeColor = [System.Drawing.Color]::White
        $bo.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Bold)
        $bo.Add_Click({
            $t = $this.FindForm().Tag
            $act = $t.Action
            $this.FindForm().Close()
            if ($act) { try { & $act } catch { Write-PelLog "Bestellungen öffnen: $($_.Exception.Message)" 'WARN' } }
        })
        $f.Controls.Add($bo)
        $bc = New-Object System.Windows.Forms.Button
        $bc.Text = 'Schließen'
        $bc.Location = New-Object System.Drawing.Point(312, 206)
        $bc.Size = New-Object System.Drawing.Size(160, 40)
        $bc.FlatStyle = 'Flat'
        $bc.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $bc.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
        $bc.ForeColor = [System.Drawing.Color]::White
        $bc.Add_Click({ $this.FindForm().Close() })
        $f.Controls.Add($bc)
        $f.Tag = @{ Count = 0; Head = $lh; List = $lb; Open = $bo; Action = $null }
        $f.Add_FormClosed({ $script:PelOrderNotify = $null })
        $script:PelOrderNotify = $f
        $f.Show()
    }
    $t = $f.Tag
    $t.Count++
    $t.List.Items.Insert(0, ('[{0}] {1}' -f (Get-Date -Format 'HH:mm'), (Limit-PelText $Line 300)))
    while ($t.List.Items.Count -gt 100) { $t.List.Items.RemoveAt($t.List.Items.Count - 1) }
    $t.Head.Text = ([PelI18n]::Tr("{0}: {1} neue Meldung(en)") -f (Limit-PelText $Heading 50), $t.Count)
    if ($OpenAction) { $t.Action = $OpenAction }
    $t.Open.Visible = [bool]$t.Action
    $t.Open.Text = if ($OpenText) { $OpenText } else { [PelI18n]::Tr('Bestellungen öffnen') }
    if ($f.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { $f.WindowState = [System.Windows.Forms.FormWindowState]::Normal }
    try { [System.Media.SystemSounds]::Exclamation.Play() } catch { }
}

# Weitere Orga-PCs benachrichtigen (Zeile "Orga:" in der Speisekarte). Geht direkt an deren
# Control Center (Live-Status-Port 9928), signiert wie der Live-Status:
#   PEORD1|Id|Veranstaltung|Text|ZeitMs|HMAC
function New-PelOrderWire([string]$EventName, [string]$Text) {
    $id = ([guid]::NewGuid().ToString('N')).Substring(0, 16)
    $core = 'PEORD1|{0}|{1}|{2}|{3}' -f $id, (ConvertTo-PelWireField $EventName 60), (ConvertTo-PelWireField $Text 300), (Get-PelNowMs)
    return "$core|$(Get-PelHmacBase64 -Text $core)"
}

function ConvertFrom-PelOrderWire([string]$Text) {
    if ($Text.Length -gt 1000) { return $null }
    $f = $Text -split '\|'
    if ($f.Count -ne 6 -or $f[0] -ne 'PEORD1' -or $f[1] -notmatch '^[0-9a-f]{16}$') { return $null }
    if (-not (Test-PelHmac -Text (($f[0..4]) -join '|') -Signature $f[5])) { return $null }
    $ts = [long]0
    if (-not [long]::TryParse($f[4], [ref]$ts) -or [Math]::Abs((Get-PelNowMs) - $ts) -gt 600000) { return $null }
    return [pscustomobject]@{ Id = $f[1]; Event = (Limit-PelText $f[2] 60); Text = (Limit-PelText $f[3] 300) }
}

function Send-PelOrderToOrgas([string[]]$Ips, [string]$EventName, [string]$Text) {
    if (@($Ips).Count -eq 0) { return }
    $own = Get-PelLocalIpSet
    $bytes = [System.Text.Encoding]::UTF8.GetBytes((New-PelOrderWire $EventName $Text))
    $u = $null
    try {
        $u = New-Object System.Net.Sockets.UdpClient
        foreach ($ip in @($Ips)) {
            if ($own.ContainsKey($ip)) { continue }
            for ($i = 0; $i -lt 2; $i++) { try { [void]$u.Send($bytes, $bytes.Length, $ip, [int]$script:PelStatusPort) } catch { } }
        }
    } catch { Write-PelLog -Level 'INTRANET' -Message "Orga-Meldung: $($_.Exception.Message)" }
    finally { if ($u) { try { $u.Close() } catch { } } }
}

# Erzeugt die komplette Seite. $Mode: 'server' (ausgeliefert, mit Formularen und
# automatischem Neuladen) oder 'preview' (Vorschau im Baukasten, ohne Netzwerk).
# $Embed: Aufruf aus dem Manager - dann erscheinen "Mitspielen"-Buttons (pel-join://).
function Build-PelIntranetHtml {
    param($Cfg, [string]$Mode = 'server', [bool]$Embed = $false, [int64]$Rev = 0)
    $en = ($script:PelLang -eq 'en')
    $culture = [System.Globalization.CultureInfo]::GetCultureInfo($(if ($en) { 'en-GB' } else { 'de-DE' }))
    $h = { param($s) ConvertTo-PelHtml $s }
    $acc = [string]$Cfg.Event.Accent
    if ($acc -notmatch '^#[0-9a-f]{6}$') { $acc = '#f28c28' }
    $server = ($Mode -eq 'server')
    $sb = New-Object System.Text.StringBuilder

    # Als normaler Text (kein Here-String), damit Build-PEL-Exe.ps1 ihn nicht als
    # eingebettetes PowerShell-Skript prüft - der Inhalt ist CSS.
    $css = 'body{margin:0;background:#191919;color:#e8e8e8;font-family:"Segoe UI",Tahoma,Arial,sans-serif;font-size:15px;line-height:1.45}
a{color:ACC}
.wrap{max-width:1240px;margin:0 auto;padding:18px}
.hero{background:#232323;border:1px solid #383838;border-radius:10px;padding:20px 24px;display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center}
.hero-l{display:flex;align-items:center}
.logo{max-height:80px;max-width:180px;margin-right:18px;border-radius:6px}
.logo.ls{max-height:52px;max-width:120px}
.logo.ll{max-height:130px;max-width:300px}
.banner{display:block;width:100%;height:auto;border-radius:10px;margin-bottom:12px;border:1px solid #383838}
.hbg{background-size:cover;background-position:center;min-height:190px}
.hbg h1,.hbg .kick,.hbg .meta{text-shadow:0 1px 3px #000}
.logos{display:flex;flex-wrap:wrap;align-items:center;justify-content:center}
.srow{display:flex;align-items:center;margin:2px 0;overflow-x:auto}
.slab{display:inline-block;width:30px;color:#aab2bd;font-weight:bold;flex:0 0 30px}
.seat{display:inline-block;min-width:36px;height:30px;line-height:30px;margin:2px;padding:0 3px;text-align:center;border-radius:5px;font-size:11px;background:#2f2f2f;border:1px solid #454545;overflow:hidden;white-space:nowrap;flex:0 0 auto}
.s-res{background:#5a3f14;border-color:ACC}
.s-in{background:#1d5a33;border-color:#3cb371}
.s-blk{background:#1b1b1b;color:#555555;border-style:dashed}
.sgap{display:inline-block;width:16px;flex:0 0 16px}
.legend{font-size:12px;color:#aab2bd;margin:6px 0}
.legend span{display:inline-block;width:12px;height:12px;border-radius:3px;margin:0 4px 0 12px;vertical-align:middle}
.lg{display:inline-block;margin:8px 14px;text-align:center;text-decoration:none;color:#aab2bd;font-size:12px}
.lg img{display:block;max-height:80px;max-width:190px;margin:0 auto 4px auto}
.kick{color:ACC;letter-spacing:2px;text-transform:uppercase;font-size:12px;font-weight:bold}
h1{margin:4px 0;font-size:30px;line-height:1.15;font-family:"Segoe UI Semibold","Segoe UI",Tahoma,Arial,sans-serif}
.meta{color:#aab2bd;font-size:14px}
.cd{display:flex;align-items:center;margin-top:8px}
.cd div{background:#161616;border:1px solid #383838;border-radius:8px;min-width:62px;text-align:center;padding:6px 8px;margin-left:8px}
.cd b{display:block;font-size:22px;line-height:1.2}
.cd span{font-size:11px;color:#9aa3ad}
.cdt{color:#aab2bd;font-size:13px;margin-left:10px;max-width:120px}
.grid{display:flex;flex-wrap:wrap;margin:8px -8px 0 -8px}
.card{flex:1 1 300px;background:#232323;border:1px solid #383838;border-radius:10px;padding:16px 18px;margin:8px;min-width:260px}
.wide{flex:1 1 100%}
.card h2{margin:0 0 10px 0;font-size:17px;font-family:"Segoe UI Semibold","Segoe UI",Tahoma,Arial,sans-serif}
.item{background:#2b2b2b;border-radius:6px;padding:8px 12px;margin-bottom:8px}
.row{display:flex;justify-content:space-between;align-items:center}
.row .l{padding-right:10px}
.muted{color:#aab2bd;font-size:13px}
.empty{color:#8c949e;font-size:13px;font-style:italic}
.tag{font-size:11px;color:#9fd8b0;border:1px solid #3c6b4c;border-radius:10px;padding:1px 8px;margin-left:8px}
.btn{display:inline-block;background:ACC;color:#141414;padding:6px 14px;border-radius:6px;font-weight:bold;text-decoration:none;border:0;font-family:inherit;font-size:14px;cursor:pointer}
.bar{background:#161616;border-radius:4px;height:8px;margin-top:4px}
.bar i{display:block;background:ACC;height:8px;border-radius:4px}
ul{margin:0;padding-left:20px}
li{margin:3px 0}
input[type=text]{background:#141414;border:1px solid #484848;color:#eeeeee;padding:6px 8px;border-radius:5px;font-family:inherit;font-size:14px;width:100%;box-sizing:border-box;margin-bottom:6px}
label{display:block;margin:4px 0}
select{background:#141414;border:1px solid #484848;color:#eeeeee;padding:3px 4px;border-radius:5px;font-family:inherit;font-size:14px;margin-left:8px}
p{margin:0 0 8px 0}
.foot{color:#8c949e;font-size:12px;text-align:center;margin:18px 0 6px 0}'
    $css = $css.Replace('ACC', $acc)

    [void]$sb.Append('<!DOCTYPE html><html><head><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">')
    [void]$sb.Append('<title>').Append((& $h $Cfg.Event.Title)).Append('</title><style>').Append($css).Append('</style></head><body><div class="wrap">')

    # ---- Kopfbereich mit Countdown ----
    # Eigenes Kopfbild: als Banner über dem Kopfbereich oder als dessen Hintergrund.
    # HideTitle blendet Begrüßung, Titel, Datum und Ort aus (stehen dann meist im Bild).
    $headerSrc = Get-PelIntranetImageSrc (Get-PelIntranetHeaderPath $Cfg) $server '/pel/header' 6291456
    $headerBg = ($headerSrc -and $Cfg.Event.HeaderMode -eq 'background')
    if ($headerSrc -and -not $headerBg) { [void]$sb.Append('<img class="banner" src="').Append((& $h $headerSrc)).Append('" alt="">') }
    $showTitle = -not ([bool]$Cfg.Event.HideTitle -and $headerSrc)
    $logoSrc = Get-PelIntranetImageSrc (Get-PelIntranetLogoPath $Cfg) $server '/pel/logo'
    $cdMs = 0
    if ($Cfg.Event.Countdown) {
        $dt = [datetime]::MinValue
        if ([datetime]::TryParseExact([string]$Cfg.Event.Countdown, 'yyyy-MM-ddTHH:mm', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeLocal, [ref]$dt)) {
            $cdMs = ([DateTimeOffset]$dt).ToUnixTimeMilliseconds()
        }
    }
    # Banner mit ausgeblendetem Titel, ohne Logo und Countdown: kein leerer Kasten darunter
    $heroNeeded = $showTitle -or $logoSrc -or ($cdMs -gt 0) -or $headerBg
    if ($heroNeeded) {
        if ($headerBg) {
            [void]$sb.Append('<div class="hero hbg" style="background-image:linear-gradient(rgba(0,0,0,0.45),rgba(0,0,0,0.55)),url(').Append((& $h $headerSrc)).Append(')">')
        } else { [void]$sb.Append('<div class="hero">') }
        [void]$sb.Append('<div class="hero-l">')
        $lsz = switch ([string]$Cfg.Event.LogoSize) { 'S' { 'logo ls' } 'L' { 'logo ll' } default { 'logo' } }
        if ($logoSrc) { [void]$sb.Append('<img class="').Append($lsz).Append('" src="').Append((& $h $logoSrc)).Append('" alt="">') }
        if ($showTitle) {
            [void]$sb.Append('<div><div class="kick">').Append((& $h (Get-PelText 'Willkommen im Intranet' 'Welcome to the intranet'))).Append('</div>')
            [void]$sb.Append('<h1>').Append((& $h $Cfg.Event.Title)).Append('</h1>')
            $meta = @(@($Cfg.Event.Date, $Cfg.Event.Place) | Where-Object { $_ })
            if ($Cfg.Event.Organizer) { $meta += ((Get-PelText 'Veranstalter: ' 'Organizer: ') + $Cfg.Event.Organizer) }
            if ($meta.Count -gt 0) { [void]$sb.Append('<div class="meta">').Append((& $h ($meta -join '  ·  '))).Append('</div>') }
            [void]$sb.Append('</div>')
        }
        [void]$sb.Append('</div>')
        if ($cdMs -gt 0) {
            $done = & $h (Get-PelText 'Es geht los!' "Let's go!")
            [void]$sb.Append('<div class="cd" id="pel-cd" data-t="').Append($cdMs).Append('" data-done="').Append($done).Append('">')
            foreach ($p in @(@('d', (Get-PelText 'Tage' 'days')), @('h', (Get-PelText 'Std.' 'hrs')), @('m', (Get-PelText 'Min.' 'min')), @('s', (Get-PelText 'Sek.' 'sec')))) {
                [void]$sb.Append('<div><b id="pel-cd-').Append($p[0]).Append('">-</b><span>').Append((& $h $p[1])).Append('</span></div>')
            }
            if ($Cfg.Event.CountdownText) { [void]$sb.Append('<span class="cdt">').Append((& $h $Cfg.Event.CountdownText)).Append('</span>') }
            [void]$sb.Append('</div>')
        }
        [void]$sb.Append('</div>')
    }
    [void]$sb.Append('<div class="grid">')

    # ---- Blöcke ----
    $visible = @($Cfg.Blocks | Where-Object { $_.Visible })
    if ($visible.Count -eq 0) {
        [void]$sb.Append('<div class="card wide"><div class="empty">').Append((& $h (Get-PelText 'Noch keine Blöcke - im Baukasten hinzufügen.' 'No blocks yet - add some in the builder.'))).Append('</div></div>')
    }
    foreach ($b in $visible) {
        $cls = 'card'
        if ($b.Wide) { $cls = 'card wide' }
        $bid = & $h $b.Id
        [void]$sb.Append('<div class="').Append($cls).Append('" id="b-').Append($bid).Append('"><h2>').Append((& $h $b.Title))
        if ($b.Type -in @('events', 'results', 'tourney')) { [void]$sb.Append('<span class="tag">live</span>') }
        [void]$sb.Append('</h2>')
        $lines = @(Get-PelIntranetLines $b.Text)
        $emptyTxt = & $h (Get-PelText 'Noch nichts eingetragen.' 'Nothing here yet.')
        switch ($b.Type) {
            'news' {
                if ($lines.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append($emptyTxt).Append('</div>') }
                foreach ($ln in $lines) {
                    $pp = Split-PelIntranetLine $ln
                    [void]$sb.Append('<div class="item"><div><b>').Append((& $h $pp[0])).Append('</b></div>')
                    if ($pp[1]) { [void]$sb.Append('<div class="muted">').Append((& $h $pp[1])).Append('</div>') }
                    [void]$sb.Append('</div>')
                }
            }
            'schedule' {
                if ($lines.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append($emptyTxt).Append('</div>') }
                foreach ($ln in $lines) {
                    $pp = Split-PelIntranetLine $ln
                    [void]$sb.Append('<div class="item row"><span class="l muted">').Append((& $h $pp[0])).Append('</span><span>').Append((& $h $pp[1])).Append('</span></div>')
                }
            }
            'seating' {
                if ($lines.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append($emptyTxt).Append('</div>') }
                foreach ($ln in $lines) {
                    $pp = Split-PelIntranetLine $ln
                    $who = $pp[1]
                    if (-not $who) { $who = Get-PelText 'frei' 'free' }
                    [void]$sb.Append('<div class="item row"><span class="l"><b>').Append((& $h $pp[0])).Append('</b></span><span>').Append((& $h $who)).Append('</span></div>')
                }
            }
            'servers' {
                if ($lines.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Server eingetragen.' 'No servers entered yet.'))).Append('</div>') }
                foreach ($ln in $lines) {
                    $pp = Split-PelIntranetLine $ln
                    $game = $pp[0]
                    $addr = $pp[1]
                    if (-not $addr -and $game -match '^[0-9.:]+$') { $addr = $game; $game = '' }
                    [void]$sb.Append('<div class="item row"><span class="l"><b>').Append((& $h $game)).Append('</b><br><span class="muted">').Append((& $h $addr)).Append('</span></span>')
                    if ($Embed -and $addr -match '^\s*(\d{1,3}(\.\d{1,3}){3})(:(\d{1,5}))?\s*$') {
                        $jip = $matches[1]
                        $jport = 0
                        if ($matches[4]) { $jport = [int]$matches[4] }
                        $href = 'pel-join://' + $jip + ':' + $jport + '/?g=' + [Uri]::EscapeDataString($game)
                        if ($jport -le 0 -or $jport -gt 65535) { $href = 'pel-join://' + $jip + ':1/?g=' + [Uri]::EscapeDataString($game) + '&noport=1' }
                        [void]$sb.Append('<a class="btn" href="').Append((& $h $href)).Append('">').Append((& $h (Get-PelText 'Mitspielen' 'Join'))).Append('</a>')
                    }
                    [void]$sb.Append('</div>')
                }
            }
            'events' {
                if ($lines.Count -gt 0) { [void]$sb.Append('<p class="muted">').Append((& $h ($lines -join ' '))).Append('</p>') }
                $evs = @()
                try {
                    if ([System.IO.File]::Exists($script:PelEventsPath)) {
                        $now = Get-PelNowSec
                        $evs = @(Read-PelTextFile $script:PelEventsPath | ConvertFrom-Json | Where-Object { $_ -and -not $_.Cancelled -and ([int64]$_.Start + 21600) -gt $now } | Sort-Object { [int64]$_.Start } | Select-Object -First 6)
                    }
                } catch { $evs = @() }
                if ($evs.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Zurzeit ist kein Spieleabend geplant.' 'No game night planned right now.'))).Append('</div>') }
                foreach ($ev in $evs) {
                    $when = ([DateTimeOffset]::FromUnixTimeSeconds([int64]$ev.Start).LocalDateTime).ToString('ddd dd.MM., HH:mm', $culture)
                    $sub = @(@((Limit-PelText ([string]$ev.Game) 60), (Limit-PelText ([string]$ev.Organizer) 40)) | Where-Object { $_ }) -join '  ·  '
                    [void]$sb.Append('<div class="item"><div class="row"><b class="l">').Append((& $h (Limit-PelText ([string]$ev.Title) 80))).Append('</b><span class="muted">').Append((& $h $when)).Append('</span></div>')
                    if ($sub) { [void]$sb.Append('<div class="muted">').Append((& $h $sub)).Append('</div>') }
                    [void]$sb.Append('</div>')
                }
            }
            'results' {
                if ($lines.Count -gt 0) { [void]$sb.Append('<p class="muted">').Append((& $h ($lines -join ' '))).Append('</p>') }
                $res = @()
                try { $res = @(Get-PelMmResults | Sort-Object { [string]$_.Time } -Descending | Select-Object -First 8) } catch { $res = @() }
                if ($res.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Ergebnisse - sie erscheinen hier, sobald in Option 4 gespielt wurde.' 'No results yet - they show up here once games are played in option 4.'))).Append('</div>') }
                foreach ($r in $res) {
                    $teamTexts = @()
                    $ti = 0
                    foreach ($t in @($r.Teams)) {
                        $names = @(@($t) | ForEach-Object { $n = $r.Names[[string]$_]; if (-not $n) { $n = '?' }; $n }) -join ', '
                        if ([int]$r.Winner -eq $ti) { $names = ([string][char]0x2605) + ' ' + $names }
                        $teamTexts += $names
                        $ti++
                    }
                    $vs = $teamTexts -join '  vs.  '
                    if ([int]$r.Winner -eq -1) { $vs += '  (' + (Get-PelText 'Unentschieden' 'draw') + ')' }
                    $time = ''
                    $dto = [DateTimeOffset]::MinValue
                    if ([DateTimeOffset]::TryParse([string]$r.Time, [ref]$dto)) { $time = $dto.LocalDateTime.ToString('dd.MM. HH:mm', $culture) }
                    [void]$sb.Append('<div class="item"><div class="row"><b class="l">').Append((& $h "$($r.Game) ($($r.Mode))")).Append('</b><span class="muted">').Append((& $h $time)).Append('</span></div>')
                    [void]$sb.Append('<div class="muted">').Append((& $h $vs)).Append('</div></div>')
                }
            }
            'tourney' {
                $all = @()
                try { $all = @(Get-PelTournaments) } catch { $all = @() }
                $want = ($lines -join ' ').Trim()
                $tt = $null
                if ($want) { $tt = $all | Where-Object { $_.Name -eq $want } | Select-Object -First 1 }
                if (-not $tt) { $tt = $all | Sort-Object @{ Expression = { switch ($_.State) { 'running' { 0 } 'signup' { 1 } default { 2 } } } }, @{ Expression = { [string]$_.Created }; Descending = $true } | Select-Object -First 1 }
                if (-not $tt) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch kein Turnier - in Option 4 unter "Turniere" anlegen.' 'No tournament yet - create one in option 4 under "Tournaments".'))).Append('</div>'); break }
                [void]$sb.Append('<div class="muted">').Append((& $h ("$($tt.Name)  ·  $($tt.Game)  ·  $(Get-PelTrFormatText $tt)  ·  $(Get-PelTrStateText $tt)"))).Append('</div>')
                if ($tt.Champion) { [void]$sb.Append('<div class="item"><b>').Append((& $h ((Get-PelText 'Sieger: {0}' 'Winner: {0}') -f (Get-PelTrEntrantName $tt $tt.Champion)))).Append('</b></div>') }
                if ($tt.State -eq 'signup') {
                    [void]$sb.Append('<p>').Append((& $h ((Get-PelText 'Anmeldung offen - bisher {0}: ' 'Sign-up open - so far {0}: ') -f @($tt.Signups).Count))).Append((& $h ((@($tt.Signups) | ForEach-Object { $_.Name }) -join ', '))).Append('</p>')
                } elseif ($tt.Format -eq 'rr') {
                    $pos = 0
                    foreach ($stg in @(Get-PelTrStandings $tt)) {
                        $pos++
                        [void]$sb.Append('<div class="item r"><span class="l"><b>').Append($pos).Append('.</b> ').Append((& $h $stg.Name)).Append('</span><span class="muted">').Append((& $h ((Get-PelText '{0} Sp. · {1} S · {2} U · {3} N · ' '{0} pl. · {1} W · {2} D · {3} L · ') -f $stg.Played, $stg.Won, $stg.Draw, $stg.Lost))).Append('<b>').Append($stg.Points).Append((& $h (Get-PelText ' Pkt.' ' pts'))).Append('</b></span></div>')
                    }
                } else {
                    foreach ($rnd in @(@($tt.Matches) | ForEach-Object { [int]$_.Round } | Sort-Object -Unique)) {
                        [void]$sb.Append('<div class="muted" style="margin-top:6px">').Append((& $h (Get-PelTrRoundName $tt $rnd))).Append('</div>')
                        foreach ($mt in @(@($tt.Matches) | Where-Object { [int]$_.Round -eq $rnd -and $_.A -ne 'BYE' -and $_.B -ne 'BYE' } | Sort-Object Slot)) {
                            $na = if ($mt.A) { Get-PelTrEntrantName $tt $mt.A } else { '...' }
                            $nb = if ($mt.B) { Get-PelTrEntrantName $tt $mt.B } else { '...' }
                            $ha = & $h $na; $hb = & $h $nb
                            if ($mt.Confirmed -and $mt.Winner -eq 'A') { $ha = '<b>' + $ha + '</b>' }
                            if ($mt.Confirmed -and $mt.Winner -eq 'B') { $hb = '<b>' + $hb + '</b>' }
                            [void]$sb.Append('<div class="item r"><span>').Append($ha).Append('</span><span class="muted">vs.</span><span>').Append($hb).Append('</span></div>')
                        }
                    }
                }
            }
            'downloads' {
                if ($lines.Count -gt 0) { [void]$sb.Append('<p class="muted">').Append((& $h ($lines -join ' '))).Append('</p>') }
                $files = @(Get-PelIntranetDownloads)
                if ($files.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Dateien bereitgestellt.' 'No files provided yet.'))).Append('</div>') }
                foreach ($f in $files) {
                    [void]$sb.Append('<div class="item row"><span class="l">').Append((& $h $f.Name)).Append(' <span class="muted">').Append((& $h (Format-PelBytes $f.Length))).Append('</span></span>')
                    if ($server) { [void]$sb.Append('<a href="/dl/').Append([Uri]::EscapeDataString($f.Name)).Append('">').Append((& $h (Get-PelText 'Laden' 'Download'))).Append('</a>') }
                    [void]$sb.Append('</div>')
                }
            }
            'rules' {
                if ($lines.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append($emptyTxt).Append('</div>') }
                else {
                    [void]$sb.Append('<ul>')
                    foreach ($ln in $lines) { [void]$sb.Append('<li>').Append((& $h $ln)).Append('</li>') }
                    [void]$sb.Append('</ul>')
                }
            }
            'seatmap' {
                $sm = Get-PelIntranetSeatMap $b
                foreach ($nt in $sm.Notes) { [void]$sb.Append('<p class="muted">').Append((& $h $nt)).Append('</p>') }
                if ($sm.Rows.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch kein Sitzplan - im Baukasten Reihen eintragen, z. B. "A | 1-12".' 'No seat map yet - enter rows in the builder, e.g. "A | 1-12".'))).Append('</div>'); break }
                $occ = @{}
                foreach ($e in @(Get-PelIntranetSeatEntries $b)) { if ($e.Seat) { $occ[$e.Seat.ToUpperInvariant()] = $e } }
                $free = New-Object System.Collections.Generic.List[string]
                $nIn = 0; $nRes = 0; $nAll = 0
                foreach ($seat in $sm.All) {
                    if ($sm.Blocked.ContainsKey($seat)) { continue }
                    $nAll++
                    if ($occ.ContainsKey($seat)) { if ($occ[$seat].State -eq 'eingecheckt') { $nIn++ } else { $nRes++ } } else { $free.Add($seat) }
                }
                [void]$sb.Append('<div class="muted">').Append((& $h ((Get-PelText '{0} Plätze · {1} reserviert · {2} eingecheckt · {3} frei' '{0} seats · {1} reserved · {2} checked in · {3} free') -f $nAll, $nRes, $nIn, $free.Count))).Append('</div>')
                [void]$sb.Append('<div class="legend"><span style="background:#2f2f2f;border:1px solid #454545"></span>').Append((& $h (Get-PelText 'frei' 'free')))
                [void]$sb.Append('<span style="background:#5a3f14"></span>').Append((& $h (Get-PelText 'reserviert' 'reserved')))
                [void]$sb.Append('<span style="background:#1d5a33"></span>').Append((& $h (Get-PelText 'eingecheckt' 'checked in')))
                [void]$sb.Append('<span style="background:#1b1b1b;border:1px dashed #555555"></span>').Append((& $h (Get-PelText 'gesperrt' 'blocked'))).Append('</div>')
                if ($server) { [void]$sb.Append('<div class="item" data-my="').Append($bid).Append('" style="display:none"></div>') }
                foreach ($row in $sm.Rows) {
                    [void]$sb.Append('<div class="srow"><span class="slab">').Append((& $h $row.Label)).Append('</span>')
                    foreach ($c in $row.Cells) {
                        if (-not $c) { [void]$sb.Append('<span class="sgap"></span>'); continue }
                        $num = $c.Substring($row.Label.Length)
                        if ($sm.Blocked.ContainsKey($c)) { [void]$sb.Append('<span class="seat s-blk" title="').Append((& $h "$c - $(Get-PelText 'gesperrt' 'blocked')")).Append('">').Append((& $h $num)).Append('</span>'); continue }
                        if ($occ.ContainsKey($c)) {
                            $e = $occ[$c]
                            $cls = if ($e.State -eq 'eingecheckt') { 'seat s-in' } else { 'seat s-res' }
                            $short = if ($e.Name.Length -gt 7) { $e.Name.Substring(0, 7) } else { $e.Name }
                            [void]$sb.Append('<span class="').Append($cls).Append('" title="').Append((& $h "$c - $($e.Name)")).Append('">').Append((& $h $short)).Append('</span>')
                        } else {
                            [void]$sb.Append('<span class="seat" title="').Append((& $h "$c - $(Get-PelText 'frei' 'free')")).Append('">').Append((& $h $num)).Append('</span>')
                        }
                    }
                    [void]$sb.Append('</div>')
                }
                if ($b.Closed) { [void]$sb.Append('<div class="item"><b>').Append((& $h (Get-PelText 'Die Platzwahl ist geschlossen - Änderungen bitte über die Orga.' 'Seat selection is closed - please ask the organizers for changes.'))).Append('</b></div>') }
                elseif ($server) {
                    [void]$sb.Append('<form method="post" action="/pel/submit" style="margin-top:10px"><input type="hidden" name="b" value="').Append($bid).Append('">')
                    if ($Embed) { [void]$sb.Append('<input type="hidden" name="e" value="1">') }
                    [void]$sb.Append('<input type="text" name="n" maxlength="32" placeholder="').Append((& $h (Get-PelText 'Dein Name / Nickname (steht auf dem Sitzplan)' 'Your name / nickname (shown on the seat map)'))).Append('">')
                    [void]$sb.Append('<div class="row"><span class="l"><select name="s" style="margin-left:0"><option value="">').Append((& $h (Get-PelText '- Platz wählen (leer = Reservierung aufheben) -' '- choose seat (empty = cancel reservation) -'))).Append('</option>')
                    foreach ($fs in $free) { [void]$sb.Append('<option value="').Append((& $h $fs)).Append('">').Append((& $h $fs)).Append('</option>') }
                    [void]$sb.Append('</select></span><button class="btn" type="submit">').Append((& $h (Get-PelText 'Platz reservieren' 'Reserve seat'))).Append('</button></div>')
                    [void]$sb.Append('<div class="muted">').Append((& $h (Get-PelText 'Ein Platz pro PC - änderbar bis zum Check-in am Orga-Tisch.' 'One seat per PC - can be changed until you check in at the organizer desk.'))).Append('</div></form>')
                }
            }
            'logos' {
                $meta = @{}
                foreach ($ln in $lines) {
                    $pp = @($ln -split '\|' | ForEach-Object { $_.Trim() })
                    if (-not $pp[0]) { continue }
                    $lnk = ''
                    $u = $null
                    if ($pp.Count -ge 3 -and $pp[2] -match '^https?://' -and [Uri]::TryCreate($pp[2], [UriKind]::Absolute, [ref]$u) -and -not $u.UserInfo) { $lnk = $u.AbsoluteUri }
                    $meta[$pp[0].ToLowerInvariant()] = @{ Name = $(if ($pp.Count -ge 2) { Limit-PelText $pp[1] 60 } else { '' }); Url = $lnk }
                }
                $files = @(Get-PelIntranetLogoFiles)
                if ($files.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Logos - im Baukasten unter "Bilder hinzufügen".' 'No logos yet - use "Add images" in the builder.'))).Append('</div>'); break }
                [void]$sb.Append('<div class="logos">')
                foreach ($f in $files) {
                    $src = Get-PelIntranetImageSrc $f.FullName $server ('/pel/img/' + [Uri]::EscapeDataString($f.Name)) 1048576
                    if (-not $src) { continue }
                    $mm = $meta[$f.Name.ToLowerInvariant()]
                    $cap = if ($mm -and $mm.Name) { $mm.Name } else { '' }
                    if ($mm -and $mm.Url) { [void]$sb.Append('<a class="lg" href="').Append((& $h $mm.Url)).Append('">') } else { [void]$sb.Append('<span class="lg">') }
                    [void]$sb.Append('<img src="').Append((& $h $src)).Append('" alt="').Append((& $h $cap)).Append('">')
                    if ($cap) { [void]$sb.Append((& $h $cap)) }
                    if ($mm -and $mm.Url) { [void]$sb.Append('</a>') } else { [void]$sb.Append('</span>') }
                }
                [void]$sb.Append('</div>')
            }
            'contact' {
                if ($lines.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append($emptyTxt).Append('</div>') }
                foreach ($ln in $lines) { [void]$sb.Append('<div>').Append((& $h $ln)).Append('</div>') }
            }
            'text' {
                $paras = @(([string]$b.Text) -split "`n\s*`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
                if ($paras.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append($emptyTxt).Append('</div>') }
                foreach ($pa in $paras) { [void]$sb.Append('<p>').Append(((& $h $pa) -replace "`n", '<br>')).Append('</p>') }
            }
            'poll' {
                $opts = @(Get-PelIntranetPollOptions $b)
                if ($opts.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Antworten eingetragen.' 'No answers entered yet.'))).Append('</div>'); break }
                $counts = New-Object int[] $opts.Count
                $total = 0
                foreach ($e in @(Get-PelIntranetEntries $b.Id)) {
                    $v = -1
                    $parts = ([string]$e) -split "`t"
                    if ($parts.Count -ge 2 -and [int]::TryParse($parts[1], [ref]$v) -and $v -ge 0 -and $v -lt $opts.Count) { $counts[$v]++; $total++ }
                }
                if ($server) { [void]$sb.Append('<form method="post" action="/pel/submit"><input type="hidden" name="b" value="').Append($bid).Append('">'); if ($Embed) { [void]$sb.Append('<input type="hidden" name="e" value="1">') } }
                for ($i = 0; $i -lt $opts.Count; $i++) {
                    $pct = 0
                    if ($total -gt 0) { $pct = [int][Math]::Round(100.0 * $counts[$i] / $total) }
                    [void]$sb.Append('<div class="item">')
                    if ($server) { [void]$sb.Append('<label><input type="radio" name="v" value="').Append($i).Append('"> ') } else { [void]$sb.Append('<label>') }
                    [void]$sb.Append((& $h $opts[$i])).Append(' <span class="muted">(').Append($counts[$i]).Append(')</span></label>')
                    [void]$sb.Append('<div class="bar"><i style="width:').Append($pct).Append('%"></i></div></div>')
                }
                [void]$sb.Append('<div class="row"><span class="muted">').Append((& $h ((Get-PelText '{0} Stimme(n) - eine pro PC, änderbar' '{0} vote(s) - one per PC, can be changed') -f $total))).Append('</span>')
                if ($server) { [void]$sb.Append('<button class="btn" type="submit">').Append((& $h (Get-PelText 'Abstimmen' 'Vote'))).Append('</button></div></form>') } else { [void]$sb.Append('</div>') }
            }
            'menu' {
                $menu = Get-PelIntranetMenu $b
                foreach ($nt in $menu.Notes) { [void]$sb.Append('<p class="muted">').Append((& $h $nt)).Append('</p>') }
                # Lieferdienste und Lokale (Links öffnen im normalen Browser - der Manager fragt vorher)
                $mapLink = ''
                # LAN ohne Internet ("Internet: nein") oder nur eigenes Angebot der Orga: dann
                # fuehren Lieferdienst-Links und die Karte ins Leere - nicht anzeigen.
                $onlyOwn = ($menu.Items.Count -gt 0 -and @($menu.Items | Where-Object { -not $_.Own }).Count -eq 0)
                if ($Cfg.Event.Place -and -not $menu.NoInternet -and -not $onlyOwn) { $mapLink = 'https://www.openstreetmap.org/search?query=' + [Uri]::EscapeDataString((Get-PelText 'Restaurant ' 'restaurant ') + [string]$Cfg.Event.Place) }
                if (-not $menu.NoInternet -and ($menu.Links.Count -gt 0 -or $mapLink)) {
                    [void]$sb.Append('<div class="muted" style="margin-top:6px"><b>').Append((& $h (Get-PelText 'Lieferdienste & Lokale in der Nähe' 'Delivery services & places nearby'))).Append('</b></div>')
                    foreach ($lk in $menu.Links) {
                        [void]$sb.Append('<div class="item row"><span class="l">')
                        if ($lk.Url) { [void]$sb.Append('<a href="').Append((& $h $lk.Url)).Append('">').Append((& $h $lk.Name)).Append('</a>') } else { [void]$sb.Append('<b>').Append((& $h $lk.Name)).Append('</b>') }
                        [void]$sb.Append('</span><span class="muted">').Append((& $h ($lk.Info -join '  ·  '))).Append('</span></div>')
                    }
                    if ($mapLink) { [void]$sb.Append('<div class="item"><a href="').Append((& $h $mapLink)).Append('">').Append((& $h ((Get-PelText 'Restaurants in der Nähe von {0} (Karte)' 'Restaurants near {0} (map)') -f $Cfg.Event.Place))).Append('</a></div>') }
                }
                if ($menu.Items.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Speisekarte - im Baukasten unter "Inhalt" eintragen.' 'No menu yet - add it in the builder under "Content".'))).Append('</div>'); break }
                # Übersicht für alle (ohne Namen): Anzahl Bestellungen und beliebteste Artikel
                $active = @(Get-PelIntranetOrders $b $menu | Where-Object { $_.State -ne 'storniert' })
                if ($active.Count -gt 0) {
                    $tot = Get-PelIntranetOrderTotals $active
                    $top = @($tot.Rows | Select-Object -First 6 | ForEach-Object { "$($_.Qty)x $($_.Name)" }) -join ', '
                    [void]$sb.Append('<div class="muted" style="margin:6px 0">').Append((& $h ((Get-PelText '{0} Bestellung(en) bisher - am beliebtesten: {1}' '{0} order(s) so far - most popular: {1}') -f $active.Count, $top))).Append('</div>')
                }
                if ($server) { [void]$sb.Append('<div class="item" data-my="').Append($bid).Append('" style="display:none"></div>') }
                if ($b.Closed) { [void]$sb.Append('<div class="item"><b>').Append((& $h (Get-PelText 'Bestellschluss - gerade werden keine Bestellungen angenommen.' 'Orders closed - no orders are being taken right now.'))).Append('</b></div>') }
                # Bestellbar ist nur, was online angeboten wird und nicht ausverkauft ist. Gibt es
                # nichts davon (z. B. nur Getränke an der Theke), entfällt das Bestellformular.
                $orderable = @($menu.Items | Where-Object { $_.Online -and -not $_.SoldOut }).Count
                $onSite = @($menu.Items | Where-Object { -not $_.Online }).Count
                $canOrder = ($server -and -not $b.Closed -and $orderable -gt 0)
                if ($onSite -gt 0) {
                    $legend = if ($orderable -gt 0) { Get-PelText 'Artikel mit Mengenauswahl bestellst du hier, alles mit "nur vor Ort" gibt es direkt an der Theke / Kasse.' 'Items with a quantity selection are ordered here, everything marked "on site only" is available directly at the counter / till.' } else { Get-PelText 'Alles hier gibt es direkt vor Ort an der Theke / Kasse - einfach hingehen.' 'Everything here is available on site at the counter / till - just go there.' }
                    [void]$sb.Append('<div class="muted" style="margin:6px 0">').Append((& $h $legend)).Append('</div>')
                }
                if ($canOrder) {
                    [void]$sb.Append('<form method="post" action="/pel/submit"><input type="hidden" name="b" value="').Append($bid).Append('">')
                    if ($Embed) { [void]$sb.Append('<input type="hidden" name="e" value="1">') }
                }
                $lastCat = $null
                for ($i = 0; $i -lt $menu.Items.Count; $i++) {
                    $it = $menu.Items[$i]
                    if ($it.Cat -ne $lastCat) {
                        $lastCat = $it.Cat
                        if ($it.Cat) { [void]$sb.Append('<div style="margin:10px 0 4px 0"><b>').Append((& $h $it.Cat)).Append('</b></div>') }
                    }
                    [void]$sb.Append('<div class="item row"><span class="l">')
                    if ($it.SoldOut) { [void]$sb.Append('<s class="muted">').Append((& $h $it.Name)).Append('</s>') } else { [void]$sb.Append((& $h $it.Name)) }
                    if ($it.Desc) { [void]$sb.Append(' <span class="muted">').Append((& $h $it.Desc)).Append('</span>') }
                    if ($it.Own) { [void]$sb.Append('<span class="tag">').Append((& $h (Get-PelText 'von der Orga' 'from the organizers'))).Append('</span>') }
                    if (-not $it.Online) { [void]$sb.Append('<span class="tag">').Append((& $h (Get-PelText 'nur vor Ort' 'on site only'))).Append('</span>') }
                    if ($it.SoldOut) { [void]$sb.Append('<span class="tag">').Append((& $h (Get-PelText 'ausverkauft' 'sold out'))).Append('</span>') }
                    [void]$sb.Append('</span><span>')
                    if ($null -ne $it.Price) { [void]$sb.Append((& $h (Format-PelIntranetMoney $it.Price))) }
                    if ($canOrder -and $it.Online -and -not $it.SoldOut) {
                        [void]$sb.Append(' <select name="q').Append($i).Append('">')
                        for ($qq = 0; $qq -le 10; $qq++) { [void]$sb.Append('<option value="').Append($qq).Append('">').Append($qq).Append('</option>') }
                        [void]$sb.Append('</select>')
                    }
                    [void]$sb.Append('</span></div>')
                }
                if ($canOrder) {
                    [void]$sb.Append('<input type="text" name="n" maxlength="32" placeholder="').Append((& $h (Get-PelText 'Dein Name (Pflicht)' 'Your name (required)'))).Append('">')
                    [void]$sb.Append('<input type="text" name="s" maxlength="16" placeholder="').Append((& $h (Get-PelText 'Platz / Tisch (z. B. B12)' 'Seat / table (e.g. B12)'))).Append('">')
                    [void]$sb.Append('<input type="text" name="c" maxlength="120" placeholder="').Append((& $h (Get-PelText 'Anmerkung (z. B. ohne Zwiebeln)' 'Note (e.g. no onions)'))).Append('">')
                    [void]$sb.Append('<div class="row"><span class="muted">').Append((& $h (Get-PelText 'Eine Bestellung pro PC - änderbar, bis die Orga bestellt hat. Alles auf 0 = zurückziehen.' 'One order per PC - can be changed until the organizers have ordered. Everything 0 = withdraw.'))).Append('</span><button class="btn" type="submit">').Append((& $h (Get-PelText 'Bestellen' 'Order'))).Append('</button></div></form>')
                }
            }
            'prices' {
                $pl = Get-PelIntranetPriceList $b
                foreach ($nt in $pl.Notes) { [void]$sb.Append('<p class="muted">').Append((& $h $nt)).Append('</p>') }
                if ($pl.Items.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Preise - im Baukasten unter "Inhalt" eintragen.' 'No prices yet - add them in the builder under "Content".'))).Append('</div>') }
                $lastCat = $null
                foreach ($it in $pl.Items) {
                    if ($it.Cat -ne $lastCat) {
                        $lastCat = $it.Cat
                        if ($it.Cat) { [void]$sb.Append('<div style="margin:10px 0 4px 0"><b>').Append((& $h $it.Cat)).Append('</b></div>') }
                    }
                    [void]$sb.Append('<div class="item row"><span class="l">').Append((& $h $it.Name))
                    if ($it.Desc) { [void]$sb.Append(' <span class="muted">').Append((& $h $it.Desc)).Append('</span>') }
                    [void]$sb.Append('</span><span><b>').Append((& $h $it.Price)).Append('</b></span></div>')
                }
            }
            'orders' {
                if ($lines.Count -gt 0) { [void]$sb.Append('<p class="muted">').Append((& $h ($lines -join ' '))).Append('</p>') }
                $ents = @(Get-PelIntranetEntries $b.Id | ForEach-Object { $x = ([string]$_) -split "`t"; if ($x.Count -ge 2) { [pscustomobject]@{ Name = $x[1]; Text = $(if ($x.Count -ge 3) { $x[2] } else { '' }) } } } | Sort-Object Name)
                if ($ents.Count -eq 0) { [void]$sb.Append('<div class="empty">').Append((& $h (Get-PelText 'Noch keine Einträge.' 'No entries yet.'))).Append('</div>') }
                foreach ($e in $ents) {
                    [void]$sb.Append('<div class="item row"><b class="l">').Append((& $h $e.Name)).Append('</b><span>').Append((& $h $e.Text)).Append('</span></div>')
                }
                [void]$sb.Append('<div class="muted" style="margin:4px 0 8px 0">').Append((& $h ((Get-PelText '{0} Einträge' '{0} entries') -f $ents.Count))).Append('</div>')
                if ($server) {
                    [void]$sb.Append('<form method="post" action="/pel/submit"><input type="hidden" name="b" value="').Append($bid).Append('">')
                    if ($Embed) { [void]$sb.Append('<input type="hidden" name="e" value="1">') }
                    [void]$sb.Append('<input type="text" name="n" maxlength="32" placeholder="').Append((& $h (Get-PelText 'Dein Name' 'Your name'))).Append('">')
                    [void]$sb.Append('<input type="text" name="t" maxlength="120" placeholder="').Append((& $h (Get-PelText 'Dein Wunsch' 'Your order'))).Append('">')
                    [void]$sb.Append('<div class="row"><span class="muted">').Append((& $h (Get-PelText 'Ein Eintrag pro PC. Beide Felder leer = Eintrag löschen.' 'One entry per PC. Both fields empty = remove entry.'))).Append('</span><button class="btn" type="submit">').Append((& $h (Get-PelText 'Eintragen' 'Submit'))).Append('</button></div></form>')
                }
            }
        }
        [void]$sb.Append('</div>')
    }
    [void]$sb.Append('</div>')
    [void]$sb.Append('<div class="foot">').Append((& $h (Get-PelText 'Hobbyprojekt · ohne Konto · ohne Werbung · Project Earth LAN Manager' 'Hobby project · no account · no ads · Project Earth LAN Manager'))).Append('</div></div>')

    # ---- Countdown und automatisches Neuladen (ES5, läuft auch im Windows-Steuerelement) ----
    # Als normaler Text (kein Here-String), damit Build-PEL-Exe.ps1 ihn nicht als
    # eingebettetes PowerShell-Skript prüft - der Inhalt ist JavaScript.
    $js = '<script>
(function(){
var cd=document.getElementById(''pel-cd'');
function set(id,v){var e=document.getElementById(id);if(e){e.innerHTML=v;}}
function pad(n){return (n<10?''0'':'''')+n;}
function tick(){
if(!cd){return;}
var t=parseInt(cd.getAttribute(''data-t''),10)-new Date().getTime();
if(t<=0){cd.innerHTML=''<b>''+cd.getAttribute(''data-done'')+''</b>'';cd=null;return;}
set(''pel-cd-d'',Math.floor(t/86400000));set(''pel-cd-h'',pad(Math.floor(t/3600000)%24));
set(''pel-cd-m'',pad(Math.floor(t/60000)%60));set(''pel-cd-s'',pad(Math.floor(t/1000)%60));
}
tick();setInterval(tick,1000);
var rev=PELREV;
function poll(){try{var x=new XMLHttpRequest();x.open(''GET'',''/pel/rev?t=''+new Date().getTime(),true);
x.onreadystatechange=function(){if(x.readyState===4&&x.status===200){var r=parseInt(x.responseText,10);if(!isNaN(r)&&r!==rev){location.reload();}}};x.send();}catch(e){}}
if(PELPOLL){setInterval(poll,10000);}
function my(){var ds=document.getElementsByTagName("div");for(var i=0;i<ds.length;i++){(function(d){var id=d.getAttribute("data-my");if(!id){return;}
try{var x=new XMLHttpRequest();x.open("GET","/pel/my?b="+id+"&t="+new Date().getTime(),true);
x.onreadystatechange=function(){if(x.readyState===4&&x.status===200){if(x.responseText){d.innerHTML=x.responseText;d.style.display="block";}else{d.style.display="none";}}};x.send();}catch(e){}})(ds[i]);}}
if(PELPOLL){my();setInterval(my,15000);}
})();
</script>'
    $js = $js.Replace('PELREV', [string]$Rev).Replace('PELPOLL', $(if ($server) { 'true' } else { 'false' }))
    [void]$sb.Append($js).Append('</body></html>')
    return $sb.ToString()
}

# Seite, die ein Browser-Gast sieht, wenn der Veranstalter ein eigenes Intranet einbettet
function Build-PelIntranetForwardHtml($Cfg) {
    $u = ConvertTo-PelHtml $Cfg.ExternUrl
    $t = ConvertTo-PelHtml $Cfg.Event.Title
    $msg = ConvertTo-PelHtml (Get-PelText 'Das Intranet dieser LAN-Party findest du hier:' 'You can find the intranet of this LAN party here:')
    return '<!DOCTYPE html><html><head><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta charset="utf-8"><title>' + $t + '</title><meta http-equiv="refresh" content="1;url=' + $u + '"><style>body{background:#191919;color:#e8e8e8;font-family:"Segoe UI",Tahoma,Arial,sans-serif;padding:40px}a{color:#6cb6ff}</style></head><body><h1>' + $t + '</h1><p>' + $msg + '</p><p><a href="' + $u + '">' + $u + '</a></p></body></html>'
}

function Get-PelIntranetInfoJson($Cfg) {
    $o = [ordered]@{
        PelIntranet = 1
        Name        = $Cfg.Event.Title
        Host        = (Limit-PelText (Get-PelDisplayName) 40)
        Mode        = $Cfg.Mode
        Url         = $(if ($Cfg.Mode -eq 'extern') { $Cfg.ExternUrl } else { '' })
        Version     = $script:PelVersion
    }
    return (ConvertTo-Json -InputObject $o -Compress)
}

# Übergibt die aktuelle Seite an den laufenden Server. Die Revision steigt nur, wenn sich
# wirklich etwas geändert hat - daran erkennen die Seiten der Gäste, dass sie neu laden
# sollen (/pel/rev, alle 10 Sekunden).
function Update-PelIntranetServerContent {
    param($Cfg, [switch]$Force)
    if (-not (('PelIntranetServer' -as [type]) -and [PelIntranetServer]::IsRunning)) { return }
    $defs = @()
    foreach ($b in @($Cfg.Blocks)) {
        if ($b.Type -eq 'poll') { $n = @(Get-PelIntranetPollOptions $b).Count; if ($n -gt 0) { $defs += "$($b.Id)|$n" } }
        elseif ($b.Type -eq 'orders') { $defs += "$($b.Id)|-1" }
        elseif ($b.Type -eq 'seatmap') {
            $defs += "$($b.Id)|-3"
            $smp = Get-PelIntranetSeatMap $b
            $seatList = [string[]]@($smp.All | Where-Object { -not $smp.Blocked.ContainsKey($_) })
            [PelIntranetServer]::SetSeats([string]$b.Id, $seatList, [bool]$b.Closed, ($script:PelLang -eq 'en'))
        }
        elseif ($b.Type -eq 'menu') {
            $defs += "$($b.Id)|-2"
            $mn = Get-PelIntranetMenu $b
            $names = [string[]]@($mn.Items | ForEach-Object { [string]$_.Name })
            $prices = [string[]]@($mn.Items | ForEach-Object { if ($null -ne $_.Price) { ([decimal]$_.Price).ToString([System.Globalization.CultureInfo]::InvariantCulture) } else { '' } })
            # Nur-vor-Ort- und ausverkaufte Artikel nimmt der Server nicht an - auch nicht,
            # wenn jemand das Formular von Hand nachbaut.
            $online = [bool[]]@($mn.Items | ForEach-Object { [bool]($_.Online -and -not $_.SoldOut) })
            [PelIntranetServer]::SetMenu([string]$b.Id, $names, $prices, [bool]$b.Closed, ($script:PelLang -eq 'en'), $online)
        }
    }
    [PelIntranetServer]::SetBlocks([string[]]$defs)
    $rev = [int64][PelIntranetServer]::Revision + 1
    if ($Cfg.Mode -eq 'extern') {
        $page = Build-PelIntranetForwardHtml $Cfg
        $embed = $page
    } else {
        $page = Build-PelIntranetHtml -Cfg $Cfg -Mode 'server' -Embed $false -Rev $rev
        $embed = Build-PelIntranetHtml -Cfg $Cfg -Mode 'server' -Embed $true -Rev $rev
    }
    # Vergleich ohne die Revisionsnummer, sonst wäre jede Seite "neu"
    $cmpPage = $page.Replace("var rev=$rev;", '')
    $cmpEmbed = $embed.Replace("var rev=$rev;", '')
    if (-not $Force -and $cmpPage -eq $script:PelIntranetLastHtml -and $cmpEmbed -eq $script:PelIntranetLastEmbed) { return }
    $script:PelIntranetLastHtml = $cmpPage
    $script:PelIntranetLastEmbed = $cmpEmbed
    [PelIntranetServer]::SetImages((Get-PelIntranetHeaderPath $Cfg), $script:PelIntranetLogosDir)
    [PelIntranetServer]::SetContent($page, $embed, (Get-PelIntranetInfoJson $Cfg), $script:PelIntranetDownloadDir, (Get-PelIntranetLogoPath $Cfg), $rev)
}

function Start-PelIntranetServer($Cfg) {
    Initialize-PelIntranetTypes
    Initialize-PelIntranetFolders
    if ([PelIntranetServer]::IsRunning) { [PelIntranetServer]::Stop() }
    $port = [int]$Cfg.Port
    # Firewall: nur Heimnetz (LocalSubnet) und P2P-Netz - wie beim Datei-Server (Option 1)
    $ruleName = "Project Earth LAN Intranet (TCP $port)"
    try {
        if (-not (Get-NetFirewallRule -DisplayName $ruleName -ErrorAction SilentlyContinue)) {
            Get-NetFirewallRule -DisplayName 'Project Earth LAN Intranet*' -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue
            New-NetFirewallRule -DisplayName $ruleName -Direction Inbound -Action Allow -Protocol TCP -LocalPort $port -RemoteAddress @('LocalSubnet', '10.77.0.0/16') -Profile Any -ErrorAction Stop | Out-Null
        }
    } catch { Write-PelLog -Level 'INTRANET' -Message "Firewall-Regel: $($_.Exception.Message)" }
    try { [PelIntranetServer]::Start($port) }
    catch { throw (Get-PelText "TCP-Port $port ist schon belegt oder gesperrt. Wähle unter 'Einstellungen' einen anderen Port.`n`n$(Get-PelInnerMessage $_)" "TCP port $port is already in use or blocked. Choose a different port under 'Settings'.`n`n$(Get-PelInnerMessage $_)") }
    Import-PelIntranetEntries $Cfg
    $script:PelIntranetLastHtml = ''
    $script:PelIntranetLastEmbed = ''
    Update-PelIntranetServerContent -Cfg $Cfg -Force
    Write-PelLog -Level 'INTRANET' -Message "Intranet veröffentlicht: TCP $port, Modus $($Cfg.Mode)"
}

function Stop-PelIntranetServer($Cfg) {
    if (-not ('PelIntranetServer' -as [type])) { return }
    if (-not [PelIntranetServer]::IsRunning) { return }
    if ($Cfg) { Save-PelIntranetEntries $Cfg }
    [PelIntranetServer]::Stop()
    Write-PelLog -Level 'INTRANET' -Message 'Intranet beendet.'
}

# Adressen, unter denen die anderen das Intranet erreichen: P2P zuerst, dann Heimnetz
function Get-PelIntranetUrls([int]$Port) {
    return @(Get-PelFileServerUrls $Port | ForEach-Object { [pscustomobject]@{ Kind = $_.Kind; Url = "$($_.Url)/" } })
}

# Wo gesucht wird: das eigene /24-Netz jeder privaten IPv4 dieses PCs (P2P-Lobby und
# Heimnetz) plus bekannte Nachbarn aus der ARP-Tabelle. Höchstens 2048 Adressen.
function Get-PelIntranetScanTargets {
    $own = Get-PelLocalIpSet
    $list = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    $add = {
        param([string]$ip)
        if (-not $ip -or $seen.ContainsKey($ip) -or $own.ContainsKey($ip)) { return }
        $seen[$ip] = $true
        $list.Add($ip)
    }
    try {
        foreach ($nb in @(Get-NetNeighbor -AddressFamily IPv4 -ErrorAction Stop)) {
            $ipn = [string]$nb.IPAddress
            if ([string]$nb.State -in @('Reachable', 'Stale', 'Delay', 'Probe', 'Permanent') -and $ipn -match '^(10|172\.(1[6-9]|2\d|3[01])|192\.168)\.' -and $ipn -notmatch '\.(0|255)$') { & $add $ipn }
        }
    } catch { }
    $nets = @($own.Keys | Where-Object { $_ -match '^(10|172\.(1[6-9]|2\d|3[01])|192\.168)\.' } | Sort-Object { if ($_ -like '10.77.*') { 0 } else { 1 } })
    foreach ($ip in $nets) {
        $pre = $ip.Substring(0, $ip.LastIndexOf('.') + 1)
        for ($i = 1; $i -le 254; $i++) { & $add ($pre + $i) }
        if ($list.Count -ge 2048) { break }
    }
    return @($list | Select-Object -First 2048)
}

# Liest einen Treffer der Suche ("IP<TAB>JSON") und prüft alle Felder.
function ConvertFrom-PelIntranetFound([string]$Line, [int]$Port) {
    $i = $Line.IndexOf("`t")
    if ($i -le 0) { return $null }
    $ip = $Line.Substring(0, $i)
    try { $j = $Line.Substring($i + 1) | ConvertFrom-Json } catch { return $null }
    if (-not $j -or [int]$j.PelIntranet -ne 1) { return $null }
    $mode = 'own'
    $url = "http://$($ip):$Port/?embed=1"
    if ([string]$j.Mode -eq 'extern') {
        $ext = Test-PelIntranetUrl ([string]$j.Url)
        if (-not $ext) { return $null }
        $mode = 'extern'
        $url = $ext
    }
    return [pscustomobject]@{
        Ip = $ip; Name = (Limit-PelText ([string]$j.Name) 80); Host = (Limit-PelText ([string]$j.Host) 40)
        Mode = $mode; Url = $url; BrowserUrl = $(if ($mode -eq 'extern') { $url } else { "http://$($ip):$Port/" })
    }
}

# ---- Export / Import als .zip (intranet.json, Logo, Kopfbild und Logo-Ordner - Downloads nicht)
function Export-PelIntranetZip($Cfg, [string]$Path) {
    Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem
    if ([System.IO.File]::Exists($Path)) { [System.IO.File]::Delete($Path) }
    $zip = [System.IO.Compression.ZipFile]::Open($Path, [System.IO.Compression.ZipArchiveMode]::Create)
    try {
        $e = $zip.CreateEntry('intranet.json')
        $w = New-Object System.IO.StreamWriter($e.Open(), (New-Object System.Text.UTF8Encoding($false)))
        try { $w.Write((ConvertTo-Json -InputObject $Cfg -Depth 5)) } finally { $w.Dispose() }
        $logo = Get-PelIntranetLogoPath $Cfg
        if ($logo) { [void][System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $logo, [System.IO.Path]::GetFileName($logo)) }
        $hdr = Get-PelIntranetHeaderPath $Cfg
        if ($hdr) { [void][System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $hdr, [System.IO.Path]::GetFileName($hdr)) }
        foreach ($lf in @(Get-PelIntranetLogoFiles)) { [void][System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $lf.FullName, ('logos/' + $lf.Name)) }
    } finally { $zip.Dispose() }
}

function Import-PelIntranetZip([string]$Path) {
    Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem
    $zip = [System.IO.Compression.ZipFile]::OpenRead($Path)
    try {
        $je = $zip.Entries | Where-Object { $_.FullName -eq 'intranet.json' } | Select-Object -First 1
        if (-not $je -or $je.Length -gt 262144) { throw (Get-PelText 'Die Datei enthält keine gültige intranet.json.' 'The file does not contain a valid intranet.json.') }
        $r = New-Object System.IO.StreamReader($je.Open(), [System.Text.Encoding]::UTF8)
        try { $raw = $r.ReadToEnd() } finally { $r.Dispose() }
        $cfg = Repair-PelIntranetConfig ($raw | ConvertFrom-Json)
        $cfg.Event.Logo = ''
        $le = $zip.Entries | Where-Object { $_.FullName -match '^logo\.(png|jpg|gif)$' -and $_.Length -le 2097152 } | Select-Object -First 1
        if ($le) {
            Initialize-PelIntranetFolders
            foreach ($old in @(Get-ChildItem -LiteralPath $script:PelIntranetDir -File -Filter 'logo.*' -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($le, (Join-Path $script:PelIntranetDir $le.FullName), $true)
            $cfg.Event.Logo = $le.FullName
        }
        $cfg.Event.Header = ''
        $he = $zip.Entries | Where-Object { $_.FullName -match '^header\.(png|jpg|gif)$' -and $_.Length -le 5242880 } | Select-Object -First 1
        if ($he) {
            Initialize-PelIntranetFolders
            foreach ($old in @(Get-ChildItem -LiteralPath $script:PelIntranetDir -File -Filter 'header.*' -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($he, (Join-Path $script:PelIntranetDir $he.FullName), $true)
            $cfg.Event.Header = $he.FullName
        }
        # Logos: nur Bilder direkt in logos/ (kein Unterordner, kein ..), höchstens 24
        $n = 0
        foreach ($lz in @($zip.Entries | Where-Object { $_.FullName -match '^logos/[\w\.\- ]+\.(png|jpe?g|gif)$' -and $_.Name -notmatch '^\.' -and $_.Length -le 2097152 })) {
            if ($n -ge 24) { break }
            Initialize-PelIntranetFolders
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($lz, (Join-Path $script:PelIntranetLogosDir $lz.Name), $true)
            $n++
        }
        return $cfg
    } finally { $zip.Dispose() }
}

# Leert die Stimmen bzw. Einträge eines Mitmach-Blocks (laufender Server UND Datei)
function Clear-PelIntranetEntries($Cfg, [string]$Id) {
    if (('PelIntranetServer' -as [type]) -and [PelIntranetServer]::IsRunning) {
        [PelIntranetServer]::ClearEntries($Id)
        Save-PelIntranetEntries $Cfg
        return
    }
    try {
        if (-not [System.IO.File]::Exists($script:PelIntranetEntriesPath)) { return }
        $j = Read-PelTextFile $script:PelIntranetEntriesPath | ConvertFrom-Json
        $o = [ordered]@{}
        if ($j) { foreach ($p in $j.PSObject.Properties) { if ($p.Name -ne $Id) { $o[$p.Name] = @($p.Value) } } }
        Write-PelTextFileAtomic $script:PelIntranetEntriesPath (ConvertTo-Json -InputObject $o -Depth 3)
    } catch { Write-PelLog -Level 'INTRANET' -Message "Einträge leeren: $($_.Exception.Message)" }
}

# Startseite der Anzeige, solange noch kein Intranet ausgewählt ist
function Get-PelIntranetIntroHtml {
    $t1 = ConvertTo-PelHtml (Get-PelText 'Intranet' 'Intranet')
    $t2 = ConvertTo-PelHtml (Get-PelText 'Links siehst du alle Intranets, die der Manager im Heimnetz und in deiner P2P-Lobby gefunden hat. Einfach anklicken.' 'On the left you see every intranet the manager found in your home network and your P2P lobby. Just click one.')
    $t3 = ConvertTo-PelHtml (Get-PelText 'Du veranstaltest selbst? Unter "Baukasten" stellst du deine Seite zusammen (oder nimmst eine Vorlage) und klickst auf "Veröffentlichen". Hast du schon ein eigenes Intranet, trägst du unter "Einstellungen" nur dessen Adresse ein.' 'Hosting yourself? Build your page under "Builder" (or start from a template) and click "Publish". Already have your own intranet? Just enter its address under "Settings".')
    $t4 = ConvertTo-PelHtml (Get-PelText 'Kein Konto, keine Werbung, keine fremden Dienste - alles bleibt in eurem Netz.' 'No account, no ads, no third-party services - everything stays in your network.')
    return '<!DOCTYPE html><html><head><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta charset="utf-8"><style>body{margin:0;background:#191919;color:#e8e8e8;font-family:"Segoe UI",Tahoma,Arial,sans-serif;font-size:15px;line-height:1.5}div{max-width:640px;margin:70px auto;padding:0 24px}h1{font-size:30px;margin:0 0 14px 0}p{color:#c3cad3}.m{color:#8c949e;font-size:13px;margin-top:26px}</style></head><body><div><h1>' + $t1 + '</h1><p>' + $t2 + '</p><p>' + $t3 + '</p><p class="m">' + $t4 + '</p></div></body></html>'
}

