    # ---- Hilfsfunktionen des Fensters ------------------------------------------------
    function Show-IntranetPage([string]$Page) {
        $st.Page = $Page
        $pView.Visible = ($Page -eq 'view')
        $pBuild.Visible = ($Page -eq 'build')
        $pSet.Visible = ($Page -eq 'set')
        foreach ($pair in @(@($btnNavView, 'view'), @($btnNavBuild, 'build'), @($btnNavSet, 'set'))) {
            if ($pair[1] -eq $Page) { $pair[0].BackColor = $cAccent } else { $pair[0].BackColor = $cBtn }
        }
        if ($Page -eq 'build') { Update-IntranetPreview }
        if ($Page -eq 'set') { Update-IntranetUrls }
    }

    function Test-IntranetRunning { return [bool](('PelIntranetServer' -as [type]) -and [PelIntranetServer]::IsRunning) }

    function Get-BlockLabel($b, [int]$Index) {
        $tn = Get-PelIntranetBlockType $b.Type
        $name = [string]$b.Type
        if ($tn) { $name = $tn.Name }
        $s = "{0}. {1}" -f ($Index + 1), $name
        if ($b.Title -and $b.Title -ne $name) { $s += ': ' + $b.Title }
        if (-not $b.Visible) { $s += '  ' + (Get-PelText '(versteckt)' '(hidden)') }
        return $s
    }

    function Update-BlockList([int]$Select = -2) {
        $st.Loading = $true
        try {
            if ($Select -eq -2) { $Select = $lbBlocks.SelectedIndex }
            $lbBlocks.BeginUpdate()
            $lbBlocks.Items.Clear()
            for ($i = 0; $i -lt $st.Blocks.Count; $i++) { [void]$lbBlocks.Items.Add((Get-BlockLabel $st.Blocks[$i] $i)) }
            $lbBlocks.EndUpdate()
            if ($st.Blocks.Count -gt 0) { $lbBlocks.SelectedIndex = [Math]::Max(0, [Math]::Min($Select, $st.Blocks.Count - 1)) }
        } finally { $st.Loading = $false }
        Show-BlockProps
    }

    function Get-SelectedBlock {
        $i = $lbBlocks.SelectedIndex
        if ($i -lt 0 -or $i -ge $st.Blocks.Count) { return $null }
        return $st.Blocks[$i]
    }

    function Update-EntryCount($b) {
        if ($b -and $b.Type -in @('poll', 'orders', 'menu', 'seatmap')) {
            $n = @(Get-PelIntranetEntries $b.Id).Count
            $lblEntries.Text = (Get-PelText '{0} Einträge' '{0} entries') -f $n
            $btnClearEntries.Enabled = ($n -gt 0)
            $btnClearEntries.Visible = $true
            $lblEntries.Visible = $true
        } else {
            $btnClearEntries.Visible = $false
            $lblEntries.Visible = $false
        }
        $btnOrders.Visible = [bool]($b -and $b.Type -in @('menu', 'seatmap'))
        $btnItems.Visible = [bool]($b -and $b.Type -in @('menu', 'prices'))
        if ($b -and $b.Type -eq 'prices') {
            $btnItems.Text = Get-PelText 'Preise bearbeiten' 'Edit prices'
            $btnItems.Location = New-Object System.Drawing.Point(16, $btnOrders.Location.Y)
        } else {
            $btnItems.Text = Get-PelText 'Speisen & Getränke' 'Food & drinks'
            $btnItems.Location = New-Object System.Drawing.Point(226, $btnOrders.Location.Y)
        }
        if ($b -and $b.Type -eq 'seatmap') { $btnOrders.Text = Get-PelText 'Check-in verwalten' 'Manage check-in' }
        else { $btnOrders.Text = Get-PelText 'Bestellungen verwalten' 'Manage orders' }
        $isLogos = [bool]($b -and $b.Type -eq 'logos')
        $btnLogosAdd.Visible = $isLogos
        $btnLogosDir.Visible = $isLogos
    }

    function Show-BlockProps {
        $b = Get-SelectedBlock
        $st.Loading = $true
        try {
            $has = [bool]$b
            foreach ($c in @($txtBTitle, $txtBText, $chkWide, $chkVisible)) { $c.Enabled = $has }
            if (-not $has) {
                $lblBType.Text = Get-PelText 'Kein Block ausgewählt' 'No block selected'
                $lblBHint.Text = ''
                $txtBTitle.Text = ''
                $txtBText.Text = ''
                Update-EntryCount $null
                return
            }
            $tn = Get-PelIntranetBlockType $b.Type
            $lblBType.Text = $tn.Name
            $lblBHint.Text = $tn.Hint
            $txtBTitle.Text = [string]$b.Title
            $txtBText.Text = ([string]$b.Text) -replace "`r?`n", "`r`n"
            $chkWide.Checked = [bool]$b.Wide
            $chkVisible.Checked = [bool]$b.Visible
            Update-EntryCount $b
        } finally { $st.Loading = $false }
    }

    function Show-EventProps {
        $st.Loading = $true
        try {
            $e = $st.Cfg.Event
            $txtTitle.Text = [string]$e.Title
            $txtDate.Text = [string]$e.Date
            $txtPlace.Text = [string]$e.Place
            $txtOrg.Text = [string]$e.Organizer
            $txtCdText.Text = [string]$e.CountdownText
            $dt = [datetime]::MinValue
            if ($e.Countdown -and [datetime]::TryParseExact([string]$e.Countdown, 'yyyy-MM-ddTHH:mm', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$dt)) {
                $dtpCd.Value = $dt
                $dtpCd.Checked = $true
            } else {
                $dtpCd.Value = (Get-Date).Date.AddDays(1).AddHours(18)
                $dtpCd.Checked = $false
            }
            $pnlAccent.BackColor = [System.Drawing.ColorTranslator]::FromHtml([string]$e.Accent)
            $btnLogoDel.Enabled = [bool](Get-PelIntranetLogoPath $st.Cfg)
            $cbLogoSize.SelectedIndex = switch ([string]$e.LogoSize) { 'S' { 0 } 'L' { 2 } default { 1 } }
            $btnHeaderDel.Enabled = [bool](Get-PelIntranetHeaderPath $st.Cfg)
            $cbHeaderMode.SelectedIndex = $(if ([string]$e.HeaderMode -eq 'background') { 1 } else { 0 })
            $chkHideTitle.Checked = [bool]$e.HideTitle
            $rbOwn.Checked = ($st.Cfg.Mode -ne 'extern')
            $rbExtern.Checked = ($st.Cfg.Mode -eq 'extern')
            $txtExtern.Text = [string]$st.Cfg.ExternUrl
            $numPort.Value = [decimal][int]$st.Cfg.Port
            $chkAuto.Checked = [bool]$st.Cfg.AutoPublish
        } finally { $st.Loading = $false }
    }

    # Änderungen sammeln und nach kurzer Pause gemeinsam speichern/anzeigen - sonst würde
    # bei jedem Tastendruck die Seite neu erzeugt.
    # ---- Check-in (Block "Sitzplan & Check-in") ---------------------------------------------
    # Am Eingang: Name oder Platz ins Suchfeld tippen, Enter = einchecken (bei genau einem
    # Treffer). Die Orga kann Plätze ändern und Gäste ohne PC eintragen.
    function Show-IntranetCheckin([string]$Id) {
        $blk = @($st.Blocks | Where-Object { [string]$_.Id -eq $Id -and $_.Type -eq 'seatmap' }) | Select-Object -First 1
        if (-not $blk) { return }
        $cs = @{ Sig = ''; Rows = @() }
        $d = (New-PelForm)
        $d.Text = (Get-PelText 'Check-in - {0}' 'Check-in - {0}') -f $blk.Title
        $d.Size = New-Object System.Drawing.Size(1000, 660)
        $d.MinimumSize = New-Object System.Drawing.Size(900, 520)
        $d.StartPosition = 'CenterParent'
        $d.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
        $d.ForeColor = [System.Drawing.Color]::White
        $d.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Regular)
        $mk = {
            param([string]$T, [int]$X, [int]$Y, [int]$W, $Back, [string]$Anchor = 'Bottom,Left')
            $bt = New-Object System.Windows.Forms.Button
            $bt.Text = $T
            $bt.Location = New-Object System.Drawing.Point($X, $Y)
            $bt.Size = New-Object System.Drawing.Size($W, 36)
            $bt.FlatStyle = 'Flat'
            $bt.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
            $bt.BackColor = $Back
            $bt.ForeColor = [System.Drawing.Color]::White
            $bt.Anchor = $Anchor
            $d.Controls.Add($bt)
            return $bt
        }
        $cN = [System.Drawing.Color]::FromArgb(45, 45, 45)
        $cG = [System.Drawing.Color]::FromArgb(0, 135, 70)
        $cR = [System.Drawing.Color]::FromArgb(160, 50, 40)
        $cB = [System.Drawing.Color]::FromArgb(0, 120, 215)
        $lblS = New-Object System.Windows.Forms.Label
        $lblS.Text = Get-PelText 'Suchen (Name oder Platz), Enter = einchecken:' 'Search (name or seat), Enter = check in:'
        $lblS.Location = New-Object System.Drawing.Point(14, 14)
        $lblS.Size = New-Object System.Drawing.Size(320, 22)
        $d.Controls.Add($lblS)
        $txtS = New-Object System.Windows.Forms.TextBox
        $txtS.Location = New-Object System.Drawing.Point(334, 10)
        $txtS.Size = New-Object System.Drawing.Size(260, 28)
        $txtS.BackColor = [System.Drawing.Color]::FromArgb(15, 15, 15)
        $txtS.ForeColor = [System.Drawing.Color]::White
        $txtS.BorderStyle = 'FixedSingle'
        $txtS.Font = New-Object System.Drawing.Font('Segoe UI', 11)
        $d.Controls.Add($txtS)
        $lblHead = New-Object System.Windows.Forms.Label
        $lblHead.Location = New-Object System.Drawing.Point(610, 14)
        $lblHead.Size = New-Object System.Drawing.Size(370, 22)
        $lblHead.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        $lblHead.Anchor = 'Top,Left,Right'
        $d.Controls.Add($lblHead)
        $lv = New-Object System.Windows.Forms.ListView
        $lv.Location = New-Object System.Drawing.Point(14, 46)
        $lv.Size = New-Object System.Drawing.Size(956, 460)
        $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.MultiSelect = $true; $lv.HideSelection = $false
        $lv.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20); $lv.ForeColor = [System.Drawing.Color]::White
        $lv.BorderStyle = 'FixedSingle'; $lv.Anchor = 'Top,Bottom,Left,Right'
        foreach ($col in @(@('Platz', 70), @('Name', 220), @('Status', 120), @('Reserviert', 90), @('Eingecheckt', 90), @('PC / Herkunft', 200))) { [void]$lv.Columns.Add($col[0], $col[1]) }
        $d.Controls.Add($lv)
        $y = 516
        $bIn = & $mk (Get-PelText 'Einchecken' 'Check in') 14 $y 140 $cG
        $bOut = & $mk (Get-PelText 'Check-in zurücknehmen' 'Undo check-in') 160 $y 190 $cN
        $bSeat = & $mk (Get-PelText 'Platz ändern ...' 'Change seat ...') 356 $y 150 $cN
        $bAddG = & $mk (Get-PelText 'Gast eintragen ...' 'Add guest ...') 512 $y 150 $cB
        $bDelG = & $mk (Get-PelText 'Entfernen' 'Remove') 668 $y 120 $cR
        $bCsv = & $mk 'CSV' 794 $y 70 $cN
        $bClose = & $mk (Get-PelText 'Schließen' 'Close') 870 $y 100 $cN 'Bottom,Right'
        $bLock = & $mk '' 14 ($y + 44) 300 $cR
        $lblHint = New-Object System.Windows.Forms.Label
        $lblHint.Location = New-Object System.Drawing.Point(330, ($y + 52))
        $lblHint.Size = New-Object System.Drawing.Size(640, 22)
        $lblHint.ForeColor = [System.Drawing.Color]::FromArgb(170, 178, 190)
        $lblHint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5, [System.Drawing.FontStyle]::Italic)
        $lblHint.Anchor = 'Bottom,Left,Right'
        $d.Controls.Add($lblHint)

        $refresh = {
            param([bool]$Force = $false)
            $running = Test-IntranetRunning
            $sm = Get-PelIntranetSeatMap $blk
            $rows = @(Get-PelIntranetSeatEntries $blk | Sort-Object @{ Expression = { $_.Seat } }, Name)
            $flt = $txtS.Text.Trim()
            $sig = (@($rows | ForEach-Object { "$($_.Key)|$($_.Seat)|$($_.State)|$($_.Name)" }) -join ';') + "|$flt|$($blk.Closed)|$running"
            if (-not $Force -and $sig -eq $cs.Sig) { return }
            $cs.Sig = $sig
            $cs.Rows = $rows
            $keep = @{}
            foreach ($si in @($lv.SelectedItems)) { $keep[[string]$si.Tag.Key] = $true }
            $lv.BeginUpdate()
            $lv.Items.Clear()
            foreach ($r in $rows) {
                if ($flt -and ([string]$r.Name).IndexOf($flt, [System.StringComparison]::OrdinalIgnoreCase) -lt 0 -and ([string]$r.Seat) -ine $flt -and -not ([string]$r.Seat).StartsWith($flt, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
                $li = New-Object System.Windows.Forms.ListViewItem([string]$r.Seat)
                [void]$li.SubItems.Add([string]$r.Name)
                [void]$li.SubItems.Add($(if ($r.State -eq 'eingecheckt') { Get-PelText 'eingecheckt' 'checked in' } else { Get-PelText 'reserviert' 'reserved' }))
                [void]$li.SubItems.Add($(if ($r.Reserved -gt [datetime]::MinValue) { $r.Reserved.ToString('dd.MM. HH:mm') } else { '' }))
                [void]$li.SubItems.Add($(if ($r.CheckedIn -gt [datetime]::MinValue) { $r.CheckedIn.ToString('HH:mm') } else { '' }))
                [void]$li.SubItems.Add($(if (([string]$r.Key).StartsWith('o:')) { Get-PelText '(von der Orga eingetragen)' '(added by organizers)' } else { [string]$r.Key }))
                $li.ForeColor = if ($r.State -eq 'eingecheckt') { [System.Drawing.Color]::FromArgb(120, 220, 140) } else { [System.Drawing.Color]::FromArgb(255, 190, 90) }
                $li.Tag = $r
                if ($keep.ContainsKey([string]$r.Key)) { $li.Selected = $true }
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
            $nAll = @($sm.All | Where-Object { -not $sm.Blocked.ContainsKey($_) }).Count
            $nIn = @($rows | Where-Object { $_.State -eq 'eingecheckt' }).Count
            $lblHead.Text = (Get-PelText 'Eingecheckt {0} von {1} · Plätze {2}' 'Checked in {0} of {1} · seats {2}') -f $nIn, $rows.Count, $nAll
            foreach ($bt in @($bIn, $bOut, $bSeat, $bAddG, $bDelG, $bLock)) { $bt.Enabled = $running }
            $bLock.Text = if ($blk.Closed) { Get-PelText 'Platzwahl für Gäste wieder öffnen' 'Reopen seat selection for guests' } else { Get-PelText 'Platzwahl für Gäste schließen' 'Close seat selection for guests' }
            $bLock.BackColor = if ($blk.Closed) { $cG } else { $cR }
            $lblHint.Text = if ($running) { Get-PelText 'Grün = eingecheckt, orange = reserviert. Gäste sehen den Status auf der Seite unter "Dein Platz".' 'Green = checked in, orange = reserved. Guests see the status on the page under "Your seat".' } else { Get-PelText 'Intranet ist nicht veröffentlicht - Check-in erst nach "Veröffentlichen".' 'Intranet is not published - check-in after "Publish".' }
        }
        $saveNow = {
            Save-PelIntranetEntries $st.Cfg
            Update-PelIntranetServerContent -Cfg $st.Cfg
            & $refresh $true
        }
        $setState = {
            param([string]$State)
            $sel = @($lv.SelectedItems | ForEach-Object { $_.Tag })
            if ($sel.Count -eq 0 -and $lv.Items.Count -eq 1) { $sel = @($lv.Items[0].Tag) }
            if ($sel.Count -eq 0) { Show-PelMsg (Get-PelText 'Bitte zuerst einen Gast in der Liste auswählen (oder so suchen, dass nur einer übrig bleibt).' 'Please select a guest in the list first (or search until only one is left).') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d; return }
            foreach ($r in $sel) {
                $err = [PelIntranetServer]::SetSeatEntry($Id, [string]$r.Key, [string]$r.Name, [string]$r.Seat, $State)
                if ($err) { Show-PelMsg $err 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d }
            }
            Write-PelLog -Level 'INTRANET' -Message "Check-in: $($sel.Count) Gast/Gäste auf '$State' ($($blk.Title))."
            & $saveNow
            if ($State -eq 'eingecheckt') { $txtS.Text = ''; [void]$txtS.Focus() }
        }
        $askSeat = {
            param([string]$Title, [string]$Current)
            $sm = Get-PelIntranetSeatMap $blk
            $taken = @{}
            foreach ($r in $cs.Rows) { if ($r.Seat) { $taken[$r.Seat.ToUpperInvariant()] = $true } }
            $free = @($sm.All | Where-Object { -not $sm.Blocked.ContainsKey($_) -and -not $taken.ContainsKey($_) })
            $hint = if ($free.Count -gt 0) { ((Get-PelText 'Freie Plätze: {0}' 'Free seats: {0}') -f (($free | Select-Object -First 40) -join ', ')) } else { Get-PelText 'Kein Platz mehr frei.' 'No seat left.' }
            return [Microsoft.VisualBasic.Interaction]::InputBox(((Get-PelText "Platz eingeben (leer = ohne Platz):`n`n{0}" "Enter seat (empty = no seat):`n`n{0}") -f $hint), $Title, $Current)
        }
        $bIn.Add_Click({ & $setState 'eingecheckt' })
        $bOut.Add_Click({ & $setState 'reserviert' })
        $txtS.Add_TextChanged({ & $refresh })
        $txtS.Add_KeyDown({
            if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $_.SuppressKeyPress = $true; & $setState 'eingecheckt' }
        })
        $lv.Add_DoubleClick({ & $setState 'eingecheckt' })
        $bSeat.Add_Click({
            if ($lv.SelectedItems.Count -ne 1) { Show-PelMsg (Get-PelText 'Bitte genau einen Gast auswählen.' 'Please select exactly one guest.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d; return }
            $r = $lv.SelectedItems[0].Tag
            $ns = & $askSeat (Get-PelText 'Platz ändern' 'Change seat') ([string]$r.Seat)
            if ($null -eq $ns) { return }
            $err = [PelIntranetServer]::SetSeatEntry($Id, [string]$r.Key, [string]$r.Name, $ns.Trim().ToUpperInvariant(), [string]$r.State)
            if ($err) { Show-PelMsg $err 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d; return }
            & $saveNow
        })
        $bAddG.Add_Click({
            $nm = [Microsoft.VisualBasic.Interaction]::InputBox((Get-PelText 'Name des Gastes (z. B. ohne eigenen PC oder Anmeldung vor Ort):' 'Guest name (e.g. without own PC or signing up on site):'), (Get-PelText 'Gast eintragen' 'Add guest'), '')
            if (-not $nm -or -not $nm.Trim()) { return }
            $seat = & $askSeat (Get-PelText 'Gast eintragen' 'Add guest') ''
            if ($null -eq $seat) { return }
            $q = [PelI18n]::Show($d, (Get-PelText 'Gleich einchecken?' 'Check in right away?'), (Get-PelText 'Gast eintragen' 'Add guest'), [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
            $state = if ($q -eq [System.Windows.Forms.DialogResult]::Yes) { 'eingecheckt' } else { 'reserviert' }
            $err = [PelIntranetServer]::SetSeatEntry($Id, ('o:' + (New-PelIntranetId)), $nm.Trim(), $seat.Trim().ToUpperInvariant(), $state)
            if ($err) { Show-PelMsg $err 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d; return }
            & $saveNow
        })
        $bDelG.Add_Click({
            $sel = @($lv.SelectedItems | ForEach-Object { $_.Tag })
            if ($sel.Count -eq 0) { return }
            $q = [PelI18n]::Show($d, ((Get-PelText '{0} Eintrag/Einträge entfernen? Der Platz wird wieder frei.' 'Remove {0} entry/entries? The seat becomes free again.') -f $sel.Count), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
            if ($q -ne [System.Windows.Forms.DialogResult]::Yes) { return }
            foreach ($r in $sel) { [void][PelIntranetServer]::RemoveEntry($Id, [string]$r.Key) }
            & $saveNow
        })
        $bCsv.Add_Click({
            $sfd = New-Object System.Windows.Forms.SaveFileDialog
            $sfd.Filter = 'CSV (*.csv)|*.csv'
            $sfd.FileName = 'Checkin_' + (Get-Date -Format 'yyyyMMdd_HHmm') + '.csv'
            $sfd.InitialDirectory = [System.Environment]::GetFolderPath('Desktop')
            if ($sfd.ShowDialog($d) -ne [System.Windows.Forms.DialogResult]::OK) { return }
            try {
                $csv = (@($cs.Rows | ForEach-Object {
                            [pscustomobject][ordered]@{
                                Platz = $_.Seat; Name = $_.Name; Status = $_.State
                                Reserviert = $(if ($_.Reserved -gt [datetime]::MinValue) { $_.Reserved.ToString('yyyy-MM-dd HH:mm') } else { '' })
                                Eingecheckt = $(if ($_.CheckedIn -gt [datetime]::MinValue) { $_.CheckedIn.ToString('yyyy-MM-dd HH:mm') } else { '' })
                                Herkunft = $_.Key
                            }
                        }) | ConvertTo-Csv -NoTypeInformation -Delimiter ';') -join "`r`n"
                [System.IO.File]::WriteAllText($sfd.FileName, $csv, (New-Object System.Text.UTF8Encoding($true)))
            } catch { Show-PelMsg ([string]$_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d }
        })
        $bLock.Add_Click({
            $blk.Closed = -not [bool]$blk.Closed
            Save-IntranetNow
            & $refresh $true
        })
        $bClose.Add_Click({ $d.Close() })
        $tmrC = New-Object System.Windows.Forms.Timer
        $tmrC.Interval = 2000
        $tmrC.Add_Tick({ try { & $refresh } catch { } })
        $d.Add_Shown({ & $refresh $true; $tmrC.Start(); [void]$txtS.Focus() })
        $d.Add_FormClosed({ $tmrC.Stop(); $tmrC.Dispose() })
        [void]$d.ShowDialog($form)
        $d.Dispose()
    }

    # ---- Bestellungen (Block "Bestellung mit Speisekarte") ----------------------------------
    # Neue oder geänderte Bestellung: Meldung am Veranstalter-PC und an die Orga-PCs
    function Receive-IntranetOrderEvent([string]$Kind, [string]$Ip, [string]$Id) {
        $blk = @($st.Blocks | Where-Object { [string]$_.Id -eq $Id -and $_.Type -eq 'menu' }) | Select-Object -First 1
        if (-not $blk) { return }
        $menu = Get-PelIntranetMenu $blk
        if ($Kind -eq 'ORDER') {
            $o = @(Get-PelIntranetOrders $blk $menu | Where-Object { $_.Ip -eq $Ip }) | Select-Object -First 1
            if (-not $o) { return }
            $who = if ($o.Seat) { "$($o.Name) ($($o.Seat))" } else { $o.Name }
            $line = "${who}: $($o.Text)"
            if ($o.HasPrice) { $line += ' - ' + (Format-PelIntranetMoney $o.Sum) }
            if ($o.Note) { $line += " - $($o.Note)" }
        } else {
            $line = (Get-PelText 'Bestellung von {0} zurückgezogen' 'Order from {0} withdrawn') -f $Ip
        }
        $act = [scriptblock]::Create("Show-IntranetOrders '$Id'")
        Show-PelOrderNotification -Heading ([string]$blk.Title) -Line $line -OpenAction $act
        Send-PelOrderToOrgas ([string[]]@($menu.Orga)) ([string]$st.Cfg.Event.Title) ("$($blk.Title): $line")
        $lblStatus.Text = (Get-PelText 'Neue Bestellung: {0}' 'New order: {0}') -f $line
    }

