        $bExit = & $mk (Get-PelText 'Schließen' 'Close') 920 $y2 130 $cN 'Bottom,Right'
        $lblHint = New-Object System.Windows.Forms.Label
        $lblHint.Location = New-Object System.Drawing.Point(700, ($y1 + 8))
        $lblHint.Size = New-Object System.Drawing.Size(350, 22)
        $lblHint.ForeColor = [System.Drawing.Color]::FromArgb(170, 178, 190)
        $lblHint.Font = New-Object System.Drawing.Font('Segoe UI', 8.5, [System.Drawing.FontStyle]::Italic)
        $lblHint.Anchor = 'Bottom,Left,Right'
        $d.Controls.Add($lblHint)

        $refresh = {
            param([bool]$Force = $false)
            $running = Test-IntranetRunning
            $menu = Get-PelIntranetMenu $blk
            $orders = @(Get-PelIntranetOrders $blk $menu)
            $sig = (@($orders | ForEach-Object { "$($_.Ip)|$($_.State)|$($_.Text)|$($_.Name)" }) -join ';') + "|$($blk.Closed)|$running"
            if (-not $Force -and $sig -eq $os.Sig) { return }
            $os.Sig = $sig
            $os.Orders = $orders
            $keep = @{}
            foreach ($si in @($lv.SelectedItems)) { $keep[[string]$si.Tag.Ip] = $true }
            $lv.BeginUpdate()
            $lv.Items.Clear()
            foreach ($o in $orders) {
                $li = New-Object System.Windows.Forms.ListViewItem($(if ($o.Time -gt [datetime]::MinValue) { $o.Time.ToString('HH:mm') } else { '' }))
                [void]$li.SubItems.Add([string]$o.Name)
                [void]$li.SubItems.Add([string]$o.Seat)
                [void]$li.SubItems.Add([string]$o.Text)
                [void]$li.SubItems.Add($(if ($o.HasPrice) { Format-PelIntranetMoney $o.Sum } else { '' }))
                [void]$li.SubItems.Add((Get-PelIntranetOrderStateText $o.State))
                [void]$li.SubItems.Add([string]$o.Note)
                switch ($o.State) {
                    'neu' { $li.ForeColor = [System.Drawing.Color]::FromArgb(255, 170, 60) }
                    'da' { $li.ForeColor = [System.Drawing.Color]::FromArgb(120, 220, 140) }
                    'storniert' { $li.ForeColor = [System.Drawing.Color]::Gray }
                }
                $li.Tag = $o
                if ($keep.ContainsKey([string]$o.Ip)) { $li.Selected = $true }
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
            $active = @($orders | Where-Object { $_.State -ne 'storniert' })
            $new = @($orders | Where-Object { $_.State -eq 'neu' })
            $tot = Get-PelIntranetOrderTotals $active
            $head = (Get-PelText '{0} Bestellung(en), davon {1} neu' '{0} order(s), {1} of them new') -f $active.Count, $new.Count
            if ($tot.HasPrice) { $head += '  ·  ' + ((Get-PelText 'Summe {0}' 'Total {0}') -f (Format-PelIntranetMoney $tot.Sum)) }
            if ($blk.Closed) { $head += '  ·  ' + (Get-PelText 'BESTELLSCHLUSS' 'ORDERS CLOSED') }
            $lblHead.Text = $head
            $newTot = Get-PelIntranetOrderTotals $new
            $lines = New-Object System.Collections.Generic.List[string]
            $lines.Add(((Get-PelText 'Neue Bestellungen zusammen ({0}):' 'New orders combined ({0}):') -f $new.Count))
            foreach ($tl in @(Get-PelIntranetTotalLines $newTot '{0,3}x {1}' '  ')) { $lines.Add($tl) }
            if ($newTot.HasPrice) { $lines.Add('  ' + ((Get-PelText 'Summe: {0}' 'Total: {0}') -f (Format-PelIntranetMoney $newTot.Sum))) }
            $txtTot.Text = $lines -join "`r`n"
            foreach ($bt in @($bOrdered, $bWay, $bReady, $bNew, $bCancel, $bAllNew, $bClose)) { $bt.Enabled = $running }
            $bClose.Text = if ($blk.Closed) { Get-PelText 'Bestellungen wieder öffnen' 'Reopen orders' } else { Get-PelText 'Bestellschluss' 'Close orders' }
            $bClose.BackColor = if ($blk.Closed) { $cG } else { $cR }
            $lblHint.Text = if ($running) { Get-PelText 'Status sehen die Gäste auf der Seite unter "Deine Bestellung".' 'Guests see the status on the page under "Your order".' } else { Get-PelText 'Intranet ist nicht veröffentlicht - Status ändern erst nach "Veröffentlichen".' 'Intranet is not published - change status after "Publish".' }
        }
        $setState = {
            param([string]$State, [bool]$OnlyNew = $false)
            $targets = if ($OnlyNew) { @($os.Orders | Where-Object { $_.State -eq 'neu' }) } else { @($lv.SelectedItems | ForEach-Object { $_.Tag }) }
            if ($targets.Count -eq 0) { Show-PelMsg (Get-PelText 'Bitte zuerst Bestellungen in der Liste auswählen.' 'Please select orders in the list first.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d; return }
            $n = 0
            foreach ($o in $targets) { if ([PelIntranetServer]::SetEntryStatus($Id, [string]$o.Ip, $State)) { $n++ } }
            Save-PelIntranetEntries $st.Cfg
            Update-PelIntranetServerContent -Cfg $st.Cfg
            Write-PelLog -Level 'INTRANET' -Message "Bestellungen: $n auf '$State' gesetzt ($($blk.Title))."
            & $refresh $true
        }
        $bOrdered.Add_Click({ & $setState 'bestellt' })
        $bWay.Add_Click({ & $setState 'unterwegs' })
        $bReady.Add_Click({ & $setState 'da' })
        $bNew.Add_Click({ & $setState 'neu' })
        $bCancel.Add_Click({ & $setState 'storniert' })
        $bAllNew.Add_Click({ & $setState 'bestellt' $true })
        $bCopy.Add_Click({
            $new = @($os.Orders | Where-Object { $_.State -eq 'neu' })
            $which = Get-PelText 'neuen' 'new'
            if ($new.Count -eq 0) { $new = @($os.Orders | Where-Object { $_.State -ne 'storniert' }); $which = Get-PelText 'aller' 'all' }
            $tot = Get-PelIntranetOrderTotals $new
            $txt = New-Object System.Collections.Generic.List[string]
            $txt.Add(((Get-PelText 'Sammelbestellung {0} ({1} {2} Bestellungen)' 'Combined order {0} ({1} {2} orders)') -f $st.Cfg.Event.Title, $which, $new.Count))
            foreach ($tl in @(Get-PelIntranetTotalLines $tot)) { $txt.Add($tl) }
            $notes = @($new | Where-Object { $_.Note } | ForEach-Object { "- $($_.Name): $($_.Note)" })
            if ($notes.Count -gt 0) { $txt.Add((Get-PelText 'Anmerkungen:' 'Notes:')); foreach ($nt in $notes) { $txt.Add($nt) } }
            if ($tot.HasPrice) { $txt.Add(((Get-PelText 'Summe laut Karte: {0}' 'Total according to menu: {0}') -f (Format-PelIntranetMoney $tot.Sum))) }
            if (Set-PelClipboard ($txt -join "`r`n")) { Show-PelMsg (Get-PelText 'Sammelbestellung liegt in der Zwischenablage - z. B. beim Lieferdienst einfügen oder am Telefon vorlesen.' 'The combined order is on the clipboard - e.g. paste it at the delivery service or read it out on the phone.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d }
        })
        $bCsv.Add_Click({
            $sfd = New-Object System.Windows.Forms.SaveFileDialog
            $sfd.Filter = 'CSV (*.csv)|*.csv'
            $sfd.FileName = 'Bestellungen_' + (Get-Date -Format 'yyyyMMdd_HHmm') + '.csv'
            $sfd.InitialDirectory = [System.Environment]::GetFolderPath('Desktop')
            if ($sfd.ShowDialog($d) -ne [System.Windows.Forms.DialogResult]::OK) { return }
            try {
                $rows = @($os.Orders | ForEach-Object {
                        [pscustomobject][ordered]@{
                            Zeit = $(if ($_.Time -gt [datetime]::MinValue) { $_.Time.ToString('yyyy-MM-dd HH:mm') } else { '' })
                            Name = $_.Name; Platz = $_.Seat; Bestellung = $_.Text; Artikel = $_.Count
                            Summe = $(if ($_.HasPrice) { ([decimal]$_.Sum).ToString('0.00', [System.Globalization.CultureInfo]::GetCultureInfo('de-DE')) } else { '' })
                            Status = (Get-PelIntranetOrderStateText $_.State); Anmerkung = $_.Note; IP = $_.Ip
                        }
                    })
                $csv = ($rows | ConvertTo-Csv -NoTypeInformation -Delimiter ';') -join "`r`n"
                # Mit BOM, damit Excel die Umlaute richtig anzeigt
                [System.IO.File]::WriteAllText($sfd.FileName, $csv, (New-Object System.Text.UTF8Encoding($true)))
                Show-PelMsg ((Get-PelText "Gespeichert:`n{0}" "Saved:`n{0}") -f $sfd.FileName) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d
            } catch { Show-PelMsg ((Get-PelText "CSV konnte nicht gespeichert werden:`n{0}" "CSV could not be saved:`n{0}") -f $_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d }
        })
        $bClose.Add_Click({
            $blk.Closed = -not [bool]$blk.Closed
            Save-IntranetNow
            Write-PelLog -Level 'INTRANET' -Message "Bestellungen '$($blk.Title)': $(if ($blk.Closed) { 'Bestellschluss' } else { 'wieder offen' })."
            & $refresh $true
        })
        $bExit.Add_Click({ $d.Close() })
        $tmrO = New-Object System.Windows.Forms.Timer
        $tmrO.Interval = 2000
        $tmrO.Add_Tick({ try { & $refresh } catch { } })
        $d.Add_Shown({ & $refresh $true; $tmrO.Start() })
        $d.Add_FormClosed({ $tmrO.Stop(); $tmrO.Dispose() })
        [void]$d.ShowDialog($form)
        $d.Dispose()
    }

    # ---- Speisen & Getränke bearbeiten (Blöcke "Bestellung mit Speisekarte" und "Preisliste") ----
    # Tabelle statt Textzeilen: eigene Speisen und Getränke anlegen, Preise selbst festlegen,
    # pro Artikel "online bestellbar" (Gäste bestellen im Intranet) oder "nur vor Ort" (steht
    # mit Preis auf der Seite, verkauft wird an Theke/Kasse) und "ausverkauft". Funktioniert
    # ohne Internet - alles bleibt im Heimnetz bzw. in der P2P-Lobby. Das Sortiment
    # (sortiment.json) merkt sich eigene Artikel für die nächste LAN-Party.
    function Show-IntranetItemEditor {
        $blk = Get-SelectedBlock
        if (-not $blk -or [string]$blk.Type -notin @('menu', 'prices')) { return }
        $isMenu = ([string]$blk.Type -eq 'menu')
        $data = Get-PelIntranetItemRows ([string]$blk.Text) ([string]$blk.Type)
        $ci = [System.Globalization.CultureInfo]::GetCultureInfo($(if ($script:PelLang -eq 'en') { 'en-GB' } else { 'de-DE' }))
        $vOwn = Get-PelText 'Eigenes Angebot' 'Own offer'
        $vExt = Get-PelText 'Lieferdienst' 'Delivery service'
        $vOnline = Get-PelText 'Online bestellbar' 'Order online'
        $vOnSite = Get-PelText 'Nur vor Ort (Theke)' 'On site only (counter)'
        $ed = @{ Result = $false }

        # Zellinhalt als getrimmter Text (leere Zellen sind $null oder DBNull)
        function Get-CellText($Row, [string]$Col) {
            $v = $Row.Cells[$Col].Value
            if ($null -eq $v -or $v -is [System.DBNull]) { return '' }
            return ([string]$v).Trim()
        }
        function Set-GridRow($Row, $Item) {
            $Row.Cells['Cat'].Value = [string]$Item.Cat
            $Row.Cells['Name'].Value = [string]$Item.Name
            $Row.Cells['Price'].Value = [string]$Item.Price
            $Row.Cells['Desc'].Value = [string]$Item.Desc
            $Row.Cells['Own'].Value = $(if ($Item.Own) { $vOwn } else { $vExt })
            $Row.Cells['Online'].Value = $(if ($Item.Online) { $vOnline } else { $vOnSite })
            $Row.Cells['SoldOut'].Value = [bool]$Item.SoldOut
        }
        # Zeile als Artikel lesen. Leere Herkunft/Verkauf (neue Zeile) = eigenes Angebot, online.
        function Get-GridItem($Row) {
            $sv = $Row.Cells['SoldOut'].Value
            return [pscustomobject]@{
                Cat = (Get-CellText $Row 'Cat'); Name = (Get-CellText $Row 'Name'); Price = (Get-CellText $Row 'Price'); Desc = (Get-CellText $Row 'Desc')
                Own = ((Get-CellText $Row 'Own') -ne $vExt); Online = ((Get-CellText $Row 'Online') -ne $vOnSite); SoldOut = [bool]($sv -is [bool] -and $sv)
            }
        }

        $d = (New-PelForm)
        $d.Text = $(if ($isMenu) { (Get-PelText 'Speisen & Getränke bearbeiten - {0}' 'Edit food & drinks - {0}') -f $blk.Title } else { (Get-PelText 'Preise bearbeiten - {0}' 'Edit prices - {0}') -f $blk.Title })
        $d.Size = New-Object System.Drawing.Size(1120, 720)
        $d.MinimumSize = New-Object System.Drawing.Size(920, 600)
        $d.StartPosition = 'CenterParent'
        $d.BackColor = $cBg
        $d.ForeColor = [System.Drawing.Color]::White
        $d.Font = $fNorm
        $cw = $d.ClientSize.Width
        $ch = $d.ClientSize.Height

        $lblInfo = & $newLbl $(if ($isMenu) { Get-PelText 'Lege eigene Speisen und Getränke an und bestimme die Preise selbst (z. B. 2,50). Herkunft: "Eigenes Angebot" = macht bzw. verkauft die Orga selbst, "Lieferdienst" = wird für die Gäste bestellt. Verkauf: "Online bestellbar" = Gäste bestellen im Intranet, "Nur vor Ort" = steht mit Preis auf der Seite, gekauft wird an Theke/Kasse. Klappt auch ganz ohne Internet.' 'Add your own food and drinks and set the prices yourself (e.g. 2.50). Source: "Own offer" = made or sold by the organizers, "Delivery service" = ordered for the guests. Sale: "Order online" = guests order in the intranet, "On site only" = shown with price on the page, bought at the counter/till. Works without internet, too.' } else { Get-PelText 'Lege alle Preise selbst fest - Eintritt, Getränke, Snacks, Startgeld. Preis als Zahl (2,50 - wird mit Währung angezeigt) oder als Text (frei, 5 € pro Tag).' 'Set all prices yourself - entry, drinks, snacks, tournament fee. Price as a number (2.50 - shown with currency) or as text (free, 5 per day).' }) $fNorm $cMuted
        $lblInfo.Location = New-Object System.Drawing.Point(14, 8)
        $lblInfo.Size = New-Object System.Drawing.Size(($cw - 28), 56)
        $lblInfo.Anchor = 'Top,Left,Right'
        $d.Controls.Add($lblInfo)

        $grid = New-Object System.Windows.Forms.DataGridView
        $grid.Location = New-Object System.Drawing.Point(14, 68)
        $grid.Size = New-Object System.Drawing.Size(($cw - 28), ($ch - 68 - 236))
        $grid.Anchor = 'Top,Bottom,Left,Right'
        $grid.BackgroundColor = $cInput
        $grid.BorderStyle = 'FixedSingle'
        $grid.GridColor = [System.Drawing.Color]::FromArgb(60, 60, 60)
        $grid.EnableHeadersVisualStyles = $false
        $grid.ColumnHeadersDefaultCellStyle.BackColor = $cBtn
        $grid.ColumnHeadersDefaultCellStyle.ForeColor = [System.Drawing.Color]::White
        $grid.ColumnHeadersDefaultCellStyle.SelectionBackColor = $cBtn
        $grid.ColumnHeadersDefaultCellStyle.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Bold)
        $grid.ColumnHeadersHeightSizeMode = 'DisableResizing'
        $grid.ColumnHeadersHeight = 30
        $grid.RowHeadersDefaultCellStyle.BackColor = $cBtn
        $grid.RowHeadersDefaultCellStyle.SelectionBackColor = $cAccent
        $grid.RowHeadersWidth = 30
        $grid.DefaultCellStyle.BackColor = $cInput
        $grid.DefaultCellStyle.ForeColor = [System.Drawing.Color]::White
        $grid.DefaultCellStyle.SelectionBackColor = $cAccent
        $grid.DefaultCellStyle.SelectionForeColor = [System.Drawing.Color]::White
        $grid.AlternatingRowsDefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(28, 28, 28)
        $grid.RowTemplate.Height = 26
        $grid.AllowUserToAddRows = $true
        $grid.AllowUserToDeleteRows = $true
        $grid.AllowUserToResizeRows = $false
        $grid.EditMode = 'EditOnEnter'
        $grid.SelectionMode = 'RowHeaderSelect'
        $grid.MultiSelect = $true
        $grid.AutoSizeColumnsMode = 'Fill'
        foreach ($cd in @(
                @('Cat', (Get-PelText 'Kategorie' 'Category'), 20, 40),
                @('Name', $(if ($isMenu) { Get-PelText 'Speise / Getränk' 'Food / drink' } else { Get-PelText 'Artikel' 'Item' }), 32, 60),
                @('Price', $(if ($isMenu) { Get-PelText ('Preis (' + [char]0x20AC + ')') ('Price (' + [char]0x20AC + ')') } else { Get-PelText 'Preis' 'Price' }), 11, 40),
                @('Desc', $(if ($isMenu) { Get-PelText 'Beschreibung' 'Description' } else { Get-PelText 'Hinweis' 'Note' }), 30, 80))) {
            $col = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
            $col.Name = $cd[0]
            $col.HeaderText = $cd[1]
            $col.FillWeight = $cd[2]
            $col.MaxInputLength = $cd[3]
            $col.SortMode = 'NotSortable'
            [void]$grid.Columns.Add($col)
        }
        foreach ($cd in @(@('Own', (Get-PelText 'Herkunft' 'Source'), 17, @($vOwn, $vExt)), @('Online', (Get-PelText 'Verkauf' 'Sale'), 19, @($vOnline, $vOnSite)))) {
            $col = New-Object System.Windows.Forms.DataGridViewComboBoxColumn
            $col.Name = $cd[0]
            $col.HeaderText = $cd[1]
            $col.FillWeight = $cd[2]
            $col.FlatStyle = 'Flat'
            $col.SortMode = 'NotSortable'
            foreach ($v in $cd[3]) { [void]$col.Items.Add($v) }
            $col.Visible = $isMenu
            [void]$grid.Columns.Add($col)
        }
        $col = New-Object System.Windows.Forms.DataGridViewCheckBoxColumn
        $col.Name = 'SoldOut'
        $col.HeaderText = Get-PelText 'Ausverkauft' 'Sold out'
        $col.FillWeight = 10
        $col.Visible = $isMenu
        [void]$grid.Columns.Add($col)
        $d.Controls.Add($grid)
        foreach ($it in $data.Rows) {
            $ri = $grid.Rows.Add()
            Set-GridRow $grid.Rows[$ri] $it
        }

        $yb = $ch - 228
        $mkB = {
            param([string]$T, [int]$X, [int]$Y, [int]$W, [string]$Kind = '', [string]$Anchor = 'Bottom,Left')
            $bt = & $newBtn $T $W $Kind
            $bt.Location = New-Object System.Drawing.Point($X, $Y)
            $bt.Anchor = $Anchor
            $d.Controls.Add($bt)
            return $bt
        }
        $bUp = & $mkB (Get-PelText 'Nach oben' 'Move up') 14 $yb 110
        $bDown = & $mkB (Get-PelText 'Nach unten' 'Move down') 130 $yb 110
        $bDel = & $mkB (Get-PelText 'Zeile löschen' 'Delete row') 246 $yb 130 'red'
        $bFromSort = & $mkB (Get-PelText 'Aus Sortiment einfügen' 'Insert from my items') 400 $yb 200
        $bToSort = & $mkB (Get-PelText 'Eigene ins Sortiment' 'Save own to my items') 606 $yb 200
        $bFromSort.Visible = $isMenu
        $bToSort.Visible = $isMenu
        [PelI18n]::Tip($tip, $bFromSort, (Get-PelText 'Fügt gespeicherte eigene Speisen und Getränke (mit Preis) aus deinem Sortiment ein - praktisch für die nächste LAN-Party.' 'Inserts saved own food and drinks (with price) from your list - handy for the next LAN party.'))
        [PelI18n]::Tip($tip, $bToSort, (Get-PelText 'Merkt sich alle Zeilen mit "Eigenes Angebot" auf diesem PC (intranet\sortiment.json).' 'Remembers all rows marked "Own offer" on this PC (intranet\sortiment.json).'))

        $lblExtra = & $newLbl $(if ($isMenu) { Get-PelText 'Weitere Angaben, eine pro Zeile - Info: Hinweis für die Gäste  ·  Link: Lieferdienst | Telefon | https://...  ·  Orga: IPs der Orga-PCs' 'More details, one per line - Info: note for the guests  ·  Link: delivery service | phone | https://...  ·  Orga: IPs of organizer PCs' } else { Get-PelText 'Weitere Angaben, eine pro Zeile - Info: Hinweis für die Gäste  ·  Währung: CHF (Standard €)' 'More details, one per line - Info: note for the guests  ·  Currency: CHF (default EUR)' }) $fNorm $cMuted
        $lblExtra.Location = New-Object System.Drawing.Point(14, ($yb + 40))
        $lblExtra.Size = New-Object System.Drawing.Size(($cw - 28), 20)
        $lblExtra.Anchor = 'Bottom,Left,Right'
        $txtExtra = & $newText (($data.Extra -join "`r`n")) $true
        $txtExtra.Location = New-Object System.Drawing.Point(14, ($yb + 62))
        $txtExtra.Size = New-Object System.Drawing.Size(($cw - 28), 70)
        $txtExtra.Anchor = 'Bottom,Left,Right'
        $txtExtra.MaxLength = 3000
        $chkNoNet = New-Object System.Windows.Forms.CheckBox
        $chkNoNet.Text = Get-PelText 'LAN ohne Internet: Lieferdienst-Links und Restaurant-Karte auf der Seite ausblenden' 'LAN without internet: hide delivery service links and restaurant map on the page'
        $chkNoNet.Location = New-Object System.Drawing.Point(14, ($yb + 138))
        $chkNoNet.Size = New-Object System.Drawing.Size(760, 24)
        $chkNoNet.Anchor = 'Bottom,Left'
        $chkNoNet.Checked = [bool]$data.NoInternet
        $chkNoNet.Visible = $isMenu
        $d.Controls.AddRange(@($lblExtra, $txtExtra, $chkNoNet))

        $bOk = & $mkB (Get-PelText 'Übernehmen' 'Apply') 14 ($yb + 176) 170 'accent'
        $bCancel = & $mkB (Get-PelText 'Abbrechen' 'Cancel') ($cw - 14 - 140) ($yb + 176) 140 '' 'Bottom,Right'
        $lblCount = & $newLbl '' $fNorm $cMuted
        $lblCount.Location = New-Object System.Drawing.Point(200, ($yb + 182))
        $lblCount.Size = New-Object System.Drawing.Size(($cw - 200 - 170), 22)
        $lblCount.Anchor = 'Bottom,Left,Right'
        $d.Controls.Add($lblCount)
        $d.CancelButton = $bCancel

        $updCount = {
            $n = 0; $own = 0; $site = 0; $sold = 0
            foreach ($gr in $grid.Rows) {
                if ($gr.IsNewRow) { continue }
                $gi = Get-GridItem $gr
                if (-not $gi.Name) { continue }
                $n++
                if ($gi.Own) { $own++ }
                if (-not $gi.Online) { $site++ }
                if ($gi.SoldOut) { $sold++ }
            }
            if ($isMenu) { $lblCount.Text = (Get-PelText '{0} Artikel - {1} eigene, {2} nur vor Ort, {3} ausverkauft' '{0} items - {1} own, {2} on site only, {3} sold out') -f $n, $own, $site, $sold }
            else { $lblCount.Text = (Get-PelText '{0} Einträge' '{0} entries') -f $n }
        }
        # Neue Zeile: eigenes Angebot, online bestellbar, Kategorie der Zeile darüber
        $grid.Add_DefaultValuesNeeded({
            param($s, $e)
            $e.Row.Cells['Own'].Value = $vOwn
            $e.Row.Cells['Online'].Value = $vOnline
            $e.Row.Cells['SoldOut'].Value = $false
            $pi = $e.Row.Index - 1
            if ($pi -ge 0) { $e.Row.Cells['Cat'].Value = $grid.Rows[$pi].Cells['Cat'].Value }
        })
        # Ungültige Auswahlwerte nicht als Fehlerfenster melden - beim Lesen gilt der Standard
        $grid.Add_DataError({ param($s, $e) $e.ThrowException = $false })
        # Haken und Auswahllisten sofort übernehmen (sonst erst beim Verlassen der Zelle)
        $grid.Add_CurrentCellDirtyStateChanged({
            if ($grid.IsCurrentCellDirty -and $grid.CurrentCell -and -not ($grid.CurrentCell -is [System.Windows.Forms.DataGridViewTextBoxCell])) { [void]$grid.CommitEdit([System.Windows.Forms.DataGridViewDataErrorContexts]::Commit) }
        })
        $grid.Add_CellValueChanged({ try { & $updCount } catch { } })
        $grid.Add_RowsRemoved({ try { & $updCount } catch { } })

        $moveRow = {
            param([int]$Dir)
            [void]$grid.EndEdit()
            $cc = $grid.CurrentCell
            if (-not $cc) { return }
            $i = $cc.RowIndex
            $j = $i + $Dir
            if ($i -lt 0 -or $j -lt 0 -or $j -ge $grid.Rows.Count -or $grid.Rows[$i].IsNewRow -or $grid.Rows[$j].IsNewRow) { return }
            # Werte tauschen statt Zeilen umhängen - bleibt auch mit der "neuen Zeile" am Ende stabil
            for ($k = 0; $k -lt $grid.Columns.Count; $k++) {
                $tmp = $grid.Rows[$i].Cells[$k].Value
                $grid.Rows[$i].Cells[$k].Value = $grid.Rows[$j].Cells[$k].Value
                $grid.Rows[$j].Cells[$k].Value = $tmp
            }
            $grid.CurrentCell = $grid.Rows[$j].Cells[$cc.ColumnIndex]
        }
        $bUp.Add_Click({ & $moveRow -1 })
        $bDown.Add_Click({ & $moveRow 1 })
        $bDel.Add_Click({
            try {
                [void]$grid.EndEdit()
                $idx = @(@(@($grid.SelectedCells | ForEach-Object { $_.RowIndex }) + @($grid.SelectedRows | ForEach-Object { $_.Index })) | Sort-Object -Unique -Descending)
                if ($idx.Count -eq 0 -and $grid.CurrentCell) { $idx = @($grid.CurrentCell.RowIndex) }
                foreach ($ri in $idx) { if ($ri -ge 0 -and $ri -lt $grid.Rows.Count -and -not $grid.Rows[$ri].IsNewRow) { $grid.Rows.RemoveAt($ri) } }
            } catch { Write-PelLog -Level 'INTRANET' -Message "Zeile löschen: $($_.Exception.Message)" }
            & $updCount
        })

        $bToSort.Add_Click({
            [void]$grid.EndEdit()
            $mine = @($grid.Rows | Where-Object { -not $_.IsNewRow } | ForEach-Object { Get-GridItem $_ } | Where-Object { $_.Name -and $_.Own })
            if ($mine.Count -eq 0) { Show-PelMsg (Get-PelText 'Keine Zeile mit Herkunft "Eigenes Angebot" gefunden.' 'No row with source "Own offer" found.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d; return }
            # Gleicher Name = ersetzen (neuer Preis), sonst anhängen
            $all = New-Object System.Collections.Generic.List[object]
            foreach ($x in @(Read-PelIntranetSortiment)) { $all.Add($x) }
            foreach ($m in $mine) {
                $pos = -1
                for ($k = 0; $k -lt $all.Count; $k++) { if ([string]::Equals([string]$all[$k].Name, [string]$m.Name, [System.StringComparison]::OrdinalIgnoreCase)) { $pos = $k; break } }
                if ($pos -ge 0) { $all[$pos] = $m } else { $all.Add($m) }
            }
            if (Save-PelIntranetSortiment $all) {
                Write-PelLog -Level 'INTRANET' -Message "Sortiment: $($mine.Count) eigene Artikel gespeichert (insgesamt $($all.Count))."
                Show-PelMsg ((Get-PelText "{0} eigene Artikel im Sortiment gespeichert (insgesamt {1}).`n`nBei der nächsten LAN-Party: ""Aus Sortiment einfügen""." "{0} own items saved to your list (total {1}).`n`nAt the next LAN party: ""Insert from my items"".") -f $mine.Count, $all.Count) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d
            } else { Show-PelMsg (Get-PelText 'Das Sortiment konnte nicht gespeichert werden (siehe Protokoll).' 'Your list could not be saved (see log).') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d }
        })

        $bFromSort.Add_Click({
            $sx = @{ All = @(Read-PelIntranetSortiment) }
            if ($sx.All.Count -eq 0) { Show-PelMsg (Get-PelText "Dein Sortiment ist noch leer.`n`nLege eigene Speisen und Getränke mit Herkunft ""Eigenes Angebot"" an und klicke ""Eigene ins Sortiment"" - dann stehen sie bei der nächsten LAN-Party hier bereit." "Your list is still empty.`n`nAdd own food and drinks with source ""Own offer"" and click ""Save own to my items"" - then they are ready here for the next LAN party.") 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $d; return }
            $p = (New-PelForm)
            $p.Text = Get-PelText 'Aus Sortiment einfügen' 'Insert from my items'
            $p.Size = New-Object System.Drawing.Size(620, 540)
            $p.MinimumSize = New-Object System.Drawing.Size(500, 400)
            $p.StartPosition = 'CenterParent'
            $p.BackColor = $cBg
            $p.ForeColor = [System.Drawing.Color]::White
            $p.Font = $fNorm
            $pw = $p.ClientSize.Width
            $ph = $p.ClientSize.Height
            $lh = & $newLbl (Get-PelText 'Haken setzen und "Einfügen" - Artikel, die schon in der Tabelle stehen, werden übersprungen.' 'Tick items and click "Insert" - items already in the table are skipped.') $fNorm $cMuted
            $lh.Location = New-Object System.Drawing.Point(14, 10)
            $lh.Size = New-Object System.Drawing.Size(($pw - 28), 40)
            $lh.Anchor = 'Top,Left,Right'
            $clb = New-Object System.Windows.Forms.CheckedListBox
            $clb.Location = New-Object System.Drawing.Point(14, 54)
            $clb.Size = New-Object System.Drawing.Size(($pw - 28), ($ph - 54 - 60))
            $clb.Anchor = 'Top,Bottom,Left,Right'
            $clb.BackColor = $cInput
            $clb.ForeColor = [System.Drawing.Color]::White
            $clb.BorderStyle = 'FixedSingle'
            $clb.CheckOnClick = $true
            $clb.IntegralHeight = $false
            $p.Controls.AddRange(@($lh, $clb))
            $fill = {
                $clb.Items.Clear()
                foreach ($x in $sx.All) {
                    $t = [string]$x.Name
                    if ($x.Price) { $t += '  -  ' + $x.Price }
                    if ($x.Cat) { $t += '  (' + $x.Cat + ')' }
                    if (-not $x.Online) { $t += '  [' + (Get-PelText 'nur vor Ort' 'on site only') + ']' }
                    [void]$clb.Items.Add($t)
                }
            }
            & $fill
            $pIns = & $newBtn (Get-PelText 'Einfügen' 'Insert') 140 'accent'
            $pIns.Location = New-Object System.Drawing.Point(14, ($ph - 46))
            $pIns.Anchor = 'Bottom,Left'
            $pDel = & $newBtn (Get-PelText 'Aus Sortiment entfernen' 'Remove from list') 200 'red'
            $pDel.Location = New-Object System.Drawing.Point(162, ($ph - 46))
            $pDel.Anchor = 'Bottom,Left'
            $pEsc = & $newBtn (Get-PelText 'Abbrechen' 'Cancel') 120
            $pEsc.Location = New-Object System.Drawing.Point(($pw - 14 - 120), ($ph - 46))
            $pEsc.Anchor = 'Bottom,Right'
            $p.Controls.AddRange(@($pIns, $pDel, $pEsc))
            $p.CancelButton = $pEsc
            $pEsc.Add_Click({ $p.Close() })
            $pIns.Add_Click({
                [void]$grid.EndEdit()
                $have = @{}
                foreach ($gr in $grid.Rows) { if (-not $gr.IsNewRow) { $have[(Get-CellText $gr 'Name').ToLowerInvariant()] = $true } }
                $added = 0
                foreach ($ix in @($clb.CheckedIndices)) {
                    $x = $sx.All[[int]$ix]
                    if ($have.ContainsKey(([string]$x.Name).ToLowerInvariant())) { continue }
                    $ri = $grid.Rows.Add()
                    Set-GridRow $grid.Rows[$ri] $x
                    $have[([string]$x.Name).ToLowerInvariant()] = $true
                    $added++
                }
                & $updCount
                $p.Close()
                if ($added -gt 0) { $lblCount.Text += '  ·  ' + ((Get-PelText '{0} aus dem Sortiment eingefügt' '{0} inserted from your list') -f $added) }
            })
            $pDel.Add_Click({
                $rm = @($clb.CheckedIndices | ForEach-Object { [int]$_ })
                if ($rm.Count -eq 0) { return }
                $ans = [PelI18n]::Show($p, ((Get-PelText '{0} Artikel aus dem Sortiment entfernen?' 'Remove {0} item(s) from your list?') -f $rm.Count), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
                if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
                $keep = New-Object System.Collections.Generic.List[object]
                for ($k = 0; $k -lt $sx.All.Count; $k++) { if ($rm -notcontains $k) { $keep.Add($sx.All[$k]) } }
                if (Save-PelIntranetSortiment $keep) { $sx.All = @($keep.ToArray()); & $fill }
            })
            [void]$p.ShowDialog($d)
            $p.Dispose()
        })

        $bCancel.Add_Click({ $d.Close() })
        $bOk.Add_Click({
            [void]$grid.EndEdit()
            $rows = New-Object System.Collections.Generic.List[object]
            $errs = New-Object System.Collections.Generic.List[string]
            $nr = 0
            foreach ($gr in $grid.Rows) {
                if ($gr.IsNewRow) { continue }
                $nr++
                foreach ($c in $gr.Cells) { $c.ErrorText = '' }
                $gi = Get-GridItem $gr
                if (-not $gi.Name -and -not $gi.Price -and -not $gi.Desc) { continue }
                if (-not $gi.Name) {
                    $gr.Cells['Name'].ErrorText = Get-PelText 'Name fehlt' 'Name missing'
                    $errs.Add(((Get-PelText 'Zeile {0}: Name fehlt' 'Row {0}: name missing') -f $nr))
                    continue
                }
                # Speisekarte: Preis als Zahl (für Summe und Bestellung), leer = ohne Preis.
                # Preisliste: Zahl oder freier Text ("frei", "5 € pro Tag").
                if ($isMenu -and $gi.Price) {
                    $pt = ($gi.Price -replace '(?i)\s*(eur|euro)\s*$', '' -replace ('\s*' + [char]0x20AC + '\s*$'), '').Trim()
                    $pv = [decimal]0
                    if ($pt -match '^\d{1,4}([.,]\d{1,2})?$' -and [decimal]::TryParse(($pt -replace ',', '.'), [System.Globalization.NumberStyles]::Number, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$pv)) {
                        $gi.Price = $pv.ToString('0.00', $ci)
                        $gr.Cells['Price'].Value = $gi.Price
                    } else {
                        $gr.Cells['Price'].ErrorText = Get-PelText 'Preis als Zahl, z. B. 2,50' 'Price as a number, e.g. 2.50'
                        $errs.Add(((Get-PelText 'Zeile {0} ({1}): Preis "{2}" ist keine Zahl - z. B. 2,50 oder leer lassen' 'Row {0} ({1}): price "{2}" is not a number - e.g. 2.50 or leave it empty') -f $nr, $gi.Name, $gi.Price))
                        continue
                    }
                }
                $rows.Add($gi)
            }
            $maxItems = if ($isMenu) { 200 } else { 100 }
            if ($rows.Count -gt $maxItems) { $errs.Add(((Get-PelText 'Höchstens {0} Artikel möglich (jetzt {1}).' 'At most {0} items possible (now {1}).') -f $maxItems, $rows.Count)) }
            if ($errs.Count -gt 0) {
                Show-PelMsg ((Get-PelText "Bitte zuerst korrigieren (rot markiert):`n`n{0}" "Please fix first (marked red):`n`n{0}") -f (@($errs | Select-Object -First 12) -join "`n")) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d
                return
            }
            $extra = [string[]]@(($txtExtra.Text -split "`r?`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            $itemText = ConvertTo-PelIntranetItemText $rows $extra ([string]$blk.Type) ([bool]$chkNoNet.Checked)
            $maxTxt = if ($isMenu) { 16000 } else { 8000 }
            if ($itemText.Length -gt $maxTxt) {
                Show-PelMsg ((Get-PelText 'Zu viel Text für einen Block ({0} von höchstens {1} Zeichen) - bitte Beschreibungen kürzen oder einen zweiten Block anlegen.' 'Too much text for one block ({0} of at most {1} characters) - please shorten descriptions or add a second block.') -f $itemText.Length, $maxTxt) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d
                return
            }
            # Bestellungen merken sich die Position der Artikel (q0, q1, ...). Verschieben oder
            # Löschen würde bestehende Bestellungen auf falsche Artikel zeigen lassen - warnen.
            if ($isMenu) {
                $nOrd = @(Get-PelIntranetEntries ([string]$blk.Id)).Count
                if ($nOrd -gt 0) {
                    $oldN = @((Get-PelIntranetMenu $blk).Items | ForEach-Object { [string]$_.Name })
                    $newN = @((Get-PelIntranetMenu ([pscustomobject]@{ Text = $itemText })).Items | ForEach-Object { [string]$_.Name })
                    $shift = $false
                    for ($k = 0; $k -lt $oldN.Count; $k++) { if ($k -ge $newN.Count -or $oldN[$k] -ne $newN[$k]) { $shift = $true; break } }
                    if ($shift) {
                        $ans = [PelI18n]::Show($d, ((Get-PelText "Es gibt schon {0} Bestellung(en). Bestellungen merken sich die Position der Artikel - durch Verschieben, Umbenennen oder Löschen zeigen sie danach evtl. auf andere Artikel.`n`nTipp: Neue Artikel unten anfügen und nicht mehr erhältliche auf ""ausverkauft"" setzen.`n`nTrotzdem übernehmen?" "There are already {0} order(s). Orders remember the position of the items - after moving, renaming or deleting they may point to other items.`n`nTip: add new items at the bottom and set items no longer available to ""sold out"".`n`nApply anyway?") -f $nOrd), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
                        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
                    }
                }
            }
            $blk.Text = $itemText
            $ed.Result = $true
            Write-PelLog -Level 'INTRANET' -Message "Speisen & Getränke '$($blk.Title)': $($rows.Count) Artikel übernommen ($(@($rows | Where-Object { $_.Own }).Count) eigene, $(@($rows | Where-Object { -not $_.Online }).Count) nur vor Ort)."
            $d.Close()
        })
        $d.Add_Shown({ & $updCount })
        [void]$d.ShowDialog($form)
        $d.Dispose()
        if ($ed.Result) {
            Show-BlockProps
            Set-IntranetDirty
            Save-IntranetNow
        }
    }

    function Set-IntranetDirty {
        if ($st.Loading) { return }
        $st.Cfg.Blocks = $st.Blocks.ToArray()
        $st.Dirty = $true
        $st.DirtyAt = [datetime]::Now
    }

    function Save-IntranetNow {
        $st.Cfg.Blocks = $st.Blocks.ToArray()
        $st.Dirty = $false
        [void](Save-PelIntranetConfig $st.Cfg)
        if (Test-IntranetRunning) { try { Update-PelIntranetServerContent -Cfg $st.Cfg } catch { Write-PelLog -Level 'INTRANET' -Message "Seite aktualisieren: $($_.Exception.Message)" } }
        if ($st.Page -eq 'build') { Update-IntranetPreview }
    }

    function Update-IntranetPreview {
        try {
            $y = 0
            try {
                if ($wbPreview.Document -and $wbPreview.Document.GetElementsByTagName('html').Count -gt 0) {
                    $y = $wbPreview.Document.GetElementsByTagName('html')[0].ScrollTop
                    if ($y -le 0 -and $wbPreview.Document.Body) { $y = $wbPreview.Document.Body.ScrollTop }
                }
            } catch { $y = 0 }
            $st.PreviewScroll = $y
            $st.Cfg.Blocks = $st.Blocks.ToArray()
            if ($st.Cfg.Mode -eq 'extern') {
                $lblPrevHdr.Text = Get-PelText 'Vorschau deines Baukastens - veröffentlicht wird zurzeit das Veranstalter-Intranet (siehe Einstellungen)' 'Preview of your builder page - the organizer intranet is currently published (see settings)'
            } else {
                $lblPrevHdr.Text = Get-PelText 'Vorschau - so sehen es die anderen' 'Preview - this is what the others see'
            }
            $wbPreview.DocumentText = Build-PelIntranetHtml -Cfg $st.Cfg -Mode 'preview' -Embed $true
        } catch { $lblStatus.Text = (Get-PelText 'Vorschau fehlgeschlagen: {0}' 'Preview failed: {0}') -f $_.Exception.Message }
    }

    function Update-IntranetUrls {
        $urls = @(Get-PelIntranetUrls ([int]$st.Cfg.Port))
        if ($urls.Count -eq 0) { $txtUrls.Text = Get-PelText '(keine Netzwerkverbindung gefunden)' '(no network connection found)' }
        else { $txtUrls.Text = (@($urls | ForEach-Object { "$($_.Kind):  $($_.Url)" }) -join "`r`n") }
    }

    function Update-IntranetState {
        $run = Test-IntranetRunning
        if ($run) {
            $btnPublish.Text = Get-PelText 'Veröffentlicht - beenden' 'Published - stop'
            $btnPublish.BackColor = $cRed
            $what = Get-PelText 'eigenes Intranet' 'own intranet'
            if ($st.Cfg.Mode -eq 'extern') { $what = Get-PelText 'Veranstalter-Intranet' 'organizer intranet' }
            $lblTopState.Text = (Get-PelText 'Online: {0} auf Port {1}' 'Online: {0} on port {1}') -f $what, [PelIntranetServer]::Port
            $lblTopState.ForeColor = [System.Drawing.Color]::LightGreen
        } else {
            $btnPublish.Text = Get-PelText 'Veröffentlichen' 'Publish'
            $btnPublish.BackColor = $cGreen
            $lblTopState.Text = Get-PelText 'Dein Intranet ist nicht veröffentlicht' 'Your intranet is not published'
            $lblTopState.ForeColor = $cMuted
        }
    }

    function Add-FoundEntry($x) {
        if (-not $x) { return }
        $key = [string]$x.Ip
        if ($st.Found.ContainsKey($key)) { return }
        $st.Found[$key] = $x
        $it = New-Object System.Windows.Forms.ListViewItem([string]$x.Name)
        [void][PelI18n]::AddSub($it, [string]$x.Host)
        $addr = [string]$x.Ip
        if ($x.Mode -eq 'extern') { $addr = ([Uri]$x.Url).Host }
        [void][PelI18n]::AddSub($it, $addr)
        $it.Tag = $x
        if ($x.Ip -eq 'self') { $it.ForeColor = [System.Drawing.Color]::LightSkyBlue } else { $it.ForeColor = [System.Drawing.Color]::White }
        [void]$lvFound.Items.Add($it)
        if (-not $st.UserPicked -and -not $st.Current -and $x.Ip -ne 'self') { $it.Selected = $true }
    }

    function Add-SelfEntry {
        if (-not (Test-IntranetRunning)) { return }
        $p = [PelIntranetServer]::Port
        $url = "http://127.0.0.1:$p/?embed=1"
        $burl = "http://127.0.0.1:$p/"
        $mode = 'own'
        if ($st.Cfg.Mode -eq 'extern') { $url = $st.Cfg.ExternUrl; $burl = $url; $mode = 'extern' }
        Add-FoundEntry ([pscustomobject]@{ Ip = 'self'; Name = [string]$st.Cfg.Event.Title; Host = (Get-PelText '(du)' '(you)'); Mode = $mode; Url = $url; BrowserUrl = $burl })
    }

    function Start-IntranetScan {
        if ($st.Scanner -and -not $st.Scanner.Finished) { return }
        $st.Found = @{}
        $lvFound.Items.Clear()
        Add-SelfEntry
        $ips = @(Get-PelIntranetScanTargets)
        if ($ips.Count -eq 0) { $lblScan.Text = Get-PelText 'Keine Netzwerkverbindung gefunden.' 'No network connection found.'; return }
        $sc = New-Object PelIntranetScanner
        $sc.Ips = [string[]]$ips
        $sc.Port = $script:PelIntranetDefaultPort
        $st.Scanner = $sc
        $btnScan.Enabled = $false
        $lblScan.Text = (Get-PelText 'Suche läuft ({0} Adressen) ...' 'Searching ({0} addresses) ...') -f $ips.Count
        $sc.Start()
    }

    function Open-IntranetEntry($x) {
        if (-not $x) { return }
        $st.Current = $x
        $txt = [string]$x.BrowserUrl
        if ($x.Mode -eq 'extern') { $txt += '   ' + (Get-PelText '- Seite des Veranstalters. Sieht sie hier komisch aus? "Im Browser öffnen".' '- organizer page. Looks odd here? "Open in browser".') }
        $lblViewUrl.Text = $txt
        try { $wbView.Navigate([string]$x.Url) } catch { $lblStatus.Text = $_.Exception.Message }
    }

    function Invoke-IntranetPublish {
        if (Test-IntranetRunning) {
            Stop-PelIntranetServer $st.Cfg
            Update-IntranetState
            if ($st.Found.ContainsKey('self')) { Start-IntranetScan }
            return
        }
        if ($st.Cfg.Mode -eq 'extern' -and -not $st.Cfg.ExternUrl) {
            Show-PelMsg (Get-PelText 'Bitte unter "Einstellungen" eine gültige Adresse des Veranstalter-Intranets eintragen oder "Eigenes Intranet" wählen.' 'Please enter a valid organizer intranet address under "Settings" or choose "Own intranet".') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form
            Show-IntranetPage 'set'
            return
        }
        if ($st.Dirty) { Save-IntranetNow }
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            Start-PelIntranetServer $st.Cfg
            $lblStatus.Text = Get-PelText 'Veröffentlicht. Die anderen finden es unter "Intranet ansehen" -> "Suchen".' 'Published. The others find it under "View intranet" -> "Search".'
        } catch {
            Show-PelMsg ([string]$_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Error) $form
        } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
        Update-IntranetState
        Update-IntranetUrls
        if (Test-IntranetRunning) {
            Add-SelfEntry
            Update-EntryCount (Get-SelectedBlock)
        }
    }

    # ---- Ereignisse: Navigation ------------------------------------------------------
    $btnNavView.Add_Click({ Show-IntranetPage 'view' })
    $btnNavBuild.Add_Click({ Show-IntranetPage 'build' })
    $btnNavSet.Add_Click({ Show-IntranetPage 'set' })

    # ---- Ereignisse: Ansehen ---------------------------------------------------------
    $btnScan.Add_Click({ Start-IntranetScan })
    $btnReload.Add_Click({ if ($st.Current) { Open-IntranetEntry $st.Current } })
    $lvFound.Add_SelectedIndexChanged({
        if ($lvFound.SelectedItems.Count -eq 0) { return }
        Open-IntranetEntry $lvFound.SelectedItems[0].Tag
    })
    $lvFound.Add_MouseDown({ $st.UserPicked = $true })
    $btnAddr.Add_Click({
        $st.UserPicked = $true
        $in = [Microsoft.VisualBasic.Interaction]::InputBox((Get-PelText 'Adresse des Intranets (z. B. 10.77.0.5, 192.168.1.20:9931 oder http://lan.local):' 'Intranet address (e.g. 10.77.0.5, 192.168.1.20:9931 or http://lan.local):'), 'Intranet', '')
        $in = ([string]$in).Trim()
        if (-not $in) { return }
        $x = $null
        if ($in -match '^(\d{1,3}(\.\d{1,3}){3})(:(\d{1,5}))?$') {
            $p = $script:PelIntranetDefaultPort
            if ($matches[4]) { $p = [int]$matches[4] }
            $u = Test-PelIntranetUrl ("http://$($matches[1]):$p/")
            if ($u) { $x = [pscustomobject]@{ Ip = $matches[1]; Name = $in; Host = ''; Mode = 'own'; Url = ($u + '?embed=1'); BrowserUrl = $u } }
        } else {
            $u = Test-PelIntranetUrl $in
            if ($u) { $x = [pscustomobject]@{ Ip = ([Uri]$u).Host; Name = $in; Host = ''; Mode = 'extern'; Url = $u; BrowserUrl = $u } }
        }
        if (-not $x) {
            Show-PelMsg (Get-PelText 'Diese Adresse liegt nicht im lokalen Netz. Erlaubt sind private IPs (z. B. 10.x, 192.168.x, 10.77.x.y) und lokale Namen wie lan.local.' 'This address is not in the local network. Allowed are private IPs (e.g. 10.x, 192.168.x, 10.77.x.y) and local names such as lan.local.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form
            return
        }
        Open-IntranetEntry $x
    })
    $btnBrowser.Add_Click({
        if (-not $st.Current) { return }
        $u = Test-PelIntranetUrl ([string]$st.Current.BrowserUrl)
        if ($u) { try { Start-Process $u } catch { } }
    })
    $wbView.Add_Navigating({
        param($s, $e)
        $u = $e.Url
        if (-not $u) { return }
        $scheme = [string]$u.Scheme
        if ($scheme -eq 'about') { return }
        if ($scheme -eq 'pel-join') {
            $e.Cancel = $true
            $ip = [string]$u.Host
            if ($ip -notmatch '^\d{1,3}(\.\d{1,3}){3}$') { return }
            $q = [System.Web.HttpUtility]::ParseQueryString($u.Query)
            $game = Limit-PelText ([string]$q['g']) 80
            $port = [int]$u.Port
            if ($q['noport']) { $port = 0 }
            $res = Invoke-PelJoinGame -Ip $ip -Port $port -JoinPort $port -GameName $game -ParentForm $form
            if ($res) { $lblStatus.Text = [string]$res }
            return
        }
        if ($scheme -in @('http', 'https') -and (Test-PelIntranetUrl $u.AbsoluteUri)) { return }
        $e.Cancel = $true
        if ($scheme -in @('http', 'https')) {
            $ans = [PelI18n]::Show($form, ((Get-PelText "Dieser Link führt aus dem lokalen Netz heraus:`n{0}`n`nIm normalen Browser öffnen?" "This link leads outside the local network:`n{0}`n`nOpen it in your normal browser?") -f $u.AbsoluteUri), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
            if ($ans -eq [System.Windows.Forms.DialogResult]::Yes) { try { Start-Process $u.AbsoluteUri } catch { } }
        }
    })
    $wbView.Add_NewWindow({ param($s, $e) $e.Cancel = $true; $lblStatus.Text = Get-PelText 'Neue Fenster sind hier gesperrt - "Im Browser öffnen" nutzen.' 'New windows are blocked here - use "Open in browser".' })
    $wbPreview.Add_Navigating({
        param($s, $e)
        # In der Vorschau führen Links nirgendwohin - sie ist nur zum Anschauen
        if ($e.Url -and [string]$e.Url.Scheme -ne 'about') { $e.Cancel = $true }
    })
    $wbPreview.Add_NewWindow({ param($s, $e) $e.Cancel = $true })
    $wbPreview.Add_DocumentCompleted({
        if ($st.PreviewScroll -gt 0) {
            try { $wbPreview.Document.Window.ScrollTo(0, [int]$st.PreviewScroll) } catch { }
        }
    })

    # ---- Ereignisse: Baukasten -------------------------------------------------------
    $lbBlocks.Add_SelectedIndexChanged({ if (-not $st.Loading) { Show-BlockProps } })
    $txtBTitle.Add_TextChanged({
        $b = Get-SelectedBlock
        if ($st.Loading -or -not $b) { return }
        $b.Title = Limit-PelText $txtBTitle.Text 60
        $i = $lbBlocks.SelectedIndex
        $st.Loading = $true
        try { $lbBlocks.Items[$i] = (Get-BlockLabel $b $i) } finally { $st.Loading = $false }
        Set-IntranetDirty
    })
    $txtBText.Add_TextChanged({
        $b = Get-SelectedBlock
        if ($st.Loading -or -not $b) { return }
        $t = ($txtBText.Text -replace "`r", '')
        # BUGFIX: hier wurde jeder Block auf 4000 Zeichen gekürzt - beim Laden dürfen Speisekarte
        # (16000) und Preisliste (8000) aber länger sein. Große Karten wurden so beim ersten
        # Tippen abgeschnitten. Jetzt dieselben Grenzen wie in Repair-PelIntranetConfig.
        $maxTxt = if ([string]$b.Type -eq 'menu') { 16000 } elseif ([string]$b.Type -eq 'prices') { 8000 } else { 4000 }
        if ($t.Length -gt $maxTxt) { $t = $t.Substring(0, $maxTxt) }
        $b.Text = $t
        Set-IntranetDirty
    })
    $chkWide.Add_CheckedChanged({ $b = Get-SelectedBlock; if ($st.Loading -or -not $b) { return }; $b.Wide = $chkWide.Checked; Set-IntranetDirty })
    $chkVisible.Add_CheckedChanged({
        $b = Get-SelectedBlock
        if ($st.Loading -or -not $b) { return }
        $b.Visible = $chkVisible.Checked
        $i = $lbBlocks.SelectedIndex
        $st.Loading = $true
        try { $lbBlocks.Items[$i] = (Get-BlockLabel $b $i) } finally { $st.Loading = $false }
        Set-IntranetDirty
    })
    $btnAdd.Add_Click({
        if ($st.Blocks.Count -ge 30) { Show-PelMsg (Get-PelText 'Mehr als 30 Blöcke sind nicht möglich.' 'More than 30 blocks are not possible.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $form; return }
        $t = $types[$cbAddType.SelectedIndex]
        $nb = New-PelIntranetBlock $t.Key $t.Name ''
        # Speisekarte gleich mit Beispiel (Lieferdienste, Kategorien, Preise) - leichter anzupassen als ein leeres Feld
        if ($t.Key -eq 'menu') { $nb.Text = Get-PelIntranetMenuSample; $nb.Wide = $true }
        if ($t.Key -eq 'prices') { $nb.Text = Get-PelIntranetPriceSample }
        if ($t.Key -eq 'seatmap') { $nb.Text = Get-PelIntranetSeatSample; $nb.Wide = $true }
        $pos = $lbBlocks.SelectedIndex + 1
        if ($pos -le 0 -or $pos -gt $st.Blocks.Count) { $pos = $st.Blocks.Count }
        $st.Blocks.Insert($pos, $nb)
        Set-IntranetDirty
        Update-BlockList $pos
        [void]$txtBText.Focus()
    })
    $btnDel.Add_Click({
        $b = Get-SelectedBlock
        if (-not $b) { return }
        $ans = [PelI18n]::Show($form, ((Get-PelText "Block '{0}' entfernen?" "Remove block '{0}'?") -f $b.Title), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        $i = $lbBlocks.SelectedIndex
        $st.Blocks.RemoveAt($i)
        Set-IntranetDirty
        Update-BlockList ($i - 1)
    })
    $moveBlock = {
        param([int]$Dir)
        $i = $lbBlocks.SelectedIndex
        $j = $i + $Dir
        if ($i -lt 0 -or $j -lt 0 -or $j -ge $st.Blocks.Count) { return }
        $tmp = $st.Blocks[$i]
        $st.Blocks[$i] = $st.Blocks[$j]
        $st.Blocks[$j] = $tmp
        Set-IntranetDirty
        Update-BlockList $j
    }
    $btnUp.Add_Click({ & $moveBlock -1 })
    $btnDown.Add_Click({ & $moveBlock 1 })
    $btnItems.Add_Click({ Show-IntranetItemEditor })
    $btnOrders.Add_Click({
        $b = Get-SelectedBlock
        if ($b -and $b.Type -eq 'menu') { Show-IntranetOrders ([string]$b.Id) }
        elseif ($b -and $b.Type -eq 'seatmap') { Show-IntranetCheckin ([string]$b.Id) }
    })
    $btnClearEntries.Add_Click({
        $b = Get-SelectedBlock
        if (-not $b) { return }
        $ans = [PelI18n]::Show($form, ((Get-PelText "Alle Stimmen bzw. Einträge in '{0}' löschen?`n`nDas lässt sich nicht rückgängig machen." "Delete all votes or entries in '{0}'?`n`nThis cannot be undone.") -f $b.Title), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Warning)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        Clear-PelIntranetEntries $st.Cfg ([string]$b.Id)
        Update-EntryCount $b
        Save-IntranetNow
    })

    $txtTitle.Add_TextChanged({ if ($st.Loading) { return }; $st.Cfg.Event.Title = Limit-PelText $txtTitle.Text 80; Set-IntranetDirty })
    $txtDate.Add_TextChanged({ if ($st.Loading) { return }; $st.Cfg.Event.Date = Limit-PelText $txtDate.Text 60; Set-IntranetDirty })
    $txtPlace.Add_TextChanged({ if ($st.Loading) { return }; $st.Cfg.Event.Place = Limit-PelText $txtPlace.Text 80; Set-IntranetDirty })
    $txtOrg.Add_TextChanged({ if ($st.Loading) { return }; $st.Cfg.Event.Organizer = Limit-PelText $txtOrg.Text 60; Set-IntranetDirty })
    $txtCdText.Add_TextChanged({ if ($st.Loading) { return }; $st.Cfg.Event.CountdownText = Limit-PelText $txtCdText.Text 40; Set-IntranetDirty })
    $dtpCd.Add_ValueChanged({
        if ($st.Loading) { return }
        if ($dtpCd.Checked) { $st.Cfg.Event.Countdown = $dtpCd.Value.ToString('yyyy-MM-ddTHH:mm', [System.Globalization.CultureInfo]::InvariantCulture) } else { $st.Cfg.Event.Countdown = '' }
        Set-IntranetDirty
    })
    $btnAccent.Add_Click({
        $cd = New-Object System.Windows.Forms.ColorDialog
        $cd.Color = $pnlAccent.BackColor
        $cd.FullOpen = $true
        if ($cd.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $c = $cd.Color
        $st.Cfg.Event.Accent = ('#{0:x2}{1:x2}{2:x2}' -f $c.R, $c.G, $c.B)
        $pnlAccent.BackColor = $c
        Set-IntranetDirty
    })
    $btnLogo.Add_Click({
        $ofd = New-Object System.Windows.Forms.OpenFileDialog
        $ofd.Filter = (Get-PelText 'Bilder (*.png;*.jpg;*.jpeg;*.gif)|*.png;*.jpg;*.jpeg;*.gif' 'Images (*.png;*.jpg;*.jpeg;*.gif)|*.png;*.jpg;*.jpeg;*.gif')
        if ($ofd.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        try {
            $fi = New-Object System.IO.FileInfo($ofd.FileName)
            if ($fi.Length -gt 2097152) { Show-PelMsg (Get-PelText 'Das Bild ist größer als 2 MB - bitte ein kleineres nehmen.' 'The image is larger than 2 MB - please choose a smaller one.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form; return }
            $ext = $fi.Extension.ToLowerInvariant().TrimStart('.')
            if ($ext -eq 'jpeg') { $ext = 'jpg' }
            if ($ext -notin @('png', 'jpg', 'gif')) { return }
            Initialize-PelIntranetFolders
            foreach ($old in @(Get-ChildItem -LiteralPath $script:PelIntranetDir -File -Filter 'logo.*' -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
            Copy-Item -LiteralPath $fi.FullName -Destination (Join-Path $script:PelIntranetDir "logo.$ext") -Force
            $st.Cfg.Event.Logo = "logo.$ext"
            $btnLogoDel.Enabled = $true
            Set-IntranetDirty
        } catch { Show-PelMsg ([string]$_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Error) $form }
    })
    $cbLogoSize.Add_SelectedIndexChanged({
        if ($st.Loading) { return }
        $st.Cfg.Event.LogoSize = @('S', 'M', 'L')[[Math]::Max(0, $cbLogoSize.SelectedIndex)]
        Set-IntranetDirty
    })
    $cbHeaderMode.Add_SelectedIndexChanged({
        if ($st.Loading) { return }
        $st.Cfg.Event.HeaderMode = if ($cbHeaderMode.SelectedIndex -eq 1) { 'background' } else { 'banner' }
        Set-IntranetDirty
    })
    $chkHideTitle.Add_CheckedChanged({
        if ($st.Loading) { return }
        $st.Cfg.Event.HideTitle = [bool]$chkHideTitle.Checked
        Set-IntranetDirty
    })
    $btnHeader.Add_Click({
        $ofd = New-Object System.Windows.Forms.OpenFileDialog
        $ofd.Filter = (Get-PelText 'Bilder (*.png;*.jpg;*.jpeg;*.gif)|*.png;*.jpg;*.jpeg;*.gif' 'Images (*.png;*.jpg;*.jpeg;*.gif)|*.png;*.jpg;*.jpeg;*.gif')
        if ($ofd.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        try {
            $fi = New-Object System.IO.FileInfo($ofd.FileName)
            if ($fi.Length -gt 5242880) { Show-PelMsg (Get-PelText 'Das Kopfbild ist größer als 5 MB - bitte ein kleineres nehmen (z. B. als JPG speichern).' 'The header image is larger than 5 MB - please choose a smaller one (e.g. save it as JPG).') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form; return }
            $ext = $fi.Extension.ToLowerInvariant().TrimStart('.')
            if ($ext -eq 'jpeg') { $ext = 'jpg' }
            if ($ext -notin @('png', 'jpg', 'gif')) { return }
            Initialize-PelIntranetFolders
            foreach ($old in @(Get-ChildItem -LiteralPath $script:PelIntranetDir -File -Filter 'header.*' -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
            Copy-Item -LiteralPath $fi.FullName -Destination (Join-Path $script:PelIntranetDir "header.$ext") -Force
            $st.Cfg.Event.Header = "header.$ext"
            $btnHeaderDel.Enabled = $true
            Set-IntranetDirty
        } catch { Show-PelMsg ([string]$_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Error) $form }
    })
    $btnHeaderDel.Add_Click({
        foreach ($old in @(Get-ChildItem -LiteralPath $script:PelIntranetDir -File -Filter 'header.*' -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
        $st.Cfg.Event.Header = ''
        $btnHeaderDel.Enabled = $false
        Set-IntranetDirty
    })
    $btnLogosAdd.Add_Click({
        $ofd = New-Object System.Windows.Forms.OpenFileDialog
        $ofd.Multiselect = $true
        $ofd.Filter = (Get-PelText 'Bilder (*.png;*.jpg;*.jpeg;*.gif)|*.png;*.jpg;*.jpeg;*.gif' 'Images (*.png;*.jpg;*.jpeg;*.gif)|*.png;*.jpg;*.jpeg;*.gif')
        if ($ofd.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        Initialize-PelIntranetFolders
        $added = 0
        $skipped = New-Object System.Collections.Generic.List[string]
        foreach ($fn in $ofd.FileNames) {
            try {
                $fi = New-Object System.IO.FileInfo($fn)
                if ($fi.Length -gt 2097152) { $skipped.Add("$($fi.Name) (> 2 MB)"); continue }
                if (@(Get-PelIntranetLogoFiles).Count -ge 24) { $skipped.Add("$($fi.Name) (" + (Get-PelText 'höchstens 24 Logos' 'max. 24 logos') + ")"); continue }
                $clean = (($fi.Name -replace '[^\w\.\- ]', '_').Trim())
                if ($clean.StartsWith('.')) { $clean = '_' + $clean }
                Copy-Item -LiteralPath $fi.FullName -Destination (Join-Path $script:PelIntranetLogosDir $clean) -Force
                $added++
            } catch { $skipped.Add($fn) }
        }
        $msg = (Get-PelText '{0} Bild(er) hinzugefügt.' '{0} image(s) added.') -f $added
        if ($skipped.Count -gt 0) { $msg += "`n`n" + (Get-PelText 'Nicht übernommen:' 'Not added:') + "`n" + ($skipped -join "`n") }
        Show-PelMsg $msg 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $form
        Set-IntranetDirty
    })
    $btnLogosDir.Add_Click({
        Initialize-PelIntranetFolders
        try { Start-Process explorer.exe -ArgumentList "`"$($script:PelIntranetLogosDir)`"" } catch { }
    })
    $btnLogoDel.Add_Click({
        foreach ($old in @(Get-ChildItem -LiteralPath $script:PelIntranetDir -File -Filter 'logo.*' -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $old.FullName -Force -ErrorAction SilentlyContinue }
        $st.Cfg.Event.Logo = ''
        $btnLogoDel.Enabled = $false
        Set-IntranetDirty
    })
    $btnTplLoad.Add_Click({
        $t = $tpls[$cbTpl.SelectedIndex]
        $ans = [PelI18n]::Show($form, ((Get-PelText "Vorlage '{0}' laden?`n`nDie jetzigen Blöcke werden dabei ersetzt. Name, Datum, Ort, Farbe und Logo bleiben." "Load template '{0}'?`n`nThe current blocks will be replaced. Name, date, location, color and logo stay.") -f $t.Name), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        $st.Blocks.Clear()
        foreach ($b in @(New-PelIntranetTemplate $t.Key)) { $st.Blocks.Add($b) }
        $st.Cfg.Template = $t.Key
        Set-IntranetDirty
        Update-BlockList 0
        Save-IntranetNow
    })
    $btnExport.Add_Click({
        $sfd = New-Object System.Windows.Forms.SaveFileDialog
        $sfd.Filter = 'ZIP (*.zip)|*.zip'
        $safe = ([string]$st.Cfg.Event.Title) -replace '[^\w\- ]', '' -replace '\s+', '_'
        if (-not $safe) { $safe = 'Intranet' }
        $sfd.FileName = "Intranet_$safe.zip"
        $sfd.InitialDirectory = [Environment]::GetFolderPath('Desktop')
        if ($sfd.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        try {
            Save-IntranetNow
            Export-PelIntranetZip $st.Cfg $sfd.FileName
            $lblStatus.Text = (Get-PelText 'Exportiert: {0}' 'Exported: {0}') -f $sfd.FileName
        } catch { Show-PelMsg ([string]$_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Error) $form }
    })
    $btnImport.Add_Click({
        $ofd = New-Object System.Windows.Forms.OpenFileDialog
        $ofd.Filter = 'ZIP (*.zip)|*.zip'
        if ($ofd.ShowDialog($form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $ans = [PelI18n]::Show($form, (Get-PelText "Intranet aus der Datei übernehmen?`n`nDeine jetzige Seite wird dabei ersetzt. Port und Einstellungen zum Veröffentlichen bleiben." "Use the intranet from this file?`n`nYour current page will be replaced. Port and publishing settings stay."), 'Intranet', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        try {
            $imp = Import-PelIntranetZip $ofd.FileName
            $imp.Port = $st.Cfg.Port
            $imp.AutoPublish = $st.Cfg.AutoPublish
            $imp.Mode = $st.Cfg.Mode
            $imp.ExternUrl = $st.Cfg.ExternUrl
            $st.Cfg = $imp
            $st.Blocks.Clear()
            foreach ($b in @($imp.Blocks)) { $st.Blocks.Add($b) }
            Show-EventProps
            Update-BlockList 0
            Save-IntranetNow
            $lblStatus.Text = Get-PelText 'Intranet übernommen.' 'Intranet imported.'
        } catch { Show-PelMsg ((Get-PelText "Die Datei konnte nicht übernommen werden:`n{0}" "The file could not be imported:`n{0}") -f $_.Exception.Message) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Error) $form }
    })
    $btnDlDir.Add_Click({ Initialize-PelIntranetFolders; try { Start-Process explorer.exe $script:PelIntranetDownloadDir } catch { } })
    $btnPublish.Add_Click({ Invoke-IntranetPublish })

    # ---- Ereignisse: Einstellungen ---------------------------------------------------
    $applyMode = {
        if ($st.Loading) { return }
        $u = Test-PelIntranetUrl $txtExtern.Text
        if ($txtExtern.Text.Trim() -and -not $u) { $lblExtHint.ForeColor = $cErr } else { $lblExtHint.ForeColor = $cMuted }
        if ($u) { $st.Cfg.ExternUrl = $u }
        $old = $st.Cfg.Mode
        if ($rbExtern.Checked -and $st.Cfg.ExternUrl) { $st.Cfg.Mode = 'extern' } else { $st.Cfg.Mode = 'own' }
        Set-IntranetDirty
        if ($old -ne $st.Cfg.Mode) { Update-IntranetState }
    }
    $rbOwn.Add_CheckedChanged($applyMode)
    $rbExtern.Add_CheckedChanged($applyMode)
    $txtExtern.Add_TextChanged($applyMode)
    $btnTest.Add_Click({
        $u = Test-PelIntranetUrl $txtExtern.Text
        if (-not $u) {
            Show-PelMsg (Get-PelText 'Diese Adresse liegt nicht im lokalen Netz und kann nicht eingebettet werden.' 'This address is not in the local network and cannot be embedded.') 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form
            return
        }
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            $req = [System.Net.HttpWebRequest]::Create($u)
            $req.Timeout = 4000
            $req.AllowAutoRedirect = $true
            $resp = $req.GetResponse()
            $code = [int]$resp.StatusCode
            $resp.Close()
            Show-PelMsg ((Get-PelText "Erreichbar (HTTP {0}). Die Gäste sehen diese Seite, sobald du veröffentlichst." "Reachable (HTTP {0}). Guests will see this page as soon as you publish.") -f $code) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Information) $form
        } catch {
            Show-PelMsg ((Get-PelText "Die Seite antwortet nicht:`n{0}`n`nLäuft das Intranet des Veranstalters und ist die Adresse richtig?" "The page does not respond:`n{0}`n`nIs the organizer intranet running and is the address correct?") -f (Get-PelInnerMessage $_)) 'Intranet' ([System.Windows.Forms.MessageBoxIcon]::Warning) $form
        } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
    })
    $numPort.Add_ValueChanged({
        if ($st.Loading) { return }
        $st.Cfg.Port = [int]$numPort.Value
        Set-IntranetDirty
        Update-IntranetUrls
        if (Test-IntranetRunning) { $lblStatus.Text = Get-PelText 'Der neue Port gilt nach dem nächsten Veröffentlichen.' 'The new port applies after publishing again.' }
    })
    $chkAuto.Add_CheckedChanged({ if ($st.Loading) { return }; $st.Cfg.AutoPublish = $chkAuto.Checked; Set-IntranetDirty })
    $btnCopyUrl.Add_Click({ if (Set-PelClipboard $txtUrls.Text) { $lblStatus.Text = Get-PelText 'Adressen kopiert.' 'Addresses copied.' } })
    $btnOpenDir.Add_Click({ Initialize-PelIntranetFolders; try { Start-Process explorer.exe $script:PelIntranetDir } catch { } })

    # ---- Taktgeber: Speichern, Suche, Server-Ereignisse, Live-Daten ------------------
    $tmr = New-Object System.Windows.Forms.Timer
    $tmr.Interval = 500
    $tmr.Add_Tick({
        try {
            if ($st.Dirty -and ([datetime]::Now - $st.DirtyAt).TotalMilliseconds -ge 700) { Save-IntranetNow }

            $sc = $st.Scanner
            if ($sc) {
                $line = $null
                while ($sc.Found.TryDequeue([ref]$line)) {
                    $x = ConvertFrom-PelIntranetFound $line $sc.Port
                    if ($x) { Add-FoundEntry $x }
                }
                if ($sc.Finished) {
                    $n = @($st.Found.Keys | Where-Object { $_ -ne 'self' }).Count
                    if ($n -eq 0) { $lblScan.Text = Get-PelText 'Kein anderes Intranet gefunden. Ist beim Veranstalter Option 11 offen und veröffentlicht?' 'No other intranet found. Is option 11 open and published at the organizer?' }
                    else { $lblScan.Text = (Get-PelText '{0} Intranet(s) gefunden.' '{0} intranet(s) found.') -f $n }
                    $btnScan.Enabled = $true
                    $st.Scanner = $null
                } else {
                    $lblScan.Text = (Get-PelText 'Suche läuft ... {0} von {1}' 'Searching ... {0} of {1}') -f $sc.Done, $sc.Total
                }
            }

            if (Test-IntranetRunning) {
                $ev = $null
                $changed = $false
                while ([PelIntranetServer]::Events.TryDequeue([ref]$ev)) {
                    $p = ([string]$ev) -split '\|', 3
                    if ($p[0] -eq 'SUBMIT') { $changed = $true }
                    elseif ($p[0] -eq 'DL' -and $p.Count -ge 3) { $lblStatus.Text = (Get-PelText 'Download: {0} an {1}' 'Download: {0} to {1}') -f $p[2], $p[1] }
                    elseif ($p[0] -eq 'SEAT' -and $p.Count -ge 3) {
                        $lblStatus.Text = (Get-PelText 'Sitzplan: Platz gewählt oder geändert ({0}).' 'Seat map: seat chosen or changed ({0}).') -f $p[1]
                    }
                    elseif ($p[0] -in @('ORDER', 'OCANCEL') -and $p.Count -ge 3) {
                        try { Receive-IntranetOrderEvent $p[0] $p[1] $p[2] } catch { Write-PelLog -Level 'INTRANET' -Message "Bestellmeldung: $($_.Exception.Message)" }
                    }
                }
                if ($changed) {
                    Save-PelIntranetEntries $st.Cfg
                    Update-PelIntranetServerContent -Cfg $st.Cfg
                    Update-EntryCount (Get-SelectedBlock)
                    $lblStatus.Text = Get-PelText 'Neuer Eintrag im Intranet.' 'New entry in the intranet.'
                }
                # Live-Blöcke (Spieleabende, Ergebnisse, Downloads) alle 15 Sekunden prüfen -
                # neu ausgeliefert wird nur, wenn sich wirklich etwas geändert hat.
                if (([datetime]::Now - $st.LastLive).TotalSeconds -ge 15) {
                    $st.LastLive = [datetime]::Now
                    Update-PelIntranetServerContent -Cfg $st.Cfg
                }
            }
        } catch { Write-PelLog -Level 'INTRANET' -Message "Timer: $($_.Exception.Message)" }
    })

    $form.Add_Shown({
        Show-EventProps
        Update-BlockList 0
        Update-IntranetState
        $wbView.DocumentText = Get-PelIntranetIntroHtml
        $lblViewUrl.Text = Get-PelText 'Wähle links ein Intranet aus.' 'Choose an intranet on the left.'
        Show-IntranetPage 'view'
        if ($st.Cfg.AutoPublish) { Invoke-IntranetPublish }
        Start-IntranetScan
        $tmr.Start()
    })
    $form.Add_FormClosing({
        $tmr.Stop()
        try { if ($st.Scanner) { $st.Scanner.Cancel = $true } } catch { }
        try { $st.Cfg.Blocks = $st.Blocks.ToArray(); [void](Save-PelIntranetConfig $st.Cfg) } catch { }
        try { Stop-PelIntranetServer $st.Cfg } catch { }
    })

    [void]$form.ShowDialog()
    try { $tmr.Dispose(); $wbView.Dispose(); $wbPreview.Dispose(); $form.Dispose() } catch { }
}

