function Test-PelWelcomeSeen { return [System.IO.File]::Exists($script:PelWelcomeMarker) }

function Set-PelWelcomeSeen {
    try {
        $dir = Split-Path -Parent $script:PelWelcomeMarker
        if (-not [System.IO.Directory]::Exists($dir)) { [void][System.IO.Directory]::CreateDirectory($dir) }
        [System.IO.File]::WriteAllText($script:PelWelcomeMarker, (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), (New-Object System.Text.UTF8Encoding($false)))
    } catch { }
}
#endregion

#region ====== Einladungen aus dem Live-Status (Control Center) ======
# ------------------------------------------------------------------------------
# "Aktionen" in der Liste "Wer spielt gerade was": Nachricht senden (über das Postfach,
# kommt auch an, wenn der andere gerade offline ist), in den Chat oder Sprachchat
# einladen, zum Spielen einladen.
# Einladungen laufen - wie der Live-Status selbst - per UDP über Port 9928, direkt an
# das Control Center des Empfängers, signiert mit $script:PelNetworkSecret (kennzeichnet
# nur "echter Manager", siehe dort). Aufbau:
#   PEINV1|Id|Art|Absendername|Spiel|Spielport|Server|Notiz|ZeitMs|HMAC
#   Art = chat / voice / game. Spielport > 0: der Absender hostet selbst (verbinden mit
#   seiner Absender-IP). Server = "IP:Port", wenn er auf einem Server spielt.
# Der Empfänger bestätigt mit PEINVACK1|Id|ZeitMs|HMAC - so sieht der Absender, ob die
# Einladung angekommen ist. Jede Einladung wird zweimal gesendet (UDP kann Pakete
# verlieren); doppelte werden am Id erkannt und nur einmal angezeigt.
# Schutz: Bannliste, höchstens 6 Einladungen pro Minute und Absender, höchstens 4
# Einladungsfenster gleichzeitig, veraltete Einladungen (> 30 Min.) werden verworfen.
# BUGFIX (01.10.2026): Einladungen kamen oft nicht an, obwohl der Live-Status lief. Der
# Live-Status ist ein Broadcast - den bekommt JEDER Socket auf Port 9928. Die Einladung
# ging nur direkt (Unicast) an die IP; teilen sich auf dem Empfänger-PC mehrere Sockets
# den Port (ReuseAddress, z. B. der Postfach-Dienst in Option 7), stellt Windows ein
# Unicast-Paket nur EINEM davon zu - oft dem falschen. Deshalb geht jede Einladung jetzt
# zusätzlich als Broadcast-Kopie hinaus:
#   PEINVB1|Ziel-IP1,Ziel-IP2|<unveränderte PEINV1-Zeile>
# Nur der Manager, dem eine der Ziel-IPs gehört, zeigt sie an (doppelte werden am Id
# erkannt). Ältere Manager kennen PEINVB1 nicht und ignorieren es - voll kompatibel.
# Die Bestätigung geht ebenso direkt UND als Broadcast zurück.
# Außerdem öffnete sich das Einladungsfenster aus dem Hintergrund oft HINTER dem aktiven
# Fenster (Windows lässt Hintergrundprogramme nicht nach vorne) - es bleibt jetzt oben,
# und im Infobereich erscheint zusätzlich eine Sprechblase.
# Beitreten nutzt immer die Absender-IP des Pakets (im P2P-Netz von der Engine
# abgesichert), nie eine im Paket behauptete Adresse - außer der ausdrücklich genannte
# Server, und auch der wird erst nach Klick des Empfängers verbunden.
# ------------------------------------------------------------------------------
$script:PelCcOpenFile = 'C:\Project-Earth-Lan\cc_open.txt'
$script:PelInviteWindows = New-Object System.Collections.Generic.List[object]

function ConvertTo-PelWireField([string]$Text, [int]$Max) {
    return (Limit-PelText (([string]$Text) -replace '\|', '/') $Max)
}

function New-PelInviteWire {
    param([string]$Kind, [string]$Game = '', [int]$Port = 0, [string]$Server = '', [string]$Note = '')
    $id = ([guid]::NewGuid().ToString('N')).Substring(0, 16)
    $core = 'PEINV1|{0}|{1}|{2}|{3}|{4}|{5}|{6}|{7}' -f $id, $Kind, (ConvertTo-PelWireField (Get-PelDisplayName) 32),
        (ConvertTo-PelWireField $Game 80), [int]$Port, (ConvertTo-PelWireField $Server 40), (ConvertTo-PelWireField $Note 200), (Get-PelNowMs)
    return [pscustomobject]@{ Id = $id; Text = "$core|$(Get-PelHmacBase64 -Text $core)" }
}

# Prüft und zerlegt eine empfangene Einladung. $null = ungültig, gefälscht oder veraltet.
function ConvertFrom-PelInviteWire {
    param([string]$Text, [string]$SrcIp, [long]$NowMs = 0)
    if (-not $NowMs) { $NowMs = Get-PelNowMs }
    if ($Text.Length -gt 1200) { return $null }
    $f = $Text -split '\|'
    if ($f.Count -ne 10 -or $f[0] -ne 'PEINV1') { return $null }
    if (-not (Test-PelHmac -Text (($f[0..8]) -join '|') -Signature $f[9])) { return $null }
    if ($f[1] -notmatch '^[0-9a-f]{16}$') { return $null }
    if (@('chat', 'voice', 'game') -notcontains $f[2]) { return $null }
    $port = 0; $ts = [long]0
    if (-not [int]::TryParse($f[5], [ref]$port) -or $port -lt 0 -or $port -gt 65535) { return $null }
    if (-not [long]::TryParse($f[8], [ref]$ts) -or [Math]::Abs($NowMs - $ts) -gt 1800000) { return $null }
    $server = ''
    $srvIp = $null
    if ($f[6] -match '^(\d{1,3}(\.\d{1,3}){3}):(\d{1,5})$' -and [int]$matches[3] -le 65535 -and [System.Net.IPAddress]::TryParse($matches[1], [ref]$srvIp)) { $server = $f[6] }
    $name = Limit-PelText $f[3] 32
    if (-not $name) { $name = $SrcIp }
    return [pscustomobject]@{
        Id = $f[1]; Kind = $f[2]; FromName = $name; FromIp = $SrcIp
        Game = (Limit-PelText $f[4] 80); Port = $port; Server = $server; Note = (Limit-PelText $f[7] 200)
    }
}

function New-PelInviteAckWire([string]$Id) {
    $core = "PEINVACK1|$Id|$(Get-PelNowMs)"
    return "$core|$(Get-PelHmacBase64 -Text $core)"
}

function ConvertFrom-PelInviteAckWire([string]$Text) {
    $f = $Text -split '\|'
    if ($f.Count -ne 4 -or $f[0] -ne 'PEINVACK1' -or $f[1] -notmatch '^[0-9a-f]{16}$') { return $null }
    if (-not (Test-PelHmac -Text (($f[0..2]) -join '|') -Signature $f[3])) { return $null }
    return $f[1]
}

# Bannliste (Option 7 / Kommunikationszentrale) - dieselbe Datei wie in den C#-Diensten,
# 5 Sekunden zwischengespeichert.
function Test-PelIpBanned([string]$Ip) {
    $now = Get-PelNowMs
    if (-not $script:PelBanCache -or ($now - $script:PelBanCacheMs) -gt 5000) {
        $set = @{}
        try {
            $bf = 'C:\Project-Earth-Lan\ip_bans.json'
            if ([System.IO.File]::Exists($bf)) {
                $txt = Read-PelTextFile $bf
                foreach ($m in [regex]::Matches($txt, '"Ip"\s*:\s*"([^"]*)"[^}]*?"Deleted"\s*:\s*(true|false)')) {
                    if ($m.Groups[2].Value -eq 'false') { $set[$m.Groups[1].Value] = $true }
                }
            }
        } catch { }
        $script:PelBanCache = $set
        $script:PelBanCacheMs = $now
    }
    return $script:PelBanCache.ContainsKey($Ip)
}

# Kommunikationszentrale (Option 6) im Chat- oder Sprachchat-Bereich öffnen. Läuft sie
# schon, holt sie sich den Wunsch aus der Übergabedatei (siehe Timer in Invoke-CommCenter)
# und kommt nach vorne - ein zweiter Start würde nur "bereits geöffnet" melden.
function Request-PelCommCenterPanel([string]$Panel) {
    try { Write-PelTextFileAtomic $script:PelCcOpenFile ("{0}|{1}" -f $Panel, (Get-PelNowMs)) } catch { }
    $running = $false
    $mx = $null
    try { $running = [System.Threading.Mutex]::TryOpenExisting('Global\ProjectEarthLan_Option_6', [ref]$mx) } catch { $running = $false }
    if ($mx) { try { $mx.Dispose() } catch { } }
    if (-not $running) { Start-OptionWindow '6' { Invoke-CommCenter } }
}

# Liest einen Bereichswunsch für die Kommunikationszentrale (einmalig, höchstens 2 Min. alt).
function Receive-PelCommCenterRequest {
    if (-not [System.IO.File]::Exists($script:PelCcOpenFile)) { return '' }
    $req = ''
    try { $req = (Read-PelTextFile $script:PelCcOpenFile).Trim() } catch { }
    try { [System.IO.File]::Delete($script:PelCcOpenFile) } catch { }
    $f = $req -split '\|'
    $ts = [long]0
    if ($f.Count -ne 2 -or -not [long]::TryParse($f[1], [ref]$ts)) { return '' }
    if (((Get-PelNowMs) - $ts) -gt 120000) { return '' }
    if (@('chat', 'voice') -contains $f[0]) { return $f[0] }
    return ''
}

# Nicht-modales Einladungsfenster (unten rechts, wie die Postfach-Meldung). Mehrere
# Einladungen stapeln sich nach oben, höchstens 4 gleichzeitig.
function Show-PelInviteNotification {
    param($Invite)
    foreach ($w in @($script:PelInviteWindows)) { if (-not $w -or $w.IsDisposed -or -not $w.Visible) { [void]$script:PelInviteWindows.Remove($w) } }
    if ($script:PelInviteWindows.Count -ge 4) {
        Write-PelLog "Einladung von $($Invite.FromName) ($($Invite.FromIp)) nicht angezeigt - schon 4 Einladungsfenster offen."
        return
    }
    $who = "$($Invite.FromName) ($($Invite.FromIp))"
    switch ($Invite.Kind) {
        'chat' { $head = [PelI18n]::Tr("{0} lädt dich in den Chat ein.") -f $who; $title = 'Einladung: Chat' }
        'voice' { $head = [PelI18n]::Tr("{0} lädt dich in den Sprachchat ein.") -f $who; $title = 'Einladung: Sprachchat' }
        default {
            $g = if ($Invite.Game) { $Invite.Game } else { [PelI18n]::Tr('ein Spiel') }
            $head = [PelI18n]::Tr("{0} lädt dich zum Spielen ein: {1}") -f $who, $g
            $title = 'Einladung: Spielen'
        }
    }
    $body = $head
    if ($Invite.Kind -eq 'game') {
        if ($Invite.Server) { $body += "`r`n" + ([PelI18n]::Tr("Server: {0}") -f $Invite.Server) }
        elseif ($Invite.Port -gt 0) { $body += "`r`n" + ([PelI18n]::Tr("{0} hostet selbst: {1}:{2}") -f $Invite.FromName, $Invite.FromIp, $Invite.Port) }
        else { $body += "`r`n" + [PelI18n]::Tr("Die Adresse wird beim Beitreten in die Zwischenablage gelegt.") }
    }
    if ($Invite.Note) { $body += "`r`n`r`n" + ([PelI18n]::Tr("Nachricht: {0}") -f $Invite.Note) }

    $f = (New-PelForm)
    $f.Text = "Project Earth LAN - $([PelI18n]::Tr($title))"
    $f.Size = New-Object System.Drawing.Size(460, 240)
    $f.StartPosition = 'Manual'
    $f.FormBorderStyle = 'FixedDialog'
    $f.MaximizeBox = $false
    $f.MinimizeBox = $false
    $f.ShowInTaskbar = $true
    $f.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $f.ForeColor = [System.Drawing.Color]::White
    $f.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Regular)
    $f.Tag = $Invite
    # BUGFIX: Ohne TopMost öffnete sich das Fenster hinter dem gerade aktiven Programm
    # (Browser, Spiel im Fenstermodus) und wurde nicht bemerkt.
    $f.TopMost = $true
    try {
        $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
        $off = $script:PelInviteWindows.Count * ($f.Height + 8)
        $f.Location = New-Object System.Drawing.Point(($wa.Right - $f.Width - 12), [Math]::Max($wa.Top, ($wa.Bottom - $f.Height - 12 - $off)))
    } catch { $f.StartPosition = 'CenterScreen' }

    $tb = New-Object System.Windows.Forms.TextBox
    $tb.Multiline = $true
    $tb.ReadOnly = $true
    $tb.ScrollBars = 'Vertical'
    $tb.Location = New-Object System.Drawing.Point(12, 12)
    $tb.Size = New-Object System.Drawing.Size(420, 120)
    $tb.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
    $tb.ForeColor = [System.Drawing.Color]::White
    $tb.BorderStyle = 'FixedSingle'
    $tb.Font = New-Object System.Drawing.Font('Segoe UI', 10.5, [System.Drawing.FontStyle]::Regular)
    $tb.Text = $body
    $f.Controls.Add($tb)

    $btnGo = New-Object System.Windows.Forms.Button
    $btnGo.Location = New-Object System.Drawing.Point(12, 146)
    $btnGo.Size = New-Object System.Drawing.Size(270, 40)
    $btnGo.FlatStyle = 'Flat'
    $btnGo.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
    $btnGo.ForeColor = [System.Drawing.Color]::White
    $btnGo.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Bold)
    if ($Invite.Kind -eq 'game') {
        $btnGo.Text = 'Beitreten'
        $btnGo.BackColor = [System.Drawing.Color]::FromArgb(0, 135, 70)
    } else {
        $btnGo.Text = if ($Invite.Kind -eq 'voice') { 'Sprachchat öffnen' } else { 'Chat öffnen' }
        $btnGo.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    }
    $btnGo.Add_Click({
        $af = $this.FindForm()
        $inv = $af.Tag
        $af.Close()
        if ($inv.Kind -eq 'game') {
            try {
                if ($inv.Server -and $inv.Server -match '^(\d{1,3}(\.\d{1,3}){3}):(\d{1,5})$') {
                    [void](Invoke-PelJoinGame -Ip $matches[1] -JoinPort ([int]$matches[3]) -GameName $inv.Game)
                } elseif ($inv.Port -gt 0) {
                    [void](Invoke-PelJoinGame -Ip $inv.FromIp -JoinPort $inv.Port -GameName $inv.Game)
                } else {
                    [void](Invoke-PelJoinGame -Ip $inv.FromIp -GameName $inv.Game -LaunchOnly)
                }
            } catch { Write-PelLog "Einladung: Beitreten fehlgeschlagen: $($_.Exception.Message)" 'WARN' }
        } else {
            Request-PelCommCenterPanel $inv.Kind
        }
    })
    $f.Controls.Add($btnGo)

    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Text = 'Schließen'
    $btnClose.Location = New-Object System.Drawing.Point(292, 146)
    $btnClose.Size = New-Object System.Drawing.Size(140, 40)
    $btnClose.FlatStyle = 'Flat'
    $btnClose.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
    $btnClose.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
    $btnClose.ForeColor = [System.Drawing.Color]::White
    $btnClose.Add_Click({ $this.FindForm().Close() })
    $f.Controls.Add($btnClose)
    $f.Add_FormClosed({ [void]$script:PelInviteWindows.Remove($this) })

    $script:PelInviteWindows.Add($f)
    try { [System.Media.SystemSounds]::Asterisk.Play() } catch { }
    $f.Show()
    Write-PelLog "Einladung ($($Invite.Kind)) von $($Invite.FromName) ($($Invite.FromIp)) erhalten."
}

# Dialog "Zum Spielen einladen": Spiel (vorbelegt mit dem, was gerade läuft, sonst aus der
# Spielebibliothek) und eine kurze Notiz. Rückgabe: @{ Game; Note } oder $null.
function Show-PelGameInviteDialog {
    param([string]$ToName, $ParentForm = $null)
    $d = (New-PelForm)
    $d.Text = 'Zum Spielen einladen'
    $d.Size = New-Object System.Drawing.Size(480, 270)
    $d.StartPosition = 'CenterParent'
    $d.FormBorderStyle = 'FixedDialog'
    $d.MaximizeBox = $false
    $d.MinimizeBox = $false
    $d.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    $d.ForeColor = [System.Drawing.Color]::White
    $d.Font = New-Object System.Drawing.Font('Segoe UI', 9.5, [System.Drawing.FontStyle]::Regular)
    $mkL = {
        param([string]$t, [int]$y)
        $l = New-Object System.Windows.Forms.Label
        $l.Text = $t
        $l.Location = New-Object System.Drawing.Point(16, $y)
        $l.Size = New-Object System.Drawing.Size(430, 20)
        $d.Controls.Add($l)
    }
    & $mkL ([PelI18n]::Tr("Einladung an {0} - Spiel:") -f $ToName) 14
    $cb = New-Object System.Windows.Forms.ComboBox
    $cb.DropDownStyle = 'DropDown'
    $cb.MaxLength = 80
    $cb.Location = New-Object System.Drawing.Point(16, 38)
    $cb.Size = New-Object System.Drawing.Size(430, 26)
    $cb.BackColor = [System.Drawing.Color]::FromArgb(15, 15, 15)
    $cb.ForeColor = [System.Drawing.Color]::White
    $cb.AutoCompleteMode = 'SuggestAppend'
    $cb.AutoCompleteSource = 'ListItems'
    $d.Controls.Add($cb)
    $names = New-Object System.Collections.Generic.List[string]
    try { foreach ($g in @((Get-PelGameLibrary).Games | Where-Object { -not $_.Hidden } | Sort-Object { [string]$_.Name })) { $names.Add([string]$g.Name) } } catch { }
    foreach ($n in @($names | Select-Object -Unique)) { [void]$cb.Items.Add($n) }
    if ($script:PelMyGame -and $script:PelMyGame.Title) { $cb.Text = ([string]$script:PelMyGame.Title) -replace '\s*\(Server\)$', '' }
    elseif ($cb.Items.Count -gt 0) { $cb.SelectedIndex = 0 }
    & $mkL "Kurze Nachricht (optional):" 74
    $tb = New-Object System.Windows.Forms.TextBox
    $tb.MaxLength = 200
    $tb.Location = New-Object System.Drawing.Point(16, 98)
