# ------------------------------------------------------------------------------
# ZENTRALES HAUPTMENÜ DASHBOARD
# ------------------------------------------------------------------------------
function Show-MainDashboard {
    $mainForm = (New-PelForm)
    $mainForm.Text = "Project Earth LAN - Control Center"
    $mainForm.Size = New-Object System.Drawing.Size(520, 1264)
    $mainForm.StartPosition = "CenterScreen"
    $mainForm.FormBorderStyle = "Sizable"
    $mainForm.MaximizeBox = $true
    $mainForm.BackColor = [System.Drawing.Color]::FromArgb(25, 25, 25)
    $mainForm.ForeColor = [System.Drawing.Color]::White
    # Auf kleinen Bildschirmen (z. B. Laptop mit 1366x768) passt das Fenster nicht ganz
    # auf den Schirm - dann auf die Arbeitsfläche begrenzen. Das Scrollen selbst
    # übernimmt weiter unten ein eigenes scrollbares Panel (mit fest sichtbaren
    # Hoch-/Runter-Buttons), nicht mehr das Formular direkt.
    try {
        $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
        if ($mainForm.Height -gt $wa.Height) { $mainForm.Height = $wa.Height }
    } catch { }

    $fontHeader = New-Object System.Drawing.Font("Segoe UI", 12, [System.Drawing.FontStyle]::Bold)
    $fontBtn = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)
    # HINWEIS: Optionen 1-11 (11 = Intranet; Datei-Server in Option 1, Autostart als kleiner Button oben). Netzwerk = P2P-Box (ersetzt ZeroTier).

    $lblTitle = New-Object System.Windows.Forms.Label
    $lblTitle.Text = "Project Earth LAN - Manager Panel"
    $lblTitle.Location = New-Object System.Drawing.Point(20, 15)
    $lblTitle.Size = New-Object System.Drawing.Size(460, 30)
    $lblTitle.Font = $fontHeader
    $lblTitle.ForeColor = [System.Drawing.Color]::White
    $lblTitle.TextAlign = "MiddleCenter"
    $mainForm.Controls.Add($lblTitle)

    # Menü nach der Bereinigung (alte Optionen 1-3 Installation/Login/Logout, 12 ZTNET und
    # 14 Deinstallation entfallen - das Netzwerk läuft jetzt über die P2P-Box unten).
    $buttons = @(
        @{ Text = "1. Tools, Mods & Games Downloader & Datei-Server"; Action = { Show-DashboardOption1Menu }; Key = 'files' },
        @{ Text = "2. Windows Remotedesktop aktivieren / deaktivieren"; Action = { Start-OptionWindow '2' { Invoke-PelRemoteDesktop } } },
        @{ Text = "3. Spielebibliothek (Spiele finden, verwalten, starten)"; Action = { Start-OptionWindow '3' { Invoke-PelGameLibrary } } },
        @{ Text = "4. Turniere & Matchmaking"; Action = { Start-OptionWindow '4' { Invoke-PelTourneyCenter } } },
        @{ Text = "5. Server-Manager & Server Browser (Port 9872)"; Action = { Start-OptionWindow '5' { Invoke-ServerManagerBrowser } } },
        @{ Text = "6. Kommunikationszentrale (Chat, Dateien, Voice)"; Action = { Start-OptionWindow '6' { Invoke-CommCenter } } },
        @{ Text = "7. Freundesliste, Bannliste & Postfach"; Action = { Start-OptionWindow '7' { Invoke-FriendsBansMailbox } } },
        @{ Text = "8. Kodi Streaming (Fernbedienung & Live-Wiedergabe)"; Action = { Start-OptionWindow '8' { Invoke-KodiSteuerung } } },
        @{ Text = "9. Eigene Lobby hosten (für Freunde, ein Klick)"; Action = { Show-PelHostDialog }; Key = 'host' },
        @{ Text = "10. Anleitung & FAQ (Datei auf dem Desktop)"; Action = { [void](Export-PelHelpFile -Owner $mainForm) } },
        @{ Text = "11. Intranet für LAN-Partys (ansehen, erstellen, einbetten)"; Action = { Start-OptionWindow '11' { Invoke-PelIntranet } } }
    )

    $yPos = 55
    $btnAutostart = $null
    $btnHost = $null
    $btnFiles = $null
    foreach ($btnInfo in $buttons) {
        $btn = New-Object System.Windows.Forms.Button
        $btn.Text = $btnInfo.Text
        $btn.Location = New-Object System.Drawing.Point(30, $yPos)
        $btn.Size = New-Object System.Drawing.Size(445, 34)
        $btn.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
        $btn.ForeColor = [System.Drawing.Color]::White
        $btn.FlatStyle = "Flat"
        $btn.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $btn.Font = $fontBtn
        $btn.UseMnemonic = $false   # sonst verschluckt WinForms das "&" ("Tools, Mods  Games")
        if ($btnInfo.Action) { $btn.Add_Click($btnInfo.Action) }
                if ($btnInfo.Key -eq 'host') { $btnHost = $btn }
        if ($btnInfo.Key -eq 'files') { $btnFiles = $btn }
        $mainForm.Controls.Add($btn)
        $yPos += 37
    }

    # ---- Option 1: Auswahl Downloader / eigener Datei-Server ----------------------------
    # Der Datei-Server läuft im Control Center (bleibt aktiv, solange es offen ist), der
    # Downloader als eigenes Fenster - deshalb ein kleines Menü statt eines Fensters.
    $opt1Menu = New-PelContextMenu
    $opt1Dl = New-Object System.Windows.Forms.ToolStripMenuItem('Tools, Mods & Games Downloader öffnen')
    $opt1Dl.Add_Click({ Start-OptionWindow '1' { Invoke-ToolsModsGames } })
    $opt1Fs = New-Object System.Windows.Forms.ToolStripMenuItem('Eigenen Datei-Server hosten (Downloads für Freunde)')
    $opt1Fs.Add_Click({ Show-PelFileServerDialog -Owner $mainForm })
    [void]$opt1Menu.Items.Add($opt1Dl)
    [void]$opt1Menu.Items.Add($opt1Fs)
    function Show-DashboardOption1Menu {
        $opt1Fs.Text = if (Test-PelFileServerRunning) { Get-PelText "Eigener Datei-Server: AKTIV ($([PelFileServer]::ActiveDownloads) Downloads) - öffnen" "Own file server: ACTIVE ($([PelFileServer]::ActiveDownloads) downloads) - open" } else { Get-PelText 'Eigenen Datei-Server hosten (Downloads für Freunde)' 'Host your own file server (downloads for friends)' }
        $opt1Menu.Show($btnFiles, 0, $btnFiles.Height)
    }

    # ---- Autostart: kleiner Button oben links neben "Sprache" (geplante Aufgabe, siehe
    # Enable-PelAutostart). Er wird hier angelegt und weiter unten neben btnLang gesetzt.
    $btnAutostart = New-Object System.Windows.Forms.Button
    $btnAutostart.Size = New-Object System.Drawing.Size(150, 26)
    $btnAutostart.FlatStyle = 'Flat'
    $btnAutostart.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
    $btnAutostart.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
    $btnAutostart.TabStop = $false
    $btnAutostart.UseMnemonic = $false
    $ttAutostart = New-Object System.Windows.Forms.ToolTip
    function Update-DashboardAutostartButton {
        $info = Get-PelAutostartInfo
        if ($info.Enabled -and $info.PathOk) {
            $btnAutostart.Text = Get-PelText 'Autostart: AN' 'Autostart: ON'
            $btnAutostart.ForeColor = [System.Drawing.Color]::LightGreen
            $ttAutostart.SetToolTip($btnAutostart, (Get-PelText 'Der Manager startet automatisch mit Windows. Klick = aus dem Autostart entfernen.' 'The manager starts automatically with Windows. Click = remove from autostart.'))
        } elseif ($info.Enabled) {
            $btnAutostart.Text = Get-PelText 'Autostart: neu einrichten' 'Autostart: set up again'
            $btnAutostart.ForeColor = [System.Drawing.Color]::Orange
            $ttAutostart.SetToolTip($btnAutostart, (Get-PelText 'Der Autostart zeigt auf einen alten Speicherort. Klick = neu einrichten.' 'Autostart points to an old location. Click = set up again.'))
        } else {
            $btnAutostart.Text = Get-PelText 'Autostart: AUS' 'Autostart: OFF'
            $btnAutostart.ForeColor = [System.Drawing.Color]::White
            $ttAutostart.SetToolTip($btnAutostart, (Get-PelText 'Klick = Manager beim Windows-Start automatisch starten.' 'Click = start the manager automatically with Windows.'))
        }
    }
    $btnAutostart.Add_Click({
        $info = Get-PelAutostartInfo
        $ico = [System.Windows.Forms.MessageBoxIcon]::Question
        $yn = [System.Windows.Forms.MessageBoxButtons]::YesNo
        if ($info.Enabled -and $info.PathOk) {
            $ans = [PelI18n]::Show($mainForm, "Der Project Earth LAN Manager startet zurzeit automatisch mit Windows.`n`nAus dem Autostart entfernen?", 'Autostart', $yn, $ico)
            if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
            $err = Disable-PelAutostart
            if ($err) { Show-PelMsg "Autostart konnte nicht entfernt werden:`n$err" 'Autostart' ([System.Windows.Forms.MessageBoxIcon]::Error) $mainForm }
            else { Show-PelMsg "Autostart entfernt. Der Manager startet nicht mehr automatisch mit Windows." 'Autostart' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm }
        } else {
            $q = "Project Earth LAN Manager beim Windows-Start automatisch starten?`n`n" +
                 "- startet ca. 30 Sekunden nach der Anmeldung, unsichtbar im Infobereich (Symbol neben der Uhr)`n" +
                 "- mit Administratorrechten, aber ohne UAC-Abfrage (als geplante Aufgabe)`n" +
                 "- Postfach, Live-Status und Spieleabend-Ankündigungen sind dann immer aktiv`n`n" +
                 "Programm: $($script:SelfPath)`n(Verschiebst du die Datei später, hier einfach neu einrichten.)"
            if ($info.Enabled) { $q = "Der Autostart zeigt noch auf einen anderen Speicherort:`n$($info.Target)`n`n" + $q }
            $ans = [PelI18n]::Show($mainForm, $q, 'Autostart', $yn, $ico)
            if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
            $err = Enable-PelAutostart
            if ($err) { Show-PelMsg "Autostart konnte nicht eingerichtet werden:`n$err" 'Autostart' ([System.Windows.Forms.MessageBoxIcon]::Error) $mainForm }
            else { Show-PelMsg "Autostart eingerichtet. Ab der nächsten Anmeldung startet der Manager automatisch im Infobereich (Symbol neben der Uhr).`n`nEntfernen jederzeit wieder über Autostart-Button." 'Autostart' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm }
        }
        Update-DashboardAutostartButton
    })
    Update-DashboardAutostartButton

    # ---- P2P-Netzwerk (Lobby) - ersetzt ZeroTier ----------------------------------------
    # Die Engine lebt in diesem Prozess (Control Center). Beitreten = virtueller Adapter +
    # Hole Punching im Hintergrund; sobald die virtuelle IP steht, wird der P2P-Adapter
    # zentral gewählt und alle Options-Fenster wechseln automatisch darauf.
    $p2pSet = Get-PelP2pSettings
    $p2pUi = [pscustomobject]@{ PeerSig = ''; CfgTries = 0; Lobby = ''; KeepMsg = $false; OwnLobby = $false }

    $grpP2p = New-Object System.Windows.Forms.GroupBox
    $grpP2p.Text = "P2P-Netzwerk (Lobby)"
    $grpP2p.Location = New-Object System.Drawing.Point(30, ($yPos + 8))
    $grpP2p.Size = New-Object System.Drawing.Size(445, 386)
    $grpP2p.ForeColor = [System.Drawing.Color]::White
    $grpP2p.Font = $fontBtn
    $mainForm.Controls.Add($grpP2p)

    $p2pFont = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
    $newP2pLabel = {
        param([string]$text, [int]$x, [int]$y, [int]$w)
        $l = New-Object System.Windows.Forms.Label
        $l.Text = $text
        $l.Location = New-Object System.Drawing.Point($x, $y)
        $l.Size = New-Object System.Drawing.Size($w, 20)
        $l.ForeColor = [System.Drawing.Color]::LightGray
        $l.Font = $p2pFont
        $grpP2p.Controls.Add($l)
        return $l
    }
    $newP2pText = {
        param([int]$x, [int]$y, [int]$w, [string]$value)
        $t = New-Object System.Windows.Forms.TextBox
        $t.Location = New-Object System.Drawing.Point($x, $y)
        $t.Size = New-Object System.Drawing.Size($w, 22)
        $t.BackColor = [System.Drawing.Color]::FromArgb(35, 35, 35)
        $t.ForeColor = [System.Drawing.Color]::White
        $t.BorderStyle = 'FixedSingle'
        $t.Font = $p2pFont
        $t.Text = $value
        $grpP2p.Controls.Add($t)
        return $t
    }
    [void](& $newP2pLabel "Vermittlungsserver:" 15 27 135)
    $txtP2pServer = & $newP2pText 155 25 275 ([string]$p2pSet.Server)
    [void](& $newP2pLabel "Lobby-Name:" 15 55 135)
    $txtP2pLobby = & $newP2pText 155 53 275 ([string]$p2pSet.Lobby)
    [void](& $newP2pLabel "Lobby-Passwort:" 15 83 135)
    $txtP2pPass = & $newP2pText 155 81 275 (Unprotect-PelP2pPassword ([string]$p2pSet.PasswordEnc))
    $txtP2pPass.UseSystemPasswordChar = $true

    $chkP2pAuto = New-Object System.Windows.Forms.CheckBox
    $chkP2pAuto.Text = "Beim Start automatisch beitreten (Passwort verschlüsselt merken)"
    $chkP2pAuto.Location = New-Object System.Drawing.Point(15, 108)
    $chkP2pAuto.Size = New-Object System.Drawing.Size(415, 22)
    $chkP2pAuto.ForeColor = [System.Drawing.Color]::LightGray
    $chkP2pAuto.Font = $p2pFont
    $chkP2pAuto.Checked = [bool]$p2pSet.AutoConnect
    $grpP2p.Controls.Add($chkP2pAuto)

    $newP2pButton = {
        param([string]$text, [int]$x, [bool]$accent, [int]$w = 200, [int]$y = 134)
        $b = New-Object System.Windows.Forms.Button
        $b.Text = $text
        $b.Location = New-Object System.Drawing.Point($x, $y)
        $b.Size = New-Object System.Drawing.Size($w, 30)
        if ($accent) { $b.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215) } else { $b.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45) }
        $b.ForeColor = [System.Drawing.Color]::White
        $b.FlatStyle = "Flat"
        $b.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $b.Font = $p2pFont
        $grpP2p.Controls.Add($b)
        return $b
    }
    $btnP2pInvite = & $newP2pButton "Einladung einfügen" 15 $true 203 134
    $btnP2pMakeInvite = & $newP2pButton "Einladung erstellen" 227 $false 203 134
    $btnP2pJoin = & $newP2pButton "Beitreten" 15 $false 203 168
    $btnP2pLeave = & $newP2pButton "Trennen" 227 $false 203 168
    $btnP2pNoise = & $newP2pButton "Broadcast-Firewall ..." 15 $false 415 202

    $lblP2pState = & $newP2pLabel "Status: getrennt" 15 238 415
    $lblP2pIp = & $newP2pLabel "Virtuelle IP: -" 15 260 415

    $lvP2p = New-Object System.Windows.Forms.ListView
    $lvP2p.Location = New-Object System.Drawing.Point(15, 284)
    $lvP2p.Size = New-Object System.Drawing.Size(415, 92)
    $lvP2p.View = 'Details'
    $lvP2p.FullRowSelect = $true
    $lvP2p.MultiSelect = $false
    $lvP2p.HeaderStyle = 'Nonclickable'
    $lvP2p.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20)
    $lvP2p.ForeColor = [System.Drawing.Color]::White
    $lvP2p.Font = $p2pFont
    [void]$lvP2p.Columns.Add("Mitspieler", 120)
    [void]$lvP2p.Columns.Add("Virtuelle IP", 95)
    [void]$lvP2p.Columns.Add("Verbindung", 125)
    [void]$lvP2p.Columns.Add("Ping", 55)
    $grpP2p.Controls.Add($lvP2p)
    $p2pTip = New-Object System.Windows.Forms.ToolTip
    [PelI18n]::Tip($p2pTip, $txtP2pServer, "Adresse des Vermittlungsservers (PEL-Rendezvous.ps1), z. B. lan.example.de:47810")
    [PelI18n]::Tip($p2pTip, $txtP2pLobby, "Alle mit demselben Lobby-Namen UND Passwort landen im selben virtuellen LAN.")
    [PelI18n]::Tip($p2pTip, $btnP2pMakeInvite, "Erstellt aus Vermittlungsserver, Lobby-Name und Passwort einen Einladungscode und kopiert ihn - Freunde klicken dann nur 'Einladung einfügen'.")
    [PelI18n]::Tip($p2pTip, $btnP2pInvite, "Einladungscode vom Gastgeber (Option 9) kopieren, dann hier klicken - Server, Lobby und Passwort werden automatisch eingetragen.")
    [PelI18n]::Tip($p2pTip, $lvP2p, "Direkt = Hole Punching erfolgreich (kein Umweg).  Relay = über den Vermittlungsserver (verschlüsselt, etwas mehr Ping).")

    $yPos = $grpP2p.Bottom

    function Update-DashboardP2pButtons {
        $run = Test-PelP2pRunning
        $btnP2pJoin.Enabled = -not $run
        $btnP2pInvite.Enabled = -not $run
        $btnP2pLeave.Enabled = $run
        $txtP2pServer.Enabled = -not $run
        $txtP2pLobby.Enabled = -not $run
        $txtP2pPass.Enabled = -not $run
    }

    function Invoke-DashboardP2pJoin {
        param([switch]$Silent, [switch]$NoSave)
        if (Test-PelP2pRunning) { return }
        $srv = $txtP2pServer.Text.Trim()
        $lob = $txtP2pLobby.Text.Trim()
        $pw = $txtP2pPass.Text
        $problem = $null
        if (-not $srv) { $problem = "Bitte die Adresse des Vermittlungsservers eintragen (z. B. lan.example.de:47810)." }
        elseif ($lob.Length -lt 3) { $problem = "Der Lobby-Name muss mindestens 3 Zeichen haben." }
        elseif ($pw.Length -lt 6) { $problem = "Das Lobby-Passwort muss mindestens 6 Zeichen haben." }
        if ($problem) {
            if ($Silent) { $lblP2pState.Text = "Status: $problem"; $lblP2pState.ForeColor = [System.Drawing.Color]::Orange; $p2pUi.KeepMsg = $true }
            else { Show-PelMsg $problem 'P2P-Netzwerk' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm }
            return
        }
        if (-not $NoSave) {
            # (Beim Hosten wird die eigene Lobby über 127.0.0.1 betreten - das nicht als
            # "normale" Lobby speichern, sonst zeigt die Box nach dem Hosten ins Leere.)
            $set = Get-PelP2pSettings
            $set.Server = $srv
            $set.Lobby = $lob
            $set.AutoConnect = [bool]$chkP2pAuto.Checked
            $set.PasswordEnc = if ($chkP2pAuto.Checked) { Protect-PelP2pPassword $pw } else { '' }
            Save-PelP2pSettings $set
            $p2pUi.OwnLobby = $false
        }

        $p2pUi.KeepMsg = $false
        $lblP2pState.Text = "Status: starte (Wintun, Schlüssel, Adapter) ..."
        $lblP2pState.ForeColor = [System.Drawing.Color]::Orange
        $mainForm.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        [System.Windows.Forms.Application]::DoEvents()
        try {
            Start-PelP2p -Server $srv -Lobby $lob -Password $pw
            $p2pUi.CfgTries = 0
            $p2pUi.PeerSig = ''
            $p2pUi.Lobby = $lob
        } catch {
            $err = Get-PelInnerMessage $_
            Write-PelLog -Level 'P2P' -Message "Start fehlgeschlagen: $err"
            $lblP2pState.Text = "Status: Fehler - $err"
            $lblP2pState.ForeColor = [System.Drawing.Color]::OrangeRed
            $p2pUi.KeepMsg = $true
            if (-not $Silent) { Show-PelMsg "Das P2P-Netzwerk konnte nicht gestartet werden:`n`n$err" 'P2P-Netzwerk' ([System.Windows.Forms.MessageBoxIcon]::Error) $mainForm }
        } finally {
            $mainForm.Cursor = [System.Windows.Forms.Cursors]::Default
        }
        Update-DashboardP2pButtons
        Update-DashboardP2p
    }

    function Update-DashboardP2p {
        try { Update-DashboardNoiseButton } catch { }
        $eng = $script:PelP2pEngine
        if ($eng) {
            $line = $null
            while ($eng.Log.TryDequeue([ref]$line)) { Write-PelLog -Level 'P2P' -Message $line }
        }
        if (-not (Test-PelP2pRunning)) {
            if (-not $p2pUi.KeepMsg) {
                $lblP2pState.Text = "Status: getrennt"
                $lblP2pState.ForeColor = [System.Drawing.Color]::LightGray
            }
            $lblP2pIp.Text = "Virtuelle IP: -"
            $grpP2p.Text = "P2P-Netzwerk (Lobby)"
            if ($lvP2p.Items.Count -gt 0) { $lvP2p.Items.Clear() }
            $p2pUi.PeerSig = ''
            return
        }

        # Virtuelle IP auf den Adapter setzen, sobald der Server sie vergeben hat (Runspace)
        if ($eng.IpChanged -and -not $script:PelP2pCfgJob -and $p2pUi.CfgTries -lt 3) {
            $eng.IpChanged = $false
            $p2pUi.CfgTries++
            Start-PelP2pAdapterConfig -Ip $eng.AssignedIp -Prefix $eng.PrefixLength
        }
        $cfg = Receive-PelP2pAdapterConfig
        if ($cfg) {
            if ($cfg.Ok) {
                Write-PelLog -Level 'P2P' -Message "Adapter $($script:PelP2pAdapterName) eingerichtet: $($cfg.Ip)"
                $pa = @(Get-PelAdapterList) | Where-Object { $_.IsP2P } | Select-Object -First 1
                if ($pa) {
                    Save-PelSelectedAdapter $pa
                    Update-DashboardAdapterLabel
                    Update-DashboardStatus
                }
            } else {
                Write-PelLog -Level 'P2P' -Message "Adapter-Einrichtung fehlgeschlagen: $($cfg.Message)"
                if ($p2pUi.CfgTries -lt 3) { $eng.IpChanged = $true }
                else { $lblP2pIp.Text = "Adapter-Einrichtung fehlgeschlagen: $($cfg.Message)"; $lblP2pIp.ForeColor = [System.Drawing.Color]::OrangeRed }
            }
        }

        $st = [string]$eng.State
        $lblP2pState.Text = "Status: $st"
        if ($st -eq 'Verbunden') { $lblP2pState.ForeColor = [System.Drawing.Color]::LightGreen }
        elseif ($st -like 'Fehler*') { $lblP2pState.ForeColor = [System.Drawing.Color]::OrangeRed }
        else { $lblP2pState.ForeColor = [System.Drawing.Color]::Orange }
        if ($eng.AssignedIp) {
            $pending = if ($script:PelP2pCfgJob) { '  (wird eingerichtet ...)' } else { '' }
            $lblP2pIp.Text = "Virtuelle IP: $($eng.AssignedIp)/$($eng.PrefixLength)$pending   Öffentlich: $($eng.PublicEndpoint)"
            if ($lblP2pIp.ForeColor -ne [System.Drawing.Color]::OrangeRed) { $lblP2pIp.ForeColor = [System.Drawing.Color]::LightGray }
        } else {
            $lblP2pIp.Text = "Virtuelle IP: wird vom Server vergeben ..."
        }

        $peers = @($eng.GetPeers())
        $direct = @($peers | Where-Object { $_.Mode -eq 'Direkt' }).Count
        $grpP2p.Text = "P2P-Netzwerk - Lobby '$($p2pUi.Lobby)'  ($($peers.Count) Mitspieler, $direct direkt)"
        # Liste nur neu aufbauen, wenn sich die Mitspieler selbst ändern (Beitritt/Verlassen);
        # Verbindungsart und Ping werden in den vorhandenen Zeilen aktualisiert - wichtig bei
        # großen Lobbys (bis 512 Mitspieler), sonst flackert und hakt das Fenster jede Sekunde.
        $sig = (($peers | ForEach-Object { "$($_.Name)|$($_.Ip)" }) -join ';')
        $rebuild = ($sig -ne $p2pUi.PeerSig) -or ($lvP2p.Items.Count -ne $peers.Count)
        $lvP2p.BeginUpdate()
        try {
            if ($rebuild) {
                $p2pUi.PeerSig = $sig
                $lvP2p.Items.Clear()
                $newItems = New-Object System.Collections.Generic.List[System.Windows.Forms.ListViewItem]
                foreach ($p in $peers) {
                    $it = New-Object System.Windows.Forms.ListViewItem([string]$p.Name)
                    [void][PelI18n]::AddSub($it, [string]$p.Ip)
                    [void][PelI18n]::AddSub($it, '')
                    [void][PelI18n]::AddSub($it, '')
                    $newItems.Add($it)
                }
                $lvP2p.Items.AddRange($newItems.ToArray())
            }
            for ($i = 0; $i -lt $peers.Count; $i++) {
                $p = $peers[$i]; $it = $lvP2p.Items[$i]
                $mode = [PelI18n]::Tr([string]$p.Mode)
                $ping = if ($p.RttMs -ge 0) { "$([int]($p.RttMs / 5) * 5) ms" } else { '-' }
                if ($it.SubItems[2].Text -ne $mode) {
                    $it.SubItems[2].Text = $mode
                    if ($p.Mode -eq 'Direkt') { $it.ForeColor = [System.Drawing.Color]::LightGreen }
                    elseif ($p.Mode -eq 'Relay') { $it.ForeColor = [System.Drawing.Color]::Gold }
                    else { $it.ForeColor = [System.Drawing.Color]::Orange }
                }
                if ($it.SubItems[3].Text -ne $ping) { $it.SubItems[3].Text = $ping }
                $it.ToolTipText = "Weg: $($p.Endpoint)   empfangen: $([math]::Round($p.RxBytes / 1KB)) KB   gesendet: $([math]::Round($p.TxBytes / 1KB)) KB"
            }
        } finally { $lvP2p.EndUpdate() }
    }

    # ---- Broadcast-Firewall: Einstellungsfenster ------------------------------------------
    # Zustand zwischenspeichern (der Button wird jede Sekunde aktualisiert - nicht jedes Mal die Datei lesen)
    $script:PelNoiseOn = [bool](Get-PelNoiseConfig).Enabled
    function Update-DashboardNoiseButton {
        $eng = $script:PelP2pEngine
        if (-not $script:PelNoiseOn) {
            $btnP2pNoise.Text = "Broadcast-Firewall: AUS  (Einstellungen ...)"
            $btnP2pNoise.ForeColor = [System.Drawing.Color]::Orange
        } else {
            $cnt = if ($eng -and (Test-PelP2pRunning)) { " - $($eng.NoiseBlocked.ToString('N0')) Pakete geblockt" } else { '' }
            $btnP2pNoise.Text = "Broadcast-Firewall: AN$cnt  (...)"
            $btnP2pNoise.ForeColor = [System.Drawing.Color]::LightGreen
        }
    }

    function Show-PelNoiseDialog {
        $set = Get-PelP2pSettings
        $cfg = Get-PelNoiseConfig $set
        $d = (New-PelForm)
        $d.Text = 'Broadcast-Firewall (P2P-Netzwerk)'
        $d.Size = New-Object System.Drawing.Size(560, 600)
        $d.StartPosition = 'CenterParent'
        $d.FormBorderStyle = 'FixedDialog'
        $d.MaximizeBox = $false; $d.MinimizeBox = $false
        $d.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
        $d.ForeColor = [System.Drawing.Color]::White
        $d.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)

        $info = New-Object System.Windows.Forms.Label
        $info.Text = "Windows, Linux und macOS schicken ständig Suchrufe ins Netz (Namensauflösung, Drucker, Smart-TVs, Apps). Im P2P-Netz würden die an alle Mitspieler gehen und nur Bandbreite kosten. Die Firewall verwirft sie beim Senden UND Empfangen. Die Server-Suche von Spielen nutzt andere Ports und ist nicht betroffen."
        $info.Location = New-Object System.Drawing.Point(14, 10); $info.Size = New-Object System.Drawing.Size(520, 64)
        $info.ForeColor = [System.Drawing.Color]::LightGray
        $d.Controls.Add($info)

        $chkOn = New-Object System.Windows.Forms.CheckBox
        $chkOn.Text = 'Broadcast-Firewall aktiv'
        $chkOn.Location = New-Object System.Drawing.Point(14, 78); $chkOn.Size = New-Object System.Drawing.Size(300, 24)
        $chkOn.Checked = [bool]$cfg.Enabled
        $d.Controls.Add($chkOn)

        $clb = New-Object System.Windows.Forms.CheckedListBox
        $clb.Location = New-Object System.Drawing.Point(14, 106); $clb.Size = New-Object System.Drawing.Size(520, 200)
        $clb.CheckOnClick = $true
        $clb.BackColor = [System.Drawing.Color]::FromArgb(20, 20, 20); $clb.ForeColor = [System.Drawing.Color]::White
        $clb.BorderStyle = 'FixedSingle'
        foreach ($c in $script:PelNoiseCategories) {
            $ptxt = if ($c.Ports.Count -gt 0) { "  [UDP " + ($c.Ports -join ', ') + "]" } else { '' }
            [void]$clb.Items.Add($c.Name + $ptxt, [bool]$cfg.Cats[$c.Id])
        }
        $d.Controls.Add($clb)

        $lblCustom = New-Object System.Windows.Forms.Label
        $lblCustom.Text = 'Zusätzliche UDP-Ports blocken (Komma-getrennt):'
        $lblCustom.Location = New-Object System.Drawing.Point(14, 314); $lblCustom.Size = New-Object System.Drawing.Size(520, 20)
        $d.Controls.Add($lblCustom)
        $txtCustom = New-Object System.Windows.Forms.TextBox
        $txtCustom.Location = New-Object System.Drawing.Point(14, 336); $txtCustom.Size = New-Object System.Drawing.Size(520, 24)
        $txtCustom.BackColor = [System.Drawing.Color]::FromArgb(40, 40, 40); $txtCustom.ForeColor = [System.Drawing.Color]::White; $txtCustom.BorderStyle = 'FixedSingle'
        $txtCustom.Text = $cfg.Custom
        $d.Controls.Add($txtCustom)

        $chkStrict = New-Object System.Windows.Forms.CheckBox
        $chkStrict.Text = 'Streng: diese Dienste auch als Direktverbindung blocken (empfohlen)'
        $chkStrict.Location = New-Object System.Drawing.Point(14, 366); $chkStrict.Size = New-Object System.Drawing.Size(520, 24)
        $chkStrict.Checked = [bool]$cfg.Strict
        $d.Controls.Add($chkStrict)

        $lblStats = New-Object System.Windows.Forms.Label
        $lblStats.Location = New-Object System.Drawing.Point(14, 396); $lblStats.Size = New-Object System.Drawing.Size(520, 110)
        $lblStats.ForeColor = [System.Drawing.Color]::LightGreen
        $lblStats.Font = New-Object System.Drawing.Font("Consolas", 9)
        $d.Controls.Add($lblStats)

        $mkB = {
            param([string]$t, [int]$x, [bool]$accent)
            $b = New-Object System.Windows.Forms.Button
            $b.Text = $t; $b.Location = New-Object System.Drawing.Point($x, 516); $b.Size = New-Object System.Drawing.Size(126, 32)
            $b.FlatStyle = 'Flat'; $b.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
            $b.BackColor = if ($accent) { [System.Drawing.Color]::FromArgb(0, 120, 215) } else { [System.Drawing.Color]::FromArgb(45, 45, 45) }
            $d.Controls.Add($b); return $b
        }
        $bDefault = & $mkB 'Standard' 14 $false
        $bReset = & $mkB 'Zähler zurücksetzen' 146 $false
        $bSave = & $mkB 'Speichern' 278 $true
        $bCancel = & $mkB 'Abbrechen' 408 $false
        $d.CancelButton = $bCancel

        $updStats = {
            $eng = $script:PelP2pEngine
            if (-not $eng -or -not (Test-PelP2pRunning)) { $lblStats.Text = "Statistik erscheint, sobald du einer Lobby beigetreten bist."; return }
            $lines = @("Geblockt seit Beitritt: $($eng.NoiseBlocked.ToString('N0')) Pakete")
            foreach ($pair in (([string]$eng.GetNoiseStats()) -split ';' | Where-Object { $_ } | Select-Object -First 5)) {
                $kv = $pair -split '='
                $lines += ("  {0,-44} {1,8}" -f (Get-PelNoisePortName ([int]$kv[0])), ([long]$kv[1]).ToString('N0'))
            }
            $lblStats.Text = ($lines -join "`r`n")
        }
        & $updStats
        $tmr = New-Object System.Windows.Forms.Timer
        $tmr.Interval = 1000
        $tmr.Add_Tick({ try { & $updStats } catch { } })
        $tmr.Start()

        $bDefault.Add_Click({
            for ($i = 0; $i -lt $script:PelNoiseCategories.Count; $i++) { $clb.SetItemChecked($i, [bool]$script:PelNoiseCategories[$i].Default) }
            $txtCustom.Text = ''; $chkStrict.Checked = $true; $chkOn.Checked = $true
        })
        $bReset.Add_Click({ if ($script:PelP2pEngine) { $script:PelP2pEngine.ResetNoiseStats() }; & $updStats })
        $bSave.Add_Click({
            $bad = @(([string]$txtCustom.Text -split '[,;\s]+') | Where-Object { $_ -and -not ($_ -match '^\d{1,5}$' -and [int]$_ -ge 1 -and [int]$_ -le 65535) })
            if ($bad.Count -gt 0) { Show-PelMsg "Ungültige Ports: $($bad -join ', ')`nBitte nur Zahlen von 1 bis 65535, getrennt durch Komma." 'Broadcast-Firewall' ([System.Windows.Forms.MessageBoxIcon]::Warning) $d; return }
            $ids = @()
            for ($i = 0; $i -lt $script:PelNoiseCategories.Count; $i++) { if ($clb.GetItemChecked($i)) { $ids += $script:PelNoiseCategories[$i].Id } }
            $s2 = Get-PelP2pSettings
            $s2.NoiseEnabled = [bool]$chkOn.Checked
            $s2.NoiseStrict = [bool]$chkStrict.Checked
            $s2.NoiseCats = if ($ids.Count -gt 0) { $ids -join ',' } else { 'none' }
            $s2.NoiseCustom = ([string]$txtCustom.Text).Trim()
            Save-PelP2pSettings $s2
            $script:PelNoiseOn = [bool]$chkOn.Checked
            Set-PelEngineNoiseFilter $script:PelP2pEngine    # wirkt sofort, auch während einer laufenden Lobby
            Write-PelLog -Level 'P2P' -Message ("Broadcast-Firewall: " + $(if ($chkOn.Checked) { 'AN' } else { 'AUS' }) + ", Kategorien: " + $s2.NoiseCats + ", eigene Ports: " + $s2.NoiseCustom)
            $d.Close()
        })
        [void]$d.ShowDialog($mainForm)
        $tmr.Stop(); $tmr.Dispose(); $d.Dispose()
        Update-DashboardNoiseButton
    }

    $btnP2pNoise.Add_Click({ Show-PelNoiseDialog })
    $btnP2pJoin.Add_Click({ Invoke-DashboardP2pJoin })
    # Einladungscode aus den aktuellen Feldern erzeugen (z. B. für einen eigenen VPS-Server)
    $btnP2pMakeInvite.Add_Click({
        $srv = $txtP2pServer.Text.Trim()
        $lob = $txtP2pLobby.Text.Trim()
        $pw = $txtP2pPass.Text
        $problem = $null
        if (-not $srv) { $problem = "Bitte zuerst den Vermittlungsserver eintragen (z. B. lan.deinserver.de:47810)." }
        elseif ($lob.Length -lt 3) { $problem = "Der Lobby-Name muss mindestens 3 Zeichen haben." }
        elseif ($pw.Length -lt 6) { $problem = "Das Lobby-Passwort muss mindestens 6 Zeichen haben." }
        elseif ($srv -match '^\s*(127\.|localhost)') { $problem = "Du hostest gerade selbst (Option 9) - nimm bitte den Einladungscode aus Option 9, der enthält deine öffentliche Adresse statt 127.0.0.1." }
        if ($problem) { Show-PelMsg $problem 'Einladung erstellen' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm; return }
        $hint = ''
        if ($srv -match '^\s*(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)') { $hint = "`n`nAchtung: $srv ist eine Heimnetz-Adresse - der Code funktioniert nur für Geräte im selben Netzwerk." }
        $code = New-PelInviteCode $srv $lob $pw
        if (Set-PelClipboard $code) {
            Show-PelMsg ("Einladungscode kopiert:`n`n$code`n`nSchick ihn deinen Freunden (Discord, WhatsApp, ...). Sie klicken im Control Center auf 'Einladung einfügen'.`nDer Code enthält das Lobby-Passwort - nur an Mitspieler weitergeben." + $hint) 'Einladung erstellen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
        } else {
            Show-PelMsg "Die Zwischenablage ist gerade blockiert. Hier der Code zum Abschreiben/Markieren:`n`n$code" 'Einladung erstellen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
        }
    })
    # Einladungscode (von Option 9 eines Freundes) aus der Zwischenablage oder per Eingabe
    $btnP2pInvite.Add_Click({
        $clip = ''
        try { $clip = [System.Windows.Forms.Clipboard]::GetText() } catch { }
        $inv = ConvertFrom-PelInviteCode $clip
        $typed = ''
        if (-not $inv -and "$clip" -notmatch 'PELF1:') {
            try { Add-Type -AssemblyName Microsoft.VisualBasic } catch { }
            $typed = [Microsoft.VisualBasic.Interaction]::InputBox([PelI18n]::Tr("Einladungscode einfügen (beginnt mit PEL1:):"), [PelI18n]::Tr("Einladung einfügen"), "")
            if (-not $typed) { return }
            $inv = ConvertFrom-PelInviteCode $typed
        }
        if (-not $inv -and "$clip $typed" -match 'PELF1:') { Show-PelMsg (Get-PelText "Das ist ein Datei-Server-Code (PELF1:). Den bitte in Option 1 (Downloader) unter 'Einladung einfügen' verwenden." "This is a file server code (PELF1:). Please use it in option 1 (downloader) under 'Paste invite'.") 'Einladung einfügen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm; return }
        if (-not $inv) { Show-PelMsg "Das ist kein gültiger Einladungscode. Er beginnt mit 'PEL1:' - lass ihn dir vom Gastgeber (Option 9 -> 'Einladung kopieren') noch einmal schicken." 'Einladung einfügen' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm; return }
        $txtP2pServer.Text = $inv.Server
        $txtP2pLobby.Text = $inv.Lobby
        $txtP2pPass.Text = $inv.Password
        $chkP2pAuto.Checked = $true
        Invoke-DashboardP2pJoin
    })
    $btnP2pLeave.Add_Click({
        $mainForm.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try { Stop-PelP2p } finally { $mainForm.Cursor = [System.Windows.Forms.Cursors]::Default }
        $p2pUi.KeepMsg = $false
        $lblP2pState.Text = "Status: getrennt"
        $lblP2pState.ForeColor = [System.Drawing.Color]::LightGray
        Update-DashboardP2pButtons
        Update-DashboardP2p
        Update-DashboardAdapterLabel
        Update-DashboardStatus
    })
    $chkP2pAuto.Add_CheckedChanged({
        # Haken entfernt -> gespeichertes Passwort sofort löschen
        if (-not $chkP2pAuto.Checked) {
            $s0 = Get-PelP2pSettings
            $s0.AutoConnect = $false
            $s0.PasswordEnc = ''
            Save-PelP2pSettings $s0
        }
    })
    $lvP2p.ShowItemToolTips = $true
    Update-DashboardP2pButtons

    # ---- Option 9: Eigene Lobby hosten (eingebauter Vermittlungsserver) -----------------
    # Fenster ist nicht-modal (Control Center bleibt bedienbar). Die Handler greifen nur auf
    # $script:PelHostUi zu, weil die lokalen Variablen von Show-PelHostDialog nach dem
    # Öffnen nicht mehr existieren.
    $script:PelHostUi = $null
    $script:PelHostForm = $null

    # ---- Option 1: Datei-Server - Button-Text und Ereignisse (jede Sekunde) --------------
    function Update-DashboardFileServer {
        Receive-PelFileServerEvents
        # Wunsch aus dem Downloader-Fenster (Option 1): Datei-Server-Dialog hier öffnen
        if ([System.IO.File]::Exists($script:PelFileServerReqFile)) {
            try { [System.IO.File]::Delete($script:PelFileServerReqFile) } catch { }
            try { Show-PelCcWindow } catch { }
            $mainForm.BeginInvoke([Action]{ Show-PelFileServerDialog -Owner $mainForm }) | Out-Null
        }
        if (-not $btnFiles) { return }
        if (Test-PelFileServerRunning) {
            $n = [PelFileServer]::ActiveDownloads
            $t = Get-PelText "1. Downloader & Datei-Server: AKTIV ($n Downloads laufen)" "1. Downloader & file server: ACTIVE ($n downloads running)"
            if ($btnFiles.Text -ne $t) { $btnFiles.Text = $t }
            $btnFiles.ForeColor = [System.Drawing.Color]::LightGreen
        } else {
            $t = Get-PelText "1. Tools, Mods & Games Downloader & Datei-Server" "1. Tools, mods & games downloader & file server"
            if ($btnFiles.Text -ne $t) { $btnFiles.Text = $t }
            $btnFiles.ForeColor = [System.Drawing.Color]::White
        }
    }

    function Invoke-DashboardHostStart {
        param([string]$Lobby, [string]$Password, [int]$DynProvider = 0, [string]$DynName = '', [string]$DynSecret = '', [bool]$Auto, [switch]$Silent)
        $problem = $null
        if ($Lobby.Trim().Length -lt 3) { $problem = "Der Lobby-Name muss mindestens 3 Zeichen haben." }
        elseif ($Password.Length -lt 6) { $problem = "Das Lobby-Passwort muss mindestens 6 Zeichen haben." }
        if ($problem) {
            if (-not $Silent) { Show-PelMsg $problem 'Lobby hosten' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm }
            return
        }
        if ($DynProvider -gt 0 -and -not $DynName.Trim()) {
            if (-not $Silent) { Show-PelMsg "Für die feste Adresse (DynDNS) bitte den Namen eintragen - oder 'Keine' wählen." 'Lobby hosten' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm }
            return
        }
        $s = Get-PelP2pSettings
        $s.HostLobby = $Lobby.Trim()
        $s.HostPasswordEnc = Protect-PelP2pPassword $Password
        $s.HostAddress = ''
        $s.DynProvider = $DynProvider
        $s.DynName = $DynName.Trim()
        $s.DynSecretEnc = Protect-PelP2pPassword $DynSecret
        $s.HostAuto = $Auto
        Save-PelP2pSettings $s
        $mainForm.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            Start-PelHostServer -Lobby $Lobby.Trim() -Password $Password -DynProvider $DynProvider -DynName $DynName.Trim() -DynSecret $DynSecret
        } catch {
            $err = Get-PelInnerMessage $_
            Write-PelLog -Level 'HOST' -Message "Start fehlgeschlagen: $err"
            if (-not $Silent) { Show-PelMsg "Hosten konnte nicht gestartet werden:`n`n$err" 'Lobby hosten' ([System.Windows.Forms.MessageBoxIcon]::Error) $mainForm }
            return
        } finally { $mainForm.Cursor = [System.Windows.Forms.Cursors]::Default }
        # Selbst der eigenen Lobby beitreten (über den eigenen Server auf diesem PC)
        if (Test-PelP2pRunning) { Stop-PelP2p }
        $txtP2pServer.Text = "127.0.0.1:$($script:PelHostPort)"
        $txtP2pLobby.Text = $Lobby.Trim()
        $txtP2pPass.Text = $Password
        $p2pUi.OwnLobby = $true
        if ($Silent) { Invoke-DashboardP2pJoin -Silent -NoSave } else { Invoke-DashboardP2pJoin -NoSave }
        Update-DashboardHost
    }

    function Invoke-DashboardHostStop {
        if ($p2pUi.OwnLobby -and (Test-PelP2pRunning)) { Stop-PelP2p }
        $p2pUi.OwnLobby = $false
        Stop-PelHostServer
        # P2P-Box wieder auf die gespeicherte (fremde) Lobby zurückstellen
        $s = Get-PelP2pSettings
        $txtP2pServer.Text = [string]$s.Server
        $txtP2pLobby.Text = [string]$s.Lobby
        $txtP2pPass.Text = Unprotect-PelP2pPassword ([string]$s.PasswordEnc)
        Update-DashboardP2pButtons
        Update-DashboardP2p
        Update-DashboardHost
        Update-DashboardAdapterLabel
    }

    function Update-DashboardHost {
        $h = $script:PelHostState
        if ($script:PelRvServer) {
            $line = $null
            while ($script:PelRvServer.Log.TryDequeue([ref]$line)) { Write-PelLog -Level 'HOST' -Message $line }
        }
        [void](Receive-PelHostProbe)
        Invoke-PelDynTick
        $members = 0
        if ($h.Running -and $script:PelRvServer) { $members = [int]$script:PelRvServer.MemberCount }
        if ($btnHost) {
            if ($h.Running) {
                $t = "9. Eigene Lobby hosten: AKTIV ($members in der Lobby)"
                if ($btnHost.Text -ne $t) { $btnHost.Text = $t }
                $btnHost.ForeColor = [System.Drawing.Color]::LightGreen
            } else {
                $btnHost.Text = "9. Eigene Lobby hosten (für Freunde, ein Klick)"
                $btnHost.ForeColor = [System.Drawing.Color]::White
            }
        }
        $ui = $script:PelHostUi
        if (-not $ui -or $ui.Form.IsDisposed) { return }
        foreach ($c in @($ui.Lobby, $ui.Pass, $ui.NewPass, $ui.DynProv)) { $c.Enabled = -not $h.Running }
        $dp = $ui.DynProv.SelectedIndex
        $ui.DynName.Enabled = (-not $h.Running) -and $dp -gt 0
        $ui.DynSecret.Enabled = (-not $h.Running) -and ($dp -eq 2 -or $dp -eq 3)
        if ($h.Running) {
            $ui.Start.Text = "Hosten beenden"
            $ui.Start.BackColor = [System.Drawing.Color]::FromArgb(160, 50, 40)
            $upnp = if ($h.Probing) { 'wird eingerichtet ...' } elseif ($h.UpnpOk) { 'OK (automatisch freigegeben)' } else { 'nicht möglich - siehe Hinweis' }
            $pub = if ($h.PublicIp) { $h.PublicIp } elseif ($h.Probing) { 'wird ermittelt ...' } else { 'unbekannt' }
            $d = $script:PelDyn
            $chk = ''
            if ($d.Job) { $chk = '  (prüfe ...)' }
            elseif ($d.LastCheck -gt [DateTime]::MinValue) { $chk = "  (geprüft $($d.LastCheck.ToString('HH:mm')), nächste $($d.NextCheck.ToLocalTime().ToString('HH:mm')))" }
            # Einzelteile vorab übersetzen (zusammengesetzte Zeile ist sonst nicht eindeutig)
            $pub = ConvertTo-PelLang $pub; $chk = ConvertTo-PelLang $chk; $upnp = ConvertTo-PelLang $upnp
            $st = "Server läuft (UDP $($script:PelHostPort))   Mitglieder: $members`nÖffentliche IP: $pub$chk   LAN-IP: $($h.LanIp)`nRouter-Freigabe (UPnP): $upnp"
            if ($d.Provider -gt 0) {
                $dl = ConvertTo-PelLang $(if ($d.Job) { 'prüfe ...' } elseif ($d.Message) { $d.Message } else { 'erster Check folgt ...' })
                if ($d.Resolved -and $h.PublicIp) {
                    if ($d.Resolved -eq $h.PublicIp) { $dl += (ConvertTo-PelLang '  - Name passt') } else { $dl += (ConvertTo-PelLang "  - Name zeigt noch auf $($d.Resolved) (DNS braucht ggf. ein paar Minuten)") }
                }
                $st += "`nFeste Adresse: $($h.Address)  |  $dl"
            } else {
                $st += "`nKeine feste Adresse: ändert sich deine öffentliche IP, brauchen Freunde einen neuen Code."
            }
            if ($ui.Status.Text -ne $st) { $ui.Status.Text = $st }
            $ui.Status.ForeColor = if ($script:PelDyn.Provider -gt 0 -and -not $script:PelDyn.Ok) { [System.Drawing.Color]::Orange } else { [System.Drawing.Color]::LightGreen }
            $code = if ($h.Address) { New-PelInviteCode $h.Address $h.Lobby $h.Password } else { '(wird erstellt, sobald die öffentliche IP bekannt ist ...)' }
            if ($ui.Code.Text -ne $code) { $ui.Code.Text = $code }
            $ui.Copy.Enabled = [bool]$h.Address
            $ui.IpNow.Enabled = -not $script:PelDyn.Job
        } else {
            $ui.IpNow.Enabled = $false
            $ui.Start.Text = "Hosten starten"
            $ui.Start.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
            $ui.Status.Text = "Nicht aktiv."
            $ui.Status.ForeColor = [System.Drawing.Color]::LightGray
            $ui.Code.Text = ''
            $ui.Copy.Enabled = $false
        }
        if ($ui.Warn.Text -ne $h.Warning) { $ui.Warn.Text = $h.Warning }
    }

    function Show-PelHostDialog {
        if ($script:PelHostForm -and -not $script:PelHostForm.IsDisposed) { $script:PelHostForm.Activate(); return }
        $hs = Get-PelP2pSettings
        $f = (New-PelForm)
        $f.Text = "Eigene Lobby hosten"
        $f.Size = New-Object System.Drawing.Size(540, 740)
        $f.StartPosition = 'CenterScreen'
        $f.FormBorderStyle = 'FixedDialog'
        $f.MaximizeBox = $false
        $f.BackColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
        $f.ForeColor = [System.Drawing.Color]::White
        $fn = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
        $f.Font = $fn

        $mk = {
            param([string]$type, [string]$text, [int]$x, [int]$y, [int]$w, [int]$h)
            $c = New-Object ("System.Windows.Forms.$type")
            $c.Text = $text
            $c.Location = New-Object System.Drawing.Point($x, $y)
            $c.Size = New-Object System.Drawing.Size($w, $h)
            if ($type -eq 'TextBox') { $c.BackColor = [System.Drawing.Color]::FromArgb(40, 40, 40); $c.ForeColor = [System.Drawing.Color]::White; $c.BorderStyle = 'FixedSingle' }
            if ($type -eq 'Button') { $c.FlatStyle = 'Flat'; $c.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45); $c.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70) }
            $f.Controls.Add($c)
            return $c
        }
        $info = & $mk 'Label' ("Mit einem Klick wirst du Gastgeber: Der Manager startet den Vermittlungsserver, " +
            "gibt die Ports im Router automatisch frei (UPnP) und erstellt einen Einladungscode. " +
            "Deine Freunde klicken im Control Center nur auf 'Einladung einfügen' - fertig. " +
            "Der Server läuft, solange dein Control Center offen ist.") 16 12 495 76
        $info.ForeColor = [System.Drawing.Color]::LightGray

        [void](& $mk 'Label' 'Lobby-Name:' 16 96 130 20)
        $defLobby = if ($hs.HostLobby) { [string]$hs.HostLobby } else { ConvertTo-PelLang "$(Get-PelDisplayName)s Lobby" }
        $tLobby = & $mk 'TextBox' $defLobby 150 94 360 24
        [void](& $mk 'Label' 'Passwort:' 16 128 130 20)
        $defPw = Unprotect-PelP2pPassword ([string]$hs.HostPasswordEnc)
        if (-not $defPw) { $defPw = New-PelRandomPassword }
        $tPass = & $mk 'TextBox' $defPw 150 126 270 24
        $bNew = & $mk 'Button' 'Neu' 426 125 84 26
        # ---- Feste Adresse (DynDNS) ----
        $prov = [int]$hs.DynProvider
        $dName = [string]$hs.DynName
        if ($prov -eq 0 -and $hs.HostAddress) { $prov = 1; $dName = [string]$hs.HostAddress }   # alte Einstellung übernehmen
        [void](& $mk 'Label' 'Feste Adresse:' 16 160 130 20)
        $cProv = & $mk 'ComboBox' '' 150 158 360 24
        $cProv.DropDownStyle = 'DropDownList'
        $cProv.FlatStyle = 'Flat'
        $cProv.BackColor = [System.Drawing.Color]::FromArgb(40, 40, 40)
        $cProv.ForeColor = [System.Drawing.Color]::White
        [void]$cProv.Items.AddRange(@(
            'Keine (öffentliche IP direkt)',
            'Router hält den Namen aktuell (z. B. MyFRITZ!)',
            'DuckDNS (kostenlos, Manager aktualisiert selbst)',
            'Andere DynDNS (Update-URL mit {IP})'))
        $lDynName = & $mk 'Label' 'Name:' 16 192 130 20
        $tDynName = & $mk 'TextBox' $dName 150 190 360 24
        $lDynSecret = & $mk 'Label' 'Token:' 16 224 130 20
        $tDynSecret = & $mk 'TextBox' (Unprotect-PelP2pPassword ([string]$hs.DynSecretEnc)) 150 222 360 24
        $bDynTest = & $mk 'Button' 'Jetzt testen' 16 254 130 26
        $lDynResult = & $mk 'Label' '' 152 258 358 20
        $lDynResult.ForeColor = [System.Drawing.Color]::LightGray
        $lDynHint = & $mk 'Label' '' 16 284 494 36
        $lDynHint.ForeColor = [System.Drawing.Color]::DarkGray
        $lDynHint.Font = New-Object System.Drawing.Font("Segoe UI", 8.5, [System.Drawing.FontStyle]::Regular)

        $cAuto = & $mk 'CheckBox' 'Beim Start des Managers automatisch hosten' 16 324 494 24
        $cAuto.Checked = [bool]$hs.HostAuto
        $bStart = & $mk 'Button' 'Hosten starten' 16 354 494 36
        $bStart.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)

        $lStatus = & $mk 'Label' 'Nicht aktiv.' 16 398 494 78
        [void](& $mk 'Label' 'Einladungscode (an Freunde schicken - enthält das Passwort):' 16 480 494 20)
        $tCode = & $mk 'TextBox' '' 16 502 494 24
        $tCode.ReadOnly = $true
        $bCopy = & $mk 'Button' 'Einladung kopieren' 16 532 290 32
        $bCopy.BackColor = [System.Drawing.Color]::FromArgb(0, 135, 70)
        $bIpNow = & $mk 'Button' 'Öffentliche IP jetzt aktualisieren' 312 532 198 32
        $tipIp = New-Object System.Windows.Forms.ToolTip
        [PelI18n]::Tip($tipIp, $bIpNow, "Prüft sofort die öffentliche IP, meldet sie an DynDNS und kündigt dich den Mitspielern neu an. Automatisch passiert das alle 5 Minuten.")
        $lWarn = & $mk 'Label' '' 16 572 494 120
        $lWarn.ForeColor = [System.Drawing.Color]::Orange

        $script:PelHostUi = [pscustomobject]@{ Form = $f; Lobby = $tLobby; Pass = $tPass; NewPass = $bNew; Auto = $cAuto; Start = $bStart; Status = $lStatus; Code = $tCode; Copy = $bCopy; Warn = $lWarn
            IpNow = $bIpNow; DynProv = $cProv; DynName = $tDynName; DynSecret = $tDynSecret; DynNameLabel = $lDynName; DynSecretLabel = $lDynSecret; DynTest = $bDynTest; DynResult = $lDynResult; DynHint = $lDynHint }
        $script:PelHostForm = $f

        $cProv.Add_SelectedIndexChanged({
            $u = $script:PelHostUi
            if (-not $u) { return }
            $i = $u.DynProv.SelectedIndex
            $u.DynResult.Text = ''
            switch ($i) {
                1 { $u.DynNameLabel.Text = 'Name:'; $u.DynSecretLabel.Text = '(nicht nötig)'; $u.DynSecret.UseSystemPasswordChar = $false
                    $u.DynHint.Text = "Der Router aktualisiert den Namen selbst. Fritz!Box: Internet -> MyFRITZ!-Konto, dort steht die Adresse (z. B. abc123xyz.myfritz.net)." }
                2 { $u.DynNameLabel.Text = 'Subdomain:'; $u.DynSecretLabel.Text = 'Token:'; $u.DynSecret.UseSystemPasswordChar = $true
                    $u.DynHint.Text = "Auf duckdns.org anmelden (z. B. mit Google/GitHub), Subdomain anlegen (z. B. 'meinlan' -> meinlan.duckdns.org) und den Token kopieren." }
                3 { $u.DynNameLabel.Text = 'Name:'; $u.DynSecretLabel.Text = 'Update-URL:'; $u.DynSecret.UseSystemPasswordChar = $false
                    $u.DynHint.Text = "Update-URL deines Anbieters mit {IP} als Platzhalter, z. B. https://benutzer:passwort@dynupdate.no-ip.com/nic/update?hostname=NAME&myip={IP}" }
                default { $u.DynNameLabel.Text = 'Name:'; $u.DynSecretLabel.Text = 'Token:'; $u.DynSecret.UseSystemPasswordChar = $true
                    $u.DynHint.Text = "Ohne feste Adresse ändert sich der Einladungscode, sobald dein Anbieter dir eine neue öffentliche IP gibt (oft täglich)." }
            }
            $run = $script:PelHostState.Running
            $u.DynName.Enabled = (-not $run) -and $i -gt 0
            $u.DynSecret.Enabled = (-not $run) -and ($i -eq 2 -or $i -eq 3)
        })
        $cProv.SelectedIndex = [Math]::Max(0, [Math]::Min(3, $prov))

        $bDynTest.Add_Click({
            $u = $script:PelHostUi
            $u.Form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
            $u.DynResult.Text = 'teste ...'
            $u.DynResult.ForeColor = [System.Drawing.Color]::LightGray
            [System.Windows.Forms.Application]::DoEvents()
            try {
                $i = $u.DynProv.SelectedIndex
                $r = & $script:PelDynWorkScript $i $u.DynName.Text $u.DynSecret.Text '' $true $script:PelHostPort
                $txt = ConvertTo-PelLang ([string]$r.Message)
                if ($i -gt 0 -and $r.Ip) {
                    if ($r.Resolved -eq $r.Ip) { $txt += (ConvertTo-PelLang ' - Name passt') }
                    elseif ($r.Resolved) { $txt += (ConvertTo-PelLang " - Name zeigt noch auf $($r.Resolved)") }
                    else { $txt += (ConvertTo-PelLang ' - Name (noch) nicht auflösbar') }
                }
                $u.DynResult.Text = $txt
                $u.DynResult.ForeColor = if ($r.Ok) { [System.Drawing.Color]::LightGreen } else { [System.Drawing.Color]::Orange }
                $tipR = New-Object System.Windows.Forms.ToolTip
                [PelI18n]::Tip($tipR, $u.DynResult, $txt)
            } catch {
                $u.DynResult.Text = "Test fehlgeschlagen: $($_.Exception.Message)"
                $u.DynResult.ForeColor = [System.Drawing.Color]::Orange
            } finally { $u.Form.Cursor = [System.Windows.Forms.Cursors]::Default }
        })

        $bNew.Add_Click({ $script:PelHostUi.Pass.Text = New-PelRandomPassword })
        $bStart.Add_Click({
            $u = $script:PelHostUi
            if ($script:PelHostState.Running) { Invoke-DashboardHostStop }
            else { Invoke-DashboardHostStart -Lobby $u.Lobby.Text -Password $u.Pass.Text -DynProvider $u.DynProv.SelectedIndex -DynName $u.DynName.Text -DynSecret $u.DynSecret.Text -Auto ([bool]$u.Auto.Checked) }
        })
        $cAuto.Add_CheckedChanged({
            $s = Get-PelP2pSettings
            $s.HostAuto = [bool]$script:PelHostUi.Auto.Checked
            Save-PelP2pSettings $s
        })
        $bIpNow.Add_Click({
            $msg = Invoke-PelDynRefreshNow
            if ($msg) { Show-PelMsg $msg 'Öffentliche IP aktualisieren' ([System.Windows.Forms.MessageBoxIcon]::Information) $script:PelHostUi.Form }
            Update-DashboardHost
        })
        $bCopy.Add_Click({
            if (Set-PelClipboard $script:PelHostUi.Code.Text) {
                Show-PelMsg "Einladungscode kopiert.`n`nSchick ihn deinen Freunden (Discord, WhatsApp, ...). Sie klicken im Control Center in der P2P-Box auf 'Einladung einfügen'." 'Lobby hosten' ([System.Windows.Forms.MessageBoxIcon]::Information) $script:PelHostUi.Form
            }
        })
        $f.Add_FormClosed({ $script:PelHostUi = $null; $script:PelHostForm = $null })
        Update-DashboardHost
        $f.Show($mainForm)
    }

