    $lblUpdated.Font = $fontSmall
    $lblUpdated.TextAlign = [System.Drawing.ContentAlignment]::MiddleRight
    $grpStatus.Controls.Add($lblUpdated)

    function Update-DashboardAdapterLabel {
        $sel = Get-PelSelectedAdapter
        if ($sel) {
            $lblAdapter.Text = "Adapter: $($sel.Name)  ($($sel.Ip))"
            $lblAdapter.ForeColor = [System.Drawing.Color]::LightGreen
        } else {
            $lblAdapter.Text = "Adapter: nicht ausgewählt - bitte 'Adapter wechseln' klicken"
            $lblAdapter.ForeColor = [System.Drawing.Color]::OrangeRed
        }
    }

    # Beim Öffnen: ist noch kein Adapter zentral gewählt, automatisch den mit der
    # niedrigsten Schnittstellenmetrik nehmen (= von Windows bevorzugte Verbindung),
    # zentral speichern, statt nur passiv "nicht ausgewählt" anzuzeigen. Der P2P-Adapter
    # wird automatisch gewählt, sobald die Lobby-Verbindung steht (siehe P2P-Box).
    if (-not (Get-PelSelectedAdapter)) {
        $autoAdapter = Get-PelAutoAdapter
        if ($autoAdapter) { Save-PelSelectedAdapter $autoAdapter }
    }
    Update-DashboardAdapterLabel

    # Freundesliste read-only laden (dieselbe Datei/derselbe Mechanismus wie in der
    # Kommunikationszentrale) - hier wird nichts gesendet, nur zum Anpingen gelesen.
    Initialize-SocialTypes
    $dashSocial = New-Object FriendAndChannelManager

    # ÄNDERUNG: Vorher wurde hier ausschließlich der ZeroTier-CLI-Status abgefragt, auch
    # wenn der Nutzer z. B. Tailscale/WireGuard/Radmin VPN oder ein reines Heimnetzwerk
    # ausgewählt hatte - die Anzeige stand dann fälschlich immer auf "ZeroTier: Nicht
    # verbunden". Jetzt wird stattdessen der zentral gewählte Adapter (siehe
    # Get-PelSelectedAdapter, gilt für jedes VPN und für normales LAN/WLAN gleichermaßen)
    # geprüft: ist er noch aktiv, gilt der Manager als "Verbunden", unabhängig davon,
    # welche Technologie dahintersteckt.
    function Get-DashboardConnectionStatus {
        $r = [pscustomobject]@{ Connected = $false; Ip = ''; AdapterName = '' }
        $a = Get-PelSelectedAdapter
        if ($a) {
            $r.Connected = $true
            $r.Ip = $a.Ip
            $r.AdapterName = $a.Name
        }
        return $r
    }

    function Update-DashboardStatus {
        $conn = Get-DashboardConnectionStatus
        if ($conn.Connected) {
            $lblZt.Text = "Verbunden ($($conn.AdapterName))"
            $lblZt.ForeColor = [System.Drawing.Color]::LightGreen
            $lblIp.Text = "Eigene IP: $($conn.Ip)"
        } else {
            $lblZt.Text = "Nicht verbunden"
            $lblZt.ForeColor = [System.Drawing.Color]::OrangeRed
            $lblIp.Text = "Eigene IP: -"
        }
        $lblUpdated.Text = "Aktualisiert: " + (Get-Date -Format 'HH:mm:ss')
    }

    # Freunde werden per (nicht-blockierendem) ICMP-Ping asynchron geprüft, damit die
    # Oberfläche dabei nicht einfriert - ein Poll-Timer liest die Task-Ergebnisse ab,
    # sobald sie fertig sind (dasselbe Prinzip wie die Hintergrund-Scans in Option 5).
    $pingState = [pscustomobject]@{ Tasks = @(); Total = 0; Online = 0; Busy = $false }
    function Start-DashboardFriendPing {
        if ($pingState.Busy) { return }
        # Vor jeder Prüfung neu von der Festplatte laden, damit neu hinzugefügte/entfernte
        # Freunde (z. B. gerade eben in der Kommunikationszentrale geändert) sofort ohne
        # Neustart des Control Centers berücksichtigt werden.
        $dashSocial.Load()
        $friends = @($dashSocial.GetFriends())
        if ($friends.Count -eq 0) {
            $lblFriends.Text = "Freunde online: keine Freunde gespeichert"
            $lblFriends.ForeColor = [System.Drawing.Color]::LightGray
            return
        }
        $pingState.Busy = $true
        $pingState.Total = $friends.Count
        $pingState.Tasks = @($friends | ForEach-Object {
            $p = New-Object System.Net.NetworkInformation.Ping
            $p.SendPingAsync($_.Ip, 700)
        })
        $lblFriends.Text = "Freunde online: prüfe $($friends.Count) ..."
    }
    $pingPoll = New-Object System.Windows.Forms.Timer
    $pingPoll.Interval = 300
    $pingPoll.Add_Tick({
        if (-not $pingState.Busy) { return }
        foreach ($t in $pingState.Tasks) { if (-not $t.IsCompleted) { return } }
        $online = 0
        foreach ($t in $pingState.Tasks) {
            try { if ($t.Result.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) { $online++ } } catch { }
        }
        $lblFriends.Text = "Freunde online: $online von $($pingState.Total)"
        $lblFriends.ForeColor = if ($online -gt 0) { [System.Drawing.Color]::LightGreen } else { [System.Drawing.Color]::LightGray }
        $pingState.Online = $online
        $pingState.Busy = $false
    })
    $pingPoll.Start()

    $statusTimer = New-Object System.Windows.Forms.Timer
    $statusTimer.Interval = 8000
    $statusTimer.Add_Tick({ Update-DashboardStatus; Start-DashboardFriendPing })
    $statusTimer.Start()

    # P2P-Status (1 s): Log übernehmen, virtuelle IP einrichten, Mitspielerliste
    $p2pTimer = New-Object System.Windows.Forms.Timer
    $p2pTimer.Interval = 1000
    $p2pTimer.Add_Tick({
        try { Update-DashboardP2p } catch { Write-PelLog -Level 'P2P' -Message ("GUI: " + $_.Exception.Message) }
        try { Update-DashboardHost } catch { Write-PelLog -Level 'HOST' -Message ("GUI: " + $_.Exception.Message) }
        try { Update-DashboardFileServer } catch { Write-PelLog -Level 'FILES' -Message ("GUI: " + $_.Exception.Message) }
    })
    $p2pTimer.Start()
    $mainForm.Add_Shown({
        # Autostart Datei-Server (Option 1)
        try {
            $fsSet = Get-PelFileServerSettings
            if ($fsSet.Auto) { Start-PelFileServer -Folder $fsSet.Folder -Port $fsSet.Port }
        } catch { Write-PelLog -Level 'FILES' -Message "Autostart Datei-Server: $($_.Exception.Message)" }
        try { Update-DashboardFileServer } catch { }
        # Autostart: erst eigene Lobby hosten (tritt dabei selbst bei), sonst gemerkte Lobby
        if ($p2pSet.HostAuto -and $p2pSet.HostLobby -and $p2pSet.HostPasswordEnc) {
            $autoProv = [int]$p2pSet.DynProvider
            $autoName = [string]$p2pSet.DynName
            if ($autoProv -eq 0 -and $p2pSet.HostAddress) { $autoProv = 1; $autoName = [string]$p2pSet.HostAddress }
            Invoke-DashboardHostStart -Lobby ([string]$p2pSet.HostLobby) -Password (Unprotect-PelP2pPassword ([string]$p2pSet.HostPasswordEnc)) -DynProvider $autoProv -DynName $autoName -DynSecret (Unprotect-PelP2pPassword ([string]$p2pSet.DynSecretEnc)) -Auto $true -Silent
        } elseif ($p2pSet.AutoConnect -and $txtP2pLobby.Text -and $txtP2pPass.Text) {
            Invoke-DashboardP2pJoin -Silent
        }
    })

    # ---- Live-Status-Verbund zwischen allen Managern (Port 9928) -----------------------
    # Jeder offene Control Center meldet per UDP-Broadcast laufend den eigenen Live-Status
    # (Name, IP, P2P-Status, Freunde online, Version) UND hört gleichzeitig auf die
    # Meldungen aller anderen Manager im Netz - "kommunizieren und abrufen" ohne zentralen
    # Server (reines UDP-Broadcast/Listen-Prinzip).
    $script:PelOtherManagers = @{}

    $statTx = $null
    try { $statTx = New-Object System.Net.Sockets.UdpClient; $statTx.EnableBroadcast = $true } catch { $statTx = $null }
    $statBcEp = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Broadcast, $script:PelStatusPort)

    $statRx = $null
    try {
        $statRx = New-Object System.Net.Sockets.UdpClient
        $statRx.Client.SetSocketOption([System.Net.Sockets.SocketOptionLevel]::Socket, [System.Net.Sockets.SocketOptionName]::ReuseAddress, $true)
        $statRx.Client.Bind((New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, $script:PelStatusPort)))
        $statRx.EnableBroadcast = $true
    } catch { $statRx = $null }

    try {
        Get-NetFirewallRule -DisplayName "Project Earth LAN Status $($script:PelStatusPort)*" -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue
        New-NetFirewallRule -DisplayName "Project Earth LAN Status $($script:PelStatusPort) (UDP)" -Direction Inbound -Action Allow -Protocol UDP -LocalPort $script:PelStatusPort -RemoteAddress Any -Profile Any -ErrorAction Stop | Out-Null
    } catch { }

    # ---- Zustand für "Wer spielt was", Spieleabende und Eigen-Filter --------------------
    # Windows liefert eigene Broadcasts auch an den Absender zurück - ohne diesen Filter
    # würde der eigene PC unter "Andere Manager" mitgezählt.
    $script:PelOwnIps = Get-PelLocalIpSet
    $script:PelMyName = Get-PelDisplayName
    $script:PelMyGame = $null
    $dashState = @{ PlayingSig = ''; OwnIp = ''; LastReqMs = [int64]0 }
    Import-PelEvents

    # Spielebibliothek-Abgleich (siehe Region "Spielebibliothek-Abgleich"). Erste Liste
    # ca. 3 s nach dem Start, zusammen mit der Bitte an alle, ihre Listen zu schicken.
    $libPeers = Read-PelNetLibrary
    $libSync = @{
        Peers = $libPeers; Partial = @{}; Rate = @{}; Dirty = $false; LastSaveMs = [int64]0
        MyStamp = [int64]-1; NextSendMs = ((Get-PelNowMs) + 3000); ReqPending = $true
        ReplyAtMs = [int64]0; LastReqMs = [int64]0; NetExes = (Get-PelNetExeMap $libPeers)
    }

    # Spielerkennung in einem eigenen, wiederverwendeten Hintergrund-Runspace (siehe
    # $script:PelGameDetectScript) - die Oberfläche friert dabei nicht ein.
    $script:PelGameCache = [hashtable]::Synchronized(@{})
    $gameDetect = @{ Rs = $null; PS = $null; Handle = $null }
    try {
        $gameDetect.Rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
        $gameDetect.Rs.Open()
    } catch { $gameDetect.Rs = $null }
    function Start-DashboardGameDetect {
        if (-not $gameDetect.Rs -or $gameDetect.PS) { return }
        try {
            $ps = [PowerShell]::Create()
            $ps.Runspace = $gameDetect.Rs
            [void]$ps.AddScript($script:PelGameDetectScript.ToString())
            [void]$ps.AddArgument($script:PelGameCache)
            [void]$ps.AddArgument($script:PelKnownGameExes)
            [void]$ps.AddArgument([string]$script:SelfPath)
            [void]$ps.AddArgument($libSync.NetExes)
            $gameDetect.PS = $ps
            $gameDetect.Handle = $ps.BeginInvoke()
        } catch { $gameDetect.PS = $null; $gameDetect.Handle = $null }
    }
    function Receive-DashboardGameDetect {
        if (-not $gameDetect.PS -or -not $gameDetect.Handle -or -not $gameDetect.Handle.IsCompleted) { return }
        try {
            $out = $gameDetect.PS.EndInvoke($gameDetect.Handle)
            $r = @($out | Where-Object { $_ })
            if ($r.Count -gt 0) { $script:PelMyGame = $r[0] } else { $script:PelMyGame = $null }
            # Neues Spiel gestartet, das noch nicht in der Bibliothek steht -> aufnehmen;
            # die geänderte games.json löst sofort den Abgleich mit den anderen aus.
            if ($script:PelMyGame) {
                $added = Register-PelRunningGame $script:PelMyGame
                if ($added) {
                    $msgAdd = [PelI18n]::Tr("'{0}' wurde automatisch in die Spielebibliothek aufgenommen.") -f [string]$added.Name
                    $lblUpdated.Text = $msgAdd
                    try { if ($trayIcon -and $trayIcon.Visible) { $trayIcon.ShowBalloonTip(5000, 'Project Earth LAN', $msgAdd, [System.Windows.Forms.ToolTipIcon]::Info) } } catch { }
                    $libSync.NextSendMs = Get-PelNowMs
                }
            }
        } catch { }
        finally {
            try { $gameDetect.PS.Dispose() } catch { }
            $gameDetect.PS = $null
            $gameDetect.Handle = $null
        }
    }

    function Update-DashboardPlaying {
        $rows = New-Object System.Collections.Generic.List[object]
        $mg = $script:PelMyGame
        $self = [pscustomobject]@{
            IsSelf = $true; Name = "$($script:PelMyName) (du)"; Ip = $dashState.OwnIp; SrcIp = ''
            Game = ''; GameExe = ''; JoinPort = 0; Server = ''
        }
        if ($mg) { $self.Game = [string]$mg.Title; $self.GameExe = [string]$mg.Exe; $self.JoinPort = [int]$mg.JoinPort; $self.Server = [string]$mg.Server }
        $rows.Add($self)
        foreach ($m in @($script:PelOtherManagers.Values | Sort-Object @{ Expression = { if ($_.Game) { 0 } else { 1 } } }, Name)) { $rows.Add($m) }
        $sig = (($rows | ForEach-Object { "$($_.Name)|$($_.Game)|$($_.Ip)|$($_.SrcIp)|$($_.JoinPort)|$($_.Server)" }) -join ';')
        if ($sig -eq $dashState.PlayingSig) { return }
        $dashState.PlayingSig = $sig
        $selKey = $null
        if ($lvPlaying.SelectedItems.Count -gt 0) { $t = $lvPlaying.SelectedItems[0].Tag; $selKey = "$($t.Name)|$($t.SrcIp)" }
        $lvPlaying.BeginUpdate()
        $lvPlaying.Items.Clear()
        foreach ($m in $rows) {
            $ip = [string]$m.Ip
            if (-not $ip) { $ip = [string]$m.SrcIp }
            $gameText = '-'
            if ($m.Game) { $gameText = [string]$m.Game }
            $addr = $ip
            if ($m.Server) { $addr = [string]$m.Server }
            elseif ($m.Game -and [int]$m.JoinPort -gt 0 -and $ip) { $addr = "${ip}:$($m.JoinPort)" }
            if (-not $addr) { $addr = '-' }
            $it = New-Object System.Windows.Forms.ListViewItem([string]$m.Name)
            [void][PelI18n]::AddSub($it, $gameText)
            [void][PelI18n]::AddSub($it, $addr)
            $it.Tag = $m
            if ($m.IsSelf) { $it.ForeColor = [System.Drawing.Color]::LightSkyBlue }
            elseif ($m.Game) { $it.ForeColor = [System.Drawing.Color]::LightGreen }
            else { $it.ForeColor = [System.Drawing.Color]::LightGray }
            [void]$lvPlaying.Items.Add($it)
            if ($selKey -and ("$($m.Name)|$($m.SrcIp)" -eq $selKey)) { $it.Selected = $true }
        }
        $lvPlaying.EndUpdate()
    }

    function Send-DashboardUdp([string]$Text) {
        if (-not $statTx) { return }
        try {
            $b = [System.Text.Encoding]::UTF8.GetBytes($Text)
            [void]$statTx.Send($b, $b.Length, $statBcEp)
        } catch { }
    }

    # Gleich beim Öffnen nach bekannten Spieleabenden fragen (statt auf die nächste
    # reguläre Weitergabe zu warten) - wichtig für "Ankündigung beim Öffnen".
    $reqCore = "PEEVTREQ1|$(Get-PelNowMs)"
    Send-DashboardUdp "$reqCore|$(Get-PelHmacBase64 -Text $reqCore)"

    $btnJoinPlayer.Add_Click({
        if ($lvPlaying.SelectedItems.Count -eq 0) {
            Show-PelMsg "Bitte zuerst in der Liste 'Wer spielt gerade was' einen Spieler auswählen." 'Mitspielen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
            return
        }
        $m = $lvPlaying.SelectedItems[0].Tag
        if ($m.IsSelf) {
            Show-PelMsg "Das bist du selbst - wähle einen anderen Spieler aus." 'Mitspielen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
            return
        }
        $ip = [string]$m.Ip
        if (-not $ip) { $ip = [string]$m.SrcIp }
        if (-not $m.Game) {
            $clipOk = Set-PelClipboard $ip
            $clipTxt = if ($clipOk) { "Seine IP $ip liegt in der Zwischenablage." } else { "Seine IP lautet $ip." }
            Show-PelMsg "$($m.Name) spielt gerade nichts, das der Manager erkennt.`n`n$clipTxt" 'Mitspielen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
            return
        }
        $tIp = $ip
        $tJoin = 0
        # Bei einem Server-Prozess den Spiel-Client starten, nicht den Server. Den EXE-Namen
        # des Servers mitgeben - Invoke-PelJoinGame macht daraus die Client-EXE
        # (FEARServer.exe -> FEARMP.exe) und startet nie einen Server.
        $joinName = ([string]$m.Game) -replace '\s*\(Server\)$', ''
        $joinHint = [string]$m.GameExe
        if ($m.Server -and ([string]$m.Server -match '^(\d{1,3}(\.\d{1,3}){3}):(\d{1,5})$')) { $tIp = $matches[1]; $tJoin = [int]$matches[3] }
        elseif ([int]$m.JoinPort -gt 0) { $tJoin = [int]$m.JoinPort }
        if ($tJoin -gt 0) {
            $res = Invoke-PelJoinGame -Ip $tIp -JoinPort $tJoin -GameName $joinName -ExeHint $joinHint -ParentForm $mainForm
        } else {
            # Spieler hostet nicht selbst und sein Server ist unbekannt (z. B. UDP-Server):
            # Spiel ohne Verbindungsparameter starten, seine IP in die Zwischenablage.
            $res = Invoke-PelJoinGame -Ip $tIp -GameName $joinName -ExeHint $joinHint -ParentForm $mainForm -LaunchOnly
        }
        if ($res) { $lblUpdated.Text = $res }
    })
    $lvPlaying.Add_DoubleClick({ $btnJoinPlayer.PerformClick() })

    # ---- Aktionen für den gewählten Spieler (Dropdown "Aktionen" + Rechtsklick) --------
    # Nachricht senden (Postfach), in Chat/Sprachchat einladen, zum Spielen einladen.
    # Einladungen: siehe Kommentar bei New-PelInviteWire.
    $invState = @{ Pending = @{}; Seen = @{}; Rate = @{} }
    $btnJoinPlayer.Size = New-Object System.Drawing.Size(122, 28)
    $btnActions = & $newDashButton "Aktionen ▾" 356 344 $false
    $btnActions.Size = New-Object System.Drawing.Size(74, 28)
    [PelI18n]::Tip($dashTip, $btnActions, 'Nachricht senden, in den Chat oder Sprachchat einladen, zum Spielen einladen (auch per Rechtsklick in der Liste).')

    function Get-DashboardSelectedPeer {
        if ($lvPlaying.SelectedItems.Count -eq 0) {
            Show-PelMsg "Bitte zuerst in der Liste 'Wer spielt gerade was' einen Spieler auswählen." 'Aktionen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
            return $null
        }
        $m = $lvPlaying.SelectedItems[0].Tag
        if ($m.IsSelf) {
            Show-PelMsg "Das bist du selbst - wähle einen anderen Spieler aus." 'Aktionen' ([System.Windows.Forms.MessageBoxIcon]::Information) $mainForm
            return $null
        }
        return $m
    }

    function Get-DashboardPeerIp($Peer) {
        $ip = [string]$Peer.SrcIp
        if (-not $ip) { $ip = [string]$Peer.Ip }
        return $ip
    }

    # Einladung direkt an das Control Center des anderen (UDP 9928). Spielt man das Spiel
    # gerade selbst als Gastgeber, wird der Spielport mitgeschickt; spielt man auf einem
    # Server, dessen Adresse - dann kann der andere mit einem Klick beitreten.
    function Send-DashboardInvite {
        param([string]$Kind, $Peer, [string]$Game = '', [string]$Note = '')
        $target = Get-DashboardPeerIp $Peer
        if (-not $statTx -or -not $target) {
            Show-PelMsg "Die Einladung konnte nicht gesendet werden (Live-Status nicht aktiv)." 'Aktionen' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm
            return
        }
        $port = 0
        $server = ''
        if ($Kind -eq 'game' -and $script:PelMyGame) {
            $cur = ([string]$script:PelMyGame.Title) -replace '\s*\(Server\)$', ''
            if ((ConvertTo-PelNormName $cur) -eq (ConvertTo-PelNormName $Game)) {
                if ([int]$script:PelMyGame.JoinPort -gt 0) { $port = [int]$script:PelMyGame.JoinPort }
                elseif ($script:PelMyGame.Server) { $server = [string]$script:PelMyGame.Server }
            }
        }
        $w = New-PelInviteWire -Kind $Kind -Game $Game -Port $port -Server $server -Note $Note
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($w.Text)
        # Broadcast-Kopie mit den Ziel-IPs (siehe Kommentar bei New-PelInviteWire): kommt
        # auch an, wenn auf dem anderen PC mehrere Programme den Port 9928 teilen.
        $targets = @($target)
        if ($Peer.Ip -and ([string]$Peer.Ip) -ne $target -and ([string]$Peer.Ip) -match '^\d{1,3}(\.\d{1,3}){3}$') { $targets += [string]$Peer.Ip }
        $bcBytes = [System.Text.Encoding]::UTF8.GetBytes("PEINVB1|$($targets -join ',')|$($w.Text)")
        try {
            for ($i = 0; $i -lt 2; $i++) { [void]$statTx.Send($bytes, $bytes.Length, $target, [int]$script:PelStatusPort) }
        } catch {
            Show-PelMsg "Die Einladung konnte nicht gesendet werden:`n$($_.Exception.Message)" 'Aktionen' ([System.Windows.Forms.MessageBoxIcon]::Warning) $mainForm
            return
        }
        try { [void]$statTx.Send($bcBytes, $bcBytes.Length, $statBcEp) } catch { }
        Write-PelLog "Einladung ($Kind) an $($Peer.Name) ($($targets -join ', ')) gesendet."
        $invState.Pending[$w.Id] = @{ Name = [string]$Peer.Name; SentMs = (Get-PelNowMs); Retried = $false; Target = $target; Bytes = $bytes; BcBytes = $bcBytes }
        $lblUpdated.Text = [PelI18n]::Tr("Einladung an {0} gesendet ...") -f $Peer.Name
    }

    # Ausstehende Einladungen: nach 2 s ohne Bestätigung einmal wiederholen, nach 7 s als
    # nicht angekommen melden. Alte Einträge (Duplikat- und Mengenschutz) aufräumen.
    function Update-DashboardInvites {
        $now = Get-PelNowMs
        foreach ($id in @($invState.Pending.Keys)) {
            $p = $invState.Pending[$id]
            $age = $now - $p.SentMs
            if (-not $p.Retried -and $age -gt 2000) {
                $p.Retried = $true
                try { [void]$statTx.Send($p.Bytes, $p.Bytes.Length, $p.Target, [int]$script:PelStatusPort) } catch { }
                if ($p.BcBytes) { try { [void]$statTx.Send($p.BcBytes, $p.BcBytes.Length, $statBcEp) } catch { } }
            } elseif ($age -gt 7000) {
                $invState.Pending.Remove($id)
                $lblUpdated.Text = [PelI18n]::Tr("Einladung an {0} kam nicht an (Control Center dort zu?)") -f $p.Name
                Write-PelLog "Einladung an $($p.Name) ($($p.Target)) wurde nicht bestätigt." 'WARN'
            }
        }
        if (($script:PelStatusHbTick % 120) -eq 7) {
            foreach ($k in @($invState.Seen.Keys)) { if (($now - $invState.Seen[$k]) -gt 1800000) { $invState.Seen.Remove($k) } }
            foreach ($k in @($invState.Rate.Keys)) { if (@(@($invState.Rate[$k]) | Where-Object { $_ -and ($now - $_) -lt 60000 }).Count -eq 0) { $invState.Rate.Remove($k) } }
        }
    }

    # Empfangene Einladung (direkt als PEINV1 oder als Broadcast-Kopie PEINVB1) anzeigen.
    # Bestätigt wird erst, wenn sie wirklich angezeigt wurde - so stimmt beim Absender die
    # Meldung "ist angekommen". Fehler beim Anzeigen landen im Log (bisher verschluckte die
    # Empfangsschleife sie still, und die Einladung war einfach weg).
    function Receive-DashboardInvite([string]$Wire, [string]$SrcIp) {
        if (Test-PelIpBanned $SrcIp) { return }
        $inv = ConvertFrom-PelInviteWire -Text $Wire -SrcIp $SrcIp
        if (-not $inv) { return }
        $sendAck = {
            try {
                $ackB = [System.Text.Encoding]::UTF8.GetBytes((New-PelInviteAckWire $inv.Id))
                [void]$statTx.Send($ackB, $ackB.Length, $SrcIp, [int]$script:PelStatusPort)
                [void]$statTx.Send($ackB, $ackB.Length, $statBcEp)
            } catch { }
        }
        # Wiederholung oder zweiter Weg (direkt + Broadcast): nur erneut bestätigen
        if ($invState.Seen.ContainsKey($inv.Id)) { & $sendAck; return }
        $nowInv = Get-PelNowMs
        $recent = @(@($invState.Rate[$SrcIp]) | Where-Object { $_ -and ($nowInv - $_) -lt 60000 })
        if ($recent.Count -ge 6) { return }
        $invState.Rate[$SrcIp] = @($recent) + @($nowInv)
        $invState.Seen[$inv.Id] = $nowInv
        $shown = $false
        try { Show-PelInviteNotification $inv; $shown = $true }
        catch { Write-PelLog "Einladungsfenster konnte nicht angezeigt werden: $($_.Exception.Message)" 'ERROR' }
        # Zusätzlich (und als Ersatz, falls das Fenster scheitert) eine Sprechblase am
        # Symbol im Infobereich - die sieht man auch, wenn das Control Center versteckt ist.
        try {
            if ($trayIcon -and $trayIcon.Visible) {
                $bt = switch ($inv.Kind) {
                    'chat' { [PelI18n]::Tr("{0} lädt dich in den Chat ein.") -f $inv.FromName }
                    'voice' { [PelI18n]::Tr("{0} lädt dich in den Sprachchat ein.") -f $inv.FromName }
                    default { [PelI18n]::Tr("{0} lädt dich zum Spielen ein: {1}") -f $inv.FromName, $(if ($inv.Game) { $inv.Game } else { [PelI18n]::Tr('ein Spiel') }) }
                }
                $trayIcon.ShowBalloonTip(8000, 'Project Earth LAN', $bt, [System.Windows.Forms.ToolTipIcon]::Info)
                $shown = $true
            }
        } catch { }
        if ($shown) {
            $lblUpdated.Text = [PelI18n]::Tr("Einladung von {0} ({1})") -f $inv.FromName, (Get-Date -Format 'HH:mm')
            & $sendAck
        } else {
            $invState.Seen.Remove($inv.Id)
        }
    }

    # ---- Spielebibliothek-Abgleich --------------------------------------------------------
    function Send-DashboardLibList {
        try {
            foreach ($wire in (New-PelLibWires $script:PelMyName $dashState.OwnIp)) { Send-DashboardUdp $wire }
        } catch { Write-PelLog "Bibliotheks-Abgleich: Senden fehlgeschlagen: $($_.Exception.Message)" 'WARN' }
    }

    # Eine empfangene PELIB1-Zeile: Teile sammeln, bei vollständiger Liste übernehmen.
    function Receive-DashboardLibPacket([string]$Text, [string]$SrcIp) {
        if (Test-PelIpBanned $SrcIp) { return }
        $now = Get-PelNowMs
        $recent = @(@($libSync.Rate[$SrcIp]) | Where-Object { $_ -and ($now - $_) -lt 10000 })
        if ($recent.Count -ge 60) { return }
        $libSync.Rate[$SrcIp] = @($recent) + @($now)
        $p = ConvertFrom-PelLibWire $Text
        if (-not $p) { return }
        $ipKey = if ($p.Ip) { $p.Ip } else { $SrcIp }
        if ($script:PelOwnIps.ContainsKey($ipKey)) { return }
        $key = ("{0}|{1}" -f $p.Name, $ipKey).ToLowerInvariant()
        $cur = $libSync.Peers[$key]
        if ($cur -and $cur.Seq -eq $p.Seq) {
            # Liste unverändert - nur "zuletzt gesehen" auffrischen
            $cur.Seen = $now
            $libSync.Dirty = $true
            return
        }
        $pk = "$key|$($p.Seq)"
        $part = $libSync.Partial[$pk]
        if (-not $part) {
            if ($libSync.Partial.Count -ge 64) { return }
            $part = @{ Total = $p.Total; Parts = @{}; Ms = $now }
            $libSync.Partial[$pk] = $part
        }
        if ($part.Total -ne $p.Total) { return }
        $part.Parts[$p.Part] = $p.Items
        if ($part.Parts.Count -lt $part.Total) { return }
        $games = New-Object System.Collections.Generic.List[object]
        for ($i = 1; $i -le $part.Total; $i++) {
            # ohne @(): @(List[object]) wirft unter PowerShell "Argument types do not match"
            $pl = $part.Parts[$i]
            if ($null -eq $pl) { continue }
            foreach ($g in $pl) { if ($g -and $games.Count -lt 400) { $games.Add($g) } }
        }
        $libSync.Partial.Remove($pk)
        if (-not $cur -and $libSync.Peers.Count -ge 256) {
            $oldest = @($libSync.Peers.Keys | Sort-Object { $libSync.Peers[$_].Seen }) | Select-Object -First 1
            if ($oldest) { $libSync.Peers.Remove($oldest) }
        }
        $libSync.Peers[$key] = [pscustomobject]@{ Name = $p.Name; Ip = $ipKey; Seq = $p.Seq; Seen = $now; Games = $games.ToArray() }
        $libSync.Dirty = $true
        $libSync.NetExes = Get-PelNetExeMap $libSync.Peers
        Write-PelLog "Bibliotheks-Abgleich: Liste von $($p.Name) ($ipKey) übernommen, $($games.Count) Spiel(e)."
    }

    # Einmal pro Timer-Tick: Anfragen aus Option 3, eigene Änderungen, Antworten, Speichern.
    function Update-DashboardLibSync {
        $now = Get-PelNowMs
        if (($script:PelStatusHbTick % 2) -eq 0 -and [System.IO.File]::Exists($script:PelLibSyncReqFile)) {
            try { [System.IO.File]::Delete($script:PelLibSyncReqFile) } catch { }
            $libSync.NextSendMs = $now
            $libSync.ReqPending = $true
            $lblUpdated.Text = [PelI18n]::Tr("Spielebibliothek wird mit den anderen Managern abgeglichen ...")
        }
        if (($script:PelStatusHbTick % 4) -eq 1) {
            $st = [int64]0
            try { if ([System.IO.File]::Exists($script:PelGameLibPath)) { $st = [System.IO.File]::GetLastWriteTimeUtc($script:PelGameLibPath).Ticks } } catch { }
            if ($st -ne $libSync.MyStamp) {
                # Eigene Bibliothek geändert (Scan, Option 3, automatisch aufgenommen) -> gleich senden
                if ($libSync.MyStamp -ne -1) { $libSync.NextSendMs = [Math]::Min($libSync.NextSendMs, $now + 500) }
                $libSync.MyStamp = $st
            }
        }
        if ($libSync.ReplyAtMs -gt 0 -and $now -ge $libSync.ReplyAtMs) {
            $libSync.ReplyAtMs = 0
            $libSync.NextSendMs = $now
        }
        if ($statTx -and $now -ge $libSync.NextSendMs) {
            $libSync.NextSendMs = $now + 120000
            Send-DashboardLibList
            if ($libSync.ReqPending) {
                $libSync.ReqPending = $false
                Send-DashboardUdp (New-PelLibRequestWire)
            }
        }
        if ($libSync.Dirty -and ($now - $libSync.LastSaveMs) -gt 3000) {
            $libSync.Dirty = $false
            $libSync.LastSaveMs = $now
            [void](Save-PelNetLibrary $libSync.Peers)
        }
        if (($script:PelStatusHbTick % 60) -eq 11) {
            foreach ($k in @($libSync.Partial.Keys)) { if (($now - $libSync.Partial[$k].Ms) -gt 30000) { $libSync.Partial.Remove($k) } }
            foreach ($k in @($libSync.Rate.Keys)) { if (@(@($libSync.Rate[$k]) | Where-Object { $_ -and ($now - $_) -lt 10000 }).Count -eq 0) { $libSync.Rate.Remove($k) } }
        }
    }

