    $miMsg = New-Object System.Windows.Forms.ToolStripMenuItem('Nachricht senden ...')
    $miChat = New-Object System.Windows.Forms.ToolStripMenuItem('In den Chat einladen')
    $miVoice = New-Object System.Windows.Forms.ToolStripMenuItem('In den Sprachchat einladen')
    $miGame = New-Object System.Windows.Forms.ToolStripMenuItem('Zum Spielen einladen ...')
    $miCopy = New-Object System.Windows.Forms.ToolStripMenuItem('IP-Adresse kopieren')
