    # ---- Postfach-Dienst (Option 7) --------------------------------------------------
    # Läuft hier im Control Center, damit Nachrichten auch ankommen, während Option 7
    # geschlossen ist. Ist Option 7 gerade der Host (Control Center war zu), übernimmt
    # das Control Center automatisch, sobald Option 7 geschlossen wird.
    [void](Start-PelMailService -NoStatusListener)
    $mailState = @{ Unread = -1 }
    function Update-DashboardMail {
        try {
            $unread = [EarthMailStore]::CountUnread()
            $waiting = [EarthMailStore]::CountFiles([EarthMailStore]::Outbox)
            $txt = if ($unread -gt 0) { "Postfach: $unread ungelesene Nachricht(en) - klicken zum Öffnen" } else { "Postfach: keine neuen Nachrichten" }
            if ($waiting -gt 0) { $txt += "  |  $waiting im Ausgang" }
            if (-not $script:PelMailNode) { $txt += "  (Dienst in Option 7)" }
            $lblMail.Text = $txt
            $lblMail.ForeColor = if ($unread -gt 0) { [System.Drawing.Color]::Gold } else { [System.Drawing.Color]::LightGray }
            $mailState.Unread = $unread
        } catch { }
    }

    # ---- GitHub-Versionsprüfung im Hintergrund (siehe $script:PelGitHubCheckScript) -------
    $ghCheck = @{ Rs = $null; PS = $null; Handle = $null; NextMs = [int64]0 }
    function Start-DashboardGitHubCheck {
        if ($ghCheck.PS) { return }
        try {
            $ghCheck.Rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
            $ghCheck.Rs.Open()
            $ps = [PowerShell]::Create()
            $ps.Runspace = $ghCheck.Rs
            [void]$ps.AddScript($script:PelGitHubCheckScript.ToString())
            [void]$ps.AddArgument($script:PelGitHubApiLatest)
            [void]$ps.AddArgument($script:PelGitHubApiTags)
            [void]$ps.AddArgument($script:PelGitHubApiContents)
            [void]$ps.AddArgument($script:PelGitHubRawVersion)
            $ghCheck.PS = $ps
            $ghCheck.Handle = $ps.BeginInvoke()
        } catch {
            $ghCheck.PS = $null; $ghCheck.Handle = $null
            if ($ghCheck.Rs) { try { $ghCheck.Rs.Dispose() } catch { } ; $ghCheck.Rs = $null }
        }
    }
    function Receive-DashboardGitHubCheck {
        if (-not $ghCheck.PS -or -not $ghCheck.Handle -or -not $ghCheck.Handle.IsCompleted) { return }
        $res = $null
        try {
            $out = @($ghCheck.PS.EndInvoke($ghCheck.Handle))
            if ($out.Count -gt 0) { $res = $out[$out.Count - 1] }
        } catch { }
        finally {
            try { $ghCheck.PS.Dispose() } catch { }
            try { $ghCheck.Rs.Close(); $ghCheck.Rs.Dispose() } catch { }
            $ghCheck.PS = $null; $ghCheck.Handle = $null; $ghCheck.Rs = $null
        }
        $when = Get-Date -Format 'HH:mm'
        if ($res -and $res.Ok) {
            if ($res.Latest -and ([string]$res.Latest -gt [string]$script:PelVersion)) {
                $script:PelGitHubLatest = [string]$res.Latest
                $lblVersion.Text = "Version: $($script:PelVersion) (veraltet)"
                $lblVersion.ForeColor = [System.Drawing.Color]::Gold
                $btnGitHub.Text = "Neue Version $($res.Latest) auf GitHub"
                $btnGitHub.Visible = $true
                [PelI18n]::Tip($dashTip, $btnGitHub, "Gefunden: $($res.Source)`nÖffnet $($script:PelGitHubUrl) im Browser - dort herunterladen und die alte Datei ersetzen.")
                [PelI18n]::Tip($dashTip, $lblVersion, "Diese Version: $($script:PelVersion) - auf GitHub: $($res.Latest) (geprüft um $when)")
                if (-not $ghCheck.Logged) { Write-PelLog "Neuere Version auf GitHub: $($res.Latest) ($($res.Source))"; $ghCheck.Logged = $true }
            } else {
                $btnGitHub.Visible = $false
                $lblVersion.Text = "Version: $($script:PelVersion) (aktuell)"
                $lblVersion.ForeColor = [System.Drawing.Color]::LightGray
                [PelI18n]::Tip($dashTip, $lblVersion, "Diese Version: $($script:PelVersion) - keine neuere Version auf GitHub (geprüft um $when)")
            }
        } else {
            [PelI18n]::Tip($dashTip, $lblVersion, "Diese Version: $($script:PelVersion) - GitHub war um $when nicht erreichbar, nächster Versuch in 1 Stunde.")
            $ghCheck.NextMs = (Get-PelNowMs) + 3600000
        }
    }
    $ghCheck.NextMs = (Get-PelNowMs) + 4000

    $script:PelStatusHbTick = 0
    $statPoll = New-Object System.Windows.Forms.Timer
    $statPoll.Interval = 500
    $statPoll.Add_Tick({
        # Gesamter Tick abgesichert: ein unerwarteter Fehler darf den Live-Status nicht
        # anhalten (er landet trotzdem im Fehlerprotokoll, siehe Save-PelErrorRecords).
        try {
            $script:PelStatusHbTick++
            Receive-DashboardGameDetect
            if (($script:PelStatusHbTick % 20) -eq 1) { Start-DashboardGameDetect }

            # Zweiter Start (z. B. Doppelklick, während der Manager per Autostart minimiert
            # läuft): dieses Fenster wieder nach vorne holen statt ein zweites zu öffnen.
            if ($script:PelShowEvent) {
                try {
                    # auch aus dem Infobereich zurückholen (Show-PelCcWindow, siehe unten)
                    if ($script:PelShowEvent.WaitOne(0)) { Show-PelCcWindow }
                } catch { }
            }

            # GitHub-Prüfung: kurz nach dem Start, danach alle 6 Stunden
            Receive-DashboardGitHubCheck
            if (-not $ghCheck.PS -and (Get-PelNowMs) -ge $ghCheck.NextMs) {
                $ghCheck.NextMs = (Get-PelNowMs) + 21600000
                Start-DashboardGitHubCheck
            }

            # Postfach: neue Nachrichten melden, Dienst ggf. übernehmen, Anzeige aktualisieren
            if (-not $script:PelMailNode -and ($script:PelStatusHbTick % 20) -eq 5) { [void](Start-PelMailService -NoStatusListener) }
            if ($script:PelMailNode) {
                $ev = $null
                $newMsgs = New-Object System.Collections.Generic.List[object]
                while ($script:PelMailNode.Events.TryDequeue([ref]$ev)) {
                    $evs = [string]$ev
                    if ($evs.StartsWith('NEW|')) {
                        $nm = [EarthMailStore]::Load((Join-Path ([EarthMailStore]::Inbox) ($evs.Substring(4) + '.msg')))
                        if ($nm) { $newMsgs.Add($nm) }
                    } elseif ($evs.StartsWith('SENT|')) {
                        $sm = [EarthMailStore]::Load((Join-Path ([EarthMailStore]::Sent) ($evs.Substring(5) + '.msg')))
                        if ($sm) {
                            $who = if ($sm.ToName) { $sm.ToName } else { $sm.ToIp }
                            $lblUpdated.Text = "Nachricht an $who zugestellt ($(Get-Date -Format 'HH:mm'))"
                        }
                    }
                }
                if ($newMsgs.Count -gt 0) {
                    Show-PelMailNotification -Messages $newMsgs -ParentForm $mainForm
                    Update-DashboardMail
                }
                if (($script:PelStatusHbTick % 120) -eq 0) { $script:PelMailNode.MyName = $script:PelMyName }
            }
            if (($script:PelStatusHbTick % 10) -eq 3) { Update-DashboardMail }

            # Live-Status senden: alle 8 s; bei vielen Teilnehmern seltener, weil jede Meldung an
            # alle geht (bis 128: 8 s, bis 256: 20 s, darüber: 30 s). Gezählt werden Mitspieler im
            # P2P-Netz UND andere Manager im LAN (LAN-Party ohne Internet, ganz ohne P2P).
            $hbEvery = 16
            if (($script:PelStatusHbTick % 20) -eq 0) {
                $pc = 0
                if ($script:PelP2pEngine) { try { $pc = [int]$script:PelP2pEngine.PeerCount } catch { } }
                if ($script:PelOtherManagers -and $script:PelOtherManagers.Count -gt $pc) { $pc = $script:PelOtherManagers.Count }
                $script:PelStatusEvery = if ($pc -gt 256) { 60 } elseif ($pc -gt 128) { 40 } else { 16 }
            }
            if ($script:PelStatusEvery) { $hbEvery = [int]$script:PelStatusEvery }
            if ($statTx -and ($script:PelStatusHbTick % $hbEvery -eq 0)) {
                try {
                    $ztNow = Get-DashboardConnectionStatus
                    $ownIp = if ($ztNow.Connected) { $ztNow.Ip } else { '' }
                    $dashState.OwnIp = $ownIp
                    if ($ownIp) { $script:PelOwnIps[$ownIp] = $true }
                    $gTitle = ''; $gExe = ''; $gJp = 0; $gSrv = ''
                    $mg = $script:PelMyGame
                    if ($mg) {
                        $gTitle = Limit-PelText (([string]$mg.Title) -replace '\|', '/') 48
                        $gExe = ([string]$mg.Exe) -replace '\|', '/'
                        $gJp = [int]$mg.JoinPort
                        $gSrv = ([string]$mg.Server) -replace '\|', '/'
                    }
                    $core = "PESTAT1|$($script:PelMyName)|$ownIp|$([int](Test-PelP2pRunning))|$($pingState.Online)|$($pingState.Total)|$($script:PelVersion)|$gTitle|$gExe|$gJp|$gSrv"
                    Send-DashboardUdp "$core|$(Get-PelHmacBase64 -Text $core)"
                } catch { }
            }

            # Spielebibliothek mit den anderen Managern abgleichen (eigener try: ein Fehler
            # hier darf den Live-Status nicht anhalten)
            try { Update-DashboardLibSync } catch { Write-PelLog "Bibliotheks-Abgleich: $($_.Exception.Message)" 'WARN' }

            # Fällige Spieleabende weitergeben (max. 2 pro Sekunde)
            if ($statTx -and ($script:PelStatusHbTick % 2 -eq 0)) {
                foreach ($ev in @(Get-PelDueEvents 2)) { Send-DashboardUdp (ConvertTo-PelEventWire $ev) }
            }

            if ($statRx) {
                try {
                    while ($statRx.Available -gt 0) {
                        $remoteEp = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
                        $bytes = $statRx.Receive([ref]$remoteEp)
                        $txt = [System.Text.Encoding]::UTF8.GetString($bytes)
                        $srcIp = $remoteEp.Address.ToString()
                        $isSelf = $script:PelOwnIps.ContainsKey($srcIp)
                        if ($txt.StartsWith('PESTAT1|')) {
                            if ($isSelf) { continue }
                            $f = $txt -split '\|'
                            if ($f.Count -lt 8) { continue }
                            $recvSig = $f[$f.Count - 1]
                            $recvCore = ($f[0..($f.Count - 2)] -join '|')
                            if (-not (Test-PelHmac -Text $recvCore -Signature $recvSig)) { continue }
                            # Postfach: Empfänger ist (wieder) online -> wartende Nachrichten sofort zustellen
                            if ($script:PelMailNode) { try { $script:PelMailNode.NotePeer($srcIp, [string]$f[1]) } catch { } }
                            $on = 0; $tot = 0; $jp = 0
                            [void][int]::TryParse($f[4], [ref]$on)
                            [void][int]::TryParse($f[5], [ref]$tot)
                            $mgr = [pscustomobject]@{
                                IsSelf = $false; Name = $f[1]; Ip = $f[2]; SrcIp = $srcIp; Zt = ($f[3] -eq '1'); Online = $on; Total = $tot; Version = $f[6]
                                Game = ''; GameExe = ''; JoinPort = 0; Server = ''
                                Seen = Get-PelNowMs
                            }
                            if ($f.Count -ge 12) {
                                $mgr.Game = $f[7]
                                $mgr.GameExe = $f[8]
                                if ([int]::TryParse($f[9], [ref]$jp)) { $mgr.JoinPort = $jp }
                                $mgr.Server = $f[10]
                            }
                            # Ein PC mit mehreren Netzwerkwegen (z. B. P2P-Adapter + WLAN) sendet seinen
                            # Status über jeden Weg - sonst stünde er doppelt in der Liste. Gleicher Name
                            # + gleiche gemeldete IP = derselbe Manager; bevorzugt wird der Eintrag, der
                            # direkt von seiner gemeldeten IP kommt.
                            # Schneller Weg: bekannter Absender mit gleichem Namen/IP -> nur auffrischen
                            # (bei großen Lobbys kommen Dutzende Meldungen pro Sekunde)
                            $cur = $script:PelOtherManagers[$srcIp]
                            if ($cur -and $cur.Name -eq $mgr.Name -and $cur.Ip -eq $mgr.Ip) { $script:PelOtherManagers[$srcIp] = $mgr; continue }
                            $dupKey = $null
                            foreach ($ok in @($script:PelOtherManagers.Keys)) {
                                $om = $script:PelOtherManagers[$ok]
                                if ($ok -ne $srcIp -and $om.Name -eq $mgr.Name -and $om.Ip -and $om.Ip -eq $mgr.Ip) { $dupKey = $ok; break }
                            }
                            if ($dupKey) {
                                if ($script:PelOtherManagers[$dupKey].SrcIp -eq $mgr.Ip -and $srcIp -ne $mgr.Ip) {
                                    # vorhandenen (direkten) Eintrag nur auffrischen
                                    $mgr.SrcIp = $script:PelOtherManagers[$dupKey].SrcIp
                                    $script:PelOtherManagers[$dupKey] = $mgr
                                    continue
                                }
                                $script:PelOtherManagers.Remove($dupKey)
                            }
                            $script:PelOtherManagers[$srcIp] = $mgr
                        } elseif ($txt.StartsWith('PEINV1|')) {
                            # Einladung: prüfen, einmal anzeigen, bestätigen (auch Wiederholungen,
                            # falls die erste Bestätigung verloren ging) - siehe Receive-DashboardInvite.
                            if ($isSelf) { continue }
                            Receive-DashboardInvite $txt $srcIp
                        } elseif ($txt.StartsWith('PEINVB1|')) {
                            # Broadcast-Kopie einer Einladung: nur anzeigen, wenn sie an diesen PC geht.
                            if ($isSelf -or $txt.Length -gt 1400) { continue }
                            $bp = $txt.Split([char[]]'|', 3)
                            if ($bp.Count -ne 3) { continue }
                            $forMe = $false
                            foreach ($tip in ($bp[1] -split ',')) { if ($tip -and $script:PelOwnIps.ContainsKey($tip.Trim())) { $forMe = $true; break } }
                            if ($forMe) { Receive-DashboardInvite $bp[2] $srcIp }
                        } elseif ($txt.StartsWith('PEORD1|')) {
                            # Bestellung aus dem Intranet eines Veranstalters: dieser PC steht dort als
                            # Orga-PC in der Speisekarte (Zeile "Orga:"). Doppelte (jede Meldung kommt
                            # zweimal) und zu viele Meldungen pro Absender werden ignoriert.
                            if ($isSelf -or (Test-PelIpBanned $srcIp)) { continue }
                            $ord = ConvertFrom-PelOrderWire $txt
                            if (-not $ord -or $invState.Seen.ContainsKey("o:$($ord.Id)")) { continue }
                            $nowOrd = Get-PelNowMs
                            $invState.Seen["o:$($ord.Id)"] = $nowOrd
                            $rk = "o:$srcIp"
                            $recentO = @(@($invState.Rate[$rk]) | Where-Object { $_ -and ($nowOrd - $_) -lt 60000 })
                            if ($recentO.Count -ge 40) { continue }
                            $invState.Rate[$rk] = @($recentO) + @($nowOrd)
                            try {
                                Show-PelOrderNotification -Heading $ord.Event -Line "$($ord.Text)  [$srcIp]" -OpenAction { Start-OptionWindow '11' { Invoke-PelIntranet } } -OpenText ([PelI18n]::Tr('Intranet öffnen'))
                            } catch { Write-PelLog "Bestellmeldung konnte nicht angezeigt werden: $($_.Exception.Message)" 'WARN' }
                        } elseif ($txt.StartsWith('PELIB1|')) {
                            if ($isSelf) { continue }
                            Receive-DashboardLibPacket $txt $srcIp
                        } elseif ($txt.StartsWith('PELIBREQ1|')) {
                            # Jemand gleicht ab: eigene Liste leicht zeitversetzt schicken, damit
                            # nicht alle Manager im selben Moment antworten.
                            if ($isSelf -or -not (Test-PelLibRequestWire $txt)) { continue }
                            $nowReq = Get-PelNowMs
                            if (($nowReq - $libSync.LastReqMs) -gt 8000) {
                                $libSync.LastReqMs = $nowReq
                                $libSync.ReplyAtMs = $nowReq + (Get-Random -Minimum 200 -Maximum 2500)
                            }
                        } elseif ($txt.StartsWith('PEINVACK1|')) {
                            $ackId = ConvertFrom-PelInviteAckWire $txt
                            if ($ackId -and $invState.Pending.ContainsKey($ackId)) {
                                $pInv = $invState.Pending[$ackId]
                                $invState.Pending.Remove($ackId)
                                $lblUpdated.Text = [PelI18n]::Tr("Einladung an {0} ist angekommen ({1})") -f $pInv.Name, (Get-Date -Format 'HH:mm')
                            }
                        } elseif ($txt.StartsWith('PEEVT1|')) {
                            $inc = ConvertFrom-PelEventWire $txt
                            if ($inc) {
                                Register-PelEventHeard $inc.Id
                                [void](Merge-PelEvent $inc)
                            }
                        } elseif ($txt.StartsWith('PEEVTREQ1|')) {
                            if ($isSelf) { continue }
                            $rf = $txt -split '\|'
                            if ($rf.Count -eq 3 -and (Test-PelHmac -Text "$($rf[0])|$($rf[1])" -Signature $rf[2])) {
                                $nowMs = Get-PelNowMs
                                if (($nowMs - $dashState.LastReqMs) -gt 10000) {
                                    $dashState.LastReqMs = $nowMs
                                    Request-PelEventResend
                                }
                            }
                        }
                    }
                } catch { }
            }
            if (($script:PelStatusHbTick % 40) -eq 0) {
                $nowTick = Get-PelNowMs
                foreach ($k in @($script:PelOtherManagers.Keys)) {
                    $expireMs = [Math]::Max(25000, 1750 * [int]$(if ($script:PelStatusEvery) { $script:PelStatusEvery } else { 16 }))
                    if (($nowTick - $script:PelOtherManagers[$k].Seen) -gt $expireMs) { $script:PelOtherManagers.Remove($k) }
                }
            }
            if (($script:PelStatusHbTick % 20) -eq 0) { $script:PelOwnIps = Get-PelLocalIpSet }
            if (($script:PelStatusHbTick % 120) -eq 0) {
                $script:PelMyName = Get-PelDisplayName
                Remove-PelOldEvents
            }
            # Ankündigungen (neu in den nächsten 3 Tagen / Erinnerung 15 Min. vorher / Absage)
            if (($script:PelStatusHbTick % 10) -eq 0) {
                $nextText = Get-PelNextEventText
                $lblNextEvent.Text = $nextText
                if ($nextText -like '*keiner geplant') { $lblNextEvent.ForeColor = [System.Drawing.Color]::LightGray } else { $lblNextEvent.ForeColor = [System.Drawing.Color]::LightGreen }
                $ann = @(Get-PelPendingAnnouncements)
                if ($ann.Count -gt 0) { Show-PelEventAnnouncement -Items $ann -ParentForm $mainForm }
            }
            $n = $script:PelOtherManagers.Count
            if ($n -eq 0) {
                $lblOtherMgrs.Text = "Andere Manager im Netz: keine gefunden"
                $lblOtherMgrs.ForeColor = [System.Drawing.Color]::LightGray
            } else {
                $names = ((@($script:PelOtherManagers.Values) | Select-Object -First 3 | ForEach-Object { "$($_.Name)$(if($_.Zt){' (P2P)'}else{''})" }) -join ', ')
                $lblOtherMgrs.Text = "Andere Manager im Netz: $n  -  $names"
                $lblOtherMgrs.ForeColor = [System.Drawing.Color]::LightGreen
            }
            Update-DashboardPlaying
            Update-DashboardInvites
        } catch { }
    })
    $statPoll.Start()

    $mainForm.Add_FormClosing({
        $statusTimer.Stop(); $pingPoll.Stop(); $statPoll.Stop(); $p2pTimer.Stop()
        Stop-PelP2p
        Stop-PelHostServer
        Stop-PelFileServer
        if ($script:PelHostForm -and -not $script:PelHostForm.IsDisposed) { try { $script:PelHostForm.Close() } catch { } }
        if ($script:PelFsUi -and -not $script:PelFsUi.Form.IsDisposed) { try { $script:PelFsUi.Form.Close() } catch { } }
        Stop-PelMailService
        if ($ghCheck.PS) { try { $ghCheck.PS.Stop(); $ghCheck.PS.Dispose() } catch { } }
        if ($ghCheck.Rs) { try { $ghCheck.Rs.Close(); $ghCheck.Rs.Dispose() } catch { } }
        if ($script:PelMailNoteForm -and -not $script:PelMailNoteForm.IsDisposed) { try { $script:PelMailNoteForm.Close() } catch { } }
        if ($statRx) { try { $statRx.Close() } catch { } }
        if ($statTx) { try { $statTx.Close() } catch { } }
        if ($gameDetect.PS) { try { $gameDetect.PS.Stop(); $gameDetect.PS.Dispose() } catch { } }
        if ($gameDetect.Rs) { try { $gameDetect.Rs.Close(); $gameDetect.Rs.Dispose() } catch { } }
        if ($script:PelAnnounceForm -and -not $script:PelAnnounceForm.IsDisposed) { try { $script:PelAnnounceForm.Close() } catch { } }
    })

    Update-DashboardStatus
    Start-DashboardFriendPing
    Update-DashboardMail

    # Per Autostart gestartet: minimiert in die Taskleiste statt mitten auf den Bildschirm.
    if ($script:PelAutostartMode) { $mainForm.WindowState = [System.Windows.Forms.FormWindowState]::Minimized }

    # ------------------------------------------------------------------------------
    # SCROLLBEREICH + SEITENLEISTEN-BUTTONS ZUM HOCH-/RUNTERSCROLLEN
    # ------------------------------------------------------------------------------
    # Das Hauptfenster hat mehr Inhalt (u. a. "Spieleabend-Planer" und "Fehlerlog
    # exportieren" unten in der Live-Status-Box), als auf kleine Bildschirme passt.
    # Der gesamte bisherige Inhalt wandert deshalb in ein eigenes scrollbares Panel;
    # zwei feste Pfeil-Buttons oben rechts bleiben dabei IMMER sichtbar (sie liegen
    # außerhalb des Scrollbereichs) und scrollen gezielt hoch/runter - unabhängig
    # davon, wie das Fenster gerade groß oder klein gezogen ist. Das Mausrad
    # funktioniert im Scrollbereich zusätzlich ganz normal.
    $mainScroll = New-Object System.Windows.Forms.Panel
    $mainScroll.Location = New-Object System.Drawing.Point(0, 34)
    $mainScroll.Size = New-Object System.Drawing.Size($mainForm.ClientSize.Width, [Math]::Max(1, $mainForm.ClientSize.Height - 34))
    $mainScroll.Anchor = 'Top, Left, Right, Bottom'
    $mainScroll.AutoScroll = $true
    $mainScroll.BackColor = $mainForm.BackColor
    foreach ($c in @($mainForm.Controls)) {
        $mainForm.Controls.Remove($c)
        $mainScroll.Controls.Add($c)
    }
    $mainForm.Controls.Add($mainScroll)

    $scrollStep = 130
    function New-PelScrollButton([string]$Glyph, [int]$XFromRight) {
        $b = New-Object System.Windows.Forms.Button
        $b.Text = $Glyph
        $b.Size = New-Object System.Drawing.Size(30, 26)
        $b.Location = New-Object System.Drawing.Point(($mainForm.ClientSize.Width - $XFromRight), 4)
        $b.Anchor = 'Top, Right'
        $b.FlatStyle = 'Flat'
        $b.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
        $b.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
        $b.ForeColor = [System.Drawing.Color]::White
        $b.TabStop = $false
        $mainForm.Controls.Add($b)
        $b.BringToFront()
        return $b
    }
    # Sprache umschalten (Deutsch/English) - Neustart des Managers nötig
    $btnLang = New-Object System.Windows.Forms.Button
    $btnLang.Text = if ($script:PelLang -eq 'en') { 'Language: English' } else { 'Sprache: Deutsch' }
    $btnLang.Size = New-Object System.Drawing.Size(150, 26)
    $btnLang.Location = New-Object System.Drawing.Point(8, 4)
    $btnLang.Anchor = 'Top, Left'
    $btnLang.FlatStyle = 'Flat'
    $btnLang.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(70, 70, 70)
    $btnLang.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 45)
    $btnLang.ForeColor = [System.Drawing.Color]::White
    $btnLang.TabStop = $false
    $mainForm.Controls.Add($btnLang)
    $btnLang.BringToFront()
    $btnAutostart.Location = New-Object System.Drawing.Point(164, 4)
    $btnAutostart.Anchor = 'Top, Left'
    $mainForm.Controls.Add($btnAutostart)
    $btnAutostart.BringToFront()
    $btnLang.Add_Click({
        $newLang = if ($script:PelLang -eq 'en') { 'de' } else { 'en' }
        $q = if ($newLang -eq 'en') { "Switch the language to English?`n`nThe manager restarts once. Lobby and hosting reconnect automatically if they are set to start automatically. Option windows that are open keep their language until you reopen them." }
             else { "Sprache auf Deutsch umstellen?`n`nDer Manager startet dafür einmal neu. Lobby und Hosten verbinden sich automatisch wieder, wenn sie auf automatisch stehen. Offene Options-Fenster behalten ihre Sprache, bis du sie neu öffnest." }
        $ans = [System.Windows.Forms.MessageBox]::Show($mainForm, $q, 'Sprache / Language', [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
        if ($ans -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        Set-PelLanguage $newLang
        $script:PelRestartRequested = $true
        $mainForm.Close()
    })
    $btnScrollUp = New-PelScrollButton ([string][char]0x25B2) 70
    $btnScrollDown = New-PelScrollButton ([string][char]0x25BC) 38
    $btnScrollUp.Add_Click({
        $cur = -$mainScroll.AutoScrollPosition.Y
        $mainScroll.AutoScrollPosition = New-Object System.Drawing.Point(0, [Math]::Max(0, $cur - $scrollStep))
    }.GetNewClosure())
    $btnScrollDown.Add_Click({
        $cur = -$mainScroll.AutoScrollPosition.Y
        $mainScroll.AutoScrollPosition = New-Object System.Drawing.Point(0, ($cur + $scrollStep))
    }.GetNewClosure())
    $ttScroll = New-Object System.Windows.Forms.ToolTip
    [PelI18n]::Tip($ttScroll, $btnScrollUp, 'Nach oben scrollen')
    [PelI18n]::Tip($ttScroll, $btnScrollDown, 'Nach unten scrollen (z. B. zu "Spieleabend-Planer" / "Fehlerlog exportieren")')

    # ---- Infobereich: EIN Symbol für den ganzen Manager ---------------------------------
    # Klick (links oder rechts) öffnet das Menü. Minimieren versteckt das Control Center im
    # Infobereich (abschaltbar im Menü). Per Autostart startet es direkt dort.
    Initialize-PelWinType
    $tray = @{ Hidden = $false; LastCount = 0; Hinted = $false }
    $trayIcon = New-Object System.Windows.Forms.NotifyIcon
    try { $trayIcon.Icon = [System.Drawing.Icon]::ExtractAssociatedIcon([string]$script:SelfPath) } catch { }
    if (-not $trayIcon.Icon) { $trayIcon.Icon = [System.Drawing.SystemIcons]::Application }
    $trayIcon.Text = 'Project Earth LAN Manager'
    $trayMenu = New-PelContextMenu
    $trayMenu.ShowImageMargin = $true
    $trayIcon.ContextMenuStrip = $trayMenu

    function Show-PelCcWindow {
        try { [void][PelWin]::ShowWindow($mainForm.Handle, [PelWin]::SW_RESTORE) } catch { }
        if ($mainForm.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { $mainForm.WindowState = [System.Windows.Forms.FormWindowState]::Normal }
        $tray.Hidden = $false
        try { [void][PelWin]::SetForegroundWindow($mainForm.Handle) } catch { }
        $mainForm.Activate()
        $mainForm.TopMost = $true; $mainForm.TopMost = $false
    }
    function Hide-PelCcWindow {
        try { [void][PelWin]::ShowWindow($mainForm.Handle, [PelWin]::SW_HIDE) } catch { return }
        $tray.Hidden = $true
        if (-not $tray.Hinted -and -not $script:PelAutostartMode) {
            $tray.Hinted = $true
            try { $trayIcon.ShowBalloonTip(5000, 'Project Earth LAN Manager', (Get-PelText 'Läuft im Infobereich weiter (Symbol neben der Uhr). Ein Klick darauf zeigt alle Fenster.' 'Keeps running in the notification area (icon next to the clock). Click it to see all windows.'), [System.Windows.Forms.ToolTipIcon]::Info) } catch { }
        }
    }
    function Add-PelTrayItem([string]$Text, [scriptblock]$Action, [bool]$Bold = $false, [bool]$Enabled = $true) {
        $it = New-Object System.Windows.Forms.ToolStripMenuItem($Text)
        if ($Bold) { $it.Font = New-Object System.Drawing.Font($trayMenu.Font, [System.Drawing.FontStyle]::Bold) }
        $it.Enabled = $Enabled
        if ($Action) { $it.Add_Click($Action) }
        [void]$trayMenu.Items.Add($it)
        return $it
    }
    # Das Menü wird bei jedem Öffnen neu aufgebaut - so zeigt es immer den aktuellen Stand.
    function Update-PelTrayMenu {
        $trayMenu.Items.Clear()
        $cc = Get-PelText 'Control Center' 'Control Center'
        if ($tray.Hidden) { $cc += '  -  ' + (Get-PelText 'im Infobereich' 'in the notification area') }
        [void](Add-PelTrayItem $cc { Show-PelCcWindow } $true)
        [void]$trayMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        [void](Add-PelTrayItem (Get-PelText 'Offene Fenster' 'Open windows') $null $false $false)
        $open = @($script:PelTrayOptions | Where-Object { Test-PelOptionRunning $_ })
        $anyHidden = $false
        foreach ($nr in $open) {
            $inTray = Test-PelOptionInTray $nr
            if ($inTray) { $anyHidden = $true }
            $label = "   $nr  ·  $(Get-PelOptionTitle $nr)"
            if ($inTray) { $label += '  -  ' + (Get-PelText 'im Infobereich' 'in the notification area') }
            $it = Add-PelTrayItem $label $null
            $it.Tag = $nr
            $it.Add_Click({ param($sender, $e) [void](Send-PelOptionShow ([string]$sender.Tag)) })
        }
        if ($open.Count -eq 0) { [void](Add-PelTrayItem ('   ' + (Get-PelText '(keine)' '(none)')) $null $false $false) }
        if ($anyHidden -or ($tray.Hidden -and $open.Count -gt 0)) {
            [void](Add-PelTrayItem (Get-PelText 'Alle Fenster anzeigen' 'Show all windows') {
                    Show-PelCcWindow
                    foreach ($n in @($script:PelTrayOptions | Where-Object { Test-PelOptionRunning $_ })) { [void](Send-PelOptionShow $n) }
                })
        }
        [void]$trayMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        $sub = New-Object System.Windows.Forms.ToolStripMenuItem((Get-PelText 'Option öffnen' 'Open option'))
        foreach ($nr in $script:PelTrayOptions) {
            $si = New-Object System.Windows.Forms.ToolStripMenuItem("$nr  ·  $(Get-PelOptionTitle $nr)")
            $si.Tag = $nr
            if ($open -contains $nr) { $si.Checked = $true }
            $si.Add_Click({
                    param($sender, $e)
                    $n = [string]$sender.Tag
                    if (Test-PelOptionRunning $n) { [void](Send-PelOptionShow $n) } else { Start-OptionWindow $n { } }
                })
            [void]$sub.DropDownItems.Add($si)
        }
        [void]$trayMenu.Items.Add($sub)
        [void]$trayMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        $chk = Add-PelTrayItem (Get-PelText 'Beim Minimieren in den Infobereich' 'Minimize to the notification area') { Set-PelTrayMinimize (-not (Get-PelTrayMinimize)) }
        $chk.Checked = (Get-PelTrayMinimize)
        [void](Add-PelTrayItem (Get-PelText 'Beenden' 'Exit') { Show-PelCcWindow; $mainForm.Close() })
    }
    $trayMenu.Add_Opening({ Update-PelTrayMenu })
    Update-PelTrayMenu
    # Auch ein Linksklick öffnet das Menü (Windows zeigt es sonst nur bei Rechtsklick)
    $trayIcon.Add_MouseUp({
        param($sender, $e)
        if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
            try { [System.Windows.Forms.NotifyIcon].GetMethod('ShowContextMenu', [System.Reflection.BindingFlags]'Instance,NonPublic').Invoke($trayIcon, $null) } catch { Show-PelCcWindow }
        }
    })
    $trayIcon.Visible = $true

    # Tooltip mit der Zahl versteckter Fenster; kurzer Hinweis, wenn eins neu dazukommt
    $trayTimer = New-Object System.Windows.Forms.Timer
    $trayTimer.Interval = 1500
    $trayTimer.Add_Tick({
        try {
            $n = @($script:PelTrayOptions | Where-Object { Test-PelOptionInTray $_ }).Count
            if ($tray.Hidden) { $n++ }
            $txt = 'Project Earth LAN Manager'
            if ($n -gt 0) { $txt += "`n" + ((Get-PelText '{0} Fenster im Infobereich' '{0} window(s) in the notification area') -f $n) }
            if ($txt.Length -gt 63) { $txt = $txt.Substring(0, 63) }
            $trayIcon.Text = $txt
            if ($n -gt $tray.LastCount -and -not $tray.Hinted -and -not $script:PelAutostartMode) {
                $tray.Hinted = $true
                $trayIcon.ShowBalloonTip(5000, 'Project Earth LAN Manager', (Get-PelText 'Das Fenster läuft im Infobereich weiter. Ein Klick auf das Symbol zeigt alle Fenster.' 'The window keeps running in the notification area. Click the icon to see all windows.'), [System.Windows.Forms.ToolTipIcon]::Info)
            }
            $tray.LastCount = $n
        } catch { }
    })
    $trayTimer.Start()

    $mainForm.Add_Resize({
        if ($mainForm.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized -and (Get-PelTrayMinimize) -and -not $tray.Hidden) { Hide-PelCcWindow }
    })
    $mainForm.Add_Shown({
        # Per Autostart gestartet: gleich in den Infobereich, ohne Hinweisblase
        if ($script:PelAutostartMode) {
            $mainForm.WindowState = [System.Windows.Forms.FormWindowState]::Minimized
            Hide-PelCcWindow
        }
    })
    $mainForm.Add_FormClosed({
        try { $trayTimer.Stop(); $trayTimer.Dispose() } catch { }
        try { $trayIcon.Visible = $false; $trayIcon.Dispose() } catch { }
    })

    # ---- Willkommen: beim allerersten Start einmal zeigen, danach per Klick auf den Titel ----
    # Über einen kurzen Timer statt direkt in Shown, damit das Fenster erst vollständig
    # steht und andere Start-Aufgaben (z. B. automatisches Beitreten) nicht warten müssen.
    $invokeWelcome = {
        $choice = Show-PelWelcomeDialog -Owner $mainForm
        if ($choice -eq 'host') { Show-PelHostDialog }
        elseif ($choice -eq 'join' -and $btnP2pInvite.Enabled) { $btnP2pInvite.PerformClick() }
    }
    $lblTitle.Cursor = [System.Windows.Forms.Cursors]::Hand
    [PelI18n]::Tip($ttScroll, $lblTitle, 'Worum es bei diesem Projekt geht (Klick)')
    $lblTitle.Add_Click({ & $invokeWelcome })
    if (-not $script:PelAutostartMode -and -not (Test-PelWelcomeSeen)) {
        $welcomeTimer = New-Object System.Windows.Forms.Timer
        $welcomeTimer.Interval = 600
        $welcomeTimer.Add_Tick({
            $welcomeTimer.Stop()
            Set-PelWelcomeSeen
            & $invokeWelcome
        })
        $mainForm.Add_Shown({ $welcomeTimer.Start() })
    }

    [void]$mainForm.ShowDialog()
    if ($script:PelRestartRequested) { Start-PelDelayedRestart }
}

# ------------------------------------------------------------------------------
# SKRIPT START
# ------------------------------------------------------------------------------
if ($Option) {
    # Getrenntes Fenster: nur die gewählte Option ausführen (jede Option nur einmal gleichzeitig)
    $optMutex = New-Object System.Threading.Mutex($false, "Global\ProjectEarthLan_Option_$Option")
    $gotMutex = $false
    try { $gotMutex = $optMutex.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $gotMutex = $true }
    if (-not $gotMutex) {
        [PelI18n]::Show("Option $Option ist bereits in einem anderen Fenster geöffnet.", "Project Earth LAN", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
        exit
    }
    Start-PelErrorLogging "Option$Option"
    # Minimieren in den Infobereich (ein Symbol für alles, siehe "INFOBEREICH")
    try { Enable-PelOptionTray $Option } catch { }
    try {
        switch ($Option) {
            '1'  { Invoke-ToolsModsGames }
            '2'  { Invoke-PelRemoteDesktop }
            '3'  { Invoke-PelGameLibrary }
            '4'  { Invoke-PelTourneyCenter }
            '5'  { Invoke-ServerManagerBrowser }
            '6'  { Invoke-CommCenter }
            '7'  { Invoke-FriendsBansMailbox }
            '8'  { Invoke-KodiSteuerung }
            '11' { Invoke-PelIntranet }
            default { Show-MainDashboard }
        }
    } catch {
        $errText = ($Error | Select-Object -First 6 | Out-String)
        Write-PelLog -Level 'ABSTURZ' -Message ("Option ${Option}: " + ($errText -replace '\s+', ' '))
        [PelI18n]::Show("Option $Option konnte nicht gestartet werden:`n`n$errText", "Project Earth LAN - Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
    } finally {
        Disable-PelOptionTray
        Stop-PelErrorLogging
        try { $optMutex.ReleaseMutex() } catch { }
    }
} else {
    # Nur EIN Control Center pro PC: läuft schon eins (z. B. minimiert per Autostart),
    # wird es nach vorne geholt statt ein zweites zu öffnen (zwei Control Center würden
    # sich Postfach und Live-Status-Ports streitig machen).
    $ccMutex = $null
    $gotCc = $true
    try {
        $ccMutex = New-Object System.Threading.Mutex($false, 'Global\ProjectEarthLan_ControlCenter')
        try { $gotCc = $ccMutex.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $gotCc = $true }
    } catch { $gotCc = $true }
    if (-not $gotCc) {
        try { $showEv = [System.Threading.EventWaitHandle]::OpenExisting('Global\ProjectEarthLan_ControlCenter_Show'); [void]$showEv.Set() } catch { }
        exit
    }
    try { $script:PelShowEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::AutoReset, 'Global\ProjectEarthLan_ControlCenter_Show') } catch { $script:PelShowEvent = $null }
    Start-PelErrorLogging 'ControlCenter'
    try {
        Show-MainDashboard
    } catch {
        $errText = ($Error | Select-Object -First 6 | Out-String)
        Write-PelLog -Level 'ABSTURZ' -Message ("Control Center: " + ($errText -replace '\s+', ' '))
        [PelI18n]::Show("Das Control Center wurde wegen eines Fehlers beendet:`n`n$errText`n`nÜber 'Fehlerlog exportieren' (nach dem Neustart) kannst du die Details weitergeben.", "Project Earth LAN - Fehler", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
    } finally {
        Stop-PelErrorLogging
        try { if ($ccMutex) { $ccMutex.ReleaseMutex() } } catch { }
    }
}